0&=\det(PHP-x)=\det\Big(P(H-P^{-2}x)P\Big)\\
&=\det(P^2) \det(G(x)^{-1})\det \left(1+xG(x)(1-P^{-2}) \right) \\
&=\det(P^2) \det(G(x)^{-1})\det \left(1+xG(x) \mathbf{U} \mathcal{D} \mathbf{U}^* \right) \\
&=\det(P^2) \det(G(x)^{-1}) \det \Big(1+x \mathbf{U}^* G(x) \mathbf{U} \mathcal{D}  \Big) \nonumber \\
& =\det(P^2) \det(G(x)^{-1})\det(\mathcal{D})\det(\mathcal{D}^{-1}+x \mathbf{U}^* G(x) \mathbf{U}),
\end{align*}
where in the penultimate step we used the identity $\det(1+AB)=\det(1+BA)$ for any matrices of conformable dimensions. The claim","release_manifest_digest":"sha256:f7beaf8680eaa84eb81fbbcaf5cb5a2b03ec8287c5920ee2e456d176a7ebc32b","revision_digest":"sha256:645f262324604036e06e1ed74adc2afd34f478ab379d48ed2bf4d0743e838559","source_id":"arxiv:2608.29872","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

