body:
[Proposition prop:local-mass-good-events-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(C<\infty\) and \(c>0\) such that, for all \(n\ge1\),
\begin{equation}
\mathbb{P}(\mathcal G_n^c)\le C2^{-cn}.
\end{equation}
Consequently, \(
\sum_{n=1}^{\infty}\mathbb{P}(\mathcal G_n^c)<\infty\).

[Lem 97 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] We have w.o.p. that the following statements hold for all $t \in [\mathsf{T}', N^5]$. 

  \begin{enumerate} 
  	\item We have that $y_{a,b,c}^{\pm,j} \le \mathsf{y}_t^{\pm, j}$ for each $j \in [1,k]$.  
  	\item We have that $\widetilde{U}_k (x) \le \mathtt{U}_t^{k/N} (x)$ for each $x \in [x^-, x^+]$. 
  \end{enumerate}

[Cor TP2-forests-partition-function of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] If ${\mathbf{w}}$ is log-concave, then the array $(\PFforests{{\mathbf{w}}}{n,k})_{n,k\geq1}$ is TP2, that is
	\begin{align}
	\forall 1\leq {n}\leq{n'},\quad \forall 1\leq{k}\leq{k'},\qquad
	\PFforests{{\mathbf{w}}}{n,k}\,\PFforests{{\mathbf{w}}}{n',k'}
	\geq \PFforests{{\mathbf{w}}}{n,k'}\,\PFforests{{\mathbf{w}}}{n',k}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 16 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $c>0$. The assignment 
\[
F\mapsto\left\{ X_{w}\right\} 
\]
is a one-to-one correspondence between measures $F\in\mathcal{M}_{+}\left(\Omega_{m},H\right)$
satisfying $F\leq cE$ and positive range martingales $\left\{ X_{w}\right\} $
satisfying 
\begin{equation}
0\leq X_{w}\leq cI_{H_{w}}
\end{equation}
for every finite word $w$. The correspondence is characterized by
\begin{equation}
F\left(\left[w\right]\right)=E^{1/2}_{w}X_{w}E^{1/2}_{w}
\end{equation}
for every finite word $w$. In \prettyref{eq:5-2}, $X_{w}$ is extended
by zero on $H^{\perp}_{w}$.

[Cor 23 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$ and $n \in \mathbb{N}_+$. Then
\begin{align} 
 \mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+1}^{\infty} [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_s^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{2} f_1(n),
 \end{align}
where $f_1:\mathbb{N}_+ \mapsto \mathbb{R}$ is given by
\begin{align*}
\forall n \in \mathbb{N}_+, \quad f_1(n):= \begin{dcases}
	 1/n, \quad & \gamma \in (0 , \; 1/2), \\
	\log(n)/n, \quad & \gamma=1/2, \\
	n^{2 \gamma-2}, \quad & \gamma > 1/2.
\end{dcases}
\end{align*}

