[Proposition 21 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] For any $q\in\mathbb{R}$,
\begin{equation*}
\mathcal{H}_{\overline{\partial }}^{m}\left( q\right) =\mathcal{H}_{
\overline{\partial },P^*}^{m}\left( q\right) \oplus
\bigoplus\nolimits_{0\leq b\leq \left\lfloor \frac{2n+1-m}{2} \right\rfloor 
}\Lambda^{b}E_{2bq}\left( \Delta _{\overline{\partial },P^*}\left(
q\right) \right) ,
\end{equation*}
where $E_{\lambda }\left( \Delta _{\overline{\partial },P^*}(q)\right)$ denotes the eigenspace of $\Delta_{\overline\partial}$ restricted to antiprimitive forms corresponding to eigenvalue $
\lambda $. In particular, for $q<0$, $\mathcal{H}_{\overline{\partial }
}^{m}\left( q\right) =\mathcal{H}_{\overline{\partial },P^*}^{m}\left(
q\right) $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 167 (Null-fluxes for the wave and transport variables) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $f$ be a scalar function on $\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}$ and let $q \in [0,\infty)$. We respectively define the {wave} ingoing and outgoing $\weight$-weighted null-fluxes associated to $f$ as follows:
	\begin{subequations}
		\begin{align}
			\ingoingfluxwave{q}[f](\ubar,u) & \eqdef \int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}} \enmomem[f](\multipliervectorfield,\newuL) \, \weight^{q}   \volingoingnullhypersurface,  \\
			\outgoingfluxwave{q}[f] (\ubar,u) & \eqdef \int_{\outgoingcharacteristicsurfacetwoarg{u}{[\leftubar,\ubar)}} \enmomem[f](\multipliervectorfield,\Lunit) \, \weight^{q}  \ReciprocalLunitAppliedtoTimeFunction \voloutgoingnullhypersurface. 
		\end{align}
	\end{subequations}

We respectively define the \emph{transport} ingoing and outgoing $\weight$-weighted null-fluxes associated to $f$ as follows:
	\begin{subequations}
		\begin{align}
			\ingoingfluxtransport{q}[f](\ubar,u) & \eqdef \int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}} f^2  \, \weight^{q} \ReciprocaluLunitAppliedtoTimeFunction \volingoingnullhypersurface,  \\
			\outgoingfluxtransport{q}[f] (\ubar,u) & \eqdef \int_{\outgoingcharacteristicsurfacetwoarg{u}{[\leftubar,\ubar)	}} f^2  \, \weight^{q} \ReciprocalLunitAppliedtoTimeFunction \voloutgoingnullhypersurface. 
		\end{align}
	\end{subequations}

[Theorem thm:sharpness-local of arXiv:2511.01851, 'Percolation on graphs of polynomial growth is local:\\analyticity, supercritical sharpness'] Let $\mathscr{G}\in\mathfrak{G}$ and $p_0\in (p_c(\mathscr{G}),1]$. Then, there is a constant $c>0$ such that the set of all $\mathscr{H}\in\mathfrak{G}$ satisfying $p_c(\mathscr{H})<p_0$ and the following condition is a neighbourhood of $\mathscr{G}$:
	\begin{equation}
	\forall p\in [p_0,1],\qquad \forall u,v\in V(\mathscr{H}),\qquad \mathbb{P}_{p,\mathscr{H}}(u\longleftrightarrow v \centernot\longleftrightarrow \infty) \leqslant \exp(-c d_\mathscr{H}(u,v)).
	\end{equation}
    ~\hfill\hyperlink{target:sharpness}{\footnotesize\color{mycolor}$\downarrow$ context and proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:asympdfold of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] For $1\leq k\leq d$, we define
			\begin{equation}
			U_k(N) :=\sum_{\substack{i_1,\ldots,i_k\ge 1\\ i_1+\cdots+i_k=N}}
			p_{i_1}\cdots p_{i_k}.
			\end{equation}
			Then
			\begin{equation}
			U_k(N) \sim C^k \frac{\Gamma(1/d)^k}{\Gamma(k/d)} N^{k/d-1},
			\end{equation}
			where $\Gamma(x)$ is the usual Gamma-function. In particular, $U_d(N)\to C^d\Gamma(1/d)^d$  while
			$U_k(N)\to0$  for every \(k<d\). \\
			Moreover, if \(1\le r<d\) and \(m_1,\ldots,m_r\) are fixed positive
			integers, then
			\begin{equation}
			V_{\mathbf m}(N)
			:=
			\sum_{\substack{i_1,\ldots,i_r\ge 1\\
					m_1i_1+\cdots+m_ri_r=N}}
			p_{i_1}\cdots p_{i_r}
			=
			O\bigl(N^{r/d-1}\bigr)
			=
			o(1).
			\end{equation}
			All estimates are uniform under bounded shifts of \(N\).

