  \bigl(\mathsf P_{b,m,\eta}^{\mathrm{sel}},
        \mathsf P_{b,m,\eta}^{\mathrm{out}}\bigr)
  \longrightarrow0,
  \qquad b\to\infty,

\end{equation}

[Lem cost=lim_wasserstein of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\Pi_i\in \mathcal P_{s,1}( \mathsf{S})$, $i=0,1$. Then 
    \begin{align}
        \mathscr W^p_{gap,p}(\Pi_0,\Pi_1)=\lim_{n\to \infty} n^{-1} \mathcal C_p(\Pi_0^{1,n},\Pi^{1,n}_1)=\sup_{n\in \IN} n^{-1} \mathcal C_p(\Pi_0^{1,n},\Pi^{1,n}_1).
    \end{align}

