[Definition def:causaldefinition of arXiv:2412.02948, 'Causal transport on path space'] \ \\
\begin{enumerate}
    \item $\pi \in \Pi\del{\eta,\nu}$ is a causal coupling between $\eta$ and $\nu$ if\begin{equation}

        \text{ for all } t \in \sbr{0,1} \text{ and } B \in \mathcal{H}_t, \; \omega \mapsto \Theta_\pi^\omega\del{B} \text{ is } \mathcal{H}_t^\eta\text{-measurable}
        .
    \end{equation} We denote by $\Pi_{c}\del{\eta,\nu}$ the set of causal couplings between $\eta$ and $\nu$;
    \item A measurable map $T : \mathcal{W}^d \rightarrow \mathcal{W}^d$ is a causal Monge transport between $\eta$ and $\nu$ if the image of $\eta$ under $T$ is $\nu$ and the induced transport plan $\pi_T := \del{X_{\cdot},T}_{\#}\eta$ is a causal transport: $\pi_T\in \Pi_{c}\del{\eta,\nu}$. 
    \item We say that $\pi \in \Pi\del{\eta, \nu}$ is a bicausal coupling between $\eta$ and $\nu$ if $\pi \in \Pi\del{\eta, \nu}$ and $R_{\#}\pi \in \Pi\del{\nu, \eta}$ where $R$ is the exchange of coordinates: \begin{eqnarray*}
        R : \mathcal{W}^d \times \mathcal{W}^d &\rightarrow &\mathcal{W}^d \times \mathcal{W}^d\nonumber\\
        (\omega',\omega)&\mapsto &R\deln{\omega,\omega'} := \deln{\omega',\omega}
    \end{eqnarray*}  The set of all bicausal couplings between $\eta$ and $\nu$  is denoted $\Pi_{bc}\del{\eta,\nu}$. 
    \item $T : \mathcal{W}^d \rightarrow \mathcal{W}^d$ is said to be a bicausal Monge map between $\eta$ and $\nu$ if $\pi_T \in \Pi_{bc}\del{\eta, \nu}$.

    $\mathcal{T}_{bc}\del{\eta,\nu}$ denotes the set of all $\pi \in \Pi\del{\eta,\nu}$ such that $\pi = \pi_T$ for some bicausal Monge map $T$. Abusing notation, we will write $T \in \mathcal{T}_{bc}\del{\eta,\nu}$ if $\pi_T$ is a bicausal coupling.
    \item Finally, $\mathcal{T}_{bcb}\del{\eta,\nu}$ denotes the set of all $\pi \in \Pi\del{\eta,\nu}$ such that $\pi = \pi_T$ for some \emph{a.s. bijective}\footnote{Here, $T$ is said to be a.s. bijective if there exists $\hat{T} : \mathcal{W}^d \rightarrow \mathcal{W}^d$ such that $\eta$-a.s. $\hat{T} \circ T =X_\cdot$ and $\nu$-a.s. $T \circ \hat{T} = X_\cdot$.} bicausal Monge map $T$. 
\end{enumerate}

\begin{remark}

\mbox{}
\begin{enumerate}
    \item Comparing Definition (def:causaldefinition of the paper) and (equation eqn:toycausalexplanation of the paper), we observe two differences:
    \begin{itemize}
        \item the first is that we ask for measurability with respect to the completed $\sigma$-algebra $\mathcal{H}_t^\eta$, instead of just $\mathcal{H}_t$. This is because the disintegration $\Theta_\pi$ is only $\eta$-a.s. unique; and,
        \item secondly, we have used the right-continuous filtration $\del{\mathcal{H}_t}_{t \in \sbr{0,1}}$, instead of $\del{\mathcal{F}_t}_{t \in \sbr{0,1}}$. This is motivated by the fact $\del{\mathcal{H}^\eta_t}_{t \in \sbr{0,1}}$ is a complete, right-continuous filtration and many familiar results from stochastic analysis hold, e.g. martingales have c\`adl\`ag modifications.
    \end{itemize}



    \item Notice that to verify (equation eqn:causaldef of the paper), it is sufficient to check measurability of $\Theta_\pi\del{B}$ for all $B \in \mathcal{F}_t$. This observation implies that:
    \begin{itemize}
        \item if $\mathcal{H}_t^\eta = \mathcal{F}_t^\eta$ for all $t \in \sbr{0,1}$, then it does not matter if we replaced $\mathcal{H}_t$ with $\mathcal{F}_t$ in (equation eqn:causaldef of the paper). Indeed, the set of causal couplings would not change. This was observed in [backhoffveraguas2024adaptedwassersteindistancelaws] for the case when $\eta$ is the law of a strongly Markov process. We also mention [liptser1977statistics] which shows that $\mathcal{H}_t^\eta = \mathcal{F}_t^\eta$ when $\eta$ is the law of an SDE with Lipschitz drift and uniformly elliptic diffusion coefficient; and,
        \item $\Pi_c\del{\eta,\nu}$ and hence, $\Pi_{bc}\del{\eta,\nu},$ are compact for the topology of weak convergence by [causalopttptlassalle].
    \end{itemize}
    \end{enumerate}
\end{remark}

[Definition 14 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Suppose $\vec{y}\in \weyl_{2k}$, $b>0$, and $g:[0,b]\to[-\infty,\infty)$ is a continuous function with $g(b)<y_{2k}$. Let $\{U_i\}_{i=1}^k$ be independent reverse Brownian motions (with no drift) on $[0,b]$ from $U_i(b) = 2^{-1/2}(y_{2i-1}+y_{2i})$, and let $\{V_i\}_{i=1}^k$ be independent 3D Bessel bridges on $[0,b]$ to $V_i(b) = 2^{-1/2}(y_{2i-1}-y_{2i})$ as in Definition \ref{Def.Bessel}. For $1\leq i\leq k$, define $B_{2i-1} = 2^{-1/2}(U_i+V_i)$ and $B_{2i} = 2^{-1/2}(U_i-V_i)$. Then we let $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y},g}$ denote the law of $\{B_i\}_{i=1}^{2k}$, conditioned on the event
\begin{equation}
E_{\mathrm{avoid}}^{\mathrm{pin}} = \left\{B_{2i}(r) > B_{2i+1}(r) \mbox{ for all } i\in\llbracket 1,k\rrbracket, \, r\in(0,b)\right\},
\end{equation}
where $B_{2k+1} = g$. The expectation with respect to this measure is denoted by $\mathbb{E}_{\mathrm{pin}}^{b,\vec{y},g}$. When $g=-\infty$, we omit the last superscript and simply write $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y}}$, and $\mathbb{E}_{\mathrm{pin}}^{b,\vec{y}}$.

