[Proposition prop-BEln-3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $f\in C^2\left(\mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}\right)$ be a  positive, globally Lipschitz and bounded function.  Then for any fixed $t\ge0$, $x=(x^{(1)},\cdots,x^{(r+1)})\in \mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}$ and any constants $\alpha_k\in \mathbb{R} (2\le k\le r+1)$,
\begin{align}
&P_tf(x)\left\|\sum_{i'=1}^{r+1}\alpha_{i'}\prod_{j=1}^{i'-1}B_{j}\nabla^{(i')}\ln P_tf(x)\right\|_{A_0}^2\le P_t\left(f\left\|\sum_{i'=1}^{r+1}\left(\sum_{i=0}^{i'-1}\alpha_{i'-i}\frac{t^i}{i!} \prod_{j=1}^{i'-1}B_{j}\right)\nabla^{(i')}\ln f\right\|^2_{A_0}\right)(x),
\end{align}
where $\alpha_1=1$.

