[Lem Black-Scholes_vs_BM of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] {The specific relative entropy between a $\mathbb{R}^l$-valued martingale Black-Scholes models with parameter $\Gamma\in \mathbb{R}^{l \times l}$ and Brownian motion, both starting wlog.\ at $\mathbf{1}$, is given by:
\begin{equation} \begin{split}  \textstyle 
h_l(\mathcal L(M^{\Gamma})|\mathbb B^l)=\frac{1}{2}\Big(\sum_{i=1}^l \big(e^{\sum_{k=1}^l \Gamma_{ik}^2}-1\big)-l+\frac{1}{2} \sum_{i=1}^l \sum _{k=1}^l \Gamma_{ik}^2 - \log \big(\det (\Gamma \Gamma^T) \big)\Big).
\end{split}
\end{equation}}

[Corollary cor:enhanced_dissipation of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that $q,p\in (2,\infty)$ satisfy $1<\frac{2}{p}+\frac{3}{q}<2$. Assume further $p<\frac{q}{3-q}$ in case $q<3$. Fix 
\begin{equation*}
M \geq 1 ,  \qquad  \varepsilon\in (0,1), \qquad \lambda\in (0,\infty) \ \quad \text{ and }\ \quad b\in (1,\infty). 
\end{equation*}
Then there exist $\mu>0$ and $\theta\in \ell^2$ such that $\#\{k\,:\, \theta_k\neq 0\}<\infty$ for which the following assertion holds. For all initial data
\begin{equation*}
u_0\in \mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^3)\qquad \text{ such that }\qquad \|u_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)}\leq M,
\end{equation*}
let $(u,\tau)$ be the unique maximal $(p,q)$-solution to the stochastic {\normalfont{3D NSEs}} (equation eq:navier_stokes_intro of the paper). Then there exists a stopping time $\tau_0\in (0,\tau]$ and a random constant $K\in [1,\infty)$ such that 
\begin{equation}

{\mathbf P}(\tau_0=\infty)>1-\varepsilon 
\qquad \text{ and }\qquad
{\mathbf E} K^b\lesssim_{p,q,M,\varepsilon,\lambda,b}1,
\end{equation}
for which we have the following enhanced dissipation estimate a.s.\
\begin{align}

\sup_{t<\tau_0}\Big(e^{\lambda t}\Big\|u(t,\cdot)-\int_{\mathbb{T}^3} u_0 \Big\|_{L^2(\mathbb{T}^3)}\Big)
&\leq K \Big\|u_0-\int_{\mathbb{T}^3}u_0\Big\|_{L^2(\mathbb{T}^3)},\\

\Big\|t\mapsto e^{\lambda t}\Big( u(t,\cdot)-\int_{\mathbb{T}^3} u_0\Big)\Big\|_{L^{2p}(0,\tau_0;L^{2q}(\mathbb{T}^3))}
&\leq K.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2605.14206, 'The clumsy coupon collector's problem'] The following limit holds for all $t < 0$ as $m \to \infty$,
  \[
    m^{-t} \binom{m \, e^{-t/m}}{m}^{-1} 
    \longrightarrow \Gammaop(1-t).
  \]
  \begin{proof}
    Combine the facts $m\,e^{-t/m} = m - t + O(m^{-1})$
    and $\binom{-\nu}{m} = (-1)^m \binom{\nu+m-1}{m}$
    from
    \cite[pp.~49--56]{oldham2009atlas}
    to write
    \begin{align*}
      m^{-t} \binom{m\,e^{-t/m}}{m}^{-1}
      &= m^{-t} \binom{m-t+O(m^{-1})}{m}^{-1}
      = m^{-t} \binom{m+(1-t+O(m^{-1}))-1}{m}^{-1}\\
      &= m^{-t} \left(-1\right)^m \binom{t-1+O(m^{-1})}{m}^{-1}.
      \intertext{Next use the asymptotic expression
      $\binom{\nu}{m}^{-1} \sim (-1)^m \, m^{\nu+1} \Gammaop(-\nu)$,}
      &\sim m^{-t} \, m^{t+O(m^{-1})} \Gammaop(1-t+O(m^{-1}))
      \sim \Gammaop(1-t). \qedhere
    \end{align*}
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn indices of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] Let $H=(V,E)$ be a graph with node set $V$ and edge set $E$.\\
    The Zagreb index is defined as
    \begin{align}
        Z_H:=\sum_{v \in V} (d(v))^2.
    \end{align}
For $\alpha \in \mathbb{R}$, the  $\alpha$-Randić index of $H$ is given by
    \begin{align}
        R_H^{[\alpha]}:=\sum_{\{u,v\} \in E} (d(u)d(v))^\alpha.
    \end{align}
If $H$ is connected, the Wiener index is defined as  
    \begin{align}
        W_H:=\frac{1}{2}\sum_{u,v\in V} \dist(u,v).
    \end{align}
If $H$ is connected and rooted, the level index is defined as 
    \begin{align}
        L_{H}:=\frac{1}{2}\sum_{u,v \in V} \vert D(u)-D(v)\vert.
    \end{align}
For a random graph $H$ of a class of rooted, connected graphs $\mathcal{H}$, the Gini index is given by
\begin{align}
G_H:=\frac{L_{H}}{\,{\mathbb{E}}[V]^2\,{\mathbb{E}}[D_\mathcal{H}^\star]},
\end{align}
where $D_\mathcal{H}^\star$ is the depth of a randomly chosen node in a random tree of class $\mathcal{H}$ (see [ma17] for more information).

