[Lem 90 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Proposition \ref{dhtqd} holds under either of the following two conditions. 

\begin{enumerate} 
	\item The point $\bar{z}$ is above the level line $\mathcal{U}_{q'}^{k N^{-1-4R\delta}}$ (namely, $\bar{y} \ge \mathcal{U}_{q'}^{k N^{-1-4R\delta}} (\bar{x})$). 
	\item We have $(\mathtt{d}_{\bar{z}} \mathtt{e}_{\bar{z};q'})^{1/2} < N^{-R\delta-1} (q-q')^{-1}$ (which holds if $(\mathtt{d}_{\bar{z}} \mathtt{e}_{\bar{z};q'})^{1/2} < N^{-2R\delta} \omega^{-1}$).
\end{enumerate}

[Definition cocycle of arXiv:2605.02226, 'Finitely Dependent Processes on Subshifts'] Let $ X \subset A^{\mathbb{Z}^d}$ be a subshift and $H$ be a group. A $ H$-valued \textbf{cocycle} on $ X$ is a continuous function $c: X \times \mathbb{Z}^d \rightarrow H$ satisfying, \begin{equation} 
     c(x, v+ w) = c(x, v)\cdot c(\sigma^{v}(x), w).  
    \end{equation}

[Lemma Lemma on Steklov of arXiv:2601.09990, 'Remarks on the convex integration technique applied to singular stochastic partial differe'] Let $I \subset \mathbb{R}$ be any interval, $E$ any measurable set over $\mathbb{T}^{d}$, $1 \leq q, r \leq \infty$ and $h > 0$. Given $v \in L^{r} (I;  L^{q}(E))$, we define a Steklov average by 
\begin{align*}
v_{h} (t, \cdot) \triangleq \frac{1}{h} \int_{t-h}^{t} \tilde{v} (s, \cdot) ds \hspace{2mm} \text{ where } \hspace{2mm}  \tilde{v}(t, \cdot) \triangleq 
\begin{cases}
v(t, \cdot) &\text{ if } t \in I, \\
0 & \text{ if } t \in \mathbb{R} \setminus I.
\end{cases}
\end{align*}
Then 
\begin{enumerate}
\item (e.g. [BD25]) $\lVert v_{h} \rVert_{L^{q}(I; L^{q}(E))} \leq \lVert v \rVert_{L^{q}(I; L^{q}(E))}$ and $(\partial_{t} v_{h})(t,x) = \frac{\tilde{v}(t,x) - \tilde{v}(t-h,x)}{h}$. 
\item (e.g. [CDG17]) $v_{h} \in C(I; L^{q}(E)) \cap L^{\infty} (I; L^{q}(E))$. 
\item (e.g. [CDG17]) $v_{h} \to v$ in $L^{r} (I; L^{q}(E))$ as $h\searrow 0$. 
\end{enumerate}

[Lemma Th+i of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Let $\theta\in [0,\pi]$ and $\gamma\geq 0$. Define $\rho_{i}(\theta)^2:=v_i^2\cot^2\theta+1$, for $i=1,2$. For each $i\in \{1,2\}$, $\Theta^+_{0, i}$ and $\hat{H}_{0,i}^2$ we have 

\begin{enumerate}
\item for $\theta\leq \pi/2$,
\begin{align}
\mathbb{E}^0_i\left[{\mathds{1}}_{\{\Theta^+_{0, i}\leq \theta\}}e^{-\gamma \hat{H}_{0,i}^2}\right]&= \pi \lambda^{3/2}\int_{0}^{\infty}\int_{0}^{h_1\rho_1(\theta)}\int_{t_+}^{\infty}  e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1  {\nonumber}\\
&\quad + \pi \lambda^{3/2} \int_{0}^{\infty}\int_{h_1}^{h_1\rho_1(\theta)}\int_{0}^{t_-} \, e^{-(\lambda\pi+\gamma)\hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 {\nonumber}\\

&\quad + \pi \lambda^{3/2}\int_{0}^{\infty}\int_{h_1\rho_1(\theta)}^{\infty}\int_{0}^{\infty}\, e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 ,
\end{align}

where $t_{\pm}:= h_1v_i\cot\theta\pm \sqrt{h_1^2 \rho_i^2(\theta) -h_2^2}$.

\item For $\theta>\pi/2$ 

\begin{align}
\mathbb{E}_0\left[{\mathds{1}}_{\{\Theta_{0, i}^+\geq \theta\}} e^{-\gamma \hat{H}_{0,1}^2} \right]&= \pi \lambda^{3/2}
\int_{0}^{\infty}\int_{0}^{h_1}\int_{\tilde{t}_+\wedge \sqrt{h_1^2-h_2^2}}^{\sqrt{h_1^2-h_2^2}}\, e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 ,
\end{align}
where $\tilde{t}_+:= h_1v_i\cot\theta+ \sqrt{h_1^2 \rho_i(\theta)^2 -h_2^2}$, for $i=1,2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] Let \(\phi\in C^\infty(\R)\) be even and strictly convex.  Assume that
\begin{equation}
 -1<\phi'(x)<1,
 \qquad
 |\phi(x)|\le C+|x|,
\end{equation}
that \(\phi^{(j)}\) is bounded for every \(j\ge1\), and that
\begin{equation}
 \phi(x)=x+c+d_1\e^{-2x}+d_2\e^{-4x}+d_3\e^{-6x}
 +O(\e^{-8x}),
 \qquad d_1>0,
\end{equation}
as \(x\to+\infty\), with differentiated remainder of every order.  Fix \(a>0\) and \(r\ge0\), and let
\[
 u(x)=T_{a,r}\phi(x).
\]
Then \(u\) is even, belongs to \(C^\infty(\R)\), is strictly convex, and satisfies
\begin{equation}
 -1<u'(x)<1,
 \qquad
 |u(x)|\le C_{a,r}+|x|.
\end{equation}
Every derivative \(u^{(j)}\), \(j\ge1\), is bounded.  Moreover, there exist constants
\(\widetilde c,\widetilde d_1,\widetilde d_2,\widetilde d_3\) such that
\begin{equation}
 u(x)=x+\widetilde c+\widetilde d_1\e^{-2x}
 +\widetilde d_2\e^{-4x}+\widetilde d_3\e^{-6x}
 +O(\e^{-8x}),
\end{equation}
with differentiated remainder of every order, and
\begin{equation}
 \widetilde d_1=d_1\e^{2(1-a)r}>0.
\end{equation}

If \(u(r,x)=T_{a,r}\phi(x)\) and \(r\) is restricted to a compact interval, then the coefficients in \eqref{eq:u-tail} are smooth functions of \(r\).  For every \(\alpha,\ell\ge0\), the expansion obtained by applying \(\partial_r^\alpha\partial_x^\ell\) to \eqref{eq:u-tail} has a remainder that is uniform for \(r\) in that interval.

