[Corollary 41 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\mu$ be an even, log-concave probability measure on $\R$ with density. 

For any pair of measurable functions $f, g:\R \to [0,\infty)$ and any non-decreasing measurable function $W: \R_+ \to (0, \infty)$ satisfying the pointwise relation
\begin{equation}

f(x)^{\frac{1}{2}} g(y)^{\frac{1}{2}} \leq W\left(\frac{|x-y|}{2}\right) \quad \text{for all } x, y \in \R,
\end{equation}
one has the functional inequality
\begin{equation}

\left( \int_{\R} f(x) \, d\mu(x) \right)^{\frac{1}{2}} \left( \int_{\R} g(y) \, d\mu(y) \right)^{\frac{1}{2}} \leq  \int_{\R} W(|r|) \,d\mu(r).
\end{equation}

[Proposition 3 (Janson, \cite{janson2013}) of arXiv:2608.26501, 'Explicit Bounds on the Entropy of Piecewise H\"{o}lder Graphon Models'] Let $W$ be a graphon defined on a set $\Omega$ with probability measure $\mu$. Then 
\begin{equation}
H\big(G(n,W)\big)\geq\binom{n}{2} \iint_{\Omega^2}h\big(W(x,y)\big)\dd\mu(x)\dd\mu(y),
\end{equation}
where $H\big(G(n,W)\big)$ is the entropy of $G(n,W)$. Further,
\begin{equation}
\lim_{n\to\infty}\frac{H\big(G(n,W)\big)}{\binom n2} = \iint_{\Omega^2}h\big(W(x,y)\big)\dd\mu(x)\dd\mu(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Fix $T > 0$. Let $h_\eps$ denote the BPHZ solution of the KPZ equation with initial data $\psi \in C^\vartheta(\mathbb{T})$ for $\vartheta \in (0,1/2)$ driven by $\xi_\eps = \xi \ast \rho^\eps$ where $\xi$ is space-time white noise and $\rho$ is a non-negative symmetric standard mollifier. Then for any $\kappa > 0$
	\begin{align*}
		\limsup_{M \to \infty} \sup_{\eps > 0} \mathbb{P} ( \eps^{-1/2} \| h_\eps - h \|_{C^{-\kappa}([0,T] \times \mathbb{T})} > M) = 0.
	\end{align*}
	Furthermore, the rate $\eps^{1/2}$ implied by the above statement is sharp since, writing $w_\eps = \eps^{-1/2} (h_\eps - h)$, we have that $(h_\eps, h, w_\eps)$ converges in law in $C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{-\kappa}((0,T] \times \mathbb{T})$ to $(h, h, w)$ where $w$ is the BPHZ solution of
	\begin{align*}
		(\partial_t - \partial_x^2) w = 2 \partial_x w \partial_x h +  c_1 \tilde{\xi}_1+c_2\tilde{\xi}_2
	\end{align*}
	with initial data $0$ where $c_1$, $c_2$ are strictly positive constants and $\tilde{\xi}_1$, $\tilde{\xi}_2$ are partially correlated\footnote{the precise covariance matrix is provided in Proposition~\ref{prop:new_noise_conv} below} space-time white noises  independent from $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be a Wigner matrix satisfying Assumption~\ref{ass:momass}. Fix a (small) $\varepsilon>0$ and a (large) $C>0$. For any fixed $p,n,S\in\N$ it holds that 
\begin{equation}
\Psi^{(p)}(n,S) \lesssim  N^{-(p-2)/2+\xi} \left( N^{-1} + \bm{1}_{n\ge p} N^{(n-p)/2}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $z\in\mathcal{D}_g(\varepsilon,C)$, which is defined in~\eqref{eq:def_D_global}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2604.04747, 'Scaling limit and density conjecture for activated random walk on the complete graph'] \thlabel{lem:max-tail}
    For $x=x_n$ and $T=T_n$ satisfying  $x = \Omega(\sqrt{\log n})$, $x = o(n^{1/6})$, and $\log n \ll T \ll 1/\mu_x$, 
    \begin{equation*}
        \mathbf{P}(m(T) \ge x) \sim \mu_x \,T.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

