[Theorem 1 (Informal; see Theorem~\ref{thm:wass_stab}) of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose that $\mu$ satisfies a suitable regularity condition, implying in particular that $\mathsf T^\mu$ is Lipschitz, and that $\nu \in \cP(\mathbb{R}^d)$ has a finite second moment. Then,
\begin{align*}
    \|\mathsf T^\mu - \mathsf T^\nu\|_{L^2(\gamma)} \le c(\mu)\, W_2(\mu,\nu) \log\Bigl(2 + \frac{c'(\mu)}{W_2(\mu,\nu)}\Bigr)\,, 
\end{align*}
where $c(\mu)$, $c'(\mu)$ are constants that depend only on $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:growth of arXiv:2604.14851, 'Pool model: a mass preserving multi particle aggregation process'] \

\begin{enumerate}

\item { For $\lambda<1$, we have asymptotically a.s. $\sqrt{t}\log^{-\frac{1+\epsilon}{2}}(t)\le {\mathcal{E}}_t\le \sqrt{t}\log(t)$ for all $\epsilon>0$. }
\item For $\lambda=1$, $\forall\zeta<1$, {$\limsup_{t\to\infty}\frac{{\mathcal{E}}_t}{t^\zeta}=\infty$ a.s.}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 (Log-concave bilinear forms) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Assume the estimates in \cref{thm:letwin}.  Let
\(X\in\R^m\) and \(Y\in\R^n\) be independent isotropic log-concave random
vectors, let \(0\neq B\in\R^{m\times n}\), and set
\[
  S=X^{\mathsf T}BY,
  \qquad
  \sigma^2=\|B\|_{\HS}^2.
\]
Then \(Z=S/\sigma\) admits a nonnegative scalar Stein kernel
\(\kappa_Z\) such that
\begin{equation}
  \E(\kappa_Z(Z)-1)^2
  \leq\frac{20}{r_4(B)}.
  \tag{5.2}
\end{equation}
Consequently, for \(G\sim N(0,1)\),
\begin{equation}
  \boxed{
  W_2^2\!\left(\Law(Z),\Law(G)\right)
  \leq\frac{20}{r_4(B)}.}
  \tag{5.3}
\end{equation}
Equivalently, if \(G_\sigma\sim N(0,\sigma^2)\), then
\begin{equation}
  W_2^2\!\left(\Law(S),\Law(G_\sigma)\right)
  \leq
  20\frac{\Tr((B^{\mathsf T}B)^2)}{\Tr(B^{\mathsf T}B)}.
  \tag{5.4}
\end{equation}

[Lemma 5 of arXiv:2609.02392, 'Large values of cubic and quartic Dirichlet $L$-functions of prime moduli'] With the notation as above and assuming the truth of GRH, we have, for large $X$ and any positive integer $c \in \mz$, 
\begin{equation} 
\sum_{\substack{(p,3)=1}} \ \sumstar_{\substack{\chi \shortmod{p} \\ \chi^3 = \chi_0}} (\log p)\chi(c) \Phi\Big(\frac{p}{X}\Big)=
\displaystyle \delta_{c=\text{cubic}} {\widehat \Phi}(1) X  + O( X^{1/2+\varepsilon}\log (c+2) ),
\end{equation}
and
\begin{equation} 
\sum_{(p,2)=1} \ \sumstar_{\substack{\chi \shortmod{p} \\ \chi^4 = \chi_0}} \chi(c) \Phi\Big(\frac{p}{X}\Big)=
\displaystyle \delta_{c=\text{quartic}} {\widehat \Phi}(1) X + O( X^{1/2+\varepsilon}\log (c+2) ).
\end{equation}
Here and after the asterisk on the sum over $\chi$ in \eqref{cubiccharsum} restricts the sum to primitive characters and $\chi_0$ denotes the principal character, while the asterisk on the sum over $\chi$ in \eqref{quarticcharsum} limits the sum to primitive characters $\chi$ such that $\chi^2$ remains primitive.

