\begin{align*}
1=\mathbb{P}(Y\in \mathbb{R}) &\le \mathbb{P}(Y \ge 0) + \mathbb{P}(Y\le 0) \\
&= \mathbb{P}(Y \ge 0) + \mathbb{P}(-Y\le 0) \\
