[Lem kolmogorov of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] {durrett}}] 
 For a sequence of mutually independent random variables $(S_{j})_{j \in \mathbb{N}}$, let $C > 0$ be given. Then the series $\sum_{j=1}^{\infty} S_{j}$ converges almost surely if and only if
 \begin{equation} 
     \sum_{j=1}^{\infty} \Prob{\left|S_{j}\right| > C} < \infty, \quad \sum_{j=1}^{\infty} \E{S_{j} \mathbf{1}_{\left|S_{j}\right| \leq C}} < \infty \quad \text{and} \quad \sum_{j=1}^{\infty} \var{S_{j} \mathbf{1}_{\left|S_{j}\right| \leq C}} < \infty. 
 \end{equation}

\hfill $\blacksquare$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:variance of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For $X\in\{D,R\}$,
\begin{equation}

 \operatorname{Var}(X_m)\leq Cm^{3/2}.
\end{equation}

[Corollary Cor.Jump of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a constant $C(c_{-},c_{+})$ such that, for any bond $b\in(\mathbb{Z}^2)^*$ and $\lambda\in(0,1)$,  we have the following uniform bound for $\pi_b\widetilde{G}_\lambda$:
		\begin{equation*}
			\norm{\pi_b\widetilde{G}_\lambda}_{L^\infty}\leqslant C m 3^{4m},\qquad\forall b\in(\mathbb{Z}^2)^*,\ \lambda\in(0,1),\quad\forall m\in\mathbb{N}.
		\end{equation*}
		\begin{proof}
			Similar to the proof for (equation eq.H1TwoScaleVar of the paper) in Proposition~(prop.H1TwoScale of the paper), we can compute $\pi_{b}\widetilde{G}_\lambda(\eta)$ exactly using the expression for $\widetilde{G}_\lambda$ and the locality of the corrector Lemma~(lem.Homogenization of the paper) (equation lem.Correctorlocal of the paper). Suppose that the bond $b= \{x,x+e_i\}$ lies in $\overline{(z+{\scaleobj{1.2}{\square}}_m)^*}$ for $z\in\mathcal{Z}_m$, then we have
			\begin{equation*}
				\pi_b\widetilde{G}_\lambda(\eta) = {\mathsf{D}}_{e_i}\overline{g}_\lambda(x)(\overline{\eta}(x)-\overline{\eta}(x+e_i))+\sum_{j=1}^{2}({\mathsf{D}}_{e_j}\overline{g}_\lambda)_{z+{\scaleobj{1.2}{\square}}_m}\pi_{x,x+e_i}\phi^z_{e_j,m}.
			\end{equation*}
			Combining (equation eq.GreenDBound of the paper) in Proposition~(prop.GreenEstimate of the paper) and (equation lem.CorrectorLp of the paper) in Lemma~(lem.Homogenization of the paper), we can obtain the desired result.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:last_ball of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Keep the same setting in Theorem (thm:upper_bd_local_time_bdry of the paper). 
	For each $1\le i \le d$, 
	\begin{align}
		\mathbb{E}[\zeta_{n}(i)-\zeta_{0}(i)]  
		&= (1-\varepsilon)n+O(\sqrt{n}).
	\end{align}
	In particular, for $d=2$, 
	\begin{align}
		\mathbb{E}[\zeta_{n}(1)-\zeta_{0}(1)] 
		&= (1-\varepsilon)n + (1-\varepsilon)^{2}\mathbf{1}(c\ge 2) \sqrt{\frac{2\varepsilon^{3}(1-\varepsilon)^{5} n}{\pi }} 
		+ o(\sqrt{n}), \\
		\mathbb{E}[\zeta_{n}(2)-\zeta_{0}(2)] 
		&= (1-\varepsilon)n + (\mathbf{1}(c\ge 2)+\varepsilon\mathbf{1}(c=1)) \sqrt{\frac{2\varepsilon^{3}(1-\varepsilon)^{5} n}{\pi }} 
		+ o(\sqrt{n}).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 85 of arXiv:2601.16377, '2601.16377'] For each $h \in [H]$, we introduce the function
\begin{equation}

\sigma_h(z)= \prod_{k = k^-(h)}^{k^+(h)} \sqrt{(z - \alpha_k)(z - \beta_k)}
 \end{equation}
 for $z$ in $\amsmathbb{C}\setminus \bigcup_{k = k^-(h)}^{k^+(h)} [\alpha_k,\beta_k]$, where we use the branch of the square root such that $\sigma_h(z)$ is a holomorphic function in this domain and such that $\sigma_h(z) \sim z^{k^+(h) - k^-(h) + 1}$ as $z \rightarrow \infty$. Next, we define
\[
\psi_h(z) :=\psi_h^+(z) \cdot \psi_h^-(z),
\]
where
\begin{equation}

 \psi_h^-(z) =\begin{cases} z-\hat a'_h & \textnormal{if }\iota_h^- \geq 2 \textnormal{ and } \hat a'_h\in \amsmathbb{S}_h,\\ 1 & \textnormal{otherwise}. \end{cases}\qquad
 \psi_h^+(z) =\begin{cases} z-\hat b'_h & \textnormal{if }\iota_h^+ \geq 2 \textnormal{ and } \hat b'_h\in \amsmathbb{S}_h,\\ 1 & \textnormal{otherwise}. \end{cases}
\end{equation}
We finally set
\begin{equation}

 s_h(z) := \frac{q_h^{-}(z)}{\sigma_h(z) \cdot \psi_h(z)}.
\end{equation}

[Lem CT LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Set $c_2 \coloneqq (2c_1)^{-1/d^{\mathrm{min}}_\mathrm{w}}$,
  where we recall the constant $c_1$ from Lemma~(lem:hk est of the paper).
  Then, for all sufficiently small $t > 0$, we have the following.
  For any $x_0 \in M$ and $n \in \mathbb{N}$,
  \begin{equation}
    \inf_{\bm{x}\in \hat{B}_*(x_0,c_2 t^{1/d^{\mathrm{min}}_\mathrm{w}})}
    \hat{E}_{\bm{x}}[C_t^n]
    \geq
    (n!)^{\hat{d}_{\mathrm{s}}^*/2}
    \bigl(\tilde{c} t^{d_{\mathrm{ct}}}\bigr)^n.
  \end{equation}

