body:
[Definition def:puremixedstoppingtimes of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] The stopping time in (equation def:admissST-eq of the paper) is said to be a Markovian randomized stopping time if $\Psi^{(i)}$ is on the form
\begin{align}
\Psi^{(i)}_t= A^{(i)}_t  +  \infty \mathbb{I}\{\tau^{D_i} \leq t \}, \enskip t  \geq 0, 
\end{align} 
where $(A_t^{(i)})_{t \geq 0}$ is a continuous additive functional of $X$ (see e.g., [revuz2013continuous]) and
\begin{align*}
\tau^{D_i}:= \inf \{t \geq 0:X_t \in  D_i\},
\end{align*}
where $D_i \subseteq {\cal I}$ is a measurable (stopping) set. 

The stopping time in (equation def:admissST-eq of the paper) is said to be a Markovian pure stopping time if it is on the form of a first entry time, i.e., in case $A^{(i)}_t = 0,t \geq 0$ so that $\tau_{\Psi^{(i)}} = \tau^{D_i}$.

[Lem lem10 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] There exist two random variables  $R_4(\omega)$ and $R_5(\omega)$ depending on the initial data, $\varepsilon_0$, $\nu$, $D$, $f$ and universal constants, such that for every $E > 0$, there exists $t(\omega,E) \leq -1$, such that for all $t_0 \leq t(\omega,E)$ and $x_0=(u_0,\rho_0,\sigma_0) \in {H}^{1}$  with $|x_0| < E$, we have
		\begin{align}
			\|\nabla v^\varepsilon(0,\omega,t_0,z(t_0,\omega)u_0)\|_{L^2} \leq  R_4(\omega),~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|\nabla \sigma(0,\omega,t_0,\sigma_0)\|_{L^2} \leq R_5(\omega),~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|\nabla \rho(0,\omega,t_0,\rho_0)\|_{L^2} \leq R_5(\omega),~for~all~t \in [-1,0].
		\end{align}
		Therefore, $B(0,R_4(\omega)+2{R_5(\omega)})$ is a random absorbing set in $V$.
		\begin{proof}
			The differential inequality (equation b4 of the paper) gives 
			\begin{align*}
				\frac{d}{dt}\|\nabla v^\varepsilon\|_{L^2}^{2}\ +\nu \|\Delta v^\varepsilon\|_{L^2}^{2} \leq& \frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon\|_{L^2}^{4}+\frac{D}{2}\|\nabla \rho \|_{L^2}^2 +C{z^4(t,\omega)}\|\rho \|_{L^2}^6\\&+C_f+Cz^4(t,\omega),
			\end{align*}
			which implies that 
			\begin{align*}
				\frac{d}{dt}\|\nabla v^\varepsilon\|_{L^2}^{2}\   \leq&  \frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon \|_{L^2}^{2}\|\nabla v^\varepsilon \|_{L^2}^{2}+\frac{D}{2}\|\nabla \rho \|_{L^2}^2+C{z^4(t,\omega)}\|\rho \|_{L^2}^6\\&+C_f+Cz^4(t,\omega).
			\end{align*}
			Let
			\begin{align*}
				f(t)=\frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon(t) \|_{L^2}^{2}.
			\end{align*}
			Applying Lemma (lem1 of the paper) on an arbitrary interval $[s,0] \subset [-1,0]$, we find
			\begin{align*}
				\|\nabla v^\varepsilon(0)\|_{L^2}^{2} \leq& e^{\int_{s}^{0} f(\xi)d\xi}[\|\nabla v^\varepsilon(s)\|_{L^2}^{2}+\frac{D}{2}\int_{s}^{0}\|\nabla \rho(\xi) \|_{L^2}^{2}d\xi+C\int_{s}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6 d\xi\\
				&+\int_{s}^{0} (C_f+Cz^4(\xi,\omega))d\xi].
			\end{align*}
			Integrating $s$ on the interval $[-1,0]$ yields
			\begin{align*}
				\|\nabla v^\varepsilon(0)\|_{L^2}^{2} \leq& e^{\int_{-1}^{0} f(\xi)d\xi}[\int_{-1}^{0}\|\nabla v^\varepsilon(s)\|_{L^2}^{2}ds+\frac{D}{2}\int_{-1}^{0}\|\nabla \rho(s) \|_{L^2}^2ds+C\int_{-1}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6d\xi\\&+\int_{-1}^{0} (C_f+Cz^4(\xi,\omega))d\xi].
			\end{align*}
			We estimate
			\begin{align}
				\int_{-1}^{0} f(\xi)d\xi &\leq C\mathop {sup}\limits_{t \in [-1,0]} \frac{1}{z^2(t,\omega)} \int_{-1}^{0}\|\nabla v^\varepsilon(\xi) \|_{L^2}^2d\xi \notag\\&\leq CR_3(\omega)\mathop {sup}\limits_{t \in [-1,0]} \frac{1}{z^2(t,\omega)}=r_3(\omega),
			\end{align}
			and
			\begin{align*}
				\int_{-1}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6d\xi &\leq \mathop {sup}\limits_{t \in [-1,0]} z^4(t,\omega)  \mathop {sup}\limits_{t \in [-1,0]}\|\rho(t) \|_{L^2}^6\\& \leq {R_0}^6\mathop {sup}\limits_{t \in [-1,0]} z^4(t,\omega)=r_4(\omega).
			\end{align*}
			We also estimate
			\begin{align*}
				\int_{-1}^{0} (C_f+Cz^4(\xi,\omega))d\xi \leq r_5(f,\omega),
