body:
[Lemma lem:monotonicity of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Let $\ell$ be a random loop in $U$,  independent of $\Gamma_U$,  whose law is absolutely continuous with respect to the Brownian loop measure in $U$. Write $\widetilde\SCL$ for the outer boundary of the cluster obtained by merging $\ell$ together with all of the loops of $\Gamma_U$ which touch $\ell$, and, on the event that $\ell$ is not contained in the interior of a loop of $\Gamma_U$, let
\begin{equation*}
	\widetilde\Gamma_U \defeq \left\{\SCL \in \Gamma_U : \SCL \not\subseteq \overline{\mathop{\mathrm{int}}(\widetilde\SCL)}\right\} \cup \left\{\widetilde\SCL\right\};
\end{equation*}
on the complementary event (on which the merged cluster is not outermost), set $\widetilde\Gamma_U \defeq \Gamma_U$, in which case the statements below are elementary.
Recall that the law of $\widetilde\Gamma_U$ is absolutely continuous with respect to the law of $\Gamma_U$, so that $D_{\widetilde\Gamma_U}^U$ is well defined and almost sure statements about $D_{\Gamma_U}^U$ transfer to $D_{\widetilde\Gamma_U}^U$. Here and below, $D_{\Gamma_U}^U(\SCL, \widetilde\SCL)$ denotes the distance from the loop $\SCL \in \Gamma_U$ to the \emph{subset} $\widetilde\SCL$ of $\overline{U}$, in the sense of (subsec:setup of the paper). Then, a.s.,
\begin{equation*}
	\begin{cases}
		D_{\widetilde\Gamma_U}^U(\SCL_1, \SCL_2) \le D_{\Gamma_U}^U(\SCL_1, \SCL_2) \wedge \left(D_{\Gamma_U}^U(\SCL_1, \widetilde\SCL) + D_{\Gamma_U}^U(\SCL_2, \widetilde\SCL)\right) & \text{for } \SCL_1, \SCL_2 \in \widetilde\Gamma_U \setminus \{\widetilde\SCL\}; \\
		D_{\widetilde\Gamma_U}^U(\SCL, \widetilde\SCL) \le D_{\Gamma_U}^U(\SCL, \widetilde\SCL) & \text{for } \SCL \in \widetilde\Gamma_U \setminus \{\widetilde\SCL\}.
	\end{cases}
\end{equation*}
In particular, a.s., $D_{\widetilde\Gamma_U}^U(\widetilde\SCL(x), \widetilde\SCL(y)) \le D_{\Gamma_U}^U(\SCL(x), \SCL(y))$ for all $x, y \in U_\BQ$ (where $\widetilde\SCL(x) = \SCL(x)$ if $x$ is not surrounded by $\widetilde\SCL$ and $\widetilde\SCL(x) = \widetilde\SCL$ otherwise).

[Cor 7 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Under the assumptions and notation of Proposition \ref{prop:Laplace} the functions $g_T$ and $h_T$ are nonincreasing, and have their supports in $[0,Ta]$, where $a$ is given by \eqref{e:a}, $g_T$ is bounded by $1$. Moreover, $g_T$ satisfies the equation
 \begin{equation}
  g_T(t)=V_T(t)+\int_0^\infty g_T(t+s)\varphi(s)ds

  \end{equation}
where $V_T$ is bounded and nonnegative, has its support in $[0,Ta]$ and it is given by
\begin{equation}
V_T(t)=1-e^{-f_T(t)}-(1-e^{-f_T(t)})\int_0^\infty g_T(t+s)\varphi(s)ds-e^{-f_T(t)}H\left(\int_0^\infty g_T(t+s)\varphi(s)ds\right).

\end{equation}
Moreover,  equation \eqref{e:gT_VT} may be written in an equivalent form as
\begin{equation}
 g_T(t)=V_T(t)+\int_0^\infty V_T(t+s)R(s)ds,

\end{equation}
where $R$ is given by \eqref{e:R}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 ({\cite[Corollary~10.7) of arXiv:2607.18104, '2607.18104'] {DOV:DirectedLandscape}}] There exist constants $c,C>0$ such that the events
    \begin{equation*}
\mathsf{A}_{x,s;y,t}^z:=\left\{|\Lsta(x,s;y,t)| \leq z |t-s|^{1/3} \log^{4/3}\Big(\frac{2(2+\lVert (x,s;y,t)\rVert_2)^{\frac{3}{2}}}{t-s}\Big)\log^{2}(2+\lVert (x,s;y,t)\rVert_2) \right\} 
\end{equation*} satisfy for all  $z>0$
\begin{equation*}
    \P\left(\mathsf{A}_{x,s;y,t}^z \text{ holds for all } (x,s;y,t) \in \R^{4}_{\uparrow} \right) \geq 1 - C\exp\big(- c z^{3/2}\big) .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:relatingmix of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{P}_t$ be a primitive QMS with invariant state $\sigma \in \mathcal{D}_+(\mathcal{M})$. Then there holds
    \begin{align*}
        t_{\rm mix}(\mathcal{L}) \le \left(2 + \log \left(\sigma_{\min}^{-1/2}\right)\right) t_{\rm rel}(\mathcal{L})\,,
    \end{align*}
    where $\sigma_{\min}$ is the minimal eigenvalue of $\sigma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] (formulas stated in \cite{Schmude2014LaplaceOpsSasakiEinstMflds} for
Sasakian-Einstein case) Let $(M^{2n+1},g,\xi )$ be a Sasakian manifold. The Dolbeault Laplacians $\Delta_{\partial _{C}}$ and $
\Delta_{\overline{\partial _{C}}}$ are related by 
\begin{equation}  
\Delta _{\partial _{C}}=\Delta _{\overline{\partial _{C}}}+i\eta\wedge(
\overline{\partial _{C}}^{\ast }+\partial _{C}^{\ast })-i\left( \overline{
\partial _{C}}+\partial _{C}\right) \xi\lrcorner-2iH\mathcal{L}_{\xi }.
\end{equation}
The Hodge Laplacian on $M$ is expressed by the formula 
\begin{equation}  
\Delta=2\Delta _{\overline{\partial _{C}}}-\mathcal{L}_{\xi }^{2}-2iH
\mathcal{L}_{\xi }+2L\Lambda +2H\eta\wedge (\xi\lrcorner)+2i\left( \eta\wedge
\overline{\partial _{C}}^{\ast }-\overline{\partial _{C}}\xi\lrcorner\right).
\end{equation}

