[Definition 7 (\cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] For a graph $F$ with $\chi(F)=r+1\geq 3$, define
	\begin{equation*}
		\partial_cF:=
		\{F-I:I\subseteq V(F)\text{ is independent},\ |I|=a(F),\ \chi(F-I)=r\}.
	\end{equation*}
	If $a(F)=1$, then
	\begin{equation*}
		\partial_cF=\{F-v:v\in V(F),\ \chi(F-v)=r\}.
	\end{equation*}

[Proposition prop:moderate:cold of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] Assume that $\beta= \Omega(1)$, $\log m = o(N^{1/3})$ and $N = o(n^3)$. Then there exist some universal constants $C, c > 0$ such that for every $\epsilon \in (0,1)$,
\begin{align*}
    {\mathbb P}\Big( 
         \mfrac{|\mathcal{E} - \bar \mathcal{E}|}{\beta^2 \log m}  
        \;>\;
        C \Big( \mfrac{\epsilon}{(1-\epsilon) \beta \log m}
            +
            \mfrac{1}{\beta (\log m)^{1/4}} \Big)
    \Big)
    \;\leq\; 
    (1+ \epsilon^{-2}) e^{ - c  \, (\log m)^{3/4} }\;.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:growing-cutoff-range of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:growing-point-cutoff}
Fix \(p\ge3\), \(m\ge2\), \(\varepsilon>0\), \(V\in\mathcal V_m\),
\(f\in\mathcal F_m\) or \(f=\ell_\eta\) for fixed \(\eta>0\),
\(K<\infty\).
For a deterministic sequence \(r_N\) satisfying
\begin{equation}
 N^{-1/2}<r_N\le1,
\end{equation}
define
\begin{align}
 D_{N,r_N}
 &:=\left\{x\in\mathbb S^{N-1}(1):
             \left\lVertx\right\rVert_\infty\le r_N\right\},\\
 \widehat\mathcal O_{N,r_N}
 &:=\left\{(v_1,\ldots,v_n,x)\in\mathbb O(N):
             x\in D_{N,r_N}\right\},\\
 q_N^{\rm gr}&:=\sqrt N\,r_N^{p-1}.
\end{align}
Let
\begin{align}
 \widehat\mathcal Z_{N,r_N}^J(V,\varepsilon,f)
 :=\omega_N\int_{\widehat\mathcal O_{N,r_N}}
 &\exp\biggl\{-NV\bigl(h_J(O)\bigr)
 +\sum_{a=1}^n\log\kappa_\varepsilon\bigl(g_{a,J}(O)\bigr)\notag\\
 &\hspace{31mm}+\operatorname{Tr} f\bigl(A_J(O)\bigr)\biggr\}
 \,\nu_N(\,\mathrm d O),
\end{align}
and put
\[
 \widehat\Phi_{N,r_N}^J(V,\varepsilon,f)
 :=\frac1N\log\mathbb E\widehat\mathcal Z_{N,r_N}^J(V,\varepsilon,f).
\]
Suppose that the independent tensor coordinates \(J_{I,N}\) satisfy
(equation eq:array-assumptions of the paper).  There are constants
\[
 q_\ast=q_\ast(p,m,K,\varepsilon,V,f)>0,
 \qquad
 C=C(p,m,K,\varepsilon,V,f)<\infty,
\]
independent of \(N\) and \(r_N\), such that, whenever
\(q_N^{\rm gr}\le q_\ast\),
\begin{equation}
 \left|
 \log\frac{\mathbb E\widehat\mathcal Z_{N,r_N}^J(V,\varepsilon,f)}
              {\mathbb E\widehat\mathcal Z_{N,r_N}^G(V,\varepsilon,f)}
 \right|
 \le CN(q_N^{\rm gr})^{m-1}.
\end{equation}
Consequently,
\begin{align}
 q_N^{\rm gr}\longrightarrow0
 &\quad\Longrightarrow\quad
 \widehat\Phi_{N,r_N}^J(V,\varepsilon,f)
 -\widehat\Phi_{N,r_N}^G(V,\varepsilon,f)
 \longrightarrow0,\\
 N(q_N^{\rm gr})^{m-1}\longrightarrow0
 &\quad\Longrightarrow\quad
 \frac{\mathbb E\widehat\mathcal Z_{N,r_N}^J(V,\varepsilon,f)}
      {\mathbb E\widehat\mathcal Z_{N,r_N}^G(V,\varepsilon,f)}
 \longrightarrow1.
\end{align}
In the second case the pressure difference is \(o(N^{-1})\).

There are universal constants \(c,C_0>0\) such that
\begin{equation}
 1-\overline\sigma_{N-1}(D_{N,r_N})
 \le C_0N e^{-cNr_N^2}.
\end{equation}
In particular,
\begin{equation}
 cNr_N^2-\log N\longrightarrow+\infty
\end{equation}
implies
\[
 \overline\sigma_{N-1}(D_{N,r_N})\longrightarrow1.
\]
The weaker condition
\begin{equation}
 \sqrt N\,r_N\longrightarrow\infty
\end{equation}
already implies
\begin{equation}
 \frac1N\log\overline\sigma_{N-1}(D_{N,r_N})
 \longrightarrow0.
\end{equation}
If both (equation eq:growing-Haar-zero-cost-condition of the paper) and
\(q_N^{\rm gr}\to0\) hold, then
\begin{align}
 \lim_{N\to\infty}\widehat\Phi_{N,r_N}^J(V,\varepsilon,f)
 ={}&\frac12\log(2\pi e)+\log a_{\varepsilon,p}\notag\\
 &+\sup_{u\in\mathbb R}
 \left\{-\frac{u^2}{2}-V(u)+\ell_{p,f}(u)\right\}.

\end{align}

[Lemma 12 (Matrix exponential I) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Let $K \coloneqq \begin{pmatrix}
        0_{(d-k) \times (d-k)} & I_{(d-k) \times (d-k)} \\ 0_{(d-k) \times (d-k)} & - \gamma  I_{(d-k) \times (d-k)} 
    \end{pmatrix}$ with $\gamma>0$. We then have 
    \begin{align}
        e^{Kt} = \begin{pmatrix}
            I & -\gamma^{-1} e^{-\gamma I t} + \gamma^{-1}I \\ 0 & e^{-\gamma It}
        \end{pmatrix},
    \end{align}
    where the identity matrices above are all $d-k$ dimensional. 
    Furthermore, for any $t\geq 0$ we have the bound 
    \begin{align*}
        \bigl\|e^{Kt}\bigr\|^2_F \leq (d-k) (2+\gamma^{-2}).
    \end{align*}

