[Theorem eq:uncut-dereg-limit of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:dereg-variational}
Let \(V\) be continuous and bounded below.  Then
\begin{align}
 &\lim_{(\varepsilon,\eta)\to(0,0)}
 \left[\frac12\log(2\pi e)+\log a_{\varepsilon,p}
 +\sup_u\left\{-\frac{u^2}{2}-V(u)
 +\ell_{p,\ell_\eta}(u)\right\}\right]\notag\\
 &\hspace{35mm}=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\},

\end{align}
where the limit is joint.  The bounded cutoff approximation also
satisfies
\begin{align}
 &\lim_{R\to\infty}\lim_{\eta\downarrow0}\lim_{\varepsilon\downarrow0}
 \left[\frac12\log(2\pi e)+\log a_{\varepsilon,p}
 +\sup_u\left\{-\frac{u^2}{2}-V(u)+\ell_{p,f_{\eta,R}}(u)\right\}\right]
 \notag\\
 &\hspace{35mm}=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\}.

\end{align}

