body:
[Lemma 3 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] If $\mathcal{M}=\Sb^1_t \times\Sb^1_x$ then for any $m \in (0,1)$
    \begin{equation}
        \ltwo{u} \leq \frac{1}{\nu}\ltwo{(\partial_t^2 -\partial_x^2+m) u},
    \end{equation}
    where $\nu=\frac{1}{2}-\abs{\frac{1}{2}-m}=\inf\{\abs{m-j},\ j \in \ZZ\}$.

[Definition d:eid of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let $(X,\mathcal{X},\mu,\mathcal{E},\mathcal{F})$ be a Dirichlet structure with the associated carr\'e du champ operator $\gamma: \mathcal{F} \times \mathcal{F} \to L^1(\mu)$. We say that the Dirichlet structure  $(X,\mathcal{X},\mu,\mathcal{E},\mathcal{F})$ satisfies the \emph{energy image density property}, if 	 for any $n \in \mathbb{N}$, $f \in \mathcal{F}^n$, we have
		\begin{equation} 
			f_*(\mathds{1}_{\{\det(\gamma(f))>0\}}\cdot \mu) \ll \mathcal{L}_n,
		\end{equation}
		where $\mathcal{L}_n$ is the Lebesgue measure on $\mathbb{R}^n$.

[Theorem thm:mr of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)} to \mbox{\normalfont  (asum:lin1 of the paper)} and \mbox{\normalfont  (asum:lin** of the paper)} 
   to \mbox{\normalfont  (asum:convergence2 of the paper)} hold with  $\bar p\geq \max\{2,\eta/8+1\}(\varepsilon+2)(\eta+1)(\eta+2)/{\varepsilon}\color{black}$, $\varepsilon\in(0,1)$.
		  {Then there is a constant $K$, independent of $n$ and $N$, such that }
		\begin{align*}
			\sup_{i\in\{1,\ldots,N\}}\sup_{ t\in[0,T]}E|x_t^{i,N}-x_t^{i,N,n}|^{2}\leq K n^{-1-\frac{2}{\varepsilon+2}}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop CT UB UT of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For any $t \in (0, \infty)$ and $\lambda \in (0, \infty)$,
  \begin{equation}
    \sup_{\bm{x} \in M^k} \hat{P}_{\bm{x}}\bigl( C_t > \lambda t^{d_{\mathrm{ct}}} \bigr) 
    \leq \tilde{c}_1(t) \exp\! \left(-\tilde{c}_2(t) \lambda^{2/\hat{d}_{\mathrm{s}}^*}\right).
  \end{equation}

[Lemma 31 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $b > 0$,  $\vec{y} \in \weyl_2$, and $f,g \in C([0,b])$, such that $f(b) \ge y_1 > y_2 \ge g(b)$, and $f(t) > g(t)$ for $t\in[0,b]$. For any $\varepsilon > 0$, there exists $\delta > 0$, depending on $\varepsilon, b, y_1, y_2 ,f,g$, such that
\begin{align}
\mathbb{P}_{\mathrm{pin}}^{b,\vec{y}}\left(g(t) - \varepsilon \leq \mathcal{Q}_2(t) \leq \mathcal{Q}_1(t) \leq f(t) + \varepsilon \mbox{ for all }t \in [0,b] \right) &\geq \delta.
\end{align}
Now fix $M>0$ and assume in addition that $f(t) = y_1+m(b-t)$ and $g(t) = y_2+m(b-t)$ for some $m\in\mathbb{R}$ with $|m|\le M$. Then the lower bound $\delta$ in \eqref{Eq.StayInCorridor} may be taken to depend only on $\varepsilon,b,M$.

