body:
[Corollary cor:crossover_weak of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d\ge 1$  and suppose that Assumptions~(ass:Omega of the paper) and~(ass:J of the paper) hold.
Suppose also that $\hat h^{(\mu)} (0)  \ge M^{-1} > 0$ for all $\mu \in \partial \Omega$.
\begin{enumerate}
\item[(i)]
For $d >2$, there exists $R > 0$ such that
\begin{equation} 
S(x) \asymp
	\frac{  \max\{ 1 , m_S  \abs x_S \} ^{ (d-3)/2} } { \abs x_S^{d-2} }
	e^{- m_S  \abs x_S }
	\qquad (\abs x_S \ge R)
\end{equation}
with constants that depend only on $d,M,K_{\mathrm{IR}},\zeta$.
\item[(ii)]
For $d\le 2$ and $s_0 > 0$, there exists $R > 0$ such that
\begin{equation}
S(x) \asymp
	\frac{  1  } { m_S   ^{ (3-d)/2}  \abs x_S^{ (d-1)/2} }
	e^{- m_S  \abs x_S }
	\qquad (\abs x_S \ge R \vee \frac{ s_0 }{ m_S  })
\end{equation}
with constants that depend only on $d,M,K_{\mathrm{IR}},\zeta,s_0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2608.29585, '2608.29585'] Fix $n\ge2$.  For $0\le j\le k$,
\begin{equation}
 D_{k,j}^{(n)}
 =(-1)^{k-j}\{j\}!\{k-j\}!
 \frac{\{n+j+k\}!}
      {\{n+j-1\}!\{n+2j\}}.
\end{equation}
The displayed quotient is a Laurent polynomial.

[Definition 1 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] The closed unit interval of $\mathbb{H}$ is 
\begin{equation}
\mathbb{I}=\left\{ p\in\mathbb{H}\,\,;\,0\le p\le1\right\} .
\end{equation}
See figure \ref{fig-1}.

[Proposition 6 (Euler support reduction) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] Let $\Lambda\in\mathfrak{L}_{\bm{\beta}}$, and let
\[
\varphi_{\Lambda}=\sum_{\bm{\gamma}\in\widetilde{\Lambda}}\bm{x}^{\bm{\gamma}}r_{\Lambda,\bm{\gamma}}(\log\bm{x})\in\mathscr{F}_{\widetilde{\Lambda}}^{\log}.
\]
If $\varphi_{\Lambda}$ is annihilated by the Euler operators $(A\theta_{\bm{x}})_{i}-\beta_{i}$ for $i=1,\dots,d$, then
\begin{equation}

\Supp(\varphi_{\Lambda})\subset\widetilde{\Lambda}\cap A_{\C}^{-1}(\bm{\beta})=\Lambda.
\end{equation}
In particular, $\varphi_{\Lambda}\in\mathscr{F}_{\widetilde{\Lambda}}^{\log}[\Lambda]$.
Moreover, its coefficients satisfy
\begin{equation}

(A\partial_{\bm{y}})_{i}\mathbin{\bullet}_{\bm{y}}r_{\Lambda,\bm{\gamma}}=0\quad(\bm{\gamma}\in\Lambda,\ i=1,\dots,d).
\end{equation}

