[Lemma 15 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(R<\infty\) and \(\varepsilon>0\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_n
  Q_n\left(
    \sup_{\substack{s,t\in[-R,R]\\|s-t|\leq\delta}}
    |Z_n(t)-Z_n(s)|>\varepsilon
  \right)=0.

\end{equation}

[Lemma eq:peierls_argument of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:peierls_argument}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$.

    There exists $c_{\mathrm{pei}} = c_{\mathrm{pei}}(G) > 0$ such that

    \begin{equation}

        \#
        \{
            A \in \mathcal{A} 
            : 
            A \ni x, 
            \# \partial A = m
        \}
        \leq 
        \exp(c_{\mathrm{pei}} m)
    \end{equation}  

    for all $x \in G$ and $m \in \mathbf{N}$.

