body:
[Thm 8 (First-passage time and hop-count limits) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Assume that $\ell\ge2$ and $\go$ is not deterministic. 
\begin{enumeratea}
\item If either $\E\go<\infty$, or Assumption~A.\ref{ass:A2} holds with
$\gc>1/\lc$, then
\begin{align}
    \frac{T_n}{n}
    \stackrel{\pr}{\to}
    \frac{\mu_{\sfT}}{\mu_{\sfP}}.
\end{align}

\item If either $\E\go^2<\infty$, or Assumption~A.\ref{ass:A2} holds with $\gc>2/\lc$ then
\begin{align}
    n^{-1/2}\left(T_n-n\cdot {\mu_{\sfT}}/{\mu_{\sfP}}\right)
    \Longrightarrow
    \N(0,\gs_{\mathrm{FPP}}^2),
\end{align}
where $\gs_{\mathrm{FPP}}^2$ is defined in~\eqref{eq:var-CLT-def}.

\item For the hop-count, we have
\begin{align}
    \frac{H_n}{n} \to \frac{\mu_{\sfH}}{\mu_{\sfP}} \quad \text{a.s.}, 
    \quad \text{and} \quad 
    \frac{\E H_n}{n} \to \frac{\mu_{\sfH}}{\mu_{\sfP}}.
\end{align}
Moreover, the central limit theorem holds:
\begin{align}
    n^{-1/2}\left(H_n-n\cdot {\mu_{\sfH}}/{\mu_{\sfP}}\right) \Longrightarrow \N(0,\gs_{\mathrm{Hop}}^2),
\end{align}
where $\gs_{\mathrm{Hop}}^2$ is defined in~\eqref{eq:hop-var-def}.

\item If either $\E\go^2<\infty$, or Assumption~A.\ref{ass:A2} holds with
$\gc>2/\lc$, then the joint central limit theorem holds:
\begin{align}
   n^{-1/2}
    \begin{pmatrix}
        T_n-n\cdot {\mu_{\sfT}}/{\mu_{\sfP}}\\[2mm]
        H_n-n\cdot {\mu_{\sfH}}/{\mu_{\sfP}}
    \end{pmatrix}
    \Longrightarrow
    \N_2(\mvzero,\Sigma_\ell),
\end{align}
where $\Sigma_\ell$ is defined in~\eqref{eq:joint-cov-def}. Since
$
    \E H_n
    =
    n\cdot {\mu_{\sfH}}/{\mu_{\sfP}}+O(1),
$
the second coordinate in~\eqref{eq:B1-joint-clt} may equivalently be
replaced by $(H_n-\E H_n)/\sqrt n$.\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W^H$ be an fBm of parameter $H\in (0,+\infty)\setminus\N$, $\kappa>0$ and let $u\in L^\infty([0,1];C^\alpha(\T^d))$ with\footnote{Condition $\alpha\geq 0$ in~\eqref{eq:condition_fBm_SWP} is not even needed in~\cite{GalGer2025}, which is set on $\R^d$; we only enforce it in order to avoid technicalities concerning the interpretation one must give to the integral in~\eqref{eq:SDE_fBm:SWP} and the identification of elements of $C^{-\theta}(\T^d)$ with suitable elements of $C^{-\theta}(\R^d)$.}
    \begin{equation}
        \alpha\geq 0, \quad \alpha>1-\frac{1}{2H}.
    \end{equation}
    Then, for any $x\in\T^d$, there exists a strong, pathwise unique solution to the SDE
    \begin{equation}
        X^\kappa_t = x + \int_0^t u(r,X^\kappa_r) \dd r + \kappa W^H_t.
    \end{equation}
    Moreover, the SDE admits a stochastic flow of diffeomorphisms $\{X^\kappa_{s,t}(x,\omega)\}$ on $\T^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:waterfall_LLN_intro of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] Assume that the side lengths of the hexagon, $a,b,c$,
	scale proportionally with a parameter $L\to+\infty$, while
	the $q$-Racah parameters $\kappa$ and $q$ remain fixed.
	Then the fixed-slice correlation kernel
	converges either to zero or the identity operator,
	depending on the scaled location $(\mathsf{t},\mathsf{x})$:\hspace{1pt}\footnote{Here
	and throughout the paper, $\mathbf{1}_A$ stands for the indicator of an event or condition $A$.}
	\begin{equation*}
		\lim_{L\to+\infty}
		K_{\lfloor L\hspace{1pt} \mathsf{t} \rfloor}
		(
		\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta x,
		\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta y)
		=
		\begin{cases}
			\mathbf{1}_{\Delta x=\Delta y}, &\textnormal{if $(\mathsf{t},\mathsf{x})\in \mathcal{W}$};
			\\
			0,&\textnormal{otherwise,}
		\end{cases}
		\quad \textnormal{for all fixed
		$\Delta x,\Delta y\in \mathbb{Z}$}.
	\end{equation*}
	Moreover, the probability of finding a
	horizontal lozenge inside $\mathcal{W}$ or a square or vertical
	lozenge outside $\mathcal{W}$ decays exponentially fast in $L$. (Proof in the paper; no proof environment follows the statement in the TeX.)

