[Pro 5 (\protect{\cite[Propositions B.3 and B.8) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] {Cannarsa_Cheng3}}]
	Let $H:\T^n\times\R^n\to\R$ be a Tonelli Hamiltonian and let $A_t(x,y)$ be the associated fundamental solution. Then the following statements hold.
	\begin{enumerate}[\rm (1)]
		\item For every $R>0$ there exist $t_R>0$ and $K_R>0$, depending on $R$ and on the local $C^2$ modulus and the Tonelli modulus of $H$, such that, for every $0<t\leqslant t_R$ and $y\in\T^n$, the function $x\mapsto A_t(x,y)$ is semiconcave with constant $K_R/t$ on $B(y,Rt)$, understood in local flat coordinates. The threshold $t_R$ is chosen small enough that these balls lie within the injectivity radius.
		\item For every $R>0$ there exist $\tau_0(R)\in(0,1]$ and $K(R)>0$, depending on $R$ and on the local $C^2$ modulus and the Tonelli modulus of $H$, such that for every $t\in(0,\tau_0(R)]$ and $y\in\T^n$ the function $x\mapsto A_t(x,y)$ is of class $C^2$ on the ball $B(y,Rt)$ and satisfies
		\begin{equation}
			D_{xx}A_t(x,y)\geqslant\frac{K(R)}{t}\,I,\qquad\forall x\in B(y,Rt).
		\end{equation}
	\end{enumerate}
	The result for the initial endpoint follows from the corresponding result for the terminal endpoint by using the reversed Lagrangian $\widehat L(x,v)=L(x,-v)$, whose action satisfies $\widehat A_t(y,x)=A_t(x,y)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eqItoProcess of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ an It\^o process, if there exist two $ H $-valued process $ \phi(\cdot) \in L^{1}_{\mathbb{F}}(0,T; H) $ and $ \Phi(\cdot) \in L^{2}_{\mathbb{F}}(0,T; H) $ such that 
    \begin{align}

        X(t)=X(0)+\int_0^t \phi(s) d s+\int_0^t \Phi(s) d W(s), \quad \text { a.s., } \quad \forall \; t \in[0, T].
    \end{align}

[Lem 14 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\Lambda>3$. There exists a constant $c_1>0$ such that, for every $z \in Q_{0,\Lambda r}\setminus Q_{0,3r}$, $\varepsilon>0$, $i\in\{1,\ldots,\varepsilon^{-1}\}$, every $K$ satisfying $L\ge 10K$, where $L=\varepsilon r/4$, and every $C\in\mathcal S_i$,
\begin{align*}
\E\left[Z_{L}^i\ind{ \mathcal C_e(0; \mathcal Q_{z, i}^c)=C}\right]\ge c_1L^2X_{r,i}^{K-\mathrm{line-good}}(C)\bP\left[C_e(0; \mathcal Q_{z, i}^c)=C\right].
\end{align*}

