[Lemma 111 of arXiv:2601.16377, '2601.16377'] With the notation $\hat m= \frac{M}{\N}$, we have the asymptotic expansion as $\N \rightarrow \infty$
\begin{equation*}
\begin{split}
& \log\Bigg(\prod_{1 \leq i < j \leq M} \frac{1}{\N^{2\theta}}\cdot \frac{\Gamma\big(\theta(j - i) + 1\big)\cdot\Gamma\big(\theta(j - i) + \theta\big)}{\Gamma\big(\theta(j - i)\big)\cdot\Gamma\big(\theta(j - i) + 1 - \theta\big)}\Bigg) \\
& = \bigg(\frac{1}{\theta} \int_{0}^{\theta\hat{m}} \int_{0}^{\theta\hat{m}} \log|x - y|\,\dd x\,\dd y\bigg)\N^2 +\theta \hat m \N \log \N \\
& \quad + \hat{m}\log\bigg(\frac{2\pi}{\Gamma(\theta)}\bigg) \N + \frac{1}{6}\bigg(\theta + \frac{1}{\theta} - 3\bigg)\log \N \\
& \quad + \frac{1}{6}\bigg(\theta + \frac{1}{\theta} - 3\bigg)\log \hat{m} + \frac{\log(2\pi)}{2} + \chi_2'(0|\tfrac{1}{\theta},1) + O\bigg(\frac{1}{\N}\bigg),
\end{split}
\end{equation*}
which is uniform for $\hat{m}$ in any compact of $\amsmathbb{R}_{> 0}$.

[Prop propCinfty of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] For every integer $n\geqslant 2$, $0<\alpha<1$,  and $\mathcal{K}>0$, $\rho_0>0$, $0\leqslant c<n-2$ there is $0<\delta<1$ such that the following holds. 

    Let $(X,\mathrm{d},\mathcal{H}^n)$ be an $\mathrm{RCD}(-\eta,n)$ space, with $\eta\geqslant 0$ such that:
    \begin{enumerate}
        \item $\Sigma \subset X$ satisfies (def:Codimension of the paper) with $k=2$ and the choices of $\mathcal{K},\rho_0,c$ above: in particular, $\Sigma$ has codimension greater than $2$. Moreover, $X\setminus\Sigma$ is (locally isometric to) a smooth Riemannian manifold;
        \item $|\mathrm{Ric}| \leqslant \eta$ on $X\setminus \Sigma$.
    \end{enumerate}
    Let $x\in X$, and let $\{f_i\}_{i=1}^n$ be harmonic functions on $B_2(x)$. Set  
    \[ 
    D:=\sum_{i,j} \fint_{B_1(x)} |\nabla f_i \cdot \nabla f_j - \delta_{ij}|\mathrm{d}\mathcal{H}^n.
    \]
    Assume $D+\eta^{1/2}\leqslant \delta$. Then the following hold:
    \begin{enumerate}
        \item The vector-valued function $f:=(f_1,\ldots,f_n):B_{1/2}(x)\to \mathbb R^n$ is a biLipschitz homeomorphism onto its image, and $f(B_{1/2}(x))\subset\mathbb R^n$ is an open set.
        \item Let $g^{ij}:=\nabla f_i\cdot\nabla f_j$. Then
        \[
    g^{ij}\circ f^{-1}
    \]
    (a priori smooth only on $f(B_{1/2}(x)\setminus\Sigma)$), can be extended to a $C^{1,\alpha}$-function on the whole open set $f(B_{1/2}(x))$.
    \end{enumerate}

[Lemma lemma_localized_eigenvector_local_law of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (theorem_localized_eigenvector_localization of the paper), and under the definitions in (equation eq:z1 of the paper) and (equation definition_shift_eigenvector of the paper), the following estimate holds for some constant $C>0$ that does not depend on $\varepsilon$:   \begin{equation}
        \begin{aligned}
            \mathbb{E}\avg{\left({\im G_0}\right){\widetilde{\Lambda}}\left({\im G_1}\right){\widetilde{\Lambda}}}\prec N^{C\varepsilon}N^{-5/3}k^{2/3}\lVert A \rVert_{\text{\rm{HS}}}^2\le N^{-1-2\varepsilon_A+C\varepsilon} ,
        \end{aligned}
    \end{equation}
   where $G_0$ and $G_1$ denote $G_0:=\left({H-z_0}\right)^{-1}$ and $G_1:=\pa{H_{\Lambda}-z_1}$.

