    \begin{equation*}
 \frac{{\widehat\pi}^{(p)}_V(\phi_o = h)}{{\widehat\pi}^{(p)}_V(\phi_o = h-1)}\geq \exp\big[-c\beta h\big] \,. 
    \end{equation*}

