body:
[Corollary downright_path of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For every down-right path $\mathcal{Y} = \{\mathbf y_i\}_{i\in \mathbb{Z}}$, every choice of $\rho_1,\dots,\rho_n \in (0,1)$, and every $t_1,\dots,t_n \in \mathbb{R}$, we have
\begin{subequations} 
\begin{align} 
\mathbb{P}\Big(\bigcap_{i=1}^n \Big\{B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} > t_i\Big\}\Big) 
&\leq \prod_{i=1}^n\mathbb{P}\big( B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} > t_i\big) \\
\text{and} \quad 
\mathbb{P}\Big(\bigcap_{i=1}^n \Big\{B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} < t_i\Big\}\Big) 
&\leq \prod_{i=1}^n\mathbb{P}\big( B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} < t_i\big).
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2604.01852, 'The on/off Brownian snake'] Consider a (possibly countably infinite) collection of independent reflecting Brownian motions $(R^j, j \in J)$ stopped at the local times at zero $(C_j, j \in J)$ on some common probability space $(\Omega, \mathcal{F}, P)$. Let $C=\sum_{j \in J}C_j$ and suppose $C$ is finite. For $j \in J$ let $D^j_h$ be the number of downcrossings from level $h$ to level $0$ for $R^j$. Then we have that
    \begin{equation*}
        \lim_{h \downarrow 0} h \sum_{j \in J} D^j_h = \frac{C}{2} \hspace{0.5cm} \text{a.s.}
    \end{equation*}
    \begin{proof}
        We first note that for $h>0$, $(D^j_h, j \in J)$ form a family of independent Poisson random variables with $D^j_h \sim \text{Poisson}(C_j/2h)$. We recall that the sum of independent Poisson random variables is again a Poisson random variable and so $\sum_{j \in J} D^j_h \sim \text{Poisson}(C/2h)$. The result then follows by the strong law of large numbers for Poisson processes.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Closed blocks of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:closed_blocks}
    Let $b \in \mathbf{N}$ and let $A_0,\ldots,A_{b-1}$ be a $1$-disconnected sequence of $1$-connected sets.

    Then there exists $\ell \leq b$ and $(B_0,\ldots,B_{\ell-1}) \in \mathcal{A}(\ell)$ such that $\cup_{i \leq b} A_i \subset \cup_{j \leq \ell} B_j$ and $\cup_{j \leq \ell} \partial B_j \subset \cup_{i \leq b} \partial A_i$.

