[Lemma lem:RGP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1}\psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta\psi_{t,r,n},
 \\
\psi_{t-1,r+1,n}
&= p^{-1}\psi_{t,r+1,n}
   - q\theta p^{-1}\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1}\phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta\phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= p^{-1}\phi_{t-1,r+1,n}
   - q\theta p^{-1}\phi_{t-1,r+2,n}.

\end{align}

[Cor sig:gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:liningam of the paper)}  hold,
		 then for  $ 0\leq p_0\leq {\bar p}/{(\eta+1)}$
		\begin{align*}
E|(\widehat b)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)|^{p_0}+E|(\widehat\sigma)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)|^{p_0}+\int_Z E|(\widehat\gamma)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}, \bar z\big)|^{p_0} \nu(d\bar z) \leq& K
		\end{align*}
		 for any   $s\in[0,T]$ and $i\in\{1,\ldots,N\}$   where $K>0$ is independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T1 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Suppose that Assumptions (A1 of the paper)--(A2 of the paper) and (A3 of the paper) hold, and that $f_s(x)$ has a lower bound $f_s^{\rm min}$ for all $x\in \mathbb{R}^d$. Let $\Delta := \max_{s \in [S]} (f_s(x^0) - f_s^{\min})$. If we set
\begin{align}
	& \beta =\left( \frac{M K L^2 \left(1+D^2\right)^2\Delta^2}{\sigma^4 T^2} \right)^{1/3}<1,  \quad \gamma=\min\left\{\frac{1}{2L},\frac{1}{L}\sqrt{\frac{\beta KM}{54}}\right\},  \nonumber \\
	&\quad \eta KL
	\le
	c_\eta
	\min\left\{
	\beta,\,
	\frac1{\sqrt K},\,
	\sqrt{\frac{\beta}{M}},\,
	\beta^{3/4}
	\left(
	\frac{L\Delta}{(KM)^{1/2}T}
	\right)^{1/2}
	\right\}, \nonumber
	\end{align}
where \(c_\eta>0\) is a sufficiently small absolute constant, and choose	$B=\left\lceil \frac{K}{T\beta^2}\right\rceil$, then Algorithm (VSOMD of the paper) admits the convergence guarantee
\begin{align*}
\mathbb{E}\left[\mathcal{G}(x_a)\right]&
\lesssim\left(\frac{L\left(1+D^2\right)\sigma\Delta}{KMT}\right)^{\frac{2}{3}}(1+S^2)+\frac{LS^2\Delta}{T} \\
&\quad+
\frac{(1+S^2)G_0^2}{T} +
\frac{(1+S^2)\sigma^2}{KM}
\left(
\frac{MKL^2(1+D^2)^2\Delta^2}{\sigma^4T^2}
\right)^{2/3},
\end{align*}
where  $G_0^2:=\frac{1}{S}\sum_{s\in[S]}\left\|\nabla f_s(x^0)\right\|^2.$
\footnotetext[1]{The notation $\lesssim$ absorbs numerical constants.}
Alternatively, if $B=\Theta(KT)$ and $ \beta = \max\left\{\, \frac{1}{T},\; \left( \frac{M K L^2 \left(1+D^2\right)^2\Delta^2}{\sigma^4 T^2} \right)^{1/3} \right\}$, then Algorithm (VSOMD of the paper) admits the convergence guarantee
\begin{align*}
  \mathbb{E}\left[\mathcal{G}(x_a)\right]&\lesssim \frac{\sigma^2(1+S^2)}{KMT}+\left(\frac{L\left(1+D^2\right)\sigma\Delta}{KMT}\right)^{\frac{2}{3}}(1+S^2)\\&\quad+ \frac{LS^2\Delta}{T}+\frac{(1+S^2)G_0^2}{T} + \frac{(1+S^2)\sigma^2}{KMT^2}.
\end{align*}

[Definition 1 (Lower-buffered quantile) of arXiv:2608.22227, '\fontsize{18pt}{20pt}\selectfont \bf Risk-Sensitive Reinforcement Learning with Smoothed Q'] For \(\beta\in(0,1)\) and \(q\in(0,1]\), define \(\ell_\beta(q)\coloneqq \min\{\beta,q\}.\) For a real-valued random variable \(X\), its lower-buffered \(q\)-quantile is $Q_q^\beta(X)\coloneqq\frac{1}{\ell_\beta(q)}
\int_{q-\ell_\beta(q)}^{q} Q_u(X)\,du$.
For the endpoint cases, we use the conventions \( Q_0^\beta(X) = \inf\operatorname{supp}(X)\) and \( Q_0^\beta(X) =\sup\operatorname{supp}(X)\).

[Prop finite-graph-window-tools of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] The following estimates hold.

\emph{(i) Greedy bounds.} For every fixed $p\geqslant1$, there is $C_p<\infty$ such
that, for all $\ell\geqslant2$ and all integers $r\geqslant0$,
\begin{align}
\left\|
 \mathfrak{a}_\ell
 T_{[0,r+\ell]}(0,[r,r+\ell])
\right\|_p
&\leqslant
C_p\left(\frac r\ell+1\right),
\end{align}
and, for all integers $r\geqslant\ell$,
\begin{align}
\left\|
 \mathfrak{a}_\ell
 T_{[0,r]}(0,r)
\right\|_p
&\leqslant
C_p\left(\frac r\ell+\log\ell+1\right).
\end{align}

\emph{(ii) One-sided short-window mean.} With $h_\ell$ as in
(equation eq:h-ell-def of the paper),
\begin{align}
 \mathfrak{a}_\ell
 \E \Big( T_{[0,\lfloor h_\ell\ell\rfloor+\ell]}
 \left(0,[\lfloor h_\ell\ell\rfloor,\lfloor h_\ell\ell\rfloor+\ell]\right) \Big)
 \leqslant \frac{h_\ell}{\mathsf{v}^\star}+o(h_\ell).
\end{align}

\emph{(iii) Freshness after a stopped window crossing.} Fix $x,H\in\mathds{Z}$ with $H\geqslant1$ and set
\begin{align*}
 I_x:=[x+H,x+H+\ell]\cap\mathds{Z} .
\end{align*}
Let $\pi^\star=\pi^\star(x,I_x)$ be the shortest path from $x$ to $I_x$ strictly inside $[x, x+H+\ell]$, stopped upon its first entrance at a terminal point $Y$. Then, conditionally on $\pi^\star$, its passage time, and $Y=y$,
\begin{align*}
 \bigl\{\go_{\{u,v\}}:\ 1\leqslant |u-v|\leqslant \ell,\ u\geqslant y,\ v\geqslant y\bigr\}
\end{align*}
are fresh, \emph{i.e.,}~conditionally independent and identically distributed as $\mathrm{Exp}(1)^{1/\theta}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Informal statement of \autoref{thm:exponentialconvergence} of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Under additional assumptions imposing a gradient structure and uniform convexity of the drift fields, the nonlinear McKean--Vlasov dynamics admits a unique invariant measure $\mu_\infty$. Moreover, the flow converges exponentially fast:
\begin{align}
{\mathcal W}_1(\mu(t),\mu_\infty)
\le e^{-\kappa t}{\mathcal W}_1(\mu(0),\mu_\infty),
\end{align}
where $\mu(0)$ denotes the law of the initial condition of (equation sistema1 of the paper) and $\kappa>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$, $n\ge 10$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$ with $|v-w|\ge 2n$, 
 	\begin{equation}
 	\begin{split}
  		\mathbb{P}^D\big(v \xleftrightarrow{\ge 0} w \big) \lesssim  \big( \mathrm{dist}(v,D)\land 1 \big)^{\frac{1}{2}}  
  		\cdot |\partial\mathcal{B}_{{v}}(n)|^{-1}  \sum\nolimits_{z\in \partial\mathcal{B}_{{v}}(n)}  \mathbb{P}^D\big( z  \xleftrightarrow{\ge 0} w  \big).
  		 	\end{split}
 	\end{equation}

