[Cor randomhypergraph of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix $r \geq 2$ and let $\bm H_n = (H_n^{(1)}, H_n^{(2)}) \sim \bm H_r(n, p, \rho)$ with parameters $p= p_n \in (0, 1)$ and $\rho = \rho_n \in [0, p(1-p))$. Given $\bm H_n$, suppose the vertices of $\bm H_n$ are colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper) such that (equation eq:p12 of the paper) holds. Then for $p \gg n^{-r}$, we have
    $$ \bm T(\bm H_n) \dto \left(\begin{array}{l}
            Z_1 + Z_{1,2}\\
            Z_2 + Z_{1,2}
            \end{array}\right) , $$
    where $Z_1 \sim \Pois(\lambda - \lambda_{1, 2})$, $Z_2 \sim \Pois(\lambda - \lambda_{1, 2})$, $Z_{1,2} \sim \Pois(\lambda_{1, 2})$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] (weak martingale solutions). Given a probability measure $\mu$ on $\ell_\rho^{2\theta}(\mathbb{Z}^+)$, a weak martingale solution of equation (\ref{INFSDE2}) with initial condition $\mu$ is a triple $(\tilde{X},\tilde{W})$, $(\tilde{\Omega},\tilde{\mathscr{F}},\tilde{\mathbb{P}})$, $\{\tilde{\mathscr{F}}_t\}$, where
    \begin{itemize}
        \item[(i)] $(\tilde{\Omega},\tilde{\mathscr{F}},\tilde{\mathbb{P}})$ is a probability space, and $\{\tilde{\mathscr{F}}_t\}$ is a filtration of sub-$\sigma$-fields of $\tilde{\mathscr{F}}$ satisfying the usual conditions,
        \item[(ii)] $\tilde{W}=\{\tilde{W}(t),\tilde{\mathscr{F}_t};0\leq t\leq \infty\}$ is cylindrical Wiener process on $\ell^{2}(\mathbb{Z}^+)$, $\tilde{X}=\{\tilde{X}(t),\tilde{\mathscr{F}_t};0\leq t\leq \infty\}$ is an adapted process in $\ell_\rho^{2}(\mathbb{Z}^+)$ and 
        \begin{equation*}
             \tilde{X}(\cdot,\tilde{\omega})\in L^{\infty}(0,T;\ell_\rho^{2\theta}(\mathbb{Z}^+))\bigcap C([0,T];\ell_\rho^{2}(\mathbb{Z}^+)) \quad \tilde{\mathbb{P}}-a.s.
        \end{equation*}
        for every $T>0$,
        \item[(iii)] the integral version of (\ref{INFSDE2})
        \begin{equation*}
            \tilde{X}(t)=\tilde{X}(0)+\int_0^tA\tilde{X}(s)+F(\tilde{X}(s))ds+\int_0^tBd\tilde{W}(s), t\in [0,\infty),
        \end{equation*}
        holds $\tilde{\mathbb{P}}$ almost surely in $\ell_\rho^{2}(\mathbb{Z}^+)$,
        \item[(iv)] $\tilde{X}(0)$ has law $\mu$.
    \end{itemize}

[Theorem thm:geo-defect of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] The following two identities describe the two canonical ways shuffle multiplicativity can fail.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.25em]
\item \textup{(Convention defect.)} Let $X$ be a semimartingale and let $\mathbf X^\circ$ denote its forward It\^o{} lift. For all letters $i,j$ for which the displayed quantities are integrable,
\begin{equation}
\inner{\mathrm{Sig}(\mathbf X^\circ)}{i}\inner{\mathrm{Sig}(\mathbf X^\circ)}{j}
-\inner{\mathrm{Sig}(\mathbf X^\circ)}{i\mathbin{\sqcup\!\sqcup} j}=[X^i,X^j]_T,

\end{equation}
the quadratic covariation. Thus the It\^o{} lift agrees with a geometric lift at level two exactly when this bracket term vanishes on the coordinate pair.
\item \textup{(Averaging defect.)} Let $\mathbf X$ be a random weakly geometric lift with square-integrable signature coordinates. For all words $u,v$,
\begin{equation}
\inner{\mathbb{E}\mathrm{Sig}(\mathbf X)}{u}\inner{\mathbb{E}\mathrm{Sig}(\mathbf X)}{v}
-\inner{\mathbb{E}\mathrm{Sig}(\mathbf X)}{u\mathbin{\sqcup\!\sqcup} v}
=-\Cov\left(\inner{\mathrm{Sig}(\mathbf X)}{u},\inner{\mathrm{Sig}(\mathbf X)}{v}\right).

\end{equation}
\end{enumerate}
Both defects are second-order: a bracket for a non-geometric convention, and a covariance for a non-degenerate law. The simultaneous zero-defect regime is the geometric deterministic case.

