body:
[Prop 2 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution of the spatially confined dynamics~\eqref{eq:abc-slow},\eqref{eq:intro-Spat-Cons-Fast} with corresponding initial datum $(Q^i_0,P^i_0)$ for $i=1,2$. 
    Let $(q_t,p_t)\in \R^{2(d-k)}$ with the same initial data $(q_0,p_0)=(Q^2_0,P^2_0)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=0 \in \R^k$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. 
    We have  
\begin{align}
  \mathbb{E} \biggl[\sup_{t\in[0,T]}  \biggl|\begin{pmatrix}
       q_t - Q^{2}_t \\ p_t-P^{2}_t  
    \end{pmatrix} \biggr|^2 \biggr] \leq
    \begin{cases}
    C_3 e^{C_4 T} \Bigl(
          T \bigl|Q_0^{1}\bigr|^2 + \eps T \bigl|P_0^{1}\bigr|^2 + \eps T^2 \Bigr) \ \  &\text{if $\alpha=0$}\\
     C_5 \left( \eps T + |Q^1_0|^2 + \eps |P^1_0|^2 \right) &\text{if $\alpha>0$}. 
    \end{cases}      
\end{align}
For $\alpha>0$ (i.e. $V$ has a quadratic part) we additionally have the uniform-in-time ($L^1$-)estimate 
\begin{align}
\mathbb{E} \biggl[\sup_{t \geq 0}  \biggl|\begin{pmatrix}
       q_t - Q^{2}_t \\ p_t-P^{2}_t  
    \end{pmatrix} \biggr| \biggr] &\leq
    C_6  \Bigl(\sqrt{\eps} + \sqrt{\eps}  \bigl|P_0^{1}\bigr|  +\bigl|Q_0^{1}\bigr|\Bigr).
    \end{align}
The constants $C_3,C_4, C_5, C_6>0$ above are independent of $\eps$ and $T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 10 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $M>0$ and consider $(u,w)\in\mathcal{S}_{M,rad}$. Then
\begin{equation}
	\mathcal{L}(u,u) = \int_{\mathbb{B}_R} \phi(u)\,\rd x - \frac{1}{2} \|\nabla\phi'(u)\|_2^2
\end{equation}
and 
\begin{equation}
	M\langle \phi'(u)\rangle\le 2\mathcal{L}(u,u)+M\phi''(1)\,.
\end{equation}

