[Lemma 10 (Tube does not intersect barrier) of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\gamma_0,\delta_0 >0$ such that the following holds for every $\gamma \leq \gamma_0$ and $\delta \leq \delta_0$.
	Consider $x_0, y\in \cD(\delta/2)$ with $\Vert x_0 - y \Vert \leq (4/5) r_\delta$ and assume that $x_0$ and $y$ are on the same side of every barrier.
	Then, for every $i \geq 0$,
	\begin{align}
		B_i\cap \{z \in \bbR^2: \exists \alpha \in [0,1],\ \Vert  \alpha x_0 + (1-\alpha)y - z \Vert \leq   \gamma r_\delta \} = \emptyset. 
	\end{align}

[Theorem theorem_localized_eigenvalue of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (theorem_localized_eigenvector_localization of the paper), for any constants $\varepsilon>0$ and $\varepsilon_0\in\left({0,2\varepsilon}\right)$, we have that
    \begin{equation}
        \begin{aligned}
            \mathbb{P}\left( \left|\left({\lambda_k-\gamma_k}\right)-\pa{\lambda_k(H)-\gamma_{k}^{{\mathrm{sc}}}}\right| \ge N^{-1+\varepsilon}\left\lVert A \right\rVert_{\text{\rm{HS}}}\right)\le N^{-\varepsilon_0},
        \end{aligned}
    \end{equation}
where $\gamma_k$ and $\gamma_k^{{\mathrm{sc}}}$ denote the $k$-th quantiles of $\rho_N$ and the semicircle law, respectively, as defined in (equation eq:gammak of the paper) below. From (equation eq:local_eigenvalue_perturb of the paper), there exists a constant $c>0$ depending on ${\varepsilon}_A$ such that the following estimate holds:
\begin{equation}
    \begin{aligned}
        \mathbb{P}\left( \left|\left({\lambda_k-\gamma_k}\right)-\pa{\lambda_k(H)-\gamma_{k}^{\text{\rm{sc}}}}\right| \ge N^{-2/3-c}{\mathfrak{r}}\left({k}\right)^{-1/3}\right)\le N^{-c}.
    \end{aligned}
\end{equation}
As a consequence of (equation eq:main_perurb of the paper), for any $k\in [\![{1,DN}]\!]$ such that (equation eq:condA2 of the paper) holds, and for any fixed $n\in \mathbb{N}$ and smooth, compactly supported test function $O \in C_c^{\infty}\left(\mathbb{R}^n\right)$, there exists a constant $c>0$ depending on ${\varepsilon}_A$ such that
\begin{equation*}
    \begin{aligned}
        &\left|	\int_{\mathbb{R}^n} \mathrm{~d} \boldsymbol{\alpha}\; O(\boldsymbol{\alpha}) p_{H_{\Lambda}}^{(n)}\left(\gamma_k+\frac{\alpha_1}{\left({DN}\right)^{2/3}{\mathfrak{r}}\left({k}\right)^{1/3}  }, \ldots, \gamma_k+\frac{\alpha_n}{\left({DN}\right)^{2/3}{\mathfrak{r}}\left({k}\right)^{1/3}  }\right)\right.\\
        &\left.-\int_{\mathbb{R}^n} \mathrm{~d} \boldsymbol{\alpha}\; O(\boldsymbol{\alpha})p_{H}^{(n)}\left(\gamma_k^{\text{\rm{sc}}}+\frac{\alpha_1}{\left({DN}\right)^{2/3}{\mathfrak{r}}\left({k}\right)^{1/3}  }, \ldots, \gamma_k^{\text{\rm{sc}}}+\frac{\alpha_n}{\left({DN}\right)^{2/3}{\mathfrak{r}}\left({k}\right)^{1/3}  }\right)   \right|\le N^{-c},
    \end{aligned}
\end{equation*}
where $\boldsymbol{\alpha}$ denotes $\boldsymbol{\alpha}=\left(\alpha_1, \ldots, \alpha_n\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_1 of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] For every $\delta,\epsilon\in(0,1)$, there exists a weak martingale solutions to  (equation Eq_approx of the paper) with initial data $(u_0,\psi_0)$, which satisfies
	\begin{equation}
		\frac{1}{2}\int_{\mathbb{T}^3}|u_{\delta,\epsilon}(t)|^2 +|\psi_{\delta,\epsilon}(t)|^2 \,\mathrm{d} x \,+\, \epsilon \int_0^t \int_{\mathbb{T}^3} 
		|\Delta u_{\delta,\epsilon}  |^2 +
		|\Delta\psi_{\delta,\epsilon} |^2\,\mathrm{d} x \,\mathrm{d} s
		\,\leq\, \frac{1}{2}\int_{\mathbb{T}^3}|u_0|^2 +|\psi_0|^2 \,\mathrm{d} x\,+\,\epsilon t,
	\end{equation}
	for all $ t\in [0,T]$, $\mathbb{P}$-almost surely.

