[Definition 83 (Curvature tensors of $\gfour$ and $\gnulltori$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The \emph{Riemann curvature tensor} $\Riemfour$ of the spacetime metric $\gfour$ is the type $\binom{0}{4}$ spacetime tensorfield 
defined by:
\begin{align} 
\Riemfour(\mathbf{X},\mathbf{Y},\mathbf{Z},\mathbf{W}) 
& \eqdef \gfour(- \Dfour^2_{\mathbf{X} \mathbf{Y}} \mathbf{Z} 
+ 
\Dfour^2_{\mathbf{Y} \mathbf{X}} \mathbf{Z}, \mathbf{W}),
\end{align}
where $\mathbf{X},\mathbf{Y},\mathbf{Z},\mathbf{W}$ are arbitrary spacetime vectorfields, and
$\Dfour^2_{\mathbf{X} \mathbf{Y}} \mathbf{Z} 
\eqdef 
\mathbf{X}^{\alpha} \mathbf{Y}^\beta \Dfour_\alpha \Dfour_\beta \mathbf{Z}$. 

The \emph{Ricci curvature tensor} $\Ricfour$ of the spacetime metric $\gfour$ is the type $\binom{0}{2}$ spacetime tensor defined 
relative to arbitrary coordinates as follows: 
\begin{align} 
\Ricfour_{\alpha \beta} 
& \eqdef 
(\gfour^{-1})^{\kappa \lambda} \Riemfour_{\alpha \kappa \beta \lambda}.
\end{align}Similarly, the Riemann curvature tensor $\Riemnulltori$ of the Riemannian metric $\gnulltori$ on 
$\doublenulltoritwoarg{\ubar}{u}$ is the type $\binom{0}{4}$ $\doublenulltoritwoarg{\ubar}{u}$ tensorfield defined 
as follows: 
\begin{align} 
\Riemnulltori(X,Y,Z,W) 
& \eqdef \gnulltori(- \nullangD^2_{XY}Z + \nullangD^2_{YX}Z,W),
\end{align}
where $X,Y,Z,W$ are arbitrary $\doublenulltoritwoarg{\ubar}{u}$-tangent vectorfields, $\nullangD$ is the Levi-Civita connection of $\gnulltori$, and $\nullangD_{XY}^2 Z= X^\alpha Y^\beta \nullangD_\alpha \nullangD_\beta Z$.

The \emph{Ricci curvature tensor} $\Ricnulltori$ of $\gnulltori$ is the type $\binom{0}{2}$ spacetime tensor defined 
relative to arbitrary coordinates as follows: 
\begin{align} 
\Ricnulltori_{\alpha \beta} 
& \eqdef 
(\gnulltori^{-1})^{\kappa \lambda} \Riemnulltori_{\alpha \kappa \beta \lambda}.
\end{align}The \emph{scalar curvature} $\Scalarnulltori$ of $\gnulltori$ 
is the scalar function defined 
relative to arbitrary coordinates as follows: 
\begin{align} 
\Scalarnulltori
& \eqdef 
(\gnulltori^{-1})^{\alpha \beta} \Ricnulltori_{\alpha \beta}.
\end{align}

[Definition 1 of arXiv:2511.00764, 'Further Developments on Stochastic Dominance for Convex\\ Combinations of Infinite-Mean Ra'] {\rm \citep{Vin25}}\ \ Let $F$ be a non-degenerate distribution function with $F(0-)=0$. $F$ is said to be completely subscalable if the inequality
\begin{equation}

      \th\, \Fbar(x) \le \Fbar\(\frac {x}{\th}\)
\end{equation}
holds for all $x\in\R_+$ and all $\th\in (0,1)$. Denote by ${\mathcal V}$ the class of all completely subscalable  distribution functions.

[Corollary 14 of arXiv:2604.12334, 'On additive averaging kernels for finite Markov chains'] For any subset $S \in \mathcal{D}$ and $P \in \mathcal{L}(\pi)$, 
    \begin{align*}
        \|A_\alpha(S) - \Pi\|_{F,\pi}^2 &= \alpha^2\Tr(P^2) - 2\alpha(1-\alpha)g(S) + 1 - 2\alpha^2\\
         = &\underbrace{2\alpha(1-\alpha) \left(\dfrac{1}{\pi(S)} \sum_{x,y \in S'} \pi(x) P(x,y) + \dfrac{1}{\pi(S')} \sum_{x,y \in S} \pi(x) P(x,y)\right)}_{\text{supermodular}}\\
         &-\underbrace{\left(\dfrac{2\alpha(1-\alpha)}{\pi(S)\pi(S')} + 6\alpha^2 - 4\alpha - 1 - \alpha^2\Tr(P^2)\right).}_{\text{supermodular}}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:connection_under_truncation of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Assume all the conditions of Proposition (prop:non_neg_conn_prob_randomvertices of the paper) and the uniform boundedness assumption (equation assump:unif_bdd_degs of the paper). With $o_1$ and $o_2$ as before random vertices from $\mathcal N^{(s_0)}$, we have
    \begin{align*}
        \liminf_{n \to \infty}\Prob{o_1\stackrel{\mathbb G_n}{\longleftrightarrow}o_2}>0.\addtocounter{equation}{1}\tag{\theequation} 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lemlwp1 of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $\alpha \in (1,5-2b),\, 0<b\leq 1/4$ and $p_{0}$  be as follows 
     \begin{gather*}
2>p_{0}>\begin{cases}
\vspace{0.2cm}
\max \left( \frac{\alpha+1}{\alpha}, \frac{4\alpha}{9-4b} \right) &\text{if} \quad \alpha \in  (1,3) \\ 
\vspace{0.2cm}
\max \left( \frac{2(\alpha-1)}{\alpha}, \frac{2\alpha}{5-2b} \right) \quad  & \text{if} \quad \alpha\in [3,5-2b).
\end{cases}
    \end{gather*}
    Then
    \begin{align*}
   \inf_{(\gamma,\rho)\in \mathcal{A}}\| ~|x|^{-b}|u|^{\alpha-1}v\|_{L^{\gamma'}_{T}L^{\rho '}}
   &\lesssim \|u\|_{X(T)}^{\alpha-1}\|v\|_{X(T)}
   \left(
     T^{1-\frac{\alpha-1}{2p_{0}}-\frac{1}{2}\left(\frac{1}{p_{0}}-\frac{1}{2}\right)} 
     + T^{1-\frac{\alpha-1}{2p_{0}}-\frac{1}{2}\left(\frac{1}{p_{0}}-\frac{1}{2}\right)-\frac{1}{\nu}}
\right).
\end{align*}

