body:
[Theorem t:suboptimal_Lq_finite_time of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix $r\in (1,\infty)$ and an interval $I=(0,T)$ for some $T<\infty$. Let $p,q\in (2,\infty)$ be such that the Sobolev index $\mathtt{Sob}\stackrel{{\rm def}}{=}1-\frac{2}{p}-\frac{d}{q}$ satisfies
\begin{equation}

-\frac{d}{2}\leq \mathtt{Sob} <0, \qquad \text{ and }\qquad p<\frac{d}{-\mathtt{Sob}},
\end{equation}
Moreover, set $q_{{\rm max}}\stackrel{{\rm def}}{=}-\frac{d^2}{d-2}\frac{1}{\mathtt{Sob}}$, 
with the convention $q_{{\rm max}}=\infty$ if $d=2$.
Then for all $p_0\in (2,\infty)$ and $q_0\in (2,q_{{\rm max}})$ satisfying 
\begin{equation}

-\frac{2}{p_0}-\frac{d}{q_0}<\mathtt{Sob},
\end{equation}
there exists a constant $C_0$ such that, for all $N\geq 1$, 
\begin{equation}

w_0\in L^r_{{\mathscr F}_0}(\Omega;\mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^d))\qquad \text{ and }\qquad F\in L^r_{\mathscr{P}}(\Omega;L^p(I ;L^q(\mathbb{T}^d;{\mathbb R}^{d\times d}))),
\end{equation}
the unique energy solution $w^N$ to the oscillating stochastic Stokes system (equation eq:turbulent_Stokes_scaling_uniform_estimates of the paper) provided by Lemma (l:global_energy_estimate of the paper) satisfies
\begin{align}

\big({\mathbf E}\|w^N\|_{L^{p_0}(I;L^{q_0} (\mathbb{T}^d))}^{r} \big)^{1/r}
&\leq C_0 \big({\mathbf E}\|w_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^d)}^r\big)^{1/r}\\
\nonumber
& + C_0  \big({\mathbf E}\|F\|_{L^p(I;L^q(\mathbb{T}^d))}^r\big)^{1/r}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $K\subset\R^{d}$ be a nonempty compact convex set and let $v\in \R^d$, $v\neq0$. Let $\pi$ be the orthogonal projection onto $v^{\perp}$. Then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K\cup\{-v\})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}} .
\end{equation}
 If additionally $0\notin\partial K$ and $0\notin\partial_{v^{\perp}}(\pi K)$, where the latter boundary is taken in $v^{\perp}$, then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K_{+}\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K_{-}\cup\{-v \})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}},
\end{equation}
whenever $K_{+}$ and $K_{-}$ are nonempty compact convex sets in $\R^d$
whose Hausdorff distance to $K$ is smaller than $\eps$, where $\eps>0$ is a sufficiently small number  depending only on $K$ and $v/\|v\|$.

[Lemma L:ZPL of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] For $F \in {{\mathcal F}_W}$ and $y \in {\mathcal Z}$, 
\begin{equation} 
 P_L( F \cap \{Z_S=y\}) 
  =  {\mathbb E} \Big(  \frac{ 1_F L_y}{X} \Big | X\ge 1 \Big), 
\end{equation}
and 
\begin{equation} 
  P_L( F | Z_S=y) 
  = \frac{ {\mathbb E}\big(  { 1_F L_y}{X^{-1}} \Big | X\ge 1 \big) }
      {  {\mathbb E}\big(  { L_y}{X^{-1}} \Big | X\ge 1  \big) }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 23 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $K$ be a compact smooth manifold of dimension $k$ and let $\cR \subset W$ be a codimension $n$ Fredholm $C^1$-rectifiable subset of a Banach space $W$. If $k < n$, then the exceptional locus
  \begin{equation*}
    \cE_K (\cR) \coloneq \{ f \in C^1(K, W) \, | \, f(K) \cap \cR \neq \emptyset \}
  \end{equation*}
  is Fredholm $C^1$ rectifiable of codimension $n-k$ in $C^1(K, W)$.

