[Thm jointr of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \ge 2$. Let $\bm H_n =(H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same vertex set $V_n$ with $|E(H_n^{(1)})| \to \infty$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold:
    \begin{itemize}
      \item  There exists constants $\lambda_1, \lambda_2, \lambda_{1,2} \ge 0$ with $\lambda_1 \ge \lambda_{1,2}, \lambda_2 \ge \lambda_{1,2}$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r-1}} \to \lambda_2, \text{ and } \frac{|E(H_n^{(1, 2)})|}{c_n^{r-1}} \to \lambda_{1,2}. 
            \end{align}


      \item  For all $t \in [2, r - 1]$
      \begin{align}
      \frac{|\cK(t, H_n^{(1)})|}{c_n^{2r-t-1}} \to 0 \text{ and } \frac{|\cK(t, H_n^{(2)})|}{c_n^{2r-t-1}} \to 0 , 
      \end{align}
     where $\cK(t, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
$$\begin{pmatrix}
    T(H_n^{(1)}\setminus H_n^{(2)})\\
    T(H_n^{(2)}\setminus H_n^{(1)})\\
    T(H_n^{(1, 2)})
\end{pmatrix} \dto \begin{pmatrix}
        Z_1 \\
        Z_2 \\
        Z_{1,2}
        \end{pmatrix} , $$
  where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2})$, $Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2})$, and $Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:q_toll_bound of arXiv:2609.02491, 'Generalised Random Parking for Trapeziums on a Strip'] There exists a finite constant $C>0$ such that, for all sufficiently large $x$,
\begin{equation}
\max_{s\in\{\mathcal{P},\mathcal{T}\}}|q_s(x)| \le C\mathcal R_2(x), \quad \text{where}\quad \mathcal R_2(x) \coloneqq
\begin{dcases}
    \mleft(\dfrac{4e}{x/a}\mright)^{x/a-4},
    &\text{if }a=b,\\
    \mleft(\dfrac{4e}{x/a}\mright)^{x/a-(5+(a+b)/(2a))},
    &\text{if }a>b.
\end{dcases}
\end{equation}

[Lemma 11 of arXiv:2608.29075, 'The 2-Monoidal Structure of Symmetric Sequences'] [\cite{Operads_2013_Hess}] 
Under the equivalence of Lemma \ref{equivalence},
\begin{enumerate}[1)]
    \item the left Kan extension of $\Phi \times \Psi$ along the fibered product functor 
    \begin{align*}
    \catname{Cospan} &\rightarrow \catname{A}^{\op} \\
    \left(T \xrightarrow{f} S, T' \xrightarrow{f'} S\right) &\mapsto \left(T \times_{S}T' \xrightarrow{f\times_{S} f'} S\right)
    \end{align*}
    corresponds to the matrix monoidal product of symmetric sequences,
    \item the left Kan extension of $\Phi \times \Psi$ along the composition functor \begin{align*}
    \catname{Comp} &\rightarrow \catname{A}^{\op} \\ \left(S\xrightarrow{f} R, T \xrightarrow{g} S\right) &\mapsto \left(T \xrightarrow{gf} R\right)
    \end{align*}
    corresponds to the composition product of symmetric sequences, and
    \item the unit for the external product of functors is $\Gamma: \catname{A}^{\op} \rightarrow \C$ specified by $\Gamma(f) = \textbf{1}$ if $f$ is a bijection and $\Gamma(f) = \varnothing$ otherwise.
\end{enumerate}

[Thm intro_existence of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] For any $x\in\Delta$, we have that 
\begin{itemize}
    \item[(i)] There exists a strong solution to (equation eq:AMTG of the paper) starting from position $x$ at time $t$;
    \item[(ii)] $(M_s)_{s \in [t,1]}$ is a win-martingale. 
\end{itemize}
Furthermore, the Aldous martingale (equation eq:AMTG of the paper) is the unique (in law) optimizer of (equation eq:optimal of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn eq:-16 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] The dynamics ((eq:-14 of the paper)) is called \emph{correlated diagonal}
if there exists a functional
\[
L(s,w)=(L^{(1)}(s^{(1)},w^{(n)}),\dots,L^{(n)}(s^{(n)},w^{(n)}))
\]
and a correlation matrix $\rho\rho^{\text{T}}$ such that
\begin{equation}
H_{0}^{(j)}(s,x)=L^{(j)}\Big(s_{j},\sum_{r=1}^{n}\rho_{jr}x^{(r)}\Big),\;1\le j\le n.
\end{equation}

[Definition 8 (Damped Brownian snake) of arXiv:2604.01852, 'The on/off Brownian snake'] We construct the \emph{damped Brownian snake} from the on/off Brownian snake $\sum_{i \in I} \delta_{((b_i,s_i), f^i, x^i)}$ given in Definition \ref{definition oo snake} on the probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. Recall, for $i \in I$, $x^i=(w^i, v^i)$ where $w^i$ is the Brownian motion component and $v^i$ is the subordinator component. Let $\Tilde{I} \coloneqq \{ i \in I: s_i = 0\}$. For $i \in \Tilde{I}$, for $r \in [0,\sigma(f^i)]$, we define a path-valued process $\Tilde{v}_r^i$ to be the indicator function for whether a dormancy has occurred. Specifically, we set $\Tilde{v}_r^i(0)=0$ and for $s>0$ we set $\Tilde{v}_r^i(s) = 1$ if there exists $u \in (0,s]$ such that $v_r^i(u) >v^i_r(u-)$ (i.e., if there is a jump in the subordinator $v_r^i$ at time $s$ or earlier) and we set $\Tilde{v}_r^i(s)=0$ otherwise.  Also, for $i \in \Tilde{I}$, $r \in [0,\sigma(f^i)]$ let $t^i$ be the unit drift deterministic process defined by $t^i_r(s)=s$ for all $s \geq 0$. We then call 
    \begin{equation*}
        \sum_{i \in \Tilde{I}} \delta_{(b^i, f^i, (w^i, t^i, \Tilde{v}^i))}
    \end{equation*}
    the \emph{damped Brownian snake}.

[Prop 10 of arXiv:2606.08115, '2606.08115'] For every $\ov{z} \in K$ the following inequalities hold
\begin{equation}

|M\ov{z}| \ge \frac{|\ov{z}|}{\|M^{-1}\|};
\end{equation}
\begin{equation}

\mathrm{dist}\left(\ov{z}, \partial K\right) \le \|M^{-1}\| \mathrm{dist}\left(M\ov{z}, \partial MK\right).
\end{equation}

