[Prop tv-general of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $K$ be a Markov kernel on $(0,\infty)$
with transition density $q( \cdot |s)$ with respect to Lebesgue
measure, and let $\pi$ be an invariant probability measure for $K$.
Suppose that:
\begin{enumerate}
\item There exists $L<\infty$ such that 
\begin{equation}
\int^{\infty}_{0}\bigl|q(t|a)-q(t|b)\bigr| dt\le L |a-b|,\qquad a,b>0;
\end{equation}
\item There exists a coupling $(X_{n},Y_{n})_{n\ge0}$ of two copies of
the chain, with 
\[
X_{0}=x,\qquad Y_{0}\sim\pi,
\]
such that for some $r\in(0,1)$, 
\begin{equation}
\mathbb{E}\!\left[ |X_{n+1}-Y_{n+1}| \, \mid  \, X_{n},Y_{n}\right]\le r |X_{n}-Y_{n}|\qquad\text{a.s. for all }n\ge0.
\end{equation}
Then for every $n\ge1$, 
\begin{equation}
d_{\mathrm{TV}}\!\bigl(K^{n}(x,\cdot),\pi\bigr)\le\frac{L}{2} r^{ n-1} \mathbb{E}|x-Y_{0}|.
\end{equation}
In particular, the chain is geometrically ergodic in total variation.
\end{enumerate}

[Lemma lem:dgt4-origin-frozen of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume that $d\geq5$ and that the scenery is i.i.d., atomless, centered,
	and of finite positive variance. For every $n\geq0$:
	\begin{equation}
	\begin{aligned}
		\{u_{n+1}(0)=0\}
		&=\{-\zeta(0)>Pw_n(0)\},\\
		(-\zeta(0)-Pu_n(0))_+
		&=(-\zeta(0)-Pw_n(0))_+,\\
		\mathbb{E} u_{n+1}(0)-\mathbb{E} u_n(0)
		&=\mathbb{E}(-\zeta(0)-Pw_n(0))_+\, .
	\end{aligned}
	\end{equation}
	If $\mathbb{E}|\zeta(0)|^p<\infty$ for some $p\geq2$, then
	\begin{equation}
	\begin{aligned}
		\frac{G(0,0)\mathbb{E} Pw_n(0)}{\mathbb{E} u_n(0)}
		&\longrightarrow1,\\
		\sup_{n\geq0}\mathbb{E}|Pw_n(0)-\mathbb{E} Pw_n(0)|^p
		&<\infty\, .
	\end{aligned}
	\end{equation}
	If, in addition, $\mathbb{E} e^{\theta_0|\zeta(0)|}<\infty$ for some
	$\theta_0>0$, then, for every
	\[
		0<\lambda<
		\frac{\theta_0}{
		\displaystyle\sup_{z\ne0}G(0,z)/G(0,0)},
	\]
	there is $C(\lambda)<\infty$ such that for every $n,r\geq0$,
	\begin{equation}
		\mathbb{P}\left(
		Pw_n(0)-\mathbb{E} Pw_n(0)\leq-r
		\right)
		\leq C(\lambda)e^{-\lambda r}\, .
	\end{equation}

[Lemma lem:sa of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] The stochastic process $\boldsymbol{\Gamma}_n$ satisfy the recursion
\begin{align}
    \boldsymbol{\Gamma}_{n+1} = \boldsymbol{\Gamma}_{n} + \frac{\boldsymbol{h}_p(\boldsymbol{\Gamma}_{n}) + \boldsymbol{e}_{n+1}}{n+1}, 
    \quad n \geq 2,
\end{align}
where $\boldsymbol{e}_{n+1}$ is a martingale-difference w.r.t.\ the filtration $\mathcal{\boldsymbol{G}}_{n} = \sigma\{\boldsymbol{\Gamma}_1, \ldots, \boldsymbol{\Gamma}_n\}$ and $\boldsymbol{h}_p : [0,1]^2 \to [0,1]^2$ is the following quadratic function
\begin{align*}
    \boldsymbol{h}_p\left(\boldsymbol{x}\right) := \begin{pmatrix}
        \left((1-p)x_1 + px_2 - 1\right)^2 - (1-x_1-x_2)^2 - x_1\\\left((1-p)x_2 + px_1 - 1\right)^2 - (1-x_1-x_2)^2 - x_2
    \end{pmatrix}.
\end{align*}
In other words, $\boldsymbol{\Gamma}_n$ is a stochastic approximation process with drift $\boldsymbol{h}_p$, random noise $\boldsymbol{e}_{n+1}$ and step-size ${1}/{(n+1)}$. For some constant $C > 0$, 
we also have, almost surely, \begin{align}\mathbb{E}\left(\|\boldsymbol{h}_p(\boldsymbol{\Gamma}_n) + \boldsymbol{e}_{n+1}\|^2 \mid \mathcal{\boldsymbol{G}}_{n}\right) \leq C(1 + \|\boldsymbol{\Gamma}_n\|^2).\end{align}
Additionally, $\boldsymbol{e}_{n+1}$ satisfies the following Lindeberg condition 
    \begin{align}
    \frac{1}{n}\sum_{k=2}^{n}\mathbb{E}\left( \|\boldsymbol{e}_{k+1}\|^2 \mathbf{1}\left\{\|\boldsymbol{e}_{k+1}\| \geq \delta\sqrt{n}\right\}\mid \mathcal{\boldsymbol{G}}_{k}\right) \stackrel{a.s.}{\to} 0, \quad \delta > 0.
    \end{align} 
    Moreover, for all $\epsilon > 0$ such that, almost surely, 
    \begin{align}
        \sup_{n \geq 2} \mathbb{E}\left( \|\boldsymbol{e}_{n+1}\|^{2+\epsilon} \mid \mathcal{\boldsymbol{G}}_{n}\right) < \infty.
\end{align}

