body:
[Definition eq:entropy of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Define the \emph{entropy}\index{entropy} of $\mathsf{acc}$ as:
	\begin{align}
	\varphi_\mathsf{acc}(p):=\mathrm{Exp}_p\mathsf{acc}(p)=p\mathsf{acc}_1(p)+(1-p)\mathsf{acc}_0(p)
	\end{align}

[Lemma lem:cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $\lambda$ be a nonnegative progressively measurable process, and denote $\Lambda_t \coloneqq \int_0^t \lambda_s \,ds$. Suppose that $\Lambda_t < \infty$ for all $t \geq 0$ and $\Lambda_\infty = \infty$, $\mathbb{P}$-a.s. Moreover, suppose that $\Omega$ supports an $\operatorname{Exp}(1)$ random variable $E$ which is independent of $\mathcal{F}_\infty$. Define the random time
	\begin{equation*}
		\tau \coloneqq \inf\{t > 0: \Lambda_t \geq E\},
	\end{equation*}
	and define the filtration $\mathbb{A} = (\mathcal{A}_t)_{t \geq 0}$ by $\mathcal{A}_t \coloneqq \sigma(\{\tau \leq s\}; s \leq t)$. Let $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown \mathbb{A}$. Then, the process $(\bm{1}_{\{\tau \leq t\}} - \Lambda_{\tau \land t})_{t \geq 0}$ is a $\mathbb{G}$-martingale, and we have $\mathbb{F} \hookrightarrow \mathbb{G}$.

[Lem surftype of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\lambda$ be a connected surface (i.e., $2$-manifold), possibly non-compact and possibly with boundary. Then at least one of the following holds:
    \begin{enumerate}
        \item $\pi_1(\lambda)$ remains nontrivial after capping off all the closed boundary components of $\lambda$.
        \item $\lambda$ is a compact genus 0 surface.
        \item $\lambda$ becomes homeomorphic to $\mathbb{R}^2$ after filling the closed boundary components with disks and deleting the open boundary components. In that case, $\pi_1(\lambda)$ is freely generated by its closed boundary components.
    \end{enumerate}

[Definition solution definition (u P) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\tau^*$ be a stopping time with $\mathbb P(\tau^*>0)=1$, and let $(u,\tau^*) \triangleq (u(t))_{t\in [0,\tau^*)}$ be a progressively measurable process on $H_{\rm div}^s$.
		The pair $(u,\tau^*)$ is called a maximal $H_{\rm div}^s$ classical solution to (equation Target problem (u P) damp of the paper) if ${\mathbb P}\text{-}{\rm a.s.}$ the following conditions are satisfied:
		\begin{itemize}
			\item (equation Target problem (u P) damp of the paper) holds as an equality in $C(\mathbb K^d)$ for all $t\in[0,\tau^*)$;
			\item  $\sup_{[0,T]}\|u(t)\|_{H^s}<\infty$ for all $T<\tau^*$;
			\item $\limsup_{t\uparrow\tau^*}\|u(t)\|_{\mathbb H^s}=\infty$ a.s. on $\{\tau^*<\infty\}.$
		\end{itemize}
		In particular, if $\mathbb P(\tau^*=\infty)=1$, the solution is called global.

[Definition 10 (Finite directional coefficient module) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] The \emph{directional relation submodule} is
\[
U_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
U_{\Lambda}^{\mathrm{Eul}}
+
U_{\Lambda}^{\mathrm{tr}}
+
U_{\Lambda,\bm{w}}^{\mathrm{van}}
\subset
F_{\Lambda},
\]
and the \emph{finite directional coefficient module} is
\begin{equation}

M_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
F_{\Lambda}/U_{\Lambda,\bm{w}}^{\mathrm{dir}}.
\end{equation}

[Proposition prop:concentration3 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] There exists  $0<C_\star<C_2$ such that if $t\in [0,1)$  and $x\in \mathbb{R}^d$ satisfy \begin{equation}
1-t^2\leq C_\star^{-1}\log(\epsilon^{-1})^{-C_\star} \text{ and } \|tx\|^2\leq 1-C_2^{-1}\log(\epsilon^{-1}+1)^{-K},
\end{equation}
then for all $l\in \{1,...,\lfloor \beta \rfloor\}$ we have
    $$\int \|f^l(y)-f^l(tx)\|^2dp^{t,x}(y)\leq C\log(\epsilon^{-1})^{C_3}(1-t^2)^{\beta-\lfloor \beta \rfloor }\log((1-t^2)^{-1})^{-2\theta}.$$

