\end{cases}
\end{equation}
At a jump of $N$, the signature is right-multiplied by $\exp_{\otimes}(e_1)$, so
\begin{equation}
S_w(t)=\sum_{k=0}^{\rho(w)}\frac{1}{k!}S_{w^{[-k]}}(t-).

\end{equation}

[Thm clt:Randic of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For all $m\ge 2$ and all $\alpha\in \mathbb{R}$ we have
    \begin{align*}
        \,{\mathbb{E}}\left[R_n^{[\alpha]}\right]&=\frac{m-1}{m^{2\alpha}}n^{2\alpha}+\frac{1}{m^\alpha}n^{\alpha+1}\\
        &\quad +\left(\frac{2\alpha(m-1)}{m^\alpha}+(m-1)\frac{2\alpha+\alpha(\alpha-1)}{2m^\alpha}\right)n^\alpha+o(n^\delta)
    \end{align*}
    with $\delta=\max\{2\alpha,\alpha\}$.\\
    For $m=2$ and $(N_1,N_2)$ defined in (equation N_i of the paper) we have for all $\alpha \in \mathbb{R}$
    \begin{align*}
        \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^\alpha} \overset{d}{\longrightarrow} \frac{(2\alpha+\alpha(\alpha-1))}{2^\alpha}\left(N_1^2+N_2^2-\frac{1}{2}\right).
    \end{align*}
    Let $m \ge 3$.
    \begin{enumerate}
    \item[(i)] For $\alpha > \frac{1}{2}$ it holds that
    \begin{align*}
       \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^{2\alpha-1/2}} \overset{d}{\longrightarrow} 

       \mathcal{N}\left(0,\frac{2\alpha^2(m-2)}{m^{4\alpha}}\right).
    \end{align*}
    \item[(ii)] For $\alpha < \frac{1}{2}$ it holds that
    \begin{align*}
        \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^\alpha} \overset{d}{\longrightarrow} \frac{2\alpha+\alpha(\alpha-1)}{2m^{\alpha-1}}\left(\sum_{i=1}^m N_i^2-\frac{m-1}{m}\right).
    \end{align*}
    \item[(iii)] For $\alpha=\frac{1}{2}$ it holds that
    \begin{align*}
        \frac{R_n^{[1/2]}-\,{\mathbb{E}}\big[R_n^{[1/2]}\big]}{\sqrt{n}}\overset{d}{\longrightarrow} \frac{1}{2}(N_1+N_m)+\frac{3\sqrt{m}}{8}\left(\sum_{i=1}^m N_i^2-\frac{m-1}{m}\right).
    \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2604.04100, '\LARGE Learning Equilibrium Fluctuation Expansions from Overdamped Langevin Dynamics'] Suppose that $F\in C^{n+1}(\mathbb{R})$ and satisfies \eqref{assump-F}.
	Let $(b_m(F))_{0\leq m\leq n}$ be the long-time limit coefficients defined in Theorem \ref{thm-longtime-intro} with the assumption $\mathbb{P}(\xi_0 > 0) = \mathbb{P}(\xi_0 < 0) = 1/2$. Let $(B_m(F))_{0\leq m\leq n}$  be the coefficients defined in Proposition \ref{prop-invariant-exp}. Then for every $m \in \{0, \dots, n\}$, we have
	\begin{equation*}
		b_m(F) = B_m(F).
	\end{equation*}

[Prp 86 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Set $r_n=n^{\theta},\;\theta\geq 0$ and suppose that $\kappa\in (1/2,1]$ and $\alpha>1$.
Then, for any $\zeta\in (0,\alpha)$,
it holds that
\begin{align*}
  \bbE[d_{\BL^{\kappa}}(\mu^{(r_n)},\mu_n^{(r_n)})^{\zeta}]
  \lesssim  
  \begin{dcases}
    n^{-\zeta(1-\frac{1}{\alpha}-\theta)}, & \alpha\in (1,2),\\
    n^{-\zeta(\frac{1}{2}-\theta)}(\log n)^{\zeta/2}, & \alpha=2,\\
    n^{-\zeta(\frac{1}{2}-\theta)}, & \alpha\in (2,\infty).
    \end{dcases}  
 \end{align*}

