body:
[Proposition 10 (A consistency property) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose the functions $(F_v^{k,H})_{v \in H}$ satisfy the 
    the consistency condition 
    \eqref{def:F-consistency},  and let $X^H$ be the associated process defined in \eqref{XH}.  Fix   any set $A \subset V$ with $A \cup \partial^2 A \subset V_H$. If the initial conditions $X^G(0)$ satisfy 
    the conditional independence property \eqref{eq:cond-independence} for  $A$,  and also satisfy the identity 
    \begin{equation}
        \Lmc\left({X^H_A}(0) \, | \, X^H_{\partial^2A}(0) = x_{\partial^2 A}\right) = \Lmc\left({X^G_A}(0) \, | \, X^G_{\partial^2A}(0) = x_{\partial^2 A}\right) 
    \end{equation}
    for $\Lmc(X^G_{\partial^2A}(0))$-almost every $x_{\partial^2 A}\in \PolishX^{\partial^2 A}$, 
    then it follows that 
    \begin{equation*}
        \Lmc\left({X^H_A}[k] \, | \, X^H_{\partial^2A}[k] = x_{\partial^2 A}[k]\right) = \Lmc\left({X^G_A}[k] \, | \, X^G_{\partial^2A}[k] = x_{\partial^2 A}[k]\right)
    \end{equation*}
    for each $k \in \N_0$ and $\Lmc(X^G_{\partial^2A}[k])$-almost every $x_{\partial^2 A}[k]\in (\PolishX^{k+1})^{\partial^2 A}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition half_zipper of arXiv:2604.17170, 'CaTherine wheels from trees and Liouville quantum gravity'] A subset $Z\subset S^2$ is a {\em half-zipper} if it satisfies the following properties:
\begin{enumerate}
\item{$Z$ is dense in $S^2$;}
\item{there is a unique embedded simple path in $Z$ (modulo time parametrization)
connecting any two distinct points of $Z$, and every point of $Z$ is a cut point of $Z$.}
\end{enumerate}
The cut point condition means that for every $p\in Z$ 
there are $q,r\in Z$ so that the unique path in $Z$ from $q$ to $r$ contains $p$ in its interior.

A half-zipper has {\em short hair} if, for any (equivalently, every) metric $d_0$ on $S^2$ which induces the standard topology, it satisfies:
\vskip 2pt
{\hskip 5pt (3) for every $\epsilon>0$ there is a compact subset
$T$ of $Z$ homeomorphic to a finite tree so that every (path) component of 
$Z-T$ has $d_0$-diameter $<\epsilon$.}

[Lemma 31 (Integral Asymptotics 3) of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that $\rho<0$, which, under Assumption \ref{Assumption}, implies that $H_0<1$. 
There is a bounded continuous function $\msf z_0:(0,\infty)\to\mbb R$
such that
for every $\th>0$, one has
\begin{align}

\msf J(\th)=8\Ga(-\rho)\left(\int_0^{\pi/2}\frac{(\cos\theta)^{-(2H_0-1)}(\sin\theta)^{d-H}}{\big(\cos\theta+\sin\theta\big)^{-\rho}}\d\theta\right)\th^{\rho}+\msf z_0(\th).
\end{align}
Moreover, one has
\begin{align}

\lim_{\th\to0}\msf z_0(\th)=
\begin{cases}
\displaystyle \frac{4\Ga(H_0)\Ga(1-H_0)\Gamma(d-H)}{\Ga(2H_0-1)(1+\rho)\rho}&H_0>1/2,\\
0&H_0=1/2.
\end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 241 of arXiv:2601.16377, '2601.16377'] Assume $\boldsymbol{\Theta}$ is positive semi-definite, take $\boldsymbol{v} \in \amsmathbb{R}^H$ non-zero and set $\widetilde{\boldsymbol{v}} = (\boldsymbol{v} \otimes \boldsymbol{v},0)$. Then, there exists a unique meromorphic bidifferential $\mathcal{B}_{\widetilde{\boldsymbol{v}}}$ on $\Sigma^{[2]}_{\widetilde{\boldsymbol{v}}}$ such that for any $\widetilde{\boldsymbol{w}} = (\boldsymbol{w}_1 \otimes \boldsymbol{w}_2,t) \in \mathfrak{G}^{[2]}.\widetilde{\boldsymbol{v}}$ and $p \in \Sigma^{[2]}_{\widetilde{\boldsymbol{v}},\widetilde{\boldsymbol{w}}}$ with $Z_{\widetilde{\boldsymbol{v}}}(p) = (z_1,z_2)$ we have
\begin{equation}

\mathcal{B}_{\widetilde{\boldsymbol{v}}}(p) = \left(\big\langle (\boldsymbol{w}_1 \otimes \boldsymbol{w}_2) \cdot \boldsymbol{\mathcal{F}}(z_1,z_2)\big\rangle + \frac{t}{(z_1 - z_2)^2}\right)\dd z_1\dd z_2.
\end{equation}
Besides, $\mathcal{B}_{\widetilde{\boldsymbol{v}}}$ is symmetric, it has no other poles than the double poles of the second term in \eqref{Omegatildevnun}, and integrating one of its variables around a contour surrounding the $h$-th segment in a fixed sheet gives zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 32 ($(L)-\overline{I}_j~a.e.$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] For a given node $(S,j)$, the following two properties will be referred  as the property $(L)-\overline{I}_j~a.e.$ on $\mathcal{S}_{(S,j)}$,
 \begin{enumerate}
     \item $(L_{(S,j)})$ holds,
     \item $\mathcal{N}^{(L_{(S,j)})} \equiv \{\hat{S} \in \mathcal{S}_{(S,j)}: \exists~k~\geq j~ \mbox{s.t.}~ (L_{(\hat{S}, k)}) ~\mbox{fails}\}$~is~a ~$\overline{I}_j$-null set (in particular $(L_{(\hat{S}, k)})$~holds~$\overline{I}_j-a.e.$~ for~ every~ $k \geq j$). 
  \end{enumerate}

[Theorem th: affine formula of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Set $X_0=x_0\in S$, fix $\mathbf{u}\in \mathcal V^*$, and suppose that the following conditions hold true.
\begin{enumerate}\phantomsection
    \item The sequence-valued  ODE
    \begin{align}
        \bm{\psi}(t)=\mathbf{u}+\int_0^tR(\bm{\psi}(s))ds, \qquad t\in [0,T],
    \end{align}
    admits a $\mathcal V^*$-valued solution $(\bm{\psi}(t))_{t\in[0,T]}$ such that 
   \begin{align}
       h_{\bm{\psi}(t)}(x)=h_\mathbf{u}(x)+\int_0^th_{R(\bm{\psi}(s))}(x)ds,
   \end{align}
  for all $x\in S$, $t\in[0,T]$.
    \item The process $N^{\exp(h_{\bm{\psi}(s)})}$ given in equation (equation eq:localmart of the paper) defines a true martingale for each $s\in [0,T].$
    \item $\int_0^T\int_0^T\mathbb E[|\mathcal{A}\exp(h_{\bm{\psi}(s)})(X_t)|]dsdt<\infty$.
\end{enumerate}
Then it holds that 
\begin{align}
    \mathbb E[\exp(h_\mathbf{u}(X_T))]=\exp(h_{\bm{\psi}(T)})(x_0).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 (resolvent regularity) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:resolvent-regularity}
For every $h > 0$ and $f\in L^{\infty}([0,\infty))$,
$v = (I - h\mathcal{L}_1)^{-1} f$
satisfies $\|v\|_\infty \le \|f\|_\infty$ and $v\in C^2((0,\infty))$.  For
$\delta\in(1,2)$, $v$ has a boundary cusp of order $x^{2-\delta}$, and,  as $x\downarrow 0$,
\begin{equation}
  v(x)-v(0)=c_v\,x^{2-\delta}+o(x^{2-\delta}),\qquad
  v'(x)=c_v(2-\delta)\,x^{1-\delta}+o(x^{1-\delta}),
\end{equation}
with $c_v$ generically nonzero. Note that $v$ is in general \emph{not} differentiable
at $0$ in the ordinary sense ($v'(0^+)=+\infty$). The
\emph{scale} derivative $dv/ds$ is finite at the boundary, and
\begin{equation}
  \frac{dv}{ds}(0^+)=\tfrac{\alpha}{\mu}\bigl(v(0)-f(0)\bigr)
\end{equation}
 when $f$ is continuous at $0$.

[Cor 36 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $ \gamma \in [1, \; 2]$, $\lambda \in (0, 1)$, $0 \leq s \leq t \leq T$ and $\omega = \min \{\gamma, \; 3/2\}$. Assume that
    \begin{equation} 
    \exists C >0, \; \forall n \in \mathbb{N}_+, \quad  \Theta(n) K_n \leq n^{\omega}.   
    \end{equation}
    Then there exists some $\delta_1 \in (0, \;1]$ and some $f: \mathbb{N}_+ \mapsto \mathbb{R}$ satisfying $\lim_{n \rightarrow \infty} f(n)=0$, such that
	\begin{align*}
		 \mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ & \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+1}^{\infty} [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \\
		- & \frac{\Theta(n) K_n}{n \sqrt{n} } \sum_{z=1}^{L_n-1}  za(z) \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )   \Psi_{x,L_n}^{\alpha,\beta}(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{1 + \delta_1} f(n), 
	\end{align*}
for every $n \in \mathbb{N}_+$, where $L_n:=n^{1 - \lambda}$. Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

[Theorem 43 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\gamma\le1$, let $A\in C(\Delta_T^2;B_\alpha)$, and assume that $\hdd A\in Z\hC^{\gamma}(\Delta_T^3;B_\alpha)$ belongs to the admissible selection domain of the chosen rule $\mathsf s$.  Define a path $I^{\mathsf s}_{\gamma,\alpha}(A)_t:=\mathcal J^{\mathsf s}_{\gamma,\alpha}(A)_{t0}$. Then
\begin{equation}

\hdd I^{\mathsf s}_{\gamma,\alpha}(A)
=
\mathcal J^{\mathsf s}_{\gamma,\alpha}(A).
\end{equation}
Equivalently,
\begin{equation*}
(\hdd I^{\mathsf s}_{\gamma,\alpha}(A))_{ts}=A_{ts}-\bigl(\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}(\hdd A)\bigr)_{ts}.
\end{equation*}
The path is the unique path satisfying \eqref{eq:convolution-primitive-identity} and $I^{\mathsf s}_{\gamma,\alpha}(A)_0=0$.

[Proposition 105 (Transport equation satisfied by $\partialmodquant{\tanderY^{N-1}}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identity holds:
	\begin{equation} 
		\Lunit \partialmodquant{\tanderY^{N-1}} =  \frac{1}{2} \vec{G}_{\Lunit \Lunit}\diamond \angLap \tanderY^{N-1} \wavearray +\, ^{(\tanderY^{N-1})}\mathfrak{B},
	\end{equation}
	where:
	\begin{align}
		\begin{split} 
		^{(\tanderY^{N-1})}\mathfrak{B} & = - \tanderY^{N-1} \mathfrak{B} - \tanderY^{N-1} |\upchi|^2   \\
		& \ \ + \frac{1}{2} [\tanderY^{N-1},\vec{G}_{\Lunit \Lunit}] \diamond \angLap \wavearray + \frac{1}{2} \vec{G}_{\Lunit \Lunit} \diamond [ \tanderY^{N-1},\angLap]\wavearray  \\
		& \ \ + [\Lunit,\tanderY^{N-1}] \mytr_{\gtorus}\upchi + [\Lunit,\tanderY^{N-1}] \widetilde{\mathfrak{X}} + L \left\lbrace \partialmodquantinhom{\tanderY^{N-1}} - \tanderY^{N-1}\widetilde{\mathfrak{X}}\right\rbrace, 
		\end{split}
	\end{align}
	where $\mathfrak{B}$ is as in \eqref{E:BINHOMRIC} and $\tanderY^{N-1}$ is the same differential operator every time it appears in \eqref{E:TRANSPORTEQUATIONFORPARTIALMODIFIEDQUANTITY}.

