[Theorem 1 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in \{3,4\}$, and let $\sO\seq\R^d$ be a bounded smooth domain. 
Suppose that 
  \begin{equation*}
      \psi=(\psi_n)_{n\geq 1}:\R^{1+d}\to \ell^2,\quad \psi(y,z) \ce \psi^0(y)+\psi^1\cdot z,
  \end{equation*}
  with $\psi^0=(\psi^0_n)_{n\geq 1}\in C^1(\R;\ell^2)$ and $\psi^1\in \ell^2(\R^d)$.
 Moreover,  assume that 
 there exists a constant $L\geq0$ such that for all $y,y'\in\R$, 
    \begin{align*}
                \|\partial_y
            \psi^0(y)-\partial_y\psi^0(y')
        \|_{\ell^2}
        \leq L|y-y'| \quad\text{ and }\quad
        \|\psi^0(y)\|_{\ell^2}
        \leq L(1+|y|).
    \end{align*}
    Suppose that one of the following two cases holds.
    \begin{enumerate}[label=(\alph*)]
        \item  Let $p=q=2$ and $s=\kappa=0$.
        \item  Let $p\in (2,\infty)$, $ \kappa\in [0,p/2-1)$, $s\in [0,1)$, and  $q\in [2, \frac{2d}{2+s})$ satisfy
    \begin{equation}
        \frac{1+\kappa}{p}\le 1-\frac{1}{4}\Big(s+\frac{d}{q}\Big).
    \end{equation}
    \end{enumerate}
     Then for all $u_0\in L^0_{\mathscr{F}_0}(\Omega;\,_\nu B^{3-s-4(1+\kappa)/p}_{q,p}(\sO))$ there exists a global solution $u$ to~\eqref{eq:intro:SPDE}, which is unique in the class $L^p_\loc([0,\infty),w_\kappa;\bpsn{3-s,q})$. In particular, in case \ref{case:pq2}, this holds for every $u_0\in L_{\F_0}^0(\Omega;H^1(\sO))$. In case \ref{case:pqnot2}, for any $\varepsilon>1/3$, one can choose suitable $p$ and $q$ such that this holds for all $u_0\in L_{\F_0}^0(\Omega; \nH^{\varepsilon, q}(\sO))$. Moreover, it holds that a.s.
    \begin{align*}
				u&\in H^{\theta,r}_{\loc}((0,\infty); \nH^{3-4\theta,\zeta}(\sO)),  \qquad \zeta\in [q,\infty),\, r\in (2,\infty),\, \theta\in [0,1/2),\\
                u&\in C_{\loc}^{\theta,6\theta}((0,\infty)\times \sO), \qquad\qquad\qquad\theta\in (0,1/2),
			\end{align*}
   and for each $0<t<T<\infty$,  whenever $u(t)\in L^4(\Omega;L^4(\sO))\cap L^2(\Omega;H^1(\sO))$, there is a constant $C_T\ge 0$ independent of $u(t)$ such that 
    \begin{equation}

        \E\nrm{u}^2_{C([t,T];H^1(\sO))}\le  C_{T} \big(1+\E\nrm{u(t)}_{L^4(\sO)}^4+\E\nrm{u(t)}_{H^1(\sO)}^2\big)<\infty.
    \end{equation}
    In case \ref{case:pq2}, it holds that $u\in L_\loc^2([0,\infty);\nH^3(\sO))\cap C_\loc([0,\infty);H^1(\sO))$ a.s.\ and \eqref{eq:aprioriIntro} also holds for $t=0$ provided that $u_0\in L^4(\Omega;L^4(\sO))\cap L^2(\Omega;H^1(\sO))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 81 of arXiv:2609.03875, 'Measure theory without infinities'] A set $\mathcal Q$ is called a semi-monotone class if the following conditions are satisfied:
  \begin{enumerate}
  \item Let $\mb A\colon\N\to\mathcal{Q}$ be an increasing sequence of sets and $A = \bigcup_{n\in\N} \mb A(n)$. If $A$ is a subset of some element of $\mathcal Q$, then $A\in \mathcal Q$. 
  \item If $\mb A\colon\N\to\mathcal{Q}$ is a decreasing sequence of sets, then  $\bigcap_{n\in \N} \mb A(n)\in\mathcal Q$.
  \end{enumerate}

[Definition 72 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that  $\rU$ is a topological vector space and $\rU^\prime$ its topological dual.
We denote by $\mathscr{L}^+(\rU,\rU^\prime)$ the space of symmetric non-negative definite linear maps $Q:\rU \to \rU^\prime $, i.e. 
for all $ f,\, g \in \rU$  the following two conditions hold, 
\begin{equation*}
\begin{aligned}
    \duality{f}{Q g}{\rU^\prime}{\rU}&= \duality{g}{Q f}{\rU^\prime}{\rU} \mbox{ and } 
    \duality{f}{Q f}{\rU^\prime}{\rU} \geq 0.
\end{aligned}
\end{equation*}

[Proposition prop:perc-Pip of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 15$
and $a \in [0,d-1]$.
For any choice of $q \in [1,\infty]$ satisfying
\begin{equation} 
\frac 1 q < 1 + \frac{ \frac 1 2 d - 1 - a } d ,
\end{equation}
there is a constant $K_{a,q} < \infty$ such that
\begin{equation} 
\bignorm{ \abs x^a  \Pi_p ^{(\mu)}(x)  }_q  \le  K_{a,q}
\end{equation}
uniformly in $p \in [p_c - \delta, p_c)$ and in $\mu \in \overline \Omega_p$.
For $a = d-1$, (equation eq:perc_moments-pnorm of the paper) also holds with $q = 2$.

