[Proposition 21 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$, $\alpha\in\mathbb R$ and $0\le \tau'\le \tau\le T$.
\begin{enumerate}
\item The restriction map
\begin{equation*}
\operatorname{Res}_{\tau,\tau'}:\mathfrak C^{\gamma}(\Delta^2_\tau;B_\alpha)\to \mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha), \quad [r]_\tau\mapsto\operatorname{Res}_{\tau,\tau'}[r]_\tau:= [r|_{\Delta_{\tau'}^2}]_{\tau'}
\end{equation*}
is well defined and linear. The map satisfies the seminorm bound 
$$\|\operatorname{Res}_{\tau,\tau'}\mathfrak r\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}\le \|\mathfrak r\|_{\mathfrak C_2^{\gamma,\alpha}(\tau)}.$$
\mlabel{it:froza}

\item The transport map
\begin{equation*}
\mathcal T_{\tau,\tau'}:\mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha)\to \mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha), \quad
[q]_{\tau'}\mapsto \mathcal T_{\tau,\tau'}[q]_{\tau'}:=[S_{\tau-\tau'}q]_{\tau'}
\end{equation*}
is well defined and linear. The map satisfies the seminorm bound 
$$\|\mathcal T_{\tau,\tau'}\mathfrak q\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}\le M_{\alpha,T}\|\mathfrak q\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}.$$
\mlabel{it:frozb}
\end{enumerate}

[Lemma Weighted radial lemma of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Let $A\subset\mathbb{B}_R^4$ be relatively closed and convex, and let
$g:A\to[0,a]$ be continuous and concave.  For almost every $s\in(0,R^2)$ set
\begin{equation*}
 J_0(s)=s\int_{\mathbb{S}^3}g(\sqrt{s}\,\theta)^n
 \mathbf1_A(\sqrt{s}\,\theta)\,\mathrm d\theta.
\end{equation*}
Here $g$ is extended by zero outside $A$, and $\mathrm d\theta$ is the area
measure on $\mathbb{S}^3$.  Then $J_0$ has a
left-continuous $\mathrm{BV}$ representative $J$ on $(0,R^2]$, with $J(0)=0$,
and
\begin{equation}
 J(s_2)-J(s_1)\leq|\mathbb{S}^3|a^n(s_2-s_1).
\end{equation}
Set $\gamma=g(0)$ when $0\in A$ and $\gamma=0$ otherwise.  Then
\begin{equation}
 J(s_2)-J(s_1)
 \leq\frac{|\mathbb{S}^3|}{2}(a^n+\gamma^n)(s_2-s_1).
\end{equation}
If $R>0$, $a>0$, and for some $h_j\downarrow0$,
\begin{equation}
 \frac{J(R^2)-J(R^2-h_j)}{h_j}\longrightarrow|\mathbb{S}^3|a^n,
\end{equation}
then $A=\mathbb{B}_R^4$ and $g\equiv a$.

[Lemma 25 of arXiv:2608.26619, 'Uniqueness of Positively Curved Ancient Ricci Flows on Surfaces with Boundary'] If $v:\old\times(-\infty,0)\rightarrow\bR$ satisfies \eqref{eq_symmetry_v}, then the function
\[
\phi:\old\longrightarrow\old,\qquad \phi(x,t)=\frac{v(x,t)-v_R(x,t)}{x_1}
\]
is even in the $x_1$ coordinate and satisfies
\begin{equation}
\begin{cases}
\phi_t=A\Delta\phi+B\cdot\nabla\phi+C\phi\quad&\text{in }\old\times(-\infty,0),
\\
\partial_r\phi=0\quad&\text{on }\partial \bD\times(-\infty,0),
\end{cases}
\end{equation}
where
\begin{align*}
A&=(1+v)^{-2},
\\
B&=2(1+v)^{-2}\frac{\nabla x_1}{x_1}-(1+v)^{-3}\nabla(v+v_R),
\\
C&=\frac{\alpha(v)-\alpha(v_R)}{v-v_R}\Delta v_R+\frac{\beta(v)-\beta(v_R)}{v-v_R}|\nabla v_R|^2-(1+v)^{-3}\nabla(v+v_R)\cdot\frac{\nabla x_1}{x_1}.
\end{align*}

