[Definition of arXiv:2412.02777, 'How to quantify the coherence of a set of beliefs'] A \textit{dissimilarity function} $\ell(p, q)$ is a function $\ell:[0, 1]\times [0, 1]\rightarrow [0, \infty]$ satisfying 
    \begin{enro}
        \item $\ell$ is lower semi-continuous with respect to $p$
        \item $\ell$ is strictly convex when finite with respect to $p$
        \item $\ell(p, q)=0$ if and only if $p=q$.
    \end{enro}

[Theorem Maruyama \cite{Maruyama1949} of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $X$ be a real-valued stationary Gaussian process, then
			\begin{itemize}
				\item $X$ is ergodic (and weakly-mixing) if and only if $\lambda$ is non-atomic.
				\item $X$ is mixing if and only if 
				\begin{equation*}
					r(t)\underset{\|t\|\to +\infty}{\longrightarrow}0.
				\end{equation*}
			\end{itemize}
			In particular, if $\lambda$ is absolutely continuous, then $X$ is mixing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 (Exact posterior covariance geometry) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{prop:gp-covariance}
Let $\Sigma_t$ be the covariance operator of the GP posterior $\Pi_t$. Under \cref{ass:gp-true,ass:gp-eigenvalues},
    \begin{equation}
    \E\sbr{\opnorm{\Sigma_t}}\lesssim t^{-1},
    \qquad
    \E\sbr{\tr(\Sigma_t)} \lesssim t^{-2\fs/(d+2\fs)}.
    \end{equation}

