h_l(\mathcal L(M^{\Gamma_1})|\mathcal L(M^{\Gamma_2}))=\frac{1}{2}\Big(tr\big((\Gamma_2 \Gamma_2^T)^{-1}(\Gamma_1 \Gamma_1^T)\big)-l - \log \frac{\det (\Gamma_1 \Gamma_1^T)}{\det (\Gamma_2 \Gamma_2^T)}\Big) .
\end {equation}}

[Proposition aux4AiandBi of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] ([olver1997asymptotics]) Let $Bi(x)$ be the other solution of the Airy equation and $c$ be the largest negative root of $Ai(x)=Bi(x)$ (see [olver1997asymptotics] for the explicit expression for both $Bi$ and $c$). Define the modulus function $\mathbf{M}$ and weight function $\mathbf{E}$ as:
    \begin{equation*}
        \mathbf{E}(x):=\left\{\begin{array}{cc}
\sqrt{\frac{Bi(x)}{Ai(x)}},~~x>c\\
1,~~~x\le c
        \end{array}\right.~~and~~ \mathbf{M}(x):=\sqrt{\mathbf{E}^2(x)Ai^2(x)+\frac{Bi^2(x)}{\mathbf{E}^2(x)}}.
    \end{equation*}
    Then $|Ai(x)|\le\left|\frac{\mathbf{M}(x)}{\mathbf{E}(x)}\right|$, and $\mathbf{E}$ increasing on $(0,\infty)$. Moreover, as $x\rightarrow\infty$,  $\mathbf{E}(x)\sim\frac{1}{\sqrt2}\exp\left(\frac{2}{3}x^\frac{3}{2}\right)$ and $\mathbf{M}(x)\sim\frac{1}{\pi^\frac{1}{2}x^\frac{1}{4}}$. Introduce the phase parameter $\theta(x):=\arctan\left(\frac{\mathbf{E}^2(x)Ai(x)}{Bi(x)}\right)$. Then $Ai$ and $Bi$ are related by:
    \begin{equation}
        Ai(x)=\frac{\mathbf{M}(x)}{\mathbf{E}(x)}\sin\theta(x),~~Bi(x)=\mathbf{M}(x)\mathbf{E}(x)\cos\theta(x).
    \end{equation}
    In terms of $Ai'$ and $Bi'$, further define a new modulus function $\mathbf{N}$ and phase function $\omega(x)$ by:
        \begin{equation*}
        \begin{split}
                   & \mathbf{N}(x):=\left\{\begin{array}{cc}
\sqrt{\frac{Ai'^2(x)Bi^2(x)+Ai^2(x)Bi'^2(x)}{Ai(x)Bi(x)}},~~x>c\\
\sqrt{Ai'^2(x)+Bi'^2(x)},~~x\le c
        \end{array}\right.\\&   \omega(x):=\left\{\begin{array}{cc}
           \arctan\left(\frac{Ai'(x)Bi(x)}{Ai(x)Bi'(x)}\right),~~x>c\\
           \arctan\left(\frac{Ai'(x)}{Bi'(x)}\right),~~x\le c
        \end{array}\right..
        \end{split}
    \end{equation*}
    Then $Ai'$ and $Bi'$ are related by:
    \begin{equation}
         Ai'(x)=\frac{\mathbf{N}(x)}{\mathbf{E}(x)}\sin\omega(x),~~Bi'(x)=\mathbf{N}(x)\mathbf{E}(x)\cos\omega(x).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem property:distance-points of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Assume that the event $F$ holds. Then
\begin{enumerate}[(a)] 
\item No two distinct points of $\mathscr{S}^{\bullet}\cup \mathscr{S}^{\circ}\cup \{v_k:k\neq i,j\}$ are within distance $c_1c_2R^{-f}$ of each other;
\item Given any $z\in \mathscr{S}^{\bullet}\cup \mathscr{S}^{\circ}\cup \{v_k:k\neq i,j\}$, changing the state of sites in $B\!\left(z,\frac{1}{2}c_1c_2R^{-f}\right)$ does not change the distance between $v_i$ and $v_j$ in $\intt\phi$;
\item Upon resampling all of the open connections between clusters in $\mathscr{S}^\circ$, the clusters of $\mathscr{S}^{\bullet}$ are still connected via closed paths to both $v_i$ and $v_j$.
\end{enumerate}

[Theorem thm_main of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume (equation converging_ratios of the paper), (equation delta_decay of the paper), (equation balanced of the paper). 
Then for either ${\scaleobj{1.1}{\diamond}}\in\{\mathsf{Ising},\mathsf{spherical}\}$ we have
\eeq{
\liminf_{N \to \infty} F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)\geqslant \lim_{N\to\infty} F_{N,{\scaleobj{1.1}{\diamond}}}^\mathsf{single}(\boldsymbol{\beta}),
}
where the coordinates of $\boldsymbol{\beta} = (\beta_p)_{p\geqslant1}$ are given by
\eeq{ 
\beta_p^2 \coloneqq \sum_{s_1,\dots,s_p\in\mathscr{S}}
\Delta^2_{s_1,\dots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}.
}
Furthermore,
\eeq{ 
\liminf_{N\to\infty} \GSE_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)\geqslant \lim_{N\to\infty} \GSE_{N,{\scaleobj{1.1}{\diamond}}}^{\mathsf{single}} (\boldsymbol{\beta}).
} (Proof in the paper; no proof environment follows the statement in the TeX.)

