[Lem lem_riemannPersistenceUpperBound of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] The persistence probability of the fractional L\'evy field $(X_H(\eta))_{\eta\in K}$ on the relatively compact set $K$ of a connected Riemannian manifold $\mathcal{M}$, where $O$ is in the interior of $K$, satisfies
    \begin{align*}
        \prob{\sup_{\eta\in K} X_H(\eta) < \varepsilon} \leq \varepsilon^{\frac{d}{H} + \mathdutchcal{o}(1)}, && \text{ for } \varepsilon \searrow 0.
    \end{align*}

[Lemma 41 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let be $\eta>0$, $\varepsilon\in (0,1)$ and $b\geq (2v)\vee(2\lambda)$.
Let $j\geq 1$.
Then
\begin{equation}

\E\Big[\Big\Vert\ind_{U_{0,b,\varepsilon}} 
V_{A_{0,b}}^{j}
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
\leq \dfrac{j C_{j}}{2^{j-1}\pi^{j+1/2}}\big\Vert\ind_{D}\big\Vert_{H^{-\eta}(\C)}\,
\Big(
\dfrac{32 b^{2}}{\pi}
\Big)^{j}
\Big(
1\vee
\Big(
\dfrac{\pi}{32 b^{2}} \vert\log\varepsilon \vert
\Big)
\Big)^{j-1}
\varepsilon^{\pi/(32 b^{2})},
\end{equation}
where
\begin{equation}

C_{j} = 
\int_{0}^{+\infty}
\Big(
1 + y\Big)^{j-1}
e^{-y}\,dy.
\end{equation}
Similarly,
given a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$,
and $\varepsilon\in (0,1)$, with
\begin{displaymath}
\varepsilon\,\leq \inf_{z\in\operatorname{Supp}(f_{0})}\CR(z,D),
\end{displaymath}
we have
\begin{multline}

\E\Big[\Big\Vert f_{0}\ind_{\widetilde{U}_{0,b,\varepsilon}} 
\vert \log \CR(z,D\setminus A_{0,b})\vert^{j}
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
\\
\leq
\dfrac{2j C_{j}}{\sqrt{\pi}}
\big\Vert f_{0}\big\Vert_{H^{-\eta}(\C)}
\Big(
\dfrac{32 b^{2}}{\pi}
\Big)^{j}
\Big(
1\vee
\Big(
\dfrac{\pi}{32 b^{2}} \vert\log\varepsilon \vert
\Big)
\Big)^{j-1}
\Big(
\dfrac{\varepsilon}{\inf_{\operatorname{Supp}(f_{0})}\CR(z,D)}
\Big)^{\pi/(32 b^{2})},
\end{multline}
where $C_{j}$ is still given by \eqref{Eq C j int}.

