[Corollary cor:main_cor of arXiv:2604.05921, 'Simplicity of random hypergraphs'] Let $\delta \in \mathds{N}$. Given vertices $v_1,v_2,\hdots,v_{\delta} \in V$, which may not all be unique, let the unique vertices be denoted by $v'_1,v'_2,\hdots,v'_{u(\vb*{v})}$, for some $u(\vb*{v}) \in \mathds{N}$. Let $D(\vb*{v})=\frac{\delta!}{\prod_{i=1}^{u(\vb*{v})} m_{v'_i}(\vb*{v})!}$, let $R(\cdot)$ be as in (equation def:B of the paper) and let $U$ denote a uniformly chosen vertex in $V$. For any function $f^{(i)}(v):V \rightarrow \mathds{N}$ and $w \in \mathds{N}$,
\begin{align}
     \sum_{\vb*{v} \in V^{\delta}} (D(\vb*{v}))^w \prod_{i=1}^{u(\vb*{v})} f^{(m_{v'_i}(\vb*{v}))}(v'_i) &=     \sum_{\substack{\vb*{a} \in \mathds{N}^{\delta}:\\\sum_{i=1}^{\delta} ia_i = \delta}}  \frac{\delta!^{1+w}}{\prod_{k=1}^{\delta} k!^{(1+w)a_k} } \sum_{\alpha(\cdot) \in R(\vb*{a})} (-1)^{\sum_{\vb*{x} \in \mathds{N}^{\delta}} (\sum_{i=1}^{\delta} x_i - 1)\alpha(\vb*{x})} \nonumber\\
     &\hspace{1cm} \times
    \prod_{\vb*{y} \in \mathds{N}^{\delta}} \Bigg( \frac{1}{\alpha(\vb*{y})!} \Big(\frac{n\mathds{E}\big[\prod_{i=1}^{\delta} (f^{(i)}(U))^{y_i}\big]\big(\sum_{i=1}^{\delta} y_i-1\big)!}{\prod_{i=1}^{\delta} y_i!} \Big)^{\alpha(\vb*{y})} \Bigg).
\end{align}

[Corollary quadratictermlocal of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Assume \\ that the linear measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \rightarrow \mathbb{R}^m$ satisfies the NSP of order $r$ with constant $\eta_r = 1/10 $, that $\mathbf{X}_\star \in \R^{d_1 \times d_2}$ is of rank $r$ and that $ \mathbf{X} \in \mathbb{R}^{d_1 \times d_2}$  satisfies $\mathbf{X} - \mathbf{X}_\star \in \ker(\mathcal{A})$. If $\varepsilon =  \frac{\besterrNuc{\mathbf{X}}{r} }{d} > 0$, $\nucnorm{\mathbf{X} - \mathbf{X}_\star} 
	\le 
	\frac{ \sigma_r \left( \mathbf{X}_\star \right) }{ \max \left( \eta_1 \sqrt{ d}, 2 \right)  }
$, where $0 < \eta_1 \leq \eta_r$ denotes again the order-one NSP constant of $\mathcal{A}$, and $\W{\mathbf{X}}{\varepsilon}(\cdot)$ is the harmonic-mean weight operator (eq:W:operator:action of the paper), then
\begin{equation} 
	\innerproduct{ \mathbf{X}_\star - \mathbf{X}  , \W{\mathbf{X}}{\varepsilon} ( \mathbf{X}_\star - \mathbf{X} ) }
	\le 
	16  \nucnorm{\mathbf{X}-\mathbf{X}_\star}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Let $(r_{t}(\cdot,\cdot), t \geq 0)$ denote the transition kernel of the OU process defined in \eqref{eq:ou-trans-dens}. Under Assumption \ref{assumption},
    \begin{align*}
        \limsup\limits_{T \to +\infty} \exp(T/2)\abs{\left(\Exp{P_T}-\Exp{Q_{T}}\right) \left[\log\left(\frac{r_{T/2}(x_T,x_{T/2})}{r_{T/2}(x_T,\nabla \varphi_{T/2}(x_{T/2}))}\right)\right]} < +\infty. 
    \end{align*}

