[Definition def: cycle conditon of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] A random vector $\Psi\colon \Omega \times \mathcal{N} \to \mathbb{R}$, satisfies the \emph{cycle condition} if for any sequence $(x_{0}, \cdots, x_{n})$ in $\mathbb{Z}^{d}$, with $x_{0} = x_{n}$ and $(x_{j-1}, x_{j}) \in \vec{E}_d$, $1 \leq j \leq n$, it holds that

  \begin{align}

    \sum_{j=1}^{n}\Psi(\tau_{x_{j-1}}\omega, x_{j} - x_{j-1}) \;=\; 0.
  \end{align}

[Lemma l:local_smoothing_homogenized of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that Assumption (ass:forcing_regularity_iteration of the paper) holds. Fix $\mu>0$, $r\in (1,\infty)$ and $p_0\in (2,p)$. Let $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha})$ be a local solution to the stochastic Stokes system (equation eq:turbulent_Stokes_scaling_quantitative_iteration of the paper) on $Q$ for some $N\geq 1$ and $\delta\in (0,1]$. Let  $(\overline{v}^{N,\delta},\overline{\pi}^{N,\delta})$ be the solution to the homogenized Stokes system (equation eq:homogenized_PDE_linear of the paper) on $(1/2)Q$ provided by Proposition (prop:local_well_posedness_homogenized_SPDE of the paper).
Then there exists a constant $C_0>0$ depending only on $\mu,\varrho,p,q,r,p_0$ and $d$ such that
\begin{equation}

\big(
{\mathbf E}\|\overline{v}^{N,\delta}\|^r_{L^p((1/4)I;W^{1,q}((1/4)B))}\big)^{1/r}
\leq C_0 \mathcal{L}_Q^{\#},
\end{equation}
where $\mathcal{L}_Q^{\#}$ is as in (equation eq:def_En_Q of the paper) and $Q=I\times B$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.23462, '2608.23462'] Let $p \geq 2$ and $\beta >0$. Assume that Assumption~\ref{assu:frozenLipschitz} is satisfied and the frozen variable is $p$-dissipative with constant $\beta$. Then, the following holds:
\begin{enumerate}
    \item[(i)] For all $x\in \R^{d_1}$, $y_1,y_2 \in \R^{d_2}$, and $t\geq 0$ we have
        \begin{align*}\|\hat{Y}^{x,y_1}_t-\hat{Y}_t^{x,y_2}\|_{L^p(\hat{\P})} \leq e^{-\beta t}|y_1-y_2|.\end{align*}
    \item[(ii)] There exists a $C_{\beta,p} > 0$ such that for all $x_1,x_2 \in \R^{d_1}$, $y \in \R^{d_2}$, and $t\geq 0$ we have
    \begin{align*}
        \|\hat{Y}^{x_1,y}_t-\hat{Y}^{x_2,y}_t\|_{L^p(\hat{\P})} \leq C_{\beta,p} |x_1-x_2| .
    \end{align*}
    \item[(iii)] There exist $C_{\beta,p}^{(1)}, C_{\beta,p}^{(2)} > 0$ such that for all $x \in \R^{d_1}$, $y \in \R^{d_2}$, and $t\geq 0$ we have       
    \begin{align*}
    \| \hat{Y}^{x,y}_t\|_{L^p(\hat{\P})} \leq \left\{ e^{-p(\beta  /2) t}|y|^p + C_{\beta,p}^{(1)} \right\}^{1/p} \leq e^{-(\beta  /2) t}|y| + C_{\beta,p}^{(2)}. 
    \end{align*}
\end{enumerate}

