[Prop barpt of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] For any $f\in C^{1,2}([0,t]\times\mathbb{R}_+^2)$, such that $f$ is non-negative, bounded, as are its first and second-order derivatives, and $f(t,z)\to 0$ when $t\to \infty$ uniformly in $z$,
\begin{equation}
\begin{aligned}

0=f(0,z_0)
+\int_0^\infty\!\int_{\mathbb{R}_+^2}(\partial_t f+\mathcal G f)(t,z)\,p(t,z_0,z)\,dz\,dt+
\sum_{i=1}^2 \int_0^\infty\!\int_{\mathbb{R}_+^2} (R^i\!\cdot\nabla f)(t,z)\,p_i^{z_0}(t,z) \,dz\,dt.

\end{aligned}
\end{equation}

