body:
[Dfn 30 (Resistance form, {\cite[Definition 3.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Kig12}}]
Let $F$ be a non-empty set.
A pair $(\calE,\calF)$ is called a resistance form if it satisfies the following conditions.
\begin{itemize}[leftmargin=3.5em, labelsep=0.3em]
  \item [(RF1)]$\calF$ is a linear subspace of $\R^F$ containing the constant functions.
  $\calE$ is a non-negative symmetric quadratic form on $\calF$ satisfying
  \begin{align*}
    \calE(u,u)=0\iff \text{$u$ is a constant.}
  \end{align*}
  \item[(RF2)]Let $\sim$ be an equivalence relation on $\calF$ defined by $u\sim v$ if and only if $u-v$ is constant.
  Then $(\calF/\sim,\calE)$ is a Hilbert space.
  \item[(RF3)] If $x\neq y\in F$, then there exists $u\in\calF$ such that $u(x)\neq u(y)$.
  \item[(RF4)]For any $x,y\in F$,
  \begin{align*}
    R(x,y)
    :=&\sup\left\{ \frac{|u(x)-u(y)|^2}{\calE(u,u)}:u\in\calF,\calE(u,u)>0 \right\}\\
    =&\inf\{\calE(u,u):u(x)=1,u(y)=0,u\in\calF\}^{-1}
  \end{align*} 
  is finite.
  \item[(RF5)]For $u\in \calF$, set $\bar{u}:=0\vee(u\wedge 1)$. 
  Then $\bar{u}\in\calF$ and $\calE(\bar{u},\bar{u})\leq \calE(u,u)$ hold. 
\end{itemize}
The function $R:F\times F\to[0,\infty)$ defined by (RF4) is a metric on $F$ (see \cite[Theorem 2.3.4]{Kig01}) and called the resistance metric associated with $(\calE,\calF)$.

[Lemma 15 (ODE tracking error) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] On the event
$\sup_{k\ge n}\norm{\hat c_k-c}\le c_\wedge/4$, for every $T>0$,
\[\max_{m\in\cW_{\mrm N}(n,T)}
\norm{\theta_m^{\mrm N}
-\vartheta_{\mrm N}(\tau_{\mrm N}(n,m);\theta_n^{\mrm N})}\le
        e^{5T/2}
        \sqbk{
        \max_{m\in\cW_{\mrm N}(n,T)}
        \norm{\sum_{k=n}^{m-1}\alpha_{k+1}^{\mrm N}\xi_{k+1}^{\mrm N}}
        +
        \frac{25T\alpha_{n+1}^{\mrm N}}{8(1-\gamma)}}.
\]

[Lemma lem:opposite of arXiv:2609.03448, 'Prime-power Diophantine tuples'] Let $a<b<c<d$ belong to a reduced $D(\varepsilon N)$-tuple and write
\[
\begin{array}{lll}
 ab+\varepsilon N=x_1^2,&ac+\varepsilon N=x_2^2,&bc+\varepsilon N=x_3^2,\\
 ad+\varepsilon N=x_4^2,&bd+\varepsilon N=x_5^2,&cd+\varepsilon N=x_6^2.
\end{array}
\]
Assume that every triple among $a,b,c,d$ is in the $\bar e$-branch.  Then
\begin{equation}
 x_1x_6\equiv x_2x_5\equiv x_3x_4\pmod N.
\end{equation}

[Lemma 13 of arXiv:2506.18558, '2506.18558'] Suppose that Assumptions {\rm\ref{A1}}, {\rm\ref{A2}}, {\rm\ref{A3}} and  {\rm\ref{A4}} hold.
For any $x\in\RR^{n}$, the SDE \eqref{e:ASDE1} has a unique strong solution $(\bar{X}_t)_{t\ge0}$. Moreover, for any $p\ge 2$ and $T>0$, there exists a constant $C_{p,T}>0$ such that
\begin{align}
\mathbb{E}\left(\sup_{t\in [0, T]}|\bar{X}_{t}|^{p}\right)\le  C_{p,T}(1+|x|^{p}),
\end{align}
and, for any $h>0$ with $0\le  t<t+h\le  T$,
\begin{align}
\mathbb{E}|\bar X_{t+h}-\bar X_{t}|^{2}
\le  C_{T}\left(1+|x|^{2}\right) h.
\end{align}

