[Definition def:TISGM of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given an infinite (locally finite) tree $T$, a positive symmetric function $\psi:\X\times \X\rightarrow (0,\infty)$ and a positive function $\bar\psi:\X\rightarrow (0,\infty)$, we say that a measure $\pmb\rho\in \P(\X^{T})$ is a splitting Gibbs measure on $T$ with state space $\X$ and specification $(\psi,\bar\psi)$ if there exists a collection of probability measures $(\ell_v)_{v\in T}$ in $\P(\X)$, called the ``boundary law'' or ``entrance law'', such that for each $r\in \N$ and $x\in \X^{T_r}$,
    \begin{align}
        \pmb\rho_{T_r}(x)=\frac{1}{Z_{T_r}}\prod_{\pr{u,v}\in E(T_r)}\psi(x_u,x_v)\prod_{v\in T_{r-1}}\bar\psi(x_v)\prod_{v\in T_r\setminus T_{r-1}}\ell_v(x_v), 
    \end{align}
    where $T_r$ is the depth-$r$ subtree of $T$ defined in Section (\oldref{subsubsec:topology}), $\pmb\rho_{T_r}$ is the marginal of $\pmb\rho$ on $T_r$ and $Z_{T_r}$ is the normalizing constant. 
    When $T=T^\k$ for some $\k\geq 2$, we say that a splitting Gibbs measure on $T^\k$ is translation-invariant if the corresponding boundary law is homogeneous, that is, $\ell_v=\ell$,  for all $v\in T^\k$ for some $\ell\in \P(\X)$. Denote the collection of translation-invariant splitting ($\TIS$) Gibbs measures on $T^\k$ with state space $\X$ and specification $(\psi,\bar\psi)$ by $\TISGM^{\psi,\bar\psi}_{T^\k}$.

[Dfn 25 (The local Hausdorff distance, {\cite[Section 3.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Nd24}}]
Let $(Z,d^Z,\rho_Z)$ be a rooted $\bcm$ space and $\calC(Z)$ be the set of all closed sets in $Z$.
We define the local Hausdorff distance $d^{Z,\rho_Z}_{\rm{H}}(A,B)$ for $A,B\in\calC(Z)$ by setting
\begin{equation*}
    d_{\mathrm{H}}^{Z,\rho_Z}(A,B):=\int_{0}^{\infty}e^{-r}(1\wedge d^{Z}_{\mathrm{H}}(A^{(r,\rho_Z)},B^{(r,\rho_Z)}))dr,
\end{equation*}
where
\begin{equation*}
      C^{(r,\rho_Z)}:=C\cap D(\rho_Z,r),\quad C\subseteq Z.
\end{equation*}

[Theorem 14 (Exact-shell Equivalence) of arXiv:2607.23526, 'Equivalence of Canonical and Microcanonical Ensembles for Euclidean Lattices'] Suppose $H(\Lambda)$ is lattice with maximal span $h>0$. Let $E_N\in\im(H_N)$ satisfy $E_N/N\to u>0$, and set $\beta=m^{-1}(u)$. Then for every $k\geq1$,
\begin{equation}
\left\|(\pi_k)_*\mu^{\sh}_{N,E_N}-p_{\beta}^{\otimes k}\right\|_{\TV}\to0,\quad N\to+\infty.
\end{equation}
Moreover, let $u_N=E_N/N$ and $\beta_N=m^{-1}(u_N)$, then
\begin{equation}
g_N(E_N)=\frac{hZ(\beta_N)^Ne^{\beta_NE_N}}{\sqrt{2\pi N\sigma^2(\beta_N)}}(1+o(1)).
\end{equation}
Consequently, the thermodynamic limit
\begin{equation}
\lim_{N\to+\infty}\frac{1}{N}R^{\sh}_{N,E_N}=\psi(\beta)+\beta u=s(u).
\end{equation}

