[Theorem TH1-* of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] \textbf{(Existence with cut-off.)} There exists  at    least   one     solution $f^\varepsilon_N$ to  (equation Ito-FP_eps-V2 of the paper) in the sense of  (Def-sol-QR-* of the paper). Moreover,  it holds 
\begin{align}
 \ensuremath{\mathbb{E}}\Big[\sup_{v\in[0,t]} \Vert f^\varepsilon_N(v)\Vert_H^2  \Big]&+\dfrac{4}{\beta}\ensuremath{\mathbb{E}}\int_0^t [f^\varepsilon_N(s)]_V^2ds\leq 2\Vert f_{0}\Vert_H^2\exp{(4\mathcal{K}_\varepsilon t)} \text{ for all } t\in [0,T],
\end{align}
where $\mathcal{K}_\varepsilon>0$ independent of $N.$
Moreover, for any two quasi-regular weak   solutions $f_1, f_2,$   of  (equation Ito-FP_eps-V2 of the paper)  with    the same    initial data    $f_0$,  if   $(f_i(t),\varphi)$    is  $\overline{\mathcal{G}}_t$-adapted, for both    $i=1,2$ and for    any $\varphi\in V$, then   $f_1=f_2.$

[Lemma lem:continuous curve of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $x_0\in U\setminus \{x_1,\ldots,x_k\}$. For $\mathbb{P}_{\vec{x}}$-almost every $\mathcal{D}$ and any $0<\beta<1$, there exist a constant $c_5=c_5(\beta,\mathcal{D},x_0)>0$ such that for all $x\in \mathcal{D}$, we can construct a rectifiable curve $\gamma_x \subseteq \mathcal{D}$ connecting $x$ and $x_0$ satisfying
    \begin{equation}
        l(\gamma_x(x,x'))\le c_5\,\mathrm{dist}(x',\partial \mathcal{D})^\beta,\ \text{ for all } x' \in \gamma_x.
    \end{equation}

[Theorem 17 (Windowed Equivalence) of arXiv:2607.23526, 'Equivalence of Canonical and Microcanonical Ensembles for Euclidean Lattices'] Suppose $H(\Lambda)$ is nonlattice. Fix $\Delta>0$, let $E_N\in\R$ satisfy $E_N/N\to u>0$, and set $\beta=m^{-1}(u)$. Then $G_N(E_N,\Delta)>0$ for all sufficiently large $N$, and for every fixed $k\geq1$,
\begin{equation}
\left\|(\pi_k)_*\mu^{\mc}_{N,E_N,\Delta}-p_\beta^{\otimes k}\right\|_{\TV}\to0,\quad N\to+\infty.
\end{equation}
Moreover, let $u_N=E_N/N$ and $\beta_N=m^{-1}(u_N)$, then
\begin{equation}
G_N(E_N,\Delta)=\frac{Z(\beta_N)^Ne^{\beta_NE_N}}{\sqrt{2\pi N\sigma^2(\beta_N)}}\left(\int_0^{\Delta}e^{\beta_Nt}dt\right)(1+o(1)).
\end{equation}
Consequently, the thermodynamic limit
\begin{equation}
\lim_{N\to+\infty}\frac{1}{N}R_{N,E_N,\Delta}^{\mc}=\psi(\beta)+\beta u=s(u).
\end{equation}

[Proposition prop:two-point of arXiv:2607.18824, 'Non-Abelian multiplicative chaos on the circle'] For all $z_1,z_2\in\mathbb D$ distinct,
    \begin{equation}
    \left|1-z_1\bar z_2\right|^\frac{2\lambda_\rho^-}{\kappa+\check h}\leq\mathcal{G}_{\kappa,\rho}(z_1,z_2)\leq\left|1-z_1\bar z_2\right|^\frac{2\lambda_\rho^+}{\kappa+\check h},
    \end{equation}
    where $\lambda_\rho^\pm$ are defined in (equation eq:lambda_rho of the paper). Moreover, if $\frac{2\lambda_\rho^+}{\kappa+\check h}>-1$, the family $(\mathcal{G}_{\kappa,\rho}(e^{-\epsilon}\,\cdot,e^{-\delta}\,\cdot)|_{\mathbb S^1\times\mathbb S^1})_{\epsilon,\delta>0}$ converges almost everywhere and in $L^1(\mathbb S^1\times\mathbb S^1)$ as $\epsilon,\delta\to0$.

