body:
[Lem 152 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Given any $\upp,\eta\in (0,1)$, if $\linit$ is sufficiently large
depending on $\upp,\eta$, then
  \[
        \sup_{1\leq \ell\leq 3\linit/4}
        \lt\{
        \plim_{N\to\infty} 
  \bigg\{
  \frac{|(
  \hat{\by}^{-\ell},
  \tilde \by^{-\ell})|}{N}
  +\frac{| (
  \hat{\bv}^{-\ell},
  \tilde\bv^{-\ell})|}{M}\bigg\}
        \rt\}
  \leq \eta\,.
  \]

\begin{proof} 
From \eqref{eq:example-AMP-for-correlated-disorder} and the surrounding discussion, we have
        \begin{align}
         \nonumber
    & \frac{(\hat{\by}^{-1},\tilde{\by}^{-1})}{N}
    \simeq
    \upp
    \cdot
    \frac{(\hat{\bv}^{-2},\tilde{\bv}^{-2})}{M}
    \simeq
    \upp^2
    \cdot  \frac{(
    \hat{\by}^{-2},\tilde\by^{-2})}{N}  \\
    &\qquad\simeq 
    \dots
    \simeq
    \upp^{2(\linit-1)}
    \frac{(\hat{\by}^{-\linit},
    \tilde\by^{-\linit})}{N}
  \simeq
  \upp^{2(\linit-1)} \,.
  \end{align}
The claim follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:u-left-nonzero of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] Fix $i\in \mathcal{E}_n$. For $0\leq t\leq n-1$
\begin{equation}
  \widetilde{w}^{(i)}_t
  =
  \begin{cases}
    0, & t<i,\\[4pt]
    \displaystyle
    \frac{1}{t-i+1}\binom{t}{i}\,\frac{(n-1-i)!}{(n-1-t)!},
      & t\ge i.
  \end{cases}
\end{equation}
Then, $(\widetilde{w}^{(i)})^{\top}T=2^{-i}(\widetilde{w}^{(i)})^{\top}$. Furthermore, $\langle \widetilde{w}^{(i)}, {w}^{(j)}\rangle=\delta_{i, j}$ for any $i, j\in \mathcal{E}_n$.

[Lemma lem:condkernel of arXiv:2608.24830, 'Motion helps the contact process: survival below\\ the percolation threshold on Poisson Br'] There is $C_0=C_0(d)$ such that if $\mathsf a\ge C_0\sqrt\Delta$ then, with constants depending only
on $d$:
\begin{enumerate}[(i)]
\item $h\ge\tfrac12$;
\item $g_\Delta(x,y)\le2\,q_\Delta(x,y)\le2(2\pi\Delta)^{-d/2}$ for all $x,y$;
\item $|g_\Delta(x_1,y)-g_\Delta(x_2,y)|\le C_d\,\Delta^{-(d+1)/2}|x_1-x_2|$;
\item for all $R>0$ and all $t>0$,
  $\mathbb{P}_x\big[\sup_{s\le t}|B_s-x|\ge R\ \big|\ \mathcal D\big]\le 8d\,e^{-R^2/(2dt)}$;
\item $\int_{\mathbb{R}^d}g_\Delta(x,y)\,\mathrm dx=1$ for every $y$.
\end{enumerate}

[Corollary 10 (Worst PCS and the cost of using the symmetric center) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] Fix $k\ge2$, $1\le t<k$, and $\delta\in(0,1)$. Then, as $n\to\infty$,
\begin{equation}
 1-P_{n,k,t,\delta}(p_{n,k,t}^*)
 =t(k-t)A_{1,\delta}n^{-1/2}e^{-n\Jn}\{1+o(1)\}.

\end{equation}
If $k\ne2t$, then
\begin{align*}
 &P_{n,k,t,\delta}(\pc)
   -P_{n,k,t,\delta}(p_{n,k,t}^*)
 \\[-1mm]
 &\qquad=\frac{t(k-t)(k-2t)^2\kappa_\delta^2A_{2,\delta}^2}
 {8I_1''(\pc)A_{1,\delta}}
 n^{-1/2}e^{-n(2\Kn-\Jn)}\{1+o(1)\}.
\end{align*}
Thus the difference between the centered PCS and the worst-case PCS is on the smaller exponential scale $2\Kn-\Jn$.

