body:
[Defn 3 (Kinetic measure) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A map $q$ from $\Omega$ to the set of nonnegative, finite measures over $\mathbb{T}^N\times [0,T]\times\mathbb{R}$ is said to be a kinetic measure, if
\begin{description}
  \item[1.] $ q$ is measurable, that is, for each $\phi\in C_b(\mathbb{T}^N\times [0,T]\times \mathbb{R}), \langle q, \phi \rangle: \Omega\rightarrow \mathbb{R}$ is measurable,
  \item[2.] $q$ vanishes for large $\xi$, i.e.,
\begin{equation}
\lim_{R\rightarrow +\infty}\E[q(\mathbb{T}^N\times [0,T]\times B^c_R)]=0,
\end{equation}
where $B^c_R:=\{\xi\in \mathbb{R}: |\xi|\geq R\}$.
  \item[3.] for every $\phi\in C_b(\mathbb{T}^N\times \mathbb{R})$, the process
\[
(\omega,t)\in\Omega\times[0,T]\mapsto \int_{\mathbb{T}^N\times [0,t]\times \mathbb{R}}\phi(x,\xi)\dd q(x,s,\xi)\in\mathbb{R}
\]
is predictable.
\end{description}

[Lemma 10 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $f:[0,\sigma] \rightarrow \mathbb{R}^d$ be a continuous function and let $L:[0,\sigma] \rightarrow [0,\infty)$ be a continuous increasing function with $L(0)=0$. Consider the Lebesgue-Stieltjes measure $dL$ defined from $L$. Let $Y$ be the measure defined via Borel-measurable functions $\Phi:\mathbb{R}^d \rightarrow [0,\infty)$ as 
    \begin{equation*}
        \langle Y, \Phi \rangle \coloneqq \int_{b \in \mathbb{R}^d} \Phi(b)Y(db) := \int_{r=0}^\sigma \Phi(f(r)) dL(r).
    \end{equation*}
    Then we have that
    \begin{equation*}
        \text{supp}(Y) = \{f(r): r \in \text{supp}(dL)\}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 15 of arXiv:2609.03777, '2609.03777'] Let $k_1,k_2\geq2$. For $\tau\in C$ and $\lambda\in\latzero$, we have
\begin{align}
\summ{\mu\in\Lambda_\tau\setminus\{0,\lambda\}}\frac{\LL(|\mu|)^m}{|\mu|^{k_1}|\mu-\lambda|^{k_2}}
\ll_{C,m}\frac{\LL(|\lambda|)^{m+1}}{|\lambda|^2}\,.
\end{align}

