[Lemma 6 of arXiv:2609.02175, '2609.02175'] Assume \eqref{eq:radial-short-range},
	\eqref{eq:radial-keller}, \eqref{eq:radial-energy}, and
	\eqref{eq:radial-convexity}. Then the deflection function
	$b\mapsto\Theta_\lambda(b)$ is strictly decreasing:
	\begin{equation}
		\Theta_\lambda'(b)<0,
		\qquad b>0.
	\end{equation}
	Moreover,
	\begin{equation}
		\lim_{b\to0^+}\Theta_\lambda(b)=\pi,
		\qquad
		\lim_{b\to+\infty}\Theta_\lambda(b)=0.
	\end{equation}
	In particular, for every scattering angle
	$\Theta\in(0,\pi)$, there exists a unique impact parameter
	$b>0$ such that
	\begin{equation}
		\Theta_\lambda(b)=\Theta.
	\end{equation}

