[Theorem t:global_NSE of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that $q,p\in (2,\infty)$ satisfy
\begin{equation}

\frac{2}{p}+\frac{3}{q}<2, \quad {{\normalfont\text{(subcriticality)}}}
\end{equation}
and fix 
\begin{equation*}
M \geq 1  \qquad \text{ and }\qquad \varepsilon\in (0,1).
\end{equation*}
Then there exist $\mu>0$ and $\theta\in \ell^2$ satisfying $\#\{k\,:\, \theta_k\neq 0\}<\infty$ for which the following assertion holds. For any
\begin{equation}

u_0\in \mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^3)\qquad \text{ such that }\qquad \|u_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)}\leq M,
\end{equation}
the unique maximal $(p,q)$-solution $(u,\tau)$ to the stochastic {\normalfont{3D NSEs}} (equation eq:navier_stokes_intro of the paper) is global in time with high probability:
\begin{equation}

{\mathbf P}(\tau=\infty)>1-\varepsilon.
\end{equation}
Moreover, $(u,\tau)$ has the following regularity properties:
\begin{align}

u&\in L^p_{{\rm loc}}([0,\tau);H^{1,q}(\mathbb{T}^3;{\mathbb R}^3))\cap C([0,\tau);B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)) \ \text{ a.s.\ }\\

u&\in C^{\vartheta_0,\vartheta_1}_{{\rm loc}}((0,\tau)\times \mathbb{T}^3;{\mathbb R}^3)\ \text{ a.s.\ for all }\vartheta_0<1/2,  \ \vartheta_1<\infty.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<p<\infty$. Given a matrix weight $W\in A_p$, we have
\begin{equation*}
\left\|\mathcal T_{W,1}f\right\|_{L_{p}} \lesssim_{p,d}[W]_{A_p}^{1+\frac{1}{p(p-1)}} \|f\|_{L_p(\Omega;\mathbb C^d)},\quad\forall f\in L_p(\Omega;\mathbb C^d).
\end{equation*}

[Lemma 36 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] The following uniform estimate holds: 

\begin{equation*}
\sup_{\delta \in (1,\infty)} \left( \sup_{0 \le t \le T} \|v_{\text{{\tiny $\delta$}}}(t)\|_{L^4(\Omega)} \right) \le C_{24},
\end{equation*}

where the constant $C_{24}>0$ is the same as in Lemma \ref{Lemma-4-1}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Fix a continuous function $f\in C(\bb T)$. Then, there exists a positive constant
$\mf h^*>0$, independent of $\epsilon$ such that
\begin{align*}
e^{-\mf h_{\widehat{\mf q}}/\epsilon}\,
\Big|\, & \int_{\bb T}f(x) \, \frac{1}{\mtt a(x)} \,
\phi_{\widehat{\mf q},\epsilon}(x)^2
\int_x^{x+1}\frac{e^{[S(y) - S(x)] /\epsilon}}{\phi_{\widehat{\mf q},\epsilon}(y)^2}
\,dy\,dx \\
&\quad - \sum_{k\in S_{\widehat{\mf q}}} \int_{\mc E_{\widehat{\mf q}}(k)} f(x)
\, \frac{1}{\mtt a(x)} \, \phi_{\widehat{\mf q},\epsilon}(x)^2
\sum_{j\in \mf I_k}\sum_{\sigma\in \mc W_{j,j+1}^{(\widehat{\mf q})}}
\int_{\sigma-\eta_0}^{\sigma+\eta_0}
\frac{e^{[S(y)-S(x)] /\epsilon}}{\phi_{\widehat{\mf q},\epsilon}(y)^2}\,dy\,dx\,\Big|
\,\leq\, e^{-\mf h^{*}/\epsilon}\,.
\end{align*}

