[Lemma lem:cavitymap of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $\k\geq 2$ and $B\in \R$. In the ferromagnetic regime $\beta>0$, there exists a critical threshold $\betacrit=\betacrit(\k,B)>0$
 such that the map $\Gamma = \Gamma(\k,\beta,B)$ has a unique fixed point $\exth^*$ if and only if $(\beta, B)$ lie in the uniqueness regime 
 \begin{equation}

           \pr{(\beta',B'): 0<\beta'<\betacrit(\k,B)\text{ or }(\beta',B')=(\betacrit(\k,0),0)}.
 \end{equation}
  Moreover, the following  properties hold in the ferromagnetic regime: 
\begin{enumerate}
\item 
Suppose $B > 0$. Then $\Gamma$  has a  unique fixed point $\exth^+$ in   the interval  $(0,\infty)$, and   
\begin{enumerate} 
\item 
if $\beta = \betacrit$,  then 
$\Gamma$ has exactly one additional fixed point $\exth^- < 0$; 
\item 
if $\beta > \betacrit$,   then 
$\Gamma$ has exactly two additional fixed points  $\exth^-<\exth^\sharp<0$. 
\end{enumerate}
  \item Suppose  
 $B < 0$. Then $\Gamma$  has a  unique fixed point  $\exth^-$  in the interval  $(-\infty,0)$, and 
 \begin{enumerate}
     \item 
 if $\beta = \betacrit$,  then 
$\Gamma$ has exactly one additional fixed point $\exth^+ > 0$; 
 \item 
 if $\beta > \betacrit$, then $\Gamma$ 
has exactly two additional fixed points  $0 < \exth^\sharp < \exth^+$.
\end{enumerate}
\item 
When  $B = 0$,  $\exth^\sharp = 0$ is always a fixed point of $\Gamma$, 
and $\Gamma$ has exactly three fixed points $\exth^-<\exth^\sharp=0<\exth^+$ if 
 $\beta  >\betacrit = \betacrit(\k,0)$.
\end{enumerate}
  Furthermore, $\betacrit(2,B)=\infty$ for every  $B\in \R$, and for $\k\geq 3$,
\begin{itemize}
        \item $\betacrit(\k,0)=\tanh^{-1}(\frac{1}{\k-1})$;
        \item $\betacrit(\k,B)=\betacrit(\k,-B)$, for every $B\in \R$.
\end{itemize}

In the antiferromagnetic regime $\beta<0$, the map $\Gamma=\Gamma(\k,\beta,B)$ has a unique fixed point $\exth^\sharp$ for all $B\in \R$. In particular, $\sgn(\exth^\sharp)=\sgn(B)$.

[Lemma lm:consi of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] The following properties hold almost surely:
    \vspace{-0.5em}
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item For every $x\in {\mathbb R}$, the set $M_+(x):=\{\mathcal S_{r,x}(a):\, r<x,\,(a,r)\in\mathcal D\}$ is dense in $ {\mathbb R}_+$.
		\vspace{-0.5em}
		\item Fix $(a,r)\in {\mathbb H}$, and let $\mathcal S_{r,\cdot}(a)$ denote the unique strong solution to~(equation eq:SDE_PSR of the paper), absorbed at $\tau_{(a,r)}$. Then, almost surely, for all $x\ge r$,
		\begin{align}
			\mathcal S_{r,x}(a)
			= \inf \left\{ \mathcal S_{r_n,x}(a_n):\, r_n< r,\ \mathcal S_{r_n,r}(a_n)>a,\ (a_n,r_n)\in \mathcal D \right\}.
		\end{align}
	\end{enumerate}

