\[
\Gamma(S) = \inf_{m \in \AllMeasures{S}}
\sup_{t \in S} I_m(t),
\quad
I_m(t) =
\int_0^{\diam(S)} \sqrt{\log\frac{1}{m(B(t,r))}} \, \ud r.
\]
Here $B(t,r)=\{u\in S:\|u-t\|_2\leq r\}$.
It suffices to show that $\LiuFunctional{F} \gtrsim \Gamma(F)$ for
all finite subsets $F \subset T$; 
this follows from~\cite[\S 6]{Liu26}; 
the details are given below as~\Cref{prop:liu-functional-controls-gamma}.
Then,
\[
\LiuFunctional{T} \geq
\sup_{\substack{F \subset T \\ |F|<\infty}} 
\LiuFunctional{F} 
\gtrsim \sup_{\substack{F \subset T \\ |F|<\infty}} \Gamma(F)
\stackrel{\rm(i)}\gtrsim \sup_{\substack{F \subset T \\ |F|<\infty}} \gamma_2(F) ...","release_manifest_digest":"sha256:14107f331760fd6c6c7a77eb7709fb9a0647195c87ff7e067b3f39b67524db6b","revision_digest":"sha256:7e3acc159d3f4842036916b780095651167fdda70a1828da81028b9d8697bb19","source_id":"arxiv:2606.03973","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Theorem 11 of arXiv:2607.08242, 'Convergence of random sums in non-commutative probability'] Let $\mathcal{S}_{N_n}$ be as in Theorem \ref{thm31}, except that its summands $\{a_i\}$ are independent and identically distributed variables on an NCP $(\mathcal{A},\varphi)$. Let $z$ be a standard Gaussian variable in $\tilde{\mathcal{A}}$, which is independent of $\tilde{N}_n$ (as defined above).
    Then, we have the following: \vskip5pt

\noindent(i) Under the assumptions of Theorem \ref{thm31} (i), we have \begin{equation*}
        \tilde{\varphi}(\tilde{\mathcal{S}}_{N_n}^m(\delta_n\tilde{N}_n)^l)=\tilde{\varphi}[(\delta_n\tilde{N}_n\cdot1_\mathcal{A}+\sqrt{1-\delta_n^2}z)^m(\delta_n\tilde{N}_n)^l]+o(1)\ \ \text{for all}\ \ m,l\in\mathbb{N}\cup\{0\}.
    \end{equation*}

    \vskip5pt

\noindent (ii) Under the assumptions of Theorem \ref{thm31} (ii), 
    \begin{equation*}
         \tilde{\varphi}(\tilde{\mathcal{S}}_{N_n}^m(\frac{N_n}{\eta_n})^l)=\mathbb{E}[(\frac{N_n}{\eta_n})^{\frac{m}{2}+l}]\varphi(z^m)+o(1),\  \ \text{for all}\ \ m,l\in\mathbb{N}\cup\{0\}.
        \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Lamperti-Kiu of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] \cite[Thm.2.3] {alili2017inversion} Let $\alpha >0$ and $((\xi,\Theta),\mathbb{P})$ be a MAP in $S\times \mathbb{R}$ with an extra isolated state $\partial$ and lifetime $\zeta$. Define a process $X$ by \begin{equation*}
    X_t=
 \begin{cases}
        \Theta_{\tau_t}e^{\xi_{\tau_t}} & \text{if  }  t< \int_0^\zeta e^{\alpha \xi_s}ds  \\
        0 &  \text{if   }  t\geq \int_0^\zeta e^{\alpha \xi_s}ds
    \end{cases}
    \end{equation*}
where the time change is given by\begin{equation*} \tau_t := \inf \{ s \, : \, \int_0^s e^{\alpha \xi_u}du>t\}
\end{equation*}
for $t< \int_0^\zeta e^{\alpha \xi_s}ds$. Define $P_x = \mathbb{P}_{x/||x||,\log ||x||}$ for $x\in \mathcal{H}$ and $P_0 = \mathbb{P}_{\partial}$. Then, the process $(X,P_x)$ is an $\mathcal{H}$-valued ssMp with index $\alpha>0$ and lifetime $\int_0^\zeta e^{\alpha \xi_s}ds$.\\
Conversely, let $(X,P_x)$ be an $\mathcal{H}$-valued self-similar Markov process with index $\alpha>0$ and lifetime $\zeta'$. Define the process $(\xi,\Theta)$ by \begin{equation*}
     \quad 
 \begin{cases}
        \xi_t = \log ||X_{A_t}|| \quad \text{and} \quad \Theta_t = \frac{X_{A_t}}{||X_{A_t}||} & \text{if  }  t< \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}  \\
        (\xi_t,\Theta_t)=\partial &  \text{if   }  t\geq \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}
    \end{cases}
\end{equation*}
where the time change is given by\begin{equation*}
    A_t := \inf \{  s \, : \, \int_0^s \frac{du}{||X_u||^\alpha}>t\} 
\end{equation*} for $t< \int_0^{\zeta'} e^{\alpha \xi_s}ds$. Define $\mathbb{P}_{y,\theta}= P_{\theta e^y}$ for $\theta \in S$ and $y\in \mathbb{R}$, and $\mathbb{P}_\partial = P_0$. Then, the process $((\xi,\Theta),\mathbb{P}_{y,\theta})$ is a MAP in $S\times \mathbb{R}$ with lifetime $ \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:meromorphic_contours of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Let $F$ be a meromorphic function on $\mathbb C$ and holomorphic at $0$, with simple
poles $a_1,a_2,\ldots$,
and let $A_1,A_2,\ldots$ denote the corresponding residues. Suppose
there exists a sequence of positively oriented, piecewise smooth,
simple closed contours $(C_N)_{N\geq1}$ such that
\begin{itemize}
    \item $0$ lies inside $C_N$, no pole lies on $C_N$, and these contours cover $\mathbb C$;

    \item the minimum distance $d_N$
    from $C_N$ to the origin satisfies $d_N\to\infty$ as $N\to\infty$;

    \item the length of $C_N$ is $\mathrm{O}(d_N)$;

    \item $F(z)=\mathrm{o}(d_N)$ uniformly for $z\in C_N$.
\end{itemize}
Then, locally uniformly for
$z\in\mathbb C\setminus\{a_1,a_2,\ldots\}$,
\[
F(z)
=
F(0)
+
\lim_{N\to\infty}
\sum_{a_n\in\operatorname{int}(C_N)}
A_n
\left(
    \frac{1}{z-a_n}+\frac{1}{a_n}
\right).
\]

[Definition 8 (Curvature Dimension Condition) of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] For $\kappa \in \mathbb{R}$, the triplet $(M,g,e^{-U}\vol)$ satisfies
$\text{CD}(\kappa,\infty)$ if the following inequality holds for all $x \in M$ 
\begin{align}\tag{CD($\kappa,\infty$)}
    \ricci + \mathrm{Hess}(U) \geq \kappa g. 
\end{align}

[Definition def:circle-endpoint-exponent of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Define
\begin{equation}
A_{\mathrm{loc}}(W)
=
\sup_{q>1}
\max\left\{
0,\,
\frac{q-1-\log_2\mathbb{E}[W^q]}{q}
\right\},
\end{equation}
where the term corresponding to \(q\) is interpreted as \(0\) whenever \(\mathbb{E}[W^q]=\infty\).

[Lemma 27 of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $\ g(\lambda, X) : \mathbb{R} \times M \rightarrow \mathbb{R}$ be an integrable function for all $\lambda$, differentiable with continuity with respect to $\lambda$ and such that $\mathbb{E}_{\mathbb{P}}[|\partial^2_{\lambda}g(\lambda,X)|]<\infty.$ Then
  \begin{equation*}
      \partial_{\lambda}\mathbb{E}_{\mathbb{P}}[g(\lambda,X)] = \mathbb{E}_{\mathbb{P}}[\partial_{\lambda}g(\lambda,X)].
  \end{equation*}

