body:
[Thm 1 of arXiv:2604.26316, 'Smallest distances between zeros of Gaussian analytic functions'] As $n\to\infty$,  $\mathcal S_n$  converges in distribution to a Poisson point process $\mathcal S$ on $[0,\infty)\times M$ with a universal rate  		$$\mathbb E [\mathcal S([0,a]\times U)]=\Big(\frac 18  a^4\Big) 
		\int_{U}  \frac{\omega}{\pi}, $$
		for any $a\in (0,\infty)$ and the measurable subset $U\subseteq M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2604.01257, '2604.01257'] Assume that conditions {(\ref{IIB3.3})} and {(\ref{IIB4.1})} hold. Then, the following relations are satisfied:
\begin{align}                
\left\{
\begin{array}{l}
    \displaystyle{{\lambda}_{\omega}}-\mathcal{L}(t)=\frac{{{\lambda}_{\omega}}}{\nu{t^{\nu}}}{L_{\omega}}(t)
    \qquad \hfill {\text{under assumption {(\ref{IIB3.3})},}}
\vspace{2.8mm}  \\
    \displaystyle{{\lambda}_{\psi}}-\ell(t)=\frac{{{\lambda}_{\psi}}}{\delta{t^{\delta}}}{L_{\psi}}(t)
    \qquad \hfill {\text{under assumption {(\ref{IIB4.1})},}}  \\
\end{array}
\right.
\end{align}
    where ${{L}_{\omega}}(t)=1+\mathcal{O}(\omega(t))$ and ${{L}_{\psi}}(t)=1+\mathcal{O}(\psi(t))$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:SRBM_d2 of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $(\zeta_{\lfloor t\rfloor}(2)-\zeta_{\lfloor t\rfloor}(1))_{t\ge 0}$ denote the continuous-time gap process for the $2$-ball SBBS with arbitrary capacity $c$ and error probability $\varepsilon\in (0,1)$. Then as $n\rightarrow\infty$, 
			\begin{align}
			(n^{-1/2}W_{\lfloor \frac{nt}{\varepsilon(1-\varepsilon)} \rfloor}\,: \, t\ge 0 ) \Rightarrow |B| \quad \text{as $n \to \infty$},
			\end{align}
			where $B$ denotes the standard Brownian motion in $\mathbb{R}$.

[Lemma lem:partial-line-loss of arXiv:2608.20480, 'When Clean Data Hurts: Learning with Monotone \\ Corruptions Beyond Binary Classification'] For every deterministic total predictor $g$,
\[
    \frac1q\frac1{q-1}
    \sum_{v\in L}
    \sum_{b\neq c_t(v)}
    \mathbf1\!\left\{
        g(r,t,F_{L,t},\{c_t(v),b\})
        \neq
        \lambda_{\{c_t(v),b\}}(c_t(v))
    \right\}
    \ge
    \frac12.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] For every $\beta>1$,
\begin{equation}
 0\in\overline{\supp\mu_\beta\setminus\{0\}}.
\end{equation}

[Thm 6 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] It holds that
\begin{equation}p_1(x,y)=\frac{\lambda\,(L-y)}{\lambda L+2c},\qquad p_3(x,y)=\frac{2c+\lambda\,(L-y)}{\lambda L+2c}\end{equation}
and
