[Lemma 12 (Energy and Hodge relations) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] For \(\tau<t<T_*\),
\begin{equation}
 \begin{aligned}
 \norm{w(t)}_2^2+2\nu\int_\tau^t\norm{\nabla w}_2^2\dd\rho
 &=F_\tau^2,\\
 \norm{z_\tau(t)}_2^2+2\nu\int_\tau^t\norm{\nabla z_\tau}_2^2\dd\rho
 &=F_\tau^2.
 \end{aligned}

\end{equation}
Moreover, \(\Pp\) and \(\Qq\) are orthogonal in \(L^2\) and in homogeneous
\(H^1\):
\begin{equation}
 \norm{q}_2^2=\norm{\Pp q}_2^2+\norm{\Qq q}_2^2,
 \qquad
 \norm{\nabla q}_2^2=\norm{\nabla\Pp q}_2^2+\norm{\nabla\Qq q}_2^2.

\end{equation}

