[Theorem 25 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Assume that conditions of Theorem \ref{Comparison for BSDEs} hold and that $K^1$ and $K^2$ are two regulated, optional, increasing processes in $\mathcal{S}^2$. If there exist a triplet $\left(Y_t^i, Z_t^i,U^i_t\right)_{0 \leq t \leq T}, i=1,2$, that belongs to $\mathcal{S}^{2,\alpha}_{\beta} \times \mathcal{H}^{2}_{\beta} \times \mathcal{U}^{2}_{\lambda,\beta}$ satisfying the equations
	\begin{equation*}
		Y_t^i=\xi^i+\int_t^T f^i\left(s, Y_s^i, Z_s^i,U^i_s\right) d s+K_T^i-K_t^i-\int_t^T Z_s^i d B_s-\int_{t}^{T}U^i_s dM_s, \quad i=1,2,

	\end{equation*}
	and, moreover, if  $K^1-K^2$ is an increasing process, then $Y_t^1 \geq Y_t^2$, $t \in [0,T]$ a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2604.24664, 'Absolute continuity of Rosenblatt measures'] Let $H \in (1/2, 1)$ and let $(B_t)_{t \in [0, T]}$ be a standard $\FctT$-Wiener process. Let $(B^{\frac{H}{2} + \frac12}_t)_{t\in [0,T]}$ be the FBM defined by \eqref{eq:fbm_representation} (with $\frac{H}{2} + \frac12$ in place of $H$) and let $(R^H_t)_{t\in [0,T]}$ be the Rosenblatt process defined by \eqref{eq:rosenblatt_representation}. Let also 
	\[
		\theta\in H^{\frac{H}{2},2}([0,T])
	\]
be given and define the process $(Z_t)_{t\in [0,T]}$ by
	\begin{multline*}
		Z_t = \exp \left(

			\vphantom{- \frac12 \frac{1}{c_{\frac{H}{2} + \frac{1}{2}}^2 \Gamma \left( \tfrac{H}{2} \right)^2} \int_0^t s^{H} \left[ I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \right]^2 \d{s}}
			- \frac{1}{c_{\frac{H}{2} + \frac{1}{2}} \Gamma \left( \tfrac{H}{2} \right)} \int_0^t s^{\frac{H}{2}} I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \d{B_s} \right.
		\\
		\left. - \frac12 \frac{1}{c_{\frac{H}{2} + \frac{1}{2}}^2 \Gamma \left( \tfrac{H}{2} \right)^2} \int_0^t s^{H} \left[ I^{-\frac{H}{2}}_{0+}(\bullet^{-\frac{H}{2}} \theta)(s) \right]^2 \d{s} \right).
	\end{multline*}
Then the measure $\tilde{\Pbb}$ defined by $\d{\tilde{\Pbb}} = Z_T \d{\Pbb}$ is a probability measure on $(\Omega,\Fcal)$ and the process $(\tilde{R}_t^H)_{t\in [0,T]}$ defined by
	\begin{equation}

		\tilde{R}^H_t = R_t^H + 2 d_H \int_0^t \theta_u \d{B^{\frac{H}{2} + \frac{1}{2}}_u} + d_H \int_0^t \theta^2_u \d{u}
	\end{equation}
is a Rosenblatt process with Hurst index $H$ with respect to $\tilde{\Pbb}$ that is adapted to $\FctT$.

