body:
[Theorem thm:gartner_ellis of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Consider a sequence of random variables $(X_n)_{n \geq 1}$ and a sequence $(a_n)_{n \geq 1}$ with $a_n \gg 1$. Assume for every $\lambda \in \mathbb R$ the limit
    \begin{align*}
    \lim_{n \to \infty}\frac{1}{a_n}\log \mathbb{E}\left[\Big.\exp\big(\lambda a_nX_n\big)\right]= \Lambda(\lambda),  \addtocounter{equation}{1}\tag{\theequation} 
\end{align*}
    exists point-wise as a convex function of $\lambda$, possibly assuming an extended real value for some $\lambda$, with the origin lying inside the interior of the domain $\mathcal D_{\Lambda}:=\{\lambda \in \mathbb R:\Lambda(\lambda)<\infty\}.$ Let $\Lambda$ further satisfy the following:
    \begin{itemize}
    \item Interior of $\mathcal D_{\Lambda}$ is non empty.
    \item $\Lambda$ is differentiable at all points of the interior of $\mathcal D_{\Lambda}$.
    \item $\Lambda(\cdot)$ is steep, namely, $\lim_{n \to \infty} |\Lambda'(\Lambda_n)|=\infty$ whenever $\lambda_n$ is a sequence of interior points of $\mathcal D_{\Lambda}$ converging to some boundary point of the interior of $\mathcal D_{\Lambda}$.
\end{itemize}
Then the sequence $(X_n)_{n \geq 1}$ satisfies a LDP with speed $a_n$ and with good rate function $\Lambda^*$, the \emph{Fenchel-Legendre} transform of $\Lambda$, defined as,
\begin{align*}
    \Lambda^*(x)=\sup_{\lambda \in \mathbb R}\Big\{\lambda x -\Lambda(\lambda)\Big\}\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem typT poly UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For any $\ell \in \mathbb{N}$ and $a \in (0,\infty)$,
  \begin{equation}
    \sup_{\bm{x} \in M^k}
    \hat{P}_{\bm{x}}\!\left(C_{\delta_\ell} \geq a \Psi_{\mathrm{ct}}(\delta_\ell)\right) 
    \leq 
    \tilde{c}_1 \ell^{-\tilde{c}_2 a^{2/\hat{d}_{\mathrm{s}}^*}}.
  \end{equation}

[Corr thisgivesthat of arXiv:2609.02682, 'LDP for tensor forms'] Given a sequence of graphs $G_n$ and a fixed graph $H$ above, set $Q_n$ by (equation eq:333 of the paper) and set $\widetilde{G}_n:=G_n/\lVert G_n\rVert_1$. Let $W^{(2)}_{\widetilde{G}_n}\in L^1([0,1]^2)$ be defined as in (equation eq:funext of the paper). Suppose the following assumptions are satisfied: 
\begin{align}
    \limsup_{n\to\infty}\,\lVert W^{(2)}_{\widetilde{G}_n}\rVert_{q\Delta} < \infty \qquad \mbox{and} \qquad \lVert W^{(2)}_{\widetilde{G}_n}-W_\infty^{(2)}\rVert_{\square^*}\overset{n\to\infty}{\to} 0, 
\end{align}
for some $q>1$ and $W_\infty^{(2)}\in L^1([0,1]^2)$. Then for any ${\boldsymbol \alpha}\in \mathbb{R}^c$, the  statistic
${\boldsymbol\alpha}^\top {\boldsymbol N}(H,G_n,{\bf{X}})$ satisfies an LDP with speed $n$ and the good rate function from (equation eq:i2 of the paper), with $G_{W_{\infty,\mathbf{1}_r}}$ replaced by $G^{(2)}_{{\infty},r}$, $1\le r\le c$ defined as
\begin{align}
    G^{(2)}_{{\infty},r}(\boldsymbol{f}):=\int_{[0,1]^v}\prod_{\{i,j\}\in E(H)} W^{(2)}_{\infty}(x_{i},x_{j})\prod_{a=1}^v f_r(x_a)\, d x_a.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] $F$ is $r$-semicontinuous if and only if the common order and uo closure of $\Ba_{F}$ is contained in $r\Ba_{F}$. Moreover, the following conditions are equivalent:
\item[(i)] $F$ is topologically semicontinuous;
\item[(ii)] The norm topology is semicontinuous;
\item[(iii)] The common order and uo closure of $\Ba_{F}$ is norm bounded;
\item[(iv)] Order closure preserves norm bounded sets;
\item[(iv')] Uo closure preserves norm bounded sets.

