[Defn 4 (Kinetic solution) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u,\nu)$ is a kinetic solution of \eqref{eq:intro-reflected-model} with initial datum $u^0$ and obstacle $\psi$ if the following conditions hold.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item The process $u$ is predictable as an $L^1(\mathbb{T}^N)$-valued process.
  \item For any $p\geq1$, there exists $C_p\geq0$ such that
\begin{equation}
\E\Big(\underset{0\leq t\leq T}{{\rm{ess\sup}}}\ \Vert u(t)\Vert ^p_{L^p(\mathbb{T}^N)}\Big)\leq C_p,
\end{equation}
\item \textbf{Obstacle constraint.} For $\mathbb{P}\otimes\dd x\otimes\dd t$-a.e. $(\omega,x,t)$,
\begin{equation*}
u(x,t)\geq\psi(x,t),
\end{equation*}
and $\nu$ is a nonnegative predictable Radon measure on $\mathbb{T}^N\times[0,T)$ satisfying $\E\nu(\mathbb{T}^N\times[0,T))<\infty$.
\item \textbf{Weak initial trace condition.} The process $u$ almost surely satisfies
\begin{equation}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation}
\item There exists a kinetic measure $q$ such that $f:= \one_{u>\xi}$ satisfies, for all $\varphi\in C^1_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla \varphi (t)\rangle \dd t\\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)\dd\mu_{x,t}(\xi)\dd x\dd\beta_k(t) \\ \notag
&\quad -\frac{1}{2}\sum_{k\geq1}\int^T_0\int_{\mathbb{T}^N}\int_{\mathbb{R}}\partial_{\xi}\varphi (x,t,\xi)G^2(x,\xi)\dd\mu_{x,t}(\xi)\dd x\dd t\\
&\quad + q(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu(x,t), \quad\ a.s. ,\nonumber
\end{align}
 where $f^0:=\one_{u^0>\xi}$, $a(\xi)=A'(\xi)$ and  $\mu_{x,t}(\dd\xi)=\delta_{u(x,t)}(\dd\xi)$.
\end{enumerate}

[Prop Properties_translationcovariant of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] {aizenman1990rounding}}]Let $(\eta_x)_{x\in \mathbb{Z}^d}$ be an i.i.d.~random field satisfying \mbox{(Ass:etaSymmetry of the paper) and~(Ass:etaNontrivial of the paper)} from Section~(sec_main of the paper). Assume that for every $x,y\in \mathbb{Z}^d$, $\Lambda\Subset\mathbb{Z}^d$ and $\zeta\in \mathcal{H}$ the following holds.
\begin{enumerate}[label=(\roman*)]
        \item $\tau$ is translation covariant, that is
        \begin{align*}
            \tau_{x+y}(\zeta)=\tau_x(T_y\zeta)\quad\text{ where }T_y\zeta=(\zeta_{\tilde x-y})_{\tilde x\in \mathbb{Z}^d}.
        \end{align*}
        \item If $x\in \Lambda$, we have $ \partial_{x}F_{\Lambda}(\zeta)=\mathbb{E}[\tau_x(\zeta_{\Lambda}
\eta_{\Lambda^\mathsf{c}})]$, where $\partial_x$ denotes the derivative w.r.t.\ the component~$\zeta_x$,
        \item $\tau\ge 0$, $|\tau_o(\zeta)|\le 2$ and $|\partial_o\tau_o(\zeta)|\le 2$, and 
        \item $\mathbb{E}[F_\Lambda(\eta)]=0$.
    \end{enumerate}
    Then, there is a function $\gamma\colon [0,\infty )\rightarrow [0,\infty )$ such that $\gamma(r)>0$ for $r>0$ and such that for all $t>0$
    \begin{align*}
        \liminf_{n\to \infty }\, \mathbb{E}\Big[\exp\Big( t F_{\Lambda_n}(\eta)/\sqrt{|\Lambda_n|}\Big)\Big]\geq \exp\big( t^2  \gamma\big(\mathbb{E}[\tau_o(\eta)]\big)^2 /2\big).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2609.02105, 'Contact fundamental forms and \\ adjoint varieties'] Let us use the coordinates and the 1-form $\theta$ on the Heisenberg group $\sH$ in Lemma \ref{l.coordi}.   
For each holomorphic function $F$ on $\sH$,  
  define a holomorphic vector field $\overrightarrow{F}$ on $\sH$ by \begin{eqnarray*}
\overrightarrow{F} & := &  - \frac{1}{2} \sum_{a=1}^m (\frac{\p F}{\p y_a} + \frac{x_a}{2} \frac{\p F}{\p t}) \frac{\p}{\p x_a} + \frac{1}{2} \sum_{a=1}^m (\frac{\p F}{\p x_a} - \frac{y_a}{2} \frac{\p F}{\p t}) \frac{\p}{\p y_a} \\ & & +  \left(\frac{1}{4} \sum_{a=1}^m  (x_a \frac{\p F}{\p x_a} + y_a \frac{\p F}{\p y_a}) - \frac{F}{2} \right) \frac{\p}{\p t}. \end{eqnarray*} 
 Then $\overrightarrow{F}$ is the unique vector field satisfying  $\theta (\overrightarrow{F}) = F$  and  $$  {\rm Lie}_{\overrightarrow{F}} \theta = -\frac{1}{2} \frac{\p F}{\p t} \theta.$$

[Lem incr_supports of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let $\mu$ be a $321$-avoiding permuton.
The supports of $\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}} + \mu_{\diagup}$ and  $\mu_{{\, \begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0,0.5) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}} + \mu_{\diagup}$ are nondecreasing subsets of $[0,1]^2$.

[Lemma lma:flipgroups of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $T$ denote $T_n^{tor}$ or $T_m^{tw}$, and let $T^{fl}$ be its flip. 
\begin{enumerate}
	\item The flipped torus-trivial group is free of rank two on $A = x_{n+3}, H^{fl} = x_1^{-1}D^{-n}$, with $D = A(H^{fl})^{-1}AH^{fl}$. The flipped twist-trivial group is free of rank two on $Y = x_{2m+4}$, $H^{fl} = x_1^{-1}C^m$, with $A = Y^{-1}(H^{fl})^{-1}YH^{fl}Y$ and $C = AYA^{-1}Y^{-1}$.
	\item Killing the trivial-strand meridian gives the same quotients $Q_n^{tor}$ and $Q_m^{tw}$ for standard and flipped tangles, with the same presentations as Propositions (prop:torusgroup of the paper) and (prop:twistgroup of the paper). 
	\item Let $r$ be a root of $P_n$. The assignments $\rho_r^{fl}(A) = A_r$, $\rho_r^{fl}(H^{fl}) = D_r^{-n}$ define a representation of the flipped torus-trivial group. It satisfies 
	\begin{equation*}
		\rho_r^{fl}(m_1) = \rho_r^{fl}(m_2) = I \ \ \ \ \ \rho_r^{fl}(m_3) = \rho_r^{fl}(m_4) = B_r
	\end{equation*} Let $z$ be a real root of $\Lambda_{2m-1}$. The assignments $\rho_z^{fl}(Y) = W_z^{-1}T_z$, $\rho_z^{fl}(H^{fl}) = W_z^m$ define a representation of the flipped twist-trivial group. It satisfies 
	\begin{equation*}
		\rho_z^{fl}(m_1) = \rho_z^{fl}(m_2) = I \ \ \ \ \ \rho_z^{fl}(m_3) = \rho_z^{fl}(m_4) = T_z
	\end{equation*}
	In both cases, every knot-strand Wirtinger generator has the same image as $\rho_r$ and $\rho_z$; indeed, both representations descend to the same $\bar\rho_r$ and $\bar\rho_z$ on the quotients. 
	\item Let $l_{1,n}^{tor, fl} = x_{n+4}^{-1}$, and $l_{1,m}^{tw, fl} = x_{2m+3}$ be the identity-strand pieces in the flipped diagrams. Then 
	\begin{equation*}
		\rho_r^{fl}(l_{1,n}^{tor,fl}) = \rho_r(l_{1,n}^{tor})^{-1} \ \ \ \ \ \rho_z^{fl}(l_{1,m}^{tw, fl}) = \rho_z(l_{1,m}^{tw})^{-1}
	\end{equation*}
	If $l_2^{fl}$ denotes the knot-strand piece in the flipped diagram, its quotient image agrees with that of $l_2$. Consequently, $\rho^{fl}(l_2^{fl}) = \rho(l_2)$. 
	\item The pair $(T^{fl}, \rho^{fl})$ satisfies hypotheses (1)-(4) of Theorem (thm:main of the paper) if and only if $(T, \rho)$ does. 
	\item Let $\widetilde{\bar\rho}: Q \to \widetilde{PSL}_2(\mathbb R)$ be the meridian-normalized lift of the quotient, and define the standard and flipped tangle lifts by composition with their quotient maps. Then 
	\begin{equation*}
		\mathrm{trans}(\widetilde\rho^{fl}(l_1^{fl})) = 0 \ \ \ \ \ \mathrm{trans}(\widetilde\rho^{fl}(l_2^{fl})) = \mathrm{trans}(\widetilde\rho(l_2))
	\end{equation*} 
\end{enumerate}

[Theorem a1 of arXiv:2411.19926, 'Sparse Pseudospectral Shattering'] For any $\rho$, $M \in \mathbb C^{n\times n}$ satisfying
\begin{equation} 
    \frac{\left[\log(n)\log(2\|M\| + n)\right]^{3}}{n} \le \rho \le \frac{n^{1/2}}{n}
\end{equation}
we have
\begin{align}
    \Pr\pare{\kappa_V(M+N_g)\ge(2\left\|M\right\|+n)^{15K}}
    &\le O\pare{n^{-K}}  \\
    \Pr\pare{\eta(M+N_g)\le(2\left\|M\right\|+n)^{-15K}}
    &\le O\pare{n^{-K}},  
\end{align}
where $K=\lceil 3\log(n)/(2\log(n\rho))\rceil$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:conditionalSurvival of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] The conditional survival function of \(X\) given \(Y=y\) is given by 
    \begin{align*}
        \mathbb{P}\bigl[X \geq x \mid Y = y\bigr] 
        = g(x,y) :=
        \begin{cases}
            \frac{\partial_y F_u(x,y)}{F_u(0,1)} e^{- \gamma(F_u(x,y) - y F_u(0,1))}
            & \text{if $y'\mapsto F_u(x,y')$ is differentiable at $y$},
            \\0 & \text{otherwise}.
        \end{cases}
    \end{align*}
    In particular, this means that for any $x\geq 0$ and any Borel set $B\subset [0,\infty)$, we have
         \begin{align} 
              \mathbb{P}[X \geq x, Y \in B]
              & = \int_{B} g(x,y) \, \mathbb{P}_Y(\mathop{}\!\mathrm{d} y).
         \end{align}

