				+ \breve{\slashed{\Transport}} \left( \frac{\ingoingmu}{\upmu \MagnitueofinnerproductofnewLandnewuL} \right) ( \SigmatTan^\alpha\newuL_\alpha)^2  \right. \\
				 & \ \ \ \ \left. + \frac{1}{\upmu}  \SigmatTan^\alpha \SigmatTan^\beta \newuL(\uLunit_\alpha \breve{\slashed{\Transport}}_\beta)
				 + \frac{1}{2 \upmu}  \SigmatTan^\alpha \uLunit_\alpha   \SigmatTan^\beta \breve{\slashed{\Transport}}_\beta \mytr_{\gnulltori} \deform{\newuL} 
				 -   \frac{1}{4\upmu} |\SigmatTan|_{\gfour}^2 \mytr_{\gnulltori} \deform{\newuL}  \right\} \weight^{\blowupratetoporderacoustic},
			\end{split}
