body:
[Lemma 26 (Time change formula for It\^o integrals) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] \textcolor{white}{,}\\   Suppose $\eta(s,\omega)$, $\ B(s,\omega)$ and $\alpha(s,\omega)$ are $ s$-continuous, $\alpha(0,\omega)=0$ for a.a. $\omega$, $\mathbb{E}[\alpha_t]<\infty$ and $ B(s,\omega) \in SO(m)$. Let $ W_s$ be an $ m$-dimensional Brownian motion and let $ v(s,\omega)$ be bounded and $ s$-continuous. Define
 \begin{equation}
     \tilde{W}_t=\lim_{j \rightarrow \infty} \sum_{j} \sqrt{\eta(\alpha_j,\omega)} B(\alpha_j,\omega)\Delta W_{\alpha_j} = \int_0^{\alpha_t}  \sqrt{\eta(s,\omega)} B(s,\omega) dW_s.
 \end{equation}
 Then  $\tilde{W}_t$ is an $\mathcal{F}_{\alpha_t}$-Brownian motion and
 \begin{equation}
     \int_0^{\alpha_t} v(s,\omega) dW_s = \int_0^t v(\alpha_r,\omega) \sqrt{\alpha'_r(\omega)} B^{-1}(\alpha_r,\omega) d\tilde{W}_r \ \ \mathbb{P}-a.s.,
 \end{equation}
 where $ \alpha'_r(\omega)=\frac{1}{\eta(\alpha_r,\omega)} .$

