[Theorem 7 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb R)$. For fixed $L,t,s$ and a deterministic
bounded input sequence,
\begin{equation}
K_{\psi,n,\theta}^{(L)}(t,s)
\xrightarrow{\mathbb P}
K_{\psi,\theta}^{(L)}(t,s)
\qquad (n\to\infty).

\end{equation}
The convergence is with respect to the joint randomness of
$W_r^{(n)}$ and $W_{\rm in}^{(n)}$.

[Lemma 14 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] For any integer $m \ge 0$,

        \begin{equation}
            \int_{[0, t]^{2m}} \left| \mathbb{E} \left[ \prod_{i=1}^m \Delta_{\epsilon}(W(s_i) - \widetilde{W}(r_i)) \right] \right|\mathrm{d} \mathbf{s} \mathrm{d}\mathbf{r} \le C^m \epsilon^{m/12} (m!)^2 \left( \frac{t^m}{m!} \right)^{17/12}
        \end{equation}

[Theorem 1 (Main theorem) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $n\ge1$, let $X_1,\ldots,X_n$ be independent nonnegative random variables with $\E X_i\le1$, and put $S=\sum_iX_i$. For $\delta>0$, set
\begin{equation}
 b_{n,\delta}=
 \begin{cases}
 \displaystyle \delta\left(\frac{n}{n+\delta}\right)^n,&0<\delta<1,\\[0.8em]
 \displaystyle \left(1-\frac1{n+\delta}\right)^n,&\delta\ge1.
 \end{cases}
\end{equation}
Then
\begin{equation}
 \Pp\left(S<\E S+\delta\right)\ge b_{n,\delta}.
\end{equation}
For every $n$ and every $\delta\ge1$, the bound is optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm NewLDP of arXiv:2609.02682, 'LDP for tensor forms'] Suppose $\{Q_n\}_{n\ge 1}$ is a sequence of symmetric, zero-diagonal $v$-tensors, such that   \begin{align}\|W_{Q_n}- W_\infty\|_{\square^*}\xrightarrow{n\to\infty}0,
\end{align}
 for some $W_{\infty}\in \mathcal{W}_v$.

Then the following conclusions hold:
 \begin{itemize}
     \item[(i)] Suppose ${\bf{X}}=(X_1,\ldots,X_n)$ where $X_i \overset{\text{i.i.d.}}{\sim} \mu$. Then $N_n(Q_n,\phi,{{\bf X}})$ satisfies an LDP with speed $n$, and the good rate function
 \begin{equation*}
J_{W_\infty}(t):=\inf_{{\boldsymbol f}\in \mathcal{F}_c:\ { G}_{{W_\infty},\phi}({\boldsymbol f})={t}}  \left\{ \int_0^1\sum_{r=1}^c f_{r}(u)\log \frac{f_{r}(u)}{\mu_r}du\right\},
\end{equation*}
with $G_{W,\phi}(\cdot)$ as in (def:g2 of the paper).
\item[(ii)] For any $\beta\in\mathbb{R}$ with $Z_{Q_n}(\beta,\mu)$ as in (equation eq:gibbs_pottsloppartition of the paper), we have
\begin{align}
\lim\limits_{n\rightarrow \infty} Z_{Q_n}(\beta,\mu)=\sup_{{\boldsymbol f}\in \mathcal{F}_c}\left\{ \beta{G}_{{W_\infty},\phi}({\boldsymbol f})
-\int_0^1\sum_{r=1}^c f_r(u)\log \frac{f_r(u)}{\mu_r}\,du\right\}.
		\end{align}


 Moreover, the maximizers of the above optimization problem are attained.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma covariance identity of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] For $u\ge s$ and $g,h \in L^2(\mu)$,
\begin{align*}
\mathds{E}_\mu[\overline{g(X_s)}h (X_u)]
=
\langle g,P_{u-s}h\rangle.
\end{align*}

[Dfn of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{The local Hausdorff topology}]
  We call $\lHausdMet{S}{\rho_{S}}$ the \textit{local Hausdorff metric (with the root $\rho_{S}$)}
  and the topology induced from the local Hausdorff metric the \textit{local Hausdorff topology}.

[Lem lall of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] For $L>0$, let $\mathcal S(L)$ be the set of closed geodesics on $X$ of length at most $L$. There exist
constants $0< \beta < 1$ and $c>0$ such that
\begin{equation}
 \liminf_{L\to\infty}
 \frac{
   \left|
     \left\{
       \gamma\in\mathcal S(L):
       N_{A,B}(\gamma)\geq\beta\,\ell_X(\gamma)
     \right\}
   \right|
 }{
   |\mathcal S(L)|
 }
 \geq c.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem TH1-*_nocutoff of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] \textbf{(Existence without cut-off.)} Assume $\kappa /(2+ k_T \beta) >1$. There exists $\eta>0$ such that if $k_T\beta \le \eta$ then there exists  at    least   one     solution $f_N$ to  (equation Ito-FP_eps-V2 of the paper) with $\varphi_\varepsilon\equiv 1$ in the sense of  (rmk:def_sol_nocutoff of the paper). Moreover,  it holds 
\begin{align}
 \ensuremath{\mathbb{E}}\Big[\sup_{v\in[0,t]} \Vert f_N(v)\Vert_{H_0}^2  \Big]&+\ensuremath{\mathbb{E}}\int_0^t [f_N(s)]_{V_0}^2ds\leq 2\Vert f_{0}\Vert_{H_0}^2\exp{(4\mathcal{K} t)} \text{ for all } t\in [0,T],
\end{align}
where $\mathcal{K}>0$ independent of $N$ but depends on $\kappa$. 
Moreover, for any two quasi-regular weak   solutions $f_1, f_2,$   of  (equation Ito-FP_eps-V2 of the paper)  with    the same    initial data    $f_0$,  if   $(f_i(t),\varphi)$    is  $\overline{\mathcal{G}}_t$-adapted, for both    $i=1,2$ and for    any $\varphi\in V_0$, then   $f_1=f_2.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] The following properties hold for the functions $L$, ${\rm LB}_m$ and ${\rm UB}_m$:
\begin{itemize}
    \item[i.] the functions $L$, ${\rm LB}_m$, and ${\rm UB}_m$ are non-increasing in the first variable, and
\begin{equation}

1\le {\rm LB}_m(x,z)\le \sqrt{L(x,z)}\le {\rm UB}_m(x,z)\le L(x,z)\quad\text{for } x>0,\ z>1;
\end{equation}
\item[ii.] for every $0<\alpha<1$,
\begin{align}

\int_\alpha^1 \frac{\rmd r}{r{\rm LB}_m(r,z)} &\le 2{\rm UB}_m(\alpha,z) + \frac{{\rm UB}_m(\alpha,z)}{z}\quad\text{and}\\

\int_\alpha^\beta \frac{\rmd r}{r{\rm UB}_m(r,z)} &\ge 2\left( {\rm LB}_{m+1}(\alpha,z) - {\rm LB}_{m+1}(\beta,z) \right)\quad \text{for every $0<\alpha<\beta\le1$};
\end{align}
\item[iii.] for every fixed $c_0>0$, there exists $C<\infty$ such that, for all $\gamma\in[c_0z^{-1},1]$, $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{align} 
{\rm LB}_m(\gamma r,z) &\le {\rm LB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right],
\\

{\rm UB}_m(\gamma r,z) &\le {\rm UB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right];
\end{align}
\item[iv.] for each fixed $B>1$ there exists $C_{B}<\infty$ such that,
whenever $s,t\in(0,1)$, $m\ge0$, $z>1$, and $B^{-1}s\le t\le Bs$,
\begin{equation}

C_{B}^{-1}{\rm LB}_m(s,z) \le {\rm LB}_m(t,z) \le C_{B}{\rm LB}_m(s,z);
\end{equation}
\item[v.] for every fixed $B\in(0,\infty)$, there exists $C_B<\infty$ such that, for all $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{equation}

{\rm LB}_{m+1}(Br,z) \ge {\rm LB}_{m+1}(r,z) \left[ 1- C_B\frac{m+1}{z} \right] - C_B{\rm LB}_{m+1}(1,z).
\end{equation}
\end{itemize}

