[Proposition 9 (Chaos asymptotics, \(H^*(m)>1/2\)) of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\delta(\varepsilon)>0\) be such that \(\delta(\varepsilon)\xrightarrow{\varepsilon\rightarrow 0} 0\) and \(\varepsilon/\delta\rightarrow 0\) as \(\varepsilon\rightarrow 0\). For \(\varepsilon\) small enough and \(H\neq 3/4\) we have the asymptotic behaviour
\begin{align}

\mathbb{E}[T_{2}^2]&\sim D_{\star}(H,m)\,\delta^{2(2-2H)\wedge 1},\\ 
\mathbb{E}[T_{2m-2r}^2]&\leq \bigl(D^{\mathrm{Diag}}_{H,m,r}+D^{\mathrm{Off}}_{H,m,r}\bigr)\delta^{2(m-r)(2-2H)\wedge 1}\quad 1\leq r< m-1,
\end{align}
where \(D_{\star}(H,m)\) is defined in \eqref{eq: D star} and the prefactors \(D^{\mathrm{Diag}}_{H,m,r}, D^{\mathrm{Off}}_{H,m,r}>0\), depending only on \(H,m\) and \(r\), are read off Lemmas~\ref{lem: asymptotic variance m=1 H>1/2}--\ref{lem: asymptotic variance m>1 H>1/2}; only \(D_{\star}(H,m)\) is used by name in the rest of the paper. The borderline value \(H=3/4\) carries an additional \(|\log\delta|\) factor in the second-chaos asymptotic. In particular,
\begin{equation}

\mathbb{E}[(C_{\varepsilon, \delta}-\mathbb{E}[C_{\varepsilon, \delta}])^2]\sim D_{\star}(H,m)\,\delta^{2(2-2H)\wedge 1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Least-favorable location for top-$t$ selection) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] Fix $k\ge2$, $1\le t<k$, and $\delta\in(0,1)$. There is $n_0=n_0(k,t,\delta)$ such that $\mathcal M_{n,k,t,\delta}$ is a singleton for all $n\ge n_0$. If $k=2t$, then
\begin{equation}
 p_{n,k,t}^*=\frac{1-\delta}{2}
 \qquad(n\ge n_0).

\end{equation}
If $k\ne2t$, then
\begin{equation}
 p_{n,k,t}^*
 =\frac{1-\delta}{2}
 +(k-2t)\Cd n^{-1/2}e^{-n\Gam}\{1+o(1)\}.

\end{equation}
Thus the displacement is to the right when $k>2t$ and to the left when $k<2t$. Consequently, for every $M>0$,
\begin{equation}
 n^M|p_{n,k,t}^*-\pc|\longrightarrow0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.11608, '2607.11608'] Let $s\in \R$ and $f_M$ as in \eqref{fM}. Then, 
\begin{align}	
&\int_{\R^d}|f_M|^2dx=1, \\
& \int_{\R^d} |f_M|^{p}dx \sim M^{\frac{dp}{2}-d}, \\
& \int_{\R^d} |\mathcal{L}^{\frac{s}{2}}f_M|^{2}dx\les M^{2s},

\end{align}
for any $p>0$, $M\gg 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] Let	$ V_i':=V_i\setminus (L\cup K) $. Then, for every $i\in[p]$, every $j\in[p]\setminus\{i\}$, and every $v\in V_i'$, we have
	\begin{equation*}
		d_{V_j'}(v)\geq
		\begin{cases}
			\bigl(\frac1p-16\varepsilon\bigr)D, & \text{if } p=2,\\
			\bigl(\frac1p-20\varepsilon\bigr)D, & \text{if } p\geq 3.
		\end{cases}
	\end{equation*}

[Definition 38 ($\ell_{t,u}$-differential) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] If $\varphi$ is a scalar function, then we define $\angrmd \varphi$ 
to be the following $\ell_{t,u}$-tangent one-form:
\begin{align} 
\angrmd \varphi 
& \eqdef \smoothtorusproject \rmd \varphi.
\end{align}

[Corollary 20 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2} with non-null $\Sigma$. Then, for almost every $\tau\ge0$, it holds that
\begin{align*}
    &\left| AC_\infty(\tau)\left[\mathbf{v}\right]
    - \left( c_1(\lambda^*) e^{-i B(\lambda)\tau}
    + c_2(\lambda^*) e^{i B(\lambda)\tau} \right)
    \right|\\
    =& \cO\left(-A(\lambda)\right) + \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right)
\end{align*}
for any $\mathbf{v}$ in a dense subset of $\R^2$ and in the limit $\lambda\to\lambda^*$. The complex parameters $c_j(\lambda)$ are defined for any $j\in\{1,2\}$ and $\lambda\leq \lambda^*$ by
\begin{align*}
    c_j(\lambda):= \frac{ \left|\left\langle \mathbf{v}, \mathbf{e}_j(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_j^*(\lambda) \right|\right|^2}{ \left|\left\langle \mathbf{v}, \mathbf{e}_1(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_1^*(\lambda) \right|\right|^2 + \left|\left\langle \mathbf{v}, \mathbf{e}_2(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_2^*(\lambda) \right|\right|^2},
\end{align*}
for $\mathbf{v}$ in the dense subset mentioned above. Moreover, we have that
\begin{align*}
    AC_\infty(\tau)\left[\mathbf{v}\right] =& c_1(\lambda^*) e^{-i B(\lambda^*)\tau}
    + c_2(\lambda^*) e^{i B(\lambda^*)\tau} + \cO\left(-A(\lambda)\right) \\
    &+ \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right) + \cO\left( |B(\lambda)-B(\lambda^*)| \right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

