[Definition 13 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $m,n\in\Nsf$, let $M$ be an $m$-dimensional manifold, and let $(U,x)$ be a chart on $M$. Let $f: M\to R_n^2M$ be a rough velocity field whose representation in the induced chart $(\overline{U},\overline{x})$ on $R_n^2M$ is $(f^i_\tau)$. Let also $\delta: M\to\Rsf$ be a smooth function. A \emph{rescaling} of $f$ by $\delta$ is the rough velocity field $\widetilde{f}: M\to R_n^2M $ whose representation $(\widetilde{f}^i_\tau)$ in chart $(\overline{U},\overline{x})$ is given by 
	\begin{equation}

		\widetilde{f}^i_{\ta} = \delta f^i_{\ta}, 
			\quad 
		\widetilde{f}^i_{\tab} = \delta^2f^i_{\tab},
			\quad \mbox{and} \quad 
		\widetilde{f}^i_{\tc} = \frac{\partial \delta}{\partial x^j}f^j_{\ta}\delta f^i_{\tb} + \delta^2f^i_{\tc}
	\end{equation}
for $i\in \llbracket 1,m \rrbracket$ and $\alpha,\beta\in\llbracket 1,n \rrbracket$.

[Lemma lm:o4 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $\mathcal{F}\subseteq \Phi$ be such that 
 \begin{enumerate} [label=\rm(\roman{*}), ref=\rm(\roman{*})]
     \item Uniform boundedness.
     \begin{equation}
     \sup_{\varphi\in\mathcal{F}}\sup_{\xi\in\mathfrak{X}}\varphi(\xi)<\infty    
     \end{equation}
     \item For any $R\in\mathbb{R}$ there exists $I_R\subseteq \mathfrak{X}$ compact such that\ 
     \begin{equation}
         \sup_{\varphi\in\mathcal{F}}\sup_{\xi\in I^c_R}\frac{\varphi(\xi)}{\mathcal P(\xi)^2}<R.
     \end{equation}
 \end{enumerate}
 Then $\mathcal{F}$ is sequentially compact i.e.\ any sequence in $\mathcal{F}$ has a convergent subsequence.

