body:
[Cor boundary-modification of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Let $R_{L_n}$ be as earlier, i.e., $L_n \times e^{ - \beta} \sqrt{\bar \kappa N} \sqrt{L_n}$, and let $|\Delta| = s\bar \kappa N$. Assume that 
    \begin{align*}
        \mathbf{E}^\Delta[\|\mu_t^\pm - \pi^\tau\|] \le \delta \qquad \forall \mathbf{P}\in \mathcal D(R_{L_n})\,.
    \end{align*}
    Then $\mathcal A(L_n,\tilde {t}_n,\tilde \delta _n)$ holds with $\tilde \delta_n = 8\delta_n + e^{ - e^{8\beta s\bar \kappa N}}$ and $\tilde t_n = 4\beta |E(\Lambda)|  \log 2 \cdot t_n \cdot  e^{4\beta s \bar \kappa N}$. 
    Analogously, $\mathcal A(L_n,t_n,\delta_n)$ implies $\mathbf{E}^\Delta[\|\mu_{t_n}^\pm - \pi^\tau\|]\le \tilde \delta_n$, and similar statements hold if we replace $R_{L_n}$ by $Q_{L_n}$ and $\mathcal A(L_n,\tilde t_n,\tilde \delta_n)$ by $\mathcal B(L_n,\tilde t_n',\tilde \delta_n')$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $U,V:\ZZ^d\to\RR$ are non-negative and there exists $p>1$ such that 
    \begin{equation}
        \fint_{B} U^p\,\le\,  \fint_{2B} V^p + C \Big(\fint_{2B}U\Big)^p 
    \end{equation}
    for a constant $C$ and all balls $B$. Then there exists $\bar p>p$ depending on $C$ and $p$ such that for any $p\le q \le \bar p$,
    \begin{equation}
        \fint_{B} U^{q}\,\lesssim \,\fint_{2B} V^{q} + \Big(\fint_{2B}U\Big)^{q}. 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma tightness-drift of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For each $n$, the empirical measure $\hat{\mu}_n^A$ is ${\mathbb P}$-almost surely contained in the compact set
	\begin{equation*}
		\mathcal{K}_1 \coloneqq \bigg\{\mu\in{\mathcal P}({\mathcal C}): \mu(H_0^1)=1,\ \esssup_{t\in[0,1]} \int_{H_0^1} \dot{\phi}(t)^2\,\mu(d\phi) \leq 1\bigg\}.
	\end{equation*}
	In particular, the sequence $\big\{\mathcal{L}(\hat{\mu}_n^A): n\in{\mathbb N}\big\}\subset {\mathcal P}({\mathcal P}({\mathcal C}))$ is tight.
	If $\nu=\mathcal{N}(0,1)$, the statement holds true if we replace the upper bound $1$ in the definition of $\mathcal{K}_1$ by $2/\pi$.

