[Lemma LemmaEx1 of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] If the hypotheses (equation VL4 of the paper)--(equation VL5' of the paper) and $t-s\in [0,1]$ hold then for every {$x_1,x_2\in{\mathbb R}^d$ and} $\mu_1,\mu_2{,\mu}\in \mathcal{P}_2({\mathbb R}^d)$ one has
		\begin{equation}
			\begin{array}{ll}
				W_{2}^{2}(\mathcal{X}_{s,t}(x_1,\mu_1 ),\mathcal{X}_{s,t}(x_2,\mu_2 )) \leq
				&\left\vert x_1-x_2\right\vert ^{2}(1-({ 2  }\bar{b}-{Q}_2)(t-s)) \\
				&+{Q}_2W_{2}^{2}(\mu_1 ,\mu_2 )(t-s)\\
				&+{C(1+\sum_{i=1}^2|x_i|^2+\|\mu_i\|_2^2)(t-s)^{3/2}},
			\end{array}
		\end{equation}
		and
		\begin{equation}
			\begin{array}{ll}
				{\mathbb E}[|\mathcal{X}_{s,t}(x_1,\mu )-\mathcal{X}_{s,t}(x_2,\mu )|^2] \leq
				&\left\vert x_1-x_2\right\vert ^{2}(1-({2}\bar{b}-{Q}_2)(t-s)) \\
				&{+C(1+\sum_{i=1}^2|x_i|^2+\|\mu\|_2^2)(t-s)^{3/2}}.
			\end{array}
		\end{equation}

