body:
[Lemma 18 of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix $\bS \in \bbH_+^k$, $\bT \in \sa{k}{\C}$ and $\bZ \in \bbH_+^k$, and let 
$\bB := \Im(\bS)$, $\bfeta := \bfeta(\bS,\bT)$. 
Then  the following hold:
\begin{enumerate}
\item $\bfeta$ satisfies
\begin{equation}

\Im(\bfeta) = -\bfeta\, \bB\, \bfeta^{*},\qquad \|\bfeta\|_\op \le \|\bB^{-1}\|_\op\, .
\end{equation}
\item
If $\bS$ satisfies $\bK_{\up{\alpha,\nu}}(\bS) = \bZ$, then
\begin{align}

&\int \bfeta\,\bB\,\bfeta^*\, \nu(\de\bT) 
= \frac{1}{\alpha}\bS^{-1}\bB\bS^{*-1} - \Im(\bZ),\\

&\bI = \alpha^2\, \bS\int \bfeta\,\bB\,\bfeta^*\, \nu(\de\bT)\, \bS^*\bB^{-1} 
+ \alpha\, \bS\,\Im(\bZ)\,\bS^* \bB^{-1}.
\end{align}
\end{enumerate}

