[Lemma 20 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE} and \ref{assump-particles} hold, with $\sigma\in [0,+\infty)$.
Then there exists a constant $C=C(T,k,A,\gamma,d,p)>0$ such that for any $N\in \N^*$ and any $t\in [0,T]$,

\begin{align*}
\big\| \langle v \rangle^{k} &(F^{(N)}_{t} - F_{t}) \big\|_{L^{2}_{x,v}}^2 + \frac{\sigma_{N}^2}{2} \int_{0}^t \big\| \langle v \rangle^{k} \nabla_{v}(F^{(N)}_{s} - F_{s}) \big\|_{L^2_{x,v}}^2 \dd s\\
&\leq C \, |\sigma_{N}-\sigma| \int_{0}^t \big\| \langle v \rangle^{k} \nabla_{v}F_{s} \big\|_{L^2_{x,v}}^2 \dd s + C \int_{0}^t \Big\| \langle v \rangle^{k} (u_s^{(N)} - u_s) F^{(N)}_{s} \Big\|_{L^2_{x,v}}^2 \dd s.
\end{align*}

[Definition 20 (Glauber dynamic) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Let $\mu$ denote a stationary measure on $S^V$
    with finite energy.
    A \emph{Glauber dynamic} for $\mu$ is a function
    \[
        R:S^V\times V\times\Sigma \to S^V
    \]
    with the following properties.
    \begin{itemize}
        \item\textbf{Local update.}
        For any $\alpha\in S^V$, $u\in V$ and $\iota\in\Sigma$, we have $R(\alpha,u,\iota)_v=\alpha_v$ for any $v\neq u$.
        \item\textbf{Consistency.}
        For any $\alpha\in S^V$ and $u\in V$, the distribution of $R(\alpha,u,\iota)_u$ in $\diff\iota$ is $\mu[\blank|(\alpha_v)_{v\neq u}]$.
        \item\textbf{Equivariance.}
        For any $\alpha\in S^V$, $u\in V$, $\iota\in\Sigma$ and $\theta\in\Theta$, we have $R(\alpha,u,\iota)\circ\theta=R(\alpha\circ\theta,u\circ\theta,\iota)$.
    \end{itemize}
    We shall also write $R_{u,\iota}:S^V\to S^V,\,\alpha\mapsto R(\alpha,u,\iota)$ for any $u\in V$ and $\iota\in\Sigma$.

[Thm 6 of arXiv:2608.26642, '2608.26642'] Assume that $(X,\mathbb{P}_x)$ admits transition densities $p_u(\cdot)$ for $u>0$. For $x\in \R$, we then have
\begin{align}
  \Q_x^\mu=\frac{1}{\varphi^\mu(x)}\int_0^\infty \Big((\Gamma_u^\mu\cdot\P_{x,0}^u)\bullet (\Gamma_\infty^\mu\cdot\P_0^{(0)})\Big)p_u(-x)du+\frac{h(x)\cdot \Gamma_\infty^\mu}{\varphi^\mu(x)}\cdot\P_x^{(0)},
\end{align}
where $\mathbb{P}_{x,0}^u$ denotes the \Levy\ bridge from $X_0=x$ to $X_u=0$, $\mathbb{P}_x^{(0)}$ denotes the law of the \Levy\ process conditioned to avoid zero, and the symbol $\bullet$ denotes concatenation. (Proof in the paper; no proof environment follows the statement in the TeX.)

