[Lemma 4 (Caccioppoli-type inequality) of arXiv:2609.02732, 'Conservation of mass for solutions of Leibenson's equation on Riemannian Manifolds'] Let $\Omega $ be an open subset of $M$ and let $I$ be an interval in $\mathbb{R}_{+}=[0, \infty)$. Let $u=u\left( x,t\right) $ be a bounded
		non-negative subsolution to \emph{(\ref{dtv})} in a cylinder $\Omega\times I$. Let $\eta $ be a locally Lipschitz non-negative bounded
		function in $\Omega\times I$ such that $\eta(\cdot, t)$ has
		compact support in $\Omega $ for any $t\in I$. Fix some real $\sigma $
		such that 
		$\sigma > q(p-1)$ and set $\lambda=\sigma-\delta>1$. 
		Choose $t_{1},t_{2}\in I$ such that $t_{1}<t_{2}$. Then
		\begin{equation}
			\left[ \int_{\Omega }u^{\lambda }\eta^{p} \right] _{t_{1}}^{t_{2}}+c_{1}
			\int_{t_{1}}^{t_{2}}
				\int_{\Omega}\left\vert \nabla \left( u^{\sigma/p }\eta \right) \right\vert
			^{p} \leq \int_{t_{1}}^{t_{2}}
				\int_{\Omega}\left[c_2u^{\sigma}|\nabla \eta|^{p}+pu^{\lambda}\eta^{p-1}\partial _{t}\eta\right],

		\end{equation}
		where $c_{1}, c_2$ are constants depending on $p, q$ and $\sigma$.

[Proposition 4 of arXiv:2606.22526, 'The conditional expectation of the product of the first $n-1$ Hermite polynomials in a mul'] For all $m,a\in\mathbb{R}$ and positive $\sigma$ we have

1.
\begin{gather*}
d_{n,k}(m,\sigma)=\frac{1}{\sigma\sqrt{2\pi}}\int_{-\infty}^{\infty}
H_{n}(x)H_{k}(x)\exp\left(  -\frac{(x-m)^{2}}{2\sigma^{2}}\right)  dx\\
=\sum_{j=0}^{\min(n,k)}\binom{n}{j}\binom{k}{j}j!\sum_{s=0}^{\left\lfloor
(n+k)/2\right\rfloor -j}\frac{(n+k-2j)!a^{n+k-2j-2k}}{2^{s}(n+k-2j-2s)}\\
\times(\sigma^{2}-1+a^{2})^{s}H_{n+k-2j-2s}(m/a).
\end{gather*}

2. In particular for $k\allowbreak=\allowbreak0$ we get
\begin{align*}
&  \frac{1}{\sigma\sqrt{2\pi}}\int_{-\infty}^{\infty}H_{n}(x)\exp\left(
-\frac{(x-m)^{2}}{2\sigma^{2}}\right)  dx\\
&  =\sum_{s=0}^{\left\lfloor n/2\right\rfloor }\frac{n!a^{n-2s}}
{2^{s}(n-2s)!s!}H_{n-2s}(m/a)(\sigma^{2}+a^{2}-1)^{s}.
\end{align*}

If we take $\sigma\allowbreak=\allowbreak\sqrt{1-\rho^{2}},$ $m\allowbreak
=\allowbreak\rho y$ and $a\allowbreak=\allowbreak\rho$ we get $\sigma^{2}
+\rho^{2}-1\allowbreak=\allowbreak0$ and consequently
\begin{equation}
\frac{1}{\sqrt{2\pi(1-\rho^{2})}}\int_{-\infty}^{\infty}H_{n}(x)\exp\left(
-\frac{(x-\rho y)^{2}}{2(1-\rho^{2})}\right)  dx=\rho^{n}H_{n}(y).
\end{equation}

3.
\[
\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\infty}H_{n}(\sigma x)\exp\left(
-\frac{x^{2}}{2}\right)  dx=
\begin{cases}
0\text{,} & \text{if }n\text{ is odd;}\\
\frac{(2m)!}{2^{m}m!}\left(  \sigma^{2}-1\right)  ^{m}\text{,} & \text{if
}n\allowbreak=\allowbreak2m\text{.}
\end{cases}
\]

4. If $\left[
\begin{array}
[c]{c}
X\\
Y
\end{array}
\right]  \sim N\left(  \left[
\begin{array}
[c]{c}
0\\
0
\end{array}
\right]  ,\left[
\begin{array}
[c]{cc}
1 & \rho\\
\rho & 1
\end{array}
\right]  \right)  ,$ then
\[
E\left(  H_{n}(X)H_{m}(Y)\right)  =
\begin{cases}
0\text{,} & \text{if }n\neq m\text{;}\\
n!\rho^{n}\text{,} & \text{if }n\allowbreak=\allowbreak m\text{.}
\end{cases}
\]

5.
\begin{equation}
H_{n}(\left(  X-m\right)  /\sigma)=\frac{1}{\sigma^{n}}\sum_{s=0}^{n}
(-1)^{s}\binom{n}{s}H_{n-s}(x)\sum_{j=0}^{\left\lfloor s/2\right\rfloor }
\frac{m^{s-2j}(1-\sigma^{2})^{j}}{2^{j}j!(s-2j)!}, 
\end{equation}
and in particular
\begin{equation}
H_{n}\left(  \frac{x-\rho z}{\sqrt{1-\rho^{2}}}\right)  =\frac{1}{\left(
1-\rho^{2}\right)  ^{n/2}}\sum_{s=0}^{n}(i\rho)^{s}\binom{n}{s}H_{n-s}
(x)H_{s}(iz). 
\end{equation}

6) Let us define the integer functions defined by
\begin{align*}
r_{k_{1},\ldots,k_{n}}  &  =E\prod_{j=1}^{n}H_{k_{j}}(X)\\
&  =\int_{\mathbb{R}}\left(  \prod_{j=1}^{n}H_{k_{j}}(z)\right)  f_{N}(z)dz,
\end{align*}
where $X$ is normal random variable $N(0,1).$ The generating function if this
function is equal to
\begin{equation}
\sum_{k_{1}}^{\infty}\ldots\sum_{k_{n}}^{\infty}r_{k_{1},\ldots,k_{n}}
\prod_{j=1}^{n}\frac{t_{j}^{k_{j}}}{k_{j}!}=\exp\left(  \frac{1}{2}\left(
\sum_{j=1}^{n}t_{j}\right)  ^{2}-\frac{1}{2}\sum_{j=1}^{n}t_{j}^{2}\right)  .

\end{equation}
In particular we have
\[
r_{n}\allowbreak=\allowbreak\delta_{0,n},~~r_{n,m}\allowbreak=\allowbreak
\begin{cases}
0\text{,} & \text{if }n\neq m\text{;}\\
n!\text{,} & \text{if }n=m\text{. }
\end{cases}
,
\]

\begin{equation}
r_{n,m,k}=
\begin{cases}
0\text{,} &
\begin{array}{l}
\text{if }n+m+k\text{ is odd or }n>k+m\\
\text{or }m>n+k\text{ or }k>n+m;
\end{array}
\\
\frac{m!n!k!}{(\frac{n+k-m}{2})!\left(  \frac{n+m-k}{2}\right)  !\left(
\frac{m+k-n}{2}\right)  !}\text{,} & \text{otherwise.}
\end{cases}
, 
\end{equation}

Assuming $n\geq m\geq k\geq j$ we have $r_{n,m,k,j}\allowbreak=\allowbreak0 $
