[Proposition 2 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1}--\eqref{co:3} be satisfied. Then~\eqref{eq:SIS epidemic model} admits a unique strong solution $I$ such that $I_{0} = \xi_{0}$ a.s.~and
\begin{equation}
\E\big[I_{t}\big] \leq e^{\int_{0}^{t}\hat{b}_{k+2}(s,N(s))\,\mathrm{d}s}\E\big[\xi_{0}\big] + \int_{0}^{t}e^{\int_{s}^{t}\hat{b}_{k+2}(\tilde{s},N(\tilde{s}))\,\mathrm{d}\tilde{s}}\hat{b}_{0}(s,N(s))\,\mathrm{d}s
\end{equation}
for all $t\geq 0$. Moreover, the following two assertions hold:
\begin{enumerate}[(i)]
\item If $\hat{b}_{k+2}^{+}(\cdot,N)$ and $\hat{b}_{0}(\cdot,N)$ are integrable, then $\sup_{t\geq 0}\E[I_{t}] < \infty$. In this case, we have $\lim_{t\uparrow\infty} \E[I_{t}] = 0$ as soon as $\int_{0}^{\infty}\hat{b}_{k+2}^{-}(s,N(s))\,\mathrm{d}s = \infty$.

\item If $\xi_{0} = i_{0}$ a.s.~and~\eqref{co:4} holds, then $0 < I < N$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:small-jumps of arXiv:2608.28004, 'Hausdorff Dimension of the Set of Extreme Points\\ of a Random Countable Stable Zonotope'] For every \(q>0\), there exists \(C_q<\infty\), depending only on \(d\),
\(\alpha\), and \(q\), such that
\begin{equation}
    \mathbb E\bigl[(1+M_Q)^N V_Q^{\,q}\bigr]
    \leq C_q\,\delta^{q}
\end{equation}
uniformly over all positive integers \(n\) and all \(Q\in\mathcal Q_n\).

[Definition 9 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Given regularisation scales $0 < \delta < \eps$, throughout this section, we define the smooth and stationary random noise assignment $\tilde{\pi}^{\eps, \delta}: \tilde{\mfL}_- \to C^\infty(\mbR^2)$
	\begin{align*}
		\tilde{\pi}^{\eps, \delta} \<b0> &= \xi_\eps, \quad \tilde{\pi}^{\eps, \delta} \<p0> = \xi_{\delta}, \quad \tilde{\pi}^{\eps, \delta} \<s(1)0> = \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta}
		\\
		\tilde{\pi}^{\eps, \delta} \<bs(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\eps} - \ell(\<bs(2)0>), \\
		\tilde{\pi}^{\eps, \delta} \<ps(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\delta} - \ell(\<ps(2)0>),
	\end{align*}
	where $\ell(\<bs(2)0>)$ and $\ell(\<ps(2)0>)$ are such that $\mathbb{E}[\tilde{\pi}^{\eps, \delta} \tau(0)] = 0$ for $\tau \in \{\<bs(2)0>, \<ps(2)0>\}$.

	We write $\tilde{Z}^{\eps, \delta} = (\tilde{\Pi}^{\eps, \delta}, \tilde{\Gamma}^{\eps, \delta})$ for the corresponding BPHZ model.

[Prop 9 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For every $\varepsilon \in (0,1)$ and $\rho \in [0,1)$
    \begin{equation}
        \lim_{N \to \infty} \sup_{\omega \in \Omega_{\lambda,\Lambda}} \sup_{\cS} \sup_{z \in V_N^\varepsilon}P^\omega_z [H_S = \infty] = 0 \,.
    \end{equation}

