[Lemma Palm-Lcal-ij of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For $l\neq r, k=1,2$ and for all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
\lefteqn{ \frac{\Lambda^{(k)}_{l,r}}{4\lambda_1\lambda_2 v_1v_2} \mathbb{E}^0_{{\mathcal V }^{(k)}_{l,r}} [f ({\mathcal H })]}{\nonumber}\\
& = \int_{0}^\infty  \int_{0}^h \int_{t^*}^\infty 
\mathbb{E}_{\mathcal H }\Bigg[ f \left(\theta_{\hat{s}_k(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')})\right) \prod_{i=1,2}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
	\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h {\nonumber}\\ 

    &\, +  \int_{0}^\infty  \int_h^\infty \int_0^{\infty}
	\mathbb{E}_{\mathcal H }\Bigg[ f \left(\theta_{\hat{s}_k(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')})\right) \prod_{i=1,2}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
	\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h ,
{\nonumber}
\end{align}

where, $(\hat{s}_k(t,h,t',h'),\hat{h}_k(t,h,t',h'))$
are the coordinates of the $k$-th intersection of the two radial birds with heads $(t,h)$ and $(t',h')$ of type $r$ and $l$, respectively, $t^*=\frac{1}{v_1v_2}(h^2-h'^2)^{\frac{1}{2}} (v_1^2-v_2^2)^{\frac{1}{2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+1
  +\mu(\kappa)+2\mu(\floor{\kappa/2}).
\end{equation}
In particular,
\begin{equation}
  e=\kappa-1\le3m-6.
\end{equation}

