[Corollary 10 (Likelihood-to-prior force ratio) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] Assume the conditions of Corollary~\ref{cor:general-high-noise-energy} and
$d^{-1}\Tr\Cov(X_0)\le C_0$.  Then, for every $t>0$,
\begin{equation}

\frac{\E\|g_t(X_t,R)\|^2}
{\E\|s_t^{\rm prior}(X_t)\|^2}
\le
\frac{C_0(a_t^2C_0+\Delta_t)}{\Delta_t^2}\,a_t^2.
\end{equation}
Consequently, on every high-noise window where $\Delta_t\ge\Delta_0>0$,
\begin{equation}

\frac{\E\|g_t(X_t,R)\|^2}
{\E\|s_t^{\rm prior}(X_t)\|^2}
\le
\frac{C_0(C_0+1)}{\Delta_0^2}\,a_t^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_eta_norm of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] By the Perron-Frobenius theorem, the principal eigenvalue $\mu$ of the strictly sub-stochastic and irreducible matrix $P$ satisfies $\mu \in (0,1)$, the multiplicity of $\mu$ is equal to $1$ and there is a unique right eigenvector $\eta$ with non-negative coordinates that  satisfies $P\eta=\mu \eta$, moreover $\Vert \eta \Vert_{\infty}=1$ and
     \begin{equation}
         \eta_{min} := \min_{x \in V} \eta_x >0.
     \end{equation}
      We define the $\eta$-norm of a vector $w\in \mathbb{R}^{V}$ by 
      \begin{equation}
      \Vert w \Vert_{\eta} = \sum_x |w_x| \cdot  \eta_x.\end{equation}

[Lemma 8 of arXiv:2512.01483, 'Scaling Limits of Line Models in Degenerate Environment'] For all fixed $t > 0$, we have the almost-sure convergence
    \begin{equation}

    \frac{D^{V,T}(t)}{D^T(t)} = \frac{\int_0^{Tt} \frac{H^{(T)}(Y_2^T(s))}{V(Y_1^T(s))} \, ds}{\int_0^{Tt} H^{(T)}(Y_2^T(s)) \, ds}\underset{T \to \infty}{\longrightarrow} 1.
    \end{equation}

[Mainthm 4 (Theorem~\ref{maintheorem}) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] Let $S$ be a Dedekind scheme of characteristic zero, and
let $f:X \rightarrow S$ be a projective surjective morphism from a normal integral scheme. Suppose that every non-closed point $x\in X$ satisfies one of the following conditions:
\begin{enumerate}
\item $(x\in X)$ is of equal characteristic zero and of klt type.
\item $(x\in X)$ is of mixed characteristic and of BCM-regular type.
\end{enumerate}
Then Conjecture~\ref{mainconj} holds for $f$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Global-solution-definition-SES of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] An $\{\mathcal{F}_t\}$-progressively measurable $\mathbf{H}$-valued process $X=(X(t))_{t\ge0}$ with càdlàg paths in $\widetilde{\mathbf{H}}$ is called a global solution to (equation SES of the paper) with initial data $X_0 \in \mathbf{H}$ if the following conditions hold $\mathbb{P}$-$\mathrm{a.s.}$:
		\begin{enumerate}[label={\rm(\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $\sup_{t\in[0,T]}\|X(t)\|_{\mathbf{H}}<\infty$ for every $T>0$;
			\item the integral equation (equation SES of the paper) holds identically for all $t\ge0$ as an equality in $\widetilde{\mathbf{H}}$.
		\end{enumerate}

[Lemma l5.3 of arXiv:2411.19255, 'Moderate, large and super large deviations principles for Poisson process with uniform cat'] The family of random variables $\frac{1}{\varphi(T)}\big(\nu_1(T)-\nu_1(T-c\varphi(T))\big)$ satisfied LDP with
normalized function $\psi(T)=\varphi(T)$ and with rate function
$$
\tilde{I}(x)= \left\{
           \begin{array}{lcl}
                              \ \infty,  \text{ if }\ x\in (-\infty,0),\\
                              x\ln\left(\frac{x(\lambda+\mu)}{\alpha\lambda c}\right)-x+\frac{\alpha\lambda c}{\lambda+\mu}, \text{ if }\ x\in [0,\infty).\\
                              \end{array}
                              \right.
$$

