[Prop uniqueness of solution for single-location master loop equation in the 't Hooft limit of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Given any $L\geq 1$, there exists $\upbeta_*(L,d)>0$ such that if $|\upbeta|\leq \upbeta_*(L,d)$, then there is a unique function $\phi_{\infty}:\mathcal{S}\to \mathbb{R}$ such that 
\begin{enumerate}
	\item $\phi_{\infty}(\emptyset) = 1$;
	\item $\phi_{\infty}$ is invariant under backtrack erasures, i.e.\ for any loop $\ell = \pi_1ee^{-1} \pi_2$, we have that $\phi_{\infty}(\ell) = \phi_{\infty}(\pi_1\pi_2)$;
	\item $|\phi_{\infty}(s)|\leq L^{|s|}$, for all $s\in \mathcal{S}$;
	\item $\phi_{\infty}(s)$ satisfies the master loop equation (equation eq:limiting_master_loop_eq of the paper),  for all non-empty $s\in \mathcal{S}$.
\end{enumerate}

[Lemma lem:ising-slepian of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] The processes defined in~(equation def:X of the paper) and~(equation def:tildeX of the paper) satisfy
		\[
		\mathbb{E}
		\sup_{\substack{\mathbf{m}\in[-1,1]^N\\ \alpha\in\mathbb{N}^L}}
		X(\mathbf{m},\alpha)
		\le
		\mathbb{E}
		\sup_{\substack{\mathbf{m}\in[-1,1]^N\\ \alpha\in\mathbb{N}^L}}
		\widetilde X(\mathbf{m},\alpha).
		\]

[Lemma 3 of arXiv:2605.27742, 'Multidimensional Stein's method for asymptotic independence with invariant measures of dif'] Define, for all $x \in (l, u)$,
	\begin{equation}
		S(x) := \frac{8 \left( \int_{l}^x F(w)\,\mathrm{d}w \right)
			\left( \int_{x}^{u} (1 - F(w))\,\mathrm{d}w \right)}{a(x)^2\,p(x)}.
	\end{equation}
	Then $S$ is bounded on $(l, u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 7 (Aru-Lupu-Sep\'ulveda \cite{ALS1}) of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $a<v$.
The measure $\nu_{A_a}$ is a.s. finite, positive and supported on $A_{a}$.
Moreover, its compact support equals a.s. the whole $A_{a}$,
that is to say a.s., for every $U$ open subset of $\C$
such that $A_a\cap U\neq \emptyset$,
$\nu_{A_a}(U)>0$.
The measure $\nu_{A_a}$ can be described as follows:
\begin{eqnarray*}
\nu_{A_a} &=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a}, \CR(z,D\setminus A_{a})<\varepsilon \CR(z,D)} d^{2} z
\\
&=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a},d(z,A_{a})<\varepsilon d(z,\partial D)} d^{2} z
,
\end{eqnarray*}
where the convergence is a.s., for the weak topology on measures.
Fix a deterministic continuous cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$.
Then
\begin{eqnarray*}
f_0\,\nu_{A_a} &=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a}, \CR(z,D\setminus A_{a})<\varepsilon} f_0(z)d^{2} z
\\
&=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a},d(z,A_{a})<\varepsilon} 
f_0(z) d^{2} z
.
\end{eqnarray*}
Moreover, if 
\begin{equation}

\operatorname{Leb}(\{ z\in D\vert d(z,\partial D)<\varepsilon\})
=
o(\vert \log\varepsilon\vert^{-1/2}),
\end{equation}
then
\begin{eqnarray}

\nu_{A_a} &=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a}, \CR(z,D\setminus A_{a})<\varepsilon} d^{2} z
\\
\nonumber
&=& \lim_{\varepsilon \to 0}
\dfrac{1}{2} \vert \log\varepsilon\vert^{1/2} \ind_{z\in D\setminus A_{a},d(z,A_{a})<\varepsilon} d^{2} z
.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:FO-derivative of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:integrand-influence}
Let
\[
 F_O(J)=e^{\Psi_O(J)}.
\]
For each \(1\le r\le m+1\),
\begin{equation}
 \left\lvert\partial_I^rF_O(J)\right\rvert\le C_rq_N^rF_O(J),
\end{equation}
uniformly over \(O\in\mathcal O_{N,L}\), \(I\in[N]^p\), and \(J\in\mathbb R^{N^p}\).  The same estimate holds for
\begin{equation}
 F(J):=\mathcal Z_{N,L}^J(V,\varepsilon,f).
\end{equation}

[Lemma 29 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $J\subseteq [n]$, $f:\cube^n\to \Rbb$, $p\in [1,2]$ and $q\in [1,2)$,
\begin{equation*}
    \left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq \Vop_J(f) \left[1+\frac{q}{2|J|(2-q)} \ln^{+}\left(\frac{\Vop_J(f)}{\left\|\Dop_J f\right\|_{\Leb^q}^{2}}\right)\right]^{|J|}.
\end{equation*}

