[Proposition Proposition3 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that (A1 of the paper)-(A7 of the paper) hold and that $\varphi$ is an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$,  satisfying (C1 of the paper)-(C3 of the paper). Then, for every $t \in \mathbb{R}$, 
\begin{align}
\mathcal{Z}^{\varphi}_{t} \coloneqq \sum_{u \in \mathcal{I}} \varphi_{u}(t- S(u))
\end{align}
\noindent converges unconditionally in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$ and almost surely over every admissible ordering of $\mathcal{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm jointr1r2 of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix integers $2 \le r_1 < r_2$. Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same set of vertices $V_n$, such that 
$H_n^{(1)}$ is $r_1$-uniform, $H_n^{(2)}$ is $r_2$-uniform, $|E(H_n^{(1)})| \to \infty,$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold: 
      \begin{itemize}
      \item  There exist constants $\lambda_1, \lambda_2 \ge 0$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r_1-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r_2-1}} \to \lambda_2 . 
            \end{align}

      \item  For all $t_1 \in [2, r_1 - 1]$ and $t_2 \in [2, r_2 - 1]$, 
      \begin{align}
      \frac{|\cK(t_1, H_n^{(1)})|}{c_n^{2r_1-t_1-1}} \to 0 \text{ and } \frac{|\cK(t_2, H_n^{(2)})|}{c_n^{2r_2-t_2-1}} \to 0 , 
      \end{align} 
     where $\cK(\cdot, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
  $$\bm T(\bm H_n)= \left(\begin{array}{l}
    T(H_n^{(1)}) \\
    T(H_n^{(2)})
    \end{array}\right) \dto \left(\begin{array}{l}
      Z_1\\
      Z_2
      \end{array}\right) , $$
    where $Z_1 \sim \Pois(\lambda_1), Z_2 \sim \Pois(\lambda_2)$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

