[Prop F-Borel of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] The following assertions hold:
\begin{enumerate}	
\item[\rm(1)] The set $F$ is Borel measurable.
\item[\rm(2)] The process $\check{\mathbb{X}}$ with state space $F$ is a Borel right-continuous Markov process.
\end{enumerate}

[Corollary 2-l13 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix a finite subset $D$ of ${\mathbb Z}^d$. Then, there exists a finite
constant $C_0$, depending only on $D$ and the bounds (equation 2-38b of the paper),
(equation 2-84 of the paper) on the density profile, such that
\begin{align*}
& {\mathbb E}_{\nu^N} \Big[ \, \Big|\, \int_s^t \sum_{x\in {\mathbb T}^d_N} G_x(r)\,
\omega_{x+D}(r) \; dr \,\Big|^\alpha\,\Big] \\
&\qquad \;\le\; C_0 \,
N^{\alpha d/2} \, |t-s|^\alpha \, \sup_{s\le r \le t} \Vert G(r) \Vert^\alpha _\infty \,
\sup_{s\le r\le t} \big( \, 1 \,+\,
H_N(f^N_r)\,\big)^{\alpha /2} 
\end{align*}
for all $1\le \alpha\le 2$, $0<s<t$,
$G\colon [0,T]\times {\mathbb T}^d_N \to{\mathbb R}$ and $N\ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:boosted small of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] There exists a constant $C>0$ such that for any $v\in [n]$ and for any $t \geq 1$, the random variable $\phi_n^{{\scriptscriptstyle{({2}})}}(v)$ satisfies 
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v) \leq \left( \frac{n}{t v} \right)^2 \right) \leq C \frac{1+\log t}{t^2},
    \end{equation}
    Furthermore, for every $\varepsilon > 0$, there exists a constant $c>0$ so that for any $n\geq 3$, $v\in [n/4]$ and $t\in\big(\sqrt{2},\tfrac{n}{v \sqrt{3}} \wedge (n/v)^{1-\varepsilon}\big)$,
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v)
    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{\log t}{t^2}.
    \end{equation}
    Moreover, there exists a constant $c^\prime>0$ so that for any $n\geq 3$, $v\in [n/4]$ and $t\in\big(1, \frac{1}{\sqrt{3}} (n/v) \big)$,
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v)
    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{1}{t^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

