[Lemma repl_lemma_ave of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For every $H \in C([0,T])$, for any $t \in [0,T]$ and $z=\epsilon_N$, it holds
\begin{equation} 
\lim_{\epsilon\to 0}\lim_{N\to+\infty}\mathbb{E}_{\nu_N} \left[\Big | \int_0^t [\eta_{sN^2}(z) - \overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}(z)] H(s)ds\Big| \right] =0,
\end{equation}
where, for every $L\in\mathbb N$ and $\eta \in \Omega_N$,
\begin{equation} 
\overrightarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y= z+\epsilon_N}^{z+L\epsilon_N}\eta(y).
\end{equation}
The same result holds for $z = \tau_N$ by replacing the average to the right, i.e. $\overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, by an average to the left, i.e. $\overleftarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, which is defined, for every $L\in\mathbb N$ and $\eta \in \Omega_N$, as
\begin{equation}
 \overleftarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y=z-L\epsilon_N}^{z-\epsilon_N}\eta(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2604.16795, '2604.16795'] Under Assumption {\rm\ref{A0}} and \eqref{ass},  the probability measure $\nu$ defined by
	\begin{align}
		\nu(\d x) = \frac{\va_0(x)}{\displaystyle\int_{\R^d} \va_0(y) \,\mu(\d y)} \,\mu(\d x)
	\end{align}
	is the unique quasi-stationary distribution for the Feynman-Kac semigroup $(P_t)_{t\ge 0}$ associated with the branching-diffusion process $(Z_t)_{t\ge 0}$ $($see \eqref{E:FK} below$)$. 
 That is, for any $t>0$ and any bounded measurable function $\phi$, it holds that
	\begin{align}
		\int_{\R^d} \mathbb{E}_x \left[ \exp\left(-\int_0^t K(X_s) \,\d s\right) \phi(X_t) \right] \nu(\d x) = e^{-\lambda_0 t} \int_{\R^d} \phi(x)\, \nu(\d x).\end{align}
	In particular,
	\begin{align}
		\frac{\displaystyle\int_{\R^d} \mathbb{E}_x \left[ \exp\left(-\int_0^t K(X_s)\, \d s\right) \phi(X_t) \right] \,\nu(\d x)}{\displaystyle\int_{\R^d} \mathbb{E}_x \left[ \exp\left(-\int_0^t K(X_s) \,\d s\right)\right] \,\nu(\d x)} = \int_{\R^d} \phi(x) \,\nu(\d x).\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Let \(p\ge 2\) and \(\gamma\in(\frac{1}{2},H)\). Under \textbf{H1}--\textbf{H3}. As \(\epsilon\) tends to zero, there exists a \(\kappa>0\) such that
\begin{eqnarray}
\|x^\epsilon-\bar x\|_{\gamma,p} \le C_{x_0,T} \epsilon^\kappa 
\end{eqnarray} 
where \(C_{x_0,T}>0\) only depends on \(x_0\) and \(T\) and \(\bar x\) is the solution to the deterministic ODE \eqref{averaged1-system}.
Moreover, \(\bar g\) is globally Lipschitz continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Push-TASEP-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator $B_{\mathbf{a},\mathbf{n}}$ satisfies:
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item For all $i > j$ and $r, r' \in \mathbb{Z}$,
\begin{equation}
[B_{\mathbf{a}+\mathbf{1}}]_{ij}(r{+}1, r'{+}1)
= [B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r').
\end{equation}

\item For all $i > j$ and $r, r' \in \mathbb{Z}$,
\begin{equation}
[B_{\mathbf{a}+\mathbf{1}}]_{ij}(r, r')
- [B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r')
= \sum_{j < \mu < i}
[B_{\mathbf{a},\mathbf{n}}]_{i\mu}(r, a_\mu{+}1)[B_{\mathbf{a}+\mathbf{1}}]_{\mu j}
(a_\mu{+}1, r').
\end{equation}

\item The propagator is $t$-independent and
invariant under uniform shifts of the particle
labels: replacing each $n_i$ by $n_i + 1$ leaves
$[B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r')$ unchanged.
\end{enumerate}

[Lemma eq:reweight_by_two of arXiv:2506.10765, 'A General Coupling for Ising Models and Beyond'] Let $G=(V,E)$ be a finite  graph. Let $A\subset V$ with $|A|$ even (could be $0$). Then, $\forall \omega\in\{0,1\}^E$,
\begin{align}
2^{\abs{\omega}} (\ell^A_x \cup \mathbb{P}_p)[\omega] \propto \left(\ell^A_{\frac{2x}{1+p}} \cup \mathbb{P}_{\frac{2p}{1+ p}}\right)[\omega].
\end{align}
   In particular, with the usual $t=(t_e)_{e\in E}$ and $J=(J_e)_{e\in E}$, it holds that
\begin{align}
       2^{\abs{\omega}} (\ell^A_t \cup \mathbb{P}_{t^2})[\omega] \propto \mathbf{P}^A_{2J}.
   \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Assume that Assumptions \ref{assumption:ass1} and \ref{assumption:ass2} hold. Then for any given $T>0$ the process $U_t$ given by \eqref{eq:converge} is a unique solution to the free SDE \eqref{eq:fSDE}, i.e., 
\begin{equation}
U_t = U_0 + \int_0^t \alpha(U_s) {\rm d}s + \int_0^t \beta(U_s) {\rm d}W_s \gamma (U_s)
\end{equation}
for $t \in [0, T].$ Moreover,
\begin{equation*}
\sup_{t \in [0, T]} \|U_t\|_2 < \infty. 
\end{equation*}

