\begin{equation*}
\widetilde{T}_M:=\inf\{t\in[0,T]: \sup_{n\in\mathbb{N}}\|U^{(n)}_{\kappa(n,t)}\|_2\vee \|U_t\|_2>M\}\wedge T.
\end{equation*} 

Hence, the local Lipschitz property of $\alpha$ implies
\begin{equation*}
\begin{split}
\biggl\|\int_{0}^{t \wedge \widetilde{T}_M} \alpha\bigl(U^{(n)}_{\kappa(n,s)}\bigr) \, {\rm d}s 
- \int_{0}^{t \wedge \widetilde{T}_M} \alpha(U_s) \, {\rm d}s \biggr\|_2 
&\leq \int_{0}^{t \wedge \widetilde{T}_M} 
\bigl\| \alpha\bigl(U^{(n)}_{\kappa(n,s)}\bigr) - \alpha(U_s) \bigr\|_2 \, {\rm d}s \\
