[Prop maximum-inequality of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Fix $\omega \in \Omega$. Let $u: \mathbb{Z}^d \to \mathbb{R}$ be either non-negative $L^\omega$-subharmonic $(-L^\omega u \leq 0)$,  or $L^\omega$-harmonic $(L^\omega u = 0)$ on $B(x, n)$, for some $x\in \mathbb{Z}^d$. Then for $p, q\in (1, \infty]$ with $1/p+1/q <2/d$, there exist constants $\kappa = \kappa(d, p, q) \in (1/2, \infty)$ and $C_{\mathrm{Max}}= C_{\mathrm{Max}}(d, p, q)$ such that for all $1/2 \leq \sigma' < \sigma \leq 1$,
\begin{align}

    \norm{u}_{\infty, B(x, \sigma'n)} \leq C_{\mathrm{Max}}\bigg( \frac{ \norm{\mu^{(2), \omega}}_{p, B(x, \sigma n)}\norm{\nu^\omega}_{q, B(x, \sigma n)}}{(\sigma - \sigma')^2}\bigg)^\kappa \norm{u}_{2p_*, B(x, \sigma n)},
\end{align}
where $p_*=p/(p-1)$ is the Hölder conjugate of $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 (rigidity lemma) of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $\Cl,\cl>0$ such that for any distinct $v,v',w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\ge d$, and any events $\mathsf{A}$ and $\mathsf{A}'$ increasing with respect to $\mathcal{C}_{v}$ and $\mathcal{C}_{v'}$ respectively, 
  	\begin{equation}
  		\begin{split}
  		 	\mathbb{P}\big(\mathsf{A} \mid  \big\{v\xleftrightarrow{} w \Vert \mathsf{A}' \big\}\big) 
  			\le   & \Cref{const_app_switch1} \Big[  \mathbb{P}\big(\mathsf{A}  \mid  v\xleftrightarrow{} w  \big) + \mathrm{exp}\big( -\cref{const_app_switch2}|v -w |^{\frac{d}{2}-1}\big)\Big]. 
  		\end{split}
  	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2609.02175, '2609.02175'] Let $V_j(x)=v_j(|x|)$, $j=1,2$, satisfy the short-range condition
	\eqref{eq:short-range} and assumptions
	\eqref{eq:radial-assumptions-intro}--\eqref{eq:radial-monotonicity-intro}.
	Fix an incoming direction $\omega\in\mathbb S^{n-1}$ and assume that
	\begin{equation}
		\frac{d\sigma_{1,h}}{d\Omega}
		(\omega,\theta;\lambda)
		-
		\frac{d\sigma_{2,h}}{d\Omega}
		(\omega,\theta;\lambda)
		\longrightarrow0,
		\qquad h\longrightarrow0,
	\end{equation}
	for every $\theta\in\mathbb S^{n-1}\setminus\{\omega,-\omega\}$.
	Then
	\begin{equation}
		r_{1,\lambda}=r_{2,\lambda}=:r_\lambda,
	\end{equation}
	and
	\begin{equation}
		V_1(x)=V_2(x),
		\qquad |x|\geq r_\lambda.
	\end{equation}
	In particular, the semiclassical differential cross section at the
	single energy $\lambda$, for one fixed incoming direction, determines
	the potential throughout the classically accessible region. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:weak_sol_MKV of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let \textcolor{black}{$\nu\in \mathcal{P}(\mathbb{R}^d)$}. A (weak) solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\nu})$ 
is a 
(general) solution to MKV$({\bf b},{\boldsymbol\sigma})$ such that
\begin{equation}
[X_0] =  \nu. \vspace{-10pt}
\end{equation}

[Lemma 103 (Raychaudhuri-type transport equation for $\mytr_{\gtorus}\upchi$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identity holds:
	\begin{align}  
		\upmu \Lunit \mytr_{\gtorus}\upchi 
		& = \Lunit \upmu \mytr_{\gtorus}\upchi - \upmu \Ricfour_{\Lunit \Lunit} - \upmu |\upchi|^2. 
	\end{align}

[Conjecture conj:main of arXiv:2607.05345, 'The local product condition implies cutoff'] A cutoff occurs as soon as 
		\begin{eqnarray}

			\gamma\times \mathrm{t}_{\textsc{mix}}(\varepsilon) & \xrightarrow[n\to\infty]{} & +\infty,
		\end{eqnarray}
		for some $\varepsilon\in(0,1)$, where $\gamma$ denotes the Poincaré constant of the considered process. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma lem:adm_scaled_exp_delta of arXiv:2607.04514, 'Boundary-layer asymptotics for Gaussian-smoothed singular measures'] Assume (ass:standing of the paper)~(ass:standing:chart of the paper){} with \(r\geqslant 2\). Let \(A,\sigma_0>0\) and \(R_0\in(0,4R)\). Then there
  exists \(\mathscr R_\Delta\in \mathfrak P_{r-2}\) defined on \(\mathcal
  D_{R_0,A,\mathcal{K}_{\mathcal{S}},\sigma_0}\), such that
  \begin{equation}
    \sigma^{-1}\Delta(\theta,\sigma\zeta)
    = \begin{bmatrix} \mathbf{L}(\theta)\\ \mathbf 0_{k\times m}
    \end{bmatrix}\,\zeta + \frac\sigma2\mathrm{D}_\xi^2 \Delta(\theta, 0)[\zeta,\zeta]
    + \sigma^2 \mathscr R_\Delta(\zeta;a,\varphi(\theta),\sigma).
  \end{equation}

