body:
[Thm 76 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $\alpha>1$. Then, for any $\displaystyle E\in \left(0,\frac{2}{11}\left[(1-\alpha^{-1})\wedge \frac{1}{2}\right]\right),K\in (0,\infty)$, and $0<T_1<T_2<\infty$,
it holds that
\begin{equation}
  \sup_{x\in\R}\Big|P_0(X_t\leq x)-P_0^n(X_t^n\le x)\Big|=O(n^{-E}),
\end{equation}
and
\begin{equation}
  \lim_{n\to\infty}n^{\frac{2}{3}E}\sup_{\substack{|x|\le K\\t\in [T_1,T_2]}}\left| p(t,0,x)-p_n\left( t,0,\frac{\floor{nx}}{n} \right) \right|=0,
\end{equation}
$\bbP$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:conditional-log-loss of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] There is an absolute constant $C_0$ such that, for every sufficiently large $n$ and every $m\leq k<k_*$,
\begin{equation}
 \mathbb{E}(\widetilde\ell_k\mid\mathcal{F}_k)\leq C_0
 \qquad\text{almost surely}.
\end{equation}

[Theorem th:equiv_MP_weak of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$, $\nu\in\mathcal{P}(\mathbb{R}^d)$, and let $\mathbb{P}$ be a probability measure on $(C_{[s,T)}, \mathcal{B} )$, such that
\begin{equation}
b, \sigma \sigma^\top \in L^{1}_{\text{loc}}([s,T) \times \mathbb{R}^d , \overline{\boldsymbol\mu}), 
\end{equation}

where $\overline{\boldsymbol\mu}$ is as in Notation (not:measure_dt_dx of the paper), with ${\boldsymbol\mu}_t:=\mathbb{P}(x_t \in dx)$, $t\in [s,T)$.
Then $\mathbb{P}$ is a solution to MP$({\bf b},{\boldsymbol\sigma};s,\nu)$ if and only if there exists a (weak) solution $X$ to SDE$({\bf b},{\boldsymbol\sigma};s,\nu)$ such that $[X] =\mathbb{P}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def Def_convexity of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nondegenerate interval.
 A function $L:I\to\mathbb{R}$ is called convex if
 \begin{align}
   L(tx+(1-t)y) \leqslant tL(x) + (1-t)L(y), \qquad t\in[0,1],\; x,y\in I.
 \end{align}
Further, $f$ is called strictly convex if strict inequality holds in (equation def_convex of the paper) for all $t\in(0,1)$ and $x\ne y$, $x,y\in I$.

[Proposition 6 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] The estimator \(C_{\varepsilon, \delta}\) admits the following decomposition into orthogonal Wiener chaoses
\begin{equation}

C_{\varepsilon, \delta} = c_m^2T_0 + \sum_{r=0}^{m-1} \left(\frac{c_m m!}{(m-r)!\sqrt{r!}}\right)^2T_{2m-2r}
\end{equation}
where the index \(2m-2r\) records the order of the Wiener chaos to which each term \(T_{2m-2r}\) belongs, and
\begin{multline}
T_{2m-2r} = \\  N^{2H'-1}\alpha(\varepsilon,H^*(m))^2I_{2m-2r}\left(\sum_{k=0}^{N-1}\int_{k\delta}^{(k+1)\delta}(\tau_s K^{\varepsilon})^{\otimes m}ds\otimes_r \int_{k\delta}^{(k+1)\delta}(\tau_s K^{\varepsilon})^{\otimes m}ds\right),
\end{multline}
and
\begin{equation}
c_m^2T_0 = \mathbb{E}[C_{\varepsilon, \delta}].
\end{equation}
The combinatorial weights \(\bigl(\tfrac{c_m m!}{(m-r)!\sqrt{r!}}\bigr)^2\) are the normalisation constants from the product formula for multiple Wiener--Itô integrals.

[Theorem thm:unrestricted-FG-mgle-barycenter-final of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] Let
\[
\mathbb{X}^k:=\mathbb{G}^{L^k}\in\mathcal{FG}_{\mathrm{mgle}}(T,d),
\qquad k\in[K].
\]
Then the unrestricted adapted barycenter problem
\begin{equation}

\inf_{\mathbb{Y}\in\mathrm{FP}_2}
\sum_{k=1}^K\lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})
\end{equation}
admits a representative \(\mathbb{G}^{
\accentset{\overline{\hphantom{L}}}{L}
}\in\mathcal{FG}_{\mathrm{mgle}}(T,d)\).  It may be chosen
as follows.  For every \(t\in[T]\), choose orthogonal matrices
\( Q_t^1,\ldots, Q_t^K\in\mathscr O(d)\) minimizing
\begin{equation}

\sum_{k=1}^K\lambda_k\|L^k_{t,t}\|_F^2
-
\left\|\sum_{k=1}^K\lambda_kL^k_{t,t} Q_t^k\right\|_F^2.
\end{equation}
Set
\begin{equation}

\accentset{\overline{\hphantom{L}}}{L}
_{t,t}:=\sum_{k=1}^K\lambda_kL^k_{t,t}\mathbf Q_t^k,
\qquad

\accentset{\overline{\hphantom{L}}}{L}
_{r,t}:=
\accentset{\overline{\hphantom{L}}}{L}
_{t,t},\quad r\ge t.
\end{equation}
Then \(\mathbb{G}^{0,
\accentset{\overline{\hphantom{L}}}{L}
}\) solves (equation eq:unrestricted-mgle-input-problem-final of the paper).  Equivalently,
its one-step covariance blocks are characterized by
\begin{equation}

\accentset{\overline{\hphantom{L}}}{L}
_{t,t}
\accentset{\overline{\hphantom{L}}}{L}
_{t,t}^{\intercal}
\in
\argmin_{\Sigma\in\mathscr S_+(d)}
\sum_{k=1}^K\lambda_k
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},\Sigma
\right),
\qquad t\in[T].
\end{equation}
The barycenter value is
\begin{equation}

\sum_{t=1}^T(T-t+1)
\min_{\Sigma\in\mathscr S_+(d)}
\sum_{k=1}^K\lambda_k
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},\Sigma
\right).
\end{equation}
In particular, for every martingale candidate \(\mathbb{G}^{0,M}\in\mathcal{FG}_{\mathrm{mgle}}(T,d)\),
\begin{equation}

\mathcal{AW}_2^2(\mathbb{G}^{0,L^k},\mathbb{G}^{0,M})
=
\sum_{t=1}^T(T-t+1)
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},
M_{t,t}M_{t,t}^{\intercal}
\right).
\end{equation}
If the minimizer in (equation eq:mgle-local-BW-covariance-final of the paper) is unique for every
\(t\), then the barycenter is unique at the level of one-step increment covariances.
This uniqueness holds, for instance, whenever for each \(t\) at least one matrix
\(L^k_{t,t}(L^k_{t,t})^{\intercal}\) is positive definite.

[Defn ent of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Given a discrete representation $\rho:\pi_1(S) \to \mathrm{PSL}_n(\mathbb{C})$, we define its Hilbert entropy to be:
\begin{equation}
H(\rho) =  \limsup\limits_{L\to \infty} \displaystyle\frac{\log \#\{[\gamma] \text{ a conjugacy class in } \pi_1(S)\ \vert\ l^H_\rho(\gamma) \leq L\}}{L}
\end{equation}
where $l^H_\rho(\gamma)$ is the Hilbert length of $\gamma$ with respect to $\rho$.  The \textit{translation length entropy} $E(\rho)$ is defined by the same expression, replacing $l^H_\rho(\gamma)$  by   the \textit{translation length} $\ell_\rho(\gamma)$ of $\rho(\gamma)$.

[Lemma LemmaRegularizedDriftBound2d of arXiv:2608.11178, 'A submartingale for the probability of avoiding the origin in one-point interaction ground'] Let \(T, \gamma>0\). There exists a constant
\(C=C(\gamma,T)>0\) such that, for all \(0<t\le T\) and all
\(x\in\mathbb R^2\setminus\{0\}\),
\begin{align}
\bigl|\widehat b_t^\gamma(x)\bigr|
\le{}&
\frac{
C\,|x|
}{
t\left(
1+\log^+\dfrac1{\gamma t}
\right)
}
\mathbf 1_{\left\{
0<|x|<
\min\left\{
\sqrt{2t},\frac12
\right\}
\right\}}
+
\frac{
C
}{
|x|
\left(
1+\log\dfrac1{|x|}
\right)
}
\mathbf 1_{\left\{
\sqrt{2t}\le |x|\le\frac12
\right\}}
+
C\mathbf 1_{\left\{
|x|>\frac12
\right\}}. \nonumber
\end{align}

