[Lemma lem:elementary-expansion of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For $a_n=d/n$,
\begin{equation}
  R_n=\sum_{k=0}^{d}
  \frac{(d)_k}{(n)_k}e_k(\delta),

\end{equation}
where $(q)_k=q(q-1)\cdots(q-k+1)$. If
\begin{equation}
  P_n=\prod_{i=1}^n(1+a_n\delta_i)
  =\sum_{k=0}^n a_n^k e_k(\delta),

\end{equation}
then
\begin{equation}
  \mathbb{E}|R_n-P_n|^2\longrightarrow0.

\end{equation}
Moreover,
\begin{equation}
  \sup_n\mathbb{E} R_n^2<\infty.

\end{equation}

[Theorem prop:uniform-time-avg-poc of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:poc of the paper) hold. Recall the constant $c_0$ from Lemma~(lem:finite-time-poc of the paper). Then, there exists a finite constant $C>0$ such that, for any $\delta>0$ and all sufficiently large $N$,
\begin{equation}
\sup_{T>0}
\mathbb E\,\left[\mathsf{KSD}_\pi\bigl(\overline\mu_T^N,\overline\mu_T\bigr)\, \mathbf{1}_{\{\int \|x\|^2 \mu^N_0(dx) \le R\}}\right]
\le C N^{-\beta/2}\exp\{c_0(1+R)(\log N)^{c_0\delta}\} + C(\delta\log\log N)^{-1/2}.
\end{equation}
Consequently,
\begin{equation}
    \lim_{M \to \infty} \, \limsup_{N \to \infty}\,\sup_{T>0}\mathbb{P}\left[\mathsf{KSD}_\pi\bigl(\overline\mu_T^N,\overline\mu_T\bigr) \ge M (\log \log N)^{-1/2}\right] = 0.
\end{equation}
Moreover, suppose that the empirical initial second moments satisfy the uniform sub-Gaussian bound
\[
R_N:=\int_{\mathbb R^d}|x|^2\,\mu_0^N(dx),
\qquad
\sup_{N\ge1}\mathbb E\exp\{\lambda R_N^2\}<\infty
\]
for some \(\lambda>0\). Then there exists \(C<\infty\) such that, for all sufficiently large \(N\),
\begin{equation}
\sup_{T>0}
\mathbb E\,\mathsf{KSD}_\pi(\overline\mu_T^N,\overline\mu_T)
\le
C(\log\log N)^{-1/2}.
\end{equation}

