[Lemma 1 of arXiv:2609.01770, 'Support of Dyson Brownian Motion'] Let $m(z)=m_\mu(z)$ be the Stieltjes transform of a finite measure $\mu$ with $A=\mu(\bR)$. For any integer $p\geq 1$, we denote its $p$-th derivative by $m^{(p)}(z)$. Then, 
\begin{align}
|m(z)|\leq \frac{A}{\dist(z,\supp(\mu))},\quad
\quad |m'(z)|\leq \frac{\Im[m(z)]}{\Im[z]}, 
\quad |m^{(p)}(z)|\leq \frac{p!A}{\dist(z,\supp(\mu))^{p+1}}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 (Transformation of conditional laws under rerooting) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds.
Let $k \in \N_0$ and let $h \colon (\PolishX^{k+1})^2 \times \SQ(\PolishX^{k+1}) \to \Rmb$ be bounded and measurable.
Define $\Xi_k \colon (\{0,1\} \times \PolishX^{k+1})^2 \rightarrow \Rmb$ by 
\begin{equation*}
\Xi_k(X_{\myroot}[k], X_1[k]) := 1_{\{N_{\myroot}(\tree)\ne\emptyset\}} \frac{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} h(X_{\myroot}[k],X_1[k],\lan X_{N_{\myroot}(\tree)}[k]\ran) \,\big|\, X_{\myroot}[k],X_1[k]\right]}{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} \,\big|\, X_{\myroot}[k],X_1[k]\right]}.
\end{equation*}
Then, for each $v \in \N$, 
\begin{equation} 
\Xi_k(X_v[k], X_{\myroot}[k]) = \Emb\left[ h(X_v[k],X_{\myroot}[k],\lan X_{N_v(\tree)}[k]\ran) \,|\, X_{\myroot}[k],X_v[k] \right], \mbox{ on } \{v \in \tree\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Krylov type estimate) of arXiv:2604.12317, 'Weak solution for distribution dependent SDEs driven by L\'{e}vy noise'] Suppose that \( \alpha \in(1,2]\), \( p>\frac{d}{\alpha-1} \) and \( q>\frac{p \alpha}{p(\alpha-1)-d} \). Then, for any \( T_{0}>0 \), there exist a constant \( C= \) \( C\left(T_{0}, d, \alpha, p, q\right)>0 \) such that for any \( \left(\mathcal{F}_{t}\right) \)-stopping time \( \tau \), and \( 0 \leq S \leq T \leq T_{0} \), and all \( f \in L^{q}([S, T] ; L^{p}(\mathbb{R}^{d})) \),
\begin{equation}
	\mathbb{E}\left(\int_{S \wedge \tau}^{T \wedge \tau} f_{S}\left(X_{S}\right) \mathrm{d} s \bigg| \mathcal{F}_{S}\right) \leq C\left[1+\mathbb{E}\left(\int_{S \wedge \tau}^{T \wedge \tau}\left|\xi_{s}\right| \mathrm{d} s \bigg| \mathcal{F}_{S}\right)\right]\|f\|_{L^{q}([S, T] ; L^{p}(\mathbb{R}^{d}))} .
\end{equation}

[Proposition 24 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $B, C \in \widehat{\Bcal}(S)$ be disjoint such that $\pbb(\nu(B) = 0) < 1$, and let $f_{B \cup C}$ be sampling function for $\xi$ on $B \cup C$. Then, defining $T_B : [0,1] \to [0,1]$ by
    \begin{equation*}
        T_B(x) \coloneqq \inf \left\{ y \in [0,1] \,\middle\vert\, \frac{\lambda\left( f^{-1}_{B \cup C}(B) \cap [0,y] \right)}{\lambda\left( f^{-1}_{B \cup C}(B) \right)} \geq x \right\},
    \end{equation*}
    the composition $f_{B \cup C} \circ T_B$ is a sampling function for $\xi$ on $B$.

