body:
[Lemma 2 of arXiv:2606.22526, 'The conditional expectation of the product of the first $n-1$ Hermite polynomials in a mul'] a)
\begin{equation}
\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\infty}H_{n}(x)H_{m}(x)e^{-x^{2}/2}dx=
\begin{cases}
0\text{,} & \text{if }n\neq m\text{;}\\
n!\text{,} & \text{if .}n=m
\end{cases}
. 
\end{equation}

b) The density of the bivariate normal distribution $N\left(  \left[
\begin{array}
[c]{c}
0\\
0
\end{array}
\right]  ,\left[
\begin{array}
[c]{cc}
1 & \rho\\
\rho & 1
\end{array}
\right]  \right)  $, i.e., function
\[
f_{2N}(x,y|\rho)=\frac{1}{2\pi\sqrt{(1-\rho^{2})}}\exp\left(  -\frac
{x^{2}-2\rho xy+y^{2}}{2(1-\rho^{2})}\right)  ,
\]
can be expanded in the following series (so-called Mehler expansion)
\begin{equation}
f_{2N}(x,y|\rho)=f_{N}(x)f_{N}(y)\sum_{n\geq0}\frac{\rho^{n}}{n!}H_{n}
(x)H_{n}(y), 
\end{equation}
convergent for all $x,y\in\mathbb{R}$ and $\left\vert \rho\right\vert <1.$

c) For all non-negative integers $m,k$ and $\left\vert \rho\right\vert <1$ ,
$x,y\in\mathbb{R}$
\begin{equation}
\sum_{j\geq0}\frac{\rho^{j}}{j!}H_{j+m}(x)H_{j+k}(y)=Q_{m,k}(x,y|\rho
)\sum_{j\geq0}\frac{\rho^{j}}{j!}H_{j}(x)H_{j}(y), 
\end{equation}
where
\begin{align}
Q_{m,k}(x,y|\rho)  &  =\sum_{s=0}^{k}\binom{k}{s}(-\rho)^{s}H_{k-s}
(y)\frac{H_{m+s}\left(  \frac{x-\rho y}{\sqrt{1-\rho^{2}}}\right)  }{\left(
1-\rho^{2}\right)  ^{\frac{m+s}{2}}}.\\
& \nonumber
\end{align}

d) We have also
\begin{align*}
Q_{m,k}(x,y|\rho)  &  =Q_{k,m}(y,x|\rho),\\
Q_{m,0}(x,y,\rho)  &  =H_{m}\left(  \frac{x-\rho y}{\sqrt{1-\rho^{2}}}\right)
/\left(  1-\rho^{2}\right)  ^{m/2},
\end{align*}

e)
\begin{align}
x^{n}  &  =\sum_{k=0}^{\left\lfloor n/2\right\rfloor }\frac{n!}{2^{k}
k!(n-2k)!}H_{n-2k}(x),\\
H_{n}(x)  &  =\sum_{j=0}^{\left\lfloor n/2\right\rfloor }\frac{(-1)^{j}
n!}{2^{j}j!(n-2j)!}x^{n-2j}. 
\end{align}
We will use in fact the following modification of this formula
\[
x^{n}=a^{n}\left(  \frac{x}{a}\right)  ^{n}=a^{n}\sum_{k=0}^{\left\lfloor
n/2\right\rfloor }\frac{n!(a^{2})^{k}}{2^{k}k!(n-2k)!}a^{n-2k}H_{n-2k}(x/a).
\]
f) We will also use the following formula (so-called umbral identity)
\begin{align}
&  (a^{2}+b^{2})^{n/2}H_{n}\left(  \frac{ay+bz}{\sqrt{a^{2}+b^{2}}}\right)
\\
&  =\sum_{k=0}^{n}\binom{n}{k}a^{k}H_{k}(y)b^{n-k}H_{n-k}(z).\nonumber
\end{align}

g) Now, to proceed further we will use the following linearization formula
\begin{equation}
H_{n}(x)H_{m}(x)=\sum_{j=0}^{\min(n,m)}\binom{n}{j}\binom{m}{j}j!H_{n+m-2j}
\left(  x\right)  . 
\end{equation}

h) We have also the so-called Taylor expanding formula
\[
H_{n}(x+y)=\sum_{j=0}^{n}\binom{n}{j}x^{j}H_{n-j}(y).
\]

i) We have multiplication theorem
\begin{equation}
H_{n}(\sigma z)=\sum_{j=0}^{\left\lfloor n/2\right\rfloor }\binom{n}{2j}
\frac{(2j)!}{2^{j}j!}\sigma^{n-2j}(\sigma^{2}-1)^{j}H_{n-2j}(x). 
\end{equation}

From this formula, immediately follows the following result 3.
\begin{align*}
&  \frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\infty}H_{n}(\sigma x)\exp\left(
-\frac{x^{2}}{2}\right)  dx\\
&  =
\begin{cases}
0\text{,} & \text{if }n\text{ is odd;}\\
\frac{(2m)!(\sigma^{2}-1)^{m}}{2^{m}m!}\text{,} & \text{if }n=2m\text{.}
\end{cases}
.
\end{align*}

j)
\begin{equation}
\sum_{s=0}^{n}\binom{n}{s}H_{s}(z)(i)^{n-s}H_{n-s}(iz)=\delta_{0,n}

\end{equation}

[Thm 1 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Suppose that, for a given time horizon \(T>0\), Assumption~\ref{ass:main} holds with \(b_0>\kappa/2\) and \(0<\kappa<K<\infty\) such that \(K/\kappa\leq 2\). Then the SDE~\eqref{eq:MV-SDE} has a unique strong solution. Moreover, this solution has a density \(p\in C^{\beta/2,\beta}_{\mathrm{loc}}((0,T)\times\R^d)\), \(\beta\in(0,1)\), satisfying~\eqref{eq:NFPE} and such that

    \begin{equation}
    p_t(x)\leq c_T\exp\{-\gamma_T\Vert x\Vert_2^2\},
    \quad \forall\,(t,x)\in(0,T)\times\R^d,
    \end{equation}
    with some \(c_T>0\) and \(\gamma_T\in(0,\kappa/2)\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:same_cond_law_weak_limit of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Let $X,Y$ be Polish spaces. Let $
u,\widetilde{
u}$ be two probability measures on $X$, and $\mu_n[dy \mid x]$ a sequence of probability kernels from $X$ to $Y$. Suppose that $
u\otimes\mu_n 	o 
u\otimes\mu$ and $\widetilde{
u}\otimes\mu_n 	o \widetilde{
u}\otimes\widetilde{\mu}$ weakly. Then there are versions of $\mu$ (with respect to $
u$) and $\widetilde{\mu}$ (with respect to $\widetilde{
u}$) such that $\mu[\cdot \mid x] = \widetilde{\mu}[\cdot \mid x]$ for every $x \in X$.

