body:
[Lem 52 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,K,D$ satisfy \eqref{eq:costanti}. Also let $k \ge 1$ be an integer and $q \in [2^k N^{K \delta-1}, \varepsilon_0]$ be a real number. Further let $q' \ge 0$ satisfy
		\begin{flalign}

			\begin{aligned} 
				& q' \in [q - 2^k N^{(D+1)\delta-1}, q - 2^k N^{(D-1)\delta - 1}]; \qquad 	\mathsf{t}:=q^{-1} k 2^{k+3} N^{1+11K\delta}.
			\end{aligned} 
		\end{flalign}

		\noindent  Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned}
				H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \mathfrak{X}$}.
			\end{aligned} 
		\end{flalign}

		\noindent Then,  w.o.p., we have
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{j=1}^{k+1} \mathcal{A}_j^{q'} (N^{A\delta})$ and $t \in [ \mathsf{t}, N^5]$.}
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop basis of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] The differential $\omega_{a,b}$ is holomorphic on $C$ if and only if $(a,b)\in A$, where

\begin{equation}
A=\Bigl\{(a,b): a\ge 0,\ 0\le b<n,\ a+\sum_{j}\Bigl\lfloor\frac{b\,l_j}{n}\Bigr\rfloor\le\frac{bm}{n}-1-\frac{1}{e_\infty}\Bigr\}.
\end{equation}

The set $\{\omega_{a,b}\}_{(a,b)\in A}$ is a basis of $H^0(C,\Omega^1)$, and

\begin{equation}
\ord_P(\omega_{a,b})=na+n-1-\bigl(b\,l_i \bmod n\bigr),
\end{equation}

where $b\,l_i\bmod n$ denotes the least non-negative residue.

