body:
[Lem 17 of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] For $\Omega_0,\Omega_1\in \mathcal{U}_s$ and $\alpha\in[0,1]$, we have
    \begin{equation*}
    \lambda(\Omega_\alpha)\le (1-\alpha)\lambda(\Omega_0)+\alpha\lambda(\Omega_1).
    \end{equation*}

[Prop prop1 of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P,T)$  be a measure preserving system. Then the following three statements are equivalent:
	\begin{longlist}
		\item $P$ is weakly mixing;
		\medskip
		\item for any $r>0$, $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{r}(B\cap T^{-i}C)=P^{r}(B)P^{r}(C)$ for any $B,C\in\mathcal{F}$;
		\medskip
		\item    for any $B,C\in\mathcal{F}$, $
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)P(C),$	 and there exists $r=r_{B,C}\in(0,1/2]$ such that $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{r}(B\cap T^{-i}C)=P^{r}(B)P^{r}(C)$.
	\end{longlist}
	In particular, $P$ is weakly mixing  if and only if $P$ is ergodic and $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{1/2}(B\cap T^{-i}C)=P^{1/2}(B)P^{1/2}(C)$ for any $B,C\in\mathcal{F}$.

[Definition def:LSI of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] A measure $\theta \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ satisfies a log-Sobolev inequality (LSI) with constant $C <\infty$ if for every continuously differentiable function $f: \ensuremath{\mathbb{R}}^m \rightarrow \ensuremath{\mathbb{R}}$ such that $\mathbb{E}^\theta[f^2] = 1$, we have
\begin{align*}
    \mathbb E^\theta[f^2 \log f^2] \leq C \mathbb E^{\theta}[|\nabla f|^2].
\end{align*}
We use ${C}_{LS}(\theta)$ to denote the best possible constant $C$.

[Lemma 12 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] For all $b>a\geq0$ and $c>0$ we have
        \begin{equation}
        \liminf\limits_{\substack{t\to\infty,\,|y|\to\infty\\ t/|y|^{\alpha/2}<M}}
             \frac{\displaystyle\int_{at}^{bt}  e^{-m s} p(s,y) \dx[s]}{\displaystyle \int_0^{ct} e^{-m s} p(s,y) \dx[s]} =
            \liminf\limits_{\substack{t\to\infty,\,|y|\to\infty\\ t/|y|^{\alpha/2}<M}}\ 
            \frac{\displaystyle \int_{a\kappa(t,y)}^{b\kappa(t,y)}\eta(z,1) \dx[z]}
            {\displaystyle \int_{0}^{c\kappa(t,y)}  \eta(z,1) \dx[z]}  > 0.
        \end{equation}

