[Lemma 36 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $p, M\in (0, \infty)$. There exists $N_2 \in \mathbb{N}$, depending on $p$ and $M$, such that the following holds. If $M_1, M_2 \in \mathbb{R}$ are such that $|M_1 - M_2| \leq M$, $n \geq N_2$, $x, y \in \mathbb{Z}$ are such that $x \leq y$ and $x \geq M_1 n^{1/2}$, $y \geq pn + M_2 n^{1/2}$, $g: \llbracket 0, n \rrbracket \rightarrow [-\infty, \infty)$ is arbitrary such that $\Omega_{\ice}(0,n,x,y, \infty, g) \neq \emptyset$, and $s \in [0, n]$, then we have
\begin{equation}
\mathbb{P}_{\ice, \operatorname{Geom}}^{0,n, x, y, \infty, g} \left( Q_1(s) - ps \geq \frac{n - s}{n} \cdot M_1 n^{1/2} + \frac{s}{n} \cdot  M_2 n^{1/2} - 3n^{1/4} \right) \geq \frac{1}{3}.
\end{equation}

[Theorem thm:app2 of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Under the same conditions in Theorem (thm:app1 of the paper), the following statements are equivalent:
	\begin{longlist}
		\item 	$Q$ is weakly mixing;
		\medskip
		\item $\lim_{\substack{n+m\to\infty\\m,n\ge0}}\frac{1}{m+n+1}\sum_{i=-m}^n|P(B\cap T^{-i} C)-P(B)Q(C)|^2=0\text{ for any }B,C\in\mathcal{F};$
		\medskip
		\item for any $f,g\in L^\infty(\Omega,\mathcal{F},Q)$, there exists a subset $J=J_{f,g}$ of $\mathbb{N}$ with $D(J)=0$ such that 
		\begin{equation}
			\lim_{n\notin J,n\to\infty}\int (f\circ T^n)\cdot gdP=\int fdQ\int gdP.
		\end{equation}
	\end{longlist}
	Moreover, these equivalent statements can imply that letting $p(x)$ be a polynomial with integer coefficients,  then for any $f \in L^r(\Omega,\mathcal{F},Q)$, $r>1$, 
	$$
	\lim _{n \rightarrow \infty} \frac{1}{n} \sum_{i=1}^{n} f(T^{p(i)} \omega)=\int fdQ \text{ for }P\text{-a.s. }\omega\in\Omega.
	$$

[Proposition 4 (Kallianpur-Striebel formula) of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] If a random variable $U$ is independent of $W$ under $P$ and \( E[|U|] < \infty \), then it holds that
\begin{align}

  E[U|\mathcal{Y}_t^\epsilon] =
  \frac{\displaystyle E_{Q^\epsilon}\left[ U Z_t^\epsilon \middle| \mathcal{Y}_t^\epsilon \right]}
       {\displaystyle E_{Q^\epsilon}\left[ Z_t^\epsilon \middle| \mathcal{Y}_t^\epsilon \right]}
  \quad (0 \leq t \leq T).
\end{align}

