[Lemma 8 (Barrier is not crossed a second time) of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] Adopt the notion and assumptions of Lemma \ref{lem: W_si_nice} and assume that the event from \eqref{eq:SlowIce} occurs.
	Additionally, assume that
	\begin{align}
		\alpha + \beta < 1/5 - \gamma\ \text{ and }\ (1-2\delta)\beta -2\gamma - 12 \delta \geq 4\delta.
	\end{align}
	Then, it holds with $T\de \inf\{t \geq 0: s_i(\Lc{i}_t) \neq s_i(0) \}$ that
	$
		\Lc{i}_{ r_\delta^2} \leq \Lc{i}_{T} +  \beta r_\delta.
	$
	In particular,
	\begin{align}
		s_i(\Lc{i}_t) = s_i(\Lc{i}_{T}) \text{ for every } t\in [T,  r_\delta^2].
	\end{align}

[Lemma le:projection-geometry of arXiv:2608.19358, 'An optimal Poincaré inequality\\for the complex Ginibre log-gas'] The following properties hold.
  \begin{enumerate}
  \item
    $\mathcal{H}_n^{\mathrm{div},0}$ and
    $\overline{\mathcal{H}_n^{\mathrm{div},0}}$ are orthogonal.
  \item For every symmetric $f\in L^2(\mu_n)$,
    \begin{equation}
      \|Pf\|_{L^2(\mu_n)}^2+\|Qf\|_{L^2(\mu_n)}^2
      \leq
      \|f\|_{L^2(\mu_n)}^2+\|P_0f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \item If $f\in L^2(\mu_n)$ is real-valued, symmetric, and centered, then
    $h=Pf$, its pointwise complex conjugate $\overline h$, and
    $r=f-h-\overline h$, are three pairwise orthogonal functions in $L^2(\mu_n)$, and
    \begin{align}
      \|f\|_{L^2(\mu_n)}^2
      &=2\|h\|_{L^2(\mu_n)}^2+\|r\|_{L^2(\mu_n)}^2,
      \\
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      &=\frac{1}{2}\|f\|_{L^2(\mu_n)}^2
        +\frac{1}{2}\|r\|_{L^2(\mu_n)}^2.

    \end{align}
    In particular, we have the half-distance estimate 
    \begin{equation}
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      \geq\frac{1}{2}\|f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \end{enumerate}

[Corollary LemmaCondExpII of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, for $t \in \mathbb{R}$ and $k=0, \dots, h+1$, 
\begin{align}  
\mathbb{E}[\varphi_{u_{1}}(t-S(u_{1})) \mid \mathcal{G}^{(k)}_{0}] \stackrel{a.s.}{=}  \varphi^{(0)}_{u_{1}}(t-S(u_{1})),
\end{align} 
\noindent while for $i \geq 2$,
\begin{align} 
\mathbb{E}[\varphi_{u_{i}}(t-S(u_{i})) \mid \mathcal{G}^{(k)}_{i-1}] \stackrel{a.s.}{=}  \varphi^{(k)}_{u_{i}}(t-S(u_{i})).
\end{align}

