\begin{equation}
	\mathbb{E}\left[|u(\rho a,x)-u(\rho b,x)|^2\right]
	=
	\rho^{2H}
	\mathbb{E}\left[|u(a,x)-u(b,x)|^2\right].
\end{equation} 
We distinguish two cases.

First, suppose that $s\ge t/2$. Then $s/t\in[1/2,1]$. Taking $\rho=t$, $a=1$, and $b=s/t$ in \eqref{self}, and then using \eqref{CLX-Upper} on the interval $[1/2,1]$, we obtain
\begin{align*}
	\mathbb{E}\left[|u(t,x)-u(s,x)|^2\right]
	= &\, 
	t^{2H}
	\mathbb{E}\left[|u(1,x)-u(s/t,x)|^2\right]   \\
	\le &\, 
	C_{1/2,1}^2 t^{2H} |1-s/t|^{2H}  
	=
	C_{1/2,1}^2 |t-s|^{2H}.
\end{align*}

Next, suppose that $0\le s<t/2$. Then $t-s>t/2$. By ...","release_manifest_digest":"sha256:b22080afc993aaa55a572cf73e64faf696423bc82b9f3e44c85fc90b9186ef96","revision_digest":"sha256:8e21ef61a9147fbfd296958ba5255dac12370926cb84604b319effde38d612cf","source_id":"arxiv:2608.04644","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

