[Theorem 4 (Modified, $L$-fold, coupled spherical integration for rank $M(N)\geq 1$) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $L=O(1)$, $M(N)=O\left(N^{1/2-\epsilon}\right)$ for some $\epsilon >0$, and $D_{l,i}= O_{l,i}\Sigma_{l,i} V^\dagger$ have a single non-zero singular value $\sqrt{\theta_{l,i}}$ at the $i^\mathrm{th}$ on-diagonal position of $\Sigma_{l,i}$. 
Define the modified, $L$-fold coupled HCIZ integral by
\begin{align}
    J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \int
        \exp\left\{
            \sum_{i=1}^{M(N)}
            \sum_{l,k=1}^{L}
                N\mathrm{tr}\left(
                    D_{k,i} D_{l,i}^\dagger
                    U_l^\dagger
                    E_{lk,i}
                    U_k
                \right)
        \right\}
        \prod_{l=1}^{L}
            \mathrm d m_N^{(\beta)}(U_l)
            .
\end{align}
The block matrix $Z_{N,i}$ is structured as in Definition~\ref{def:operator_valued_convergence}, i.e. the block at position $(l,k)$ of $Z_{N,i}$ is $E_{lk,i}$ with $E_{lk,i} = E_{kl,i}^\dagger\in \mathbb A^{N\times N}$ for all $(l,k)$, $Z_{N,i}$ converges to some $Z_{i}$ with finite moments as $N\uparrow\infty$, is R-cyclic, and $||E_{lk,i}||_\infty<\infty$ for all $(l,k,i)$ as $N\uparrow\infty$.
If all $\theta_{l,i}$ are sufficiently small, such that
\begin{align}
-P_{i}=-\mathrm{diag\left\{\frac{2\theta_{1,i}}\beta,\ldots,\frac{2\theta_{L,i}}\beta\right\}}
    \in \left\{\left.G_{Z_{i}}^{\mathcal D_L}(S) \right| S^{Z_i}\in\mathcal S_{\{-\}^L}\right\},
\end{align}
then
\begin{align}
    \lim_{N\uparrow\infty} \frac{1}{NM(N)}
    \log J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \lim_{N\uparrow\infty}
    \frac{1}{M(N)}
    \sum_{i=1}^{M(N)}
        \frac{\beta}{2}
        \int_{0}^1
            \mathrm{tr}\left(
                R_{Z_{i}}^{\mathcal D_L}(P_i w) P_i
            \right)
            \mathrm d w.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:disk+QT of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix $W,W_1,W_2,W_3>0$ such that $W_2+W_3=W_1+2$ or $W_1+W_3=W_2+\gamma^2-2$. There exists some constant $c:=c_{W,W_1,W_2,W_3}\in (0,
	\infty)$ such that
	\begin{equation}
	    \mathrm{QT}(W+W_1,W+W_2,W_3)\otimes \mathrm{SLE}_\kappa(W-2;W_2-2,W_1-W_2) = c\int_0^\infty {\mathcal{M}}^\mathrm{disk}_{0,2}(W;\ell)\times\mathrm{QT}(W_1,W_2,W_3;\ell)d\ell.
	\end{equation}
	That is, if we draw an independent $\mathrm{SLE}_\kappa(W-2;W_1-2,W_2-W_1)$ curve $\eta$ on a sample from $\mathrm{QT}(W+W_1,W+W_2,W_3)$ embedded as $(D,\phi,a_1,a_2,a_3)$, then the quantum surfaces to the left and right of $\eta$ are corresponding independent quantum disks and triangles conditioned on having the same interface quantum length. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Deff fxn-vanish of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For an arbitrary set $A$ and functions $f: A \to [-\infty,\infty]$ and $g:A \to [0,\infty]$, we say $f$ vanishes over $g$ if one of the following equivalent conditions holds: \begin{enumerate}

        \item $\forall \epsilon > 0, \exists M > 0$ such that $|f|\mathbbm{1}_{|f|>M} \leq \epsilon g$
        \item $\forall \epsilon > 0, \exists N > 0$ such that $|f| \leq \epsilon g + N$
    \end{enumerate}

[Proposition 10 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Suppose that \(m>2\) and \(H\in(3/4,1-1/(2m))\). Then:
\begin{itemize}
    \item If \(H^*(m)>1/4\), then \(r_I\geq r_S\).
    \item If \(H^*(m)<1/4\), then \(r_I\leq r_S\).
    \item If \(H^*(m)=1/4\) then \(r_I=r_S\).
\end{itemize}

