[Defn embedded-maps-bound-plaq-ass of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] For a balanced  pair $(s,K)$, we say that  $M=(m,\psi)$ is an \textbf{embedded map with boundary $s$ and plaquette assignment $K$} if $M$ is an embedded map (Definition~(defn:embedded-map of the paper)) which satisfies the following three additional conditions:
\begin{enumerate}
	\item [3.] the number of internal yellow faces sent to $p$ by $\psi$ is equal to $K(p)$, for all $p\in \mathcal{P}_{\Lambda}$.
	\item [4.] the total number of external yellow faces in $m$ is equal to the number of loops in $s$;
	\item [5.] the boundary of each external yellow faces of $m$ is isomorphically sent by $\psi$ to a distinct loop in $s$ preserving the orientation;\footnote{We remark that to determine if the boundary of an external yellow face of $m$ is sent to $\ell$ or $\ell^{-1}$ by $\psi$, one should use the same procedure used to determine if an internal yellow face is sent to $p$ or $p^{-1}$ by $\psi$. See also Figure~(fig-embedded-maps-exemp4 of the paper) for more explanations.}
\end{enumerate}
We denote by $\mathcal{M}(s,K)$ the set of embedded maps with boundary $s$ and plaquette assignment $K$.
For a non-balanced pair $(s,K)$, we define $\mathcal{M}(s,K)=\emptyset$.

[Defi sol2 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] \begin{enumerate}
\item[(1)] 
Let $\alpha\in(1,1+\frac{4}{d})$ and $T>0$. 
A $L^2$-solution of (equation RSNLS1 of the paper) is a pair $(y,\tau)$, where $\tau(\le T)$ is an $(\mathcal{F}_t)$-stopping time, and $y=(y(t))_{t\in[0,\tau]}$ is a $L^2(dt)\cap L^2(d\langle M\rangle(t))$-valued continuous $(\mathcal{F}_t)$-adapted process, such that $|y|^{\alpha}\in L^1([0,T];H^{-2}(\mathbb{R}^d))$, and it satisfies ${
{\mathbf{P}}\text{-a.s.}}$,
\begin{align*}
y(t)&=x-i\int_0^te^{-M(s)}\Delta(e^{M(s)}y(s))ds-\frac{1}{2}\sum_{j=1}^N\int_0^t(|\mu_j|^2|e_j|^2+\mu_j^2e_j^2)y(s)d\langle M_j\rangle(s) \\
& \quad -\int_0^t\lambda i |e^{(\alpha-1)M(s)}||y(s)|^{\alpha-1}y(s)ds,
\end{align*}
as equation in $H^{-2}$.
\item[(2)] 
Let $\alpha\in(1,1+\frac{4}{d})$ and $T>0$. 
A $L^2$-solution of (equation RSNLS2 of the paper) is a pair $(y,\tau)$, where $\tau(\le T)$ is an $(\mathcal{F}_t)$-stopping time, and $y=(y(t))_{t\in[0,\tau]}$ is a $L^2(dt)\cap L^2(d\langle M\rangle(t))$-valued continuous $(\mathcal{F}_t)$-adapted process, such that $|y|^{\alpha}\in L^1([0,T];H^{-2}(\mathbb{R}^d))$, and it satisfies ${
{\mathbf{P}}\text{-a.s.}}$,
\begin{align*}
y(t)&=x+\int_0^tA(s)y(s)ds-\frac{1}{2}\sum_{j=1}^N\int_0^t(|\mu_j|^2|e_j|^2+\mu_j^2e_j^2)y(s)d\langle M_j\rangle(s) \\
& \quad -\int_0^t\lambda i e^{(\alpha-1)\text{Re}M(s)}|y(s)|^{\alpha-1}y(s)ds,
\end{align*}
as equation in $H^{-2}$.
\end{enumerate}

[Theo 6 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{h(n) : n \ge 1\} \subset [0, \infty)$ and $p \in [1, \infty)$. Assume that $\{X^n_s : s \in S_n, n \ge 1\}$ is $(\nu_n)$-$\UI(p)$ w.r.t. $\{h(n)\}$. If
	\begin{align}
		\lim_{n \rightarrow \infty} h(n) \nu_n(S_n)=0,
	\end{align}
	then
	\begin{align}
	\lim_{n \to \infty} \mathbb{E}  \lt\| \int_{S_n} X^n_s \, \nu_n(\od s) \rt\|^p  = 0,
	\end{align}
	and in particular, $\int_{S_n} X^n_s \, \nu_n(\od s)  \to 0$ in probability  as $n \to \infty$.

[Corollary cor:complete-intersection-spectrum-tower of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Fix $k\geq3$, and let $\mathcal R_{\mathrm{CI}}(h,k)$ be the set of labels in
$\mathcal R(h,k)$ having a primitive witness whose projective monomial curve is a
complete intersection.  There are constants $0<c_k<C_k$ such that, for all
sufficiently large integers $h$,
\begin{equation}
 \left|\mathcal R_{\mathrm{CI}}(h,k)
 \cap[c_kh^{k-1},C_kh^{k-1}]\right|
 \gg_k \frac{h^{k-2}}{(\log h)^{k-3}}.
\end{equation}
These witnesses are Gorenstein, have maximal active rank $k-2$, and satisfy
\begin{equation}
 \operatorname{ndiam}(A)=\prod_{i=1}^{k-2}p_i(A)\asymp_k h^{k-2}.
\end{equation}
With $\xi$ again recording homological degree, their Betti and Hilbert
numerators are respectively
\begin{equation}
 \prod_{e\in\{p,\ell_1,\ldots,\ell_{k-3}\}}(1+\xi z^e),
 \qquad
 \prod_{e\in\{p,\ell_1,\ldots,\ell_{k-3}\}}(1-z^e).
\end{equation}

