body:
[Ppn 27 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Recall $F^{\rv}$ from \eqref{e:F.rv}
and $F^{\rvi}$ from \eqref{e:F.rvi}. For all $t\in \R$, we have
    \[
        \P(F^{\rv} \ge t) \le 4\P(F^{\rvi} \ge t)\,.
    \]

\begin{proof}
Recall from \eqref{e:F.rv} that the function $F^{\rv}$ is defined by the supremum of the function $\acute{F}$ over $\|\by\|^2=N$. The function $\acute{F}$ is given by the sum of $F_w$ from \eqref{e:F.w}, $F_v$ from \eqref{e:F.v}, and $F_x$ from \eqref{e:F.x}. Note that we can decompose $F_v = F_{v+}+ F_{v-}$ where         \[
    F_{v+}(\bG,\by)
    \equiv\sum_{j\in J_+}
        \frac{\hv_j}{M}
        \sum_{a\in B_j}
        \frac{(\bg^a,\by)^2}{N}
    = \sum_{j\in J_+}
        \frac{\hv_j}{MN}
        \|\bG^{B_j}\by\|^2\,,
    \]
and $F_{v-}$ is defined analogously. By calculus, we can rewrite
    \begin{align*}
    F_{v+}(\bG,\by)
    &= \sup\bigg\{
    \frac{2(\btheta_+,\bG^{B_+} \by)}{M\sqrt{N}}
            - \sum_{j\in J_+} \frac{\|\btheta_+(B_j)\|^2}{M\hv_j}
            :\btheta_+
            \in\R^{B_+}
    \bigg\}\,,\\
    F_{v-}(\bG,\by)
    &=\inf\bigg\{
    \frac{2(\btheta_-,\bG^{B_-} \by)}{M\sqrt{N}}
            - \sum_{j\in J_-} \frac{\|\btheta_-(B_j)\|^2}{M\hv_j}
    :\btheta_-
            \in\R^{B_-}
    \bigg\}\,.
    \end{align*}
For standard gaussians $Z_+, Z_-$ independent of all else, let
    \begin{align*}
    \tilde{F}_{v+}(\bG,Z_+,\by)
    &\equiv
    \sup\bigg\{
    \frac{2(\btheta_+,\bG^{B_+} \by) + 2\|\btheta_+\|\|\by\| Z_+}{MN^{1/2}}
            - \sum_{j\in J_+} \frac{\|\btheta_+(B_j)\|^2}{M\hv_j}
    :\btheta_+\in\R^{B_+}
    \bigg\}\,,\\
    \tilde{F}_{v-}
    (\bG,Z_-,\by)
    &\equiv
    \inf\bigg\{
    \frac{2(\btheta_-,\bG^{B_-} \by) + 2\|\btheta_-\|\|\by\| Z_-}{MN^{1/2}}
            - \sum_{j\in J_-} \frac{\|\btheta_-(B_j)\|^2}{M\hv_j}
            :\btheta_-\in\R^{B_-}
    \bigg\}\,.
    \end{align*}
Note that we have $Z_+,Z_-\ge0$ with probability $1/4$; on this event, the quantities $F_{v\pm}$ are dominated by the quantities $\tilde{F}_{v\pm}$. Let
    \begin{align*}
    \tilde{F}^{\rv}
    &\equiv
    \sup_{\|\by\|^2=N}
    \bigg\{
    F_w(\by)
    +F_x(\tbmeta,\by)
    +
    \tilde{F}_{v+}(\bG,Z_+,\by)
    +
    \tilde{F}_{v-} (\bG,Z_-,\by)
    \bigg\}\,.
    \end{align*}
Finally, in order to compare $\tilde{F}_{v\pm}$ with $\bar{F}_{v\pm}$ as defined by \eqref{e:bar.F.v.plus} and \eqref{e:bar.F.v.minus}, let $Z$ denote a standard gaussian random variable, and let us compare the gaussian processes
    \begin{align*}
    A(\btheta,\by)
    &\equiv (\btheta,\bG\by)
        + \|\btheta\|\|\by\| Z\,,\\
    B(\btheta,\by)
    &\equiv\|\by\| (\hbg,\btheta) + \|\btheta\| (\dbg,\by)\,.
    \end{align*}
We then calculate
    \begin{align*}
    \E[A(\btheta,\by)
        A(\btheta',\by')]
    &= (\btheta,\btheta')
        (\by,\by')
        +\|\btheta\|\|\btheta'\|
        \|\by\|\|\by'\|\,,\\
    \E[B(\btheta,\by)
        B(\btheta',\by')]
    &=(\btheta,\btheta')
    \|\by\|\|\by'\|
    +\|\btheta\|\|\btheta'\|
    (\by,\by')\,.
    \end{align*}
These quantities are equal whenever $\btheta=\btheta'$ or $\by=\by'$. In general, the $A$-covariances upper bound the $B$-covariances: by scaling, it suffices to show this in the case $\btheta,\btheta',\by,\by'$ are all unit vectors, in which case it reduces to the inequality
    \[
    1-(\btheta,\btheta')
        -(\by,\by')
        +(\btheta,\btheta')
        (\by,\by')
    = \Big(1-(\btheta,\btheta')\Big)
    \Big(1-(\by,\by')\Big) \ge0\,.
    \]
Therefore, we can use Slepian's inequality to compare $\tilde{F}_{v+}$ with $\bar{F}_{v+}$; and we can use Gordon's inequality to compare $\tilde{F}_{v-}$ with $\bar{F}_{v-}$. This implies that $\tilde{F}^{\rv}$ is stochastically dominated by
$\tilde{F}^{\rvi}$. The claim follows by recalling the above observation that
$F^{\rv} \le \tilde{F}^{\rv}$
with probability at least $1/4$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 34 (Metric form of the Transference Principle) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be a Polish probability space. Let $G:\R_+\to\R_+$ be a continuous, non-increasing function decaying to zero at infinity and let $\mathcal A,\mathcal D\subset \mathcal{B}(X)$. Then, the following are equivalent:
\begin{enumerate}
    \item For all
$A\in\mathcal A$ and $B\in\mathcal D$, one has
\[
    \mu(A)^{\frac12}\mu(B)^{\frac12}
    \leq
    G(d(A,B));
\]
\item For every pair of measurable functions $f \in \mathcal{F}(\mathcal{A})$ and $ g\in \mathcal{F}\left(\mathcal{D}\right)$ and measurable, non-decreasing function $W \colon \R_+  \to \R_+$ that satisfy \begin{align*}
f(x)^\frac{1}{2}g(y)^\frac{1}{2} &\leq W(d(x,y)) \quad \text{ for all } 
\quad(x,y)\in X\times  X,
\end{align*}
one has
\[
\left(\int_{X} f(x) d\mu(x) \right)^{\frac{1}{2}} \left(\int_{X} g(y) d\mu(y) \right)^{\frac{1}{2}}\leq \int_{\R_+} W(r) d(-G)(r).
\]
\end{enumerate}
We say that the space $(X,d,\mu)$ satisfies the metric-Santal\'o inequality induced by $G$ on the domain $(\mathcal A,\mathcal D)$.

[Definition Def_DOA of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For a point process $\Pi$, we say a point process $\theta$ is in the domain of attraction of $\Pi$, written as  $ \theta \in \textrm{Dom}_{\lambda}(\Pi)$, if $\theta_t^\lambda$ given by (equation theta_t-def of the paper) started from $\theta_0^\lambda = \theta$ converges to $\Pi$ in the sense that for all $f \in C_c^+(\mathbb R),$ 
    \begin{equation}
        \mathbb E[e^{-\langle f , \theta_t^\lambda \rangle}]\longrightarrow \mathbb E[e^{-\langle f , \Pi \rangle}]
    \end{equation}
    as $t \to \infty.$

[Lemma lem:good_event_many_scales of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] By possibly taking $\delta \in (0,1)$ to be smaller and $N \in \BN$ to be larger in the definition of the events $E_n(\Psi)$,  we have that the following is true off an event with probability at most $\varepsilon^3$,  for all sufficiently small $\varepsilon$ (in a way depending only on $a$ and $\theta$).  There exists an integer $n$ such that
\begin{align*}
n \in \left(\frac{\theta \log(1/\varepsilon)}{3\log(2)} ,  -1 + \frac{\log(1/\varepsilon)}{3\log(2)}\right)
\end{align*}
and $E_n(\Psi)$ occurs.

[Lemma lem:positive-beta-estimates of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Let $\beta>0$. For every bounded interval $I\subset\mathbb R$,
    \begin{equation}
            B(z+\beta+2,\beta+1)
            =
            O_{\beta,I}\bigl(|\operatorname{Im} z|^{-\beta-1}\bigr),
            \qquad\text{as }|\operatorname{Im} z|\to\infty,
    \end{equation}
    uniformly for $\textnormal{Re} z\in I$. Consequently, if $\phi_\beta$ has no zero on
    $\textnormal{Re} z=-\sigma$, then
    \begin{equation}
            A_{\beta,\sigma}
            :=
            \frac1{2\pi}
            \int_{-\infty}^{\infty}
            |F_\beta(-\sigma+it)|\mathrm{d} t
            <\infty.
    \end{equation}

[Definition fixed-curve of arXiv:2607.15966, 'Canonical Mandelbrot Cascades on Curves Are Rajchman'] A map \(\Gamma:\mathbb T\to\mathbb R^2\) is called a fixed nondegenerate
\(C^2\) Jordan curve if \(\Gamma\) is a \(C^2\) embedding and satisfies
 \begin{equation}
        \inf_{t\in\mathbb T}|\Gamma'(t)|>0,
     \qquad
    \inf_{t\in\mathbb T}
     |\det(\Gamma'(t),\Gamma''(t))|>0.
\end{equation}
 When derivatives are written, \(\Gamma\) is represented by its associated
 \(1\)-periodic \(C^2\) lift to \(\mathbb R\).

[Defn def:adapted of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ be a cooriented $C^0$-foliation on a manifold with fences and windows $M_{\mathord{\scalebox{0.45}{$\square$}}}$. We say that $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is \textbf{adapted} to the boundary of $M_{\mathord{\scalebox{0.45}{$\square$}}}$ if it is transverse to $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$, and there exist pairwise disjoint standard neighborhoods and coordinates of the fences and windows such that
    \begin{itemize}
        \item In $N(\mathcal{A}_i)$, $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is tangent to $\partial_y$, positively transverse to $\partial_z$ (i.e., horizontal), and it is
        \begin{itemize}
            \item Positively transverse to $\partial_x$ in $S^1 \times I \times [1,2)$
            \item Negatively transverse to $\partial_x$ in $S^1 \times I \times (-1,0]$,
        \end{itemize}

        \item If $\mathcal{W}_j$ is a square window, then in $N(\mathcal{W}_j)$, $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is the standard horizontal foliation by $(x,y)$-planes. In particular, it is smooth there. If $\mathcal{W}_j$ is a toroidal window, we only require that $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is tangent to $\partial_y$ in $N(\mathcal{W}_j)$.
    \end{itemize}

[Cor polynomial-log of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Let \(P\in\mathbb R[x]\) have degree \(d\ge2\).  There exists \(A_0=A_0(P)>0\) such that, if for all sufficiently large \(n\),
			\begin{equation}
				v_n\ge A\left(\frac{\log n}{n}\right)^{\frac{1}{d}}
			\end{equation}
			with \(A\ge A_0\), then \(P(X)\) is almost surely absolutely normal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] For $k\leq l$ and pairwise different $x_1,\dots,x_l\in\X$, it holds $\P$-almost surely that
\begin{align*}
\Lambda_{(x_1,U_1),\dots,(x_l,U_l)}^k \chi_a(\Delta_W) \,=\, \sum_{i=k-1}^\alpha a_i \, f_i^{x_1,\dots,x_k} \big(\Delta_W^{x_1,\dots,x_l,\{1,\dots,k\}}\big).
\end{align*}

