body:
[Defi 9 (Diagonal negative dependence) of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] \mbox{ }
\begin{enumerate}[(i)]
\item Two $\cX$-valued random elements $X, Y$ are said to be \textit{diagonally negatively dependent} if 
\begin{align}
\bP(X \in A, Y \in A) \le \bP(X \in A)\,\bP(Y \in A), \quad \forall A \in \cB(\cX),
\end{align}
or equivalently,
$\Cov(\1_{\{X \in A\}}, \1_{\{Y \in A\}}) \le 0$ for all $A \in \cB(\cX)$.

\item Let $\varnothing \neq I \subseteq \bR$ and $M \in \bN \cup \{0\}$.
A family $\{Y_i : i \in I\}$ of $\cX$-valued random elements is \textit{$M$-pairwise diagonally negatively dependent} if $Y_i, Y_j$ are diagonally negatively dependent for all $i, j \in I$ with $|i-j|>M$.
When $M=0$, we then simply call $\{Y_i : i \in I\}$ \textit{pairwise diagonally negatively dependent}.

\end{enumerate}

[Proposition 7 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $m\in\Z$ there is a natural isomorphism
\begin{equation}
 H^2\!\left(G_{\{p\}},(\Qp/\Zp)(m)\right)^\vee
 \simeq e_mX[f_m].
\end{equation}

[Corollary C:Chung of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume condition~(equation E:main of the paper) holds. For part (i) below, further assume $\ell < \alpha(\gamma+1/2)$ if $\beta = 2$ and
  $\gamma \in (0, 2]$.
  \begin{enumerate}[\rm (i)]

    \item If $\rho \in (0, 1)$, then for any compact interval $I$ in $(0,
            \infty)$ and any $x_0 \in \mathbb{R}^d$, there exist constants $C_5, C_5' \in [0,
              \infty]$ such that for each $t_0 \in I$,
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{t:\, |t-t_0|
              \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log\log(1/\varepsilon))^{-\rho}}
            = C_5 \quad \text{a.s.}
          \end{align}
          and
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{t_0 \in I} \sup_{t: |t-t_0|
              \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log(1/\varepsilon))^{-\rho}}
            = C_5' \quad \text{a.s.}
          \end{align}
          Moreover, when $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma=[0,1]$, $\ell<\alpha(\gamma+1/2)$, we
          have $C_5>0$, $C_5'>0$, and $t \mapsto u(t, x_0)$ is a.s.\ nowhere
          differentiable on $(0, \infty)$.\\
          When $\gamma \in [0,1-\beta]$, we have $0 < C_5 < \infty$.

    \item If $\tilde\rho \in (0, 1)$, then for any $t_0 > 0$ and any compact
          rectangle $J$ in $\mathbb{R}^d$, there exist constants $C_6 \in (0,\infty)$ and
          $C_6' \in (0, \infty]$ such that for each $x_0 \in J$,
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{x:\, |x-x_0|
              \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde\rho}(\log\log(1/\varepsilon))^{-\tilde\rho/d}}
            = C_6 \quad \text{a.s.}
          \end{align}
          and
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{x_0 \in J} \sup_{x:\, |x-x_0|
              \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde\rho}(\log(1/\varepsilon))^{-\tilde\rho/d}}
            = C_6' \quad \text{a.s.}
          \end{align}
          In particular, $x \mapsto u(t_0, x)$ is a.s.\ nowhere differentiable on
          $\mathbb{R}^d$.
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:overdam of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{L}_\gamma = \mathcal{L}_H + \gamma \mathcal{L}_S$, with $\mathcal{L}_H$ in (equation Hamiltonianterm of the paper) and $\mathcal{L}_S$ in (equation def:lsbip of the paper), be the QMS generator given as above. Suppose that Conditions~(asspA2 of the paper), (asspB2 of the paper), and~(condeq:php of the paper) hold. Then, we have 
\begin{enumerate}[label=(\roman*)]
    \item  The generator $\mathcal{L}_O$ of the overdamped limit of $\exp(t \mathcal{L}_\gamma)$ is given by
    \begin{align} 
        \mathcal{L}_O(X^B) = - \sum_{j \ge 1} \frac{1}{\lambda_j} \Gamma_{\sigma^B}^{-1}\left[(G_j^B)^*, \Gamma_{\sigma^B}\left(\left[G_j^B, X^B \right]\right) \right],
    \end{align}
    where the operators $G_j^B$ are from the decomposition (equation eq:decomHab of the paper), and $\Gamma_{\sigma^B}$ is defined as in (equation def:weighting of the paper).  
    \item $\mathcal{L}_O$ is self-adjoint with respect to the KMS inner product $\langle \cdot, \cdot \rangle_{\sigma^B,1/2}$ on $\mathcal{M}_B$ with invariant state $\sigma^B$. The fixed-point subspace of $\exp(t \mathcal{L}_O)$ is 
    \begin{align} 
        \ker(\mathcal{L}_O) = \left\{X^B \in \mathcal{M}_B\,;\ \left[G_j^B, X^B\right] = 0 \ \text{for all $j \ge 1$}  \right\}\,.
    \end{align}
    Thus, $\sigma^B$ is the unique invariant state of $\exp(t \mathcal{L}_O^\dag)$ if and only if 
    \begin{align}  
        \ker(\mathcal{L}_O) = {\rm Span}\{{\bf 1}^B\}\,.
    \end{align}
    \item The fixed-point algebra of $\exp(t \mathcal{L}_\gamma)$ satisfies
    \begin{align} 
        \mathcal{F}(\mathcal{L}_\gamma) = {\bf 1}^A \otimes \ker(\mathcal{L}_O)\,.
    \end{align}
    Thus, $\mathcal{L}_\gamma$ is primitive if and only if (lokernel of the paper) holds.
\end{enumerate}

[Lem theo: decoupling ineq of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n,$ $T$ and $N$ be as in Corollary~(coro: advanced geographic ineq coupling map of the paper). Let 
	\begin{align*}
		A_n^{(1)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_1)\leqslant \delta\},\\
		A_n^{(2)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_2)\leqslant \delta\},\\
		B_T(\varepsilon, \delta)&=\{w\in \mathcal W_T\ |\ d_{\mathrm{LP}}(L[w],\mu)\leqslant f(\varepsilon, \delta)\}.
	\end{align*}
	Then,
	\begin{equation}
		\begin{split}

		\mathbb P(A_n^{(1)}(\delta))^{\lceil N/2\rceil}\mathbb P(A_n^{(2)}(\delta))^{\lfloor N/2\rfloor}&\leqslant C_{n,T} \mathbb P(B_T(\varepsilon,\delta)),
		\\ C_{n,T}&= \big(c_K^r(\tau_K+1)^{r}(n+1)^{2r+1}\big)^{N}.
		\end{split}
	\end{equation}

