\sqrt{ \Big| \tfrac{   \lambda_j^{-\vsg} - \lambda_j^{\vsg}  }{ \lambda_i^{\vsg} \, - \lambda_j^{-\vsg} }  \Big| }

                        \ln\frac{\sqrt{2}+1}{\sqrt{2}-1}   &  j < i   \ea \right.  \vspace{2mm} \\

\big| \big( \mf{m}_{1}^{\vsg}\big)_{ij} \big| &\leq

\left\{  \ba{cc} \ln|\lambda_{i}^{\vsg} - \lambda_j^{\vsg}|  - \ln|\lambda_i^{\vsg} - \lambda_{j+1}^{\vsg}|  + \pi &  i >j+1   \vspace{2mm}\\

\ln 2  + \mathbbm{1}_{\{ \ups_j = -\vsg \}} \sqrt{ \Big| \tfrac{  \lambda_{j+1}^{\vsg} - \lambda_{j+1}^{-\vsg}   }

            {\lambda_{j+1}^{-\vsg} - \lambda_{i}^{\vsg} }  \Big| }

