body:
[Lemma 4 (Control-law relative entropy) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] For controlled laws with the same initial law and diffusion coefficient,
\begin{equation*}
\KL(P^{\bm u}\|P^{\bm v})
=\frac12\E_{P^{\bm u}}\int_0^T\norm{\bm u_t-\bm v_t}^2\,\dd t
\end{equation*}
whenever the Girsanov exponentials are true martingales. In particular,
\begin{equation*}
\norm{P_t^{\bm u}-P_t^{\bm v}}_{\rm TV}
\leq\frac12\left(\E_{P^{\bm u}}\int_0^T\norm{\bm u_s-\bm v_s}^2\,\dd s\right)^{1/2}.
\end{equation*}
The proof is given in \cref{app:proof-control-kl}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 169 (quenched second moment bounds for $\vX$, $\vX^\trunc$, and $\vX^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\hat{a}$, $\hat{a}^\frozen$,
$\hat{\iota}$, and $\hat{\iota}^\frozen$
be sampled uniformly at random from 
$[M]$, $[M^\frozen]$,
$[N]$, and $[N^\frozen]$, independently of the gaussian disorder and of one another. 
Recall that $\bE$ denotes expectation over $\hat{a}$, $\hat{a}^\frozen$, $\hat{\iota}$, and $\hat{\iota}^\frozen$, as applicable.
Then for 
all $0\le d\le \dmax-1$ we have
	\[\max\bigg\{
	\frac{\bE[\Delta X^{\RomI}(q_d,\hat{a})^2]}
		{(\delta_d)^2 p'(q_d)},
	\frac{\bE[\Delta X^{\RomII}(q_d,\hat{a})^2]}
		{\delta_d  p(q_d)},
	\frac{\bE[\Delta X^{\RomIII}(q_d,\hat{a})^2]}
		{\delta_d  q_d p'(q_d)},
	\frac{\bE[\Delta X^{\Ising}(q_d,{\hat{\iota}})^2]}
		{\delta_d}
	\bigg\}
    \le (\MAX_N)^2\,,\]
where $\MAX_N$ is defined by \eqref{e:MAX.N}. The same bound holds with $\vX^\trunc$ or $\vX^\frozen$ in place of $\vX$
(using $(\hat{a}^\frozen,\hat{\iota}^\frozen)$ in place of $(\hat{a},\hat{\iota})$ for the case of $\vX^\frozen$).

\begin{proof}
Recall the notation introduced in \eqref{e:normalized.vectors.g}--\eqref{e:normalized.vectors.y}. From \eqref{e:X.decomp}, we have
	\begin{align*}
	\frac{\Delta X^{\RomI}(q_d,a)}{\delta_dp'(q_d)^{1/2}}
	&= 
	\frac{(\bmeta^a(q_{d+1}),
	\by(q_{d+1}))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\RomII}(q_d,a)}{(\delta_d p_d)^{1/2}}
	&= \frac{(\bar{\bg}^a(q_d),\by(q_{d+1}))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\RomIII}(q_d,a)}{[\delta_d q_d p'(q_d)]^{1/2}}
	&= 
	\frac{(\bmeta^a(q_{d+1}),\bar{\bx}(q_d))}{N^{1/2}}\,,\\
	\frac{\Delta X^{\Ising}(q_d,
		{i})}{(\delta_d)^{1/2}}
	&=(\be_i,\by(q_{d+1}))\,,
	\end{align*}
where $a\in[M]$ and $i\in[N]$.
We therefore have the (quenched) second moment bounds
	\begin{align*}
	\frac{\bE[\Delta X^{\RomI}(q_d,
		\hat{a})^2]}
		{(\delta_d)^2 p'(q_d)}
	&=\frac{1}{M}
	\sum_{a=1}^M \frac{(
	\bmeta^a(q_{d+1}),
		\by(q_{d+1}))^2}{N}
	\le \frac{
	\|\bXi(q_{d+1})\|^2
	\|\by(q_{d+1})\|^2}
		{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\RomII}(q_d,\hat{a})^2]}
		{\delta_d p_d}
	&=
	\frac{1}{M}
	\sum_{a=1}^M 
	\frac{(\bar{\bg}^a(q_d),\by(q_{d+1}))^2}{N}
	\le
	\frac{\|\bar{\bG}(q_d)\|^2
	\|\by(q_{d+1})\|^2}{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\RomIII}(q_d,
		\hat{a})^2]}{\delta_d q_d p'(q_d)}
	&=\frac{1}{M}
	\sum_{a=1}^M
	\frac{(\bmeta^a(q_{d+1}),\bar{\bx}(q_d))^2}{N}
	\le \frac{\|\bXi(q_{d+1})\|^2 \|\bar{\bx}(q_d)\|^2}{MN}
	\le (\MAX_N)^2\,,\\
	\frac{\bE[\Delta X^{\Ising}
	(q_d,{\hat{\iota}})^2]}{\delta_d}
	&=
	\sum_{i=1}^N \frac{(\be_i,\by(q_{d+1}))^2}{N}
	= \frac{\|\by(q_{d+1})\|^2}{N}
	\le \MAX_N\,.
	\end{align*}
This proves the claim for $\vX$.
Then note that $\Delta X^{\trunc,\RomI}(q_d,a)$ equals either $\Delta X^{\RomI}(q_d,a)$ or zero, where the latter case corresponds to scenarios where the trajectory has exited $[-\trK,\trK)^3$ (Definition~\ref{d:trunc}) or has landed in a small bucket (Definition~\ref{d:buckets}). 
Likewise, $\Delta X^{\frozen,\RomI}(q_d,a)$ equals either $\Delta X^{\trunc,\RomI}(q_d,a)$ or zero, 
where the latter case corresponds to the same scenarios mentioned above for $X^{\trunc,\RomI}$, or to the scenario where $a$ is the index of one of the frozen particles added in Definition~\ref{d:froze}. It follows that
	\[
	\bE\Big[\Delta X^{\frozen,\RomI}(q_d,\hat{a}^\frozen)^2\Big]
	\le 
	\bE\Big[\Delta X^{\trunc,\RomI}(q_d,\hat{a})^2\Big]
	\le \bE\Big[
		\Delta X^{\RomI}(q_d,\hat{a})^2\Big]\,,\]
and similarly for $X^{\RomII}$, $X^{\RomIII}$, and $X^{\Ising}$. The claim then follows for $\vX^\trunc$ and $\vX^\frozen$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:inter ber of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ be such that $n^{1/4}\ll\mu\ll n$, and assume that $\delta_n$ admits a limit $\delta$ (possibly infinite).
    Let $\mathbf{T}_n$ be a $\mu$-height-biased tree of size $n$.
    Then, $h(\mathbf T_n)-m_{\mu/n}+2$ converges in distribution to a Bernoulli random variable with parameter
    \begin{align*}
        p_\delta=\frac{e^{-\delta}}{1+e^{-\delta}}\,.
    \end{align*}

