body:
[Theorem 9 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $h,T$ be such that $\frac Th\in\mathbb{N}$ and $f:\R\to\R$ be three times weakly differentiable with derivatives of polynomial growth. Under Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new}, for $\tiX^{h,\delta}$ and $\hX^{h,\delta}$ respectively defined in \eqref{Eq:Half_step} and \eqref{eq_Xhdelta} it holds for any $p>1$ and $\delta \in (0,1/2)$ that
        \begin{align*}
            \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\tiX_T^{h,\delta}\bigr)\bigr]\Bigr|=\Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,\delta}\bigr)\bigr]\Bigr|\lesssim h + \delta^{\frac1p}
        \end{align*}
        Here the hidden constant also depends on $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Critical Threshold for User Population Survival) of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] To prevent demographic collapse (i.e., to have $C(\beta) \ge 1$), $\beta$ must be smaller than the critical threshold $\beta_c$, defined as:
\begin{equation}
    \beta_c \triangleq \max \left\{ 0,\frac{r-q}{2(q+r)}\right\}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Divided-power Koszul--Schur complex) of arXiv:2609.03282, 'Characteristic-free characterizations of projective space for smooth toric varieties'] Let
\begin{equation}
0\longrightarrow\cA\xrightarrow{\iota}\cB\xrightarrow{\pi}\cC\longrightarrow0
\end{equation}
be a short exact sequence of vector bundles on a scheme $S$.  For every integer $m\geq1$, there is an exact complex
\begin{equation}
\begin{split}
0\longrightarrow\Gamma^m\cA
&\xrightarrow{d_m}\Gamma^{m-1}\cA\otimes\cB
\longrightarrow\cdots\longrightarrow
\Gamma^q\cA\otimes\bigwedge^{m-q}\cB\\
&\xrightarrow{d_q}\Gamma^{q-1}\cA\otimes\bigwedge^{m-q+1}\cB
\longrightarrow\cdots\longrightarrow
\bigwedge^m\cB
\xrightarrow{\wedge^m\pi}\bigwedge^m\cC
\longrightarrow0.
\end{split}
\end{equation}
For $1\leq q\leq m$, the differential $d_q$ is the composite
\begin{equation}
\begin{split}
\Gamma^q\cA\otimes\bigwedge^{m-q}\cB
&\xrightarrow{\Delta_{q-1,1}\otimes\id}
\Gamma^{q-1}\cA\otimes\cA\otimes\bigwedge^{m-q}\cB\\
&\xrightarrow{\id\otimes(\iota\wedge-)}
\Gamma^{q-1}\cA\otimes\bigwedge^{m-q+1}\cB,
\end{split}
\end{equation}
where $\Delta_{q-1,1}$ is the $(q-1,1)$ component of the standard comultiplication on the divided-power algebra (see \eqref{eq:divided-comultiplication} below).

[Lemma l:local_ito_stratonovich_corrector of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $B$ be a ball of radius $\varrho\in (0,1/4]$. 
Let $\chi$ be a cutoff function such that $\chi|_{B}=1$ and $\mathrm{supp}\,\chi\subseteq 2 B$. Then there exist constants $C_0,\beta>0$ for which the following holds. For all $N\geq 1$, $\delta \in (0,1]$ such that $\delta N\geq 1$, $\Phi\in  W^{2,\infty}(B;{\mathbb R}^d)\cap H^1_0(B;{\mathbb R}^d)$, and $H\in L^2(2B;{\mathbb R}^{d\times d})$ satisfying 
\begin{equation*}
\mathrm{Tr} (H)=0 \text{ a.e.\ on }2 B, \qquad \text{ and }\qquad 
\nabla \cdot H=0 \ \text{ in }\mathscr{D}'(2 B),
\end{equation*}
it holds that 
\begin{equation}

|A^{N,\delta}(H,\Phi) |\leq \frac{C_0}{(\delta N)^{\beta}}\|H\|_{L^2(2B)}
\|\Phi\|_{W^{2,\infty}(B)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem6 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let $v^\varepsilon(t_0)$ $\in$  $H^1$ and $c_i(t_0) \in H^1$. Then, there exists a positive constant $a$ depending on $D$, $\varepsilon_0$ and $\nu$, and a positive constant $A$ depending on the initial data, universal constants, $\varepsilon$ and $\omega$ such that 
		\begin{align}
			\|\nabla \rho (t)\|_{L^2}^2+\|\nabla \sigma (t)\|_{L^2}^2 \leq  Ae^{-a(t-t_0)},
		\end{align}
		for all $t \geq t_0$. 
		\begin{proof}
			Adding (equation b26 of the paper) to (equation b32 of the paper) together, the conclusion can be proved.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:cS-def of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Let $(G,x)$ be a weighted planar graph with the combinatorics of the plane, and let $\mathcal{X}:\Upsilon^\times(G)\to\mathbb{C}$ be a solution to the full system of equations (equation eq:3-terms of the paper) around each quad. We say that $\mathcal{S}=\mathcal{S}_\mathcal{X}:\Lambda(G)\to\mathbb{C}$ is an s-embedding of $(G,x)$ associated with $\mathcal{X}$ if, for each $c\in\Upsilon^\times(G)$, we have\begin{equation}

\mathcal{S}(v^\bullet(c))-\mathcal{S}(v^\circ(c))=(\mathcal{X}(c))^2.
\end{equation}
For $z \in \diamondsuit(G)$, the quadrilateral $\mathcal{S}^\diamond(z) \subset \mathbb{C}$ is the region bounded by the edges connecting the vertices $\mathcal{S}(v_0^\bullet(z))$, $\mathcal{S}(v_0^\circ(z))$, $\mathcal{S}(v_1^\bullet(z))$, and $\mathcal{S}(v_1^\circ(z))$. The s-embedding $\mathcal{S}$ is called \emph{proper} if the quadrilaterals $\mathcal{S}^\diamond(z) = (\mathcal{S}(v_0^\bullet(z)) \mathcal{S}(v_0^\circ(z)) \mathcal{S}(v_1^\bullet(z)) \mathcal{S}(v_1^\circ(z)))$ do not overlap. It is called \emph{non-degenerate} if no quadrilateral $\mathcal{S}^\diamond(z)$ degenerates into a segment. No convexity condition is imposed on the quadrilaterals $\mathcal{S}^\diamond(z)$.

[Theorem th:d3 of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $d=3$. Then
\begin{equation}
    \lim_{n\rightarrow\infty}\frac{\Ca_{\mathbb{Z}^3}(\eta[0,n])}{3n^{1/\beta}}=\C_{\mathbb{R}^3}(\gamma[0,1])
\end{equation}
in distribution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Theorem 1.3 from \cite{KozhinaThesis}). Fix $T > 0$ and let us define a time-grid $\mathbb{T}_N := \{t_i\}_{i=1}^N$ for $N \in \mathbb{N}$. Under assumptions A1, A2, AD3 there exist constants $C \ge 1$ and $c \in (0, 1]$ such that for all $0 < t_i < t_j \le T$ and all $((x, y), (x', y')) \in (\mathbb{R}^{2d})^2$:
\begin{equation*}
|(p^\epsilon_h - p_h)(t_i, t_j, (x, y), (x', y'))| \le C \bar{\Delta}_{\epsilon,\gamma,q} \, p_{c,K}(t_j - t_i, (x, y), (x', y')),
\end{equation*}
where $p_{\epsilon,h}$ and $p_h$ stand for the transition densities of the perturbed and original Euler schemes respectively, starting from $(x, y)$ at time $t_i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:profile-sharp-subg of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:profile-sharp-subg}
We say that the random field satisfies \(({\rm PSG})_p\) if, for every
\(N\), \(x\in\mathbb S^{N-1}(1)\), and \(s\in\mathbb R\),
\begin{equation}
 \mathbb E e^{s h_N^J(x)}\le e^{s^2/(2N)}.
\end{equation}
This rank-one/profile-direction bound is a convenient finite-\(N\)
sufficient condition for the weaker tail-rate input below.

