[Definition 4 of arXiv:2606.03661, '2606.03661'] Let $G(\cdot)$ be the Barnes $G$-function (see Appendix~\ref{appendix.Barnes}). 
We define the $G$-Pochhammer symbol as 
\begin{equation}

\Lbrack a \Rbrack_n = \frac{G(a + n)}{G(a)} ,  
\end{equation}
where $a \in \mathbb{C}$.

[Prop 4 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Suppose that $\nu_{\Unif}$ is the uniform distribution on $\mathsf S_N$, $\pi\sim \nu_{\Unif}$, and $G$ is the shuffle graph generated as above. Then we have
		\begin{equation}
		d_{\TV} (\pi^G,\pi)
            =
            d_{\TV}\big(\Pi_{1\leq i\leq K}
            \bP(n_0^{(i)},\cdots,n_{k-1}^{(i)}),\nu_{\Unif}\big)
            .  
		\end{equation}

[Theorem 14 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\alpha > 0$ and $\kappa \geq \kappa_c$. There exist $\lambda = \lambda(\alpha, \kappa)$ and $\psi = \psi(\alpha,\kappa) > 0$ such that for all $r \geq 1$,
    \begin{equation}
        \P_{\alpha,\kappa}( 0 \leftrightarrow x_r) = \psi\lambda^r\, (1 + o_{\alpha,\kappa}(1)). 
    \end{equation}
    Furthermore, $\lambda$ is monotone increasing in $\alpha$, and it is the unique solution in $(\tau^2_\kappa, 1)$ to
    \begin{equation} 
         (\lambda^{-1} -1) \sum_{n \geq 0} \big( (1-\tau_\kappa^{2(n+1)})^{-\alpha} -1 \big) \lambda^{-n}  = 1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

