[Lem l:1104.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $\widehat{\eta}_{\rm D}$ be limit of $\{\widehat{\eta}_{n,r_n}\}$ along some subsequence, with $\{r_n\}$ as in~(equation e:1.11i of the paper). Then, there exists a coupling between $\widehat{\eta}_{\rm D}$, the random measure $\eta_{\rm D}$ from~(equation e:1.10i of the paper), and $h_{\rm D}^\psi$ from~(equation e:1104.13 of the paper), such that $\widehat{\eta}_{\rm D}$ and $h_{\rm D}^\psi$ are independent and 
\begin{equation}

\widehat{\eta}_{\rm D} \circ \tau^{-1}_{h^{\psi}_{\rm D}} = \eta_{\rm D} \,,
\end{equation}
where $\tau_{\psi}: {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2} \to {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2}$ is the translation operator
\begin{equation}
	\tau_{\psi}(x,s,\omega) =(x,s + \psi(x), \omega) \,.
\end{equation}
Moreover, along the above subsequence we have
\begin{equation}
	 \big(\eta_{n,r_n}, \widehat{\eta}_{n,r_n}, h_n^\psi\big) \Longrightarrow \big(\eta_{\rm D}, \widehat{\eta}_{\rm D}, h^\psi_{\rm D}\big) \,.
\end{equation}

[Lemma eq: short first row of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] For all $\lambda=(\lambda_1,\lambda_2,\ldots)\vdash n$, we have
\begin{equation}
-\frac{\lambda_1'}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le\frac{\lambda_1}{n},
\end{equation}
\begin{equation}
-1+2\frac{\lambda_1}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le1-2\frac{\lambda_1}{n}+2\left(\frac{\lambda_1}{n}\right)^2.
\end{equation}
In particular, when $\lambda_1\ge n-n^{o(1)}$, set $r:=n-\lambda_1$. Then, we have
\begin{equation}
\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}=1-2\frac{r}{n}+O(n^{-2+o(1)}).
\end{equation}

[Lemma 6 of arXiv:2604.01978, 'Homogenized Transformers'] Under Assumption \ref{ass:high_order_short}, there exist $C_1,C_2>0$ independent of $\alpha, \eta, L$ such that
\begin{enumerate}
\item $b\in C^4((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$.
\smallskip
\item We have
\begin{equation*}
    \upsigma \coloneqq \max_{X\in(\S^{d-1})^n}\|G(X,\cdot)\|_{L^2({\uprho_*})}<\infty
\end{equation*}
and 
\begin{equation*}
     \underset{X \in (\S^{d-1})^{n}}{\max}\|G(X,\cdot)\|_{L^3({\uprho_*})}\leq C_1\upsigma .
\end{equation*}
\smallskip 
\item For ${\uprho_*}$-a.e.\ $\bm{\theta}$, $G(\cdot,\bm{\theta})\in C^5((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$ and
\begin{equation*}
    \left\|\Big\|G(\cdot, \bm\theta)\Big\|_{C^5} \right\|_{L^2({\uprho_*})} + \left\|\Big\|\nabla_{G(\cdot,\bm{\theta})}G(\cdot,\bm{\theta})\Big\|_{C^5}\right\|_{L^2({\uprho_*})} \leq C_2 \upsigma .
\end{equation*}
\end{enumerate}
Moreover we can choose $C_1=O(1+\frac{\sigma_{\bA}\|\E\bV\|_{\mathrm{op}}\upbeta}{\sigma_{\bV}})$ and $C_2=O(1+\upbeta^{10}\sigma_{\bA}^{10}d^5)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro ERmb of arXiv:2601.20502, 'Optimal matching under size priority'] Under the same condition and notation of Theorem~(thm:mandatory of the paper), we have that
    \begin{align}
        &\frac{1}{|E(G_n)|}\sum_{e \in E(G_n)} \mathbbm{1}_{e \in \bigcap_{M \in M_{n,\max}}M} \overset{\mathbb{P}}{\longrightarrow} \gamma^2, \\
        &\frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{e \in \bigcap_{M \in M_{n,\max}}M^{\complement}} \overset{\mathbb{P}}{\longrightarrow} (1-\gamma)^2.
    \end{align}
    where the convergence holds in probability and $\gamma$ is the unique fixed point of $t \mapsto \hat{\phi}(1-t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi smooth of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] {Revuz}}}}]
{\rm Let $\nu$ be a $\sigma$-finite Borel measure. We say that $\nu$ is \emph{smooth (in the strict sense)} if:
\begin{enumerate}
\item[\rm(1)] $\nu$ does not charge any semi-polar sets.
\item[\rm(2)] There exists an increasing sequence of Borel sets 
$\{E_n\}$ such that $X=\bigcup_{n=1}^{\infty}E_n$ and 
\begin{enumerate}
\item[\rm(a)] $\nu(E_n)<\infty$ for each $n\in\mathbb{N}$.
\item[\rm(b)] $\int_{E_n}G_1(x,y)d\nu(y)$ is bounded with respect to $x$.
\item[\rm(c)] Let $T_n:=\sigma_{X\setminus E_n}$ and $T:=\lim_{n\to\infty}T_n$. Then, it should hold 
\begin{align*}
\mathbb{P}_x(T\geq\zeta)=1\quad\text{ for any }\quad x\in X.
\end{align*}
\end{enumerate}
\end{enumerate}
}

[Corollary coro1dimensional1 of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $S\subseteq \mathbb R$ be a subset with an accumulation point in $\mathbb R$ and $X=(X_t)_{t\in [0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$. Fix $\varepsilon>0$ and assume that $b_j,a_{ij}\in\mathcal O_\varepsilon(S)$ and 
\begin{align}
    \int_{\mathbb R}\xi^\beta K(\cdot,d\xi) \in \mathcal{O}_\varepsilon(S),\quad \text{for all }  \beta\geq2. 
\end{align}
Suppose furthermore that the following conditions hold true.
\begin{enumerate}
\item for all $x\in {S}$, $ \int_{|\xi|>1} \exp(|\xi|) K(x,d\xi)<\infty;$
    \item the real valued map
$\sum_{\beta\geq2}\frac{1}{\beta!}|h_{\mathbf{m}^\beta}(\cdot)|
$
is locally bounded on $P^1_{R(S)+\varepsilon}(0)$.
\end{enumerate}
Fix 
\begin{equation}
    G>\sup_{x\in {S}}\sup_{\xi\in \textup{supp}(K(x,\cdot))}|x|+|\xi|
\end{equation}
and set $\mathcal{V}$, $\mathcal{V}^*$ as in equation (equation eq:Vgeneralkernel of the paper).  Then $X$ is an $S$-valued $\mathcal{V}$-holomorphic process and
for all $\mathbf{u}\in\mathcal{V}^*$  
$$\mathcal{A}h_\mathbf{u}=h_{L(\mathbf{u})}|_S,$$
where $L:\mathcal{V}^*\rightarrow \mathcal{S}^*$  is the operator defined in equation (equation eq:Lgeneralkernel of the paper), whose explicit form for $d=1$ reads
\begin{align}
    L(\mathbf{u})_\alpha=(\mathbf{u}^{(1)}\ast \mathbf{b})_\alpha+\frac{1}{2}(\mathbf{u}^{(2)}\ast (\mathbf{a}+\mathbf{m}^2))_\alpha+\sum_{\beta=3}^\infty\frac{1}{\beta!}(\mathbf{u}^{(\beta)}\ast \mathbf{m}^\beta)_\alpha.
\end{align}
for all $\mathbf{u}\in\mathcal{V}^*$, $\alpha\in\mathbb{N}_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defination 7 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let  $(A(t))_{t\ge 0}$  be  a family  of  measurable  locally  bounded processes with  values in the class of  $n \times n $  matrices, let $\zeta $  be  the matrix-valued  solution of \begin{equation}
				\dot{\zeta}(t)= A(t) \zeta(t),~~~\zeta(0)= I.
			\end{equation}

			\noindent	 We will  say  that $(A(t))_{t\ge 0}$  is  \textbf{exponentially  stable} if there  exist  some positive  constants  $C$  and $c$    such  that for $s \leq t$,
			\begin{equation} 
				\vert \zeta(t)\vert\leq C e^{ (- c(t-s))} \vert \zeta(s) \vert.
			\end{equation}

[Theorem main_theorem_toric of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $X$ be a smooth, projective, split toric variety over $\mathbb{Q}$ of Picard rank $\rho\ge 2$ with open orbit $U$, and let $\pi\colon Y\to X$ be as in (constr:family-over-toric-base of the paper). Write $\Delta = \sum_{d\in \mathcal{D}} \Delta_d$ and assume (eq:affine-asymp of the paper) for $i\in \mathcal{I}$. If $-\vec \Delta$ is of convergent type, then the number 
	\begin{equation*}
		N(B) = \sharp\{x\in U(\mathbb{Q}) : Y_x(\mathbb{A}_\mathbb{Q})\ne \emptyset,\ H(x)\le B\}
	\end{equation*}
	of everywhere locally soluble fibres satisfies
	\begin{equation*}
		N(B) = c B (\log B)^{\rho-1-\Delta} + O_\pi \!\left(B (\log B)^{\rho-1-\Delta-\varepsilon}\right),
	\end{equation*}
	where
	\begin{equation*}
		c= \frac{\alpha(X)}{2^{n+\rho}}  \omega_\infty \prod_p  \left( 1-\frac{1}{p}\right)^{\rho}\frac{|\mathfrak{X}(\mathbb{F}_p)|}{p^n} \prod_{d\in \mathcal{D}} c_d a_d^{\Delta_d},
	\end{equation*}
    and $\varepsilon >0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lemcov of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] For any $\epsilon>0$, large $k$ and $j>k$ such that  $j-k$ large 

\begin{align*}
 & |Cov[(\overline{Z}_{\rho_j}-\overline{Z}_{\eta_{j}}),(\overline{Z}_{\rho_k}-\overline{Z}_{\eta_{k}})]| \\
 & \leq 8\mathbb{E}(\overline{Z}_{\eta_{j-k}}^{\alpha})((Var(\overline{Z}_{\eta_{k}}^{\alpha}))^{1/2}+\epsilon \mathbb{E}(\overline{Z}_{\eta_k}^{\alpha}))+ 2Var( \overline{Z}_{\eta_k}^{\alpha}) \nonumber  \\
 & +cste\epsilon^{-\alpha/(1-\alpha)} (j-k)^{\alpha/(1-\alpha)} ((Var( \overline{Z}_{\eta_k}^{\alpha}))^{1/2}+\epsilon \mathbb{E}(\overline{Z}_{\eta_k}^{\alpha}))+2\epsilon \mathbb{E}(\overline{Z}_{\eta_k}^{2\alpha})+4 \mathbb{E}(\overline{Z}_{\eta_k}^{\alpha}). 
 \end{align*}

