[Proposition prop:underline_comp of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $X$ satisfy Assumption~(ass:chi of the paper)(i). Fix a (large) $L>0$ and (small) $c_0,\epsilon,\xi>0$. Let $\theta>0$ be a (possibly, $N$-dependent) small parameter. Consider $k_j\in [N]$, $z_j\in\mathbf{C}$, and $w_j=\mathrm{i}\eta_j$ with $\eta_j>0$, for $j=1,2$. Denote $x_j:=k_j/N$, $G_j:=G^{(k_j),z_j}_{x_j}(w_j)$ and assume that $x_1\le x_2$. Recall the definition of $\kappa_4$ from (equation eq:def_kappa_4 of the paper). It holds that
\begin{equation}
\mathbf{E} \langle G_1-\mathbf{E} G_1\rangle \langle G_2-\mathbf{E} G_2\rangle = \frac{1}{2x_1x_2N^2}\left(V_{12}+\bm{1}_{\beta=1}V_{1\overline{2}}+\kappa_4 x_1^2 U_1U_2\right) + \mathcal{O}_\theta\left(\left(\frac{1}{N\eta_*}+\frac{1}{\sqrt{N}}\right)\frac{N^\xi}{N^2\eta_1\eta_2}\right),

\end{equation}
uniformly in $x_j\in [c_0,1]$, $z_j\in\mathbf{C}$ with $\theta\le |\sqrt{x_j}-|z_j||\le L$, and $N^{-1+\epsilon}\le \eta_j\le N^L$, for $j=1,2$. In (equation eq:Cov_UV of the paper) we denoted $\eta_*:=\min\{\eta_1,\eta_2\}$ and
\begin{equation}
\begin{split}
U_j=U_j(x_j,\eta_j,z_j):=&\frac{\mathrm{i}}{\sqrt{2}}\partial_{\eta_j}m_j^2,\quad j=1,2,\\
V_{12}:=V\big((x_1,\eta_1,z_1),(x_2,\eta_2,&z_2)\big),\quad V_{1\overline{2}}:=V\big((x_1,\eta_1,z_1),(x_2,\eta_2,\overline{z}_2)\big),\\ 
V\big((x_1,\eta_1,z_1),(x_2,\eta_2,z_2)\big):=&\frac{1}{2}\partial_{\eta_1}\partial_{\eta_2}\log \left[1+x_1^2\left(u_1u_2|z_1z_2|\right)^2 -x_1^2m_1^2m_2^2 -2x_1u_1u_2\Re [z_1\overline{z}_2]\right],\\
\end{split}

\end{equation}
where $m_j:=m^{z_j}_{x_j}(w_j)$ and $u_j:=u^{z_j}_{x_j}(w_j)$.
The implicit constant in $\mathcal{O}_\theta(\cdot)$ is bounded from above by $\theta^{-D}$ for some (large) fixed $D>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Assume that the model is locally identifiable and satisfies the standard
regularity conditions for Fisher-information calculations, including common
support in a neighborhood of the true parameter, differentiability with respect
to \((\boldsymbol{\theta},\boldsymbol{\xi})\), interchange of differentiation
and integration, finite second moments of the relevant score functions, and
nonsingularity of \(\boldsymbol{B}_{\boldsymbol{\xi}\boldsymbol{\xi}}\).
Then the efficient Fisher information for
\(\boldsymbol{\theta}\), after eliminating the missingness-specific nuisance
parameter \(\boldsymbol{\xi}\), is
\begin{equation}
\boldsymbol{I}_{\mathrm{PC}}^{\mathrm{eff}}
(\boldsymbol{\theta})
=
\boldsymbol{I}_{\mathrm{CC}}
(\boldsymbol{\theta})
-
\boldsymbol{D}
(\boldsymbol{\theta},\boldsymbol{\xi})
+
\boldsymbol{I}_{M}^{\mathrm{eff}}
(\boldsymbol{\theta},\boldsymbol{\xi}),

\end{equation}
where
\begin{equation}
\boldsymbol{D}
(\boldsymbol{\theta},\boldsymbol{\xi})
=
E
\left[
q(\boldsymbol{Y};\boldsymbol{\theta},\boldsymbol{\xi})
\,
\boldsymbol{I}_{Z\mid\boldsymbol{Y}}
(\boldsymbol{\theta};\boldsymbol{Y})
\right],

\end{equation}
and
\begin{equation}
\boldsymbol{I}_{M}^{\mathrm{eff}}
=
\boldsymbol{B}_{\boldsymbol{\theta}\boldsymbol{\theta}}
-
\boldsymbol{B}_{\boldsymbol{\theta}\boldsymbol{\xi}}
\boldsymbol{B}_{\boldsymbol{\xi}\boldsymbol{\xi}}^{-1}
\boldsymbol{B}_{\boldsymbol{\xi}\boldsymbol{\theta}}
\succeq
\boldsymbol{0}.

\end{equation}
Here
\(\boldsymbol{I}_{\mathrm{CC}}(\boldsymbol{\theta})\) denotes the Fisher
information that would be available if all class labels were observed. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:density_stable_expression of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $Z \sim S_\alpha(1,\beta,0)$ and denote by $f_{Z}$  the corresponding density function. Then, for $\alpha \neq 1$ and  $\theta_0 = \alpha^{-1} \arctan ( \beta \tan(\pi\alpha/2))\mathbf{1}_{\alpha \neq 1} +
\frac\pi2 \mathbf{1}_{\alpha=1}$, the density $f_Z$ can be expressed for $x\in \mathbb{R}$ as 
\begin{align*}
f_{Z}(x)&=\begin{cases} \frac{\alpha x^{\frac{1}{\alpha-1}}}{\pi |\alpha-1|} \displaystyle \int_{\theta_0}^{\pi/2} V_{\alpha,\beta}(\theta) \exp\left(-x^{\frac{\alpha}{\alpha-1}} V_{\alpha,\beta}(\theta) \right) d\theta & x>0,\\
\pi^{-1}\Gamma(1+ \alpha^{-1}) \cos(\theta_0) (\cos(\alpha\theta_0))^{1/\alpha} & x=0,\\
f_{-Z,\alpha}(x) & x<0.
\end{cases}
\end{align*}
where $-Z \sim S_\alpha(1,-\beta,0)$. For $\alpha=1$, the density $f_Z$ can be expressed for $x\in \mathbb{R}$ as 
\begin{align*}
f_{Z}(x)&=\begin{cases} \frac{1}{2\beta} e^{-\frac{\pi x}{2\beta}}\displaystyle \int_{-\pi/2}^{\pi/2} V_{1,\beta}(\theta) \exp\left(-e^{-\frac{\pi x}{2\beta}} V_{1,\beta}(\theta) \right) d\theta & \beta \neq 0,\\
\frac{1}{\pi(1+x^2)} & \beta=0.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

