[Thm matrix-main of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Fix integers $r_{\star}\ge1,$ $k\ge2$, and
set $t\coloneqq k/r_{\star}$. Suppose $\operatorname{rank}(X_{\star})\le r_{\star}$
and that $\mathcal{A}\in\operatorname{RIP}(\delta,k)$. If $\delta<\delta_{\mathrm{sharp}}(t)$ and
the regularization parameter $\lambda>0$ satisfies
\begin{equation}
\lambda\ge2\frac{1+\rho_{\delta,t}}{1-\rho_{\delta,t}}\normop{\mathcal{A}^{*}(\xi)},
\end{equation}
then for any search rank $r\ger_{\star}$, the solution $X_{\lambda,r}$
in ((eq:matrix-lasso of the paper)) satisfies\begin{subequations}
\begin{align}
\normtwo{\mathcal{A}(X_{\lambda,r}-X_{\star})} & \le\frac{4\tau_{\delta,t}}{1-\rho_{\delta,t}}\sqrt{r_{\star}}\,\lambda,\\
\normF{X_{\lambda,r}-X_{\star}} & \le\frac{16\tau_{\delta,t}^{2}}{(1-\rho_{\delta,t})^{2}}\sqrt{r_{\star}}\,\lambda.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] For every $\delta \in (1,\infty)$ the approximate initial-boundary value problem $\mbox{(AP)}{}_{\text{{\tiny $\delta$}}}$ admits at least 
one strong solution $(u_{\text{{\tiny $\delta$}}},v_{\text{{\tiny $\delta$}}},w_{\text{{\tiny $\delta$}}})$ on $[0,T]$ satisfying 

\begin{equation}
u_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad v_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad w_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad \text{a.e.}~(x,t) \in Q_T.
\end{equation}

\indent
Moreover, the following estimates hold:
\begin{enumerate}\leftskip6pt
\item[(1)] There exists a constant $C_{21}>0$, which depends on $\delta$, $T$, $\|u_0\|_{H^1(\Omega)}$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$,
such that

\begin{equation*}
\int_0^T \|u_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \sup_{0 \le t \le T} \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^T \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2 dt \le C_{21}.
\end{equation*}

\item[(2)] There exists a constant $C_{22}>0$, which depends on $\delta$, $T$ and $\|v_0\|_{H^1(\Omega)}$, such that

\begin{equation*}
\int_0^T \|v_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \max_{0 \le t \le T} \|v_{\text{{\tiny $\delta$}}}(t)\|_{L^2(\Omega)} \right)^2 \le C_{22}.
\end{equation*}

\item[(3)] There exists a constant $C_{23}>0$, which depends on $\delta$, $T$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that

\begin{equation*}
\int_0^T \|w_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^T \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2 dt \le C_{23}.
\end{equation*}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

