body:
[Corollary of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] For every $n\in\mathbb N$, $\lambda>0$, and $\theta\in(0,1/2)$, the functions
    \begin{align}
        F_1(z)\coloneqq \left(\frac12+\frac{1}{2\bigl(1+\frac{\theta\lambda}{n}(1-z)\bigr)}\right)^n,
        \qquad
        F_2(z)\coloneqq \left(
        \frac{2+\frac{\theta\lambda}{n}(1-z)}
        {2+\frac{2\lambda}{n}(1-z)+\frac{\theta\lambda^2}{n^2}(1-z)^2}
        \right)^n
    \end{align}
    are pgfs satisfying
    \begin{align*}
        \Phi_n(F_1(z),F_2(z))
        =
        \left(1+\frac{\lambda}{n}(1-z)\right)^{-n},
        \qquad
        \Phi_n(x,y)\coloneqq \bigl(x^{-1/n}+y^{-1/n}-1\bigr)^{-n},
    \end{align*}
    but neither factor belongs to the negative binomial family $\left\{\left(1+\frac{\mu}{n}(1-z)\right)^{-n}:\mu>0\right\}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem the1ch5 of arXiv:2512.09308, 'On asymptotic behavior of solutions to random fractional Riesz-Bessel equations with cycli'] Consider the random field $u(t,x),$ $t>0,$ $x\in\mathbb R,$ defined by ~{\rm ((modch5 of the paper))} with  $\alpha>1/2$, and the random initial condition {\rm((modCch5 of the paper))}. Let $\xi (x),$ $x\in \mathbb R,$ have a covariance function satisfying Assumption~{\rm(Asumptionmain of the paper)} with $A_{0}=0$. If $\varepsilon\to 0,$ then the finite-dimensional distributions of the random fields
\begin{equation*}
    U_{\varepsilon}(t,x)={\varepsilon^{-\beta/2\alpha}}u\left(\frac{t}{\varepsilon},\frac{x}{\varepsilon^{\beta/\alpha}}\right)
\end{equation*}
converge weakly to the finite-dimensional distributions of the zero-mean Gaussian random field defined by
\begin{equation}ch5}
    U_{0}(t,x)=\sqrt{\sum_{j=1}^{n}c_1(\kappa_j)A_{j}K_{\frac{\kappa_j-1}{2}}(|w_j|)|w_j|^{\frac{\kappa_j-1}{2}}}\int_{\mathbb R}e^{i\lambda x} E_{\beta}\left(-\mu t^{\beta}|\lambda|^{\alpha}\right)W(d\lambda),
\end{equation}
with the covariance function
\begin{align}
  {\rm Cov}\left(U_{0}(t,x), U_{0}(t',x')\right)&=\sum_{j=1}^{n}2c_1(\kappa_j)A_{j}K_{\frac{\kappa_j-1}{2}}(|w_j|)|w_j|^{\frac{\kappa_j-1}{2}}\nonumber\\
  &\times\int_{0}^{
  +\infty}\cos\lambda(x-x')E_{\beta}(-\mu t^{\beta}|\lambda|^{\alpha})E_{\beta}(-\mu (t')^{\beta}|\lambda|^{\alpha})d\lambda.
\end{align}

