[Lemma lem:vthd of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] {bass1992lifetimes}}]
    If for any $x\in D$, there exists $b>0$ such that
\begin{equation}
\mathrm{dist}(x',\partial D)\ge C_6(b+l(\gamma_x(x,x')))^{1/\alpha},\ \text{ for all } x'\in\gamma_x,
\end{equation}
letting $\delta(x)$ be the supremum of $b$'s that satisfy (equation eq:2193 of the paper), then this ${\delta}$ is bounded continuous, and satisfies conditions (i) and (ii) in Definition~(def:thd of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor clt:I_n of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] Let $I^{(n)}:=\left(I_1^{(n)},\dots,I_m^{(n)}\right)\overset{d}{=}M(n;1/m,\dots,1/m)$. Then, with $\mu^{(n)}=(n/m,\ldots,n/m)^t$, we have
    \begin{align}
        I^{(n),\ast}:=\frac{I^{(n)}-\mu^{(n)}}{\sqrt{n}}\overset{d}{\longrightarrow} N=(N_1,\ldots,N_m),
    \end{align}
    where $\mathcal{L}(N)=\mathcal{N}(0,\Sigma)$ with 
\begin{equation}
\Sigma = \left( \begin{array}{cccc}
    \frac{m-1}{m^2} &-\frac{1}{m^2}& \cdots & -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \ddots & &\vdots\\
    \vdots &  & \ddots& -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \dots & -\frac{1}{m^2}& \frac{m-1}{m^2}
    \end{array}
    \right).
\end{equation}

[Theorem thm:design of arXiv:2510.22778, 'Free denoising diffusion models'] Let $\mu_{*}$ be a compactly supported probability measure with a density $\psi_{*}$
that is H\"older continuous on $K:=\supp\mu_{*}$, and let $f\in C(K)$ with $f>0$.
Then the principal value in
\begin{equation}
  b_{*}(x)=-f(x)^{2}\,H(f^{2}\mu_{*})(x),
  \qquad H(f^{2}\mu_{*})(x)=\mathrm{p.v.}\!\int_{K}\frac{f(y)^{2}\,\mathrm{d}\mu_{*}(y)}{x-y}
\end{equation}
converges for every $x\in K$ and $b_{*}$ is itself H\"older continuous there, and
$\mu_{*}$ is a stationary spectral law of the free diffusion
$\mathrm{d} X_{t}=b_{*}(X_{t})\mathrm{d} t+f(X_{t})\mathrm{d} S_{t}\,f(X_{t})$.

[Lemma 1 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] The limiting drift $\Delta_k$ satisfies the following properties for all $k\geq 1$.
\begin{enumerate}
    \item  $\Delta_k(\gamma_1)>0>\Delta_k(1-\gamma_0)$ and $\Delta_k$ has at least one and at most three real roots (counting multiplicity) in the interval $\mc S$.
    \item  Let $r_1$ and $r_2$ denote the smallest and the largest real roots of $\Delta_k$ in $\mc S$, respectively, with the possibility of $r_1=r_2$ when the root is unique. Then, for $\gamma_0\neq\gamma_1$ we have
    \begin{align}
        (\gamma_1-\gamma_0)(r_1+r_2-1+\gamma_0-\gamma_1) > 0,

    \end{align}
    Similarly, for $\gamma_0=\gamma_1$, we have $r_1+r_2=1$ and we always have a root of $\Delta_k$ at $1/2$.








\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2606.03661, '2606.03661'] Let $\alpha \in (0,1)$ and $\nu>-1$. For a differentiable function 
$f:\mathbb{R}^+ \to \mathbb{R}$, the beta-weighted derivative
of $f$ is defined by
\begin{equation}

(\mathscr{D}_t^{(\alpha,\nu)} f)(t) := 
\frac{t^{\alpha-\nu-1}}{\Gamma(1-\alpha)} 
\int_0^t \tau^\nu (t-\tau)^{-\alpha} f^\prime(\tau) \, d\tau .
\end{equation}

[Theorem 30 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\alpha\in\mathbb R$. The assignment
\begin{equation}

\hat\Lambda_{S,1,\alpha}^{\mathrm q}:Z\hat C^{1}(\Delta^3_T;B_\alpha)\to \mathfrak Q_{\mathrm{fr},\mathrm{log}}^{1,\alpha},
\quad h\mapsto \hat\Lambda_{S,1,\alpha}^{\mathrm q}h,\quad 
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau:=[r_{\mathrm d}^\tau(h)]_\tau,
\end{equation}
is a well-defined continuous linear map. It satisfies the following properties
\begin{enumerate}
\item for every $\tau\in[0,T]$ and every representative $r^\tau\in \bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau$, $\delta r^\tau = h^\tau$;

\item in particular, for every $0\le s\le u\le t\le T$ and every representative $r^t\in \bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^t$, $(\delta r^t)_{tus}=h_{tus}$;

\item for every $h\in Z\hat C^{1}(\Delta^3_T;B_\alpha)$, the uniform estimate $\|\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\|_{\mathfrak Q_{\mathrm{fr}, \mathrm{log}}^{1,\alpha}}\le C_{T} M_{\alpha,T}\|h\|_{1,\alpha}$ holds.
\end{enumerate}

