[Lemma 8 (Algebraic integrability only depends on the field of definition) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $K'/K$ be a finite extension of fields of characteristic zero. 
    \begin{enumerate}
        \item Any foliation $\F$ on $K$ over $k$ uniquely extends to a foliation on $K'$ over $k$, where $k$ is a subfield.
        \item If $\F$ is of rank $1$, and $D$ is a basis of $F$, then if there exists $F\in K'$ non-constant such that $D(F)=0$, then there exists $G\in K$ non-constant such that $D(G)=0$.
        \item If $\F$ is algebraically integrable over $K'$, then it is algebraically integrable over $K$.
    \end{enumerate}

[Proposition 30 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(a>0\),
\begin{equation}
  Z_a\,\widehat{\EE}_a[J_a^{-1}]
  =\EE[I(a)^{-1}].

\end{equation}
Furthermore,
\begin{equation}
  a^{1-H}\EE[I(a)^{-1}]
  \longrightarrow H\,\EE[M].

\end{equation}
Consequently, if
\(\widehat{\EE}_a[J_a^{-1}]\longrightarrow D_H\in(0,\infty)\), then
\begin{equation}
  a^{1-H}Z_a\longrightarrow\frac{H\,\EE[M]}{D_H},

\end{equation}
and then \eqref{eq:rough-sharp-persistence-asymptotic}--
\eqref{eq:rough-persistence-constant} follow.

[Theorem th: moment formula holomorphic of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Set $X_0=x_0\in S$, fix $\mathbf{u}\in \mathcal V^*$, and suppose that the following conditions hold true.
\begin{enumerate}\phantomsection
    \item The sequence-valued linear ODE
    \begin{align}
        \mathbf{c}(t)=\mathbf{u}+\int_0^tL(\mathbf{c}(s))ds, \qquad t\in [0,T],
    \end{align}
    admits a $\mathcal V^*$-valued solution $(\mathbf{c}(t))_{t\in[0,T]}$  such that
   \begin{align}
       h_{\mathbf{c}(t)}(x)=h_\mathbf{u}(x)+\int_0^th_{L(\mathbf{c}(s))}(x)ds,
   \end{align}
  for all $x\in S$, $t\in[0,T]$.

    \item The process $(N^{h_{\mathbf{c}(s)}}_t)_{t\in[0,T]}$ given in equation (equation eq:localmart of the paper) defines a true martingale for each $s\in [0,T].$
    \item $\int_0^T\int_0^T\mathbb E[|\mathcal{A}h_{\mathbf{c}(s)}(X_t)|]dsdt<\infty$.
\end{enumerate}
Then for each $\mathbf{u}\in \mathcal V*$ it holds that
\begin{align}
    \mathbb E[h_\mathbf{u}(X_T)]=h_{\mathbf{c}(T)}(x_0).
\end{align}

