[Lemma DensityQuotient of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] Let $o\in\Lambda\Subset\mathbb{Z}^d$, $\omega \in \Omega^+_\Lambda$ with $\omega_o\neq 1$, and $\zeta\in \mathbb{R}^{\Lambda}$. Then, 
\begin{enumerate}[label=(\roman*)]
    \item the flipped configuration obeys the hard-core constraint $\omega ^{A_\omega }\in \Omega^+_\Lambda$ and
    \item the quotient of the densities is given by
    \begin{align*}
    \frac{f^+_\Lambda(\omega, \zeta)}{f^+_\Lambda(\omega^{A_\omega}, \zeta^{A_\omega})}=\exp\Big(\sum_{x\in  \partial^1 A_\omega }(-\lambda +\varepsilon \zeta_x) 
    \Big)Z^{\varepsilon \zeta^{A_\omega }} _{\Lambda, + }/Z^{\varepsilon\zeta} _{\Lambda, + }.
    \end{align*}
\end{enumerate}

