[Lemma L:TBF of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] Suppose that $Z$ is injective. Then 
\begin{equation}  
  P_E( F | H_y) = {\mathbb P}(F| G_y) \quad \hbox{ for all $F \in {{\mathcal F}_W}$.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Evolution of blockage: horizontal finite range.}

Recall the notations of Theorem \ref{evo}. Let $N$ be a fixed integer. The restriction of the law of $(X_n, H_n)_{0\leq n\leq N}$ to $\Half^{n+1}$, or in other words, the restriction of the law of the evolution of blockage to the event of always finding a blocking building in range has density with respect to the product measure $\mu\displaystyle\bigotimes_{i=1}^{N} (\Leb \otimes \mathcal{L})$, which is given by
\begin{align*}
g_{N, R}: (x_n, h_n)_{0\leq n\leq N} \mapsto \lambda^N\exp\Biggl(-\lambda\Biggl(&\frac{\primi(h_{n-1}+Rt_n)}{t_n}-\frac{\primi(h_0)}{t_1}+\sum_{i=1}^{n-1}\primi(h_i)(\frac{1}{t_{i}}-\frac{1}{t_{i+1}})\\
&+ \sum_{i=1}^{n-1} (\frac{\primi(h_i + r_i (t_i \wedge t_{i+1}))}{t_i\wedge t_{i+1}}-\frac{\primi(h_i +r_i t_{i+1})}{t_{i+1}})\Biggl)\Biggl)\\
\prod_{1\leq i\leq n}&\mathds{1}_{x_i\in ]x_{i-1}, x_{i-1}+R]}\mathds{1}_{t_i\leq t_{i-1} \text{ or } x_i > x_{i-2}+R },
\end{align*}
where:
\begin{itemize}
    \item The $t_i$ are defined to be the slopes from $(x_{i-1}, h_{i-1})$ to $(x_i, h_i)$ (with the convention $t_0 = +\infty$).
    \item The $r_i$ are defined as the \textit{leftover signal range}: $r_i := R-(x_i-x_{i+1})$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:300.32 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $\gamma$ is small enough, then, given any $0 < \eta' < \eta< \tfrac{1}{2}$ small enough (depending only on $\gamma$), for any fixed $\epsilon > 0$ and $u \geq 0$ we have  
\begin{equation}
\frac{\sum_{j \in J_{k,l}} \big|{\mathbf R}_n^{k,\epsilon}(u;j)\big|}{|{\mathbf R}^{k,\epsilon}_n(u)|} \overset{\mathbb{P}}{\longrightarrow} 1
\end{equation}
in the limit as $n \to \infty$ followed by $k \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gp independent of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] Let $(Y_n)_{n\in\mathbb{N}}$ and $(Z_n)_{n\in\mathbb{N}}$ be two independent usual random walks on $G$ with step distribution $\mu$ and starting at $o$ and $Y_{\infty}, Z_{\infty}$ the respective hitting points on $\partial G$. Then for $n>D$ big enough
\begin{enumerate}
\item  $ \mathbb{P}_o\Big[\big(Y_n,Z_{\infty})^{{\mathcal G}}_o\geq D\Big]\asymp {\rm e} ^{-D}$, and 
\item  $ \mathbb{P}_o\Big[\big(Y_n,Z_n)^{{\mathcal G}}_o\geq D\Big]\asymp {\rm e} ^{-D}$.
\end{enumerate}

