[Lemma 180 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $\usigma $ be a Borel $d\times d_{1}$-valued 
  and $\ub$ be a Borel $\bR^{d}$-valued functions on $\bR^{d+1}$. Assume that $\ua:=\usigma\usigma^*$ is $\bS_{\delta'}$-valued.
Then there exist   
\begin{equation}

\widehat{D\sigma}=\widehat{D\sigma}(d, \delta',q_{0},p_{0},\beta)>0,\quad
\hat{b}=\hat{b}(d, \delta',q_{0},p_{0},\beta,
\rho_{a})>0
\end{equation}
such that if
\begin{equation}

D\usigma\in L_{1,\loc}(\bR^{d+1}),\quad
\widehat { D\usigma}_{p_{0},\rho_{a}}\leq 
 \widehat{D\sigma},
\quad\hat{\ub}_{p_{0} , \rho_{b} }
< \hat b,
\end{equation}
then

 (i) we have
 \begin{equation}

e\widehat { D\ua }_{p_{0} ,\rho_{0}}\leq 
 \widehat{Da},
\quad e\hat {\ub}_{p_{0} , \rho_{0} }
\leq  \hat b,
\end{equation}
where $(\widehat{Da},\hat b)=
(\widehat{Da},\hat b)(d,\delta',p_{0})$, are taken from Lemma 
\ref{lemma 11.26,3} when $n=1$ there;

(ii) we have
\begin{equation}

N_{1}\hat {\ub}_{p_{0},q_{0}, \rho_{b}}<\sfb_{0}(d,\delta'),
\end{equation}
where $N_{1}=N_{1}(d,\delta',q ,p,\beta ,\rho_{a} )$ is taken from \eqref{11.15,4};

(iii) we have
\begin{equation}

\ua^{\shharp}_{\rho_{a}}\leq 
\hat  a,\quad\hat {\ub}_{q_{0},p_{0}, \rho_{b}}\leq
\hat  b ,
\end{equation}
where
$$
\hat a=\hat  a(d,\delta',q,p,\beta)>0,\quad\hat b=\hat  b(d,\delta',q,p,\beta,\rho_{a} )>0,
$$ 
are taken from Theorem \ref{theorem 5.8,20};

(iv) we have
\begin{equation}

e\widehat { D\usigma }_{p_{0},\rho_{0}}\leq 
 \widehat{D\sigma},\quad e\hat {\ub}_{p_{0} , \rho_{0} }
\leq  \hat b,
\end{equation}
where $(\widehat{D\sigma},\hat b )=(\widehat{D\sigma},\hat b )(d,\delta' ,p_{0},n)$ are taken from
Theorem \ref{theorem 6.21.1} with integer $n>d/4$ there and the degree of the polynomial equal to two. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm th.SFG of arXiv:2411.13099, 'Long time behavior of killed Feynman-Kac semigroups with singular Schr{ö}dinger potentials'] Assume that:
\begin{itemize}
\item[] {\rm \textbf{[SF$_0$]}} For every $t>0$ and  $f\in b\mathcal B(\mathscr M)$,  $\mathfrak z\in \mathscr M \mapsto U^{\mathfrak X}_t f(\mathfrak z)$ is continuous.     
\item[]     {\rm \textbf{[P$_{t=s}$]}} The mapping $\mathfrak z \in \mathscr M\mapsto \mathfrak X_t(\mathfrak z)$ is continuous in $\mathbb P$-probability.  
    \item[] {\rm \textbf{[D$_{\rm e}$]}} For all $t>0$ and $\mathfrak z\in \mathscr M$,  $\mathfrak X_t(\mathfrak  z)$ has a density w.r.t. the Lebesgue measure. 

\item[] {\rm \textbf{[$I\mathbf V_{\mathbf S}$]}} For all $t\ge 0$ and all $\mathfrak  z_n \to \mathfrak  z\in \mathscr M$, $ \int_0^t \mathbf V (\mathfrak X_s(\mathfrak  z_n))ds\to \int_0^t \mathbf V (\mathfrak X_s(\mathfrak  z))ds$ in $\mathbb P$-probability. 

  \end{itemize}

  Then,  {\rm \textbf{[SF$_1$]}} is satisfied. Assume in addition that 
  \begin{itemize}
  \item [] {\rm \textbf{[B]}} For all compact   subset $K$ of $\mathscr V$,  $\lim_{s\to 0^+}\sup_{\mathfrak  z\in K}  \mathbb P_{\mathfrak z}[\sigma^\mathfrak X_{\mathscr V}\le s]=0$.
  \end{itemize}
Then {\rm \textbf{[SF$_2$]}}   holds.

[Lemma 32 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, for every deterministic vector $\bbx\in\C^L$,
        \begin{align}
                \sum_{\mu=M+1}^{L}\abs{G_{\bbx\mu}}^2 =\frac{(\Im G)_{\bbx\bbx}}{\eta}. 
        \end{align}
        Let $\wh\bbx:=\wh I\bbx$ and $\wt\bbx:=\wt I\bbx$. Then
        \begin{align}
                \sum_{a=1}^{L}\abs{G_{\wh\bbx a}}^2 & \prec\frac{(\Im G)_{\wh\bbx\wh\bbx}+\eta\|\wh\bbx\|^2}{\eta},   \\
                \sum_{a=1}^{L}\abs{G_{\wt\bbx a}}^2 & \prec\frac{(\Im G)_{\wt\bbx\wt\bbx}+\eta\|\wt\bbx\|^2}{\eta}. 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma energy_estimate_lemma_statement of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Let $\sigma$ represent the mobility, i.e. $\sigma(\alpha):=\alpha(1-\alpha)$. Then
    \begin{align} 
        \mathbb{E}_{\mathbb{Q}} \left[ \sup_{H \in C([0,T];C^1([0,1]))} \left\{ \int_0^T \int_0^1 \nabla H_s(x) \rho_s(x) dxds - 2 \int_0^T \int_0^1 [H_s(x)]^2 \sigma(\rho_s(x))dxds\right\}\right]  { < \infty.}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

