[Definition 29 (Augmented liquid region) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Given  $\delta > 0$ and $N \ge 1$,
        define the \emph{augmented liquid region} $\mathfrak{L}^{+}_{q; a, b, c} (\delta) = \mathfrak{L}_{q; a, b, c} (\delta; N) \subset \mathfrak{X}_{a, b, c}$ by setting 
		\begin{flalign}

			\mathfrak{L}^{+}_{q; a, b, c} (\delta) = \mathfrak{L}_{q; a, b, c} \cup \big\{ z \in \mathfrak{X}_{a, b, c} : \dist (z, \mathfrak{A}_{q; a, b, c}) \le \mathfrak{d}_z^{2/3} N^{\delta-2/3} \big\}.
		\end{flalign}

[Lemma 34 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For sufficiently large $n$, we have if 
    \begin{align*}
        \#\left\{i=0,\ldots,\left\lfloor\frac{1}{3}\delta(\log n)^{1+\frac{\varepsilon}{8}}\right\rfloor: X_{l_{i+1}}\le \dfrac{X_{l_{i}} }{(\log n)^{\frac{\varepsilon}{6}}}+(\log n)^{1+\frac{\varepsilon}{2}}\right\}\ge \frac{1}{6}\delta (\log n)^{1+\frac{\varepsilon}{8}},
    \end{align*}
    then $X_{h^*-\lfloor\frac{1}{3}\delta n\rfloor}< 2(\log n)^{1+\frac{\varepsilon}{2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 14 of arXiv:2608.26642, '2608.26642'] For every $x\in \R$,
  \begin{align}

   \lim_{q\to 0+}r_q(0)\P_x\Big[\Gamma_{\bm{e}_q}^\mu\Big]=\varphi^\mu(x).
 \end{align}
This convergence is uniform on compact sets. In particular, $\varphi^\mu=f^\mu$ on $K.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Dyadic--close harmonic envelope) of arXiv:2609.01570, 'A Proof of Fraenkel's Conjecture'] Let
\[
 H_y^{\rm good}:=\frac1y+
 \sum_{\substack{b\in A\setminus\{1,y\}\\ b\text{ is good}}}
 \frac1{\normQ{yb^{-1}}};
\]
thus the superscript includes the anchor \(b=1\) as well as every selected
good element other than \(y\).  This contribution to the \(y\)-row satisfies
\begin{equation}
 H_y^{\rm good}
 <\frac2m+\frac{10J}{3y}+\frac{2\Harm_{y-1}}{y-1}.
\end{equation}

[Prop proposition:ManyToOneL* of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $r\geq 0$.  For every non-negative measurable function $\Phi$ on $\mathcal{M}^2_f(\mathbb{R}_+) \times \mathcal{W}_{\overline{E}}$, we have:
\begin{align}
     &  \mathbf{N}^{\bullet, L}_{x,r} \big(  \Phi\big( \rho_U,\eta_U, \overline{W}_U\big)  \big)  
  =   E^0 \otimes \mathcal{N}_{x,r} \Big(  \exp\big(- \alpha\cdot  \uptau \big)\Phi\big( \mathcal{J}_{\uptau}, \widecheck{\mathcal{J}}_{\uptau}, (\bar{\xi}_t:~t\in [0,\uptau] ) \big) \Big). 
\end{align}
Under $\mathbf{N}_{x,r}^{\bullet, L}$, conditionally on $(\rho_U,\eta_U, \overline{W}_U)$ the
processes $(\rho,\overline{W})^{U,\leftarrow}$ and  $(\rho,\overline{W})^{U,\rightarrow}$ are independent and their  conditional distributions are as follows:
\begin{itemize}
\item the process $(\rho,\overline{W})^{U,\leftarrow}$ is distributed as  $(\eta, \overline{W})$ under $\mathbb{P}_{\eta_U, \rho_U,\overline{W}_U}^\dagger$; 
\item the process $(\rho, \overline{W})^{U,\rightarrow}$ is distributed as  $(\rho, \overline{W})$ under $\mathbb{P}_{\rho_U,\overline{W}_U}^\dagger$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

