[Definition of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $0 \leq p, \, q \leq \infty$ and $s, \, \beta \in \mathbb{R}$, the hyperbolic Besov space with hyperbolic scale is defined by
\begin{equation}
 \widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)  :  = \Big\{ f \in \mathcal{S}'(\mathbb{R}^2)~:~ \,   \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q < \infty \Big\}
\end{equation}
with the norm
$$
\Vert f \Vert_{\widetilde{B}^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)} = \left( \sum_{\bar{j} \in \mathbb{N}^2 } (\max(\bar{j})) ^{-\beta q} 2^{\max(\bar{j})sq} \Vert \Delta_{\bar{j}} f \Vert_p^q \right)^{1/q},
$$
with the usual modification if $q= \infty$.

[Defn 10 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$.
	\begin{enumerate}[(1)]


	\item We call $x\in\Omega$ a \emph{regular point} of $\phi$ if there exists a convex open neighborhood $V$ of $x$ and a semiconvex function $\psi: V \to \R$ with linear modulus touching $\phi$ from below at $x$ in $V$. We denote by $\reg(\phi)$ the set of regular points of $\phi$ and call it the \emph{regular set} of \( \phi \).

	\item We call $x\in\Omega$ a \emph{cut point} of $\phi$ if $x$ is not a regular point of $\phi$. We denote by $\cut(\phi)$ the set of cut points of $\phi$ and call it the \emph{cut locus} of $\phi$, that is, 
	\begin{align*}
	\cut(\phi)= \Omega \setminus \reg(\phi).
	\end{align*}
	\end{enumerate}

[Theorem 4 (Risk stability of SGD) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let the Hessian be a positive trace-class operator with spectrum
\[
\bH=\diag(\lambda_1,\lambda_2,\ldots),
\qquad
\lambda_1=\lambda_{\max}\geq\lambda_2\geq\cdots>0,
\]
and suppose
\(\sigma>0.\)
Then SGD is risk stable if and only if
\begin{equation}

\eta<\frac{2B}{(B+1)\lambda_{\max}}
\end{equation}
and
\begin{equation}

\kappa_{\sgd}(\eta)
:=
\sum_{i\geq1}
\frac{\eta\lambda_i}{2B-(B+1)\eta\lambda_i}
<1.
\end{equation}

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. A function $g:S\to [0,\infty]$ is a strong upper gradient for $F$ if for every absolutely continuous curve $v\in AC(a,b;S)$ the function $g\circ v$ is Borel and \begin{align*}
        \left\lvertF(v(t))-F(v(s))\right\rvert\leq \int_s^tg(v(r))\left\lvertv'\right\rvert(r)dr \quad \forall a< s\leq t< b.
    \end{align*}
    In particular, if $g\circ v \left\lvertv'\right\rvert\in L^1(a,b)$ then $F\circ v$ is absolutely continuous and \begin{align*}
        \left\lvert(F\circ v)'(t)\right\rvert\leq g(v(t))\left\lvertv'(t)\right\rvert\quad \text{ for a.e. } t\in (a,b).
    \end{align*}

[Lemma lem:weightedore of arXiv:2609.00889, 'Dominant-Degree Conditions for Ramsey--Tur\'an Factors of Non-Directed Cycle Orientations'] Suppose that $D$ is an oriented graph of sufficiently large order $n$  with
$\sigma_{\mathrm{Ore}}^*(D)\ge\left(\frac34+\mu\right)n$. Let $V_0,V_1,\ldots,V_k$ and $D'$ be the partition and pure digraph obtained by Lemma (lem:regularity of the paper) with $D$, respectively. Let $R$ and $w_i(D)$ be the corresponding reduced digraph and dominate wight defined as above. Then the following hold.
\begin{enumerate}[label=\rm(\roman*)]
\item $\displaystyle \min_{v\in V(D)}d_D^*(v)\ge \mu n/3$;
\item $\displaystyle \min_{i\in[k]}w_i(D)\ge  \mu k/4$;
\item if $C$ is a component of $UG(R)$, $r:=|C|$, and $X_C:=\cup_{i\in C}V_i$, then
$|X_C|\ge \mu n/5$,
and the set
\[
L_C:=\left\{x\in X_C:d_D^*(x)\le\frac34|X_C|+\frac\mu8n\right\}
\]
satisfies $|L_C|\ge \mu^2n/100$.
\end{enumerate}

