[Lemma 3 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $M\sim Compound(N,X)$.
	\begin{itemize}
		\item[($i$)] If $N$ has independent increments, then $M$ has independent increments.
		\item[($ii$)] If $N$ has stationary increments, then $M$ has stationary increments.
	\end{itemize}

[Lemma 8 of arXiv:2603.25615, 'Fourier dimension of Mandelbrot cascades on planar curves'] Let $I\subset[0,1]$. Then
    \begin{equation*}
    \left|\int_{\gamma(I)}\exp\left(-2\pi i x\cdot\xi \right)\,dx\right|\lesssim |\xi|^{-1/2}\,.
\end{equation*}
    For $j \geq 1 $, assume that $b^{-j}|\xi| \leq |\gamma'(t) \cdot \xi|$ for all $t \in I$. Then
    \begin{equation*}
    \left|\int_{\gamma(I)}\exp\left(-2\pi i x\cdot\xi \right)\,dx\right|\lesssim b^j/|\xi|\,,    
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ll1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $x \in \mathbb{Z}^2$ and $0 < r < R$, the simple symmetric random walk on $\mathbb{Z}^2$ satisfies the following estimates:
	\begin{enumerate}
		\item [a)] For any $y \in {\rm B}(x;R)\setminus {\rm B}(x;r)$, 
		\begin{equation}
			\mathbb{P}_y( \tau_{{\rm B}(x;r)} < \tau_{\partial {\rm B}(x;R)})  = \frac{R- \log \|x-y\| +O({\rm e}^{-r})}{R-r}.  
		\end{equation}
		\item [b)] For any $y \in {\rm B}(x;R) \setminus \{x\}$, 
		\begin{equation}
			\mathbb{P}_y( \tau_x < \tau_{\partial {\rm B}(x;R)}) = \left(\frac{R-\log\|x-y\|+O(\|x-y\|^{-1})}{R}\right)(1+O(R^{-1})).  
		\end{equation} 
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor Corid4 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $0<\alpha<\nicefrac{1}{2}$, for any fixed $x$, $z=(x,1)$ or $z=(1,x)$ and $i$ large 
   \begin{align} \mathbb{E}_{z}(\overline{Z}_{\rho_i})  =  {\mathbf{c_{_1}}} \cdot (i+g_{\alpha} \cdot i^{\frac{1-2\alpha}{1-\alpha}})^{\frac{1}{1-\alpha}}+o_i(1)


   \end{align}
   where $ {\mathbf{c_{_1}}}=(2(1-\alpha))^{\frac{1}{1-\alpha}}$ and $g_{\alpha}=\frac{ {\mathbf{c}}}{2( {\mathbf{c_{_1}}})^{\alpha}}$.
   Also, 
   \begin{align}
    \sum_{m \leq i} \mathbb{E}_z(\overline{Z}_{\rho_m}-\overline{Z}_{\eta_m} )  \sim   {\mathbf{c_{_1}}} i^{1/(1-\alpha)}\ and\ \mathbb{E}_{z}(\overline{Z}_{\eta_i}) \sim  {\mathbf{c_{_1}}} i^{1/(1-\alpha)}. 

    \end{align}

