[Lemma 15 of arXiv:2603.28226, '2603.28226'] Assume that $(\mathcal F_n)_{n\ge1}$ is an $\alpha$-regular atomic filtration. Fix $N\ge1$ and an atom $A\in\mathcal A_N$. Let $g\in L^1(\mathcal F_\infty)$ and $\lambda>0$. If
\begin{equation}

 \frac{1}{\mathbb P(A)}\,\mathbb E[|g| \, \mathbf1_A]\le \lambda,
\end{equation}
then there exists a finite or countable collection of pairwise disjoint atoms $\{A_j\}_{j\in J}$ contained in $A$ such that

\smallskip
\noindent\textup{(i)}
\begin{equation}

 \lambda<\frac{1}{\mathbb P(A_j)}\,\mathbb E[|g| \, \mathbf1_{A_j}]\le \alpha^{-1}\lambda,
 \qquad j\in J;
\end{equation}

\noindent\textup{(ii)}
\begin{equation}

 |g(\omega)|\le \lambda
 \qquad\text{for a.e. }\omega\in A\setminus\bigcup_{j\in J}A_j;
\end{equation}

\noindent\textup{(iii)}
\begin{equation}

 \sum_{j\in J}\mathbb P(A_j)
 \le \frac1{\lambda}\,\mathbb E[|g|\, \mathbf1_A].
\end{equation}

[Lem 37 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] There exists a constant $C_7=C_7(\alpha,\iota)$ such that for all parameters $\hw,\hv,(\hx_1,\ldots,\hx_{r'})$ satisfying \eqref{e:reduced-normalization}, we have
    \[
        \max\bigg\{
            \gamma_\star, \frac{1}{\alpha - \hv_1 m(z_\star)}
        \bigg\} \le C_7\,,
    \]
for $z_\star$ as defined by \eqref{e:fp.z.star} and $\gamma_\star$ as defined by Lemma~\ref{l:fp-vii-estimate-prep}.

\begin{proof} Recall the sets $J_+,J_- \subseteq [r]$ defined in \eqref{e:Jplus}, \eqref{e:Jminus}, which index the positive and negative entries of $\hv$. Let $\gamma_+(z)$ denote the contribution to \eqref{e:fp.gamma.function} from indices $j\in J_+$, and denote similarly $\gamma_-(z)$. Then, for any $z>\hw_1$, we have 
    \beq
    \gamma_-(z)
    = \alpha \sum_{j\in J_-}
            \lambda_j \bigg(
            \frac{\hv_j}{\alpha - \hv_j m(z)}
        \bigg)^2
        \le \alpha 
        \sum_{j\in J_-}
            \lambda_j
    \bigg(
            \frac{\hv_j}{\alpha}
        \bigg)^2
        \stackrel{\eqref{e:reduced-normalization}}{\le} \frac{4}{\alpha\iota^2}\,.
    \eeq
If $J_+ = \emptyset$, this upper bounds $\gamma(z)=\gamma_-(z)$ for any $z>\hw_1$. 
    In this case, we also have \[
    \frac1{\alpha - \hv_1 m(z)} \le \frac1\alpha\,,\]
for any $z>\hw_1$, so the result follows. 

Otherwise, assume $J_+ \neq \emptyset$, so $\hv_1 > 0$. By Lemma~\ref{l:fp-zmin-equal-z0}, this implies $z_{\min} > z_0$. Recall that \eqref{e:fp-uniform-bound-Jminus-contribution} above already bounds $\gamma_-(z)$ for all $z>\hw_1$. Meanwhile, both $m(z)$ and $\gamma_+(z)$ are strictly decreasing on the interval $z \in (z_0,+\infty)$. Since $z_\star \ge z_{\min} > z_0$ and $\gamma(z_\star) = \gamma_\star$, it suffices to show 
\beq

        \max\bigg\{
        \gamma_+(z_{\min})
        \le \gamma(z_{\min}),
            \frac{1}{\alpha - \hv_1 m(z_{\min})}
        \bigg\} \le C_7\,.
    \eeq
We divide the analysis into two cases:
    \begin{itemize}
        \item If $m(z_{\min}) \le \alpha / (2\hv_1)$, then 
        \begin{align*}
    \gamma_+(z_{\min})\
    &=
            \alpha \sum_{j\in J_+} \lambda_j \bigg(
            \frac{\hv_j}
            {\alpha - \hv_j m(z_{\min})}
            \bigg)^2\\
            &\le \alpha \bigg(
                \frac{\hv_1}{\alpha - \hv_1 m(z_{\min})}
            \bigg)^2 
            \le \frac{4(\hv_1)^2}{\alpha}
            \stackrel{\eqref{e:reduced-normalization}}{\le}
            \frac{16}{\alpha \iota^2}\,,\\
       \frac{1}{\alpha - \hv_1 m(z_{\min})}
           &\le \frac{2}{\alpha}\,.
        \end{align*}

        \item If $m(z_{\min}) > \alpha / (2\hv_1)$, then Lemma~\ref{l:fp-m-fns-conversion} gives
        \[
            m_2(z_{\min}) >
            m_2\bigg(m^{-1}\bigg(\frac{\alpha}{2\hv_1}\bigg)\bigg)
            \ge \frac{\alpha^2 \iota }{4(\hv_1)^2}\,.
        \]
        Since $\hv_1 > 0$, it follows from Lemma~\ref{l:fp-zmin-equal-z0} that $V'(z_{\min}) = 0$.
        Recalling the formula for $V'$ from \eqref{e:fp-V-pr}, this implies
        \[
        \frac{\alpha\lambda_1(\hv_1)^2}
            {(\alpha-\hv_1m(z_{\min}))^2}
        \le
        \gamma(z_{\min}) 
            = \frac{1}{m_2(z_{\min})}
            \le \frac{4(\hv_1)^2}{\alpha^2\iota}
            \stackrel{\eqref{e:reduced-normalization}}{\le}
            \frac{16}{\alpha^2\iota^3}\,.
        \]
Rearranging the above and recalling $(\lambda,\mu) \in \Lambda$ gives
        \[
            \frac{1}{\alpha - \hv_1 m(z_{\min})}
            \le \frac{2}{\alpha^{3/2}\iota}\,.
        \]
    \end{itemize}
In all cases, the conclusion follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 2 (We study these derivations) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $K$ be a field of characteristic zero with a transcendental basis $x_1,x_2,\ldots, x_n$, where $n\in \mathbb{N}$, over a subfield $k$.

    We say that a derivation $D:K\to K$ over $k$ has \textbf{rational function coefficients that separate variables} if there exist non-zero rational functions in one variable $f_1,f_2,\ldots,f_n \in k(X)$ such that

    \begin{equation}
    D= f_1(x_1)\frac{\partial}{\partial x_1}+f_2(x_2)\frac{\partial}{\partial x_2}+\ldots+f_n(x_n)\frac{\partial}{\partial x_n}.
\end{equation}

[Definition 75 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Put
\begin{equation}
\bZ= C([0,\infty),\rU^\prime),
\end{equation}
and let $X$ be the canonical process on $\bZ$ defined by
 \[
 X: [0,\infty) \times  \bZ \ni (t,\omega) \mapsto \omega(t) \in \rU^\prime.
 \]
As in \cite{Mik+Roz_1998}, we introduce the following objects 
 \begin{align}
     \mathscr{D}_t= \sigma(X_s,\,s \leq t),\;\;
     \mathscr{D}_{t +}= \bigcap_{s >t} \mathscr{D}_s,\;\;
     \mathbb{D}= (\mathscr{D}_{t +})_{t \in [0,T]}, \mbox{ and }
     \mathscr{D}= \sigma(X_s,\,s \geq 0),
      \end{align}
and we also refer the reader to the definition \eqref{eqn-D_t-D_t+} and \eqref{eqn-mb-D}.

[Lem 5 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a) For any $\varphi$ satisfying \eqref{e:critical}
 \begin{equation}
  \lim_{T\to \infty }\frac 1T I_R(T)=\frac 1{m_\varphi},

 \end{equation}
where $m_\varphi$ is given by \eqref{e:phi_x_integrable}, with the convention $\frac 1{\infty}=0$. In particular we always have
 \begin{equation}
\limsup_{T\to \infty} \frac 1T I_R(T)<\infty.
\end{equation}
b)  Under Assumption \ref{ass:beta_integrable} we have
\begin{equation}
\liminf_{T\to \infty} \frac 1{T^{(\beta+\delta)\wedge 1}} I_R(T)>0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

