    =\sqrt{\frac{1}{\mu\left(x\right)}\sum_{z\sim ...","release_manifest_digest":"sha256:9f10dcd67cfe45420d9121471cff8b93a19597a2f7ce0234d1a78931efce29b4","revision_digest":"sha256:96cfda9346ab9906c2fa893e9821ccd6390f5617548fbe90d0636b5d4bd24df9","source_id":"arxiv:2608.30409","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

