[Theorem 7 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function. Then for any $0<f\in \ell^{\infty}\left(V\right)$ with $R_{f}<\infty$, 
    \begin{equation}
         \partial_t\left(\alpha \phi\right)\geq\left(\alpha^{\prime}-\frac{4\alpha\gamma}{n}-2\alpha K\right)\phi+\frac{4\psi^{\prime}\left(1\right)\alpha\gamma}{n}\Delta P_T f-\frac{2\alpha\gamma^2}{n} P_T f,  

    \end{equation}
     where $\phi$ is defined as in \eqref{phi def}, $\alpha\in C^{1}\left[0,T\right]$ is positive,  and $\gamma\in C\left[0,T\right]$.

