[Definition def:sigmaandv(X) of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Given a $d\times d$ matrix $X$ with jointly gaussian entries (which we will write as $X = A_0 + \sum_{k=1}^n g_kA_k$) we define the following parameters
\begin{equation}
    \sigma(X)^2 = \big\| \mathbb{E}(X - \mathbb{E} X)(X - \mathbb{E} X)^\top \big\| \vee \big\| \mathbb{E}(X - \mathbb{E} X)^\top(X - \mathbb{E} X) \big\| = \left\| \sum_{k=1}^n A_kA_k^\top \right\| \vee \left\| \sum_{k=1}^n A_k^\top A_k \right\|;
\end{equation}
\begin{equation}
    v(X)^2 = \big\| \cov(X) \big\| = \sup_{\|B\|_F = 1} \left|\Tr(B^\top A_k)\right|^2,
\end{equation}
where $\cov(X)$ denotes the $d^2\times d^2$ covariance matrix of the entries of $X$;
\begin{equation}
    \sigma_{\ast}(X)^2 = \sup_{u,v\in\mathbb{S}^{d-1}}\mathbb{E} \big| u^\top (X - \mathbb{E} X)v\big|^2= \sup_{u,v\in\mathbb{S}^{d-1}}\sum_{k=1}^n\big| u^\top A_kv\big|^2.
\end{equation}

[Lemma computation for exact asymptotics of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $X$ be a uniform random variable in the unit disk. Then 
    \begin{equation*}
I := \mathbb{E}\left[ [\log|1-X|]^2\right] = \frac{1}{\pi} \int_0^1 \int_0^{2\pi} \left( \log \left| 1 - r e^{i\theta} \right| \right)^2 \, r \, d\theta \, dr = \frac{\zeta(2) - 1}{2}= \frac{\pi^2 - 6}{12}.
\end{equation*}

