[Lemma lem:endpoint-transfer-square-sums-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Almost surely, on the event \(\{M>0\}\),
\begin{equation}
\liminf_{n\to\infty}
\frac{\log_2\Sigma_n}{-n}
=
\dim_2(\mu)
=
\liminf_{n\to\infty}
\frac{\log_2\Sigma_n(\mu)}{-n}.
\end{equation}

[Corollary 9 (Finite \(n\) local consequences) of arXiv:2608.04799, '2608.04799'] For every compact \(K\Subset E\), there are \(C_K,c_K>0\) such that, for all
\(n\ge n_\lambda\) and \(m\ge1\),
\begin{equation}
  \Prob\{\Xi_n(K)\ge m\}
  \le \frac{C_K^m}{m!}e^{-c_Km^3}.
\end{equation}
Let \(h:E\to\mathbb C\) be bounded and Borel measurable with
\(\operatorname{supp}h\subset K\), and define
\begin{equation}
  G_n(h)=\E\prod_{z\in\Xi_n}(1+h(z)),
\end{equation}
where atoms are counted with multiplicity.  Then
\begin{equation}
  G_n(h)
  =\sum_{q=0}^\infty\frac1{q!}
    \int_{E^q}\prod_{i=1}^q h(z_i)
    \,\dd\alpha_{\Xi_n}^{(q)}(\mathbf z).
\end{equation}
For every \(T<\infty\), there are \(A=A(K,T)<\infty\) and
\(d=d(K,T)>0\) such that, for every \(Q\in\mathbb Z_{\ge0}\),
\begin{equation}
\begin{aligned}
  \sup_{\substack{n\ge n_\lambda,\ \operatorname{supp}h\subset K\\
                   \|h\|_\infty\le T}}
  \left|G_n(h)-\sum_{q=0}^Q\frac1{q!}
    \int_{E^q}\prod_{i=1}^q h(z_i)
    \,\dd\alpha_{\Xi_n}^{(q)}(\mathbf z)\right|
  \le A e^{-dQ^3}.
\end{aligned}
\end{equation}
For every Borel set \(B\subset K\), the choice \(h=-\one_B\) gives the
finite \(n\) void probability estimate
\begin{equation}
 \sup_{n\ge n_\lambda}
 \left|\Prob\{\Xi_n(B)=0\}
 -\sum_{q=0}^Q\frac{(-1)^q}{q!}
   \E[(\Xi_n(B))_q]\right|
 \le Ae^{-dQ^3},
\end{equation}
where \(A,d\) may be taken from \eqref{eq:Gn-tail} with \(T=1\).
If \(f:E\to\mathbb C\) is bounded and Borel measurable with
\(\operatorname{supp}f\subset K\), then \eqref{eq:Gn-tail} also applies to the
complex local Laplace functional after taking \(h=e^{-f}-1\).  In particular,
for every \(t\ge0\),
\begin{equation}
  \sup_{n\ge n_\lambda}\E e^{t\Xi_n(K)}<\infty.
\end{equation}

[Lemma 5 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $p\ge 2k-1$ and $z \ge 5$. Then for $0<a< 1$, we have
		\begin{equation} 
			\E \left(\Delta^2\mathbf{1}(|\Delta|\le a)\mathbf{1}(z-a \le W \le z+a)\right) \le \dfrac{B^{p}(1+\E|W|^{2p})a(\sqrt{\E R^2} + \lambda)}{(1+z)^p}.
		\end{equation}

