[Definition 16 of arXiv:2609.02197, '2609.02197'] Let $\left(\alpha,U\right) \in \mathbb{R}\times \mathbb{R}_+.$ We denote by \gls{pc5} the set of functions $h:\left[0,U\right]\longrightarrow\mathscr{C}^\alpha$ such that $h$ is continuous on $\left[0,U\right].$
We also define
\begin{align*} 
\left\Vert\cdot\right\Vert_{C_U\mathscr{C}^\alpha}: C_U\mathscr{C}^\alpha &\longrightarrow \mathbb{R}_+ \\ f & \longmapsto \left\Vert f\right\Vert_{C_U\mathscr{C}^\alpha}=\sup_{r \in \left[0,U\right]}\left\Vert f\left(r\right)\right\Vert_{\mathscr{C}^\alpha}
\end{align*}

[Lemma lem:Lambda_J_approach2 of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let Assumptions~(ass:dynamics of the paper) hold, such that the symmetric part
$\mathcal{L}_S$ satisfies the Poincar\'e inequality~(equation eq:poincare of the paper) with
spectral gap $\lambda_\mathrm{gap}>0$. 
Then for all $k\geq0$ with
$k \|W-\E^\mu[W]\|_{L^\infty(\mu)}
 + k^2\|Q-\E^\mu[Q]\|_{L^\infty(\mu)} < \lambda_\mathrm{gap}$,
\begin{align}
\Lambda^J(k)
\leq
k \E^\mu[W]
+ k^2 \E^\mu[Q]
+
\frac{k^2 \bigl(\sqrt{\mathrm{Var}_\mu(W)} 
+ k\sqrt{\mathrm{Var}_\mu(Q)}\bigr)^2}
{\lambda_\mathrm{gap} - k\|W - \E^\mu[W]\|_{L^\infty(\mu)} - k^2\|Q - \E^\mu[Q]\|_{L^\infty(\mu)}}.

\end{align}

[Theorem 1 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] (Theorems \ref{thm:uniqueness}, \ref{thm:existence}, Corollary \ref{cor-1}) Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for unique} hold for $\dot{\xi}^{F}, \psi$, $u_{\mathrm{init}}, \Phi, \sigma, g$.  Then the obstacle problem for \eqref{eq:main} has at most one stochastic kinetic solution with the initial value $u_{\mathrm{init}}$ in the sense of Definition \ref{def:def of stochastic kinetic solution}. Moreover, if $(u_1,\nu_1)$ and $(u_2,\nu_2)$ are two stochastic kinetic solutions with initial data $u_{1,\mathrm{init}}$ and $u_{2,\mathrm{init}}$, then
almost surely for every $t\in(0,T)$,
\begin{align*}
\|u_1(t)-u_{2}(t)\|_{L^1(\mathbb{T}^d)}
\leq\|u_{1,\mathrm{init}}-u_{2,\mathrm{init}}\|_{L^1(\mathbb{T}^d)}.
\end{align*}
If further Assumption \ref{assu:assu for existence} is in force for some $p\in [2, \infty)$, there exists a unique stochastic kinetic solution $(u,\nu)$ in the sense of Definition \ref{def:def of stochastic kinetic solution}.

The same results also hold for the lower obstacle problem for \eqref{eq:main} (the constraint is changed to $u\geq\psi$), under the additional assumptions $|\sigma(r)|\leq C(1+|r|)$ and $p=2$. This includes the classical Dean--Kawasaki equation
\begin{align*}
\mathrm{d}u & =\Delta\Phi(u)\mathrm{d}t+\nabla\cdot\sqrt{\Phi(u)}\circ\mathrm{d}\xi^{F},
\end{align*}
provided that $|\Phi(r)|\leq C(1+|r|^{2})$ for all $r\in\mathbb{R}$, and thus in particular covers the case $\Phi(r)=r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 21 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $T$ be a tree, let $c$ be a labeling of $T$, and put $S=S_c(T)$. Assume
$|S|\ge2$, and let $a,b\in S$ be the vertices with
\[
  c(a)=\min\{c(x):x\in S\},\qquad c(b)=\max\{c(x):x\in S\}.
\]
Write $P_{ab}=p_1p_2\cdots p_m$ with $p_1=a$ and $p_m=b$. Then
\begin{enumerate}
\item[\textup{(i)}] $S\subseteq V(P_{ab})$;
\item[\textup{(ii)}] $c(p_i)=c(a)+i-1$ for $1\le i\le m$; in particular
$c(b)=c(a)+m-1$ and $c\bigl(V(P_{ab})\bigr)=[\,c(a),c(b)\,]$;
\item[\textup{(iii)}] every $z\in V(T)\setminus V(P_{ab})$ satisfies
$c(z)<c(a)$ or $c(z)>c(b)$.
\end{enumerate}

[Theorem thm:main_regularity_result of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] Let $C \in \mathcal{C}_{ar}^d$ and $\gamma \in \mathcal{P}_{\mathcal{W}_d}$ be its corresponding Williamson measure. Then the following three equivalences hold:
    \begin{description}
        \item[(i)] $\gamma^{dis}([0,\infty)) > 0$ if, and only if $\mu_C^{dis}(\mathbb{I}^d) > 0$.
        \item[(ii)] $\gamma^{abs}([0,\infty)) > 0$ if, and only if $\mu_C^{abs}(\mathbb{I}^d) > 0$.
        \item[(iii)] $\gamma^{sing}([0,\infty)) > 0$ if, and only if $\mu_C^{sing}(\mathbb{I}^d) > 0$.
    \end{description}

