\frac{\log \ell_{n+m}}{\log a}\geq \frac{\log\ell_n+m\log b}{\log a}
=\frac{\log \ell_{n}}{\log a}+m\frac{s}{u}.
\]
This yields
\[
\sum_{m=0}^{\infty}2^{-\beta \frac{\log \ell_{n+m}}{\log a}+m}
\leq 2^{-\beta \frac{\log \ell_{n}}{\log a}}\sum_{m=0}^{\infty}2^{m(1-\beta ...","release_manifest_digest":"sha256:5d673302383df879bd2ffb231a7ce86cc9a09ef8525ff3b4c7266d306a795f8a","revision_digest":"sha256:97d9b09dff45a737593e8af1f535f90a48c68c93c09521669b7fb964aba59763","source_id":"arxiv:2506.10448","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

