[Lemma 9 (resolvent boundary condition) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:resolvent-bc}
The resolvent kernel $G^{\rm sticky}_\alpha(x,y)$, viewed as a function
of its first argument at fixed $y \in (0,\infty)$, solves
$(\alpha-\mathcal{L})G^{\rm sticky}_\alpha(\cdot,y)=\delta_y$ on $(0,\infty)$
in the speed-measure sense, with boundary condition
\begin{equation}
  \frac{dG^{\rm sticky}_\alpha(\cdot,y)}{ds}(0^+)
  = \frac{\alpha}{\mu}\,G^{\rm sticky}_\alpha(0,y).
\end{equation}
By the symmetry $G^{\rm sticky}_\alpha(x,y) = G^{\rm sticky}_\alpha(y,x)$, the same condition holds in the second argument.

[Definition 1 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] The \textit{Brownian-snake} is the Markov process in $\mathcal{W}$, denoted by $(\omega_s,s\geq0)$, whose transition kernels $\mathcal{Q}_s$ are given by 
    \begin{align} 
        \mathcal{Q}_s(\omega,d\nu) = \int_\mathbb{R} \int_\mathbb{R} \gamma_s^{\ell_\omega}(dp,dq) \, R_{p,q}(\omega,d\nu) \,.
    \end{align}

[Lemma eq:DlDr-rev of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Let  $t_2\in \mathbb{R} $ and $ h_1, h_2\in \mathbb{R}^+$ be such that there is a bird at $(t_2,h_2)$ of speed $v_2$. Then there exist two sets $D'_\ell\equiv D'_\ell(t_1,h_1,h_2), D'_r\equiv D'_r(t_1,h_1,h_2)\subsetneq \mathbb{R}$, such that, for all $t_1\in (D'_\ell \cup D'_r)^\circ$ or $\partial(D'_\ell \cup D'_r)$ or $(D'_\ell \cup D'_r)^c$, the radial bird of speed $v_1$ and head at $(t_1,h_1)$ intersects the first bird, twice, once or never, respectively. The sets $D'_\ell, D'_r$ are given by,

\begin{equation}
\begin{aligned}
D'_\ell&=\begin{cases}
           (-\infty,t_2], & \text{ if } h_1\leq  h_2,\\
           (-\infty, t_2-t^*], &\text{ if } h_1>h_2,
    \end{cases}
&\hspace{0.3in}
D'_r&=\begin{cases}
           [t_2,\infty), & \text{ if } h_1\leq h_2,\\
           [t_2+t^*,\infty), &\text{ if } h_1>h_2,
    \end{cases}
\end{aligned}

\end{equation}

where $t^*$ as defined in ((eq:tstar of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm_cons of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Under Assumptions~(a:main of the paper) and (ass:f of the paper),  the optimizer of the constrained \sch problem (equation e:minentadpt of the paper) is $P({\hat\alpha})$, with $\hat\alpha_t=\sigma^2(t,X^2_t)\frac{\rho_y(t,X^2_t;X^1_1)}{\rho(t,X^2_t;X^1_1)}$, where $\rho:[0,1]\times E_\ell^2\to\bbR_+$ is defined as
\begin{equation}
\rho(t,y;z):=\int_{E}f(z,u)q(t,1;y,u)du + f(z,\ell)L(t,1;y),
\end{equation}
with $\rho_y$ being its partial derivative with respect to $y$.

[Theorem thm: R (S,X_S) (T,X_T) of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] Let $X_1,X_2,\ldots,X_n$ be non-degenerate independent random variables taking values in a general measurable space $(F,\mathcal{F})$. Fix a special point $\partial$ outside of $F$. Let $S$ and $T$ be two random subsets of $[n]=\{1,2,\ldots,n\}$. Suppose that $(S,T)$ is independent of $(X_1,X_2,\ldots,X_n)$. For $i=1,2,\ldots,n$, define
\[Y_i=\left\{\begin{array}{ll}
X_i, & \text{if }i\in S,\\
\partial, & \text{otherwise},
\end{array}\right.\text{ and }Z_i=\left\{\begin{array}{ll}
X_i, & \text{if }i\in T,\\
\partial, & \text{otherwise}.
\end{array}\right.\]
Then for $n\geq 1$, we have that
\begin{equation}
R((Y_1,Y_2,\ldots,Y_n),(Z_1,Z_2,\ldots,Z_n))=\max(R(S,T),\max(r_j:j\in[n])),
\end{equation}
where $r_j$ is the best constant $r$ for the following inequality
\begin{equation}
\sum_{s,t:j\in s\cap t}P(S=s,T=t)\alpha_s\beta_t\leq r\sqrt{\sum_{s:j\in s}P(S=s)\alpha_s^2}\sqrt{\sum_{t:j\in t}P(T=t)\beta_t^2}, \quad \forall \text{ real } \alpha_s, \beta_t.
\end{equation}
In particular, when $S$ and $T$ are independent, we have that $R(S,T)=0$ and that
\[r_{j}=\sqrt{P(j\in S)P(j\in T)}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 50 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}--\eqref{H2}. For fixed $\delta, s, \eta, M_0, c_0$, there exists $\gamma>0$ such that for all $1\le m\le M_0$ and sufficiently large $n$,
\begin{align}
    \q^m_n \big( \mathcal{N}_i \ge \gamma n^2,\ \forall 1\le i \le m \big) \ge 1 - \tfrac\eta 2.
\end{align}

