[Lemma lem:genealogy of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {kkmt2026cle4_part2}}]
		Fix $a>0$ and let $\Gamma_{V_a}$ be a $\CLE_4$ in $V_a$.  Then, there exists $r_0>0$ such that with positive probability we have that 
		\begin{align*}
			D_{\Gamma_{V_a}}^{V_a}(\{0\} \times [0,1] ,  \{a\} \times [0,1]) < r_0 < 2r_0 \leq D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\} ,  [0,a] \times \{1\}).
		\end{align*}
		More precisely, the following holds with positive probability. Let us divide $V_a$ into three rectangles $G_1= (0,a) \times (4/5, 1) $, $G_2= (0,a) \times (1/5, 4/5)$ and $G_3=  (0,a) \times (0, 1/5)$. Let $L_2=\{0\} \times [1/5,4/5]$ be the left boundary of $G_2$ and let $L=\{0\}\times [0, 1]$ be the left boundary of $V_a$. Let $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ be the right boundary of the metric ball $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$, which we define as the intersection of $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ with the closure of the union of the connected components $C$ of $V_a \setminus \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ such that $\overline{C} \cap (\{a\}\times (0,1)) \neq \emptyset$. Then,
			\begin{enumerate}[label=(\alph*)]
				\item We have $D_{\Gamma_{V_a}}^{V_a}(L_2 ,  \{a\} \times [1/5,4/5]) < r_0$;
				\item The right boundary $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ intersects $L_2$;
				\item We have $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1/5\})\ge r_0$ and $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{4/5\}, [0,a] \times \{1\})\ge r_0$.
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6.13 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] Define the following stopping time
\begin{equation}
\tau_*^n=\inf\{t:r_s(U(t)-V^n(t))\ge r_*\},

\end{equation}
using the convention \(\inf\varnothing=\infty\).  Then for any \(t<\tau_*^n\), we have

\begin{equation}
\mathfrak b(t)
\le
C_3f_\delta(r_s(t))
+C_3\left(
\delta^p+\delta^\gamma
+\varepsilon_n^2\delta^{p-2}
\right),

\end{equation}
where $C_3>0$ depends on $m[g],c_g,[g]_{C^\beta},s,p,T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Kac, Pleijel) of arXiv:2507.06186, '2507.06186'] If $\partial D$ is sufficiently regular (e.g., smooth), then
\begin{align}

\msf T_0(t)=\tfrac{\msf{A}(D)}{2\pi}t^{-1}
-\tfrac{\msf{L}(\partial D)}{4\sqrt{2\pi}}t^{-1/2}+O(1)\qquad\text{as }t\to0,
\end{align}
where $\msf L(\partial D)$ is the length of the curve
$\partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] Assume the geometric hypotheses of \cref{thm:intro-bounded} and
normalize $K$ as above.  For every $0<\varepsilon<\tfrac12$ there is
a solution of
\begin{equation}
 \Delta u=V+2, \text{ with}
\end{equation}
\begin{equation}
 u=-\tfrac{r^2}{2}+w,\qquad
 |\nabla_b^jw|=\mathcal{O}(r^{1+\varepsilon-j}),
\end{equation}
and the tensor $k_K$ of \eqref{eq:k-def} satisfies
\begin{equation}
 |\nabla^jk_K|=\mathcal{O}(r^{-1+\varepsilon-j}),\qquad j=0,1,2.
\end{equation}
In particular, it satisfies the decay assumptions for dynamical destabilizations of ALF metrics from \cite[Definition 5.1]{KO}.

[Lem Wiener:caterpillar of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] In the case of a caterpillar, we have
    \begin{align*}
    \begin{split}
        W_n=&\sum_{i<j} (j-i+2)I_i^{(n)}I_j^{(n)}+\sum_{i,j=1}^m (\vert j-i\vert+1)I_j^{(n)}\\
        &+\sum_{i=1}^m I_i^{(n)}(I_i^{(n)}-1)+\frac{(m-1)m(m+1)}{6}.
    \end{split}
    \end{align*}

[Proposition 11 (Chaos asymptotics, \(H^*(m)<1/2\)) of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\delta(\varepsilon)>0\) be such that \(\delta(\varepsilon)\xrightarrow{\varepsilon\rightarrow 0} 0\) and \(\varepsilon/\delta\rightarrow 0\) as \(\varepsilon\rightarrow 0\). For \(\varepsilon\) small enough, for any \(0\leq r\leq m-1\),
\begin{equation}

\mathbb{E}[T_{2m-2r}^2]\leq D^{\mathrm{Diag}}_{H,m,r}\delta+D^{\mathrm{Off}}_{H,m,r}f(\delta,\varepsilon,m,r),
\end{equation}
with \(D^{\mathrm{Diag}}_{H,m,r}, D^{\mathrm{Off}}_{H,m,r}>0\) read off Lemmas~\ref{lem: second chaos m=1 H<1/2}--\ref{lem: asymptotics m>1 H<1/2}, and
\begin{equation}

f(\delta, \varepsilon, m,r) =
\begin{cases}
\delta(\varepsilon/\delta)^{2m(2-2H)-2} \quad &r< r_I\wedge r_S\\
\varepsilon^{2(m-r)(2-2H)} \quad &r> r_I\vee r_S\\
\delta^{2(m-r)(2H-2)}(\varepsilon/\delta)^{2m(2-2H)-2} \quad &r_S< r < r_I\\
\delta(\varepsilon/\delta)^{2(m-r)(2-2H)} \quad &r_I< r< r_S
\end{cases}
\end{equation}
The borderline cases \(r(2H-2)=-1\) or \(2(m-r)(2H-2)=-1\) carry the same orders up to logarithmic corrections: when \(r=r_I\) and \(r(2H-2)=-1\),
\[
f(\delta,\varepsilon,m,r) \sim
\begin{cases}
\delta(\varepsilon/\delta)^{2(m-r)(2-2H)}\log(\delta/\varepsilon)^2, & H^*(m)>1/4,\\
\varepsilon^{2(m-r)(2-2H)}\log(\delta/\varepsilon)^2, & H^*(m)<1/4;
\end{cases}
\]
when \(r=r_S\) and \(2(m-r)(2H-2)=-1\),
\[
f(\delta,\varepsilon,m,r) \sim
\begin{cases}
\varepsilon^{2(m-r)(2-2H)}\log(\delta), & H^*(m)>1/4,\\
\log(\delta)(\varepsilon/\delta)^{2m(2-2H)-2}, & H^*(m)<1/4;
\end{cases}
\]
and when \(r=r_I=r_S\) (so that \(H^*(m)=1/4\)), \(f(\delta,\varepsilon,m,r)\sim \varepsilon\log(\delta)\log(\delta/\varepsilon)\). In particular,
\begin{equation}

\mathbb{E}[(C_{\varepsilon, \delta}-\mathbb{E}[C_{\varepsilon, \delta}])^2]\lesssim \delta+\varepsilon^{2(2-2H)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Hard Edge) of arXiv:2511.12623, 'The eigenvector bead process'] We recall Convention~\ref{conv:inverse-stieltjes-branches}, and use the same convention for the inverse branches of the Stieltjes transform appearing below. 
Let $\alpha = T - N \ge 0$ denote the rectangularity parameter of the Wishart ensemble.
For $u, v \in \mathbb{N}$, the overlaps satisfy
\begin{equation}
\Omega^{(N)}_{u,v}
\;\mathrel{\underset{N \to \infty}{\overset{d}{\sim}}}\;
\frac{g_v \, \sqrt{\xi_v}}{\,D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_v\,}
\left(
    \sum_{v' \in \mathbb{N}} 
    \frac{(g_{v'})^2\xi_{v'}}{\bigl(D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_{v'}\bigr)^2}
\right)^{-1/2}.
\end{equation}

\noindent
Here $(\xi_u)_{u \in \mathbb{N}}$ follow the Bessel point process associated with the parameter $\alpha$, 
and $(g_u)_{u \in \mathbb{N}}$ are i.i.d.~standard Gaussian random variables 
$\mathcal{N}(0,1)$, independent of $(\xi_u)$.

\medskip
\noindent
The function $D_{g^2, \xi, \alpha}(z)$ is defined by
\begin{equation}
D_{g^2, \xi, \alpha}(z)
= \sum_{i \in \mathbb{N}} \frac{g_i^2}{ \xi_i-z}
- \frac{\chi_{\alpha}}{z},
\end{equation}
where $\chi_{\alpha}$ denotes a chi-square random variable with $\alpha$ degrees of freedom. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:zero-rate-localized-complement of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:nonnegative-bulk}
\leavevmode\par\noindent
In the setting of (thm:conditional-transfer of the paper), suppose that both
de-regularization defects vanish and \(\Phi\ge0\).  If
\begin{equation}
 \overline\Lambda_L^J(V)\le0,
\end{equation}
then the full exact-complexity limit exists and equals \(\Phi\).

[Conjecture conj:perc of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] For $s\in \mathbb{R}$, let
\begin{equation}

f_{\rm perc}(s) = \int_0^\infty x^2 \mathrm d\sigma_s, \qquad
\mathrm d \sigma_s =
	\frac 1 { \sqrt{2\pi} } x^{-5/2} \Psi(x^{3/2})
    e^{-\frac 1 6 x^3 + \frac s 2 x^2 - \frac{ s^2} 2 x}
    \mathrm dx
    .
\end{equation}
Then, for some $a,b>0$, as $V\to\infty$ we have
\begin{equation} 
\begin{aligned}
    \tau_{V,01}(1+sV^{-1/3}) & \sim b V^{-2/3} f_{\rm perc}(as),
    \\
    \chi_{V} ^{\rm {perc}}(1+sV^{-1/3}) & \sim b V^{1/3} f_{\rm perc}(as).
\end{aligned}
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition 23 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d=4$ and suppose that the assumptions of Theorem~\ref{thm:localWP_weakened} hold. Moreover, let $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$ and $T>0$. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $\mu$ the chemical potential of Definition~\ref{def:chemPotential}. Then, we have
	\begin{equation}
	       \sup_{t\in[0,T]\cap [0,\sigma)}\|u(t)\|_{H^1}+\int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt < \infty  \qquad \mathbb{P}\text{-a.s.}
	\end{equation}
	If, in addition, $u_0\in L_{\F_0}^4(\Omega;L^4(\sO))\cap L_{\F_0}^2(\Omega;H^1(\sO))$, then
    \begin{equation}
    \E\bigg[\sup_{t\in[0,T]\cap[0,\sigma)}  \|u(t)\|^2_{H^1(\sO)} + \int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt \bigg] \le C_{\psi,T,\sO}\big(1+\|u_0\|^4_{L^4(\Omega;L^4(\sO))}+\|u_0\|^2_{L^2(\Omega;H^1(\sO))}\big) < \infty.
    \end{equation}

[Lemma 11 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Let $(X(t))_{t \geq 0}$ be a $\Lambda$-coalescent with death according to $D(dz)$ and $\Lambda(dz)$ satisfying \eqref{eq:density} with parameter $\alpha \in (1,2)$. Now if $X(s) = k+j$, then there exists a constant $C > 0$ such that the probability that the next event the process experiences is a death event that brings it below $k$ particles is bounded above by

    \begin{align*}
        \frac{C}{k^\alpha}\left(1 + \frac{k}{j} \right).
    \end{align*}

    \noindent In particular, the constant $C > 0$ is independent of $k$ and $j$.

