[Corollary cor:bc-fidelity of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] For all $t_1,t_2\ge0$,

\begin{equation}
\mathrm{BC}(\pi_{t_1},\pi_{t_2})=\braket{\sqrt{\pi_{t_1}}}{\sqrt{\pi_{t_2}}}
=\braket{\psi_{\theta(t_1)}}{\psi_{\theta(t_2)}}
=\cos^{n}\!\Bigl(\tfrac{\theta(t_2)-\theta(t_1)}2\Bigr).

\end{equation}

The Bhattacharyya overlap of the laws at two times equals the fidelity
overlap of the corresponding register states, and it depends only on the
clock increment.

[Lemma lem:CRP case of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Suppose $\alpha\in(0,1)$. \begin{enumerate}[(i)]
\item 
Suppose $p_\ell = d_0\Gamma_\ell^{-1/\alpha}, \ell\in{\mathbb N}$ as in (equation eq:p_n CRP of the paper). 
For every $K>0$,
\begin{equation}
\max_{|k|\le K\sqrt{j_n\log\log n}}\abs{np_{\ell_n+k}-j_n   +\frac{j_n(\Gamma_{\ell_n}-\ell_n+k)}{\alpha\ell_n}}= O\pp{j_n^{1/4}(\log n)^{1/2}\pp{\log\log n}^{1/4}},
\end{equation}
almost surely. 
\item Suppose $p_n = d_0n^{-1/\alpha}(1+\rho_n)$. Then for all $K>0$,
\begin{equation}
\max_{|k|\le K j_n^{1/2}}\abs{np_{\ell_n+k}-j_n + \frac{j_nk}{\alpha\ell_n}} = O\pp{1}+O\pp{j_n\max_{|k|\le Kj_n^{1/2}}|\rho_{\ell_n+k}|}.
\end{equation}
\end{enumerate}

