[Prop CM UT LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a deterministic constant $c_3 \in (0,\infty)$ such that, 
  for any $x_0 \in M$, $r \in (0, 1 \wedge r_*)$, and $n, N \in \mathbb{N}$ with $4n \leq N$ and $c_1 Nr^{d^{\mathrm{min}}_\mathrm{w}} < 1 \wedge t_*$,
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{cp}}}\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} > 2,
  \end{equation}
  and 
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0, r)}
    \hat{P}_{\bm{x}}\!\left(\Pi_{c_1 N r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0,r)) \geq c_3 n r^{d_{\mathrm{f}}} \log (N/n)\right) 
    \geq 
    \tilde{c}_1 e^{-\tilde{c}_2 n},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} = 2.
  \end{equation}

[Lemma lem:eternal_time_s of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $b$ be an eternal solution, and assume there exists $s \in \mathbb{R}$ so that $\pmb{\xi}^{b,s}$ contains at least two colors. Then, for all $x \in \mathbb{R}$,
    \[
    b(x,s) =(\Wf{\mathfrak{c}^s})(x,s),
    \]
    where $\mathfrak{c}^s:\mathfrak{X} \to [-\infty,\infty)$ is defined by $\mathfrak{c}^s(\xi) = -\infty$ for all $\xi \notin \pmb{\xi}^{s,b}$, and for $\xi \in \pmb{\xi}^{s,b} = \{\xi_i\}_{i \in \mathcal I^s}$,
    \begin{equation}
    \mathfrak{c}^s \left(\xi_i \right)=
        b(\mathfrak{a}_{\xi_0},s) + \begin{cases}
            \sum^{i-1}_{j=0}W^{\xi_j}\left(\mathfrak{a}_{\xi_j},s;\mathfrak{a}_{\xi_{j+1}},s \right)+W^{\xi_{i}}\left(\mathfrak{a}_{\xi_{i}},s;0,0\right) & i \in \mathbb{Z}_{\ge 0}\\
            -\sum_{j=i+1}^{-1}W^{\xi_{j}}\left(\mathfrak{a}_{\xi_{j}},s;\mathfrak{a}_{\xi_{j+1}},s\right)+W^{\xi_{i}}\left(\mathfrak{a}_{\xi_{i+1}},s;0,0\right)& i \in \mathbb{Z}_{< 0},
        \end{cases}
    \end{equation}
    and we use the same shorthands for $\xi_i$ and $\mathfrak{a}_{\xi}$ as in Lemma (lem:s3 of the paper).

[Lemma lem:boundaryboxes of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $\vec W = (\log (B/X_1), \dots, \log (B/X_k))$ as in the previous lemma, $\vec U_{\!\pm}$ be defined as in (lem:decomposition into boxes of the paper), and $1< \theta \leq 2$. Let $\gamma > \max_{1\leq l\leq k} \sum_{i=1}^s \frac{\varpi_{li}}{\alpha_i}$. Then
	\begin{multline*}
		\sum_{\substack{\vec j \in \cal P(\vec U_{\!+}) \\ \vec j \notin \cal P(\vec U_{\!-})}} \sum_{\vec x \in \cal B_{\vec j}} |f(\vec x)| \ll
		C_f \int_{\Xi} \prod_{i=1}^s \mathrm e^{t_i} (1 + t_i)^{\ell_i} \,\mathrm d\vec t\\
		+ C_f (\log \theta)^{-A - s} \int_{\Xi} (1 + \min\nolimits_i t_i)^{-\delta} \prod_{i=1}^s \mathrm e^{t_i} (1 + t_i)^{\ell_i} \,\mathrm d\vec t,
	\end{multline*}
	where
	\begin{equation*}
		\Xi = \cal P(\vec W + (\gamma \log \theta, \dots, \gamma \log \theta)) \setminus \cal P(\vec W - (\gamma \log \theta, \dots, \gamma \log \theta)).
	\end{equation*}

