[Lemma 3 of arXiv:2604.12317, 'Weak solution for distribution dependent SDEs driven by L\'{e}vy noise'] (i) For any \( \alpha \in(1,2],~p>1 \) and \( \beta, \gamma \geq 0 \), for all \( f \in \mathbf{H}^{\beta,p} \), we have
\begin{equation}
		\left\|{P}_{t} f\right\|_{\beta+\gamma, p} \leq C t^{-\gamma / \alpha}\|f\|_{\beta, p}.
\end{equation}
(ii) For any \( \alpha \in(1,2], \theta \in[0,1] \) and \( p>1 \), there exists a constant \( C=C(d, p, \theta)>0 \), such that for all \( f \in \mathbf{H}^{\theta,p} \), we have
\begin{equation}
		\left\|{P}_{t} f-f\right\|_{p} \leq C t^{\theta / \alpha}\|f\|_{\theta, p}.
\end{equation}

[Corollary 7 (Closed-form sparse PX-EM updates) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] Let $\Ab^{(t)}=(a_{rc}^{(t)})$ be defined in \eqref{eq:A_updated_def}, and let $\psi_{rr}^{(t)}$ denote the $r$th diagonal entry of $\Psib^{(t)}$. The unique minimizer over
$\Lambdab\in\CC^{p\times k}$ of
\begin{align}

  \Qcal_{\Lambdab}^{\mathrm{red}}
  \left(
    \Lambdab
    \mid
    \thetab^{(t)}
  \right)
  +
  \rho\|\Lambdab\|_{1,\CC} =  \tr\left[
    \left(
      \Lambdab-\Ab^{(t)}
    \right)^\star
    \left(\Psib^{(t)}\right)^{-1}
    \left(
      \Lambdab-\Ab^{(t)}
    \right)
  \right] +
  \rho\|\Lambdab\|_{1,\CC},
\end{align}
is $\Lambdab^{(t+1)}$, whose entries are
\begin{align}

  \lambda_{rc}^{(t+1)}
  =
  \mathcal{T}_{\rho\psi_{rr}^{(t)}/2}
  \left(
    a_{rc}^{(t)}
  \right),
  \qquad
  r=1,\ldots,p,\quad c=1,\ldots,k,
\end{align}
where $\mathcal{T}_{\tau}$ is the complex soft-thresholding operator
defined in \eqref{eq:complex_soft_threshold_operator} as
\begin{align}

  \lambda_{rc}^{(t+1)}
  =
  \begin{cases}
    \displaystyle
    \left(
      1-
      \frac{\rho\psi_{rr}^{(t)}}
      {2|a_{rc}^{(t)}|}
    \right)
    a_{rc}^{(t)},
    &
    |a_{rc}^{(t)}|
    >
    \dfrac{\rho\psi_{rr}^{(t)}}{2},\\[3mm]
    0,
    &
    |a_{rc}^{(t)}|
    \leq
    \dfrac{\rho\psi_{rr}^{(t)}}{2}.
  \end{cases}
\end{align}
All entries of $\Lambdab^{(t+1)}$ can be updated simultaneously.

[Lemma lem:lcp-finite-energy-centered-products of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $x\in\Omega_{\rm str}^{\partial}$, and let
$\phi_1,\ldots,\phi_r$ be real, $L^2(M_x^\partial)$-orthonormal
eigenfunctions of $A_x$ with positive eigenvalues, and define
\begin{equation}
 \sigma_{ij}^x
 :=\Theta_{M_x^\partial}(\phi_i,\phi_j)
 =\phi_i\phi_jM_x^\partial-\delta_{ij}m,
 \qquad 1\le i,j\le r.

\end{equation}
For $1\le i,j\le r$,
\begin{equation}
 \sigma_{ij}^x(\mathbb T)=0,
 \qquad
 \iint_{\mathbb T\times\mathbb T}|G(\theta,\varphi)|
 \,d|\sigma_{ij}^x|(\theta)
 \,d|\sigma_{ij}^x|(\varphi)<\infty.

\end{equation}
Moreover, $U\sigma_{ij}^x\inH$ and
\begin{equation}
 \inner{U\sigma_{ij}^x}{f}_{H}
 =\int_{\mathbb T}f\phi_i\phi_j\,dM_x^\partial,
 \qquad f\inH_{\mathrm{reg}}.

\end{equation}

[Theorem eq:index-generating-formal of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:index-generating}
Fix \(s\in\mathbb R\), \(L>L_0\), and a continuous \(V\) bounded below.  Then
\begin{align}
 &\lim_{R\to\infty}\lim_{\delta\downarrow0}
 \lim_{\eta\downarrow0}\lim_{\varepsilon\downarrow0}
 \lim_{N\to\infty}
 \Phi_{N,L}^{G}(V,\varepsilon,f_{\eta,R,s,\delta})\notag\\
 &\qquad=\sup_u\{\theta_p(u)-V(u)+s\alpha_p(u)\}.

\end{align}
If \(V\in\mathcal V_m\) and the array \(J\) satisfies the hypotheses of either
(thm:bulk-universality of the paper) or (thm:weibull-bulk of the paper), the same
iterated limit holds with \(G\) replaced by \(J\).

