body:
[Pro 6 of arXiv:2605.30779, '2605.30779'] Let \(\beta\in\{1,2\}\) and \(\{\xi_{\beta,j}\}_{j\ge1}\) be i.i.d.\ random variables, independent of \(\{a_{\beta,j}^{\Theta}\}_{j\ge1}\), with \(\xi_{\beta,j}^2\sim\chi_\beta^2\). Define the Airy-Green function
  \begin{equation}
    \mathcal G^{(\beta)}_{\Theta}(w)
    :=
    \lim_{x\to-\infty}
    \left[
      \sum_{j:\,a_{\beta,j}^{\Theta}>x}
      \frac{\beta^{-1}\xi_{\beta,j}^2}{w-a_{\beta,j}^{\Theta}}
      -\frac{2}{\pi}\sqrt{-x}
    \right].
  \end{equation}
  For every fixed finite vector \(\Theta\), the limit in \eqref{eq:defn_Airy_Green_multiple} exists almost surely for every
  \[
    w\in
    \mathbb C\setminus
    \bigl\{
    a_{\beta,j}^{\Theta}:j\ge1
    \bigr\},
  \]
  uniformly on compact subsets avoiding the poles. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm intro3 of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\varphi(x)=|x|^{-s}$ for $0<s<1$ or $\varphi(x)=-\log|x|$.    Let $\mathsf{P}_0,\mathsf{P}_1$ be the laws of two stationary point processes with unit intensity with $\mathcal F^{elec}_{\beta}(\mathsf{P}_i)<\infty$, $i=0,1$. Then there exists a coupling $ \mathsf{Q}^0$ of $\mathsf{P}^0_0$ and $\mathsf{P}^0_1$ such that for $0\leq t\leq 1$ ($s=0$ corresponding to the $\log$ case)
    \begin{align*}
        \mathcal F^{elec}_{\beta}(\mathsf{P}_{t})&\leq  (1-t) \mathcal F^{elec}_{\beta}(\mathsf{P}_{0})+t\mathcal F^{elec}_{\beta}(\mathsf{P}_{1})\\
        &-\frac{(\mathbbm{1}_0(s)+s(s+1))(1-t)t\beta}{4}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}\left\lvertz\right\rvert^{-s-2} \mathsf{Q}^0(d\bar\xi).
    \end{align*}
In particular, $\mathcal F^{elec}_{\beta}$ has a unique minimizer. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 (Maximum principle with one boundary for \eqref{moving frame-u}) of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] For any fixed $t_*\ge 0$ and for any  continuous  function $X(t,i)$ defined for $t\ge i+t_*$ and $i\in[0,i_\dagger)$  satisfying $X(t,i)$  for each $i\in[0,i_\dagger)$ is nondecreasing in $t\in(i+t_*,+\infty)$, and  $X(t,0)\ge \max_{s\in[0,i]}X(t-i+s,s)$, let $u(t,i,x)$ be a  bounded and continuous  function defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $x\ge X(t,i)-R$,  such that
	\begin{equation}

		\begin{aligned}
			\left\{\begin{split}
				&	\partial_t u(t,i,x)  + \partial_i u(t,i,x) \le 0,~~~~~~~ ~~~~~~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~x\ge X(t,i) -R, \\
				&	u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *u(t,i,x)\md i,  ~~~~~~~~~~~~~~~~~~~t\ge  i_\dagger+t_*,   ~x\ge X(t,0).
			\end{split}\right.		
		\end{aligned}
	\end{equation}
	Assume further that $u(t,0,x)\le0$ for $t\in [ t_*,i_\dagger+t_*]$ and $x\ge X(t,0)$, that\footnote{For this boundary assumption, it will be sufficient to assume: $u(t,i,x)\le 0$ for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and $x\in[X(t,i)-R,X(t,i)]$.}  $u(t,0,x)\le 0$ for $t\ge t_*$ and $x\in[X(t,0)-R,X(t,0)]$, and $u(t,i,X(t,i))\le 0$ for $t\ge i+i_\dagger+t_*$ and $i\in[0,i_\dagger)$, then $u(t,i,x)\le 0$  for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:rec_map_prop of arXiv:2607.04514, 'Boundary-layer asymptotics for Gaussian-smoothed singular measures'] Assume (ass:standing of the paper)~(ass:standing:chart of the paper). Fix \(A>0\). There exists \(\sigma_0>0\) such that the map
  \( \mathcal T_{\rm rescaled}:(a,x,\sigma) \longmapsto y_\sigma(a,x)\) defined on
  \(\overline{\mathbb B}_A^{c+k}\times \mathcal{K}_{\mathcal{S}} \times (0,\sigma_0]\) and taking values in
  \(\mathcal U\) is well defined and of class \(C^{r}\). Moreover,
  \begin{equation*}
    \mathbf{Q}(x)^\top\bigl(y_\sigma(a,x)-x\bigr) = (0_{m-c},\sigma a_{\mathcal C},\sigma a_{\mathcal N}),
  \end{equation*}
  and
  \begin{equation}
    \pi\bigl(y_\sigma(a,x)\bigr)=x, \qquad u\bigl(y_\sigma(a,x)\bigr)=\sigma a_{\mathcal C},
    \qquad \eta\bigl(y_\sigma(a,x)\bigr)=\sigma a_{\mathcal N}.
  \end{equation}
  Consequently, for \((a,\sigma)\in\overline{\mathbb B}_A^{c+k}\times (0, \sigma_0]\) and for every
  \((y, \sigma)\in \mathcal Y_{A,\mathcal{K}_{\mathcal{S}}, \sigma_0}\),
  \begin{equation}
    a\bigl(y_\sigma(a,x),\sigma\bigr)=a ,\qquad \text{and}
    \qquad y_\sigma\bigl(a(y,\sigma),\pi(y)\bigr)=y.
  \end{equation}

[Proposition prop:CL-gen-system of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The system (equation eq:Linear-Psi-3 of the paper) is compatible\footnote{That is, for any choice of initial data $\{\Psi(T^ku_0)\}_{k \in \mathbb{Z}}$ along a $T$-orbit, the value of $\Psi$ at any vertex reached by a finite composition of $S_i$-shifts is independent of the order of the composition.} if and only if for all $i, j\in \mathbb{N}$ and $u \in \mathcal V$,
\begin{align}
C_i(Tu)C_j(S_iu) &= C_j(Tu)C_i(S_ju), \\
\Lambda_i(u)\Lambda_j(S_iu) &= \Lambda_j(u)\Lambda_i(S_ju), \\
C_i(u)\Lambda_j(S_iu)+\Lambda_i(Tu)C_j(S_iu)&-C_j(u)\Lambda_i(S_ju)-\Lambda_j(Tu)C_i(S_ju)=0. 
\end{align}

[Theorem thLIL1 of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] Assume
  \begin{align} C_{\mathbb V}\bigg[\frac{Y_1^2}{\log\log|Y_1|}\bigg]<\infty,
    \end{align}
    \begin{align}\breve{\mathbb E}[Y_1]=\breve{\mathbb E}[-Y_1]=0, \end{align}
    \begin{align}\overline{\sigma}^2<\infty. \end{align}
 Then
\begin{align}
\widehat{\mathbb V}^{\ast}\bigg( \limsup_{n\to \infty}\frac{|S_n|}{\sqrt{2n\log\log n}}> \overline{\sigma} \bigg)=0,
\end{align}
\begin{align}\widehat{\mathcal V}^{\ast}\bigg([-\overline{\sigma}, \;\;\overline{\sigma}]\supset Cl\Big\{\frac{S_n}{\sqrt{2n\log\log n}}\Big\} \supset
[-\underline{\sigma}, \;\;\underline{\sigma}]\bigg)=1,
\end{align}
where $Cl \{x_n\}$ denotes the set of limit points (cluster points) of $\{x_n\}$ in $\mathbb R$.

Furthermore, assume ((eqLILmomentcondition1 of the paper)), ((eqLILmeanzerocondition of the paper)), ((eqLILmomentcondition2 of the paper)), and
   \begin{align} \underline{\sigma}^2>0,
    \end{align}
and condition (CC) is satisfied. Then for $V=\mathbb V^{\mathscr{P}}$ or $\widehat{\mathbb V}^{\ast}$, we have
 \begin{align} 
V\bigg( Cl \bigg\{\frac{S_n}{\sqrt{2n\log\log n}}\bigg\}=[-\sigma, \sigma]\bigg)=\begin{cases}
  1, & \text{if } \sigma\in [\underline{\sigma},\overline{\sigma}],\\
  0, & \text{if } \sigma\not\in [\underline{\sigma},\overline{\sigma}].
  \end{cases}
\end{align}

Conversely, if condition (CC) is satisfied and for $V=\mathbb V^{\mathscr{P}}$ or $\widehat{\mathbb V}^{\ast}$,
$$V\bigg( \limsup_{n\to \infty} \frac{|S_n|}{\sqrt{2n\log\log n}}=\infty\bigg)<1, $$
then ((eqLILmomentcondition1 of the paper))-((eqLILmomentcondition2 of the paper)) hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 16 of arXiv:2609.03054, 'The classes of bivariate Schur and Herglotz matrix-valued rational functions: realizations'] Let $F(z_1,z_2)$ be a rational function. The statements of Theorems \ref{thm:kneseDD}, \ref{thm:contrRHP}, \ref{thm:posReRHP},  and \ref{thm:DDposRe}
hold when appending simultaneously:
\begin{enumerate}[]
\item $F$ being real rational matrix function  in statement {\rm (i);}
\item $A,B,C,D,P_1,P_2$ being real matrices in statement {\rm (ii)}.
\end{enumerate}

