[Lemma 17 (consistency: one-step weighted defect) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:boundary-charge}
  Assume $G'\in C^2_{\mathrm b}([0,\infty))$ and $\delta \in (1,2)$.  There exist $C_{\mathrm b}<\infty$ and $h_0>0$ such that, for all $h\in(0,h_0]$, the one-step defect of the clamped kernel \eqref{eq:clamped-kernel} satisfies
  \begin{equation}
    \|\nu_h\|_{V}=|\nu_h(\{0\})|+\int_0^\infty(1+x^2)|r(x)|\,dx\le C_{\mathrm b}\,h^{\delta}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma dir_E[multi_edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e^{\textnormal{tail}} = \delta^{\textnormal{tail}}\in O(1)$ and $\delta_e^{\textnormal{head}} = \delta^{\textnormal{head}}\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[(d_U^{\textnormal{out}})^{2\delta^{\textnormal{tail}}}], \mathds{E}[(d_U^{\textnormal{in}})^{2\delta^{\textnormal{head}}}] \in o(n)$
    \item $\exists c>0: \mathds{P}(d_U^{\textnormal{out}} \geq 2\delta^{\textnormal{tail}}),\mathds{P}(d_U^{\textnormal{in}} \geq 2\delta^{\textnormal{head}}) \geq c$ 
\end{enumerate}
then
\begin{align*}
    \mathds{E}[M_n] &= \frac{(\delta^{\textnormal{tail}}-1)!(\delta^{\textnormal{head}}-1)!}{2} n^2 \mathds{E}[d_U^{\textnormal{out}}] \mathds{E}[d_U^{\textnormal{in}}] \\
    &\hspace{0.5cm} \times \Big( \frac{\mathds{E}[(d_U^{\textnormal{out}})^2] - \mathds{E}[d_U^{\textnormal{out}}]}{n \mathds{E}[d_U^{\textnormal{out}}]^2} \Big)^{\delta^{\textnormal{tail}}} \Big(  \frac{\mathds{E}[(d_U^{\textnormal{in}})^2] - \mathds{E}[d_U^{\textnormal{in}}]}{n \mathds{E}[d_U^{\textnormal{in}}]^2} \Big)^{\delta^{\textnormal{head}}} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:convergence_need_to_explain of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $f(\omega,x)\in L_\omega^2L_x^2$ and $k(x,y)\in L_x^\infty L_y^2 $. Then, we have 
		\begin{equation}
			\lim_{n\uparrow\infty}\mathbb{E}\left\|f(k-k_n) \right\|_{L_{x,y}^2}^2=0.
		\end{equation}

