[Lemma thm:u=F of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For all integers $n_j\ge 1, j=1,\ldots,s$, we have    
\begin{equation}
    \kappa_X\big(n_1,\cdots,n_s\big)=\sum_{\Gamma\in \mathscr{D}_{s;\beta}^*} F_{\Gamma}(\{n_j\}_{j=1}^s).
\end{equation}

[Theorem TheoremCanoncialSpace of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] There exist unique $\mathcal{F}_{s-}$-measurable  probability kernels $\mathbb{P}_{s}^i$, $s \in [0,\infty)$, $i\in\mathcal{Z}$,  on $(\Omega, \mathcal{F}_{\infty})$   such that 
\begin{enumerate}
    \item[(i)]  For $s \in [0,\infty)$, $\omega \in \Omega$  and $i,j \in \mathcal{Z}$ with $j \neq i$, it holds that
\begin{align*}
 \Lambda^{ij}(\mathrm{d} t)(\omega) = \frac{\mathbb{E}_s^i[\mathds{1}_{\{\tau(s) \geq t\}} N^{ij}(\mathrm{d} t )](\omega)}{\mathbb{E}_s^i[\mathds{1}_{\{\tau(s) \geq t\}}](\omega)} 
\end{align*}
for those $t \in (s,\infty)$ such that neither $Z(\cdot )(\omega)$ has a jump in $(s,t)$ nor $\Lambda^{i \raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(\cdot)(\omega)$ has a pole or a jump of size $+1$ in $(s,t{]}$. 
\end{enumerate}
    Further, there exists a unique probability measure $\mathbb{P}$ on $(\Omega, \mathcal{F}_{\infty})$ such that
    \begin{enumerate}
\item[(ii)] Equation~(equation DefOfProbKernel of the paper) holds almost surely for $A \in \mathcal{F}_{\infty}$, $s \in [0,\infty)$,
	\item[(iii)] {f}or  $i \in \mathcal{Z}$, it holds that  
   \begin{align*}
   	 \alpha(i) =\mathbb{P}[Z(0) = i  ].
   \end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:on-bank-truth-validity of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Suppose the reported truth-level assertion $\widehat g$ is emitted only when
its predicate satisfies Equation~(equation eq:universal-truth-predicate of the paper), and
suppose the data-generating explanation $e_\star$ belongs to the bank.
Under Equation~(equation eq:on-bank-truth-retention of the paper),
\begin{equation}
    \sup_{e_\star\in\mathcal B}
    \mathbb P_{e_\star}
    \left\{
        \widehat g
        \text{ is reported and }
        q_{\widehat g}(e_\star)=0
    \right\}
    \le
    \alpha_{\mathcal B}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 33 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For each index $i\in [N]$ and for each $y \in \al, z \in \ar$, there exists a subset $A_{y,z,i}^{\stable}\subseteq A_{y,z}^{\stable}$ such that
    \begin{enumerate}
        \item The size of the subset is bounded: $|A_{y,z,i}^{\stable}| \leq 2k$.
        \item We have
        \begin{align}
