[Definition of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let
			\begin{align*}
				\tilde{T}^{2}(\mathbb{R}^d):=\big{\lbrace}\big{(}1\oplus(\alpha,\beta)\oplus(\gamma,\theta)\big{)}\ \vert\ \alpha ,\beta\in \mathbb{R}^d \ \text{and} \ \gamma ,\theta\in \mathbb{R}^d\otimes \mathbb{R}^d\big{\rbrace}.
			\end{align*}
			We define projections $\Pi_i^j$ by
			\begin{align*}
				\Pi_i^j\big{(}1\oplus(\alpha,\beta)\oplus(\gamma,\theta)\big{)} := \begin{cases}
					\alpha &\text{if } i = 1,\, j = 1 \\
					\beta &\text{if } i = 1,\, j = 2 \\
					\gamma &\text{if } i = 2,\, j = 1 \\
					\theta &\text{if } i = 2,\, j = 2.
				\end{cases}
			\end{align*}
			We also define
			\begin{align*}
				\big{(}1\oplus(\alpha_{1},\beta_{1})\oplus(\gamma_{1},\theta_{1})\big{)}&\circledast \big{(}1\oplus(\alpha_{2},\beta_{2})\oplus(\gamma_{2},\theta_{2})\big{)}:=\\ &\big{(}1\oplus(\alpha_{1}+\alpha_{2},\beta_{1}+\beta_{2})\oplus(\gamma_{1}+\gamma_{2}+\alpha_{1}\otimes\alpha_{2},\theta_{1}+\theta_{2}+\beta_{1}\otimes\alpha_{2})\big{)}
			\end{align*}
			and $\mathbf{1} := (1,(0,0),(0,0))$. In this case, \((\tilde{T}^{2}(U), \circledast)\) is a topological group with identity \(\mathbf{1}\). In particular, a \emph{delayed \(\gamma\)-rough path} takes values in \(\tilde{T}^{2}(\mathbb{R}^d)\), and the cocycle property (equation eqn:cocycle_rough_delay of the paper) is equivalent to  $ \mathbf{X}_{0,t}(\theta_{s}(\omega))=\mathbf{X}_{0,s}^{-1}(\omega)\circledast\mathbf{X}_{t+s}(\omega) $ for every $s,t \in \mathbb{R}$ and every $\omega \in \Omega$.

[Theorem 28 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $0\le p<(4a-1)/4a$ and $\{Z_n\}_{n\ge1}$ be uniformly bounded. Then,
\begin{equation}
\frac{W_n}{\sqrt{n}}\xrightarrow{d}\mathcal{N}\Big(0,\sigma^2+\frac{\mu^2K}{(2a(1-p)-1)^2}\Big),
\end{equation}
where $K$ is as given in \eqref{K}.

