[Proposition 1 of arXiv:2608.28991, 'Jigsaw-CRL: Recovering Global Latent Causal Order from Fragmented Multi-Client Interventio'] For $Z$ generated by Eq.~\eqref{eq:gloabl latent}, let $Z_k=(Z_{(i)})_{i\in O_k}$. Then
\begin{equation}
Z_k = \bA_k Z_k + E_k,
\end{equation}
where
\begin{align}

    \bA_k
    &=
    [\bA]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bA]_{M_k,O_k}, \\
    E_k
    &=
    E_{O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    E_{M_k}.
\end{align}
Moreover, $E_k$ has mean zero and covariance
\begin{equation}

    \bSigma_k
    =
    [\bSigma]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bSigma]_{M_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-T}
    [\bA]_{O_k,M_k}^{T}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorema WPHs of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $s\geq 0 $ and  $0<b< 1-s$. 
    \begin{enumerate}
        \item (subcritical) If 
        \begin{align*}
            1< \alpha < \begin{cases}
            1+ \frac{4-2b}{1-2s}\quad &\text{if} \quad s<1/2 \\ 
            \infty \quad &\text{if} \quad s \geq 1/2
        \end{cases},
         \end{align*} 
         then (equation INLS of the paper) is locally well-posed in $H^s.$ 
        \item (critical) If $s> 1/2$ and $\alpha=1+\frac{4-2b}{1-2s},$ then (equation INLS of the paper) is locally well-posed in $H^s$ and globally well-posed for the small data.
        \item (mildly ill-posed) If $s>0,\quad 0<b<1 \leq b+s<5/2, \; \alpha-1 \in 2\mathbb{N} \quad \text{and,\; if}\quad b+s \geq 1,\quad b+s \not \in \mathbb{N},$ then  (equation INLS of the paper) is mildly ill-posed in $H^s.$ 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 3 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] Let $T$ be a trace--class operator with eigenvalues $\lambda_i$, counted with algebraic multiplicity. Then the \emph{Fredholm determinant} of $I+T$ ($I$ being the identity operator) is defined as,
    \begin{equation*}
        \det(I+T) = \prod_i(1+\lambda_i)
    \end{equation*}

[Proposition 108 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] There are functors
	\begin{align*}
		\patch_\mode
		\colon
		\Heyt_\mode
		&\longrightarrow
		\EFrm_\mode;
		\\
		A&\longmapsto (E_A,\dc{A});
		\\
		g &\longmapsto \idl(\bool{g}).
	\end{align*}

[Lemma 26 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $h,\gamma,\lambda>0$ and  $T>0$ such that $n\coloneqq T/h\in\mathbb{N}$. Assume that there is a recurrence relation of the form 
    \begin{align*}
        f_{j+1}\le \bigl(1+ h\gamma \bigr)f_j+\lambda \qquad j=0,\dots,Tn-1
    \end{align*}
    such that $f_0=0$. Then it follows that
    \begin{align*}
        f_j\le \lambda \sum_{k=1}^j (1+h \gamma )^{k-1} .
    \end{align*}
    In particular $f_j\le \frac\lambda{h\gamma}  e^{T\gamma}$.

