{"artifact_digest":"sha256:80ace1bae3f785266fcff6c149a205fa74df7d19f656ff1c3e5ee9600e508bb2","artifact_path":"objects/sha256/80/80ace1bae3f785266fcff6c149a205fa74df7d19f656ff1c3e5ee9600e508bb2.md","bundle_digest":"sha256:fa6d822059c17973e8ffe531657f8d6a3f5daccf67db12bd2a9bc55330060f53","bundle_entry_key":"2606-15843-theorem-5-maintheorem","bundle_id":"population.tex-extract-s3_051","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-20260907/bundle_s3_051.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2606-15843-theorem-5-maintheorem","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: When $r<d$, consider the following system of SDE,
