[Definition 188 (The flat elliptic-hyperbolic current) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\SigmatTan$ be a $\Sigma_t$-tangent vectorfield.
	We define the characteristic current
	to be the vectorfield $\flatcurrent = \flatcurrent[\SigmatTan,\pmb{\partial} \SigmatTan]$
	with the following components, $(\alpha = 0,1,2,3)$:
	\begin{align} 
		\flatcurrent^{\alpha}[\SigmatTan,\pmb{\partial} \SigmatTan]
		& \eqdef 
		\SigmatTan^{\beta} 
		\partial_{\beta} \SigmatTan^{\alpha}
		-
		\SigmatTan^{\alpha} 
		\partial_{\beta} \SigmatTan^{\beta}.
	\end{align}

[Lem 249 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Assume that $L\ge1$ and that condition \eqref{e:deriv.p.bound} holds. Let $\vX\equiv \vX^N$ be the process defined by \eqref{e:X.decomp}
and \eqref{e:Delta.X.Ising}, and assume that condition~\eqref{e:w2.coupling.assumption} holds. Then the processes $\vX^\trstar,\vX^\frstar$ 
and $\vX^\trunc,\vX^\frozen$ 
of Definitions \ref{d:trunc}--\ref{d:buckets.Ising} can be coupled so that
	\begin{align*}
	\E\Big[\|\vX^\trstar(1)
		-\vX^\trunc(1)\|^2\Big]
	&\le O(\epsilon) + o_{\trK}(1)\,,\\
	\E\Big[\|\vX^\frstar(1)
		-\vX^\frozen(1)\|^2\Big]
	&\le O(\epsilon) + o_{\trK}(1)\,,
	\end{align*}
uniformly in $N$.
\begin{proof}
For fixed $a\in[M]$, consider $\vX^\trstar(q_d,a)$ as a process indexed by time $q_d$. Recalling Definitions~\ref{d:buckets} and \ref{d:buckets.Ising}, let $\tau^\trunc$ be the first time that index $a$ lands in a small bucket, and analogously $\tau^{\trunc,\Ising}$:
	\begin{align*}
	\tau^\trunc(a)
	&\equiv \min\bigg\{ 1,
	\min\bigg\{
		q_d : |B(q_d,a)| < \frac{M}{\BUCKETS^2}\bigg\} 
	\bigg\}\,,\\
	\tau^{\trunc,\Ising}(i)
	&\equiv \min\bigg\{ 1,
	\min\bigg\{
		q_d : |B^\Ising(q_d,i)| < \frac{N}{\BUCKETS^2}\bigg\} 
	\bigg\}\,.
	\end{align*}
It follows from the discussion around \eqref{e:total.number.of.particles.in.small.buckets} that
	\[\frac1M \sum_{a=1}^M
	\ind\{ \tau^\trunc(a) < 1 \}
	+\frac1N \sum_{i=1}^N
	\ind\{ \tau^{\trunc,\Ising}(i) < 1 \}
	\le o_\eta(1)\,.
	\]
This is similar to but stronger than our earlier claim 
\eqref{e:truncation.K.stopping.time.small.prob} for the stopping time $\tau$ from \eqref{e:trstar.stopping.time}. Therefore, repeating the argument around \eqref{e:truncation.K.stopping.time.small.prob} gives the result of
Proposition~\ref{p:max.X.process.on.trstar.stopped.event} with $\tau^\trunc$ in place of $\tau$. Repeating the argument of Corollary~\ref{c:X.versus.trstar.X.W2.error.estimate} then gives the conclusion for the $\bbW_2$ error between $\vX^\trstar(1)$ and $\vX^\trunc(1)$. Essentially the same argument applies to bound the 
$\bbW_2$ error between $\vX^\frstar(1)$ and $\vX^\frozen(1)$.
\end{proof}

[Corollary C:MC of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose condition (equation E:main of the paper) holds. Further assume $\ell<\alpha(\gamma+1/2)$ if $\beta=2$ and $\gamma \in (0,2]$ for part (i) below.
  Then the following results hold.
  \begin{enumerate}[\rm (i)]

    \item If $\rho \in (0, 1]$, then for any compact interval $I$ in $(0,
            \infty)$ and $x_0 \in \mathbb{R}^d$, there exists a random variable $Z_1$ with
          $\mathbb{E}[Z_1]<\infty$ such that
          \begin{align}
            |u(t, x_0) - u(s, x_0)| \le Z_1 w_1(|t-s|) \quad \text{for all } t, s \in I.
          \end{align}
          Moreover, suppose $\beta \in (0, 2)$, $\gamma \ge 0$, or $\beta = 2$, $\gamma \in [0,1]$. If
          $\rho \in (0, 1)$, then we have the following exact uniform modulus of
          continuity: There exists a constant $C_1 \in (0, \infty)$ such that
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{t, s \in I:\, 0<|t-s|\le \varepsilon} \frac{|u(t, x_0) - u(s, x_0)|}{w_1(|t-s|)} = C_1 \quad \text{a.s.}
          \end{align}

    \item If $\tilde\rho \in (0, 1]$, then for any $t_0 > 0$ and any compact
          rectangle $J$ in $\mathbb{R}^d$, there exists a random variable $Z_2$ with
          $\mathbb{E}[Z_2] < \infty$ such that
          \begin{align}
            |u(t_0, x) - u(t_0, y)| \le Z_2 w_2(|x-y|) \quad \text{for all } x, y \in J.
          \end{align}
          If $\tilde\rho \in (0, 1)$, then we have the following exact uniform
          modulus of continuity: There exists a constant $C_2 \in (0, \infty)$ such
          that
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{x, y \in J:\, 0<|x-y| \le \varepsilon} \frac{|u(t_0, x) - u(t_0, y)|}{w_2(|x-y|)} = C_2 \quad \text{a.s.}
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 53 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation in Lemma \ref{Lem.PowerSeriesSG}, and fix $\theta \in (\pi/4, \pi/2)$. There exist constants $\delta_1 \in (0,\delta_0]$ and $\epsilon_1 > 0$, depending on $q, \kappa, c, \theta$, such that for $r \in [0, \delta_1]$
\begin{equation}
\Real \left [\SFt(z;\kappa) - \SFt(c;\kappa) \right] \leq -\epsilon_1 \cdot r^2, \mbox{ if } z = c+r e^{\pm \im \theta}.
\end{equation}

