body:
[Lemma star of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $\eta$ be a function in $C^0(\mathbb{R}^n)$ and $J^\varepsilon$ a sequence of vector fields in $\mathbb{R}^{\mathcal E_{\varepsilon}}_a$. We define their product $\eta \pentagram J\in \mathbb{R}^{\mathcal E_{\varepsilon}}_a$  by
\begin{align*}
    (\eta\pentagram J) (x,y)=\frac{\eta(x)+\eta(y)}{2}J(x,y).
\end{align*}
Then:
    \begin{enumerate}

      \item Modulation:
      Let $ \iota J^\varepsilon\stackrel{*}{\rightharpoonup} \nu$ vaguely. Then
      \begin{align*}
       \iota(\eta \pentagram J^\varepsilon) \stackrel{*}{\rightharpoonup} \eta \nu \text{ vaguely.}
      \end{align*}
      \item Convergence of divergence:
        Let $\eta\in C^1(\mathbb{R}^n)$. Let $J^\varepsilon\stackrel{*}{\rightharpoonup} \nu$ and $\dive \iota  J^\varepsilon\stackrel{*}{\rightharpoonup} \dive \nu$ vaguely. Then
\begin{align*}
    \dive \iota (\eta\pentagram J^\varepsilon) \stackrel{*}{\rightharpoonup} \dive (\eta \nu) \text{ vaguely.}
\end{align*}
    \end{enumerate}

