body:
[Theorem 20 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Under Assumptions \ref{assumption 9.24.2}
and \ref{assumption 6.9.2} suppose that
\eqref{9.23.1} is satisfied and
 $u\in W^{1,2}_{(q,p),\loc}
(\cO)\cap C(\bar \cO)$.
Then 
on $\cO$
\begin{equation}

u \leq  \sup_{\partial'\cO }u_{+}+N(d,p_{0})C
\big\|c^{-\nu}r^{-1/q}(\det a)^{-1/p}(\cL u)_{-}
\big\|_{L_{(q,p)}(\cO )},
\end{equation}
where  $N$ is the constant in \eqref{6.2.1} and
$$
C= \Big(R+ \|h\|_{L_{(q_{0},p_{0})}}
^{  p_{0}/(p_{0}-d)  } 
\Big)^{ d/p}  
 $$
if $p_{0}>d$ and $C=N(d,\|h\|_{L_{(\infty,d)}})R$ if $p_{0}=d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 10 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] (localization of mixed moments of scores)
Assume the score $\xi: (X \times \R \times \MM)
\times \mathbf{N} \to \R$ satisfies $BL(\theta,\theta')$ space-time localization on $(X,d,\nu) \times (\R, \mu)$ as in Def.~\ref{def:space-time-loc} with short-range scores $(\xi^{[r]})_{r>0},(\xi^{(s)})_{s \in \R}$ and functions $\psi$ and $\phi$.

    Then for  any $\mathcal{A}_i \subseteq \{(z_1,t_{z_1}),...,(z_4,t_{z_4}),(x,t_{x}),(y,t_y)\} \in X \times \R$, with $i=1,...,4$, and any non-negative integers $p_1,p_2,p_3,p_4$ such that $p_1+p_2+p_3+p_4=p-1>0$, we have for any $r>0$
    \begin{equation}
    | \E \Pi_{i=1}^4 \xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)^{p_i} - \E \Pi_{i=1}^4 \xi^{[r]}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)^{p_i}| \leq C_p \psi(r)^{1/p}
    \end{equation}
    and  $s \in \R$ 
    \begin{equation}
    | \E \Pi_{i=1}^4 \xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)^{p_i} - \E \Pi_{i=1}^4 \xi^{(s)}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)^{p_i}| \leq C_p \phi(s)^{1/p},
    \end{equation}
    where $C_p=(36p-20) (M_{5,X}^\xi)^{(p-1)/p}$.

[Lemma 10 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} be valid and~\eqref{a.2} be false and suppose that if $\eta_{0} = \frac{1}{2}$, then $g_{1,1} = 0$ or $g_{1,2} = 0$. If $u_{1},u_{2}\in\R$ satisfy~\eqref{eq:extinction in the epidemic models 4} and
\begin{equation}
\limsup_{t\uparrow\infty} c_{1,2}(t) - \frac{1}{2}\big((g_{1,1} + g_{1,2}\mathbbm{1}_{\{1\}}(\eta_{0}))^{2} + g_{2,1}^{2}\mathbbm{1}_{\{1\}}(\eta_{0})\big) \leq u_{2},
\end{equation}
then any positive solution $I$ to~\eqref{eq:SIS epidemic model} becomes exponentially extinct whenever 
\begin{equation}
\big(u_{1} + u_{2}N_{\infty}\big)^{+}N_{\infty} < \mu_{\infty} + \gamma_{\infty} + u_{I}
\end{equation}
with the non-negative constant $u_{I} := \liminf_{t\uparrow\infty} \beta_{1}^{+}(t)N(t) - \beta_{1}(t)\E\big[I_{t}\big]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop gamma_rate of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] Assume there exist constants $\kappa>0$ and $C>0$ such that, for all $u\in[0,1]$,
    \begin{equation}
        \mu\bigl((a, a + (b-a)u] \bigr) \leq C u^{\kappa}.
    \end{equation}
    Then
    \begin{equation}
        0 \leq \gamma_n- \mathbb{P}(X=a) 
        \leq C \Gamma(\kappa+1) \frac{n}{(n-1)^{\kappa+1}}
        \le C \Gamma(\kappa+1)n^{-\kappa}, \qquad n \geq 2.
    \end{equation}

