[Corollary 7 of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] Fix $m\geq 1$, $p\in (0, 1)$, and $u\in (0, 1)$.  
\begin{enumerate}
\item Let $N$ be geometrically distributed by
\[
\mathbb{P}(N=n)=(1-u)u^n,
\qquad n\ge 0\;,
\]
and, conditional on $N=n$, let $\pi$ have the law $\nu^{(p)}_{n,m}$. Then, every finite subcollection of $N_1,N_2,\ldots $ is independent and the probability generating function of $N_i$ is
\begin{equation}
G^{(m,p)}_{i,u}(x):=\E_{\pi}[x^{N_i}]=\exp\left\{\sum_{r\ge 1}\frac{x^r-1}{ir}B^{(m,p)}_{i,r}u^{ir}\right\}.

\end{equation}

\item Fix $i\geq 1$, and let $\pi_n\sim \nu^{(p)}_{n,m}$.  Then, for every finite set $I\subseteq\mathbb{N}$, the random variables $\{N_i(\pi_n):i\in I\}$ converge jointly to independent random variables with marginal pgfs $G^{(m,p)}_{i, 1}$. 

\end{enumerate}

[Corollary 46 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Assume \eqref{eq:affine linear}.
Let $\lambda\in\mathbb{R}$ and let $\mathbf{u}^1=(u^1_{\mfl})_{\mfl\in\mfL_+}$, $\mathbf{u}^2=(u^2_{\mfl})_{\mfl\in\mfL_+}$ be the spatially periodic solutions of the systems 
\begin{align*}
   (\partial_t - \mathcal{L}_\mfl)u_\mfl^i = \sum_{\mft \in \mathfrak{L}_- \sqcup \{ \mathbf{0} \}} F_\mfl^\mft (\mathbf{u}^i) \xi_\mft^i+\sum_{\tau\in\mcT_-}c^i(\tau)\Upsilon_{\mfl}[\tau](\mathbf{u}^i), \qquad \mfl \in \mathfrak{L}_+,
\end{align*}
where the following are assumed:
\begin{itemize}
\item The initial conditions $\psi^i_\mfl$ satisfy $\psi^1_\mfl=\psi^2_\mfl$ for $\mfl\in\mfL_+^{\inh}$ and $\lambda\psi^1_\mfl=\psi^2_\mfl$ for $\mfl\in\mfL_+^{\hom}$;
\item The set $\mcT_-$ is finite and the prefactors $c^i:\mcT_-\to\mathbb{R}$ satisfy $c^2(\tau)=\lambda^{[\tau]}c^1(\tau)$;
\item $\xi^i_{\mft}$ are smooth functions that satisfy $\xi^1_{\mft}=\xi^2_\mft$ for $\mft\in\hat\mfL_-^{1}$ and $\lambda \xi^1_{\mft}=\xi^2_\mft$ for $\mft\in\mfL_-^{0}$.
\end{itemize}
Then $u^2_{\mfl}=\lambda u^1_{\mfl}$ for all $\mfl\in\mfL_+^{\hom}$ on their common interval of existence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(f\colon\mcalY\to\mcalX\) be a \(B\mcalG\)-torsor for a flat affine group scheme \(\mcalG\) over an fpqc stack \(\mcalX\).
  Let \(u\colon V\to\mcalX\) be an fpqc cover such that $V$ is a small disjoint union of affine schemes and
  \[
  \mcalY \times_{\mcalX} V \simeq B_V\mcalG_V
  \]
  over $V$.
  We consider the pullback square
  \begin{equation*}
    \begin{tikzcd}
      \mcalY_V \arrow[r,"v"] \arrow[d,"f_V"'] & \mcalY \arrow[d,"f"] \\
      V \arrow[r,"u"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  For $\mcalF \in \mcalD^+_{\qcoh}(\mcalY)$, the base change morphism
    \begin{equation}

      \BC_{f, u}(\mcalF) \colon Lu^*Rf_*\mcalF\to R(f_V)_*Lv^*\mcalF
    \end{equation}
    is an equivalence in \(\mcalD_{\qcoh}(V)\).

