[Lemma 18 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Let $\tau\in\mathbb{R}$, $T>0$, and let $\mathfrak{B}(\tau)>0$ be a given constant. Then, for every $\zeta\in L^4(\Omega,\mathscr F_\tau;\mathcal H)$ satisfying $\mathbb E[|\zeta|^4+|\partial_z\zeta|^4]\leq\mathfrak B^4(\tau)$,
	\begin{align}
		\lim_{\epsilon\to0}\sup_{\substack{\mathbb E\left[|\zeta|^4+|\partial_z\zeta|^4\right]\leq \mathfrak{B}^4(\tau)}}
		\mathbb E\left[\sup_{t\in[\tau,\tau+T]}
		|v^\epsilon(t,\tau,\zeta)-v^0(t,\tau,\zeta)|^2\right]=0.
	\end{align}
	Consequently, for the admissible moment ball
	\[
	\mathbb B_{4,z}(\mathfrak B(\tau))
	:=
	\left\{\mu\in\mathcal P_{4,z}(H):
	\int_H\bigl(|\zeta|^4+|\partial_z\zeta|^4\bigr)\mu(d\zeta)
	\le\mathfrak B^4(\tau)\right\},
	\]
	and every $t\in[\tau,\tau+T]$,
	\begin{align}
	\lim_{\epsilon\to0}
	\sup_{\mu\in\mathbb B_{4,z}(\mathfrak B(\tau))}
	d_{\mathcal P(H)}
	\bigl(S_\epsilon(t,\tau)\mu,S_0(t,\tau)\mu\bigr)=0.
	\end{align}

[Thm 39 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] The following hold.
  \begin{itemize}
    \item [$\mathrm{(i)}$]For any $x\in F$, a non-empty open set $U\subsetneq F$ and its complement $A:=F\setminus U$, 
    $g_A^{\alpha}(x,\cdot)$ is $2$-Lipschitz. 
    \item [$\mathrm{(ii)}$]For any $x\in F$, $g^{\alpha}(x,\cdot)$ is a Lipschitz continuous function.
    Moreover, there exists $\g{c}{continuity,1}\in (0,\infty)$ such that
    \begin{align}
      \|g^{\alpha}(x,\cdot)\|_{\Lip^1}\lesssim 
      \g{c}{continuity,1}(1+\alpha^{-1}),\qquad x\in F,\;\alpha\in (0,\infty),
    \end{align}
    and $\g{c}{continuity,1}$ is given by 
    \begin{align}
    \g{c}{continuity,1}=\frac{1}{1-E_{x_0}[e^{-\sigma_{x_0,x_1}}]}  
    \end{align} 
    for any distinct points $x_0,x_1\in F$.
    \item [$\mathrm{(iii)}$]Let $t_0\in (0,\infty]$. Suppose that the heat kernel $p$ satisfies
    \begin{equation*}
      \begin{aligned}
        c_{\rm{LHK}}t^{-\theta_l}\leq p(t,x,x),\quad t\in (0,\infty),\;
        \rm{and}\;\;
         p(t,x,x)\leq c_{\rm{UHK}}t^{-\theta_u},\quad t\in (0,t_0).
      \end{aligned}
    \end{equation*}
    with constants $c_{\rm{LHK}},c_{\rm{UHK}},\theta_u>0$, and $\theta_l\in (0,1)$.
    Then $p(t,x,\cdot)$ is Lipschitz continuous for $t<t_0$, and it holds that
    \begin{align}
       \|p(t,x,\cdot)\|_{\Lip^1}\lesssim \g{c}{continuity,2}(1+t)t^{-\left(\frac{\theta_u-\theta_l}{2}+1\right)},\qquad x\in F,\;t\in (0,t_0),
    \end{align}
    where $\g{c}{continuity,2}=\g{c}{continuity,1}\left( \frac{c_{\rm{UHK}}}{c_{\rm{LHK}}\Gamma(1-\theta_l)} \right)^{1/2}$.
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 214 of arXiv:2601.16377, '2601.16377'] The fundamental solution of the master problem is the $H^2$-tuple of functions $\boldsymbol{\mathcal{F}}(z_1,z_2) = \big(\mathcal{F}_{h_1,h_2}(z_1,z_2)\big)_{h_1,h_2 = 1}^{H}$ given in terms of the operator \eqref{eq_solution_Master_equation} by
\begin{equation}

\forall h_1,h_2 \in [H] \qquad \mathcal{F}_{h_1,h_2}(z_1,z_2) =
\Op_{h_1}\left[\frac{\sqrt{(* - \alpha_{h_2})(* - \beta_{h_2})}}{2(*- z_2)^2}\boldsymbol{e}^{(h_2)}\,;\,\boldsymbol{\kappa} = \boldsymbol{0}\right](z_1),
\end{equation}
where $*$ is a placeholder for the variable in which this tuple is seen as a function on which the operator $\Upsilon_{h_1}$ is applied, and $\boldsymbol{e}^{(1)},\ldots,\boldsymbol{e}^{(H)}$ is the canonical basis of $\amsmathbb{R}^H$.

[Lemma flowuniq of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] The flow $ \Phi_t $ associated with the RDEs ((RDEvec of the paper)) is given by the formula
	\begin{equation*}
	\Phi_t=e^{tV_0}\circ e^{B_t^{H,1}V_1}\circ \cdots \circ e^{B_t^{H,d}V_d},
	\end{equation*}
	where $ \phi \circ \psi $ is the composite of two maps $ \phi$, $\psi $ of $ \mathbb{R}^n $ into itself. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] For almost every $a_0\in \R$, we have
      \begin{equation}

          \int_{\R^+\times\R} \mathds{1}_{\widetilde \Omega_{a_0}\setminus\Gamma_{a_0}}(t,x)dtdx=0,
