[Lemma WPD-NHS-HUD-BB-3 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\} $ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, the intermittent building block ${\mathbb{W}_\xi } \left( {t, \cdot } \right)$ defined by (equation IBW-GJI-A-2 of the paper) satisfies
\begin{equation}
{\left\| {{\mathbb{W}_\xi }\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}  \lambda _{q + 1}^N    ,
\end{equation}
and
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}{\mathbb{W}_\xi }\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim   \delta _q^{\frac{1}{2}}\lambda _{q + 1}^{N + 1}   .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(\mathcal{Z}_t)_{0 \leq t \leq T}$ be a given $\mathcal{S}'(\mathbb{R})$-valued stochastic process defined on some probability space $(X, \mathcal{F}, P)$. 
We say that $(\mathcal{Z}_t)_{0 \leq t \leq T}$ satisfies an \textit{Energy Estimate} (EE) if there exist $\kappa_0 >0$, $\omega >0$ such that for every $H \in \mathcal{S}(\mathbb{R})$, any $0 < \delta < \varepsilon < 1/2$ 
and any $0 \leq s < t \leq T$, we have 
\begin{equation} 
\mathbb{E}_P \big[ \big( \mathcal{B}_{s,t}^{\varepsilon}(H) - \mathcal{B}_{s,t}^{\delta}(H)  \big)^2 \big] \leq \kappa_0 \varepsilon^{\omega} (t-s) \| \nabla H \|^2_{L^2(\mathbb{R})}, 
\end{equation}
where, for any $\varepsilon \in (0, 1/2)$, $0 \leq s \leq t \leq T$ and $H \in \mathcal{S}(\mathbb{R})$, 
the process $\mathcal{B}_{s,t}^{\varepsilon}(H)$ is defined as 
\begin{equation} 
\mathcal{B}_{s,t}^{\varepsilon}(H):= \int_s^t \int_{\mathbb{R}} \nabla H (u)  \mathcal{Z}_r \big(\overleftarrow{\iota}^u_{\varepsilon}\big) \mathcal{Z}_r \big( \overrightarrow{\iota}_{\varepsilon}^u \big) \; \dd u \; \dd r,
\end{equation}
and $\overleftarrow{\iota}_{\varepsilon},\,\overrightarrow{\iota}_{\varepsilon}$ 
are the normalised indicator functions 
\begin{align} 
\overleftarrow{\iota}_{\varepsilon}(v):=\frac{1}{ \varepsilon } \mathbbm{1}_{ \{  [- \varepsilon, \; 0)  \}  } (v), \quad \overrightarrow{\iota}_{\varepsilon}(v):=\frac{1}{ \varepsilon } \mathbbm{1}_{ \{  (0, \; \varepsilon ]  \}  } (v)\,,\qquad  v \in \mathbb{R}
\end{align}
while, for $u \in \mathbb{R}$ fixed, and a function $h$, the shifted function $h^{u}$ 
is 
\begin{align} 
 h^{u}(v):=h(v-u)\,,\qquad  \,v \in \mathbb{R}\,.
\end{align}

[Proposition 5 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] For every $t>0$, we have
		\begin{equation}
			\E[\Card(\VOMR)] = (d\kappa_d)^d C_d \sum_{i=0}^{d-1} t^{di} \kappa_d^{i-d+1} \frac{(d-1)!}{i!} e^{-\kappa_d t^d} 
		\end{equation}
		where \(\kappa_d\) is given at \eqref{eq:defkappad}. Therefore,
		\begin{equation}
			\E[\Card(\VOMR)] \underset{t\rightarrow\infty}{\sim} (d\kappa_d)^d C_d t^{d(d-1)} e^{-\kappa_d t^d}
		\end{equation}
		where, denoting by \(\m U_0,...,\m U_d\) $(d+1)$ i.i.d. uniform random variables on the \((d-1)\)-dimensional unit sphere \(\Sp_{\R^d}\) and by \(\Delta_{d}(\m U_0,...,\m U_d) = \Vol_d(\Conv(\m U_0,...,\m U_d))\) the \(d\)-dimensional Lebesgue measure of the \(d\)-dimensional simplex having these random points as vertices,
		\begin{equation}
			C_d = \E\left[ \Delta_{d}(\m U_0,...,\m U_d)  \1_{0\in\Conv(P_{\m U_0^\perp}(\m U_1),... ,P_{\m U_0^\perp}(\m U_d))} \right].
		\end{equation}

