\d\mathbf{S}^{N}_{\t,\x}&=\mathscr{T}_{N}\mathbf{S}^{N}_{\t,\x}\d\t+[\mathscr{S}^{N}\star(\sqrt{2}\lambda N^{\frac12}\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}\d\mathbf{b}_{\t,\cdot})]_{\x}\\
&+N\sum_{\substack{\n=1,\ldots,\mathrm{K}\\{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\lesssim \mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\d\t\\
&+N\sum_{\substack{\n=1,\ldots,\mathrm{K}\\{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\lesssim \mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{T},\mathrm{av}}_{\mathfrak{t}_{\mathbf{Av}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{X},\mathfrak{q}_{\n}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\d\t\\
&+\mathrm{Err}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}\d\t.
\end{align}

\begin{itemize}
\item We set {\small$\mathscr{T}_{N}:=(N^{2}\alpha+\frac12N\lambda^{2})\Delta$}, where {$\Delta$} is the discrete Laplacian as in (equation eq:phi of the paper), and $\alpha,\lambda$ are defined after (equation eq:ch of the paper). 
\item For each {\small$\n$} in the summations in (equation eq:s-sdeI of the paper)-(equation eq:s-sdeII of the paper), the local function {\small$\mathfrak{q}_{\n}$} is admissible (see Definition (definition:admissible of the paper)).
\item The parameters {\small$\mathfrak{t}_{\mathbf{Av}},\mathfrak{n}_{\mathbf{Av}}$} are from Definition (definition:eq-operators of the paper).
\item The {\small$\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\in\R$} are deterministic coefficients satisfying the following estimates.

\begin{itemize}
\item If {\small$\min\{|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\}\geq2$}, then we have {\small$|\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}|\lesssim 1$}. In general, we have {\small$|\mathrm{c}_{N,\n,\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}|\lesssim N$}.
\end{itemize}

\item The quantity {\small$\mathrm{Err}[\mathbf{R}^{N}\mathbf{S}^{N}]$} is a linear operator in {\small$\mathbf{S}^{N}$} which satisfies the following deterministic estimate for some positive {\small$\mathrm{C}\lesssim1$}, in which {\small$\mathsf{f}:\Z\to\R$} is any test function:

\begin{align}
|\mathrm{Err}[\mathbf{R}^{N}_{\t,\cdot}\mathsf{f}]_{\x}|\lesssim N^{-\frac12+\mathrm{C}\delta_{\mathbf{S}}}\cdot N^{-1+\delta_{\mathbf{S}}}\sum_{|\w|\lesssim N^{1-\delta_{\mathbf{S}}}}\Big(1+\sum_{|\z|\lesssim1}|\bphi_{\t,\x+\w+\z}|^{\mathrm{C}}\Big)\cdot|\mathbf{R}^{N}_{\t,\x+\w}|\cdot|\mathsf{f}_{\x+\w}|.
\end{align}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 52 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] There is a unique probability measure \(\pi_H\) on \(\mathbb R_+\) such
that, with
\begin{equation}
  \mu_H:=\int_{[0,\infty)}K_u\,\pi_H(\mathrm du),

\end{equation}
one has
\begin{equation}
  \mathcal L_{\widehat{\PP}_a}
  (U_a,V_a,\overline L_a,\overline R_a)
  \Longrightarrow\mu_H,
  \qquad a\to\infty.

\end{equation}
Moreover, let \(a_n\to\infty\) be arbitrary and choose the strictly
increasing integers \(r_n\), with \(h_n:=2^{-r_n}\leq2^{-n}\), far enough
along the fixed-row approximations that both
\eqref{eq:relative-tilted-diagonal} and
\eqref{eq:scalar-tilted-grid-diagonal} hold, as in
Theorem~\ref{thm:subsequential-boundary-entrance-mixture}.  Then the
associated left-horizon mixing measures satisfy
\begin{equation}
  \pi_n\Longrightarrow\pi_H.

\end{equation}

