[Thm Base Point Independence of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $\Gamma = \mathscr{P}(z_i, z_j)$ be a Pochhammer contour, and let $p_0 = \Gamma(0)$ denote its base point. Then the integral
\begin{equation}
\int_{\Gamma} C_{(b)}[\boldsymbol{\sigma}] \, d\xi
\end{equation}
is independent of the choice of base point $p_0$.

[Proposition prop:ultrahot of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] Assume $\beta = o(1)$. Then there exist universal constants $C, c > 0$ such that, for all $\epsilon \in (0,1)$,
\begin{align*}
    {\mathbb P}\Big( 
        \,
        |\mathcal{E} - \bar \mathcal{E} |
        \;\geq\;  
        C
        \Big(
            \mfrac{\epsilon}{(1-\epsilon) }    
            +
            \mfrac{\beta^2 \log m}{n}
        \Big)
    \Big)
    \;\leq\; 
    \epsilon^{-2} 
    e^{ - c \log m }\;.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 3 (Wigner matrix) of arXiv:2605.07050, 'Universality of the fluctuations of the free energy in generalized Sherrington--Kirkpatric'] A Wigner matrix is an $N \times N$ real symmetric matrix $W$ whose upper triangle entries $W_{ij}$ are i.i.d. real random variables satisfying the following conditions:
\begin{itemize}
\item The entries are centered, i.e., $\E[W_{ij}] = 0$ for all $i, j$.
\item The variances of the entries are normalized so that $\E[W_{ij}^2] = N^{-1}$ for $i \neq j$ and $\E[W_{kk}^2] = w_2 N^{-1}$ for a constant $w_2 \geq 0$.
\item For any integer $s>2$, there exists a constant $C^W_s$ such that $\E[|\sqrt{N} W_{ij}|^s] \leq C^W_s$ for all $i, j$.
\end{itemize}

[Proposition prop:concentr of arXiv:2411.11429, 'Functional Central Limit Theorem for topological functionals of Gaussian critical points'] {  Let $G$ be a Gaussian field over some compact $A\subseteq  \mathbb R^{ d}, \sigma _A^2: =  \sup_{ x\in A} \textrm{Var}\left(G(x)\right)$ and $ \sigma ^2\geqslant \sigma _A^2 $. Assume  for some $ \lambda <\infty $
\begin{align}

 \sigma ^{ -2}\mathbf E [\|G(x)-G(y)\|^2]\le   \lambda  ^2\|x-y\|^2, \qquad x,y\in A.
\end{align}
 There is  $ c >0$ depending only on $d, \lambda  $ such that for  $ t\geqslant 0$
\begin{align}
\mathbf P(\|G\|_A\ge t)\le  c  (1 +  \mathsf{ diam }(A)^{  {d}})\exp(-t^2/2\sigma^2).
\end{align}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2604.16795, '2604.16795'] Suppose that Assumption {\rm\ref{A0}} holds. Then the following statements hold.
	\begin{itemize}
		\item[{\rm(i)}] Assume that \begin{equation}\limsup_{|x|\to \infty} \frac{V_-(x)}{|x|^2}=0,\quad \limsup_{|x|\to \infty}\frac{V_-(x)}{\inf_{z\in B(x,|x|/2)}\widetilde K(z)}<\infty.\end{equation}
		Then, for any $c>0$, there are constants $c_1,c_2, r_0>0$ and $T_0\ge1$ such that for all $n\ge0$, $x\in \R^d$ with $|x|\ge r_0$,
		\[ |\va_n(x)|\le c_1e^{\lambda_n T_0/2}\exp\left(-{V_+(x)}\right)\left[\exp\left(-c\inf_{z\in B(x,|x|/2)}\widetilde K(z)\right)+\exp\left(- c_2 |x|^2 \right)\right].\]
		\item[{\rm(ii)}]  Assume that \begin{equation}\limsup_{|x|\to \infty} \frac{|x|^2}{\inf_{z\in B(x,|x|/2)}\widetilde K(z)}<\infty, \quad \limsup_{|x|\to\infty}\frac{V_-(x)}{|x|\inf_{z\in B(x,|x|/2)}\widetilde K(z)^{1/2}}=0.\end{equation} Then, there are constants $c_1,c_2,r_0>0$ and $T_0\ge1$ such that for all $n\ge0$ and $x\in \R^d$ with $|x|\ge r_0$,
		\[ |\va_n(x)|\le c_1e^{\lambda_n T_0/2}\exp\left(-{V_+(x)}\right)\exp\left(-c_2|x|\inf_{z\in B(x,|x|/2)}\widetilde K(z)^{1/2}\right).\]
	\end{itemize}

