[Theorem thm:harmonizable of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $\widetilde{M}_\alpha$ be a complex isotropic S$\alpha$S random
measure on $\mathbb{R}$ with Lebesgue control measure. Under
Assumption~(ass:params of the paper), define
\begin{equation}

\widetilde{X}^{(n)}_H(t)
:= \mathrm{Re}\int_\mathbb{R}
\frac{\Gamma(1/\alpha)}{\alpha\sqrt{2\pi}}\cdot
\frac{e^{it\xi}
  - \displaystyle\sum_{k=0}^{n-1}\frac{(it\xi)^k}{k!}}
{|\xi|^{H(t)+1/\alpha}}\,
e^{-i\pi(1-1/\alpha)\,\mathrm{sign}(\xi)/2}
\,d\widetilde{M}_\alpha(\xi).
\end{equation}
Then $\{X^{(n)}_H(t)\}_{t\in\mathbb{R}}$ and
$\{\widetilde{X}^{(n)}_H(t)\}_{t\in\mathbb{R}}$ have identical
finite-dimensional distributions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem.dpiconstant of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Suppose that $p > 4$, $(\Omega, \mathcal{F}, \mathbb{P})$ is any probability space, $t_0 \in [0,1)$, $X_0 \in L^p(\Omega)$, $\widebar\alpha \in L^{\infty}(\Omega)$ with $\|\widebar\alpha\|_2 \leq c_0$, and $h \in (0,1-t_0)$. Then
    \begin{align*}
        \mathcal{V}_p^+\big( t_0, \mathcal{L}(X_0) \big) \leq \mathcal{V}_p^+\big( t_0 + h, \mathcal{L}(X_0 + h \widebar\alpha) * \gamma_h \big).
    \end{align*}

[Defn 2 of arXiv:2606.11774, 'Martingale Solutions to a Stochastic Keller-Segel System with nonlocal Source and Super-li'] (Martingale solution)
  Let $T > 0$, a global martingale solution on $[0,T]$ to the equation (\ref{equ1}) is a triple\begin{align*}
 \big(  (\tilde{\Omega} ,\tilde{\mathcal{F}}, \{\tilde{\mathcal{F}}_{t}\} _{t\ge 0}  ,\tilde{\mathbb{P}}  ), \tilde{u},\tilde{W}\big) 
  \end{align*}such that
  \item[(i)]$\tilde{\mathfrak{A}}:= (\tilde{\Omega} ,\tilde{\mathcal{F}}, \{\tilde{\mathcal{F}}_{t}\} _{t\ge 0}  ,\tilde{\mathbb{P}}  )$ is a probability space with a complete, right-continuous filtration;
   \item[(ii)]$\tilde{W}$ is a $Q$ Wiener process   on $\tilde{\mathfrak{A}}$;
 \item[(iii)]$\tilde{u}(t)$ is a $\tilde{\mathcal{F}}_{t}$-measurable process  such that
\begin{align*}
   \tilde{u } \in L^2(\tilde{\Omega};L^\infty([0,T];L^2(\mathcal{O})))\cap L^2(\tilde{\Omega};L^2([0,T];H^1(\mathcal{O})))\cap L^k(\tilde{\Omega};L^k([0,T];L^k(\mathcal{O}))),
\end{align*}
where $ k\in(2,\frac{2}{d+2}(\alpha-1+\beta)+2)$. Moreover,
the law of $\tilde{u}(0)$ is the same as  $u_0$ and  for all $t\in[0,T]$ and for all $\phi \in H^1(\mathcal{O})$,  $\tilde{u}$ satisfies
\begin{align*}
    (\tilde{u}(t),\phi)_{L^2(\mathcal{O})}=&(\tilde{u}(0),\phi)_{L^2(\mathcal{O})}-\int _0^t\int_\mathcal{O}\nabla\tilde{u}(s)\cdot\nabla\phi dx ds+  \int _0^t\int_\mathcal{O} \tilde{u}(s)\nabla \tilde{c}(s)\cdot\nabla  \phi dxds
    \\&+\int _0^t\int_\mathcal{O} \tilde{u}^\alpha(s)(1-\int_\mathcal{O}\tilde{u}^{\beta}(s)dx)\phi dx ds+\Big(\int _0^t\sigma(\tilde{u}(s))d\tilde{W}(s),\phi \Big)_{L^2(\mathcal{O})}.
\end{align*}

