[Theorem 9 (Non-critical power-rate estimate) of arXiv:2608.17540, 'Pathwise stability for one-dimensional SDEs driven by Brownian motion and a symmetric stab'] Assume Assumptions~\ref{ass:baseline}--\ref{ass:solutions}. Suppose $B,A,S<1$.
If $\wt\eta\in(1/\alpha,1]$, then there exists $C>0$ such that
\begin{align}
\sup_{0\le t\le T}\E|X_t-\wt X_t|^{\alpha-1}
\le C\Bigg[&|x_0-\wt x_0|^{\alpha-1} \notag\\
&+\max\left\{
B^{\frac{\alpha\wt\eta-1}{\alpha\wt\eta-\alpha+1}},
A^{\frac{2(\alpha\wt\eta-1)}{\alpha\wt\eta-\alpha+2}},
S^{\alpha-1/\wt\eta}
\right\}\Bigg]. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ito-convergence of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Consider the setup of (general-mild-existence of the paper) and (def:yosida of the paper), and suppose $\theta_F = \theta_G = 0$. Let $\Phi: \mathcal{B} \to \mathbb{R}$ be twice continuously differentiable with linearly bounded first and second derivatives: $\|\Phi'(x)\|_{\mathcal{L}(\mathcal{B},\mathbb{R})} + \|\Phi''(x)\|_{\mathcal{L}(\mathcal{B},\mathcal{L}(\mathcal{B},\mathbb{R}))} \lesssim 1 + \|x\|_B$. Then for all $T > 0$, $p \geq 2$:
    \begin{itemize}
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T |\Phi'(x_n(t))F_n(x_n(t)) - \Phi'(x(t))F(x(t))|^pdt\Big] = 0$.
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T \|\Phi'(x_n(t))G_n(x_n(t)) - \Phi'(x(t))G(x(t))\|_{\mathcal{U}^*}^pdt\Big] = 0$.
        \item $\lim_{n \to \infty} \mathbb{E}\Big[\int_0^T |\operatorname{tr}_{G_n(x_n(t))}\Phi''(x_n(t)) - \operatorname{tr}_{G(x(t))}\Phi''(x(t))|^pdt\Big] = 0$. (For any operator $T$ on $\mathcal{U}$ we define $\operatorname{tr}_{T}\Phi''(x) = \sum_{j \geq 1} \Phi''(x)[Tu_j, Tu_j]$ where $(u_j)$ is an orthonormal basis for $\mathcal{U}$.)
    \end{itemize}
    Thus,
    \begin{align*}
        \int_0^t \Phi'(x_n F_n(x_n))ds + \int_0^t \Phi'(x_n G_n(x_n)) dW_s + \frac{1}{2}\int_0^t \operatorname{tr}_{G_n(x_n)}\Phi''(x_n)ds \\
        \to \int_0^t \Phi'(x)F(x)ds + \int_0^t \Phi'(x)G(x)dW_s + \frac{1}{2}\int_0^t \operatorname{tr}_{G(x)}\Phi''(x)ds
    \end{align*}
    in $L^p(\Omega; C([0,T], \mathbb{R}))$, where we omitted the dependence of $x_n$ and $x$ on $s$.

