body:
[Theorem th:nonquad of arXiv:2608.19358, 'An optimal Poincaré inequality\\for the complex Ginibre log-gas'] Take $n\geq1$ and let
  $V\in\mathcal{C}^2(\mathbb{C}\equiv\mathbb{R}^2,\mathbb{R})$ be rotationally
  invariant, and such that
  \begin{equation}
    Z_n^V=\int_{\mathbb{C}^n}\mathrm{e}^{-n\sum_{k=1}^nV(z_k)}\prod_{j<k}|z_j-z_k|^2\mathrm{d}z_1\cdots\mathrm{d}z_n <\infty.
  \end{equation}
  Consider the Boltzmann--Gibbs probability measure on $\mathbb{C}^n$ defined by
  \begin{equation}
    \mu_n^V=\frac{1}{Z_n^V}\mathrm{e}^{-n\sum_{k=1}^nV(z_k)}\prod_{j<k}|z_j-z_k|^2\mathrm{d}z_1\cdots\mathrm{d}z_n.
  \end{equation}
  Then for every constant $\rho>0$, the following properties are satisfied.
  \begin{enumerate}
  \item If $V$ is $\rho$-subharmonic, in the sense that
    $V-\frac{\rho}{2}\left|\cdot\right|^2$ is subharmonic, then $\mu_n^V$
    satisfies a Poincaré inequality for symmetric functions: for all symmetric
    $f\in\mathcal{C}^\infty_c(\mathbb{C}^n,\mathbb{R})$,
    \begin{equation}
      \operatorname{Var}_{\mu_n^V}(f)
      \leq\frac{1}{\rho n}\int_{\mathbb{C}^n}|\nabla f|^2\mathrm{d}\mu_n^V.
    \end{equation}
  \item If $V$ is $\rho$-convex, in the sense that
    $V-\frac{\rho}{2}\left|\cdot\right|^2$ is convex, then $\mu_n^V$ satisfies
    a logarithmic Sobolev inequality for symmetric radial functions: for all
    symmetric $F\in\mathcal{C}^\infty_c((0,\infty)^n,\mathbb{R})$, the
    function $f(z_1,\ldots,z_n)=F(|z_1|,\ldots,|z_n|)$ satisfies
    \begin{equation}
      \operatorname{Ent}_{\mu_n^V}(f^2)
      \leq\frac{2}{\rho n}\int_{\mathbb{C}^n}|\nabla f|^2\mathrm{d}\mu_n^V.
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm quantitive of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] A unique smooth solution $g$ to (equation eq:Monge of the paper) exists, and the following estimates hold
\begin{itemize}
    \item[(i)] $\lim\limits_{x \to x^0 } \lambda_{min}( \nabla^2 g(x)) < +\infty, \quad \text{for $x^0  \in \partial \Delta \backslash \{0,e_1,\dotso,e_d\}$} $;
    \item[(ii)] $\sup_{x\in\Delta } \nabla g(x)^{\top} (\nabla^2g(x))^{-1} \nabla g(x)<\infty $. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $p \in [2, \infty)$, we have that
	\begin{align*}
		\mathbb{E}^{1/p} \Bigl [ \fint_{B(0, \lambda)} |K \ast \xi(z') - K \ast \xi(0)|^p dy \Bigr ] \lesssim \lambda^{\frac12}
	\end{align*}
	where $\xi$ is the space-time white noise in one spatial dimension.

	In particular, it follows that for any compact set $\mathfrak{K}$ and any $\psi \in \mcB^r$ satisfying $\int \psi = 0$, we have that
	\begin{align*}
		\mathbb{E}^{1/p} [ \| K \ast \xi \ast \psi^\eps \|_{L^p(\mathfrak{K})}^p] \lesssim \eps^{1/2}.
	\end{align*}

