[Proposition prop:results:energyBound of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper). 


Then, with $R_q$ as in (equation eq:results:fPartitionFunction of the paper), we have
\begin{equation}
   \mathbb{H}_\kappa^* :=  \inf_{\nu\in \mathcal{Q}_{\kappa, d}} \mathbb{H}_\kappa(\nu) \geq - \log R_q,

\end{equation} and $\mathbb H_\kappa$ is lower semicontinuous on $\mathcal{Q}_{\kappa, d}$. If $(U, W)$ additionally satisfy Assumption (as:results:strongCoercivity of the paper), then for all $M \in \ensuremath{\mathbb{R}}$ we have
    \begin{equation}
            \mathcal{R}(M):=\{\nu \in {\mathcal{M}_{\kappa, d}}: \mathbb{H}_\kappa(\nu) \leq M\} \subset \mathcal{Q}_{\kappa, d},

    \end{equation}
and $\mathcal{R}(M)$ is compact in the weak topology. Moreover there exists $C_{q,M} \in (0, \infty)$ such that
     \begin{equation}
        \sup_{\nu \in \mathcal{R}(M)}\bigg\{  \int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} |\mathbf{x}|^2 \nu(d\mathbf{x}) \bigg\} \leq C_{q, M}.

    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem LM53 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that the Borel right process $X$ satisifes (AC) and (H3'), and that $X$ is transient.  Let $B\in \mathscr{B}^n(E)$ be a nearly Borel set such that $p_B\in {\mathcal{F}}_\mathrm{e}$. Then there exists a unique measure $\nu_B\in \mathscr{M}$ such that ${\mathcal{F}}_\mathrm{e}\subset L^1(E,\nu_B)$ and
    \begin{equation}
        {\mathcal{E}}(g,p_B)=\int_E g(x)\nu_B(\mathrm{d} x),\quad \forall g\in {\mathcal{F}}_\mathrm{e}. 
    \end{equation}
    In particular, 
    \begin{equation}
        p_B(x)=\int_E u(x,y)\nu_B(\mathrm{d} y),\quad \forall x\in E,
    \end{equation}
    and $\nu_B$ is a finite measure concentrated on $\overline{B}$ with $\nu_B(\overline{B})={\mathcal{E}}(p_B,p_B)$.

[Theorem 26 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\Lambda$ be a compact subset of $\Delta_I$, for some non-empty $I\subset\{1,\ldots,d\}$, and let $k_t:\Lambda\to\N^d$ be Borel and satisfy

\begin{equation*}
\sup_{\lambda\in\Lambda}|k_t(\lambda)-t\lambda|_1=o(\sqrt t).
\end{equation*}

Let $g$ be a transition reward and assume

\begin{equation*}
\Ee_{\mathfrak a}\left[L_1^2+|Y_1|_1^2+(R_1^*(g))^2\right]<\infty.
\end{equation*}

Let $a_g=\Ee_{\mathfrak a}[R_1(g)]$ and $\bar g=a_g/\ell$. Let

\begin{equation*}
W=(W_Y,W_L,W_R)
\end{equation*}

be a centered Brownian motion in $\R^{d+2}$ with covariance matrix equal to the covariance matrix of $(Y_1,L_1,R_1(g))$ under $\Pp_{\mathfrak a}$. For $\lambda\in\Lambda$, define

\begin{equation*}
\zeta_I(\lambda)=
\min_{r\in I}\left\{-\frac{W_{Y,r}(\kappa(\lambda))}{m_r}\right\}.
\end{equation*}

Then, in $\ell^\infty(\Lambda)$,

\begin{equation*}
\left(
\frac{\mathfrak N(k_t(\lambda))-t\kappa(\lambda)}{\sqrt t}
\right)_{\lambda\in\Lambda}
\xrightarrow[t\to\infty]{d}
\left(\zeta_I(\lambda)\right)_{\lambda\in\Lambda},
\end{equation*}

\begin{equation*}
\left(
\frac{N(k_t(\lambda))-t\ell\kappa(\lambda)}{\sqrt t}
\right)_{\lambda\in\Lambda}
\xrightarrow[t\to\infty]{d}
\left(W_L(\kappa(\lambda))+\ell\zeta_I(\lambda)\right)_{\lambda\in\Lambda},
\end{equation*}

and

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(\lambda))-t a_g\kappa(\lambda)}{\sqrt t}
\right)_{\lambda\in\Lambda}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa(\lambda))+a_g\zeta_I(\lambda)\right)_{\lambda\in\Lambda}.
\end{equation*}

Moreover, the random-count centered reward satisfies

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(\lambda))-\bar g N(k_t(\lambda))}{\sqrt t}
\right)_{\lambda\in\Lambda}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa(\lambda))-\bar g W_L(\kappa(\lambda))\right)_{\lambda\in\Lambda}.
\end{equation*}

The last limit is Gaussian for every cell $\Delta_I$.

