[Prop TP2-forests-partition-function-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Assume that ${\mathbf{w}}$ is $d$-arithmetic and that the sequence ${\mathbf{W}}=(w_0,w_d,w_{2d,\dots})$ is log-concave.
	Then, the arrays $(F^s, s\in\{0,\dots,d-1\})$, are TP2, that is we have:
	\begin{align}
	F^s_{n,k}\,F^s_{n',k'}
	\geq F^s_{n,k'}\,F^s_{n',k}.
	&&\begin{cases}
		0\leq {n}<{n'},\quad  0\leq{k}<{k'}, & s\in\{1,\dots,d-1\}\\
		1\leq {n}<{n'},\quad  1\leq{k}<{k'}, & s=1.
	\end{cases}
	\end{align}

[Corollary 11 (First two descent moments) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] Let $n,m\geq 1$, let $\pi\sim\nu_{n,m}^{(p)}$, and let $D_n=\des(\pi)$. Put $\dd=2p-1$. Then
\begin{equation}

\E[D_n]
=
\frac{n-1}{2}
+
\dd\left(
 m-\frac{n+1}{2}
 -\frac{n+1}{m^n}S_n(m)
\right).
\end{equation}
Moreover,
\begin{align}

\E[D_n(D_n+1)]
&=
\frac{n(n+1)}{4}-\frac{m}{2}
+\frac{(n+1)mS_n(m)-(n+2)S_{n+1}(m)}{m^n} \notag\\
&
+\dd\left(
 nm-\frac{n(n+1)}{2}
 -\frac{n(n+1)}{m^n}S_n(m)
\right) \notag\\
&
+\dd^2\left(
 m^2-\left(n+\frac12\right)m+\frac{n(n+1)}{4}\right. \notag\\
&\qquad\left.
 +\frac{(n^2-1)mS_n(m)-n(n+2)S_{n+1}(m)}{m^n}
\right).
\end{align}

[Proposition 142 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any tuple of compact sets $\amsmathbb{K}_h\subset \amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$ indexed by $h \in [H]$, there exists a $\N$-independent sequence of positive constants $(C_n)_{n \geq 1}$ depending on these compacts and the constants in the assumptions, such that, for any $n \in \amsmathbb{Z}_{> 0}$, $h_1,\ldots,h_n \in [H]$ and $(z_1,\ldots,z_n) \in \prod_{i = 1}^{n} \amsmathbb{K}_{h_i}$ we have
\begin{equation}

 \E\Bigg[\bigg| \prod_{i=1}^n \Delta G_{h_i}(z_i) \bigg|\Bigg] \leq C_n.
\end{equation}

