[Theorem 8 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function. Assume that $W\in C^{1}[0,T)\cap C[0,T]$ satisfies $W\left(0\right)=1, W\left(T\right)=0, W>0 \ on\ [0,T)$ and $W^{\prime}\in L^{2}(0,T)$. Then for any $0<f\in \ell^{\infty}\left(V\right)$, 
    \begin{equation*}
    \begin{aligned}
        \Gamma^{\psi}\left(P_T f\right)&\leq\psi^{\prime}\left(1\right)\left(1+2K\int_{0}^{T}W\left(s\right)^2ds\right)\frac{\Delta P_T f}{P_T f}\\
        &+\frac{n}{2}\left(\int_{0}^{T}W^\prime\left(s\right)^2ds+K^2\int_{0}^{T}W\left(s\right)^2ds+K\right).
    \end{aligned} 
    \end{equation*}

