	\bigg\}
	\le \frac{\SMAX_N(\RomIII)^2\BUCKETS\delta}{M}\]
where $\SMAX_N(\RomIII)$ is a random variable satisfying the bound
	\[\P\Big(\SMAX_N(\RomIII) \ge \log N\Big)
	\le \exp
	\bigg(
	-\frac{(\log N)^2}{L^{O(1)}}
	\bigg)
	\,.\]
The same bound holds with $\bar{D}^{\frozen,\RomIII}$ in place of
$\bar{D}^{\RomIII}$.
\begin{proof}
Recall that we can rewrite \eqref{e:drift.error.III} as
	\[
	\frac{\Delta\bar{D}^\RomIII(q_d)}
		{[q_d p'(q_d)]^{1/2}}
	= \frac{(\delta_d)^{1/2}}{|B|^{1/2}}
	\bigg(
	\sum_{a\in B}
	\frac{\bmeta^a(q_{d+1})}{|B|^{1/2}},
		\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)
	\equiv
	\frac{(\delta_d)^{1/2}}{|B|^{1/2}}
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)\,.
	\]
If we define the random variable
	\[
	\SMAX_N(\RomIII)
	\equiv\max\bigg\{
	\bigg|\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)\bigg|
	: 
	0\le d\le \dmax-1,
	B\in \mathcal{B}(q_d)
	\bigg\}\,,
	\]
then we have the quenched second moment bound
	\[
	\frac{\bE[\Delta\bar{D}^{\RomIII}(q_d)^2]}{q_d p'(q_d)}
	\le \frac{\delta_d}{M}
	\sum_{B\in\mathcal{B}(q_d)}
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)^2
	\le \frac{\SMAX_N(\RomIII)^2\BUCKETS\delta}{M}\,.
	\]
The vector $\bar{\bx}(q_d)$ is measurable with respect to $\cG(q_d)$; and it follows from Lemmas~\ref{l:bar.x.subgaus} and \ref{l:sg.norm.bound} that
	\beq
	\P\bigg(\frac{\|\bar{\bx}(q_d)\|^2}{N} \ge L^{O(1)}\bigg)
	\le \frac{1}{2^N}
	\eeq
provided we take the $L^{O(1)}$ large enough. Conditional on $\cG(q_d)$, the vector $\bmeta^B(q_{d+1})$ is distributed as a standard gaussian in $\R^N$. Therefore,
	\begin{align*}
	&\P\Big(
	\SMAX_N(\RomIII)\ge \log N
	\Big)
	\le \P\bigg(
	\bigg|\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)\bigg|
	\ge\log N
	\textup{ for any }
	0\le d\le \dmax-1,
	B\in\mathcal{B}(q_d)
	\bigg) \\ 
	&\qquad \le \dmax\BUCKETS
	\bigg\{ \frac{1}{2^N}
	+ \exp
	\bigg(
	-\frac{(\log N)^2}{L^{O(1)}}
	\bigg) \bigg\}
	\le \exp
	\bigg(
	-\frac{(\log N)^2}{L^{O(1)}}
	\bigg)
	\end{align*}
where the $1/2^N$ in the second line comes from \eqref{e:III.norm.bound}, and the final simplification uses Assumption~\ref{a:params}. This proves the claim for $\bar{D}^{\RomIII}$, and the claim for
$\bar{D}^{\frozen,\RomIII}$ follows by using \eqref{e:barD.vs.plus}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

