[Prop geographic ineq slicing map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] \begin{enumerate}
		\item
	Let $n\in \mathbb N$
	and let $u\in \widetilde{\mathcal{W}}_n$ be such that $\underline w:=F_n(u)\neq (e,\ldots, e)$. Then,
	\begin{equation}

		d_{\mathrm{LP}}(L[u],L[\underline w])\leqslantd_{\mathrm{TV}}(L[u],L[\underline w]) \leqslant h\Big(\frac{|\underline w|}{n}\Big).
	\end{equation}
	\item
	Let $k\in \mathbb N$ and let $\underline u:=(u^{1},u^ 2,\ldots, u^k)\in \widetilde{\mathcal{W}}^k_n$ be such that $\underline w^i:=F_n(u^i)\neq (e,\ldots, e)$ for all $i$. Then,
	\begin{equation}

		d_{\mathrm{LP}}(L[\underline u],L[\underline v])\leqslant \frac 1k\sum_{i=1}^k\Big(h\Big(\frac{k|\underline w^i|}{|\underline v|}\Big)+h\Big(\frac{|\underline w^i|}{n}\Big)\Big),
	\end{equation}
	where $\underline v\in \mathcal W^{kr}$ is the concatenation of the lists $\underline w^1,\ldots,\underline w^k$. 
\end{enumerate}

