body:
[Lemma lem:bernstein_current of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let $\bar W = W - \E^\mu[W]$ and
$\bar Q = Q - \E^\mu[Q]$.
Let $k^\ast_{\max}$ be the positive root of
$k(\|\bar W\|_{L^\infty(\mu)} + k\|\bar Q\|_{L^\infty(\mu)}) = \lambda_\mathrm{gap}$,
\begin{align}
k^\ast_{\max}
=
\begin{cases}
\dfrac{-\|\bar W\|_{L^\infty(\mu)} + \sqrt{\|\bar W\|_{L^\infty(\mu)}^2 + 4\lambda_\mathrm{gap}\|\bar Q\|_{L^\infty(\mu)}}}{2\|\bar Q\|_{L^\infty(\mu)}}
& \|\bar Q\|_{L^\infty(\mu)} > 0, 
\\[6pt]
\dfrac{\lambda_\mathrm{gap}}{\|\bar W\|_{L^\infty(\mu)}}
& \|\bar Q\|_{L^\infty(\mu)} = 0,
\end{cases}
\end{align}
and define
\begin{align}
c_{J,2} \equiv \frac{1}{k^\ast_{\max}},
\qquad
\tilde\sigma_{J,2}^2 \equiv 2\E^\mu[Q]
+ \frac{2}{\lambda_\mathrm{gap}}
  \left(\sqrt{\mathrm{Var}_\mu(W)} + k^\ast_{\max}\sqrt{\mathrm{Var}_\mu(Q)}\right)^2.
\end{align}
Then for all $k \in [0, k^\ast_{\max})$,
\begin{align}
\Lambda^J(k) - k\E^\mu[W]
\leq
\frac{\tilde\sigma_{J,2}^2 k^2}{2(1 - c_{J,2}k)}.

\end{align}

