[Prop link-with-compositions-new-2 of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Under the assumptions of Proposition (prop:link-with-compositions-new-1 of the paper), we have for $n\geq 0$ the identity $\PFtrees{\mathbf{w}} {nd+1}=\PFComp{{\mathbf{w}},{\mathbf{b}}}{nd}$, and for $T\in\trees[d]_{nd+1}$ if we write $c(T)=\underline{n}_1 \cdots  \underline{n}_i$ and $\varphi(T)=(T^{[1]},\dots,T^{[i]})$, then
	\begin{align}
	\SimpGen{{\mathbf{w}}}{nd+1}(T)=\PComp{{\mathbf{w}},{\mathbf{b}}}{n-1}\bigl(c(T)\bigr)\cdot\left(\SimpGen{{\mathbf{w}}}{n_1}\bigl(T^{[1]}\bigr)\cdots \SimpGen{{\mathbf{w}}}{n_i}\bigl(T^{[i]}\bigr)\right).
	\end{align}

[Prop 12 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] (cf.\ Theorem 5.1 of \cite{BFS})
Let $p\ge 4$ 
and let $f$ be a local $L^{p'}(\mu_{u_0})$ function on $\mathcal{X}_N = \R^N$
for some $p'>p$, depending only on $\eta_{\La_{\ell_0}} = 
(\eta(x))_{x\in \La_{\ell_0}}$, such that 
$\tilde f(u_0) = E^{\mu_{u_0}}[f]=0$ and $\tilde f'(u_0)=0$.  Then,
there exists a constant $C= C(u_0,\ell_0)$ (which is uniform in $u_0: |u_0|\le K$
for any $K>0$)
such that for $\ell\geq\ell_0$ we have
\begin{align}  
\Big\| E^{\mu_{u_0}}\big[f| \eta^{(\ell)}\big] 
 - \frac12\Big\{(\eta^{(\ell)}-u_0)^2- \frac{{\rm var} (u_0) }{2\ell +1}\Big\} 
\tilde f''(u_0)
\Big\|_{L^p(\mu_{u_0})} 
\leq \ \frac{C\|f\|_{L^{p'}(\mu_{u_0})}}{\ell^{3/2}},
\end{align}
where ${\rm var} (u_0)$ is defined below \eqref{eq:3.2-A}.
On the other hand, when only $\tilde f(u_0)=0$ is known, we have
\begin{align}  
&\Big\| E^{\mu_{u_0}}[f| \eta^{(\ell)}]  - (\eta^{(\ell)} - u_0)\tilde f'(u_0)  
\Big\|_{L^p(\mu_{u_0})} \ \leq \ \frac{C\|f\|_{L^{p'}(\mu_{u_0})}}{\ell}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 55 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For any $\delta>0$ and $n\in\N$,
there exists a constant $\g{c}{sle,n}=\g{c}{sle,n}(\delta)\in (0,\infty)$ such that
\begin{align*}
  \g{c}{sle,n}\alpha\leq \inf_{\substack{x,y\in F\\d(x,y)\geq \delta}}E_{x}[1-e^{-\alpha \sigma_{x,y}}]\wedge \inf_{\substack{z,w\in F_n\\d(z,w)\geq \delta}}E_{z}^n[1-e^{-\alpha \sigma^n_{z,w}}],\quad \alpha\in (0,\alpha_n).
\end{align*} 
Here, $\sigma_{x,y}$ and $\sigma^n_{z,w}$ are the commute time of $X$ between $x$ and $y$, 
and that of $X^n$ between $z$ and $w$ (recall its definition from \Cref{resis}, respectively).
Moreover, $\g{c}{sle,n}$ is given by
\begin{align*}
  \g{c}{sle,n}=\int_{0}^{T}(Ae^{-Bs}-1)^2e^{-\alpha_n s}ds.
\end{align*}
The definitions of $A,\;B,$ and $T$ are given below at \eqref{abtdef}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:convergence2 of the paper)}  hold with 
   $\bar p\geq \max\{2,\eta/8+1\}(\varepsilon+2)(\eta+1)(\eta+2)/{\varepsilon}\color{black}$
   where $\varepsilon\in(0,1)$.
	 Then,
	\begin{align*}
		&\int_Z E\big|\gamma\big( x_s^{i, N,n},\mu_s^{x, N,n}, z\big)-(\widehat{\Gamma})_{tam}^{\displaystyle n}\big(\kappa_{n}(s),s,x_{\kappa_{n}(s)}^{i,N,n},\mu_{\kappa_{n}(s)}^{x,N,n},z\big)\big|^2\nu(d z)\leq Kn^{-1-\frac{2}{\varepsilon+2}}
	\end{align*}
	for any $s\in[0,T]$ and $i\in\{1,\ldots,N\}$	where $K>0$ is a constant independent of $N$ and $n$.

