[Corollary 3 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Let~$\{T_k\}_{k\ge0}$ have the law of $\{\frac12|B_k|^2\}_{k\ge0}$ for~$B$ denoting a standard two-dimen\-sional Brownian motion. Let~$\{Z_{T_k}\}_{k\ge0}$  be a sequence of random Borel measures on~$[0,1]$ coupled with~$\{T_k\}_{k\ge0}$ so that \eqref{E:1.21a} holds as stated. Then
\begin{equation}

\ZZ(\textd x)\laweq \sum_{k\ge1}1_{ [b^{-k-1},b^{-k})}(x)\, b^{-2k} Z_{T_k}\bigl(b^k\textd x\bigr). 
\end{equation}
A.e.\ sample of~$\ZZ$ is diffuse. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 41 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume that $I_s-q_{\zerod}$ is invertible. The coefficients of $\psi=(e_0-q)^{(-1)}$ are determined recursively by

\begin{equation*}
\psi_{\zerod}=(I_s-q_{\zerod})^{-1}
\end{equation*}

and, for $k\neq\zerod$,

\begin{equation*}
\psi_k=(I_s-q_{\zerod})^{-1}
\sum_{0_d<\ell\leqd k}q_{\ell}\psi_{k-\ell}.
\end{equation*}

Consequently, if two kernels coincide on all coefficients $\ell\leqd k$, then their potentials coincide at $k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theo:intro of arXiv:2605.21265, 'The non-Hermitian minor process'] Consider the complex Ginibre minor process $X^{(xN)}$, and fix any $x,y\in (0,1]$ with $x\le y$. Let $f,g$ be smooth functions supported in the open disks\footnote{Here $\mathbf{D}_x:=\{z\in\mathbf{C}:|z|\le \sqrt{x}\}$.} $\mathbf{D}_x$, $\mathbf{D}_y$, respectively. Then, the linear statistics $L^{(xN)}(f), L^{(yN)}(g)$ converge jointly to centered Gaussian random variables $L(x,f), L(y,g)$, with covariance
\begin{equation}
\mathbf{E} L(x,f) L(y,g)= -\frac{1}{\pi^2} \int_{\mathbf{D}_x} \!\!\mathrm{d}^2 z\int_{\mathbf{D}_y}\!\!\mathrm{d}^2 w\,\, \overline{\partial_z f(z)}\partial_w g(w) \partial_z\partial_{\overline{w}} \log K\big((x,z),(y,w)\big),

\end{equation}
where $K$ is given by\footnote{Later in (equation eq:def_K of the paper) we extend the definition of $K$ to general $x,y\in(0,1]$.}
\begin{equation}
K\big((x,z),(y,w)\big):=|z-w|^2+|x-y|\left(1-\frac{|w|^2}{y}\right), \qquad z\in \mathbf{D}_x, \; w\in \mathbf{D}_y.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 34 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] Suppose $G$ has $\alpha$-stretched-exponential growth for some $\alpha\in(0,1)$ and $\operatorname{WSM}(C)$ holds for RFIM $\mu_G$ for some $C>0$. Then for any fixed $\delta\in(0,1)$, with $\mathbb{P}_h$-probability at least $1-\delta$, we have the following inequality for all functions $\varphi:\{-1,+1\}^V\to\mathbb{R}$:
    \begin{equation}
\operatorname{Var}_{\mu_G}(\varphi)\leq K\delta^{-1/q}|V|^\kappa\mathcal{E}_{\mu_G}(\varphi,\varphi)^{1/p}\cdot\operatorname{osc}(\varphi)^{2/q},        
    \end{equation}
    where the constants $K,\kappa>0$ and $p,q\geq 1,1/p+1/q=1$ all depend on $C,C_\alpha,\alpha$ and $\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:kernelholojs of arXiv:2411.04238, 'Holomorphic jump-diffusions'] The jump kernel $K$ is said to have holomorphic jump size if it is of the form
   \begin{align*}
    K(\cdot,A)=\lambda(\cdot)\int_E 1_{A\setminus\{0\}} ( j(\cdot,y))F(dy),
\end{align*}
where,
\begin{enumerate}
\item $F$ is a non-negative measure on a measurable space $E$;
    \item $\lambda\in \mathcal{O}(S)$ and its restriction to $S$ is positive real valued;
    \item $j:S\times E \rightarrow \mathbb{R}^d$ such that $ j=j_\varepsilon|_{S\times E}$ for some $\varepsilon>0$ and some measurable function $$j_\varepsilon:P^d_{R(S)+\varepsilon}(0)\times E \rightarrow \mathbb{C}^d$$ with $j_\varepsilon(\cdot,y)\in H(P^d_{R(S)+\varepsilon}(0),\mathbb C^d)$ for each $y \in E$.
\end{enumerate}

[Lemma 25 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] For every $N\ge1$,
\begin{equation}
\E\mathcal Z_N^{-2}\ge \E\bigl(\mathcal Z_N^{\mathrm{sph}}\bigr)^{-2}.
\end{equation}

