[Lemma lem:massive-massless-continuous-correction of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix a disk $U\Subset\mathbb R^2$ and $m_0>0$.  Write $\Delta_U$ for the
Dirichlet Laplacian on $U$ and set $L_0^U:=-(2\pi)^{-1}\Delta_U$.  Consider
a centered Gaussian field $Z_U$ with covariance operator
\begin{equation}
 \Cov(Z_U)=C_U^{(m_0)}
 :=(L_0^U)^{-1}-(L_0^U+m_0^2)^{-1}
 =m_0^2(L_0^U)^{-1}
   (L_0^U+m_0^2)^{-1}.

\end{equation}
Then $Z_U$ has a continuous version.  More precisely, for every $K\Subset U$
there is $C_{K,U,m_0}<\infty$ such that
\begin{equation}
 \mathbb E|Z_U(z)-Z_U(z')|^2
 \le C_{K,U,m_0}r^2
 \left(1+\log\frac1r\right),
 \qquad
 z,z'\in K,\quad 0<r:=|z-z'|\le\frac12.

\end{equation}

[Theorem 2 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85,Slep62})
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item $\mE(X_{i}^2)=\mE(Y_{i}^2)$
\item $\mE(X_{i}X_{l})\leq \mE(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
\mE(\min_{i} X_{i})\leq \mE(\min_i Y_{i}) \quad  \Longleftrightarrow \quad \mE(\max_{i} X_{i})\geq \mE(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Let $u$ be the solution of equation (\ref{3.1}) with initial value $f$. 
\begin{itemize}
  \item [(i)] Suppose that (H4) holds. If $\alpha > 0$, and for some $\lambda>0$ satisfying $\frac{\lambda^2}{2}<\alpha$, there exists $f\in L^1_{\lambda}$ such that
\begin{align}
  \sup_{t\geq 0}\mathbb{E} \Vert u(t)\Vert_{L^1_{\lambda}} <\infty ,
\end{align}
then there exists a unique invariant measure in $L^1_{\lambda}$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric $W_1$.
  \item [(ii)] Suppose that (H2) and (H4) hold. If $\alpha > \frac{L_{\sigma}^4}{8}$, and for some $\lambda>0$ satisfying $\frac{\lambda^2}{8}<\alpha - \frac{L_{\sigma}^4}{8}$ and $\frac{\lambda^2}{4}<\alpha$, there exists $f\in L^2_{\lambda}$ such that
\begin{align}
  \sup_{t\geq 0}\mathbb{E} [\Vert u(t)\Vert^2_{L^2_{\lambda}}] <\infty ,
\end{align}
then there exists a unique invariant measure in $L^2_{\lambda}$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric  $W_2$.
\end{itemize}

