[Theorem 19 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $M\sim CR(X,Y)$. 
	\begin{itemize}
		\item[($i$)] With $\gamma \in\mathbb{R}$ and $H_Y(\gamma) = \mathbb{E}e^{i\gamma Y}$,
		\begin{align}
			\mathbb{E}& \exp\left( i\gamma \int_0^t M(s)  \dif s\right ) \nonumber\\
			&= \sum_{n\ge0} \mathbb{E}  \Biggl[\conv_{k=1}^n \Big(  e^{i\gamma \sum_{h=k}^nY_h\sbullet}F(\sbullet)\Big)\ast 1 (t)- \conv_{k=1}^{n} \Big( e^{i\gamma \sum_{h=k}^nY_h\sbullet}F(\sbullet) \Big)\ast F \ast 1 (t) \Biggr]  \\
			& = \sum_{n\ge0} \mathbb{E} \Bigg[ \mathds{1}(X> t-S_n ) \prod_{k=1}^n H_Y\big(\gamma (t-S_k)\big)\Bigg] . 
		\end{align}
		\item[($ii$)] If $X$ is absolutely continuous with density $f$ and $\mu>0$,
		\begin{align}
		\int_0^t e^{-\mu t} \mathbb{E} \exp\Bigg( i\gamma\bigg(t\sum_{k=1}^{N(t)} Y_k &- \int_0^t M(s)  \dif s\bigg) \Bigg) \dif t = \frac{1-\mathcal{L}f(\mu)}{\mu}\sum_{n\ge0}\mathbb{E} \prod_{k=1}^n \mathcal{L}f\bigg(\mu+i\gamma \sum_{h=k}^n Y_k\bigg). 
	\end{align}
	\end{itemize}

[Lem 3 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] Suppose that $Q(r)$ is twice continuously differentiable.
Then $J_{t}(\mu)$ converges to\textcolor{black}{{} the functional
\begin{equation}
J:{\cal P}_{c}(M)\rightarrow[0,\infty),\ J(\mu)\triangleq-\frac{1}{4}Q''(0)\int_{M\times M}d_{{\rm eu}}(z,w)^{2}\mu(dz)\mu(dw)
\end{equation}
}as $t\rightarrow\infty$ uniformly for all $\mu\in{\cal P}(K)$ with
$K$ being any given compact subset of $M$.

[Theorem thm: SSC JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] [State Space Collapse for JSQ]

    For JSQ under in heavily overloaded condition (ass:heavy_overload of the paper), the following inequality holds:
    \begin{align*}
        \mathbb{E}[\|\mathbf{q}_{\perp}\|^{p}]^{1/p} &\leq \max\{ E_{n,\lambda,\mu}^{(1)} p^2, E_{n,\lambda,\mu}^{(2)} p \} \leq E_{n,\lambda,\mu} p^2 \end{align*}
    Where $\mathbf{q}_{\perp} = \mathbf{q} - \frac{1}{n}(\sum_{i=1}^n q_{i})\boldsymbol{1}$.
    $E_{n,\lambda,\mu}^{(i)}, i=1,2$ and $E_{n,\lambda,\mu}$ are constants independent of $p,\gamma$, their closed forms are given in (equation eq: p-moment for q_perp, state space collapse of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

