we have for~$a,b\in A$ and~$w=a_1a_2\cdots a_n$,
\begin{eqnarray*}
\hat{\mu}(abw)&=&v_aM_{a,b}M_{b,a_1}M_{a_1,a_2}\cdots M_{a_{n-1},a_n}\\
&=&\frac{(v_aM_{a,b})(v_bM_{b,a_1}\cdots)}{v_b}=\frac{\hat{\mu}(ab)\hat{\mu}(bw)}{\hat{\mu(b)}}.
\end{eqnarray*}
Conversely, set~$v_a=\hat{\mu}(a)$ and 
\begin{displaymath}
M_{a,b}=\frac{\hat{\mu}(ab)}{\hat{\mu}(a)}.
\end{displaymath}
Then
\begin{eqnarray*}
\hat{\mu}(a_1\cdots a_n)
