{"artifact_digest":"sha256:4822d7f2cda64ac6e34ea479a60ef12ee8db67bb1ff779eb00f1e4d2c2bfdd95","artifact_path":"objects/sha256/48/4822d7f2cda64ac6e34ea479a60ef12ee8db67bb1ff779eb00f1e4d2c2bfdd95.md","bundle_digest":"sha256:eb18fa18d774709c2015f01d87ee0ca275c2d09f2bbc70a839e4b6cb4cceb5d3","bundle_entry_key":"2605-08844-theorem-30-uniqueness-thm-equation-statem","bundle_id":"population.tex-extract-s3_028","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-20260907/bundle_s3_028.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2605-08844-proposition-30-uniqueness-thm-equation-statem","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Notice that by the structure of equation \eqref{uniqueness_thm_equation_statement}, if any solution exists, it has to be bounded.\newline
