[Thm 5 (Perturbation formula) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Restricted to the event $\{X_t^{i,n}\neq \dagger\}$, for $t>0$, the conditional law of $X_t^{i,n}$ given $\sigma(\cup_{s>0}\mathcal{{G}}_{s}^{i,n})$ has a random density $p^{i,n}(t,x)$, which is supported on $[\hat{A}_t^{i,n},\infty)$ and  jointly continuous in $x
    \geq \hat{A}_t^{i,n}$ and $t>0$. This density can be expressed as
	\begin{equation}
	p^{i,n}(t,x)=\hat{p}^{i,n}\Bigl(t\,,\int_{\hat{A}^{i,n}_t}^x \frac{1}{\sigma(t,y)}\dy  \Bigr)\frac{1}{\sigma(t,x)},\quad \text{for all}\quad x \geq \hat{A}_t^{i,n},\,t> 0,
	\end{equation}
	where $\hat{p}^{i,n}$ is supported on $[0,\infty)$ and satisfies the implicit Volterra relation
	\begin{align}
	\hat{p}^{i,n}(t,x) & =\int_0^\infty N(x,t,y,0)\hspace{1pt} \di \hat{\mu}^{i}_0(y) +\int_{0}^{t}\int_{0}^{\infty}\partial_{y}N(x,t; y ,r)\tilde{b}^{i,n}(r, y)\hat{p}^{i,n}(r,y)\dy \dr \nonumber\\
	& \qquad\; -\int_{0}^{t}N(x,t;0,r)\gamma(r,\hat{{C}}_{r}^{i,n})\sigma(r,\hat{{A}}_{r}^{i,n})^2p^{i,n}(r,\hat{A}^{i,n}_r)\dr
	\end{align}
     with $\hat{\mu}_0^{i}=\mathrm{Law}(X_0^i) \circ (\int_{a_0}^\cdot \frac{1}{\sigma(0,y)}\dy)^{-1}$.    Furthermore, for any $T>0$, we have
\begin{equation}
	\hat{p}^{i,n}(t,x) \leq \frac{C_1}{\sqrt{t}} \exp\Bigl( -c_1x^{2}\Bigr),\quad \text{for all}\quad x\in[0,\infty), \,t\in(0,T],
	\end{equation}
for some constants $c_1,C_1>0$, and, in turn, there are constants $c_2,C_2>0$ such that
	\begin{equation}
		p^{i,n}(t,x) \leq \frac{C_2 }{\sqrt{t}} \exp\Bigl( -c_2(x-\hat{A}^{i,n}_t)^2 \Bigr),\quad \text{for all}\quad x\in[\hat{A}^{i,n}_t,\infty), \,t\in(0,T],
	\end{equation}
	These constants can be chosen independently of $i=1,\ldots,n$ and $n\geq 1$, and we note that \eqref{eq:lamperti_aronson}--\eqref{eq:particle_aronson} confirm that the perturbation formula \eqref{eq:density_rep-1} is well-defined.

[Proposition prop:bound-partition-functions of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Let $Z^n_{A', B'} = \sum_{\gamma \in \ensuremath{\mathcal P}_{\mathbb Z^2}(A', B')}w^n(\gamma)$. Then, for all $k \leq \frac{a}{1-\delta}\log_2\log L$, uniformly over all $A', B' \in \ensuremath{\mathcal R}_k$, we have
		\begin{equation*}
			Z^n_{A', B'} \leq z_ke^{{\ensuremath{\mathscr G}}^n_\mu(\ell_{A', B'}, \theta_{A', B'}})
		\end{equation*}
		where $z_1 = e^{c(\log L)^2}$, $z_k = z_1^{2^{k-1}}$.

