body:
[Theorem thm:jordan of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For the Jordan-based estimator $\widehat{\sigma}_{J}$, there exist constants $c, C, \delta > 0$ such that for all $n \ge 1$, any $v \in [n]$ and any $S \in [1, \delta n/v]$, the upper tail satisfies
    \begin{equation}
        \frac{c}{S} 
        \ \leq\ \mathbb{P} \big( \widehat{\sigma}_{J}(v) \geq S v\big) 
        \ \leq\ \frac{C}{S}.
    \end{equation}
    The upper bound holds for all $S \geq 1$.

    Moreover, there exist constants $c', c'', C', C'', \delta' > 0$ such that for all $n \ge 1$, any vertex $v \in [n/2]$, and any $S \in [1, \min(\sqrt{v},\delta'v)]$, the lower tail satisfies
    \begin{equation}
        c''\exp(-C''S) 
        \ \leq\ \mathbb{P} \Big( \widehat{\sigma}_{J}(v) \leq \frac{1}{S} v\Big) 
        \ \leq\ C'\exp(-c'S).
    \end{equation}
    The upper bound holds for all $v \in [n]$ and $S \in [1, \sqrt{v}]$; the lower bound holds for all $v\in[n/2]$ and $S\in[1,\delta'v]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem5-2 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)} and $b\in (0,1)$.  
	\begin{itemize}
		\item[(i)] Fix $\delta\in (0,1)$. Then for all $k\delta \geq K_0, I= [(k-1)\delta, k\delta)$ and $x>K_0$, 
		\begin{align}
			\frac{e^{\lambda x^b}}{\ell(x)x^a }T_3 \lesssim_{\beta } \frac{e^{\lambda (k\delta)^b}}{\ell(k\delta)(k\delta)^a} .
		\end{align}
		\item[(ii)] For $I=[p, q)$, it holds that 
		\begin{align}
			\lim_{x\to+\infty} \frac{e^{\lambda x^b}}{\ell(x)x^a }T_3  =0.
		\end{align}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:covariance of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( \mu \) be a measure on \( (X, \mathcal{C}(X)) \) such that \( X^* \subseteq L^2(\mu) \).
    The \emph{covariance} of \( \mu \) is the bilinear form
    \begin{equation} 
        R_\mu : X^* \times X^* \to \mathbb{R}, \qquad
        (f,g) \mapsto \int_X (f(x) - a_\mu(f))(g(x) - a_\mu(g)) \, \mu(dx).
    \end{equation}

[Lemma 18 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] The following statements hold.

  \smallskip
  \noindent
  \textup{(i) (\textsf{Explicit Malliavin derivatives})}  For $\eps>0$,
  \begin{align}
    D_{j,y}B_i^\eps(t)
    &=\dl_{ij}\bigl(\Phi^\eps(t-y)-\Phi^\eps(-y)\bigr),

      \\
    D_{j,y}\xi_i^\eps(x)
    &=\dl_{ij}\phi^\eps(x-y).
  \end{align}
  Consequently,
  \begin{align}
    D_{j,y}H_{x}^{\al,\eps}(\ga)
    =
    \begin{cases}
      \Phi^\eps(x+\ga_{j+1}-y)
      -\Phi^\eps(x+\ga_j-y),&0\leq j\leq n-1,\\[3pt]
      \al\bigl(\Phi^\eps(x+\ga_n-y)-\Phi^\eps(-y)\bigr),&j=n.
    \end{cases}
  \end{align}

  \smallskip
  \noindent
  \textup{(ii) (\textsf{Variance bound})}  Put
  $v_\eps(x,\ga)=\Var(H_{x}^{\al,\eps}(\ga)) =  \| D H_{x}^{\al,\eps}(\ga) \|_\fH^2  $.  Then
  \begin{align}
    -\al^2|x|+(1+\al^2)\ga_n
    -\eps(n+\al^2)\int_\R |r|(\phi\ast\phi)(r)\,dr
    \leq v_\eps(x,\ga)
    \leq \al^2|x|+(1+\al^2)\ga_n.
  \end{align}
  In particular, for every compact $K\subset\R$,
  \[
    \sup_{x\in K,\,0\leq\eps<1}v_\eps(x,\ga)
    \leq C_K(1+\ga_n).
  \]

  \smallskip
  \noindent
  \textup{(iii) (\textsf{Uniform free-energy moments and removal of the path
  truncation})}  For every compact $K\subset\R$, $p<\infty$, and
  $\lambda\in[0,\be)$,
  \begin{align}
    \sup_{\substack{x\in K,\ 1\leq R\leq\infty\\0\leq\eps<1}}
    \bigl\|\log Z_{x,R}^{\al,\be,\eps}(\lambda)\bigr\|_{L^p(\Omega)}
    <\infty.
  \end{align}
  For fixed $x$ and $\eps\in[0,1)$,
  \begin{align}
    \log Z_{x,R}^{\al,\be,\eps}(\lambda)
    \xrightarrow[R\to\infty]{L^p(\Omega)}
    \log Z_{x,\infty}^{\al,\be,\eps}(\lambda).
  \end{align}

  \smallskip
  \noindent
  \textup{(iv) (\textsf{Removal of the mollification})}  For every fixed $x$ and
  every $p<\infty$,
  \begin{align}
    \log Z_{x}^{\al,\be,\eps}
    \xrightarrow[\eps\downarrow0]{L^p(\Omega)}
    \log Z_{x}^{\al,\be}.
  \end{align}

[Proposition 23 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] Let $p\wedge q$ and $|p-q|_{\mathbb H}$ be defined by \eqref{min-sup} and \eqref{p-q} respectively. The function 
\[
p\wedge q,\quad p,q\in\mathbb{H}_{+}
\]
is positive definite on $\mathbb{H}_{+}$ and the function
\begin{equation}
\frac{1}{2}\left(|p|_{\mathbb{H}}+|q|_{\mathbb{H}}-|p-q|_{\mathbb{H}}\right),\quad p,q\in\mathbb{H}
\end{equation}
is positive definite on $\mathbb{H}$.

[Prop entropy_exp of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mu$ be a measure on $[0,\infty)^{n}$ such that $\int x_i\mu(dx)=\int x_1\mu(dx)$ for all $i=1,\dots,n$.
    Then \begin{align*}
        \mathsf{Ent}(\mu\mid \mathsf{Leb}_{\IR^{n}})=\mathsf{Ent}(\mu\mid\gamma^{\otimes_{i=1}^n} )-n\int x_1\mu(dx).
    \end{align*}

[Lemma lem:measurability of arXiv:2609.01576, '\normalfont Pointwise Majorization for sub-Weibull and Mixed Tail Processes with Applicati'] The map $(t,r)\mapsto\mu(B_d(t,r))$ is Borel measurable on
$T\times[0,\infty)$. Consequently, $v$ and
$\Phi_{\mu,d}^{(\alpha)}$ are $[0,\infty]$-valued Borel functions.
Moreover, for every $r_0,s_0>0$, the maps
\begin{align*}
t\longmapsto J_{r_0}\rbr{\Phi_{\mu,d}^{(\alpha)}(t)},\ 
t\longmapsto J_{s_0}\rbr{v(t)}
\end{align*}
