[Theorem 12 (Theorem 2.1 of \cite{zhang2016central}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose $\{Z_{n}\}$ converges to the constant $\theta^{*}$ almost surely, and that Assumptions~\eqref{gen_assump_dist_2} and \eqref{gen_assump_dist_3} are satisfied. Suppose $\rho=1/2$, and that either
\begin{equation}
\sum_{i=0}^{n-1}\delta_{i}=o\left(\sqrt{n/\log n}\right) \text{ almost surely,}
\end{equation}
or that 
\begin{equation}
\sum_{i=0}^{n-1}\frac{\left|\left|\delta_{i}\right|\right|_{2}}{\sqrt{i+1}}=o\left(\sqrt{\log n}\right) \text{ almost surely}.
\end{equation}
Then
\begin{equation}
\frac{\sqrt{n}}{(\log n)^{\nu-1/2}}\left(Z_{n}-\theta^{*}\right)\convd N(0,\Sigma),
\end{equation}
where, letting $\Gamma$ be the matrix mentioned in Assumption~\eqref{gen_assump_dist_3}, we set 
\begin{equation}
\Sigma=\lim_{n\rightarrow\infty}\frac{1}{(\log n)^{2\nu-1}}\int_{0}^{\log n}\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\Gamma\left[\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\right]^{t}du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cut_bij of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $n\geq1$ and $x\in\mathbb Z$.
    There is a function $\phi_x$ that bijectively sends the set $\mathcal B^{(n)}_x$ of bridges from $0$ to $x$ onto
    \begin{align*}
        \tilde{\mathcal B}^{(n)}_x:=\mathcal B_{-\mathbb{1}_{\{n\textrm{ is odd}\}}}^{(n)}\cap\Big\{\big(w_t:0\leq t\leq n\big):\exists t,w_t=\left\lfloor x/2\right\rfloor\Big\}
    \end{align*}
    of all bridges starting at $0$, ending at $-1$ when $n$ is odd or at $0$ when $n$ is even, and passing through $\left\lfloor x/2\right\rfloor$.

