[Thm 160 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Under the assumptions of Theorem~\ref{thm:IAMP-main}\ref{i:IAMP-main-chaotic}, for fixed $L,\epsilon,\delta$, we have 
  \beq
     \lim_{\eta\downarrow 0}
     \lim_{\upp\uparrow 1}
     \lim_{\linit\to\infty}
    \plim_{N\to\infty} \frac{(\hat{\by}^{\ubl},\tilde{\by}^{\ubl})}{N}
     =
     0\,.\eeq
(We note that the order of parameters is consistent with \eqref{eq:eta-delta-eps}.) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 ({\cite{bhatt2022Prismsa}*{Lemma 4.22}}) of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(A\to A'\) be a flat morphism of commutative rings, and let \(K^\bullet\) be a cosimplicial object of \(\mcalD(A)\). Assume that there exists an integer \(c\) such that \(K^n\in\mcalD^{\geq c}(A)\) for every integer \(n\geq0\). Then the canonical morphism
  \begin{equation}

    A'\otimes_A^L\Tot(K^\bullet)\to\Tot(A'\otimes_A^LK^\bullet)
  \end{equation}
  is an equivalence in \(\mcalD(A')\).

[Theorem 5 of arXiv:2607.23401, 'Limit Theorems for the Pitman-Yor Frequency Spectrum'] We have, for   $0<\lambda < 1$ and $\ell=0,1,\ldots$, the limit 
   \be
  \lim_{n\to\infty} \PP\big(S_n^\lambda(\alpha,\theta) =\ell\big)
= \frac{ 
(c(\lambda))^\ell\Gamma(\theta)
(\Gamma(1-\alpha))^{\theta/\alpha+\ell}
}
{\Gamma(\theta/\alpha) \ell!}
\int_0^\infty x^{\theta/\alpha+\ell-1}e^{-x\lambda^{-\alpha}}f_{Y_x(\alpha,\lambda)+ H_\ell(\lambda)}(1)\rmd x.
 \ee
  The right-hand side of \eqref{f28} 
defines a proper probability mass function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem teo:ejtriple of arXiv:2410.23509, 'Dynkin Games for L\'evy Processes'] Under the assumptions (equation eq:inf_density of the paper) and (equation eq:sup_density of the paper)
for the densities of the respective infimum and supremum of the process $X$, and
for the linear payoffs $G_1(x)=x-\delta,$ $G_2(x)=x+\delta,$
for some $\delta>0$,
the DG of Definition (def:dg of the paper) has optimal thresholds given by
\begin{align}
x_I&=-\delta-E_I+F_I\frac{E_Se^{r_Iu}-E_IG_S}{e^{(r_I+r_S)u}-G_IG_S},\\
x_S&=\delta+E_S+F_S\frac{-E_Ie^{r_Su}+E_SG_I}{e^{(r_I+r_S)u}-G_IG_S},
\end{align}
where $u$ is the unique solution of  
\begin{equation}
    u-2\delta-E_I-E_S
=\frac{-E_IF_Se^{r_Su}-E_SF_Ie^{r_Iu}+2E_SF_SG_I}{e^{(r_I+r_S)u}-G_IG_S}.

\end{equation}

Moreover, the value function is given by
 \begin{equation}
V(x)=
\begin{cases}
x+\delta, & \text{if $x\leq x_I$},\\    
A_I e^{-r_I(x-x_S)}+A_S e^{r_S(x-x_I)},& \text{if $x_I\leq x\leq x_S$},\\
x-\delta, & \text{if $x\geq x_S$,}
\end{cases}
\end{equation}
with
\begin{equation}
A_I=\frac{-E_Ie^{r_Su}+E_SG_I}{e^{(r_I+r_S)u}-G_IG_S},
\quad
 A_S=\frac{E_Se^{r_Iu}-E_IG_S}{e^{(r_I+r_S)u}-G_IG_S}.
\end{equation}

