[Cor main of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $\rho_0,\rho_1 \in {\mathcal P}(\mathbb{R}^n)$ with $W_2(\rho_0,\rho_1)<\infty$. Let  $\bar m^\varepsilon_0, \bar m^\varepsilon_1\in {\mathcal P}({\mathcal X_{\omega,\varepsilon}})$ with $W_2(\bar m^\varepsilon_0, \rho_0) \to 0$, $W_2(\bar m^\varepsilon_1, \rho_1) \to 0$.


     Let $(m^\varepsilon, J^\varepsilon)$ be  minimizers of the discrete action on $[0,1]$ with $m^\varepsilon_0 = \bar m^\varepsilon_0$, $m^\varepsilon_1 = \bar m^\varepsilon_1$. Then the curves have convergent subsequences $m^\varepsilon \stackrel{*}{\rightharpoonup} \rho$, $\iota J^\varepsilon \stackrel{*}{\rightharpoonup} j$, and
    \begin{equation*}
        C_\omega(\rho_0,\rho_1) = A_\omega(\rho,j) = \lim_{\varepsilon \to 0} \mathcal{A}_{\omega,\varepsilon}(m^\varepsilon, J^\varepsilon).
    \end{equation*}

    Here the homogenized Wasserstein distance $C_\omega$ can be characterized as either the minimal action
    \begin{equation*}
        C_\omega(\rho_0,\rho_1)= \min_{(\rho,j)}A_\omega(\rho,j)
    \end{equation*}
    or as the minimum Monge-Kantorovich cost
    \begin{equation*}
    C_\omega(\rho_0,\rho_1)= \min_{\gamma\in \mathrm{Cpl}(\rho_0,\rho_1)}\langle \gamma, f_\omega(y-x)\rangle,
    \end{equation*}
     where $\mathrm{Cpl}(\rho_0,\rho_1)$ is the set of all couplings of $\rho_0$ and $\rho_1$, i.e. all measures $\gamma\in {\mathcal P}(\mathbb{R}^n\times\mathbb{R}^n)$ with marginals $\rho_0$ and $\rho_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Suppose that $A :\rK \to H$ is a bounded linear operator. Then, $A$ is Hilbert--Schmidt if and only if there exists a (strongly) $\tilde{\kappa}$-measurable function
  $\Phi : \mO \to H$ with
\begin{equation}
\int_{\mO} \normm{\Phi(x)}_H^2\,\tilde{\kappa}(\d x)< \infty,
\end{equation}
such that
\begin{equation}
Af = \int_{\mO} f(x)\, \Phi(x)\, \tilde{\kappa}(\d x),
\;\; \forall\, f \in \rK,
\end{equation}
where the integral is a Bochner integral in $H$. In this case,
\begin{equation}
\normm{A}_{\HS(\rK, H)}^2
= \int_{\mO} \normm{\Phi(x)}_H^2\, \tilde{\kappa}(\d x),
\end{equation}
where $\normm{A}_{\HS(\rK,H)}^2$ is the Hilbert-Schmidt norm defined by  
  \begin{equation}
    \normm{A}_{\HS(\rK,H)}^2
    = \sum_{n=1}^\infty \normm{A \tilde{e}_n}_H^2
  \end{equation}
  for any complete orthonormal system $(\tilde{e}_n)_{n=1}^\infty$ in $\rK=L^2(\mO, \tilde{\kappa})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Suppose Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new} hold. Let $K_\eps$ satisfy Assumption \ref{Ass:kernel}. Let $h,T>0$ such that $T/h\in{\mathbb N}$, $\eps,\delta \in (0,1)$ and $ \hX_{jh}^{h,\eps,\delta}$ be defined in Equation \eqref{eq_Xhepsdelta} for $j\in \{0,\dots,\frac Th\}$. Recall $\lambda$ from Equation \eqref{Eq_lambda}.
        Let $f$ be three times differentiable with derivatives of polynomial growth, then it holds for any $p>1$ that
        \begin{align}
            \Bigl|\E\bigl[ f(Y_T)\bigr]-\E\bigl[f\bigl(\hX_T^{h,\eps,\delta}\bigr)\bigr]\Bigr|\lesssim h + \eps h^{-1} e^{\frac {\eps^2}{\lambda}} + \delta^{\frac1p}.
        \end{align}
         Here the hidden constant explodes as $p\rightarrow 1$ or $p \rightarrow \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

