[Corollary cor:hereditary-endpoint of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Suppose the seed chart is prime-energy stable with exponents $(a,\mu)$.
Then, for every fixed $t\in\mathbb Z_{\geq0}$,
\begin{equation}
 |\mathcal R(h,d+1+t)|\geq h^{2a-\mu+t-o(1)}.
\end{equation}
Thus the deficit $d-(2a-\mu)$ from the ambient exponent is invariant throughout
this prime-energy-stable suspension tower.  In particular, the endpoint
identity $2a-\mu=d$ implies
\begin{equation}
 |\mathcal R(h,d+1+t)|=h^{d+t+o(1)}
\end{equation}
for every fixed $t\in\mathbb Z_{\geq0}$.

[Theorem thm:iovw-rw-hitting of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] {IOVW20}}]
Consider the 2\emph{D} effective random walk ${\ensuremath{\mathsf S}}(\cdot)$. Let $\tau_G$ be the hitting time of a set $G\subset \mathbb Z^2$. There exists a constant $C>0$ such that, for every sequence $\delta_\ell$ that goes to~$0$ arbitrarily slowly as $\ell\to\infty$, and for all $u,v\in \mathbb Z$ such that $u/\sqrt{\ell},v/\sqrt{\ell}\in (0,\delta_\ell)$,    
\begin{equation*}
\hat{\ensuremath{\mathbf P}}_{(0,u)}(\tau_{(\ell,v)}<\tau_{\mathbb H_-}<\infty\mid {\mathsf{Bdd}}) \sim C \frac{h^+(u)h^-(v)}{\ell^{3/2}}\,, 
\end{equation*}
where $h^\pm$ are positive harmonic (in particular, asymptotically linear) functions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 112 (Derivatives of the null-acoustic geometry scalars on $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] }$]  
Let $\ubar$ be the ingoing eikonal function that solves \eqref{E:INGOINGEIKONALEQUATIONINITIALVALUEPROBLEM} and let $\ingoingmu,\,  \ReciprocalLunitAppliedtoTimeFunction=  1/ \Lunit \ubar, \, \ReciprocaluLunitAppliedtoTimeFunction = 1/ \uLunit u, \, \MagnitueofinnerproductofnewLandnewuL$ be the null-acoustic geometry scalar functions defined in \eqref{E:NULLACOUSTICSCALARS}. 

Then, the following sharp estimates and identities hold, where we use Notation\,\ref{N:RESTRICTIONOFUBARONDATASURFACE}: 
\begin{subequations} 
\begin{align} 
		0.87 \blowupdelta^{-1} \le \min_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \mr \ReciprocalLunitAppliedtoTimeFunction & \le \max_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \mr \ReciprocalLunitAppliedtoTimeFunction \le 1.16 \blowupdelta^{-1},  \\
		1.72 \blowupdelta \le \min_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \mr  \ingoingmu & \le \max_{\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}} \mr \ingoingmu \le  2.33 \blowupdelta^{-1}, 
\end{align} 
\end{subequations}
\begin{subequations}
\begin{align}
\mr \ReciprocaluLunitAppliedtoTimeFunction, \,  \mr \MagnitueofinnerproductofnewLandnewuL\big|_{\twoargmumuxtorus{0}{0}} & = 0  \\
\newuL \mr \ReciprocaluLunitAppliedtoTimeFunction, \, \newuL \mr\MagnitueofinnerproductofnewLandnewuL \big|_{\twoargmumuxtorus{0}{0}} & = 0  
\end{align}
\end{subequations}Moreover, the following estimates hold for $M = 1,2$:
  \begin{align}
\left\| \mr \ingoingmu,\, \mr \ReciprocalLunitAppliedtoTimeFunction, \, \mr \ReciprocaluLunitAppliedtoTimeFunction, \, \mr \MagnitueofinnerproductofnewLandnewuL\right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)} & \le C,  \\
 \left\| \newuL^M \mr \ingoingmu,\,  \newuL^M  \mr\ReciprocalLunitAppliedtoTimeFunction, \, \newuL^M \mr \ReciprocaluLunitAppliedtoTimeFunction, \, \newuL^M \mr \MagnitueofinnerproductofnewLandnewuL\right\|_{C_{\textnormal{data}}^{0,1} \left(\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}\right)} & \le C. 
\end{align}

[Lemma 66 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let $(\delta_n)_{n\in \mathbb{N}}\subset (0,1)$ such that $\delta_n \to 0$ as $n \to \infty$. Assume that the assumption \ref{ass-A3} holds. Suppose that $\bu_n \to \bu$ in $L^2([0,T] \times \domO)$. Then, we have
\begin{equation}
\lim_{n \to \infty} \Vert \widetilde{\bG}^{\delta_n,n}(\cdot,\cdot;\bu_n) - \bg(\cdot,\cdot;\bu) \Vert_{L^2([0,T] \times \domO;\mathrm{Y})}^2
=0.
\end{equation}

