[Lemma 35 of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Let $I\subseteq[d]$ be nonempty and fix $x\in\mathbb{T}^d$ such that $x[i]=x[j]$ for all $i,j\in I$.
Then for all $t\ge 0$,
\begin{equation}

\bigl\|\mathcal{L}_x(X_t[I])-\pi_{|I|}\bigr\|_{\mathrm{TV}}
\;\ge\;
\mathbb{P}\Bigl(\exists i\neq j\in I:\;H_i(t)=H_j(t)\Bigr).
\end{equation}

[Corollary cor:f with a root at 0 of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\tilde{f}_n(z)=z^{m_n}f_n(z)$ for a sequence of $f_n\in\mathcal{LP}$ satisfying  Assumption (assump:main assumption of the paper). If $\{p_n\}_{n\geq 1}$ is a sequence of real-rooted polynomials indexed by their degree such that $\llbracket p_n\rrbracket\Rightarrow\mu$ and $\frac{m_n}{n}\rightarrow t\in [0,1)$, then \begin{equation}
		\llbracket \tilde{f}_{n}(\partial_z)p_{n}\rrbracket\Rightarrow\mathcal{D}_{1-t}\left(\mu\boxplus\mu_{c,\Sigma} \right)^{\boxplus\frac{1}{1-t}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(f \in \CF_{N - 1}\), we have the estimate
  \begin{equation}
    \begin{split}
      &\ \|R^{\phi(\mathbf{Y}), f}\|_{(N - |f|)\gamma}\\
      \lesssim\ & \|R^{\sharp, f}\|_{N\gamma} |t - s|^{|f|\gamma}
      + \frac{|\CT_{N - 1}|^{N - |f| - 1}}{(N - |f|)!} C_{[s, t]}^f
        \|R^{\mathbf{Y}, \mathbf{1}}\|_{N\gamma}^{N - |f|} |t - s|^{(N - 1)(N - |f|)\gamma}\\
      & + \frac{|\CT_{N - 1}|^{N - |f| - 1}}{(N - |f|)!} C_{[s, t]}^f \sum_{\tau \in \CT^+_{N - 1}}
        (\|\partial^\tau_X Y\|_{\infty; [s, t]}\|\<\mathbf{X}, \tau\>\|_{|\tau|\gamma} |t - s|^{(|\tau| - 1)\gamma})^{(N - |f|)}.
    \end{split}
  \end{equation}
  where for any \(I \subseteq \mathbb{R}\), we have denoted
  \begin{equation}
    C_{I}^f := \sup_{\substack{u < v \in I\\ \lambda \in [0, 1]}}
    \|D^{N - |f|} [\partial^f_X \phi(\lambda \mathbf{Y}_u + (1 - \lambda) \mathbf{Y}_v)]\|.
  \end{equation}

