[Lemma lem:budget of arXiv:2608.07842, 'Resolution of a Conjecture on Shifted R\'enyi Divergence'] Let $D$ be a scalar $N(a,\tau^2)$ variable with $2\tau^2<w^2$. Then
$$\mathbb{E}\exp(D^2/w^2)=\Big(1-\frac{2\tau^2}{w^2}\Big)^{-1/2}\exp\Big(\frac{a^2}{w^2-2\tau^2}\Big),$$
so $\mathbb{E}\exp(D^2/w^2)=2$ iff
\begin{equation}
a^2=(w^2-2\tau^2)\Big(\log 2+{\tfrac12}\log\Big(1-\frac{2\tau^2}{w^2}\Big)\Big).
\end{equation}

[Theorem thm:codiff of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), for any $s, t \in \mathbb{R}$:
\begin{equation}

\tau\!\bigl(X^{(n)}_H(s),\, X^{(n)}_H(t)\bigr)
= \int_\mathbb{R}
\bigl[|f_n(s,u)|^\alpha + |f_n(t,u)|^\alpha
- |f_n(s,u) - f_n(t,u)|^\alpha\bigr]\,du.
\end{equation}

[Lem 6 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $X\sim \Hyp(n_1,n,m)$ with $\mathbb EX=\frac{n_1m}{n}\geq 10$. There exists absolute constants $C,c$ such that for all $\delta<1/2$,
		\begin{equation} 
			\mathbb P(|X-\mathbb E X|\geq (\mathbb EX)^{1/2+\delta})\leq C\exp(-c(\mathbb EX)^{2\delta}).
		\end{equation}

[Definition 6 (\cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] For a graph $F$ with $\chi(F)=r+1\geq 3$, define
	\begin{equation*}
		a(F):=\min\{|I|: I\subseteq V(F)\text{ is independent and }\chi(F-I)\le r\}.
	\end{equation*}
	If $a(F)=1$, the graph $F$ is called singleton-boundary.

[Theorem 7 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Under the conditions above,
\begin{equation}
\Delta_R
=
\sum_{j=1}^{r}
w_j
\frac{\lambda_j-1}{\lambda_j}.

\end{equation}
Consequently, if
\(\mathcal{P}=\{j:\lambda_j>1\}\) and
\(\mathcal{N}=\{j:\lambda_j<1\}\), then
\(\Delta_R>0\) if and only if
\begin{equation}
\sum_{j\in\mathcal{P}}
w_j
\frac{\lambda_j-1}{\lambda_j}
>
\sum_{j\in\mathcal{N}}
w_j
\frac{1-\lambda_j}{\lambda_j}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] Let
\begin{align*}
  \eta_t^\epsilon = O_{\nu^\epsilon}^{T}(1)
\end{align*}
if a family of random variables $\{\eta_t^\epsilon\}_{0\leq \epsilon<1,t\geq 0}$ and family of probability measures $\{\nu_\epsilon\}_{0\leq \epsilon <1}$ on $\mathcal{F}$ satisfies
\begin{align*}
  \lim_{K\to \infty}\sup_{0\leq t\leq T}\sup_{0<\epsilon <r}\nu^\epsilon(|\eta_t^\epsilon|>K)=0
\end{align*}
for some $r>0$.
Furthermore, let us write $\eta^\epsilon=O_{\nu^\epsilon}^{T}(\epsilon^i)$ if
\begin{align*}
  \frac{\eta^\epsilon}{\epsilon^i}=O_{\nu^\epsilon}^{T}(1)
\end{align*}
for $i=0,1,2,\cdots$.

[Lemma lem:DMSboundA of arXiv:2608.29657, 'Hypocoercivity of Tempered Bouncy Particle Samplers for Heavy-Tailed Targets'] Let~(ass:wpi of the paper), (ass:sigmabounds of the paper) and~(ass:curvature of the paper) hold.
    For all $f \in C^1_c({\mathbb R}^d \times {\mathbb R}^d)$,
    \begin{equation}|\langle {\mathcal A} f, {\mathcal L} f \rangle_{L^2(\mu_\sigma )}| \leq \|f- \Pi f\|_{L^2(\mu_\sigma)}^2.\end{equation}

[Proposition 14 (Macroscopic mass) of arXiv:2608.04799, '2608.04799'] There is \(M=M(\lambda)<\infty\) such that
\begin{equation}
  \sup_{n\ge n_\lambda}n^{-2/3}
  \E\sum_{C:\,|C|\ge n^{2/3}}|C|\le M.
\end{equation}
Consequently, for every \(B\ge1\),
\begin{equation}
  \sup_{n\ge n_\lambda}\Prob(X_{n,1}>B)\le M/B.
\end{equation}

