[Definition 129 of arXiv:2601.16377, '2601.16377'] We introduce
\begin{equation}

s^{\circ}_h(z):=  \frac{q_h^-(z)}{\sqrt{(z-\alpha_{h})(z-\beta_{h})}}= (z-\hat a'_h)^{\mathbbm{1}_{\amsmathbb{S}_h}(\hat{a}'_{h})} \cdot (z-\hat b'_h)^{\mathbbm{1}_{\amsmathbb{S}_h}(\hat{b}'_{h})}\cdot s_h(z).
\end{equation}

[Definition def:regular-time-weight of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$.  A \emph{regular time weight of order $\alpha$} is
\begin{equation*}
 w(t)=t^\alpha e^{\phi(t)},
 \qquad \phi\in W^{1,1}(0,T),
 \qquad \phi(T)=0.
\end{equation*}
The normalization only fixes $w(T)=T^\alpha$ and entails no loss of generality.
The ratio $w(t)/t^\alpha=e^{\phi(t)}$ has a positive continuous extension to
$[0,T]$.  For $0\leq r_0<r_1\leq T$ and $I=(r_0,r_1)$, define its intrinsic
logarithmic oscillation by
\begin{equation*}
 \operatorname{osc}_{\alpha,I}(w)
 :=\max_{t\in\overline I}\log\frac{w(t)}{t^\alpha}
   -\min_{t\in\overline I}\log\frac{w(t)}{t^\alpha},
\end{equation*}
where the quotient at $t=0$, when needed, is understood through this extension.
We write $\operatorname{osc}_\alpha(w)$ on the full interval.  For $\kappa\geq0$,
define on the full interval
\begin{equation*}
 w_\kappa(t):=w(t)e^{-2\kappa(T-t)},\qquad 0<t<T,
\end{equation*}
and use its restriction on subintervals.  For every measurable field $h$,
\begin{equation}
 \left(\min_{t\in\overline I}\frac{w_\kappa(t)}{t^\alpha}\right)^{1/2}
 \left\lVert h\right\rVert_{\alpha;I}
 \leq \left\lVert h\right\rVert_{w_\kappa;I}
 \leq
 \left(\max_{t\in\overline I}\frac{w_\kappa(t)}{t^\alpha}\right)^{1/2}
 \left\lVert h\right\rVert_{\alpha;I}.

\end{equation}
In particular, for every fixed $\kappa$, these norms define the same underlying
space, and $w_\kappa\leq w$.  On the full interval,
\begin{equation}
 e^{-\operatorname{osc}_\alpha(w)/2-\kappa T}\left\lVert h\right\rVert_\alpha
 \leq \left\lVert h\right\rVert_{w_\kappa}
 \leq e^{\operatorname{osc}_\alpha(w)/2}\left\lVert h\right\rVert_\alpha.

\end{equation}

[Definition mixingdef of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $t_N$ be a non-decreasing sequence of positive integers. A Markov chain $([N], P_N)$  is said to be \emph{Short-to-Long Mixing} at time \(t_N\) if its $n$-step transition probability $p_n(x,y)$ satisfies the following two conditions:

\begin{enumerate}[leftmargin=*,label=(B\arabic*)]
    \item  \textbf{(Short-time average mixing)}  
    There exists a constant $\gamma \ge 1$ and $N_0 > 0$ such that for all $N \ge N_0$ and all $x, y \in [N]$,
    \begin{equation}
        \frac{1}{t_N} \sum_{n=1}^{t_N} p_n(x, y) \le \frac{\gamma}{N}.
    \end{equation}

    \item  \textbf{(Long-time uniform mixing)} 
    There exists  $\delta \in (0, 0.1)$, such that for all $n \ge t_N$ and all $x, y \in [N]$,
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{N} \right| \le \frac{\delta}{N}.
    \end{equation}
\end{enumerate}
The additional assumption that  $\delta = \delta_N \to 0$  may be imposed   when necessary.

[Theorem S5T of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Fix $p \in (0, \infty)$, $\sigma = \sqrt{p(1+p)}$, $K \in \mathbb{N} \cup \{\infty\}$, $\Sigma = \llbracket 1, K + 1 \rrbracket$ and $\Lambda = (\alpha,\beta) \subseteq \mathbb{R}$ to be any non-empty open interval. We further suppose that we have sequences $d_N \in (0,\infty)$, $\hat{A}_N, \hat{B}_N \in \mathbb{Z}$ with $\hat{A}_N \leq \hat{B}_N$, $K_N \in \Sigma \cup \{\infty\}$ and $\Sigma$-indexed geometric line ensembles $\mathfrak{L}^N = \{L^N_i\}_{i \in \Sigma}$ on $\mathbb{Z}$ that satisfy the following conditions:
\begin{itemize}
\item $d_N \rightarrow \infty$, $\hat{A}_N/d_N \rightarrow \alpha$, $\hat{B}_N/d_N \rightarrow \beta$, $K_N \rightarrow K+1$ as $N \rightarrow \infty$;
\item for each $t \in \Lambda$ and $i \in \llbracket 1, K \rrbracket$ the random variables $\sigma^{-1} d_N^{-1/2}  \left( L_i^N(\lfloor t d_N \rfloor) - ptd_N \right)$ are tight;
\item the restriction $\{L_i^N(s): i \in \llbracket 1, K_N \rrbracket$ and $s \in \llbracket \hat{A}_N, \hat{B}_N\rrbracket \}$, satisfies the interlacing Gibbs property from Definition (DefSGP of the paper).
\end{itemize}
Then, the sequence of line ensembles $\mathcal{L}^N = \{\mathcal{L}_i^N\}_{i = 1}^{K} \in  C(\llbracket 1, K \rrbracket \times \Lambda)$, defined through 
$\mathcal{L}_i^N(t) = \sigma^{-1} d_N^{-1/2}  \left( L_i^N(td_N) - ptd_N \right),$
is tight. Moreover, any subsequential limit satisfies the partial Brownian Gibbs property from [DM21].

[Lem 53 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For all $\alpha\in (0,\alpha_n),\;x,y\in F,\;x_n,y_n\in F_n$, and $f\in\BL^{\kappa}(M)$,
it holds that
\begin{align*}
  |G^{\alpha}_xf(y)-G^{\alpha,n}_{x_n}f(y_n)|\lesssim \g{c}{itkill}\Bigl\{ \|f\|_{K_n}(d(x,x_n)+d(y,y_n))+\|f\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n) \Bigr\}.
\end{align*}

[Lemma 16 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] }
Assume that $g$, defined in \eqref{g_defn}, is in $\mathcal{C}^{(1)}(\mathcal{S})$. Then, for $\omega(\nabla g;\cdot)$ as defined in \S\ref{subsec:notations_2}, $H_{n}$ as defined in \eqref{H_{n}_defn}, $E_{n}$ as defined in \eqref{E_{n}_defn}, $\mathcal{S}_{n}$ as defined in \eqref{S_{n}_defn} and $C=1/\sqrt{2}+1/2$, for each $n\geqslant N$: 
\begin{align}
\sup\left\{\left|H_{n}(x,y)-g(x,y)\right|:(x,y)\in\mathcal{S}\right\}\leqslant
\begin{cases}
& C\omega\left(\nabla g;\sqrt{\E\left[K_{n}^{-1}\right]}\right)\sqrt{\E\left[K_{n}^{-1}\right]},\\
& C\omega\left(\nabla g;\E\left[K_{n}^{-1}\right]\left(\E\left[K_{n}^{-1/2}\right]\right)^{-1}\right)\E\left[K_{n}^{-1/2}\right],
\end{cases}_H_{n}}\\
\sup\left\{\left|E_{n}\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)-g\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\right|:\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\in \mathcal{S}_{n}\right\}\leqslant
\begin{cases}
& C\omega\left(\nabla g;\sqrt{\E\left[K_{n}^{-1}\right]}\right)\sqrt{\E\left[K_{n}^{-1}\right]},\\
& C\omega\left(\nabla g;\E\left[K_{n}^{-1}\right]\left(\E\left[K_{n}^{-1/2}\right]\right)^{-1}\right)\E\left[K_{n}^{-1/2}\right].
\end{cases}_E_{n}}
\end{align}

