\int_{\Gamma_{i}(t_{0})}
f  (t_{1},...,t_{i})
\,dw^{ k_{i}}_{t_{i}}\cdot...\cdot dw^{ k_{1}}_{t_{1}}\Big)^{2}
$$
\begin{equation}

