[Theorem 3 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb{R})$. For fixed $L,t,s$ and a deterministic
bounded input sequence $(u_r)_r$, as $n\to\infty$,
\begin{equation}
  K_{\psi,n,\theta}^{(L)}(t,s)
  \xrightarrow{\mathbb{P}}
  K_{\psi,\theta}^{(L)}(t,s),

\end{equation}
where
\begin{equation}
\begin{aligned}
  K_{\psi,\theta}^{(L)}(t,s)
  &:=\mathbb{E}\!\left[\psi(g_t)\psi(g_s)\right], \\
  (g_t,g_s)
  &\sim\mathcal{N}\!\left(
    0,\Sigma_{\theta}^{(L)}(t,s)
  \right).
\end{aligned}

\end{equation}
The convergence is in probability with respect to the joint randomness
of $W_r$ and $W_{\rm in}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem15 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)), ((f0 of the paper)) and ((f1 of the paper)) 
  with some $\lambda>1$,
  and let $p\ge 2$ and $r\ge \max\{p,2\lambda\}$ be such that $p>n$ and
  \begin{equation} \label{15.1}
	p\ge n(\lambda-1)
  \end{equation}

  as well as
  \begin{equation} \label{15.01}
	r>2\lambda
	\qquad \mbox{if } n=2
  \end{equation}
  and
  \begin{equation} \label{15.02}
	\frac{np\lambda}{n+p-2} \le r < \frac{np}{n-2}
	\qquad \mbox{if } n\ge 3.
  \end{equation}
  Then there exist $b_1=b_1(p,r,a,h,f)>0, b_2=b_2(p,r,a,h,f)>0$, $\kappa_1=\kappa_1(p,f)>1$ and $\kappa_2=\kappa_2(p,h,f)>1$
  as well as $\Gamma_{10}=\Gamma_{10}(p,r,a,h,f)>0$
  and $\Gamma_{11}=\Gamma_{11}(p,r,a,h,f)>0$ such that whenever ((init of the paper)) and ((uut of the paper)) hold with some $T\in (0,T_{max}]$,
  the function defined by
  \begin{equation} \label{F}
	{\mathcal{F}}(t)
	:= \int_\Omega |\nabla v|^p
	+ b_1 \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	+ b_2 {\mathcal{F}}_1^\frac{p}{2}(t)

	\qquad t\in [0,T_{max}),
  \end{equation}
  with ${\mathcal{F}}_1$ taken from ((F1 of the paper)) satisfies
  \begin{equation} \label{15.2}
	{\mathcal{F}}'(t) + \Gamma_{10} {\mathcal{F}}(t)
	+ \Big\{ \Gamma_{10} - \Gamma_{11} {\mathcal{F}}^{\kappa_1}(t) \Big\} \cdot \int_\Omega |\nabla v|^{p-2} |D^2 v|^2
	\le \Gamma_{11} {\mathcal{F}}^{\kappa_2}(t)
	\qquad \mbox{for all } t\in (0,T).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Well-posedness of the SDE to transition path process) of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] Let \((\widehat{W}, \mathcal{F}_t^{\widehat{W}})\) be a standard Brownian motion in \(\mathbb{R}^d\), and let \(\widehat{N}\) be an independent Poisson random measure on \([0, \infty) \times (\mathbb{R}^d \setminus \{0\}) \times [0, \infty)\) with intensity measure \(m \times \nu \times m\). Both are defined on a probability space \((\widehat{\Omega}, \widehat{\mathcal{F}}, \mathbb{Q})\).  Let \(\xi : \widehat{\Omega} \to \bar{A}^c \cap (A + 1)\) be a random variable defined on the same probability space and independent of \(\widehat{W}\) and \(\widehat{N}\). Then, there exists a unique c\`{a}dl\`{a}g process \(Y_t : [0, \infty) \to \mathbb{R}^d\), adapted to the augmented filtration \(\widehat{\mathcal{F}}_t\), which satisfies the following equation \(\mathbb{Q}\)-almost surely:
    \begin{equation*}
        \begin{aligned}
            Y_t = &\ \xi + \int_0^{t \wedge \tau_B} K(Y_{s-}) \d s 
            + \int_0^{t \wedge (\tau_A \wedge \tau_B)} \sigma(Y_{s-}) \d \widehat{W}_s \\
            &\ + \int_0^{t \wedge (\tau_A \wedge \tau_B)} 
            \int_{[0, \infty) \times \{|r| < 1\}} 1_{[0, \lambda(Y_s, r)]} F(Y_{s-}, r) \widetilde{\widehat{N}}(\d v, \d r, \d s), \quad t \geq 0,
        \end{aligned}
    \end{equation*}
    where \(\tau_B = \inf\{t \geq 0 \mid Y_t \in \bar{B}\}\) and \(\tau_A = \inf\{t \geq 0 \mid Y_t \in \bar{A}\}\). Moreover, \(Y_t \notin \bar{A}\) for all \(t > 0\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 9 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] Let $0 \le x < y \le 1$. Then
        \begin{align*}
            \int_x^y\frac{y - t}{t^{\frac 3 2}}dt \ge \int_x^y\frac{t - x}{t^{\frac 3 2}}dt \ge \frac{(y-x)^2}{4y^{\frac 3 2}}.
        \end{align*}

