[Lemma lem:hypercoercivity of arXiv:2605.20697, 'Uniform-in-time propagation of chaos for \\ Second-Order Consensus-Based Optimization'] For \(\phi_{a,p}\), define the constants \(c_1(a,p)\) and \(c_2(a,p)\) by
\begin{equation}
    c_1(a,p) :=
    \begin{cases}
        \frac{a+1-\sqrt{(a-1)^2+(m/\gamma)^2}}{2}, & p=2,\\[1.2em]
        \min\!\left\{ a-2(p-1)\left(\frac{m}{p\gamma}\right)^{\frac p{p-1}}, \, 1-\frac1{2^{p-1}} \right\}, & p>2,
    \end{cases}
\end{equation}
and
\begin{equation}
    c_2(a,p) :=
    \begin{cases}
        \frac{a+1+\sqrt{(a-1)^2+(m/\gamma)^2}}{2}, & p=2,\\[1.2em]
        \max\!\left\{ a+2(p-1)\left(\frac{m}{p\gamma}\right)^{\frac p{p-1}}, \, 1+\frac1{2^{p-1}} \right\}, & p>2.
    \end{cases}
\end{equation}
If \(c_1(a,p)>0\), then
\begin{equation}
    c_1(a,p)(|x|^p+|v|^p) \leqslant \phi_{a,p}(x,v) \leqslant c_2(a,p)(|x|^p+|v|^p).
\end{equation}

For \(\psi_2\), define
\begin{equation}
    c_1^{(2)} := \frac{a_2+1-\sqrt{(a_2-1)^2+(5/\gamma)^2}}{2},
    \qquad
    c_2^{(2)} := \frac{a_2+1+\sqrt{(a_2-1)^2+(5/\gamma)^2}}{2}.
\end{equation}
If \(c_1^{(2)}>0\), then
\begin{equation}
    c_1^{(2)}(|x|^2+|v|^2) \leqslant \psi_2(x,v) \leqslant c_2^{(2)}(|x|^2+|v|^2).
\end{equation}
In particular, the quadratic admissibility condition \(\gamma^2>3m/2\) implies \(\gamma^2>7m/6\), which guarantees \(c_1^{(2)}>0\).

