[Theorem 7 (Mod-$\phi$ convergence for descending plane partitions) of arXiv:2608.14143, 'Mod-$\phi$ convergence for random variables with cyclotomic generating functions'] For each $N\in\N$ let $X_N$ be a random variable with rescaled moment generating function of the form \eqref{eq:mgfDPP}. Then the sequence of random variables $X_N/N^2$ converges mod-$\phi$ with parameter $N$, and normalization function and limiting function given by
	\begin{align*}
	\phi(z) &:= \int_0^1\log\Bigl(\frac{1-e^{zt^2}}{-zt^2}\Bigr) dt, \\
	\psi(z) &:= \exp\Bigl( \frac{1}{2}\log\Bigl(\frac{1-e^{z}}{-z}\Bigr) - \frac{z}{4} \Bigr) = \sqrt{\frac{e^z-1}{z}}\, e^{-z/4}.
	\end{align*}
	on $\mathscr{D}$ as in Theorem \ref{thm:modphi-mixed}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: stable Op nu of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] Suppose that the L\'{e}vy measure has the form (equation eq: stable Levy measure spectral measure of the paper). Let
\begin{equation*}
\begin{aligned}
&C_{++}=\int_{0}^{\frac{\pi}{2}}|\cos\theta\sin\theta|^{\frac{\alpha}{2}}\,\tau(\mathrm{d}\theta),\quad &C_{+-}=\int_{\frac{3\pi}{2}}^{2\pi}|\cos\theta\sin\theta|^{\frac{\alpha}{2}}\,\tau(\mathrm{d}\theta),\\
&C_{-+}=\int_{\frac{\pi}{2}}^{\pi}|\cos\theta\sin\theta|^{\frac{\alpha}{2}}\,\tau(\mathrm{d}\theta),\quad &C_{--}=\int_{\pi}^{\frac{3\pi}{2}}|\cos\theta\sin\theta|^{\frac{\alpha}{2}}\,\tau(\mathrm{d}\theta),
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
&D^{x}_{+}=\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}|\cos\theta|^{\alpha}\,\tau(\mathrm{d}\theta),\quad &D^{x}_{-}=\int_{\frac{\pi}{2}}^{\frac{3\pi}{2}}|\cos\theta|^{\alpha}\,\tau(\mathrm{d}\theta),\\
&D^{y}_{+}=\int_{0}^{\pi}|\sin\theta|^{\alpha}\,\tau(\mathrm{d}\theta),\quad &D^{y}_{-}=\int_{\pi}^{2\pi}|\sin\theta|^{\alpha}\,\tau(\mathrm{d}\theta).
\end{aligned}
\end{equation*}
Then we have that
\[\mathrm{Op}(\nu)=\left\|\begin{pmatrix}
C_{++}/\sqrt{D^{x}_{+}D^{y}_{+}} & \quad C_{+-}/\sqrt{D^{x}_{+}D^{y}_{-}}\\
C_{-+}/\sqrt{D^{x}_{-}D^{y}_{+}} & \quad C_{--}/\sqrt{D^{x}_{-}D^{y}_{-}}
\end{pmatrix}\right\|_2\]
with the convention that $0/0=0$, where $\|\cdot\|_2$ denotes the spectral norm.

