body:
[Theorem thm:linear-least-squares of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ ( \Omega, \mathcal F, {\mathbb P} ) $ be a probability space, let
$ \kappa \in (0,\infty) $,
$ m, d, M \in {\mathbb N} $,
$ \vartheta \in {\mathbb R}^d $,
let $ A \in {\mathbb R}^{ m \times d } $ have no zero columns,
let $ K \subseteq {\mathbb R}^m $ be compact,
let $ ( Y_{ n, r } )_{ (n,r) \in {\mathbb N}^2 } $ be $ K $-valued i.i.d.\ random variables with a bounded Lebesgue density,
let $ L \colon {\mathbb R}^d \times {\mathbb R}^m \to {\mathbb R} $ satisfy for all $\theta\in{\mathbb R}^d$, $y\in{\mathbb R}^m$ that
\bas{

\textcolor{magenta}{
  L( \theta, y )
  = | A \theta - y |^2
}
}
and
let $ F \colon {\mathbb R}^d \to {\mathbb R} $
satisfy for all $ \theta \in {\mathbb R}^d $ that
$
  F(\theta)
=
  {\mathbb E}[L(\theta,Y_{1,1})]
  - \inf_{\vartheta\in{\mathbb R}^d}{\mathbb E}[L(\vartheta,Y_{1,1})]
$.

Then there exists $ \eta \in (0,\infty) $
such that for every
$ \mathfrak{C} \in (0,\infty) $ there exists
$ c \in {\mathbb R} $ such that
for all $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
$ \varepsilon \in [0,1] $, all $ {\mathbb R}^d $-valued
stochastic processes $ ( w_n )_{ n \in {\mathbb N}_0 } $ and $ ( \theta_n )_{ n \in {\mathbb N}_0 } $,
and every $ ( 0, \mathfrak{C} ] $-valued decreasing $ ( \gamma_n )_{ n \in {\mathbb N} } $
with the property that for every
$ n \in {\mathbb N} $,
$ j \in {\mathbb N} \cap [ 1, n ] $,
$ i \in \{ 1, 2, \dots, d \} $
it holds that

\begin{equation}

\begin{gathered}

\textcolor{magenta}{
  w_0 = 0
}
  ,
  \qquad

\textcolor{magenta}{
  w_n^{(i)}
  = \beta w_{n-1}^{(i)}+(1-\beta)
  \bigl[
  \textstyle
    M^{ - 1 } \sum_{r=1}^M
    ( \nabla_{ \theta_i } L )( \theta_{ n - 1 }, Y_{ n, r } )

  \bigr]^2
}
  ,
\\
\textcolor{magenta}{
  \theta_0 = \vartheta
} ,
\qquad
\textcolor{magenta}{
  \theta_n^{(i)}

  =
  \theta_{n-1}^{(i)}
  -
  \gamma_n
  \bigl[
    \varepsilon + ( 1 - \beta^n )^{ - 1 / 2 } ( w_n^{ (i) } )^{ 1 / 2 }
  \bigr]^{ - 1 }
  \textstyle

    M^{ - 1 }
    \sum_{r=1}^M
    ( \nabla_{ \theta_i } L )( \theta_{ n - 1 }, Y_{ n, r } )
}

\end{gathered}
\end{equation}
and
\textcolor{magenta}{$
  \gamma_j
  \le  \mathfrak{C} \exp( \frac\eta2 \sum_{ k = j+1 }^{ n } \gamma_k )
   \gamma_n
$}
we have for every $ n \in{\mathbb N} $ that
\bas{
\textcolor{magenta}{
  {\mathbb E}\bigl[
    F(\theta_n)
    \1_{ \cap_{ j = 0 }^{ n - 1 } \{|\theta_j|\le\kappa\}}
  \bigr]
  \le
  \exp\bigl(
  \textstyle
    - \eta \sum_{ k = 2 }^n \gamma_k
  \bigr)
  \,

    \bigl(
      \gamma_1
      ( d \| A^\mathsf{T} A \| )^{ 1 / 2 }
      +
      | F( \theta_0 ) |^{ 1 / 2 }
    \bigr)^2

  + c \gamma_n
  + c (1-\beta)^2
}
  .
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 2 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space with a filtration $(\mathcal{F}_{t})_{t\in[0,\infty)}$.
A kinetic measure is a map $q$ from $\Omega$ to the space of nonnegative, locally finite measures on $\mathbb{T}^{d}\times(0,\infty)\times[0,T]$ that satisfies the property that the process
\begin{align*}
(\omega,t)\in \Omega\times[0,T]\to\int^t_0\int_{\mathbb{R}}\int_{\mathbb{T}^d}\phi(x,\xi)\mathrm{d}q(x,\xi,r)
\end{align*}
is $\mathcal{F}_t-$predictable, for every $\phi\in C^{\infty}_c(\mathbb{T}^d\times (0,\infty))$.

[Lemma lem:exact-martingale-decomposition-band-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Let \(d\in\mathfrak D_\xi\).  On the weak-convergence event \(\widetilde\nu_L\xrightarrow{\mathrm{w}}\widetilde\nu\), the post-bin limit \(F^{\mathrm{post}}_{\xi,d}\) exists, and
\begin{equation}
\int e^{i\phi_\xi(t)}\chi_{\xi,d}(t)\,d\widetilde\nu(t)
=
F^{(0)}_{\xi,d}
+
F^{\mathrm{pre}}_{\xi,d}
+
F^{\mathrm{post}}_{\xi,d}.
\end{equation}

[Definition 31 (First fundamental forms) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill

\begin{enumerate}
\item We define $g$, the first fundamental form of $\Sigma_t$ relative to $\gfour$, 
	to be the symmetric type $\binom{0}{2}$ tensorfield $\Sigmatproject \gfour$. Note that
	$g(Y,Z) = \gfour(Y,Z)$ for
	all pairs $(Y,Z)$ of $\Sigma_t$-tangent vectorfields.
	We define the corresponding inverse first fundamental form $g^{-1}$
	to be the symmetric type $\binom{2}{0}$ tensorfield that is $\gfour$-dual to $g$
	i.e., 
	$(g^{-1})^{\alpha \beta} 
	\eqdef 
	(\gfour^{-1})^{\alpha \widetilde{\alpha}} 
	(\gfour^{-1})^{\beta \widetilde{\beta}}
	g_{\widetilde{\alpha} \widetilde{\beta}}$.
	Note that the restriction of $g$ to $\Sigma_t$-tangent tensorfields is the Riemannian\footnote{It is Riemannian
	is because the $\gfour$-normal to $\Sigma_t$ is the $\gfour$-timelike vectorfield $\Transport$; see
	Lemma\,\ref{L:BASICPROPERTIESOFVECTORFIELDS}.} 
	metric on $\Sigma_t$ induced by $\gfour$. In particular, 
	relative to the Cartesian spatial coordinates, we have: 
	\begin{align} 
		g_{ij} 
		& = \gfour_{ij}
		= \Speed^{-2} \updelta_{ij},
	\end{align}
	where $\updelta_{ij}$ denotes the Kronecker delta,
	and to obtain the last equality in \eqref{E:CARTESIANCOMPONENTSOFFIRSTFUNDAMENTLAFORMOFSIGMAT}, 
	we have used \eqref{E:ACOUSTICALMETRIC}.
 \item We define $\gtorus$, the first fundamental form of the acoustic tori $\ell_{t,u}$ relative to $\gfour$, 
	to be the symmetric type $\binom{0}{2}$ tensorfield $\smoothtorusproject \gfour$. Note that
	$\gtorus(Y,Z) = \gfour(Y,Z)$ for
	all pairs $(Y,Z)$ of $\ell_{t,u}$-tangent vectorfields.
	Note that the restriction of $\gtorus$ to $\ell_{t,u}$-tangent tensorfields is the Riemannian\footnote{It is Riemannian
	is because $\ell_{t,u}$ is a sub-manifold of the spacelike hypersurface $\Sigma_t$.} 
	metric on $\ell_{t,u}$ induced by $\gfour$.
	We define the corresponding inverse first fundamental form $\gtorus^{-1}$
	to be the symmetric type $\binom{2}{0}$ tensorfield that is $\gfour$-dual to $\gtorus$
	i.e., 
	$(\gtorus^{-1})^{\alpha \beta} 
	\eqdef 
	(\gfour^{-1})^{\alpha \widetilde{\alpha}} 
	(\gfour^{-1})^{\beta \widetilde{\beta}}
	\gtorus_{\widetilde{\alpha} \widetilde{\beta}}$.
\end{enumerate}

[Theorem thm:ibpf of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] Let $h\inH_0^1~\cap~H^2$ and $F \in \exp(C^{\infty})$. Then we have the IbPFs
	\begin{align}
		\mathbb{E}_{\rho^a\mu^{\beta}}\left[ \partial_h F \right] + \mathbb{E}_{\rho^a\mu^{\beta}}\left[ F \, (h'',\cdot)_{L} \right] &= - \langle \!\langle F(\beta), \bar{h}_a \delta_0(\beta_a) \rangle \!\rangle\\
		\text{and}\quad\mathbb{E}_{\rho\mu^{\beta}}\left[ \partial_h F \right] + \mathbb{E}_{\rho\mu^{\beta}}\left[ F \, (h'',\cdot)_{L} \right] &= - \Big\langle \mspace{-7mu} \Big\langle F(\beta), \int_{(0,1)}\bar{h}_x \delta_0(\beta_x) \, dx \Big\rangle \mspace{-7mu} \Big\rangle.
	\end{align}
	Further, the linear operators
	\begin{align*}
		\exp(C^{\infty})\mathrel{\reflectbox{$\in$}} F &\mapsto \langle \!\langle F(\beta), \bar{h}_a \delta_0(\beta_a) \rangle \!\rangle \in\mathbb{R}\\
		\text{and}\quad\exp(C^{\infty})\mathrel{\reflectbox{$\in$}} F &\mapsto \Big\langle \mspace{-7mu} \Big\langle F(\beta), \int_{(0,1)}\bar{h}_x \delta_0(\beta_x) \, dx \Big\rangle \mspace{-7mu} \Big\rangle \in\mathbb{R}
	\end{align*}
	extend uniquely to $W^{1,2}(L, \mu^{\beta})$. Identifying these operators with their extensions in $W^{-1,2}(L, \mu^{\beta})$, (equation IbPF:rho_x of the paper) and (equation IbPF:rho of the paper) hold for all $F \in C_b^1(L)$.

