[Lemma 7 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For $d\ge 3$, $n\ge 1$, $D\subset \widetilde{\mathbb{Z}}^d$, and $v,w\in \widetilde{\mathbb{Z}}^d$ with $\mathrm{dist}(D,\{v,w\})\ge n$, 
\begin{equation}
  \big|  \mathbb{P} (v\xleftrightarrow{\ge 0} w  ) -\mathbb{P}^{D}(v\xleftrightarrow{\ge 0} w ) \big|  \lesssim  \widetilde{G}(v,w)-\widetilde{G}_D(v,w)  +   n^{2-d} \cdot  \mathbb{P} (v\xleftrightarrow{\ge 0} w  ). 
\end{equation}

