[Definition 60 (Change of variables maps) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the change of variables map from geometric to Cartesian coordinates as follows:
	\begin{align} 
		\Upsilon(t,u,x^2,x^3) 
		& 
		\eqdef (t,x^1,x^2,x^3).
	\end{align}

	We define the change of variables map from geometric coordinates 
	to rough adapted coordinates as follows:
	\begin{align} 
		\CHOVgeotorough{0}(t,u,x^2,x^3) 
		& 
		\eqdef (\timefunctionarg{0},u,x^2,x^3).
	\end{align}

	We define the map $\CHOVgeotomumuxmu$ 
	from geometric coordinates to ``$(\upmu,\muX \upmu,x^2,x^3)$-space''
	and its Jacobian 
	$\CHOVJacobiangeotomumuxmu$ as follows:
	\begin{subequations}
		\begin{align} 
			\CHOVgeotomumuxmu(t,u,x^2,x^3)
			& \eqdef (\upmu,\muX \upmu,x^2,x^3),
			\\
			\CHOVJacobiangeotomumuxmu(t,u,x^2,x^3)
			& \eqdef 
			\frac{\partial \CHOVgeotomumuxmu(t,u,x^2,x^3)}{\partial(t,u,x^2,x^3)}
			=
			\frac{\partial (\upmu,\muX \upmu,x^2,x^3)}{\partial(t,u,x^2,x^3)}.

		\end{align}
	\end{subequations}

	We define the map $\CHOVroughtomumuxmu{0}$ 
	from rough adapted coordinates to ``$(\upmu,\muX \upmu,x^2,x^3)$-space''
	and its Jacobian 
	$\CHOVJacobianroughtomumuxmu{0}$ as follows:
	\begin{subequations}
		\begin{align} 
			\CHOVroughtomumuxmu{0}(\timefunctionarg{0},u,x^2,x^3)
			& \eqdef (\upmu,\muX \upmu,x^2,x^3),
			\\
			\CHOVJacobianroughtomumuxmu{0}(\timefunctionarg{0},u,x^2,x^3)
			& \eqdef 
			\frac{\partial \CHOVroughtomumuxmu{0}(\timefunction,u,x^2,x^3)}{\partial(\timefunctionarg{0},u,x^2,x^3)}
			=
			\frac{\partial (\upmu,\muX \upmu,x^2,x^3)}{\partial(\timefunctionarg{0},u,x^2,x^3)}.

		\end{align}
	\end{subequations}

[Lemma 22 of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] Define 
$$J^j[w_{\varepsilon}]:=T^{ij}(D^2w_{\varepsilon})(w_{\varepsilon}Z^{w_{\varepsilon}}_{i}-Z^{w_{\varepsilon}}(w_{\varepsilon
    })_{i}),$$
    $$Q^j[w_{\varepsilon}]:=T^{ij}(D^2w_{\varepsilon})(w_{\varepsilon})_{i},$$
    $$ K^j[w_{\varepsilon}]:=T^{ij}(D^2w_{\varepsilon})Z^{w_{\varepsilon}}_i,$$
    then 
    \begin{equation}
        \diver  Q[w_{\varepsilon}]=kF_{\varepsilon},
    \end{equation}\
\begin{equation}
        \diver K[w_{\varepsilon}]=x\cdot DF_{\varepsilon}+k(1+q)F_{\varepsilon},
    \end{equation}
    \begin{equation}
        \diver J[w_{\varepsilon}]=w_{\varepsilon}\left(x\cdot DF_{\varepsilon}+k(1+q)F_{\varepsilon
        }\right)-kZ^{w_{\varepsilon}}F_{\varepsilon}.
    \end{equation}
    And there is
$$\diver Q[w]=\diver K[w]=\diver J[w]=0\quad\text{in}~\mathcal{D}'(E).$$

