body:
[Theorem th:off-critical-decay of arXiv:2606.11503, 'Percolation on hierarchical lattices'] For any directed graph $G$ satisfying (e:hypothesis of the paper), we have
  \begin{enumerate}[\quad a)]
  \item 
    (Existence of correlation length and surface tension) The function $\xi: (0, p_\star) \to (0, \infty)$ given by
    \begin{equation}

      \xi(p) = - \lim_k \frac{\log f_k(p) }{\d_{1}(a_1, b_1)^k}
    \end{equation}
    is well-defined and non-decreasing.
    The non-increasing function $\eta: (p_\star, 1) \to (0, \infty)$,
    \begin{equation}

      \eta(p) = - \lim_k \frac{\log \big( 1- f_k(p) \big)}{\cut(G_{1})^k}
    \end{equation}
    is well-defined.
  \item 
    (Critical exponents for the correlation length and surface tension) There exist constants $\uc{c:corr_exp_1}, \uc{c:corr_exp_2} > 0$ such that
    \begin{equation}

      \uc{c:corr_exp_1} (p_\star - p)^{-\nu}
      \leq \xi(p)
      \leq \uc{c:corr_exp_2} (p_\star - p)^{-\nu},
      \text{ for $p \in (p_\star/2, p_\star)$}
    \end{equation}
    where $\nu = \log_\zeta \d_{1}(a_1, b_1)$.
    Moreover, there exist constants $\uc{c:surf_exp_1}, \uc{c:surf_exp_2} > 0$ such that
    \begin{equation}

      \uc{c:surf_exp_1} (p - p_\star)^{-\mu}
      \leq \eta(p)
      \leq \uc{c:surf_exp_2} (p - p_\star)^{-\mu},
      \text{ for $p \in (p_\star, 1 - (1-p_\star)/2)$}
    \end{equation}
    with $\mu = \log_\zeta \cut(G_{1})$.
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma inlarge of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] For any $r\ge0$ and $t\in\left[\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}},\infty\right)$, when $N$ is sufficiently large, we have
    \begin{equation*}
        |G_{\tau}(t)|,~|H_{\tau}(t)|\le N^{-r}C(\gamma,r)e^{-\frac{t}{2}}
    \end{equation*}
    where $C(\gamma,r)$ is a constant determined by $\frac{N}{N+a}\rightarrow\gamma\in(0,1)$ and $r$.

[Proposition ASsSCAAS of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume \( \frac{1}{3}<\beta< \gamma< H\) and let \(\mathbf{B}\) be the delayed \(\gamma\)-rough path cocycle constructed in Theorem (thm:B_delayed_cocycle of the paper). Consider the same conditions on \(A\), \(\pi\), and \(G\) as specified in Proposition (BBSTAB of the paper). We consider the following linear rough delay equation:
			\begin{equation}
				\begin{aligned}
					\mathrm{d}y_t &= A \left( y_t, \int_{-r}^{0} y_{\theta+t} \, \pi(\mathrm{d}\theta) \right) \mathrm{d}t + \epsilon G(y_t, y_{t-r}) \, \mathrm{d}\mathbf{B}_t(\omega), \\
					y_{\theta} &= \xi_{\theta} \quad \text{for} \quad \theta \in [-r, 0], \quad \xi \in \mathscr{D}_{\mathbf{B}(\omega)}^{\beta, \gamma}([-r,0]),
				\end{aligned}
			\end{equation}
			where \( y^{\xi, \epsilon}_t(\omega) \) denotes the solution. Let \( \lambda_1 \) be as defined in (equation TRFVV of the paper), and assume \( \lambda_1 < 0 \). Then, there exists \( \epsilon_0 > 0 \) such that for every \( 0 < \epsilon < \epsilon_0 \), there exists \( \lambda^\epsilon < 0 \) such that for any \( \xi \in  \mathscr{D}_{\mathbf{B}(\omega)}^{\beta, \gamma}([-r,0]) \), the following holds:
			\begin{equation}
				\limsup_{t \to \infty} \frac{1}{t} \log | y^{\xi, \epsilon}_t(\omega) | \leq \lambda^\epsilon.
			\end{equation}
			In particular, our stability result holds for every \(\xi \in C^{2\gamma}([-r, 0], \mathbb{R}^n)\), where \(\frac{1}{3} < \gamma < H\) and \(\gamma\) can be chosen arbitrarily close to \(\frac{1}{3}\).

[Corollary 20 of arXiv:2609.01020, '2609.01020'] In the situation as above, there exists $0<\e_1 \ll 1$ and $\lambda >0$ such that 
we have an isomorphism 
\begin{equation}
\psi_f(F)_{(0,0)} \simeq \rsect (B(0;\e)\times B(0;\lambda \e) \cap f^{-1}(t); F)
\end{equation}
for any $0<\e \leq \e_1$ and $t\in \CC^\ast$ such that $0<\abs{t} \ll 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (One-parameter Mittag--Leffler function) of arXiv:2608.25164, 'A time-fractional Kalman filter'] For $z,\alpha\in\mathbb C$ with $\operatorname{Re}(\alpha)>0$, define
\begin{equation}
E_\alpha(z)=E_{\alpha,1}(z)
=\sum_{k=0}^{\infty}\frac{z^k}{\Gamma(\alpha k+1)}.
\end{equation}

[Corollary 2 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Let $\alpha \in (1/2,1)$. Suppose $U:\T^d \to\R^d$ is a $C^{\alpha-}(\T^d)$ multiscale finite range random velocity field; that is, $U$ satisfies Assumption~\ref{asmp:main for autonomous}, and \eqref{eq:main theorem hypothesis} holds for some $p > \frac{d}{\alpha-1/2}$. Suppose in addition that $\nabla \cdot U=0$ and there exists a random constant $\delta>0$ such that almost surely
        \begin{equation}

        \lim_{\ep \to 0} \ep^{-(1-\alpha +\delta)} |Z_\ep| =0.\end{equation}      
    Then almost surely, 
    \begin{enumerate}
        \item for almost every $y \in \T^d$,~\eqref{eq:main ODE autonomous data} admits a unique solution on $(-\infty,\infty)$,
        \item and for every bounded $\phi : \T^d \to \R$,~\eqref{eq:continuity} admits a unique bounded solution $f$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq: def-whitney of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a graph $G = (V,E)$ define the Whitney number polynomial $w_G(x,t)$ as \begin{equation}

    w_G(x,t) := \sum_{A\in \mathcal{F}(G)} x^{rk(A)}\chi_{G/A}(t)
\end{equation} where $\mathcal{F}(G)$ is the set of flats of $G$. In a graph $G = (V,E)$, a flat $A \in \mathcal{F}(G)$ is a subset of $E$ such that each connected component of the graph $(V,A)$ is an induced subgraph of $G$.

[Lemma lem:interior_intersection_left of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $a_1 >0$, $p \in (0,1)$. Suppose $h$ is a GFF on $\delta\mathbf{D}$ with some bounded boundary values so that the angle $\theta_0$ flow line $\eta_0$ from $-i\delta$ to $i\delta$ and the angle $\theta_0$ flow line $\overline{\eta}_0$ from $i\delta$ to $-i\delta$ in the components of $\delta\mathbf{D} \setminus \eta_0$ to the right of $\eta_0$ (and reflected off $\eta_0$) are defined. Let $z_1 \in \partial B(0,\delta/2)$, $w_1 \in \partial B(0,3\delta/16)$. Let $\eta_{z_1}^{\theta_0}$ be the angle $\theta_0$ flow line of $h$ starting from $z_1$ and stopped upon exiting $B(0,3\delta/4)$. Let $\eta_{w_1}^R$ be the angle $-\pi/2$ flow line starting from $w_1$, reflecting off $\eta_{z_1}^{\theta_0}$ in the opposite direction, and stopped upon exiting $B(0,\delta/4)$. Let $\eta_{w_1}^L$ be the angle $+\pi/2$ flow line starting from $w_1$ and stopped upon exiting $B(0,3\delta/4)$. In case $\eta_{w_1}^R$ and $\eta_{z_1}^{\theta_0}$ intersect, sample the internal metric in the regions bounded between them. 
Let $E^p$ be the event that the following hold.
\begin{itemize}
\item $\eta_{w_1}^R$ intersects the right side of $\eta_{z_1}^{\theta_0}$ with an angle difference of $3\pi/2 - \theta_0 = 0$ (before reflecting off), and they do not intersect in any other way.
\item $\eta_{w_1}^L$ does not intersect $\eta_{z_1}^{\theta_0}$.
\item There exist $x',x,y,y' \in \eta_{z_1}^{\theta_0} \cap \eta_{w_1}^R$ such that $(x,y) \in \intptsapproxbubble{U_{x',y'}}{\epsilon}$ as in~(equation eq:intpts_bubble of the paper) and $U_{x',y'} \subseteq B(0,\delta^{1+a_1})$ and $\metapproxacres{\epsilon}{U_{x',y'}}{x}{y}{\Gamma} \geq \median{\epsilon}+\epsilon^{-a_0}\mathbf{a}_{\epsilon}$.
\item The following event has conditional probability at least $p$ given $\eta_{z_1}^{\theta_0}$, $\eta_{w_1}^R$, $\eta_{w_1}^L$, $X_\delta^{\theta_0}$, $X_\delta^{+\pi/2}$, and the values of $h$ on these sets:
\begin{itemize}
\item The flow line $\eta_0$ merges into $\eta_{z_1}^{\theta_0}$ before entering $B(0,\delta/4)$.
\item The extension of $\eta_{w_1}^L$ does not intersect $\eta_0$ until it hits $\partial(\delta\mathbf{D})$.
\end{itemize}
\end{itemize}
Then $\mathbf{P}[E^p] = O(\delta^{{\alpha_{\mathrm{apr}}}})$ as $\delta \to 0$.

[Theorem 2 of arXiv:2609.00087, 'Translational tiles without spectra\\ in finite abelian $p$-groups'] There exist explicit translational tiles without spectra in each of the
following groups:
\begin{enumerate}
\item a $64$-point set $\Gamma\subset\Z_4^4\times\Z_2^2$;
\item a $512$-point set $R_2\subset\F_2^{13}$;
\item a $2187$-point set $R_3\subset\F_3^9$.
\end{enumerate}
The corresponding tiling complements have cardinalities $16$, $16$, and
$9$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:type_path_induced of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Fix $s_0,s_1 \in S$. Consider any rooted tree $\mathbb T$ with vertex types in $S$. For any vertex $v \in \mathbb T$ with $T_{p(v)}=s_0, T_v=s_1$, and a type path/ray $\pi=(s_0\rightarrow s_0s_1 \rightarrow s_0s_1s_2\rightarrow \dots)$, we define the subtree $\mathbb T(v;\pi)$ of $\mathbb T$ to be spanned by the vertices
    \begin{align*}
        \{v\}\cup \left(\cup_{i=2}^{|\pi|}C(e;\pi_{(i)})  \right),
    \end{align*}
    where $e$ is the directed edge $(p(v),v)$. We naturally think of $\mathbb T(v;\pi)$ to be a rooted tree, rooted at $v$. We call $\mathbb T(v;\pi)$ the subtree of $v$ in $\mathbb T$ induced by $\pi$.

[Propn PDEtoCompare of arXiv:2605.04860, 'Branching Brownian motion with rank-based selection and reaction-diffusion equations'] Let $G:[0,1]\to \mathbb{R}$ be a differentiable function such that $G(0)=G(u^\star)=G(1)=0$, $G(x)>0$ for $x\in (0,u^\star)$ and $G'(x)\leq G'(0)$ for $x\in [0,1]$, and consider the PDE 
\begin{equation} U_t = \frac12 U_{xx} + G(U).\end{equation}
Then any front-like initial condition $U_0(x)$ such that $\lim_{x\to-\infty}U_0(x)=1$ and $\lim_{x\to\infty}U_0(x)=0$ spreads up to the value $u^\star$ with speed at least $\sqrt{2G'(0)}$. Moreover, the minimal spreading speed is attained; that is, there exists an initial condition $U_0(x)$ which spreads up to the value $u^\star$ at speed $\sqrt{2G'(0)}$.

