[Lemma lem_3 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $u,v,w, w'$ be positive numbers such that $w\geq w'$ and $x=\frac{\sqrt{v^2+3uw}-v}{3w}$. Then 
  \begin{eqnarray}
\hskip1cm-ux+vx^2+wx^3\leq \frac{1}{27w^{\frac{1}{2}}w'^{\frac{3}{2}}}(\sqrt{v^2+3uw'}-v)(v\sqrt{v^2+3uw'}-v^2-6uw').
\end{eqnarray}

[Thm 3.3 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] For each $n\geq1$, let $\xi^n, \xi\in L_\tau^p(\rho_\cdot;{\mathbb R}^k)$, both $g^n$ and $g$ be the generator of BSDEs   satisfying assumptions (A:H4 of the paper) and (A:H5 of the paper), and $(Y_\cdot^n, Z_\cdot^n)$ and $(Y_\cdot, Z_\cdot)$ be the weighted $L^p$ solution of BSDE$(\xi^n,\tau,g^n)$ and BSDE$(\xi,\tau,g)$, respectively, in the space of $H_\tau^p(\rho_\cdot;{\mathbb R}^{k}\times{\mathbb R}^{k\times d})$. If
$$\lim_{n\rightarrow\infty}\mathbb{E}\left[e^{p \int_{0}^{\tau}\rho_r{\rm d}r}|\xi^n-\xi|^p+\left(\int_0^\tau e^{\int_0^s\rho_r{\rm d}r}\left|g^n(s,Y_s,Z_s)-g(s,Y_s,Z_s)\right|{\rm d}s\right)^p\right]=0,$$
then
$$
\lim_{n\rightarrow\infty}\mathbb{E}\left[\sup_{s\in[0,\tau]}\left(e^{p \int_{0}^{s}\rho_r{\rm d}r}|Y_s^n-Y_s|^p\right)+\left(\int_0^{\tau} e^{2\int_0^s \rho_r{\rm d}r}|Z_s^n-Z_s|^2{\rm d}s\right)^{\frac{p}{2}}\right]=0.\vspace{0.2cm}
$$
\begin{proof}
For each $n\geq1$, let
$$\hat{Y}_\cdot^n:=Y_\cdot^n-Y_\cdot, \ \ \hat{Z}_\cdot^n:=Z_\cdot^n-Z_\cdot \ \ {\rm and}\ \ \hat{\xi}^n:=\xi^n-\xi.$$
Then, for each $n\geq1$, $(\hat{Y}_\cdot^n,\hat{Z}_\cdot^n)$ is a weighted $L^p$ solution of the following BSDE:
\begin{align*}
\hat{Y}_t^n=\hat{\xi}^n+\int_t^\tau \hat{g}^n(s,\hat{Y}_s^n,\hat{Z}_s^n){\rm d}s-\int_t^\tau\hat{Z}_s^n{\rm d}B_s, \ t\in[0,\tau],
\end{align*}
where the generator $\hat{g}^n$ is defined by
$$\hat{g}^n(t,y,z):=g^n(t,y+Y_t,z+Z_t)-g(t,Y_t,Z_t),
~~(t,y,z)\in[0,\tau]\times{\mathbb R}^k\times{\mathbb R}^{k\times{d}}.$$
It follows from (A:H4 of the paper) and (A:H5 of the paper) that for each $n\geq1$ and $(y,z)\in{\mathbb R}^k\times{\mathbb R}^{k\times{d}}$,
\begin{align*}
\begin{split}
\left<\hat{y},\hat{g}^n(t,y,z)\right>&=\left<\hat{y},g^n(t,y+Y_t,z+Z_t)-g(t,Y_t,Z_t)\right>\\
&\leq \mu_t|y|+\nu_t|z|+|g^n(t,Y_t,Z_t)-g(t,Y_t,Z_t)|, \ \ t\in[0,\tau],
\end{split}
\end{align*}
which implies that for each $n\geq1$, the generator $\hat g^n$ satisfies assumption (A:A of the paper) with $\bar{p}:=p$, $\bar\mu_t:=\mu_t$, $\bar\nu_t:=\nu_t$, $\bar\rho_t:=\rho_t$ and $f_t:=|g^n(t,Y_t,Z_t)-g(t,Y_t,Z_t)|$. Then, it follows from (pro2.1 of the paper) with $r=t=0$ that there exists a constant $C_{p,\theta}>0$ depending only on $p$ and $\theta$ such that
\begin{align*}
\begin{split}
&\mathbb{E}\left[\sup_{s\in[0,\tau]}\left(e^{p \int_{0}^{s}\rho_r{\rm d}r}|Y_s^n-Y_s|^p\right)+\left(\int_0^{\tau} e^{2\int_0^s \rho_r{\rm d}r}|Z_s^n-Z_s|^2{\rm d}s\right)^{\frac{p}{2}}\right]\\
&\ \ \leq C_{p,\theta}\mathbb{E}\left[e^{p \int_{0}^{\tau}\rho_r{\rm d}r}|\xi^n-\xi|^p+\left(\int_0^\tau e^{\int_0^s\rho_r{\rm d}r}\left|g^n(s,Y_s,Z_s)-g(s,Y_s,Z_s)\right|{\rm d}s\right)^p\right].
\end{split}
\end{align*}
Thus, the desired assertion follows by sending $n$ to infinity in the last inequality.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

