[Theorem thm:sto of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every smooth, compactly supported $\omega:\R\rightarrow\R$, $P{\geqslant1}$, $\eta>0$ and $c>0$ sufficiently small, we have
\begin{equs}
\E\big[ {\talloblong \omega\xi \talloblong}_{4}^P\big]^{1/P}\lesssim_{P} 1\quad\text{and}\quad\E\big[ {\talloblong \omega\xi \talloblong}_{4,c}^P\big]^{1/P}\lesssim_{P} 1\,,
\end{equs}
where we write $\omega\xi^\tau_{\eps,\mu}(t,s^\tau)\eqdef\omega(t)\xi^\tau_{\eps,\mu}(t,s^\tau)$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 3 (\rm  Stone  local limit theorem for nonlattice random walk in cones) of arXiv:2603.26228, 'A local limit theorem for nonlattice multidimensional random walks in cones'] Assume  hypotheses  {\bf C},  {\bf M},  {\bf N} and {\bf A}. Let ${\bf B}_1\subset \mathbb R^s$ be a  bounded Borel  set  whose boundary is negligible with respect to the Lebesgue measure on $\mathbb R^s$   and $ {\bf y}_2\in G_2$ such that ${\bf B}:= {\bf B}_1\times \{{\bf y}_2\}\subset \mathcal C$.  Then,    as $n \to +\infty$,  uniformly in $ {\bf x} \in \cC$,
 \begin{equation*}
 \Big\vert n^{p/2+d/2}\bP(  \tau({\bf x})>n, {\bf x}  +S(n) \in   {\bf B})- \    \kappa_0 H_0  V({\bf x})\  \int_{\bf B}  u( {\bf y}/\sqrt{n})e^{-{\vert  {\bf y}_1\vert^2+ \vert{\bf y}_2\vert^2\over 2n}} {\rm d}{\bf y}_1\Big\vert\to 0 
\end{equation*}
where $\kappa_0$ and $H_0$ are defined in Proposition \ref{exitTime}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:SW-length of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Fix $\varepsilon, \delta \in (0, 1)$, and $A, B$ with $B \in \ensuremath{\mathcal Y}_\delta^\blacktriangleleft(A)\setminus \{A\}$. We call $V$ an $\varepsilon$-\emph{nice} domain with respect to $A, B$ if there exists $\beta_0, v_0, \delta_0, c > 0$ such that uniformly over $\beta \geq \beta_0$ and $r \geq 1 + \varepsilon$, we have
		\begin{align}
			Z_V^{\mathsf{SW}}(A, B \mid |S| \geq r\lVertA - B\rVert_1) \leq ce^{-v_0\beta r\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,,\\
			Z_V^{\mathsf{SW}}(A, B \mid |\mathsf{Cpts}(S)| < 2\delta_0\lVertA-B\rVert_1) \leq ce^{-v_0\beta\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,.
		\end{align}

