[Definition D:horizon-topology of arXiv:2604.10020, 'The directed landscape in half-space'] Let $L$ be an interval in $\mathbb{R}$ and let $J \in \{\mathbb{R}, \mathbb{Z}\}$, and fix a distinguished point $\gamma_0 \in L$. Define $\mathcal{D}(L, J, \gamma_0)$ to be the set of functions $F:L \times J \to \mathbb{R}$, such that (denoting $F_\gamma(j)=F(\gamma,j)$)
\begin{itemize}[nosep]
    \item $F_{\gamma_0}$ is continuous if $J = \mathbb{R}$;
    \item $F_\gamma(0) = 0$ for all $\gamma$;
    \item there is a $\sigma$-finite measure $\mu_F$ on $L \times J$ such that for any $\gamma_1<\gamma_2\in L$ and $j_1<j_2\in J$, we have
    \begin{equation}

        \mu_F((\gamma_1, \gamma_2] \times ((j_1, j_2]\cap J)) = F(\gamma_1, j_1) + F(\gamma_2, j_2) - F(\gamma_1, j_2) - F(\gamma_2, j_1). 
    \end{equation}
\end{itemize}
We say that $F^n \to F$ in $\mathcal{D}(L, J, \gamma_0)$ if $F^n_{\gamma_0} \to F_{\gamma_0}$ in the uniform-on-compact topology, and $\mu_{F^n} \to \mu_F$ vaguely. This turns $\mathcal{D}(L, J, \gamma_0)$ into a Polish space.

[Lemma 79 of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The material vectorfield $\Transport$ admits the following decompositions in terms of the double-null frame and the vectorfield from \eqref{E:TORITANGENTVECTORFIELDASSOCIATEDTODOUBLENULLFRAME}:
		\begin{subequations}
			\begin{align}
				\Transport &= \frac{1}{\upmu} \newuL + \frac{1}{\ingoingmu} \newL + \ReciprocalLunitAppliedtoTimeFunction \ToriTangentVectorfieldAssociatedToDoubleNullFolliations   \\
				& = \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \uLunit + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \Lunit + \breve{\slashed{\Transport}}. 
			\end{align}
		\end{subequations}
In particular, we have: 
	\begin{align}
		\ReciprocalLunitAppliedtoTimeFunction \ToriTangentVectorfieldAssociatedToDoubleNullFolliations  = \breve{\slashed{\Transport}} 
	\end{align}In addition, there exists unique $\Sigma_t$-tangent vectorfields $\Lunit^\perp$ and $\uLunit^\perp$ such that: 
	\begin{subequations}
		\begin{align}
			\Lunit & = \Transport + \Lunit^\perp,  \\
			\uLunit & = \Transport + \uLunit^\perp. 
		\end{align}
	\end{subequations}
Moreover, $\Lunit^\perp$ and $\uLunit^\perp$ satisfy:
	\begin{align}
		 \gfour(\Lunit^\perp,\Lunit^\perp) & = 1, & \gfour(\uLunit^\perp,\uLunit^\perp) & = 1, & \gfour(\Lunit^\perp,\uLunit^\perp) & = 1 - \MagnitueofinnerproductofLunitanduLunit. 
	\end{align}

[Lemma 7 of arXiv:2605.05864, 'Classification and Metrization of Classes of Smooth measures'] It holds that
\begin{eqnarray*}
\mathcal{K} \!\! &=& \big\{\mu \in \mathcal{S} \mid \lim_{t \to 0}\|\mathbb{E}_{\cdot}[A_t^\mu]\|_{\infty} =0 \big\}\  =\  \big\{\mu \in \mathcal{S} \mid \lim_{t \to 0}\|\mathbb{E}_{\cdot}[A_t^\mu]\|_{\infty,q } =0 \big\}. 
\end{eqnarray*}

[Corollary cor_high of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume (equation converging_ratios of the paper), (equation delta_decay of the paper), (equation balanced of the paper).
With $\beta_p$ as in (equation beta_def of the paper), define
\eeq{ 
\xi^\mathsf{single}(x) \coloneqq \sum_{p=1}^\infty \beta_p^2x^p, \quad x\in[-1,1].
}
For either ${\scaleobj{1.1}{\diamond}}\in\{\mathsf{Ising},\mathsf{spherical}\}$, the following implication holds:
\eeq{ 
\lim_{N\to\infty}F_{N,{\scaleobj{1.1}{\diamond}}}^\mathsf{single}(\boldsymbol{\beta}) = \frac{\xi^\mathsf{single}(1)}{2} \quad \implies \quad
\lim_{N\to\infty} F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N) = \frac{\xi^\mathsf{single}(1)}{2}. 
}

