\begin{equation*}
\max_{x\in {\mathbb T}^d_N} \big|\, (\Delta^{(1)}_N {\boldsymbol u}_N)(x) + K\,
E_{\nu^N}[\tau_x h_0] \,\big|\;\le\; \frac{C_0 \, K^2}{N^2}
\end{equation*}
for all $N\ge 1$.

[Corollary cor:BLPP-trace-defect of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $F_n = \det(I - K_n)$.
Then
$\partial_{\mathbf{a}} \log F_n
= \operatorname{tr}_E(\mathcal{A}_n)$,
and
\begin{equation}
\bigl[D_{\mathbf{t}} - \tfrac{1}{2}D_{\mathbf{a}}^2\bigr]
F_{n+1} \cdot F_n
= \tfrac{1}{2}F_{n+1}
F_n
\bigl(\operatorname{tr}_E((\mathcal{A}_{n+1}
- \mathcal{A}_n)^2)
- (\operatorname{tr}_E(\mathcal{A}_{n+1}
- \mathcal{A}_n))^2\bigr).
\end{equation}

[Prop edge-weight-locality of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $d=d^{{\mathrm {res}}}$. Suppose that $V,V_1,V_2\in\mathfrak{C}$ are such that $\mathcal{X}\cap\overline{V} = (\mathcal{X}\cap\overline{V_1}) \cup (\mathcal{X}\cap\overline{V_2})$ and $(\mathcal{X}\cap\overline{V_1}) \cap (\mathcal{X}\cap\overline{V_2}) = \{a,b\}$. There exists a countable set $\mathcal{Z}_V=\{z_1,z_2,\ldots\} \subseteq \mathcal{X}\cap\overline{V}$ that contains $a,b$, is dense with respect to $d^{{\mathrm {path}}}_{\overline{V}}$, and such that the following holds for sufficiently large~$m$. Let $A = \{z_1,\ldots,z_m\}$, $A_1 = A \cap \overline{V_1}$, $A_2 = A \cap \overline{V_2}$, and let $w$ (resp.\ $w_1$, $w_2$) be the weight function associated with $\mathfrak{d}_V(\cdot,\cdot)|_{A}$ (resp.\ $\mathfrak{d}_{V_1}(\cdot,\cdot)|_{A_1}$, $\mathfrak{d}_{V_2}(\cdot,\cdot)|_{A_2}$). Then
\begin{itemize}
    \item $w(x,y)=w_1(x,y)$ for each $x,y\in A_1$;
    \item $w(x,y)=w_2(x,y)$ for each $x,y\in A_2$;
    \item $w(x,y)=0$ for each $x\in A_1 \setminus \{a,b\}$, $y\in A_2 \setminus \{a,b\}$;
    \item $w(a,b)=0$.
\end{itemize}

[Definition 4 (Caputo fractional derivative) of arXiv:2608.25164, 'A time-fractional Kalman filter'] Let $\alpha>0$ and let $n=\lceil\alpha\rceil$. The Caputo derivative is
defined by
\begin{align}
D_C^\alpha f(t)
&=I^{n-\alpha}f^{(n)}(t)\nonumber\\
&=\frac{1}{\Gamma(n-\alpha)}
  \int_0^t(t-s)^{n-\alpha-1}f^{(n)}(s)ds,
  \qquad n-1<\alpha<n,
\end{align}
while $D_C^n f=f^{(n)}$ when $\alpha=n$.

[Theorem 1 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(X, X_1,X_2,\dots\) be an i.i.d.\ family of \(\Z\)-valued, irreducible, aperiodic random variables satisfying~\eqref{eq:conditions_steps}. Let \(a_*,b_*\) be defined as in~\eqref{eq:dual_allowed_slopes}, and \(a_*<a<b<b_*\). Let \(h\in C^2([0,1])\) be a non-negative concave function with \(h''<0\), \(\mathrm{Image}(h')\subset H_X'([a,b])\), and \(h(0)=0\). Define
    \begin{equation*}
        h_n(k) = nh(k/n),\quad k=0,\dots, n.
    \end{equation*}
    Then, there are \(c_+\geq c_- >0, n_0\geq 1\) such that for any \(n\geq n_0\),
    \begin{equation*}
        e^{-c_+n^{1/3}}
        \leq
        e^{n\int_{0}^1 I(h'(s))ds} P\bigl(S\geq h_n, S_n = \lceil h_n(n)\rceil\bigr)
        \leq
        e^{-c_-n^{1/3}},
    \end{equation*}
    where \(S_0=0\), \(S_k=S_{k-1}+X_k\) and \(I(x) = \sup_{\lambda} \bigl(\lambda x - H(x)\bigr)\).

[Proposition 3 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] {Assume  \eqref{as:generatorf}, \eqref{as:b:sigma} and \eqref{as:int:X:nablaX}.}
Then there exists a function $u \in {C}^1(\bR^d,\bR^{d'})$ such that, for all $x\in \bR^d$, $\Yx=u(\Xx)$, $\nabla_x u({\Xx})\sigma(\Xx):=\bar{u}(\Xx)$ is a continuous version of $\Zx$ and we have the following probabilistic representation for $(u,\bar{u})$: for all $x\in \bR^d$,
\begin{align}
 u(x):= \Yx_0 &= \E{\int_0^\infty  e^{-as}(f(\Xx_s,u(\Xx_s),\bar{u}(\Xx_s))+a u(\Xx_s)) \ds}\\
&=\frac{1}{\theta }\E{  (f(\Xx_E,u(\Xx_E),\bar{u}(\Xx_E))+a u(\Xx_E))e^{-(a-\theta)E} },
\\
 \bar{u}(x) := \Zx_0  &= \E{\int_0^\infty  e^{-\ta s}(f(\Xx_s,u(\Xx_s),\bar{u}(\Xx_s))+ \ta u(\Xx_s))\Ux_s \ds}\\
&=\frac{\sqrt{\pi}}{\sqrt{\ttheta} }\E{  (f(\Xx_\tE,u(\Xx_\tE),\bar{u}(\Xx_\tE))+ \ta u(\Xx_\tE))\sqrt{\tE}e^{-(\ta-\ttheta)\tE}\Ux_\tE }

\end{align}
where $\theta >0$, $\ttheta >0$, $E\sim\cE(\theta)$ is independent of $W$ and $\tE \sim \Gamma(1/2,\ttheta)$ is independent of $W$. 
Lastly, we have the following growth:
\begin{align}

 |u(x)| +  \norm{\bar{u}(x)} \leqslant C(1+|x|^{r}),\quad \forall x \in \bR^d.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma stochasticesti of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $s \in \mathbb{R}$, $0\leq 
		b<1/2$, $0<T<1$. For any $ j\in \mathbb{N}$, $f_j(t',x,\omega)$ is $\mathscr{B}\left([0,t]\times \mathbb{R}\right)\times \mathcal{F}_t$ measurable on $[0,t]\times \mathbb{R}\times\Omega  $. Then for any stopping time $\sigma$, we have 
		\begin{equation*}
			\left\|\sum_{j\in \mathbb{N}}\int_{0}^{t} U(t-t')f_j(t',x,\omega) ~d\beta_j(t')\right\|_{L_\omega^{2}Z^{s,b}_{T\wedge \sigma}} \lesssim \| f_j\|_{L_\omega^{2}L^2_{T\wedge \sigma}l^2_j H^s_x}.
		\end{equation*}

