[Prop torusgroup of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] $G_n^{tor}$ is free on $A = x_{n+3}, H = x_2(x_{n+3}x_{2n+4})^{-n}$. Killing the trivial-strand meridian gives the quotient
\begin{equation*}
	Q_n^{tor} \cong \langle A, B \mid (BA)^nB = A(BA)^n \rangle \cong \langle u, v \mid u^2 = v^{2n+1} \rangle
\end{equation*}
which is the group of the $(2, 2n+1)$-torus knot, denoted $T_{2,2n+1}$.

[Definition def:complex-SaS of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] A \emph{complex isotropic S$\alpha$S random measure}
$\widetilde{M}_\alpha$ on $\mathbb{R}$ with Lebesgue control measure
is a complex random measure such that, for every
$f \in L^\alpha(\mathbb{R},\mathbb{C})$:
\begin{equation}

\mathbb{E}\!\left[\exp\!\left(
i\,\mathrm{Re}\int_\mathbb{R} f(\xi)\,d\widetilde{M}_\alpha(\xi)
\right)\right]
= \exp\!\left(-c_\alpha\int_\mathbb{R}|f(\xi)|^\alpha\,d\xi\right),
\end{equation}
where
\begin{equation}

c_\alpha
:= \frac{1}{2\pi}\int_0^{2\pi}|\cos\theta|^\alpha\,d\theta
= \frac{\Gamma\!\left(\frac{\alpha+1}{2}\right)}
{\sqrt{\pi}\;\Gamma\!\left(\frac{\alpha}{2}+1\right)}.
\end{equation}
The measure $\widetilde{M}_\alpha$ is \emph{isotropic}: for every
$\phi \in \mathbb{R}$, $e^{i\phi}\widetilde{M}_\alpha(\cdot)
\overset{d}{=} \widetilde{M}_\alpha(\cdot)$.

[Theorem 10 of arXiv:2604.13819, 'Convolution, cumulants and infinitesimal generators in the formal power series ring'] \begin{enumerate}[\rm (1)]
\item (\textit{Law of large numbers for $\boxplus^t$})\ For $t\in \mathbb{R}^\times$, let us consider $A\in U$ such that $\kappa_1^t(A)=\lambda$. Then
\begin{align*}
D_{1/m}\bigl[A^{\boxplus^t m}\bigr] (z) \to B_\lambda^{(t)}(z), \qquad m\to \infty.
\end{align*}
\item (\textit{Central limit theorem for $\boxplus^t$})\ For $t\in \mathbb{R}^\times$, let us consider $A\in U$ such that $\kappa_1^t(A)=0$ and $\kappa_2^t(A)=1$. Then
\begin{align*}
D_{1/\sqrt{m}} \bigl[A^{\boxplus^t m} \bigr] (z)  \to H^{(t)}(z), \qquad m \to\infty.
\end{align*} 
\end{enumerate}

