[Theorem 35 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume that the Markov renewal kernel is strict, and let $\mathcal E$ and $(R_h)_{h\in\N^d}$ be defined by \eqref{eq:augmented-admissible-set} and \eqref{eq:augmented-transition-kernel}. For every initial law concentrated on $\mathcal E$, the augmented field $Y=(Z_k,U_k)_{k\in\N^d}$ satisfies

\begin{equation}
\Ee\left[f(Y_{k+h})\mid \mathcal G_k^Y\right]=R_hf(Y_k),
\qquad k,h\in\N^d,
\end{equation}

for every bounded measurable function $f$ on $\mathcal E$. Moreover, $(R_h)_{h\in\N^d}$ is a Markov semigroup:

\begin{equation}
R_{\zerod}=I,
\qquad
R_{h+r}=R_hR_r,
\qquad h,r\in\N^d.
\end{equation}

In particular, the coordinate transition kernels $R_{e_1},\ldots,R_{e_d}$ commute.

[Theorem thm:shuffle of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] For bounded-variation paths and words $u,v$,
\begin{equation}
\inner{\mathrm{Sig}(x)}{u}\,\inner{\mathrm{Sig}(x)}{v}
=
\inner{\mathrm{Sig}(x)}{u\mathbin{\sqcup\!\sqcup} v},
\end{equation}
where $u\mathbin{\sqcup\!\sqcup} v$ is the sum of all order-preserving interlacings of $u$ and $v$.

[Lemma 17 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] For any integer $p \ge 2$ and $0 < \theta < 1/6$,
        \begin{equation}

        \Bigg| \mathbb{E} \bigg[ \int_{-\infty}^{\infty}\int_{[0, t]_<^{p}} \prod_{j=1}^p\Delta_{\epsilon}(W(s^{j}) - x)  \mathrm{d} \mathbf{s} \mathrm{d} x
        \bigg]^m \Bigg| \le C^m \epsilon^{\theta(p-1) m} (m!)^p \Big( \frac{t^m}{m!} \Big)^{\frac{p+1}{2} - (p-1)\theta}.
        \end{equation}

