body:
[Lemma lem.TransitionGreen of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the transition kernel $\overline{p}_t(\{0,1\},Y)$ and the Green function $\overline{g}_\lambda(Y)$:
		\begin{enumerate}
			\item [LandimGaussian] There exist finite positive constants $C_1,C_2,C_3$ such that for every $t>C_1$ and every $x<y$, the following estimate holds:
			\begin{equation*}
				\overline{p}_t(\{0,1\},\{x,y\})\leqslant \frac{2C_1}{1+t}\left(\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_{2}^2}{C_2t}\right)+\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_2}{C_2\log t}\right)\1_{\left\Vert{(x,y)}\right\Vert_2\geqslant \frac{C_3et}{\log t}}\right),
			\end{equation*}
			where the norm $\left\Vert{(x,y)}\right\Vert_2$ is defined as $\left\Vert{(x,y)}\right\Vert_2^2:=x^2+(y-1)^2.$
			\item [CarinciExact]
			The Laplace transform of the transition kernel for every $x<y$ is given by:
			\begin{equation*}
				\overline{g}_\lambda(\{x,y\})\\
				=\frac{1}{8\pi^2\mathbf{D}(\rho)}\int_{\pi}^{\pi}\int_{-\pi}^{\pi}\frac{e^{i(k_1 x+k_2(y-1))}+{\mathsf{A}}(\frac{k_1+k_2}{2},\lambda)e^{i(k_1 y+k_2(x-1))}}{2+\lambda-(\cos k_1+\cos k_2)}\, {\mathrm{d}} k_1\, {\mathrm{d}} k_2,
			\end{equation*}
			where the function ${\mathsf{A}}(k,\lambda)$ is defined as:
			\begin{equation*}
				{\mathsf{A}}(k,\lambda):=2\frac{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)}{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)-2(x_{\lambda,k}-\cos k)}-1,
			\end{equation*}
			with
			\begin{equation*}
				\xi_{\lambda,k}=x_{\lambda,k}-\sqrt{x_{\lambda,k}^2-1},\qquad x_{\lambda,k}=\frac{1}{\cos k}\left(1+\frac{\lambda}{2}\right).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro:OU-back-time-used of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Suppose that $|m_0|=\mathsf{m}_{3}$, and define $T_0$ by:  
    \begin{align*}
        T_0&=\frac1{8C_E}(\sqrt{\frac{\beta C_E}2}\arcsin(\mathsf{m}_{3})-\sqrt{\frac{\beta C_E}2}\arcsin(\mathsf{m}_{2}))^2\nonumber\\
        &=\frac\beta{16}(\arcsin(\mathsf{m}_{3})-\arcsin(\mathsf{m}_{2}))^2\,.
    \end{align*}
    then the probability that $|m_t| = \frac12(\mathsf{m}_{3}+\mathsf{m}_{2})$  for some $t<T_0$ is less than $e^{-cN}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm thm-G of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let  $d\ge 3$ and $ \lambda\in \Sigma_\theta$.
There exists $\varepsilon \in (0, 1)$,  depending only on $d$,  $\theta$ and $M$, such that 
if  
\begin{equation}
\Big| \frac{1}{q} -\frac12 \Big| < \frac{1}{2d} +\varepsilon,
\end{equation}
then 
for any $F\in L^q(E_r; \mathbb{C}^d)$, $f\in L^q(E_r ; \mathbb{C}^{d\times d})$ and $g \in L^q(E_r; \mathbb{C})$ with $\int_{E_r} g =0$,
there exists  a unique  $u \in W_0^{1, q}(E_r; \mathbb{C}^d)$
such that  (equation G-eq of the paper) holds for some $\phi\in L^q(E_r; \mathbb{C})$.
Moreover, the solution satisfies 
\begin{equation}
\aligned
 & |\lambda|^{1/2} \| \nabla u \|_{L^q(E_r)}
+|\lambda| \| u \|_{L^q(E_r)}
\\
&\quad \le C \left\{
\| F \|_{L^q(E_r)}
+ |\lambda|^{1/2}  \| f \|_{L^q(E_r )}
+|\lambda|^{1/2}  \| g \|_{L^q(E_r)}
+  |\lambda| \| g \|_{\accentset{\circ}{W}^{-1, q}(E_r )}
\right\},
\endaligned
\end{equation}
where $C$ depends only on $d$, $q$, $\theta$ and $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm free_energy_torus of arXiv:2506.12171, 'The multinomial dimer model'] The {free energy per dimer} of $\mu_{n,N,w}=\mu_{n,N}(w_1,\dots,w_D)$ is
\begin{equation*}
    F(w_1,...,w_D) := \lim_{n\to \infty} \lim_{N\to \infty} \frac{1}{N n^d} \log \frac{ Z_{n,N}(w_1,\dots,w_D)}{(N!)^{n^d}}=
    \log (w_1+\dots+w_D).
\end{equation*}

