[Proposition lem:rho-closed of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $w\ge10$ and set
\[
  \lambda_w=\frac{14(w-1)}{36w-25}.
\]
Then $\ell=\mu(w)$ satisfies
\begin{equation}
  (1+\lambda_w^2)\ell^2-(5+\lambda_w)\ell+6-4w\le0.
\end{equation}
Relaxing $\lambda_w\ge\tfrac38$ in (equation eq:rho-sharp of the paper) gives
\begin{equation}
  73\ell^2-344\ell+384-256w\le0,
\end{equation}
and hence the closed form
\begin{equation}
  \mu(w)<\frac{15}{8}\sqrt w+\frac{12}{5}.
\end{equation}
Moreover (equation eq:rho-closed of the paper) holds for every $w\ge1$.

[Lemma lem:density of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let $\delta, C>0$. There exists $r_0 = r_0(\delta,C)>0$ such that for $r\geq r_0$, $\lambda>0$ and $\xi\sim \mathrm{PPP}\big(\lambda dx, \mathbb R^d\big)$ we have
\begin{equation}
\mathbb P \bigg(\mathrm{d}_{\mathbb{R}^d}(x,\xi)\leq r\lambda^{-1/d}/C \; \text{ for all } x\in B_{\mathbb R^d}\big(0, r\lambda^{-1/d}\big) \bigg) \geq 1-\delta.
\end{equation}

[Proposition eq:jet-h-linear of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:jet-linear}
For every frame \(O\),
\begin{align}
 h_J(O)&=\sum_I e_I(O)J_I,
 &e_I(O)&=N^{-1/2}x_I,\\
 g_{a,J}(O)&=\sum_I b_{a,I}(O)J_I,\\
 A_{ab,J}(O)&=\sum_I C_{ab,I}(O)J_I.
\end{align}

[Proposition 18 (A \(q\)-factorial form of \(Q_r\)) of arXiv:2609.03881, 'Eulerian insertion operators and an Eulerian form of the Pieri rule'] For every \(r\geq0\),
\begin{equation}
 Q_r
 =
 \frac{1}{[r]_q!}
 \prod_{\ell=1}^r
 \bigl([\ell]_q+q^\ell tD_q\bigr),
\end{equation}
where $[r]_q!=[1]_q[2]_q\cdots[r]_q$.

[Lemma lem:truncation of arXiv:2608.31043, 'Sharp constants for weak estimates of Riesz Potentials when $0<s<\min\{n,2\}$'] If $f\in L^1(\mathbb{R}^n)$, $f\geq 0$ and $u=I_sf$, then
\begin{equation*}
 T(u)\in\dot H^{s/2}(\mathbb{R}^n),
 \qquad
 \mathcal{E}_s(T(u))\leq\|f\|_{L^1(\mathbb{R}^n)}.
\end{equation*}

