 \|e^{\alpha\mathsf T_k}-e^{\alpha\mathsf T_{k-1}}\|_{L^p(\mathbb Q_s)}
 \ll_{\alpha,p}(1+k)^{\alpha/\lambda-1/p}.
\end{equation}

