[Defn integ1 of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Suppose that $(\Omega,{\mathscr{B}},{\mathbb{P}})$ is a complete probability space endowed with the $\sigma$-algebra generated by $(B^{i}(t)\otimes W^{Q,i}(t))_{t\in[0,T],i=1\ldots,N}$ and that is still denoted as $({\mathscr{F}}_{t})_{t\in[0,T]}$. We say that an ${\mathscr{F}}(U)$-valued predictable process $\lambda^{i}(t)$, $t\in[0,T]$, is a weak solution to 

\begin{align}
&{\rm d}\lambda^{i}(t)= {\mathbb R}(X^i(t),\lambda^i(t),\mu^{N}(t))\,{\rm d} t+
\sqrt{2\sigma_\lambda}\,\Pi_{\lambda^i(t)}\,{\rm d} W^{Q,i}(t)   
\end{align}
if  for all $x^{\ast}\in ({\mathscr{F}}(U))^{\ast}$

\begin{align}
\nm{\lambda^{i}(t),x^{\ast}}=\nm{\lambda^{i}(0),x^{\ast}}+ \int_{0}^{t}\nm{{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)),x^{\ast}}{\rm d} s+ \sqrt{2\sigma}T_{{\mathbbm{1}}_{i}}^{t}x^{\ast}
\end{align}
where ${\mathbbm{1}}_{i}\in {\mathcal H}_{Q}(L({\mathscr{F}}(U),{\mathscr{F}}(U)))$ denotes the projector operator $\Pi_{\lambda^{i}}$. Moreover, we say that $(\lambda^{i}(t))_{t\in[0,T]}$ is a strong solution if 
\begin{align}
\lambda^{i}(t)=\lambda^{i}(0)+ \int_{0}^{t}{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)){\rm d} s+ \sqrt{2\sigma}\int_{0}^{t}\Pi_{\lambda^{i}(s)}{\rm d} s \hskip 0,4cm \text{${\mathbb{P}}$-a.s..}
\end{align}

[Lemma keyI of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Given a fixed $s_0\in\mathbb{R}$, assume the scaling $(\tilde{\mu}_{n,N},\tilde\sigma_{n,N})$ satisfies the order restriction in (equation restriction of recaling of the paper). Then under the assumption that $\frac{N}{n}\rightarrow\gamma\in(0,1)$, we have:
    \begin{equation*}
        N^{\frac{2}{3}}B_{n,N}(x_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    for any $s\in\left[s_0,\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}}\right]$ when $N$ is large enough. Furthermore, with  $\tilde{x}_N(s):=\tilde{\mu}_{n,N}-\tilde{\sigma}_{n,N}s$,
    \begin{equation*}
        N^{\frac{2}{3}}B_{n-1,N}(\tilde{x}_N(s)),~N^{\frac{2}{3}}B_{n,N-1}(\tilde{x}_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    for $N$ large.

[Definition 8 of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] (Stopping Time \cite[Definition 5.3]{bender3})  
Given a Trajectory Space $\Se$, a \emph{trajectory based stopping time} (or \emph{stopping time} for short) is a function $\tau:\Se\rightarrow \mathbb{N}\cup\{\infty\}$ such that:
\begin{equation*}
    \text{for any}\quad S,S'\in\Se\quad\text{if}\quad S_k=S'_k\quad\text{for}\quad 0\leq k\leq \tau(S),\quad\text{then}\quad \tau(S)=\tau(S').
\end{equation*}

[Lemma 24 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] Let $1\le q<\infty$.  If $a_n\to a$ and $c_n\to c$ in $[0,1]$, then
\begin{equation}   \norm{J(a_n,c_n)-J(a,c)}_{L^q[0,1]}\longrightarrow0.   
\end{equation}
Moreover,
\begin{equation}   \norm{J(a,c)}_{L^q[0,1]}=|c-a|^{1/q},   \qquad   \norm{J(a,c)}_{L^\infty[0,1]}\le1.   
\end{equation}

[Cor 6 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $Z$ be a one-dimensional symmetric $\alpha$-stable process with $\alpha \in (1,2)$. Consider two processes, $X$ and $\tilde{X}$, satisfying the SDEs
\begin{align*}
X_t = x_0 + \int_0^t b(X_s) \rd s + \int_0^t \sigma(X_{s-}) \rd Z_s \quad \text{and} \quad \tilde{X}_t = \tilde{x}_0 + \int_0^t \tilde{b}(\tilde{X}_s) \rd s +  \int_0^t \tilde{\sigma}(\tilde{X}_{s-}) \rd Z_s,
\end{align*}
for $t\in[0,T]$ with initial values $x_0, \tilde{x}_0\in\real$.

Suppose the coefficients satisfy the following conditions for some constants $K, k, K'>0$, and $\tilde{\eta} \in [1/\alpha,1]$:
\begin{itemize}
    \item[(i)'] The drift coefficient $b$ is continuous bounded and $\tilde{b}$ is Lipschitz continuous:
    \begin{align*}
       |b(x)|\le K, \quad |\tilde{b}(x)-\tilde{b}(y)|\le K |x-y|. 
    \end{align*}
    \item[(ii)'] The jump coefficients $\sigma$ and $\tilde{\sigma}$ are bounded and H\"older continuous, and $\sigma$ is strictly positive:
    \begin{align*}
       k \le \sigma(x)\le K, \quad |\sigma^\alpha(x)-\sigma^\alpha(y)|\le K|x-y|^\eta,\\
       |\tilde{\sigma}(x)|\le K', \quad |\tilde{\sigma}(x)-\tilde{\sigma}(y)|\le K|x-y|^{\tilde{\eta}}.
    \end{align*}
    \item[(iii)'] The distances between the coefficients are small in the weighted norms defined in \eqref{weighted_norm}:
    \begin{align*}
       B \coloneqq \|b-\tilde{b}\|_{L^1\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1, \quad S \coloneqq \|\sigma-\tilde{\sigma}\|_{L^\alpha\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1. 
    \end{align*}
\end{itemize}
Then, there exists a positive constant $C = C(T, \alpha, K, k)$ such that\\
\noindent (1) Convergence in Expectation:
\begin{align*}
\sup_{t \in [0,T]} \e\left[|X_t-\tilde{X}_t|^{\alpha-1}\right] \le 
 \begin{cases}
    C\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \textrm{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	C\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha,
  \end{cases}
\end{align*}
\noindent (2) Convergence in Probability: For any $h>0$,
\begin{align*}
\p\left(\sup_{t \in [0,T]}|X_t-\tilde{X}_t|^{\alpha-1}>h\right) \le
 \begin{cases}
    \frac{C}{h}\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \text{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	\frac{C}{h}\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha.
 \end{cases}
\end{align*}

