[Prop Concentration_Inequality of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] There exist constants $c,C>0$ such that for all $n\in \mathbb{N}$ the following is true. 
Assume that $X=(X_1,\ldots, X_n)$ are independent standard Gaussian random variables and  $f\colon \mathbb{R}^n\rightarrow \mathbb{R}$  Lipschitz continuous with Lipschitz constant $L>0$. Then, 
\begin{align*}
\mathbb{P}(|f(X)-\mathbb{E}[f(X)]|\ge z )    \le C\exp\left(-cz^2/L^2\right),\qquad \text{ for all }z>0.
\end{align*}

[Proposition 3 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] There exists a unique line ensemble $\hsai = \{\hsai_{i}\}_{i \geq 1}$ on $[0, \infty)$, which satisfies the following properties. Firstly, the line ensemble is ordered, meaning that almost surely
\begin{equation}
\hsai_{1}(t) \geq \hsai_{2}(t) \geq \cdots \mbox{ for all } t \in [0,\infty).
\end{equation}
In addition, if $\mathsf{S} = \{s_1, \dots, s_m\} \subset (0,\infty)$, then the random measure
\begin{equation}
\hsmi(\omega, A) = \sum_{i \geq 1} \sum_{j = 1}^m {\bf 1}\{(s_j, \hsai_i(s_j,\omega) ) \in A\}
\end{equation}
is a Pfaffian point process on $\mathbb{R}^2$ with reference measure $\mu_{\mathsf{S}} \times \mathrm{Leb}$ as in Definition \ref{Def.Measures} and correlation kernel $\hski$, given by
\begin{equation}
\begin{split}
&\hski(s,x; t,y) = \begin{bmatrix}
    \hski_{11}(s,x;t,y) & \hski_{12}(s,x;t,y)\\
    \hski_{21}(s,x;t,y) & \hski_{22}(s,x;t,y) 
\end{bmatrix} \\
&= \begin{bmatrix}
    \hsii_{11}(s,x;t,y) & \hsii_{12}(s,x;t,y) + \hsri_{12}(s,x;t,y) \\
    -\hsii_{12}(t,y;s,x) - \hsri_{12}(t,y;s,x) & \hsii_{22}(s,x;t,y) + \hsri_{22}(s,x;t,y) 
\end{bmatrix},
\end{split}
\end{equation}
where the kernels $\hsii_{ij}, \hsri_{ij}$ are defined as follows. We have
\begin{equation}
\begin{split}
\hsii_{11}(s,x;t,y) = &\frac{1}{(2\pi \im)^2} \int_{\mathcal{C}_{1+s}^{\pi/3}}dz \int_{\mathcal{C}_{1+t}^{\pi/3}} dw \frac{(z + s - w - t)H(z,x;w,y)}{4(z + s + w + t)(z+s)(w+ t)}, \\
\hsii_{12}(s,x;t,y) = &\frac{1}{(2\pi \im)^2} \int_{\mathcal{C}_{1+s}^{\pi/3}}dz \int_{\mathcal{C}_{1+t}^{\pi/3}} dw \frac{(z + s - w + t) H(z,x;w,y)}{2(z+ s)(z + s + w -t)}, \\
\hsii_{22}(s,x;t,y) = &\frac{1}{(2\pi \im)^2} \int_{\mathcal{C}_{1+ s}^{\pi/3}}dz \int_{\mathcal{C}_{1+t}^{\pi/3}} dw \frac{(z - s - w + t)H(z,x;w,y)}{z - s + w - t},
\end{split}
\end{equation}
where we have set 
\begin{equation}
H(z,x;w,y) = e^{z^3/3 + w^3/3 - xz - y w},
\end{equation}
and the contours $\mathcal{C}_{z}^{\varphi}$ are as in Definition \ref{Def.S1Contours}. We also have that 
\begin{equation}
\hsri_{12}(s,x;t,y) = - \frac{{\bf 1}\{s < t\} }{\sqrt{4\pi (t-s)}} \cdot \exp \left(\frac{- (s-t)^4 + 6 (x+ y)(s-t)^2 + 3 (x-y)^2}{12 (s-t)} \right), 
\end{equation}
\begin{equation}
\begin{split}
\hsri_{22}(s,x;t,y) = \frac{H(s,x;t,y) (y-t^2 -x + s^2) }{2\pi^{1/2} (t+s)^{3/2} } \cdot \exp \left(-\frac{(y - t^2 - x +s^2)^2}{4(t+s)}\right).
\end{split}
\end{equation}

[Definition of arXiv:2602.00853, 'Mixing times for the stochastic $p$-Laplace equation'] Let $p\ge 2$. We say that $\{X_t\}_{t\in [0,T]}$ is a \emph{variational solution} to (equation eq:pLaplace of the paper) for initial data $x_0\in H$ if
\begin{enumerate}[(i)]
\item $X\in L^2(\Omega;C([0,T];L^2(U)))\cap L^p([0,T]\times\Omega;W^{1,p}_0(U))$;
\item for any $v\in W^{1,p}_0(U)$, $t\in [0,T]$, $\mathbb{P}$-a.s.
\[\int_U X_t v\,\mathrm{d} z=\int_U x_0 v\,\mathrm{d} z-\int_0^t\int_U |\nabla X_s|^{p-2}(\nabla X_s \cdot \nabla v)\,\mathrm{d} z\, \mathrm{d} s +\int_U v B \, W_t \,\mathrm{d} z.\]
\end{enumerate}

[Theorem th:volume-of-critical-cluster of arXiv:2606.11503, 'Percolation on hierarchical lattices'] There exists constants $d_f$ (referred as the fractal dimension of $\mathcal{C}_{\{a_k, b_k\}}$) and $\uc{c:volume_low}, \uc{c:volume_high} > 0$ such that, at $p_\star$,
  \begin{equation}

    \uc{c:volume_low} d_f^k
    \leq \mathbb{E}_{p_\star}^{k} \big[ |\mathcal{C}_{\{a_k, b_k\}}| \big]
    \leq \uc{c:volume_high} d_f^k.
  \end{equation}
  Moreover, $d_f$ satisfies:
  \begin{enumerate}[\quad a)]
  \item $d_f < |\mathcal{E}_{1}|$,
  \item $d_f > \max \{ \deg^{\mathrm{out}}(a_1), \deg^{\mathrm{in}}(b_1), \deg(a_1) \wedge \deg(b_1) \}$.
  \end{enumerate}
  As a consequence, we obtain an estimate for the annealed one-arm connection probability.
  If $E_k$ denotes an uniformly selected edge in $G_k$, then
  \begin{equation}

    \uc{c:volume_low} \d_{k}(a_k, b_k)^{-\alpha_1}
    \leq \; \mathbb{P}_{p_\star}^{k} \big( E_k \leftrightarrow \{a_k, b_k\} \big)
    \leq \; \uc{c:volume_high} \d_{k}(a_k, b_k)^{-\alpha_1},
  \end{equation}
  where $\alpha_1 = \log \big( |\mathcal{E}_{1}|/d_f \big) / \log \d_{1}(a_1, b_1)$ is called the one-arm exponent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 (Growth estimates of $u$ and $A_s u$) of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Assume $b$ satisfies \eqref{eq:dispt}, $f\in L^\infty (\mR^d)$ with $\|f\|_{L^\infty}\leq 1$. Then 
    \begin{enumerate}[(a)]
        \item There exists a solution $u$ to \eqref{eq:poisson} such that 
        \begin{equation}
            |u(x)|\leq C (1+|x|^{p_0}), \quad x\in \mR^d 
        \end{equation}
        where $C$ only depends on $\Theta$. 
        \item If $b$ also satisfies \eqref{eq:growth}, then for each $s$, $u\in \cX_{s,\eps}$ and $A_s u$ given by \eqref{eq:def_As} satisfies 
        \begin{equation}
            \big| A_s u(x) \big| \leq C  \exp\left(\frac{\kappa}{20d\theta} |x|^\theta\right), \quad x\in \mR^d, 
        \end{equation}
    where $C$ only depends on $\Theta$. 
    \end{enumerate}

[Lemma lem:measure-data-rigorous of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] Let $(Y,\mathrm{d},\mathcal{H}^n,y)$ be a pointed
$\operatorname{RCD}(K,n)$ space, with an integer $n\geqslant 2$, and $K\in\mathbb R$. Let $R>0$, and suppose that $\overline{B}_{\frac{3}{2}R}(y)\neq B_{2R}(y)$, and
\[
 f\in W^{1,2}_{\mathrm{loc}}(B_{2R}(y)),\qquad
 \mathbf{\Delta} f=\sigma,
\]
where $\sigma$ is a finite signed Radon measure on $B_{2R}(y)$.  Then,
for every $1\leqslant q<n/(n-1)$,
\begin{equation}
 \|f\|_{W^{1,q}(B_R(y))}
 \leqslant C\left(\|f\|_{L^1(B_{2R}(y))}+|\sigma|(B_{2R}(y))\right).
\end{equation}
The constant $C$ depends on $q,K,n,R$ and geometric data on $B_{2R}(y)$\footnote{From the proof, one can track down precisely the constants on which this $C$ depends on: those are the constants appearing in (equation eq:P-Lq of the paper), (equation eq:gradient-Lq of the paper), (equation eqn:LinftyL1 of the paper), (equation eqn:Caccioppoli of the paper), and (equation eqn:Ebbasta of the paper).} (upper/lower bounds of volumes of balls of radius $\sim R$, upper/lower bounds of Ahlfors constant on $B_{2R}(y)$, Poincaré/Dirichlet inequality constants...).

[Lemma lem.new of arXiv:2411.07103, 'On a connection between total positivity and Bernoulli stopping problems'] Let $I \coloneqq \{m_1, m_2, \ldots, m_N\}$ be a arbitrary collection of positive integers, where $N \in \mn$.  Define 
	\begin{alignat}{2}
		v(k; I) \coloneqq \sum_{j \in I} s_j(k),\quad k \in \mn.
	\end{alignat} 
If  $\sum_k p_k < \infty$, then $v$ is unimodal.

[Proposition prop:concentration1 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] Let $t\in [0,1)$ and $x\in \mathbb{R}^d$, then for all $f\in \mathcal{H}_1^{\beta-\lfloor \beta \rfloor,\theta}(\mathbb{R}^d)$  we have
    \begin{align*}
    \int \|f(y)-f(tx)\|^2 dp^{t,x}(y) \leq C (1-t^2)^{\beta-\lfloor \beta \rfloor}\log\Big(\big((1-t^2)\wedge 1/2\big)^{-1}\Big)^{-2\theta}.
\end{align*}

[Theorem 2 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that Assumption \ref{Assumption} holds, and let $\ka>0$.
On the one hand:
\begin{enumerate}
\item If $0<\rho<1$, then
$\displaystyle\mbf E\big[\msf Q_\ka(t)\big]\sim\frac{\ka^2\mf b|D|}{(1+\rho)\rho}\,t^{1+\rho}.$
\vspace{5pt}
\item If $\rho=0$, then
$\displaystyle\mbf E\big[\msf Q_\ka(t)\big]\sim-\ka^2\mf b|D|\,t\log(1/t).$
\vspace{5pt}
\item If $-1/2<\rho<0$, then
$\displaystyle\mbf E\big[\msf Q_\ka(t)\big]
\begin{cases}
\sim\frac{\ka^2\mf b|D|}{(1+\rho)\rho}\,t^{1+\rho}
&\text{if }H_0>1/2,\\
=0\quad\text{for all }t>0&\text{if }H_0=1/2.
\end{cases}$
\end{enumerate}
On the other hand, in all cases,
\begin{align}

\sqrt{\mbf{Var}[\msf Q_{\ka}(t)]}\sim \ka\mf c\,t^{H_0}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition RSRI-ujdh-main of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $t \in \mathrm{supp}_t\ w_{q + 1}^{\left( s \right)}$, the Wiener process ${\mathfrak{W}_{q+1}}\left( t \right)$, the velocity ${u_{q + 1}}\left( {t,x} \right)$ and the Nash pressure ${\mathfrak{p}_{q + 1}}\left( {x} \right)$ satisfy
\begin{equation}
{\left\| {{u_{q+1}} } \right\|_0} + {\left\| {{v_{q + 1}}} \right\|_0} + {\left\| {{\mathfrak{p}_{q + 1}}} \right\|_0} \leqslant C  ,
\end{equation}
and
\begin{equation}
{\left\| {{u_{q+1}} } \right\|_N} + {\left\| {{v_{q + 1}}} \right\|_N} + {\left\| {{\mathfrak{p}_{q + 1}}} \right\|_N} \lesssim \delta _{q+1}^{\frac{1}{2}}\lambda _{q+1}^N , \ \ \forall \, N \in \left\{ {1, \cdots ,10} \right\}   . 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma S31L of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Fix $p, \eta, M \in (0, \infty)$ and $\delta_1 \in (0,1/2)$. There exist $N_1 \in \mathbb{N}$ and $\delta > 0$, depending on $p, \eta, M, \delta_1$, such that the following holds. If $n \geq N_1$, $x, y \in \mathbb{Z}$ are such that $x \leq y$ and $|x| \leq M n^{1/2}$, $|y - pn| \leq M n^{1/2}$, $t \in [\delta_1, 1-\delta_1]$, and $a \in \mathbb{R}$, we have
\begin{equation}
\mathbb{P}_{ \operatorname{Geom}}^{0,n, x, y} \left( n^{-1/2} (Q_1(tn) - ptn) \in [a -\delta, a + \delta ]  \right) < \eta.
\end{equation}

