 Assume that $ \Omega_1,\Omega _2$ and the following hold:
 \begin{enumerate}
\item  {There is no stratified quasi critical point $ (t,x)
$  for $ t\in [0,1],x\in $ 
$ Q_i$, or $x\in   Q_{i}^{m} $  {at level }
$u_-$ or $u_+$.}
\item There is no $(t,x)\in [0,1]\times \partial Q_i$ such that $ \nabla F_t(x) = 0$.
\item { For all $ t\in [0,1]$}, there are no two critical points $ x\ne y\in Q_i^m$ of $ F_t$ such that $ x_1= y_1$.
 \item { For $ (t,x)\in [0,1]\times  Q_i^m, \det \text{\rm{Hess}}_{F_t}(x)\ne 0$ if $ \nabla F_t(x) = 0$. }
