[Definition def:JumpHKE of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] Let $\phi_j$ be a scale function.
  For a  regular Dirichlet form $(\mathcal{E},\mathcal{F})$ of pure-jump type, 
  we say that HK($\phi_j$) holds if there exists a heat kernel $p(t,x,y)$ of $(\mathcal{E},\mathcal{F})$
  and 
  there exist a properly exceptional set $\mathcal{N}$ and 
  constants $c_1 ,c_2 > 0$ such that
  for all $t > 0$ and $x,y \in M \backslash \mathcal{N}$,
  \begin{align}
    c_1 p^{(j)}(t,x,y) \le p(t,x,y) \le  c_2p^{(j)}(t,x,y).

  \end{align}
  Here, $p^{(j)}(t,x,y)$ is defined by
  \begin{equation}
    p^{(j)}(t,x,y) := \frac{1}{V(x,\phi_j^{-1}(t))} \wedge \frac{t}{V(x,d(x,y))\phi_j(d(x,y))}, \quad t > 0,x,y \in M.

  \end{equation}

[Proposition 1 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Under Assumptions~\ref{ass:potential} and \ref{ass:coefficient}, there exists a unique \(C^1\) zero-flux stationary density for $\xi$ given by
\begin{equation}
 \pi_\xi(x)=g_\xi^{-1}(\mu_\xi-\V(x)),
\end{equation}
where $\mu_\xi$ is the unique constant satisfying \( \int_{v_\star}^{\infty}g_\xi^{-1}(\mu_\xi-s)m_\V(s)\,\dd s=1 \). Equivalently, $q_\xi(s):=g_\xi^{-1}(\mu_\xi-s)$ solves
\begin{equation}
 q_\xi'(s)=-q_\xi(s)\xi(q_\xi(s)) \quad \text{for} \quad s>v_\star,
\end{equation}
where $a_\xi:=q_\xi(v_\star)$ is chosen to satisfy 
\begin{equation}
\int_{v_\star}^{\infty}q_\xi(s)m_\V(s)\,\dd s=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_9 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $r(A)\geq 3$, $\lambda_{\max}(A)>0$, $\lambda_1,\cdots, \lambda_k$ be as in ((poloi_1 of the paper)) and $r(A)-k$ be even. If
\begin{eqnarray}

t+\mathrm{tr}(A)\ge0,
\end{eqnarray}
then 

\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{-\frac{t+\mathrm{tr}(A)}{2\lambda_{\max}(A)}}\sum_{l=0}^{\frac{r(A)-k}{2}-1}\frac{1}{2^l}\sum_{\substack{i_0,i_1,\cdots, i_k\ge0\\i_0+i_1+\cdots+i_k=l}}\tilde{c}_{i_0,i_1,\cdots, i_k}\Big(\frac{t+\mathrm{tr}(A)}{\lambda_{\max}(A)}\Big)^{i_0}\prod_{j=1}^k\frac{(\frac{-\lambda_j}{\lambda_{\max}(A)})^{i_j}}{(\frac{-\lambda_j}{\lambda_{\max}(A)}+1)^{i_j+\frac{1}{2}}},
\end{eqnarray}
where 
\begin{eqnarray}
\tilde{c}_{i_0,i_1,\cdots, i_k}=\frac{\prod_{j=1}^k(2i_j-1)!!}{i_0!i_1!\cdots i_k!}
\end{eqnarray}
and the double factorial notation is given in ((double_factorial of the paper)).

