[Definition 2 (Regular right edge) of arXiv:2608.27307, '2608.27307'] We call $E_*\in\mb D_0$ a regular right edge of $\bnu$ if
        \begin{align}
                s_{\min}\left(AA^\top-(E_*+g(E_*))(I_M+m(E_*)\Sg)\right) & \geq\tau_0. 
        \end{align}
        $s_{\min}(\cdot)$ denotes the smallest singular value.
        A regular left edge is defined analogously, with the adjacent gap lying to the left of $E_*$.

[Lemma 17 (Second moment under a constrained strongly convex Gibbs law) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:strong-convex-moment}
Let $K\subset\R^d$ be a compact convex set with nonempty interior and let $\theta_0\in\operatorname{int}(K)$. Suppose $U$ is continuously differentiable on a neighborhood of $K$ and $\beta$-strongly convex on $K$. Then for a probability measure $\check\Pi$ on $\R^d$ such that
    \begin{align*}
    \check\Pi(\d\theta)=Z^{-1}\e^{-U(\theta)}\ind_K(\theta)\d\theta,
    \end{align*}
we have
    \begin{align}
    \int\|\theta-\theta_0\|^2\check\Pi(\d\theta)
    \le \frac{2\|\nabla U(\theta_0)\|^2}{\beta^2}+\frac{2d}{\beta}.
    \end{align}

