[Lemma eq:mixture-tail-cost of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:mixture-tail}
For the law in (prop:moment-law of the paper), every \(a>0\) and \(\eta>0\) satisfy
\begin{equation}
 \lim_{N\to\infty}-\frac1N\log
 \mathbb P_\mu\left(\frac\xi{\sqrt N}\in[a,a+\eta]\right)
 =\frac{a^2}{2\sigma^2}.
\end{equation}

[Prop sugra index asymptotics of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\epsilon_1,\ldots,\epsilon_5$ are generic equivariant parameters satisfying the Calabi--Yau condition $\sum_i \epsilon_i = 0$.
    Then, as $u\to 0$, one has the asymptotic expansion
    \begin{multline}

        \log \Exp\left(
            - \frac{\sum_{i=1}^5 (q_i-q_i^{-1})}{\prod_{i=1}^5 (q_i^{1/2}-q_i^{-1/2})}
        \right) \\
        \sim
        - \zeta(3)\,\frac{p_3}{3 e_5}\frac{1}{u^2}
        + \frac{1}{12}\log(u)
        - c
        +
        \sum_{g > 1} \frac{B_{2g-2}}{2g-2}
        \left[
            \frac{\sum_{i=1}^5 \varsigma(2u\epsilon_i)}{\prod_{i=1}^5 \varsigma(u\epsilon_i)}
        \right]_{2g-2}
        u^{2g-2} \,,
    \end{multline}
    where $q_i=\mathrm{e}^{u\epsilon_i}$, $p_3=\sum_{i=1}^5\epsilon_i^3$, $e_5=\prod_{i=1}^5\epsilon_i$, and
    \begin{equation}
        c
        =
        \log \prod_{i=1}^5
        \frac{
        	\Gamma_4(-\epsilon_i;\epsvec{\hat{\imath}})
        }{
        	\rho_4(\epsvec{\hat{\imath}})
        } \,.
    \end{equation}
    Here $\epsvec{\hat{\imath}}=(\epsilon_1,\ldots,\widehat{\epsilon_i},\ldots,\epsilon_5)$, and $\Gamma_4$, respectively $\rho_4$, denote the $4$-fold Barnes Gamma function and the corresponding modular constant. (See (equation eq: Barnes zeta of the paper) and (equation eq: Barnes Gamma and modular constant of the paper).) (Proof in the paper; no proof environment follows the statement in the TeX.)

