[Lemma 19 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $\left(\psi_t^{(1)}\right)_{t\geq 0}$ be a solution to the first equation in \eqref{eq:fast system simplified hopf 2} with $||\bm{\sigma}_1||^2\neq 0$. Consider $\alpha=\alpha(\lambda)\in\C$ such that $\underset{\lambda\to\lambda^*}{\lim} \alpha(\lambda)=\alpha(\lambda^*)\in i \R\setminus\{0\}$. Then, it holds that
\begin{align}
    \left| \frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)} - e^{-i \operatorname{Im}(\alpha(\lambda))\tau} \right| = -\operatorname{Re}(\alpha(\lambda)) \tau \Delta(\tau) + \mathcal{O}\left( \operatorname{Re}(\alpha(\lambda))^2 \right) ,
\end{align}
with $\Delta(\tau)\neq 0$ for almost every $\tau \geq 0$. In particular, for almost every $\tau\ge0$, we have that
\begin{align*}
    &\frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)}
    = e^{-i \operatorname{Im}(\alpha(\lambda^*))\tau} 
    + \cO \left(\operatorname{Re}(\alpha(\lambda))\right) + \cO\left( \operatorname{Im}(\alpha(\lambda)-\alpha(\lambda^*))\right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm comparison of arXiv:2605.14910, 'Sharp Phase Transition for the Formation of Infinite Tubes'] Let $1\le k\le d-1$.
  Then
  \begin{equation}
  p_c^{\mathrm{core}}(k,d)
  \le p_c^{\mathrm{tube}}(k,d)
  \le1-p_c^{\mathrm{shield}}(k+1).
  \end{equation}
  Moreover, $p_c^{\mathrm{tube}}(1,d)=p_c^{\mathrm{bond}}(d)$, and
  \begin{equation}
  p_c^{\mathrm{tube}}(k,d)
  <1-p_c^{\mathrm{bond}}(k+1)\quad\text{for $k\ge9$.}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2604.01852, 'The on/off Brownian snake'] Fix $s > 0$ and let $x=(b,s') \in E$ with $s'<s$. We define the time changes
\begin{equation*}
    \eta(s,u,i) \coloneqq \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0\}} dr > u\Big\};
\end{equation*}
\begin{equation*}
    \eta(s,u,i, \rm a) \coloneqq \it \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0, A^i_r(s) = 1\}} dr > u\Big\};
\end{equation*}    
\begin{equation*}
    \eta(s,u,i, \rm d) \coloneqq \it \inf \Big\{ t' \geq 0: \int_{r=0}^{t'} \mathbbm{1}_{\{\text{Res}^i_r(s) > 0, A^i_r(s) = 0\}} dr > u\Big\}.
\end{equation*}
Then the maps $u \mapsto \text{Res}^i_{\eta(s,u,i)}(s)$, $u \mapsto \text{Res}^i_{\eta(s,u,i, \rm a)}(s)$ and $u \mapsto \text{Res}^i_{\eta(s,u,i, \rm d)}(s)$ are stopped reflecting Brownian motions $\mathbb{N}_x$-a.e. Furthermore we have that the local times of $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$, $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$ and $(\text{Res}^i_{\eta(s,u,i, \rm d)}(s))_{u \geq 0}$ at level $0$, denoted by $\hat{\ell}_{s,i}$, $\hat{\ell}^{\rm a}_{s,i}$, $\hat{\ell}^{\rm d}_{s,i}$, are such that 
    \begin{equation*}
        \mathbb{N}_x\Big(\hat{\ell}_{s,i}(\infty)\Big) = \mathbb{N}_x\Big(\hat{\ell}^{\rm a}_{s,i}(\infty)\Big) +  \mathbb{N}_x\Big(\hat{\ell}^{\rm d}_{s,i}(\infty)\Big) = 1.
    \end{equation*}
    \begin{proof}
        Consider the open set $D=\mathbb{R}^d \times [0,s)$ in the setting of Lemma \ref{lemma snake exit open set general}. In this setting the process $(U_{\eta_r}, r \geq 0)$ is exactly the process given by $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$ as
        \begin{equation*}
            \tau^s(X_t) = \inf \{r \geq 0 | (B_t(r), S_t(r)) \notin \mathbb{R}^d \times [0,s)\} = \inf \{r \geq 0 |  S_t(r) \geq s \} = H_t(s),
        \end{equation*}
        and because the Residual process is the difference between the excursion $\zeta^i_t$ and the age process $H^i_t(s)$.
        \par
        Now instead consider the set $D=\mathbb{R}^d \times [0,\infty) \backslash \{s\}$ in the setting of the previous lemma. In this instance the process $(U_{\eta_r}, r \geq 0)$ is exactly the process given by $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$  
        \begin{equation*}
            \tau^s(X_t) = \inf \{r \geq 0 | (B_t(r), S_t(r)) \notin \mathbb{R}^d \times [0,\infty) \backslash \{s\} \} = \inf \{r \geq 0 | S_t(r) = s\}, 
        \end{equation*}
        i.e. if the subordinator $S_t(\cdot)$ can take the value $s$, then the particle is in the active state.
        \par
        The final case follows as 
        \begin{equation*}
            \text{Res}^i_t(s) = \text{Res}^i_t(s)\mathbbm{1}_{A_t(s) = 0} + \text{Res}^i_t(s)\mathbbm{1}_{A_t(s) = 1}
        \end{equation*}
        and so the process $(\text{Res}^i_{\eta(s,u,i, \rm d)}(s))_{u \geq 0}$ is a reflecting Brownian motion as it is defined by first taking the process $(\text{Res}^i_{\eta(s,u,i)}(s))_{u \geq 0}$ and removing excursions that correspond to $(\text{Res}^i_{\eta(s,u,i, \rm a)}(s))_{u \geq 0}$. For the final part we use \eqref{equation local time contribution} and note that
        \begin{equation*}
            \mathbb{N}_x\Big(\hat{\ell}_{s,i}(\infty)\Big) = P^\xi_x\Big(\inf(\{y: S(y) \geq s\})<\infty \Big) = 1 >  P^\xi_x\Big(\inf(\{y: S(y) = s\})<\infty\Big) = \mathbb{N}_x\Big(\hat{\ell}^{\rm a}_{s,i}(\infty)\Big),
        \end{equation*}
        where the inequality can be seen in e.g. \cite[Theorem III.5]{bertoin1996levy} and where $S$ denotes the subordinator component of $\xi$. Furthermore we have that 
        \begin{equation*}
            \mathbb{N}_x\Big(\hat{\ell}^{\rm d}_{s,i}(\infty)\Big) = 1 - P^\xi_x(\inf(\{y: S(y) = s\})<\infty) = P^\xi_x(\inf(\{y: S(y) = s\})=\infty) \in (0,1),
        \end{equation*}
        where we note that the final probability is in $(0,1)$ as the subordinator can either cross or hit level $s$, see e.g.\ \cite[Theorem III.5]{bertoin1996levy}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 of arXiv:2601.16377, '2601.16377'] Given an equilibrium measure $\boldsymbol{\mu}$, the $h$-th \emph{effective potential} is the function of $x \in [\hat{a}'_h,\hat{b}_h']$ defined through
 \begin{equation}
 V^{{\textnormal{eff}}}_h(x)= V_h(x) - \sum_{g =1}^H 2\theta_{h,g}
\int_{\hat a'_{g}}^{\hat b'_g} \log|x-y|\mu_{g}(y)\dd y.
\end{equation}

[Defn 25 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $  {\boldsymbol v}\in \mathbb R^d$. We define the function $\z_{  {\boldsymbol v}}:I\to \mathbb R$ by 
    \begin{equation*}
         \z_{  {\boldsymbol v}}(   y_1-   y_2) :=\sum_{\substack{r_1+...+r_d=p\\s_1+...+s_d=p}}\frac{  {\boldsymbol v}^{   r+   s}}{   r!   s!}\boldsymbol \eta_{   r,   s}(   y_1-   y_2).
    \end{equation*}

[Proposition \cite{lawler80selfavoiding} of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Two-sided LERW $\hat\eta$ satisfies the following properties:
\begin{enumerate}
	\item the law $\hat\eta$ is absolutely continuous with respect to the law of $\eta$;
	\item $T^k\eta$ converges weakly to $\hat\eta$ as $k\rightarrow\infty$;
	\item $\hat\eta$ is stationary with respect to $T$, i.e., $T\hat\eta\stackrel{d}{=}\hat\eta$;
	\item $\eta$ and $\hat\eta$ are ergodic with respect to $T$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sobolev of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] On the unit sphere $\mathbb S^{N-1}$, for any $g \in W^1_2(\mathbb S^{N-1})$, we have the Sobolev inequality
    \begin{align*}
        \left\lVertg\right\rVert_q^2\leq \frac{q-2}{N-1} \left\lVert\nabla g\right\rVert_2^2+\left\lVertg\right\rVert_2^2\,,
    \end{align*}
    where $q=\frac{2(N-1)}{N-3}$.    
    Switching to $\mathbf{S}_N$, for any $f\in W^1_2(\mathbf{S}_N)$, 
    \begin{align*}
        \left\lVertf\right\rVert_q^2\leq \frac{N(q-2)}{N-1} \left\lVert\nabla f\right\rVert_2^2+\left\lVertf\right\rVert_2^2\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 39 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $\varepsilon\in (0,1)$ and $z\in D$.
On the event $\{\ell_{0,b}(z) = b,\, 2\pi V_{A_{0,b}}(z)<\vert \log\varepsilon\vert\}$,
\begin{displaymath}
\PP(z\in \Ns_{\varepsilon}(A)\vert A_{0,b},\ell_{0,b}) =
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\psi_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}.
\end{displaymath}
On the event $\{\ell_{0,b}(z) = b, \CR(z,D\setminus A_{0,b})\in (\varepsilon,\varepsilon^{-1})\}$,
\begin{displaymath}
\PP(z\in \widetilde{\Ns}_{\varepsilon}(A)\vert A_{0,b},\ell_{0,b}) =
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\tilde{\psi}_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Wasserstein SN approximation of the Wishart law) of arXiv:2606.28678, '2606.28678'] Let $\alpha\in (d-1,\infty)$ and $\Sigma\in \mathcal{S}_{++}^d$. Let $\mathfrak{W}\sim \mathcal{W}_d(\alpha,\Sigma)$, and let $\mathfrak{Z}_{\alpha,\Sigma}$ be defined as in \eqref{eq:Z.alpha.Sigma}. Let $\mu_{\mathfrak{W}}$ and $\mu_{\mathfrak{Z}_{\alpha,\Sigma}}$ denote the laws of $(\mathfrak{W} - \alpha \Sigma)/\sqrt{\alpha}$ and $(\mathfrak{Z}_{\alpha,\Sigma} - \alpha \Sigma)/\sqrt{\alpha}$, respectively, on $\mathcal{S}^d$. Then
\begin{equation}
d_{\mathrm{W}}^{\mathcal{S}}(\mu_{\mathfrak{W}},\mu_{\mathfrak{Z}_{\alpha,\Sigma}}) \leq \frac{1}{\sqrt{\pi \alpha}} \, \|\Sigma^{-1}\|_2 \, \sqrt{\{(d + 2)\tr(\Sigma)^2 + \|\Sigma\|_F^2\} \{\tr(\Sigma)^2 + \|\Sigma\|_F^2\}}.
\end{equation}
The $\alpha^{-1/2}$ rate in the bound (\ref{eq:Wishart.shifted.symmetric.normal.bound}) is optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 ({\cite{mingoFreeProbabilityRandom2017}}) of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] If $\{\mu_n\}_{n\in\mathbb N}$ is a sequence of probability measures on $\mathbb R$ such that
\begin{equation*}
G_{\mu_n}(z)\to G_\mu(z), \qquad z\in\mathbb C^{+},
\end{equation*}
for some probability measure $\mu$ on $\mathbb R$, then $\mu_n$ converges weakly to $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 (Hard-Edge Limit) of arXiv:2511.12623, 'The eigenvector bead process'] We have, almost surely,
\[
\lim_{N \to \infty}
\left(
\frac{1}{4N}
+ 
\sum_{j \in \mathbb{Z}} \frac{\gamma_j^{N}}{\mu_j^{N} - z}
- 
\frac{\Gamma_N}{z}
\right)
=
\sum_{j \in \mathbb{Z}} \frac{\gamma_j}{\mu_j - z}
- 
\frac{\chi_{\alpha}}{z},
\]
for all $z \in \mathbb{R} \setminus \{\mu_j\}_{j \in \mathbb{Z}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:lack of detailed balance of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$ is a chemical system with sources and sinks. Assume that the system $(\Omega , \mathcal R, \mathcal K ) =(\Omega, \mathcal R , \emptyset ,  \mathcal K, \emptyset ) $ without sources and sinks satisfies the detailed balance condition.  Let $\mathcal B_{\mathcal W_r} = \{ w_k \}_{k =1}^{|\mathcal W_r |} $ be a basis for the space of the cycles of $(\Omega , \mathcal R, \mathcal K )$ and let $\mathcal B_{ \mathcal W} =  \{ w_k \}_{k =1}^{|\mathcal W |} $ be a basis of the space of the cycles of  $(\Omega, \mathcal R , \mathcal R_s ,  \mathcal K, \mathcal K_s )$. Assume that 
 \begin{equation} 
 |\mathcal W| >  |\mathcal W_r |. 
 \end{equation}
 Then for every $w \in \mathcal W$ such that $ \pi_{ \mathcal R } w \notin \mathcal W_r $, it holds that 
 \begin{equation} 
 \Delta (w)= (E- D)^T \mathbb S_r \pi_{\mathcal R }  w
 \end{equation}
where $E \in \mathbb R^M $ is a solution to \begin{equation} 
 S_\rho^T  E = \ln \left( \dfrac{ K_{ - \rho} }{ K_{  \rho } }  \right)  \ \forall \rho \in \{ 1, \dots, r \}   
\end{equation} 
and where $D \in \mathbb R^M $ is the vector 
\[
D(k)= \begin{cases} &\log \left( \frac{\alpha_k }{ \beta_k } \right), \quad k \in \{ 1, \dots, |\Omega_c | \}   \\
& 0, \quad   k \in \{|\Omega_c | +1 , \dots , M \}. 
\end{cases}
\]

