body:
[Lemme 28 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] One has the upper bound

\beq

\mc{I}(\bs{\la}^+_N ; \veps_N)  \, \leq \,  \pl{\vsg = \pm}{} \Big\{  \f{ \mc{S}^{\vsg}   }{ \Delta(\bs{\lambda}_N^{\vsg}) } \Big\}^{\f{1}{2}}

\enq

with $\mc{S}^{\vsg} $ expressed as a combinatorial sum of determinants

\begin{align}

\mc{S}^{\vsg}\overset{\mathrm{def}}{=} \hspace{-5mm}

\sul{ \bs{\sg}_{N-1} \in \{ 0, 1\}^{N-1} }{} | \det_N\big[ \op{M}_{ \bs{\sg}_{\small N-1} }^{\, \vsg} \big]  |

\end{align}

involving the $N\times N$ matrix  $\op{M}_{ \bs{\sg}_{\small N-1} }^{\, \vsg}$ having entries

\beq

\big( \op{M}_{\bs{\sg}_{N-1}}^{\, \vsg}\big)_{ij} \overset{\mathrm{def}}{=} \left\{ \ba{c c c }

\Int{\mathcal{K}_j^{\sigma_j}}{} \frac{\mu - \lambda_{j+\sigma_j}^{\vsg} }{ \mu - \lambda_i^{\vsg} }

\frac{1}{\big\{ (\mu - \lambda_{j+\sigma_j}^+) (\mu - \lambda_{j+\sigma_j}^-) \big\}^{ 1/2 }  } \, \mathrm{d}\mu   & for & j \leq N-1   \vspace{3mm} \\

1 & for & j = N    \ea \right.  \, .

\enq (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 35 (One-dimensional block integral) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $x:[0,T]\to\R$ be continuous and of bounded variation, and let $0\leq a<b\leq T$.
For $n\geq 0$,
\begin{equation}
\int_{a<s_1<\cdots<s_n<b}
\dd x_{s_1}\cdots\dd x_{s_n}
 =\frac{(x_b-x_a)^n}{n!}.
\end{equation}

[Lemma 42 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $x,y\in\bbR$ be deterministic.  With positive probability, $\eta_x^\rmW$ hits  $\bbR+i\tau$. Under this event, almost surely, the following holds:
  \begin{enumerate}[(i)]
      \item  $\eta_x^\rmW$ is disjoint from $\bbR+i\tau$ except for its ending point. Furthermore, $\eta_x^\rmW$ is disjoint from $(x,\infty)$, and  if $\kappa\in(0,2]$, then $\eta_x^\rmW$ is also disjoint from $(-\infty,x)$;
      \item $\eta_x^\rmW$ is disjoint from all of its translates $\{\eta_x^{\rmW}+k:k\in\bbZ\}$;
      \item  For  each connected component $D$ of $\cS_\tau\backslash (\cup_{k\in\bbZ}(\eta_x^\rmW+k) )$, $h^\rmS|_D$ has the conditional law as a zero boundary GFF on $D$ plus a harmonic function which is equal to $h^\rmS$ on $\partial D\cap\partial \cS_\tau$ and has flow line boundary conditions on $\partial D\cap (\cup_{k\in\bbZ}(\eta_x^\rmW+k))$. 
      \item We have  $\eta_y^\rmW$ hits $\bbR+i\tau$, and $\eta_{y+i\tau}^\rmE$ hits $\bbR$.
      \item The same conclusion holds for the conditional law of $h^\rmS$ given $\eta_{y+i\tau}^\rmE$ in connected components of $\cS_\tau\backslash (\cup_{k\in\bbZ}(\eta_{y+i\tau}^\rmE+k) )$ as in part (iii).
  \end{enumerate}

[Definition def:not:linGrowth of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(\mu, \gamma)$ be a solution to the $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$ satisfying Assumption (as:results:lyapunov of the paper) and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. We call $(\mu, \gamma)$ a \emph{linear growth solution} to the $\kappa$-MLFE{} if
there exists $C \in (0, \infty)$ depending only on $( \kappa, d, T, b, \lambda)$ such that\begin{equation}

        \sup_{t \in [0, T]} \operatorname*{\bar{\mu}_t-ess\,sup}_{x, y \in \ensuremath{\mathbb{R}}^d} \frac{|\gamma(t, x, y)|} {1 + |x| + |y|} \leq C.
    \end{equation}
    We say that the $\kappa$-MLFE{} with potentials $(U, W)$ is \emph{well-posed} if for all $\lambda \in \mathcal{Q}_{\kappa, d}$ there is a linear growth solution to the $\kappa$-MLFE{} on $[0, \infty)$ with initial condition $\lambda$ that is unique among the class of linear growth solutions.

[Lemma 17 of arXiv:2606.01881, '2606.01881'] For every $a\in(0,1]$,
\begin{equation}
        \sup_{p\in[a,1]}\Pp\bigl(\exists j\ge2^M:D_j^c\bigr)\longrightarrow0,
        \qquad M\to\infty.

\end{equation}

