[Thm 9 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] The triple $\left(K_{E},P,V\right)$ is a minimal
Naimark dilation of $E$. That is, 
\begin{equation}
E\left(B\right)=V^{*}P\left(B\right)V,\qquad B\in\mathcal{B}\left(\Omega_{m}\right),
\end{equation}
and 
\begin{equation}
K_{E}=\overline{span}\left\{ P\left(B\right)Vh:B\in\mathcal{B}\left(\Omega_{m}\right),\ h\in H\right\} .
\end{equation}

[Lemma 6 of arXiv:2607.17396, '2607.17396'] Let $\left\{X_{k},k\geq 0 \right\}$ be the critical branching processes with strictly stationary immigration. If $\mathbf{E}X_{0}^{2}<\infty$, $\sigma^{2}<\infty$ and $b^{2}<\infty$, then for all $k\geq 1$, we have
\begin{equation}
\mathbf{E}(X_k\mid \mathfrak F_{k-1})=X_{k-1}+\eta_{k},
\end{equation}
\begin{equation}
\mathbf{E}(X_k)=\mathbf{E}(X_{k-1})+\lambda = \mathbf{E}(X_0)+\lambda k,
\end{equation}
\begin{equation}
\operatorname{Var}(X_{k}\mid \mathfrak F_{k-1})
=\mathbf{E}(M_{k}^{2} \mid \mathfrak F_{k-1})
=\sigma^{2} X_{k-1}+\nu_{k},
\end{equation}
\begin{equation}
\operatorname{Var}(X_{k})
=\operatorname{Var}(X_{k-1})
+\sigma^{2}\mathbf{E}(X_{k-1})
+\sigma^{2}
+2 \operatorname{Cov}(X_{k-1}, \eta_{k}),
\end{equation}
\begin{equation}
\mathbf{E}(M_{k}^{2})
= \sigma^{2} \mathbf{E}(X_{k-1})
+\mathbf{E}\nu_{k}.
\end{equation}

[Lem mix_mom of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For $I^{(n)}$ as in Corollary (clt:I_n of the paper) we have
    \begin{align*}
    \,{\mathbb{E}}\left[{I_i^{(n)}}\left(I_i^{(n)}-1\right)\right]=\frac{n(n-1)}{m^2}
    \end{align*}
    and
    \begin{align*}
        \,{\mathbb{E}}\left[I_i^{(n)}I_j^{(n)}\right]=\frac{n(n-1)}{m^2} \text{ for } i \neq j.
    \end{align*}

