body:
[Cor P-U-T-U of arXiv:2609.01300, 'Virasoro Constraints for Orbifold Curves'] The following commutators hold:
\begin{align}
  [P(x),U(y)]&=xyP(x+y),\\
  [T_a(x),U(y)]&=xy\left(1+\frac{y}{x}\right)^{a/r-1}T_a(x+y).
\end{align}
In particular, for $m,k\geq 0$, we have
\begin{align}
  [P_m,U_k]&=\frac{(m+1)_k}{k!}P_{m+k-1},\\
  [T_{m,a},U_k]&=\frac{(m+a/r)_k}{k!}T_{m+k-1,a}.

\end{align}

[Theorem 10 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose Assumptions \ref{assm_big1} and \ref{ass:unper} hold. Suppose $X$ satisfies the bounded support condition (\ref{eq_support}) with $n^{-1/2}\le q\le n^{-\tau}$ for some constant $\tau>0$. 
 Fix $C_0>1$ and let $0<c_0<\wt c$ be a sufficiently small constant where $\wt c$ is defined in Lemma \ref{lem_mbehavior}.
Then the following estimates hold for any constant $\e>0$. 
\begin{itemize}
\item[(1)] {\bf Anisotropic local law}: For any $z\in  S(c_0,C_0,\epsilon)$ and deterministic unit vectors $\mathbf u, \mathbf v \in \mathbb C^{p+n}$,
\begin{equation}

\left| \langle \mathbf u, G(X,z) \mathbf v\rangle - \langle \mathbf u, \Pi (z)\mathbf v\rangle \right| \prec q+\Psi(z).
\end{equation}
\item[(2)] {\bf Averaged local law}: For any $z \in S(c_0, C_0, \epsilon)$,  we have
\begin{equation}

|m_1(z)-m_{1c}(z)|+|m_2(z)-m_{2c}(z)|+|m(z)-m_c(z)|\prec  \frac{q^2}{\sqrt{\kappa+\eta}}\wedge q +\frac{1}{n\eta}.
\end{equation}
\end{itemize}
The above estimates are uniform in $z$ and any set of deterministic unit vectors of cardinality $n^{\OO(1)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 27 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] We use the notation in \Cref{notation:log-dR}.
  Then the canonical morphism
  \begin{equation*}
    \pi\colon X^{(1)} \to  X'
  \end{equation*}
  induced from the structure morphism \(S\to\Spec(k)\) is the coarse moduli morphism of \(X^{(1)}\).

  Moreover, let \(\bar{x}\to X'\) be a geometric point lying on precisely the components \(D_{i_1}',\ldots,D_{i_r}'\), where \(D_i'\) is the pullback of \(D_i\) to \(X'\).
  Then the fiber of \(X^{(1)}\) over \(\bar{x}\) has a unique isomorphism class of geometric points, and the stabilizer group scheme of any representative is canonically isomorphic to
  \begin{equation*}
    \prod_{a=1}^r\mu_p\cong\mu_p^r.
  \end{equation*}

