&=(\|\widehat{{\bf K}}\|_{\infty}+\lambda_D)\|f\|_2^2.
\end{align*}

Now suppose $\lambda_D + I(0)=0$ and that $I(\gamma)=0$ for $|\gamma|<2k$ for some $k\ge 1$.  Then $Q_{j}^{{\bf K}}(f,f)=0$ for $j<2k$. In (equation eq:prelimcovformulafourier of the paper), use the Taylor expansion of $\widehat{{\bf K}}$ to order $2k-1$ as

\[
\widehat{{\bf K}}(z)=\widehat{{\bf K}}(0)+\sum_{\gamma:|\gamma|\le 2k-1}\frac{\partial^{\gamma}\widehat{{\bf K}}(0)}{\gamma!}z^{\gamma} + ...","release_manifest_digest":"sha256:dcfac66bde4b3d3a93651e576c6e8cc626193eaf5084f3eae8d09b05808d7636","revision_digest":"sha256:be1e62a318332422fbe1ac702dbe93d35e1991e9054624eb60536cfcace8d580","source_id":"arxiv:2411.08848","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

