[Proposition 24 (Positive-time smoothing and regular restart) of arXiv:2608.30027, 'Under Ricci flow, a 3-torus goes flat'] Fix \(K_0<\infty\).  There are constants
\[
        \beta_{\mathrm{reg}}>0,\qquad C_{\mathrm{reg}}<\infty,
        \qquad \Lambda_{\mathrm{reg}}<\infty,
\]
depending only on \(K_0,N,\sigma\), with the following property.

\medskip
\noindent\textbf{Hypotheses.}
Let \(r(\tau)\), \(1\leq\tau\leq100\), be an invariant Ricci flow satisfying
\begin{equation}
        |\sec_{r(\tau)}|\leq K_0/\tau.
\end{equation}
Let \(q(\tau)\) be a Ricci--DeTurck flow relative to \(r(\tau)\) and assume
\begin{equation}
        \|q-r\|_{X_r^N[1,100]}\leq\beta_{\mathrm{reg}}.
\end{equation}

\medskip
\noindent\textbf{Rescale and average.}
Put
\[
        q^+(1)=100^{-1}q(100),\qquad
        \rho^+=100^{-1}r(100),\qquad
        r^+(1)=\overline{q^+(1)}.
\]

\medskip
\noindent\textbf{Conclusion.}
Then \(r^+(1)\) is Riemannian,
\[
        \BG_N(\rho^+;\Lambda_{\mathrm{reg}}),\qquad
        \BG_N(r^+(1);\Lambda_{\mathrm{reg}}),
\]
and
\begin{equation}
\begin{split}
 &\|q^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}
 +\|r^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}\\
 &\qquad\leq C_{\mathrm{reg}}
 \|q-r\|_{C^0(M\times[1,100],r)}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

