[Thm 21 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Let $T>0$. Assume that assumptions \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2}, \ref{H3} and conditions
\begin{align*}
&\beta+\delta<\frac12\min\{\alpha,1-\alpha\},\\
&\theta>\max\left\{\frac23,\frac{2\delta+(2\alpha-1)\vee0}{2\delta+\alpha}
\right\},\\
&\phantom{a}\notag\\
&\begin{cases}
\vspace{5pt}
\displaystyle\sum_{k=1}^{ \infty}\mu_k^{2\beta+1-\alpha(1+3\theta)}<\infty, &{\rm if }\;\; \alpha\in \left(0,\frac12\right],\\[1mm]
\displaystyle\sum_{k=1}^{ \infty}\mu_k^{2\beta+1-2\alpha+(1-\alpha)(1-3\theta)}<\infty, &{\rm if }\;\; \alpha\in \left[\frac12, \frac34-\frac\delta2\right], \\[1mm]
\displaystyle\sum_{k=1}^\infty\mu_k^{2\beta-1+2\delta(1-\theta)+\alpha(1-\theta)}<\infty, &{\rm if }\;\; \alpha\in\left[\frac34-\frac\delta2,1\right),
\end{cases}
\end{align*}
are satisfied. Then pathwise uniqueness for \eqref{abstract_formulation} holds.

[Lem 8 (Absorbed Euler limit) of arXiv:2607.28078, '2607.28078'] Let $D\subset\mathbb R^d$ be open with compact closure. Suppose that $b$ and $\sigma$ are bounded on $[0,T]\times\overline D\times\mathcal{M}$ and continuous in $(x,\mu)$ there, where $\mathcal{M}$ is a compact set of probability measures supported by $\overline D$. Let the mesh sizes of a sequence of partitions converge to zero. Let $(X^n,B^n)$ be the absorbed Euler concatenations of Lemma~{\rm \ref{lem:splicing}}, with $\mathcal L_{X^n(0)}=\nu_0$ and with all their marginal laws in $\mathcal{M}$. Then there exist a subsequence, a stochastic basis $(\Omega,\mathcal{F},\{\mathcal{F}_t\},\mathbb{P})$, an $m$-dimensional Brownian motion $B$, a continuous adapted process $X$, and a stopping time $\theta$ with values in $[0,T]\cup\{\infty\}$ such that
\begin{equation}
X(t)=X(0)+\int_0^t\mathbf1_{\{r<\theta\}}b\bigl(r,X(r),\mathcal{L}_{X(r)}\bigr)dr+\int_0^t\mathbf1_{\{r<\theta\}}\sigma\bigl(r,X(r),\mathcal{L}_{X(r)}\bigr)dB(r),\,\,0\leq t\leq T,
\end{equation}
and
\begin{equation}
X(t)=X(t\wedge\theta),\,\,
X(\theta)\in\partial D\quad\hbox{on }\{\theta\leq T\}.
\end{equation}
In general, $\theta$ need not be the first exit time of $X$ from $D$.

[Lem lem_ballInequalityImpliesLebesgue of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $X$ be a random variable in $\mathbb{R}^d$. Let $A\subseteq \mathbb{R}^d$ be an open set and suppose there exist constants $c_A>0$ and $\varepsilon_A > 0$ (that may both depend on $A$), such that for all $0<\varepsilon<\varepsilon_A$ and all $x\in A$ we have
    \begin{align*}
        \prob{X\in \mathcal{B}_\varepsilon (x)} \leq c_A ~ \varepsilon^d.
    \end{align*}
    Then the distribution of $X$ is absolutely continuous with respect to  the Lebesgue measure on $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $k$ be a positive integer and let $Y_k$ be a random variable distributed according to $p_k$ as given in \eqref{b1}.
		Let $(W, W')$ be an exchangeable pair of random variables satisfying \eqref{nonlinear2} and let $\Delta=W-W'$. 
		Then for any $a>0$, $p\ge 2k-1$ and $z\in\mathbb{R}$, we have
		\begin{equation*}
			\begin{split}
				&|\P(W\le z) - \P(Y_k\le z)| \\
				&\le\frac{B^p(p^{p/k}+\E |W|^{2p})}{(1+|z|)^{p} } \left(\sqrt{\E\left( 1- \frac{1}{2\lambda}\E({\Delta}^2|W)\right)^2} +\dfrac{\sqrt{\E R^2}}{\lambda} 
				+  a +\frac{ a^3}{\lambda}+ \dfrac{\sqrt{\E\Delta^4\mathbf{1}(|\Delta|>a)}}{\lambda}\right),
			\end{split}
		\end{equation*}
		where $B$ is a constant which depends only on $k$ and $a_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition ex2 of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $\epsilon_2(\kappa_N,z)$ be the error term and $\mathcal{V}(\omega_N,\zeta)$ be the controlling function introduced before. Then for any $\delta\in(0,1)$, we have $\mathcal{V}(\omega,\zeta)$ is bounded for any $\omega\in[\delta,2-\delta]$ and $s\in\left[s_0,\frac{2\mu_{n,N}}{3\sigma_{n,N}}\right]$ when $N$ is large. Hence, the error is controlled by
    \begin{equation}
        |\epsilon_2(\kappa_N,z)|\le C(\delta)\frac{\mathbf{M}\left(\kappa_N^\frac{2}{3}\zeta\right)}{\kappa_N\mathbf{E}\left(\kappa_N^\frac{2}{3}\zeta\right)}
    \end{equation}
    for some constant $C(\delta)$ determined by $\delta$ when $N$ is large under our assumption.

[Lemma 29 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] For every $x>b_N$,
\begin{equation}
\E\left[D_N(x)\1_{\{\lambda_1<x,\ \lambda_3\ge b_N\}}\right]
=
\frac{\mathfrak C_{N+1,N}}{(N+1)\mathfrak C_{N,N}}
 e^{Nx^2/4}r_N(x).
\end{equation}

