\item If $\rho>0$, for every $t>0$, there exists a random variable $\ga_t(B)$ such that
\begin{align}

\lim_{\eps\to0}\be^\eps_t(B)=\ga_t(B)
\qquad\text{in $L^2$}.
\end{align}
Moreover, for every $c,t>0$, one has
\begin{align}

\sup_{\eps>0}\mbf E\left[\exp\big(c\be^\eps_t(B)\big)\right]\leq\mbf E\left[\exp\big(c\ga_t(B)\big)\right]<\infty.
\end{align}
\item If $\rho\leq0$, for every $t>0$, there exists a random variable $\ga_t(B)$
such that
\begin{align}

\lim_{\eps\to0}\Big(\be^\eps_t(B)-\mbf E\big[\be^\eps_t(B)\big]\Big)=\ga_t(B)
\qquad\text{in $L^2$}.
\end{align}
Moreover, for every $c>0$, there exists $\th_c>0$ such that for every $t\in(0,\th_c)$,
\begin{align}

\sup_{\eps>0}\mbf E\left[\exp\Big(c\big(\be^\eps_t(B)-\mbf E\big[\be^\eps_t(B)\big]\big)\Big)\right]<\infty
\quad\text{and}\quad
\mbf E\left[\exp\big(c\ga_t(B)\big)\right]<\infty.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

