[Lemm 6 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] Let $h \in L^2(\mathbf{N} \times \WW)$ and let $\tau \in (0,1)$. Then $P_\tau h$ satisfies
    \begin{equation}
        \E \int_\WW \int_\WW \left( D_z P_\tau h(\eta,w) \right)^2 \mu(dz)\mu(dw) < \infty.
    \end{equation}
and $P_\tau h \rightarrow h$ in $L^2(\mathbf{N} \times \WW)$ as $\tau \rightarrow 1$. Moreover, for $w,z \in \WW$ and all $p \geq 1$,
\begin{align*}
    \E |P_\tau h(\eta,w)|^p \leq \E |h(\eta,w)|^p\\
    \intertext{and}
    \E |D_zP_\tau h(\eta,w)|^p \leq \E |D_zh(\eta,w)|^p.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$, $t> 0$ and $p\in [1,2]$,
\begin{equation}
    \left\|\left|\grad^k \Pop_t f\right|\right\|_{\Leb^2}^{2} \leq \upe^{-2k\left(p-1\right)t}\left(\upe^{4t}-1\right)^{-k(1-\frac{p}{2})}  \left\|f\right\|_{\Leb^{\infty}}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}.
\end{equation}

