[Proposition prop:poisson_summation_hyperfluctuating of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] There exists a finite positive measure supported on $\mathbb{R}^{+}$ so that
		\begin{equation*}
			s_{\xi_B}(t)-\bar{s}_{\xi_B}(t) = \frac{\sqrt{2\pi}}{t^{1/h}}\int_{0}^{+\infty}\sum_{n \neq 0}\frac{e^{-\frac{1}{2u}(2\pi n+t)^{2}t^{-2/h}}}{\sqrt{u}} \, \mu(\mathrm{d}u).
		\end{equation*}

		Moreover, $\mu$ satisfies
		\begin{equation*}
			e^{-\frac{1}{2}|t|^{2h}} = \int_{0}^{+\infty}e^{-\frac{1}{2}t^{2}u} \,\mu(\mathrm{d}u), \quad t \in \mathbb{R}.  
		\end{equation*}

