[Prop 13 (Randomized measure-valued weak solution) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t,I_t,Z_t)_{t\in[0,T]}$ be a limit point of $(\mu^n_t,I^n_t,Z^n_t)_{t\in[0,T]}$. Then, $\mu=(\mu_t)_{t\in[0,T]}$ is a stochastic process taking values in $\mathcal{M}_{\leq 1}(\R^+)$ with $\mu_0=P_0\circ \theta_{a_0}^{-1}$ and it satisfies
\begin{equation}
\di \langle\mu_t,\phi\rangle	=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\phi}_t,
\end{equation}
for all $t\in[0,T]$ and all $\phi \in C^{2}_b(\R)$, almost surely, with 
\begin{equation}
\E\biggl[\int_0^t H_s \di Z_t^{ \phi}\biggr]
= \lim_{\delta \downarrow 0}  \E\biggl[\int_0^t H_s \bigl( \tfrac{1}{2} \partial_x \phi(0) - \phi(0) \gamma(s, C_s) \bigr)\langle \mu_s, \sigma_A(s, \cdot)^2 \psi_\delta  \rangle \ds \biggr],
\end{equation}
for all $t\in[0,T]$, all $\phi\in C_b^2(\R)$, and
all bounded continuous processes $H$ adapted to the filtration \eqref{eq:limit_filtration} generated by $(\mu,I)$, where
\begin{equation}
A_t = a_0 + \alpha\int_{t-\bar{d}}^t \varrho(t-s) I_{s} \ds,\quad C_t = \int_{t-\bar{d}}^t \varrho(t-s) (I_{s} - I_{s-\bar{d
}})\ds,\quad I_t= 1- \mu_t(\R^+).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Neutrality condition of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] A double divisor $\left(\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right)$ satisfies the neutrality condition $\left(\mathrm{NC}_b\right)$  if 
\begin{equation}
\int\boldsymbol{\sigma}=\int \boldsymbol{\sigma}^{+}+ \int \boldsymbol{\sigma}^{-}=2b.
\end{equation}

[Definition 210 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{F}(z) = (F_h(z))_{h = 1}^H$ is \emph{tame} if for each $h \in [H]$ there exists a complex neighborhood $\amsmathbb{M}_h$ of $[\alpha_h,\beta_h]$ such that
\begin{itemize}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]$;
\item $F_h(x^{\pm}) = \lim_{\epsilon \rightarrow 0^+} F_h(x \pm \ii \epsilon)$ exists for any $x \in (\alpha_h,\beta_h)$;
\item there exists an integer $m_{\boldsymbol{F}}$, called tameness exponent, and a real number $M_{\boldsymbol{F}}$ such that
\[
\sup_{z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]} \big| \big((z - \alpha_h)(z - \beta_h)\big)^{\frac{1}{2}m_{\boldsymbol{F}}} F_h(z)\big| \leq M_{\boldsymbol{F}};
\]
\item the function $x \mapsto F_h(x^+) + F_h(x^-)$ extends to a meromorphic function in $\amsmathbb{M}_h$.
\end{itemize}

[Proposition prop:2s5c-result of arXiv:2411.00930, '\bf \Large Asymptotic Product-form Steady-state for Multiclass Queueing Networks: A Reentr'] Under Assumption~(assumption:2s5c-t-moment of the paper) and~(assumption:multi-scale-2s5c of the paper),
there exist a random vector $(Z_1^\ast, Z_4^\ast)\in\mathbb{R}_+^2$ such that
    \begin{equation*}
        (rZ_1^{(r)}, rZ_2^{(r)}, rZ_3^{(r)}, r^2Z_4^{(r)}, rZ_5^{(r)})\Rightarrow (Z_1^\ast, 0, 0, Z_4^\ast,0),\quad\text{as }r\to0,
    \end{equation*}
    where ``$\Rightarrow$'' denotes convergence in distribution.

   Moreover, $Z_1^\ast$ and $Z_4^\ast$ are independent and have the following marginal distributions
   \begin{equation*}
        Z_1^\ast\sim\exp\big(1/d_1\big),\quad\text{and}\quad Z_4^\ast\sim\exp\big(1/d_4\big),
    \end{equation*}
    with
    \begin{align}
        d_1&=\frac{\alpha_1}{2(m_1+m_3-m_5\frac{m_2}{m_4})}\Big((m_1+m_3-m_5\frac{m_2}{m_4})^2c_{e,1}^2+m_1^2c_{s,1}^2+m_3^2c_{s,3}^2+m_5^2c_{s,5}^2\nonumber\\
        &\qquad\qquad\qquad\qquad\qquad\quad+(\frac{m_5}{m_4})^2\big(m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\big)\Big)\\
        d_4&=\frac{\alpha_1}{2m_4}\Big((m_2+m_4)^2c_{e,1}^2+m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\Big).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] There is a full Harris set $H\in\calX$ such that, for every $x\in H$ and every deterministic sequence $k\to_\lambda\infty$,

\begin{equation*}
\frac{N(k)}{|k|_1}\xrightarrow[k\to_\lambda\infty]{} \rho_\lambda
\end{equation*}

$\Pp_x$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def weighted stable nodal family of arXiv:2609.04023, 'Characterizing Contractions and Weighted Blowdowns'] \begin{enumerate}
    \item Define input data to be a tuple $(g,\mathscr{A}):=(g,a_1,\dots,a_n)$ consisting of an integer $g\ge 0$ and the {\em weight data} $(a_1,\dots,a_n)\in \mathbb{Q}^n$ satisfying $0<a_j\leq 1$ for $j=1,\ldots,n$ and $2g-2+a_1+a_2+\dots +a_n>0$.
    \item A family of nodal curves with marked points $(C,s_1,\ldots,s_n)\xrightarrow{\pi}B$ is stable of type $(g,\mathscr{A})$ if
    \begin{itemize}
        \item the sections $s_1,\ldots,s_n$ lie in the smooth locus of $\pi$,
        \item for any $\{i_1,\dots, i_r\}\subseteq [n]$ such that $\bigcap_{j=1}^{r}s_{i_j}(B)\neq\emptyset$, we have $a_{i_1}+\dots +a_{i_r}\leq 1$ and,
        \item $K_{\pi}+a_1s_1+a_2s_2+\dots +a_ns_n$ is $\pi$-ample.
    \end{itemize}
\end{enumerate}

[Lemma L5 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Suppose that Assumptions (A1 of the paper) and (A3 of the paper) hold. If $\max\{1152e^2(1-\beta)^2 \left(\eta KL\right)^2, 1152e^2(1-\beta)^2 \left(\eta \gamma KL^2\right)^2\} \leq \beta^{2}$, then the following inequality holds:
\begin{equation*}
	\sum_{t=0}^{T-1} \Xi_{s}^t \leq \frac{\beta^{2}}{288 e^2 K^{2} L^{2}} \sum_{t=0}^{T-1}\left(\mathcal{E}_{s}^{t-1}+\mathbb{E}[\|g^{t-1}\|^{2}]\right)+4 \eta^{2}TD^2.
\end{equation*}

[Thm 1 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and consider an initial value
\begin{equation}
    (u^0,w^0)\in W_{p}^{1,+}(\Omega)  \times L_\infty^+(\Omega) \,.
\end{equation}
Then there is a unique couple $(u,w)$ of functions satisfying
\begin{subequations}
\begin{align}
&u \in  C^1\big((0,\infty),L_p(\Omega)\big) \cap  C\big((0,\infty),W_{p,N}^{2}(\Omega)\big)\cap C\big([0,\infty),W_{p}^{1}(\Omega) \big)\,,\\
& w\in C^1 \big([0,\infty),L_\infty(\Omega)\big)\,,\qquad v := \mathcal{K}[w-\langle w\rangle] \in C^1\big([0,\infty),W_{p,N}^{2}(\Omega)\big)\,,
\end{align}
such that $(u,v,w)$ is a global non-negative strong solution to~\eqref{E}.
\end{subequations}
In fact, the mapping 
\begin{equation*}
	\boldsymbol{\Psi}:(u^0,w^0)\mapsto (u,w)
\end{equation*} 
defines a global semiflow on $W_{p}^{1,+}(\Omega) \times L_\infty^+(\Omega)$.  
Moreover, 
\begin{itemize}
    \item  for $t\ge 0$, it holds that
    \begin{equation}
        \|u(t)\|_1 = \|u^0\|_1\,, \quad \|w(t)\|_1 \le \max\big\{ \|w^0\|_1 , \|u^0\|_1 \big\}\,; 
    \end{equation}
	\item  if $u\in L_\infty((0,\infty),L_m(\Omega))$, then $(u,w)\in L_\infty((0,\infty)\times\Omega,\R^2)$;
	\item  if $\Omega=\mathbb{B}_R$  and $(u^0,w^0)$ are radially symmetric, then $(u,v,w)(t)$ are radially symmetric for all $t\ge 0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eq:strong:Markov:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $T$ be a $(\overline{\mathcal{F}}_{t+})$-stopping time such that  $T > 0$, $\mathbf{N}_{x,r}$-a.e. For every non-negative $\overline{\mathcal{F}}_{T+}$-measurable function $\Phi$  and non-negative measurable function $F$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_{f}(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$, we have 
\begin{equation} 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}} \Phi \cdot  F \big( (\rho_{T + s }, \overline{W}_{T + s } : s \geq 0  ) \big)  \big) 
    = 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}}  \Phi \cdot  \mathbb{E}^{\dag}_{\rho_T, \overline{W}_T} [ F ]   \big).  
\end{equation}

[Proposition 2-l05 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on
${\boldsymbol u}^N$, $A$ and the dimension $d$, uniformly bounded in $N$
($\sup_N {\mathfrak c}({\boldsymbol u}^N) < \infty$), such that
\begin{equation*}
\begin{aligned}
& K\, \int  {\mathcal W}^{(2)}_\ell \, f\; d\nu^N \; \le\;
\delta\, N^2 \, I^E_{N}(f; \nu^N)
\; +\; {\mathfrak c}({\boldsymbol u}^N)  \, K\, \sum_{x\in{\mathbb T}_N^d}
\int (\omega^{\ell} _{x})^2 \, f \; d\nu^N
\\
& \;+\; {\mathfrak c}({\boldsymbol u}^N)  \, 
\Big(\frac{K}{N}\Big)^2 \Big\{ \, \frac{1}{\delta}\, \Big[ \, 1 \,+\, 
\frac{K\, s_d(\ell) \,}{N^2} \,\Big] \,+ \,  (1+\lambda)  \Big\} \, \,
\int \sum_{k=1}^d \sum_{x\in{\mathbb T}_N^d} (H^{(\ell)}_{k,x})^2 \, f  \;
d\nu^N
\\
& \quad \;+\; {\mathfrak c} ({\boldsymbol u}^N)\, K^2\, N^{d-2}
\,\Big\{\, \delta \,+\, \frac{s_d(\ell)}{\lambda} \,\Big\} 
\end{aligned}
\end{equation*}
for all $0<\delta<1$, $\lambda>0$, density $f$ with respect to $\nu^N$
and $N> 4\ell$. In this formula, $s_d(\ell)$ is the sequence
introduced in (equation 2-18 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary C:smallball of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose condition (equation E:main of the paper) holds.
  \begin{enumerate}[\rm (i)]

    \item Suppose $\beta\in(0,2)$; or $\beta=2$, $\gamma\in[0,1]$, $\ell<\alpha(\gamma+1/2)$. If $\rho \in (0,1)$,
          then for any compact interval $I\subset (0,\infty)$, there exist two
          constants $0<C_7\le C_7'<\infty$ such that for all $x_0\in \mathbb{R}^d$ and all
          $\varepsilon \in (0, 1)$,
          \begin{align}
            \exp\left( - \frac{C_7'}{\varepsilon^{1/\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{t\in I} |u(t,x_0)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_7}{\varepsilon^{1/\rho}} \right).
          \end{align}

    \item If $\tilde\rho\in (0,1)$, then for any $t_0>0$ and compact rectangle
          $J$ in $\mathbb{R}^d$, there exist two constants $0<C_8\le C_8'<\infty$ such that
          for all $\varepsilon\in(0,1)$,
          \begin{align}
            \exp\left( - \frac{C_8'}{\varepsilon^{d/\tilde\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{x\in J} |u(t_0,x)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_8}{\varepsilon^{d/\tilde\rho}} \right).
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

