[Definition def:polynomial-acceleration of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] A \emph{polynomial acceleration scheme} of degree $m$ is defined by a polynomial $Q_m$ of degree at most $m$ satisfying $Q_m(1) = 1$. The accelerated trajectory is
\begin{equation}
g_k^{\mathrm{acc}} := Q_m(P)^k g_0, \qquad k = 0, 1, 2, \dots
\end{equation}

[Thm persistence of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Assume $(X_{j})_{j \in \mathbb{N}}, (X'_{j})_{j \in \mathbb{N}}$ are defined as in~(equation eq:def-ex of the paper) and Assumption~(ass:gen-ass of the paper) is satisfied. Then, in the process $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$, we have the following: 
    \begin{enumerate}
        \item   If the series $\sum_{i=1}^{\infty} (X_{i} - X'_{i})$ diverges almost surely, then, almost surely, $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$ does not contain a persistent hub.
        \item  Suppose that, for $\alpha > 0$ and $K \in \mathbb{N}$ we have



        \begin{equation} 
             \sum_{j=1}^{\infty} \E{e^{-\alpha \sum_{i=1}^{j} X_{i}}} < 1 \quad \text{and} \quad \prod_{i=K+1}^{\infty}\E{e^{\alpha (X'_{i} - X_{i}) }} < \infty.
        \end{equation}
        Then, almost surely, $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_0}$ contains a persistent hub.  
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn localization of measure of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $\Omega \subsetneq \mathbb{C}$ be a simply connected domain with an interior marked point $u \in \Omega$. Let $z_1, z_2, \ldots, z_n$ denote distinct prime ends of $\partial \Omega$, and let $U_1, U_2, \ldots, U_n$ be closed neighborhoods of $z_1, z_2, \ldots, z_n$ in $\Omega$ such that:
\begin{itemize}
    \item $U_i \cap U_j = \emptyset$ for all $1 \leq i < j \leq n$,
    \item None of the $U_j$ contain the interior point $q$.
\end{itemize}
We consider the measures 
\[
\mathbb{P}_{\left(\Omega; z_1, z_2, \ldots, z_n, q\right)}^{\left(U_1, U_2, \ldots, U_n\right)}
\]
defined on $n$-tuples of unparametrized continuous curves in $\Omega$. Each curve $\eta^{(j)}$ begins at $z_j$ and exits $U_j$ almost surely.

A family of such measures indexed by different choices of $\left(U_1, U_2, \ldots, U_n\right)$ is called \textbf{compatible} if for all $U_j \subset U_j'$, the measure 
\[
\mathbb{P}_{\left(\Omega; z_1, z_2, \ldots, z_n, q\right)}^{\left(U_1, U_2, \ldots, U_n\right)}
\]
is obtained by restricting the curves under 
\[
\mathbb{P}_{\left(\Omega; z_1, z_2, \ldots, z_n, q\right)}^{\left(U_1', U_2', \ldots, U_n'\right)}
\]
to the portions of the curves that remain inside the subdomains $U_j$ before their first exit.

\begin{figure}[ht]
    \centering
    \includegraphics[width=8cm]{Random_3_with_localization.png}
    \caption{Localization of multiple radial SLE($\kappa$)} 

\end{figure}

[Definition 36 of arXiv:2601.16377, '2601.16377'] Let $\boldsymbol{\chi}_{\N}^{(1)}$ and $\boldsymbol{\chi}_{\N}^{(2)}$ be two families (indexed by a large parameter $\N$) of discrete random $K$-dimensional real vectors. We say that the distribution of $\boldsymbol{\chi}_{\N}^{(1)}$ is asymptotically equal to the distribution of $\boldsymbol{\chi}_{\N}^{(2)}$ if
\begin{equation}

 \lim_{\N\rightarrow\infty} \sup_{f \in \textnormal{Lip}_1} \big|\E[f(\boldsymbol{\chi}_{\N}^{(1)})]-\E[f(\boldsymbol{\chi}_{\N}^{(2)})]\big| =0,
\end{equation}
where $\textnormal{Lip}_1$ is the set $1$-Lipschitz functions real-valued functions on $\amsmathbb{R}^K$ that are upper-bounded by $1$. If \eqref{eq_asymptotic_equivalence} holds, we write $\chi_{\N}^{(1)} \stackrel{\textnormal{d}}{\sim} \chi_{\N}^{(2)}$.

