[Theorem thm:lattice of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Assume that $\mathbf E|X|^{r+3}$ is finite for some integer $r \ge 1$.
Assume also that $S_n$ is integer valued with maximal span $1$. Then there exist polynomials $P_1$, $P_2$,\ldots, $P_{r+1}$ such that
\begin{align*}
    \mathbf P(S_n=x,\tau>n) 
=
    e^{-\frac{x^2}{2\sigma^2n}}
    \sum_{\nu = 2}^{r+1}
        \frac{P_\nu(x/\sigma\sqrt{n})}{n^{\nu/2}} 
+
    O\left( \frac{1}{\min (n^{(r+2)/2}, x^{r+2})} \right).
\end{align*}
Every polynomial $P_\nu$ has degree $3\nu-5$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that $(F_n,R_n,\mu_n)\in \bbF_c^{\circ}$ converges to $(F,R,\mu)\in\bbF_c^{\circ}$
  with respect to $d^{\tau,\BL^{\kappa}}_{\frK}$.
We regard $F_n,n\in\N,$ and $F$ as subsets of a common compact metric space $(M,d^M)$.
  Fix $t>0,\;x,y\in F,$ and $x_n,y_n\in F_n$.
Suppose that 
\begin{align*}
  h:=d_{\rm{H}}^M(F,F_n)^{\kappa}+d_{\BL^{\kappa}}^M(\mu,\mu_n)+d^M(x,x_n)+d^M(y,y_n)\le \frac{1}{2}.
\end{align*}
Then we have the following.
\begin{itemize}
  \item [$\mathrm{(i)}$]If $(F,R,\mu)$ satisfies Assumption $\rm{(A1)}$ with $s_0-s_1<1$,
then there exists a constant $E=E(s_0,s_1,\kappa)$ (see \cref{hkest}$\rm{(i)}$ for an explicit formula), and it holds for $\kappa\in [1/2,2/3)$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\mathrm{(ii)}$]If $(F,R)$ satisfies Assumption $\mathrm{(A2)}$ with $s_0-s_1<1$, 
then there exists a constant $E=E(s_0,s_1,\kappa)$ (see \cref{hkest}$\rm{(ii)}$ for an explicit formula), and it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\rm{(iii)}$]If $(F,R)$ satisfies Assumption $\mathrm{(A3)}$, 
then there exist constants $E_1=E_1(s_0,s_1,\kappa)$ and $E_2=E_2(s_0,s_1,\kappa)$ (see \cref{hkest}$\rm{(iii)}$ for an explicit formula), 
and it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^{E_1}(\log(1/h))^{E_2}.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma 4.1 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] [{[Dunlap-Sorensen-2025] and [Rahman-Virag-21]}]
    Fix any $\xi_1<\xi_2$ and $c_1,c_2\in\mathbb{R}$. Then, for any $s\in\mathbb{R}$,
    \begin{equation} 
        \tau^{L,c,\xi_1,\xi_2}_t=\tau^-_{f;p}(t), \qquad \text{and} \qquad\tau^{R,c,\xi_1,\xi_2}_t=\tau^+_{f;p}(t)\qquad \text{for all } t\geq s,
    \end{equation}
    where $p=(\tau^{c,\xi_1,\xi_2}_s,s)$ and $f=f^{\xi_1,\xi_2}_{p}$. In particular, the function $t \mapsto \tau_t^{c,\xi_1,\xi_2}$ is continuous.

