[Theorem thm:qsl-rw2mc of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] {We have the following quadratic strong laws for the fluctuations around the almost sure limit.
\begin{enumerate}
\item[a)] For $p \in \left(0, \frac{11}{16}\right)\cup\left(\frac{113+\sqrt{97}}{128}, 1\right)$,
\begin{align}
    \lim_{n \to \infty} \frac{1}{\log n}\sum_{k=1}^n\left(\frac{S_k}{k}-\Lambda_p\right)^2 
    {= \Sigma^{(1)}_p},
\end{align}
where $\Sigma^{(1)}_p$ is given by (equation eq:sigma1 of the paper).\\
\item[b)] For $p \in \left\{\frac{11}{16}, \frac{113+\sqrt{97}}{128}\right\}$,
\begin{align}
    \lim_{n \to \infty}  \frac{1}{\log\log n}\sum_{k=1}^n\left(\frac{1}{\log k}\right)^2\left(\frac{S_k}{k}-\Lambda_p\right)^2 
    {= \Sigma^{(2)}_p},
\end{align}
where $\Sigma^{(2)}_p$ is given by (equation eq:sigma2 of the paper).
\end{enumerate}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm split_sharp of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix~$p_0\in(0,\frac12)$ and~$a\in(0,1)$, and let~$C_\star$ and~$u_\star$ be as in Theorem~(thm:plugin_sharp of the paper). Then,
\begin{equation}

\lim_{n\to\infty}
\ \sqrt{an}
\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n^{\pi_a}(p)\bigr)
 =
C_\star
,
\end{equation}
and, for any~$[p_0,1)$-valued sequence~$(p_n)$, one has~$\sqrt{an}\bigl(V_n(p_n)-W_n^{\pi_a}(p_n)\bigr)\to C_\star$ if and only if~$\sqrt{an}\,\bigl|p_n-\tfrac12\bigr|\to\tfrac{u_\star}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop5.4 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $0<\alpha<\nicefrac{1}{2}$, for any $z$ and large $i$
   \begin{align} 
  \mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}) +2 (\mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}))^{\alpha}+ {\mathbf{c}} -a_{i-1} \leq \mathbb{E}_{z}(\overline{Z}_{\rho_{i}})  \leq \mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}) +2(\mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}))^{\alpha}+ {\mathbf{c}},

   \end{align}
where $(a_i,i)$ is a positive sequence which converges to zero when $i \rightarrow + \infty$ such that  $a_i (\mathbb{E}_z(\overline{Z}_{\rho_{i-1}})^{2\alpha-1}\vee \mathbb{E}_z(\overline{Z}_{\rho_{i-1}}^{-\alpha}))^{-1}$ is bounded.

