body:
[Theorem log_analyticity_general of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm u$ be as in Theorem (theorem:analyticity_general of the paper). Assume that $\bm{u}_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}} =\mathbb{E}[\exp(\bracket{\bm p}{\sigW[t,T]})] \neq 0$ for all $t \in [0\,,T]\,$, and define  $\bm \psi := \log^{\mathrel{\sqcup \mkern -3mu \sqcup}}(\bm u)$ as in (equation eq:def_log_shuffle_psi of the paper). It holds that:
    \begin{enumerate}
        \item For all $t \in [0,T]$ and $\sigX[] \in G$ such that $\|\bm u_t\|_{\sigX[]} < 2 |\bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|\,$, we have $\bm \psi_t \in \mathcal A_{\sigX[]}$ and 
        $$
        \mathbb{E}\left[\exp\left(\bracket{\bm p}{\sigX[] \otimes \sigW[t,T]}\right)\right] = \exp (\bracket{\bm \psi_t}{\sigX[]})\,.
        $$
        \item For any $\varepsilon \in (0\,,1)\,$, there exists $r = r(\bm p, T, \varepsilon) >0\,$, such that $\|\bm u_t\|_{\sigX[]} \leq (2-\varepsilon)|\bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|$ for all $t \in [0\,,T]$ and $\sigX[] \in G_{\bm p, r}\,$, so that $\bm \psi_t \in \mathcal A_{\bm p, r}\,$. Moreover,
        $$
        \sup_{t \in [0, T]} \|\bm \psi_t\|_{\sigX[]} \leq \sup_{t \in [0, T]} |\bm \psi_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}| + \log\left({\varepsilon}^{-1}\right) < + \infty\,, \quad \sigX[] \in G_{\bm p, r}.
        $$
        The Fourier--Laplace transform {thus} reads 
        \begin{align}
        \mathbb{E}\left[\exp \left(\bracket{\bm p}{\sigW[T]}\right) \, |\, \mathcal F _t\right] = \exp(\bracket{\bm{\psi}_t}{\sigW[t]}),     
        \end{align}
        for all $t \in [0, T]$ such that $|M_{\bm{p}}(\sigW)| \leq r$. In particular, (equation eq:logcharsigexpansion of the paper) holds for all  $t \in \llbracket  0, \tau \rrbracket$, where $\tau$ is a positive stopping time given by
        \begin{equation}
                \tau := \inf\{t \geq 0\colon\ |M_{\bm p}(\sigW[t])| \geq r \}.
        \end{equation}
        \item $t \mapsto \bm \psi_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}$ is continuous on $[0\,, T]\,$.
    \end{enumerate}

[Proposition 35 (Gram symmetrization) of arXiv:2609.03736, '2609.03736'] The pair $(K^\perp, L^\perp)$ is normalized and satisfies
\begin{align}
 \Phi(K^\perp,L^\perp)&=1-\Phi(K,L),
 \\
 \Gamma(K^\perp,L^\perp)
 &=\tr(G^{-1/2}QG^{-1/2}Q).

\end{align}
Consequently the Gram-symmetrized pair
\begin{equation}
 \widehat K=\frac12K\oplus\frac12K^\perp,
 \qquad
 \widehat L=\frac12L\oplus\frac12L^\perp

\end{equation}
has
\begin{equation}
 \Phi(\widehat K,\widehat L)=\frac12,
 \qquad
 \Gamma(\widehat K,\widehat L)=J(K,L).

\end{equation}

[Lemma 16 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\delta >0$. In the same setting as Lemma \ref{lemma support sbm interval}, we have that
        \begin{equation*}
        \overline{\bigcup_{0 \leq s \leq \delta} \text{supp}(\mathcal{Y}_s)} = \text{supp}(\mu_{\rm d}) \cup \overline{\bigcup_{i \in I} \{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}} \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.}
    \end{equation*}
    \begin{proof}
        For $i \in I$ recall the measures $\mathcal{Z}_{s, i}$ from \eqref{equation components of total measure oosbm}. We first note that
        \begin{equation*}
            \overline{\bigcup_{0 \leq s \leq \delta} \text{supp}(\mathcal{Y}_s)} = \overline{\bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_s)} = \text{supp}(\mu_d) \cup \overline{\bigcup_{i \in I} \bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i})}.
        \end{equation*}
        To prove the result we now show for each $i \in I$ that
        \begin{equation*}
            \overline{\bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i})} = \overline{\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}}.
        \end{equation*}
        The first inclusion follows from the proof of Lemma \ref{lemma supports sbm and oosbm} which states that 
        \begin{equation*}
            \text{supp} (\mathcal{Z}_{s,i}) = \overline{\{\hat{w}^i_{T^{1/m}_{s,n,i}}: m \in \mathbb{N}, 1 \leq n \leq M_i^{1/m}\}}
        \end{equation*}
        and we note that for all $s<\delta$, $s \in \mathbb{Q}$, $m \in \mathbb{N}, 1 \leq n \leq M_i^{1/m}$, we have that $H^i_{T^{1/m}_{s, n, i}}(\delta)=f^i_{T^{1/m}_{s, n, i}}$, since $T_{s,n,i}^{1/m}$ is a downcrossing time. From this, it follows that
        \begin{equation*}
            \bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i}) \subseteq \overline{\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}}.
        \end{equation*}
        It remains to show the reverse inclusion. We consider
        \begin{equation*}
            \sum_{i \in I} \delta_{((b_i,s_i), f^i, x^{i, \delta})}
        \end{equation*}
        where $I$, $(b_i, s_i)$, $f^i$ are the same as for the original Brownian snake defined in \eqref{equation snake poisson random measure} and where $x^{i, \delta}$, $i \in I$, are defined as follows. For $i \in I$, we let $x^{i, \delta} = (w^{i, \delta}, v^i)$ where $v^i$ is the usual subordinator component for $x^i=(w^i, v^i)$, and where for $r \in [0,\sigma(f^i)]$, $u \in [0,f^i_r]$, we define $w^{i, \delta}_r(u) = w^i_r(u \wedge H^i_r(\delta))$. It follows that $x^{i, \delta}$ is a bivariate Brownian snake where the second component is a subordinator and the first component is Brownian path stopped at a time determined by the subordinator. We claim that
        \begin{equation*}
            \{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\} = \{\hat{w}^{i, \delta}_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}.
        \end{equation*}
        This is because for $r \in [0,\sigma(f^i)]$ with $f^i_r = H^i_r(\delta)$ we have that 
        \begin{equation*}
            \hat{w}^i_r = w^i_r(f^i_r) = w^i_r(f^i_r \wedge H^i_r(\delta)) = \hat{w}^{i, \delta}_r. 
        \end{equation*}
        We can also define a measure $\mathcal{Z}^{\delta}_{s, i}$ by
        \begin{equation*}
            \langle \mathcal{Z}^{\delta}_{s, i}, \Phi \rangle = \int_{r=0}^{\sigma(f^i)} \Phi(\hat{w}^{i, \delta}_r) d\ell_{s, i}(r)
        \end{equation*}
        for any Borel-measurable function $\Phi$. Like our original snake, $x^i$, our new snake, $x^{i, \delta}$, has head of the snake process $(\hat{w}^{i, \delta}_r)_{0 \leq r \leq \sigma(f^i)}$ which is continuous. We can apply the results of Lemmas \ref{lemma supports sbm and oosbm} and \ref{lemma support sbm interval} to $(\mathcal{Z}^{\delta}_{s, i}, s \geq 0)$. Specifically, we can let $(\mathcal{Y}^{\delta}_{s, i})_{s \geq 0}$ be a continuous modification of $(\mathca (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainthm t:1.1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $\widecheck{{\mathbf t}}_N$ be defined via the relation:
\begin{equation}

\sqrt{\widecheck{{\mathbf t}}_N} = \frac{1}{\sqrt{\pi}} \log N - \frac{1}{4 \sqrt{\pi}} \log \log N \,.
\end{equation}
Then, there exist random variables $\widecheck{{\mathbf T}}_{\rm D}$ and $\widecheck{{\mathbf X}}_{\rm D}$, defined on the same probability space and take values in $\mathbb{R}$ and ${\rm D}$ respectively, such that
\begin{equation}

\Big(\frac{\widecheck{{\mathbf T}}_N/|{\rm D}_N| - \widecheck{{\mathbf t}}_N}{\log N}
\,,\,\, \frac{\widecheck{{\mathbf X}}_N}{N}\Big)
	\underset{N \to \infty}\Longrightarrow \, \big(\widecheck{{\mathbf T}}_{\rm D},\, \widecheck{{\mathbf X}}_{\rm D}\big) \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma W_ratio_big_extraction of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] There exists an absolute constant $c_1=c_1(q,\kappa)>0$ not depending on the size of the hexagon, such that for all $T,S,N,t$ and points
	$x,y$ on the $t$-th vertical slice of the hexagon, we have
	\begin{equation}

		c_1
		<
		q^{
			\operatorname{\mathrm{sgn}}(x-y)
		\sum_{u=\min(x,y)}^{\max(x,y)-1}
		\mathscr{W}_{\mathbf{k}}(u\mid T,S,N,t)}
		\cdot
		\frac{w^{qR}(\tilde x)}{w^{qR}(\tilde y)}
		<
		c_1^{-1}.
	\end{equation}

[Lemma lem:large-n of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] Let $T\geq Y^\sigma$.  For $0\leq\sigma,\tau\leq1$,
\[
\sum_{\substack{Y^\sigma<n\leq T\\d\leq Y^\tau}}
\frac{\mathcal S_{d,n,r}}{nd}
\ll_\varepsilon
(QXT)^\varepsilon
\left(
\sqrt X+Y^{1-\sigma/2}+\sqrt Y\,T^{1/4}
\right).
\]

[Thm smc_density of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] The SMC process conditioned on $Y_{0}=x>0$
has Laplace transform $\phi(\ell,\lambda):=\mathbb{E}_{x}e^{-\lambda Y_{\ell}}$ given by
\begin{equation}
\phi(\ell,\lambda)=1-\frac{\lambda(1+\lambda+\ell)}{(1+\lambda)(\lambda+\ell)}\left(1-e^{-(\lambda+\ell)x}\right),
\quad\ell\ge0,\lambda>0,

\end{equation}

