body:
[Lem L:1.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that $X$ satisfies (AC), (H1a), and (H1b), and additionally that $({\mathcal{E}},{\mathcal{F}})$ is transient. 

Let $B\subset E$ be a nearly Borel set of finite $0$-order capacity. Then there exists a unique  finite, positive measure $\nu_B$ with $\mathrm{supp}[\nu_B]\subset \overline{B}$ such that 
\begin{equation}
    \mathbb{P}^x[\sigma_B<\infty]=\int_E u(x,y)\nu_B(\mathrm{d} y),\quad \forall x\in  E,
\end{equation}
where $u(x,y)$ denotes the potential kernel of $X$.
In particular,
\begin{equation}
{\mathbb{P}}^x\left[\sigma_B\le t\right] \ge \emph{Cap}_{(0)}(B)\inf_{y\in \overline B}\int_0^t  p(s, x, y)\mathrm{d} s,\quad \forall t>0,x\in E.
\end{equation}

[Theorem mt1 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Let $(\ell_N:N\ge 1)$ be the sequence such that $\ell_N = N^{4/5}$ in
dimension $1$, $\ell^3_N \log \ell_N = N^2$ in
dimension $2$, and $\ell_N = N^{4/3d}$ in dimension $d\ge 3$.  Assume
that $\lim_{N\uparrow\infty}K_N=\infty$ and
$\sup_{N\ge 1} K^2_N / \ell^d_N < \infty$.  Then, there exists a
constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on ${\boldsymbol u}^N$ and uniformly
bounded in $N$, such that
\begin{equation*}
\frac{d}{dt}\, H_N(f^N_t) \;\leq\; 
{\mathfrak c}({\boldsymbol u}^N)\,\, K^2_N
\, \big\{ H_N(f^N_t) \,+\, (N/\ell_N)^d \, \big\}
\end{equation*}
for all $t\ge 0$, $N\ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Define the processes
    \begin{align*}
        A_t = \int a \, d\mu_t \,, \quad I_t = \int 1-a \, d\mu_t \,,
    \end{align*}
    which count the number of active and inactive branches respectively. 
    Then $A_t$ is equal to the number of dendrite tips and $I_t$ is equal to the number of branch points.

[Corollary 16 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] If
\begin{equation}
 2\int_0^tq(s)\dd s=tq(t),
\end{equation}
then
\begin{equation}
 q(t)<t\theta^2.
\end{equation}

[Definition kpoint of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] For $k\in \Bbb N$, define the \textit{$k$-point motion} to be the continuous-time Markov process $\mathbf R=(R^1,\ldots,R^k)$ on $\Bbb Z^k$ with transition probabilities  given, for every $t\ge0$ and $\mathbf x = (x_1,\ldots,x_k), \mathbf y=(y_1,\ldots,y_k)\in \mathbb{Z}^k$, by
    \begin{equation}\mathsf p^{(k)}_t(\mathbf x, \mathbf y)\coloneqq \Bbb E \bigg[ \prod_{j=1}^k K_t (x_j,y_j)\bigg]\; \text{.}
    \end{equation} 
     Let $\ensuremath{\mathcal L}^{(k)} (\mathbf x,\mathbf y):= \frac{{\rm d}}{{\rm d} t}\big|_{t=0}\, \mathsf p^{(k)}_t(\mathbf x,\mathbf y) $, $\mathbf x, \mathbf y \in \mathbb{Z}^k$, denote the corresponding generator, while
    $\mathbf P_\mathbf x^{(k)}$ and $\mathbf E_\mathbf x^{(k)}$ stand for the path law and corresponding expectation when starting from $\mathbf x\in \mathbb{Z}^k$.

[Proposition prop:marginals of arXiv:2510.22778, 'Free denoising diffusion models'] The unique adapted solution of (equation eq:forward of the paper) is
\begin{equation}
  X_{t}=\sqrt{\alpha_{t}}\,X_{0}
  +\int_{0}^{t}\sqrt{\tfrac{\alpha_{t}}{\alpha_{s}}}\,\sqrt{\beta(s)}\;\mathrm{d} S_{s},
\end{equation}
and its spectral law is
\begin{equation}
  \mu_{t}:=\mu_{X_{t}}=\big(D_{\sqrt{\alpha_{t}}}\mu_{0}\big)\boxplus\gamma_{1-\alpha_{t}},
\end{equation}
where $D_{c}\mu$ denotes the pushforward of $\mu$ under $x\mapsto cx$. In particular
$\int x^{2}\mathrm{d}\mu_{t}=\alpha_{t}\int x^{2}\mathrm{d}\mu_{0}+(1-\alpha_{t})$ and
$\mu_{t}\to\gamma$ in $W_{2}$ as $\Lambda(t)\to\infty$.

