[Proposition 3 (Regularity of the coefficient fields) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Then, for every $n\ge0$, $\theta_n^\mrm U,\theta_n^\mrm N\in\Theta$. Moreover, the coefficient fields are also Lipschitz with
\begin{equation}
        [\theta_n^{\mrm U}]_{\rho}
        \le L_{0,\rho} + \frac{2\alpha_{\mrm U} L_{\kappa,\rho}}{1-\gamma}
        \log\crbk{\frac{n+n_0^{\mrm U}}{n_0^{\mrm U}}},

\end{equation}
and
\begin{equation}
        [\theta_n^{\mrm N}]_{\rho}
        \le
        L_{0,\rho}+
        \frac{2\alpha_{\mrm N} L_{\kappa,\rho}}{1-\gamma} \crbk{\frac{1}{c_\wedge}+\frac{1}{c_\wedge^2}}
        \log\crbk{\frac{n+n_0^{\mrm N}}{n_0^{\mrm N}}}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 211 (quenched second moment bounds for $\vY$ and $\vY^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For all $0\le s<t\le1$ we have
    \[
    \sum_{\sigma\in\{\RomII,\RomIII,\Ising\}}
    \frac{\bE[(Y^\sigma(t)-Y^\sigma(s))^2]}{(t-s)}
    \le L^{O(1)} \bigg\{
    (\MAX_N)^2+ \frac{(\SMAX_N)^2\BUCKETS}{N\delta}
    \bigg\}
    = L^{O(1)} (\TMAX_N)^2
    \,,
    \]
with $\TMAX_N$ defined by \eqref{e:def.TMAX}. The same bound holds with $\vY^\frozen$ in place of $\vY$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma WPD-NHS-AA of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\}$ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, there exists a real number $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that the backward flow ${{\tilde \Phi }_k}\left( {t,x} \right)$ and the Lagrangian flow ${{\tilde X}_t}$ satisfy
\begin{equation}
{\left\| {\nabla {{\tilde \Phi }_k}} \right\|_N} + {\left\| {{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N}  \lesssim \lambda _q^N \lambda _{q + 1}^{ - \alpha }   ,
\end{equation}
\begin{equation}
{\left\| {D{{\tilde X}_k}} \right\|_N} \lesssim  \max \left\{ {1,\lambda _q^N \lambda _{q + 1}^{ - \alpha }} \right\}  ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}\nabla {{\tilde \Phi }_k}} \right\|_N} + {\left\| {{{\bar D}_{t,\Gamma }}{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}   ,
\end{equation}
\begin{equation}
{\left\| {{\partial _{tt}}{{\tilde \Phi }_k}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}  ,
\end{equation}
and
\begin{equation}
{\left\| {{\partial _{tt}}{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}} \lambda _q^{N + 3}   ,
\end{equation}
where ${{\bar D}_{t,\Gamma }} \triangleq {\partial _t} + {{\bar v}_{q,\Gamma }} \cdot \nabla $ is the material derivative corresponding to ${{\bar v}_{q,\Gamma }}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

