		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma3 of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume   (equation EY* of the paper) and
 suppose further that  there exist constants $ \lambda_b^\star, C_b^\star>0$ such that for any $\delta\in[0,1] $ and $x\in\mathds R^d,$
\begin{align}
\<\pi^{(\delta)}(x),b^{(\delta)}(\pi^{(\delta)}(x))\>\le   C_b^\star- \lambda_b^\star|\pi^{(\delta)}(x)|^2.
\end{align}
 Then, for any $p>0$,
 there exists a constant  $  C^*(p)>0$ such that for all $\delta\in (0,\delta_\star]$ and $n\ge0,$
\begin{equation}
\mathbb E\big(|X^{\delta}_{n\delta}|^{p}\big|\mathscr F_0\big)\le  C^*(p)(1+   d^{\frac p2}) +  \text{\rm{e}}^{-\frac{p\lambda_b^\star  n\delta}{4(3+\lfloor p\rfloor)} }|X^\delta_0|^p,
\end{equation}
in which $\delta_\star:=\big( \lambda_b^\star/(2\psi^2_2(1))\big)^{\frac{1}{1-2\theta}}\wedge(1/\lambda_b^\star)\wedge 1$ with $\psi_2(\cdot)$ being introduced in (equation EY* of the paper).
Consequently,  for each fixed $\delta\in(0,\delta_\star],$  $(X_{n\delta}^{\delta})_{n\ge0}$ possesses an   IPM  $\pi^{(\delta)}_\infty$  satisfying
\begin{align}
\pi_\8^{(\delta)}(|\cdot|^p)\le  C^*(p)(1+   d^{\frac p2}).
\end{align}

