[Lemma 8 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] Let $\kappa\geq \kappa_c$. For a finite subset of vertices $F$,
\begin{equation}
    \mu_\kappa(\ell : \ell \cap F \neq \emptyset)
    =
    \log \det\big( G^\kappa|_{F} \big),
\end{equation}
where $G^\kappa$ is the Green function viewed as a matrix $(G^\kappa(x,y))_{x,y}$, and $G^\kappa|_{F}$ is its submatrix indexed by $F \times F$.
In particular, for $n$ distinct vertices $v_1, \ldots, v_n$,
\begin{equation}
    \mu_\kappa\big( \ell : v_i \in \ell \text{ for } i \in \{1,\ldots,n\} \big)
    =
    \sum_{\substack{A \subset \{v_1,\ldots,v_n\} \\ A \neq \emptyset}}
    (-1)^{\# A + 1}
    \log \det\big( G^\kappa|_{A} \big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 20 (Verification theorem) of arXiv:2607.22416, 'A multi-player optimal stopping game based on a spider Brownian bridge'] Suppose that for $j \neq i$, Player $j$ uses the threshold strategy $\tau_j :=\inf\{s\geq 0: R_{s}\geq  d_j \sqrt{1-s}, \Theta_{s} = \theta_j \}$. Under Assumptions~\ref{ass:Gamma_N} and \ref{ass:spidersupermartingale}, the value function $\overline{V} = \overline{V}(t,r,\theta)$ defined in \eqref{Valuefunc_P1_E} coincides with the value function $V_{*} = V_{*}(t,r,\theta)$ given by \eqref{Expression_VE_star}. Moreover, the stopping time
    \begin{equation*}
        \tau^{*}:=\inf\{s\geq 0: R_{s}\geq b^*\sqrt{1-s}, \Theta_{s} = \theta_i\},
    \end{equation*}
    where $b^*>0$ is the maximizer of $\Gamma \equiv B_i$, is optimal for Player $i$.

[Lemma 11 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $(M(t),\covm(t))_{t \geq 0}$ be an EKF satisfying assumptions (A\ref{cond1})-{(A\ref{cond4})} of Theorem \ref{CvgTH}. Suppose also that { $ \qcovm= \eps^{-1} \covm$ }		satisfies 
				\begin{equation} 
					\qcovm(t)  \big(\nabla_y h^{\top} (\coDifO\coDifO^\top)^{-1}\nabla_yh \big )(t,M(t))\qcovm(t) +\af(t,M(t))\geqm k(t)\qcovm(t),
				\end{equation}
				for some family of deterministic positive functions $k(t)$   and the function $\af$ given in (A\ref{cond4}). Further, it is assumed that    there is a constant $C>0$ such that  
				\begin{equation}

					\qcovm(t) + \qcovm^{-1}(t)\leqm Ck(t)I.
				\end{equation}
				Then $\qcovm^{-1/2} (t)\big(\sig(t)-M(t)\big)$ is of order $\sqrt{\eps}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Controlling the commutators) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $\phi(t,x) \in \{ b_A(t,x), \sigma_{A}(t, x)^2 \}$. Then, the commutator $c^{\phi,\varepsilon}_t(x)$ defined in \eqref{eq:commutator} satisfies
	\begin{equation*}
	  \| c^{\phi,\varepsilon}_t \|^2_2  \leq C\sqrt{\varepsilon},
	\end{equation*}
    for all $t\in[0,T]$, where $C$ only depends on $\phi$ and $T>0$.

[Thm plugin_sharp of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix~$p_0\in(0,\frac12)$ and let
\begin{equation}

C_\star
:=
\frac{1}{2}\sup_{u>0}
u\Phi(-u)
=
0.08498\ldots
,
\end{equation}
where~$\Phi$ denotes the standard normal distribution function; the supremum is attained at the unique positive root~$u_\star=0.7517\ldots$ of~$\Phi(-u)=u\varphi(u)$, with~$\varphi:=\Phi'$. Then,
\begin{equation}

\lim_{n\to\infty}
\ \sqrt n
\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n(p)\bigr)
 =
C_\star
,
\end{equation}
and, for any~$[p_0,1)$-valued sequence~$(p_n)$, one has~$\sqrt n\bigl(V_n(p_n)-W_n(p_n)\bigr)\to C_\star$ if and only if~$\sqrt n\,|p_n-\tfrac12|\to\tfrac{u_\star}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

