[Lem 13 (Vanishing viscosity limit) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] For fixed $n\in\mathbb N$, equation \eqref{eq:penalized-hyperbolic} admits a unique kinetic solution $u_n$ in the sense of Definition \ref{def:kinetic-penalized}.
Moreover, as $\alpha\downarrow0$,
\begin{equation*}
u_{\alpha,n}\rightarrow u_n\quad\text{strongly in }L^p(\Omega\times Q_T)
\end{equation*}
for every $1\leq p<\infty$, and
\begin{align*}
\nu_{\alpha,n}&\rightarrow\nu_n \quad\text{strongly in }L^1(\Omega\times Q_T),\\
f_{\alpha,n}&\rightarrow f_n\quad\text{strongly in }L^1_{\mathrm{loc}}(\Omega\times Q_T\times\mathbb R),\nonumber
\end{align*}
and for every $\phi\in C_c^1(\mathbb T^N\times[0,T]\times\mathbb R)$, 
\begin{equation*}
\lambda_{\alpha,n}(\phi)\rightarrow\lambda_n(\phi)\quad\text{in }L^1(\Omega).
\end{equation*}
Moreover, we have
\begin{equation}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u_{n}(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation}

[Definition 17 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that  $k \in \mathbb{N}$. 
We define  maps $\Sigma_k$ and $\bG_k$  by 
\begin{equation}
\bSi_k: [0,T] \times \StokesV \ni (t,\bu) \mapsto \bSi_k(t)\bu \coloneqq   \P \left[(\sigma_k(t,\cdot )  \cdot\nabla) \bu(\cdot)\right] \in \StokesH,
\end{equation}
and 
\begin{equation}
\bG_k: [0,T] \times \StokesH \ni (t,\bu) \mapsto   \P \left[
\bg_k(t,\cdot,\bu(\cdot)) \right] \in \StokesH.
\end{equation}
Next, we define  maps $\bG$ and $\bSi$ by
\begin{equation}
\bG: [0,T] \times \StokesH \ni (t,\bu) \mapsto \left(  \bG_k(t,\bu)\right)_{k=1}^\infty
 \in \ell^2(\StokesH)
\end{equation}
and 
   \begin{equation}
      \bSi: [0,T] \times \StokesV \ni (t,\bu) \mapsto  \bSi(t)\bu \coloneqq \left( \bSi_k(t)\bu \right)_{k=1}^\infty
     \in  \ell^2(\StokesH),
   \end{equation}
where the Hilbert space  $ \ell^2(\StokesH)$ has been defined in \eqref{eqn-l^2Y}.

[Theorem thmDou2022 of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any $t_0\in (0,T)$, there exists a positive constant $\mathcal{C}=\mathcal{C}(t_0)$ such that for some generic constant $\gamma = \gamma(t_{0}, T) \in (0,1)$  and for any $M>0$, for all $ y_0, \hat y_0\in U_{M,1} $,
letting
\begin{align}

    \beta(\eta) =
    \mathcal{C} \eta
    +
    \mathcal{C} M^{2} \operatorname{exp}  [-  3^{-\gamma} \ln^{\gamma} (\eta^{-1}) ]
\end{align}
it holds that

\begin{equation}
| y(t_0)-\hat y(t_0)|^{2}_{L^2_{\mathcal{F}_{t_0}}(\Omega;H^{1}(G))} \leq \beta\Big( | y(T) - \hat{y}(T) |_{L^{2}_{\mathcal{F}_{T}}(\Omega; L^{2}(G))} \Big),
\end{equation}

where $y(\cdot)$ (resp. $\hat y(\cdot)$) is the solution to (sp-eq1 of the paper) with respect to the initial datum $y_0$ (resp. $\hat y_0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

