[Theorem thm:KS of arXiv:2510.13572, 'Coalescence in Markov chains'] Let $P=(p_{i,j}:i,j\in S)$.
Let $\mathcal S$ be a partition of $S$, and let
\begin{equation}
\lambda_{r,s}^{(i)}= \sum_{j \in S_s} p_{i,j}, \quad i \in S_r.
\end{equation}
A Markov chain $X$ with transition matrix $P$ 

 is $\mathcal S$-lumpable if and only if, 
\begin{equation}
\text{for every $r$, $s$, we have that $\lambda_{r,s} := \lambda_{r,s}^{(i)}$ is constant 
for $i\in S_r$.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 11 (Exponential tightness) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] There exists a sequence of compact sets $K_L \subset \mathcal{M}_1(\mathbb{R})$ ($L > 0$) such that

\begin{align}

\limsup_{L \to +\infty} \limsup_{N \to +\infty} \frac{1}{N} \ln \overline{\Pi}_{N}[K_L^c] = - \infty \, .

\end{align}

Likewise, if we let $K_{L,\mathsf{c}} = K_L \cap \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$
then (we claim, according to our earlier choice of $K_L$) $K_{L,\mathsf{c}}$
is compact in the subspace topology of $\mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$

\begin{align}

\limsup_{L \to +\infty} \limsup_{N \to +\infty} \frac{1}{N} \ln \overline{\Pi}_{N,\mathsf{c}}[K_{L,\mathsf{c}}^c] = - \infty \, .

\end{align}

where here the complement is taken in $\mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem9 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] There exist a positive number $R_2$ depending on $D$ and universal constants, and a random variable $R_3(\omega)$ depending on the initial data, $\varepsilon_0$, $\nu$, $f$ and universal constants, such that: For every $E > 0$, there exists $t(\omega,E) \leq -1$, such that for all $t_0 \leq t(\omega,E)$ and $x_0=(u_0,\rho_0,\sigma_0)$ $\in{H}^{1}$ with $|x_0| < E$, we have 
		\begin{align}
			\int_{-1}^{0} \|\nabla \sigma(s,\omega,t_0,\sigma_0)\|_{L^2}^{2}ds \leq R_2,
		\end{align}
		\begin{align}
			\int_{-1}^{0} \|\nabla \rho(s,\omega,t_0,\rho_0)\|_{L^2}^{2}ds \leq R_2,
		\end{align}
		\begin{align}
			\int_{-1}^{0} \|\nabla v^\varepsilon(s,\omega,t_0,z(t_0,\omega)u_0)\|_{L^2}^{2}ds \leq R_3(\omega).
		\end{align}
		\begin{proof}
			The differential inequality (equation d3 of the paper) gives 
			\begin{align}
				\frac{d}{dt}( \|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ ) +2D(\|\nabla\rho\|_{L^2}^{2} + \|\nabla\sigma\|_{L^2}^{2}) \leq 0.
			\end{align}
			Integrating (equation d12 of the paper) between $-1$ and $0$ yields
			\begin{align*}
				&\|\sigma(0)\|_{L^2}^{2}-\|\sigma(-1)\|_{L^2}^{2}+\|\rho(0)\|_{L^2}^{2}-\|\rho(-1)\|_{L^2}^{2}+2D\int_{-1}^{0} (\|\nabla \sigma(s)\|_{L^2}^{2}+\|\nabla \rho(s)\|_{L^2}^{2})ds \leq 0.
			\end{align*}
			It follows that
			\begin{align*}
				\int_{-1}^{0} (\|\nabla \sigma(s)\|_{L^2}^{2}+\|\nabla \rho(s)\|_{L^2}^{2})ds &\leq \frac{1}{2D}(\|\sigma(-1)\|_{L^2}^{2}+\|\rho(-1)\|_{L^2}^{2}) \leq \frac{{R_0}^2}{2D}=R_2,
			\end{align*}
			which proves (equation f1 of the paper) and (equation f2 of the paper).
			Integrating (equation d6 of the paper) between -1 and 0, we get
			\begin{align*}
				\|&v^\varepsilon(0)\|_{L^2}^{2}-\|v^\varepsilon(-1)\|_{L^2}^{2}+\nu \int_{-1}^{0} \|\nabla v^\varepsilon(s)\|_{L^2}^{2}ds\\& \leq \frac{1}{\nu}\int_{-1}^{0} {z^2(s,\omega)}(\|\rho(s)\|_{L^2}^{3}\|\nabla \rho(s)\|_{L^2}+\|f\|_{L^2}^2)ds.
			\end{align*}
			Thus, we have
			\begin{align*}
				\int_{-1}^{0} \|\nabla v^\varepsilon(s)\|_{L^2}^{2}ds \leq \frac{1}{\nu}{R_1}^2(\omega)+\frac{{R_0}^3}{{\nu}^2}(\int_{-1}^{0} z^4(s,\omega) ds +R_2+C_f)=R_3(\omega),
			\end{align*}
			which proves (equation f3 of the paper).
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $ (f_{N}, N\geq 1)$ be a sequence of random variables in $ H ^{\odot p}$ with $p\geq 2$. Assume (\ref{a1}). Then
		\begin{enumerate}
			\item  For every $h\in H$,
			\begin{equation*}
				f_{N} \otimes _{1} h \to _{N \to \infty} 0 \mbox{ in } H ^{\otimes p-1}.
			\end{equation*}
			\item For any sequence $(h_{N}, N\geq 1)$ bounded in $H$, 
			\begin{equation*}
				f_{N}\otimes _{1} h_{N} \to _{N \to \infty} 0 \mbox{ in } H ^{\otimes p-1}.
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Delta theta denominator stays positive of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda,C^2)\in S^0$ with $\Delta z(\lambda,C^2)=0$. Then 
  \begin{equation*}
    k(s)^{2p-2}((p-1-\lambda)^2 + p^2 C^2)-p^2C^2\geq \varepsilon_{\lambda,C^2}>0.
  \end{equation*}

