[Lemma 34 of arXiv:2608.27307, '2608.27307'] Let $h$ be a real random variable with moments of all orders, and let $F:\R\to\C$ be a smooth function. For every fixed integer $\ell\geq1$,
        \begin{align}
                \bb E[hF(h)] =\sum_{k=0}^{\ell}\frac{\kappa_{k+1}(h)}{k!}\bb E F^{(k)}(h)+\calR_{\ell+1}. \nonumber
        \end{align}
        For any $K>0$, the remainder term satisfies
        \begin{align}
                \abs{\calR_{\ell+1}} & \leq O(1)(\bb E\sup_{|t|\leq|h|}|F^{(\ell+1)}(t)|^2\bb E[|h|^{2\ell+4}1_{\{|h|>K\}}])^{1/2} +O(1)\bb E|h|^{\ell+2}\sup_{|t|\leq K}|F^{(\ell+1)}(t)|. \nonumber
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:harmonic of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] Fix an input $x$ and a parameter $\theta$.
For every truncation order $T \ge 1$,
\begin{equation}
J^{(T)}_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{T} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big),

\end{equation}
and if $J_{\mathrm{TailRL{}}}(\theta;x) > -\infty$, the same identity holds for the full series,
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big).

\end{equation}

