[Proposition 18 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
\begin{align}
\Xi_t^{(p)}(n,S)\lesssim & \left(\frac{N^{(n-p)/2}}{N^{(p-2)/2}} + \frac{(N\eta_t)^{n-p}}{(N\eta_t)^{p-2}}\right)\frac{N^\xi}{\eta_t^S},\\
\Theta_t^{(p)}(n,S)\lesssim & N^{(n-2p+2)/2+\xi},

\end{align}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 94 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $F$ be a grounded set and let $F\cup g$ be an enlargement of $F$ in direction $s$.  Given $Q \in \S^\rm{u}_k(F\cup g)$ such that $Q[F]$ is nonsingular, let $C$ be its Verblunsky coefficient over $Q[F]$.  Then the map
\begin{align*}
\big\{Q \in \S^\rm{u}_k(F\cup g):\ Q[F]\ \hbox{nonsingular}\big\} &\to \S_k^\circ(F)\times \Xi(k,k|F\setminus sF|):\\ Q &\mapsto (Q[F],C)
\end{align*}
is a homeomorphism, and it maps $\S_k^\circ(F\cup g)$ onto $\S_k^\circ(F)\times \Xi^\circ(k,k|F\setminus sF|)$.

[Lemma 24 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] For any \(1/2<H<1\) we have that
\begin{equation}
\int_{u\vee v}^{1}(s-u)^{H-3/2}(s-v)^{H-3/2}ds < |u-v|^{2H-2}\beta(H-1/2,2-2H).
\end{equation}
\begin{proof}
\begin{align}
\int_{u\vee v}^{1}(s-u)^{H-3/2}&(s-v)^{H-3/2}ds = \int_0^{1-u\vee v}(s+|u-v|)^{H-3/2}s^{H-3/2}ds\\
&=|u-v|^{2H-3} \int_0^{1-u\vee v}\left(\frac{s}{|u-v|}\right)^{H-3/2}\left(\frac{s}{|u-v|}+1\right)^{H-3/2}ds\\
&=|u-v|^{2H-2}\int_0^{(1-u\vee v)/|u-v|}t^{H-3/2}(t+1)^{H-3/2}dt\\
&< |u-v|^{2H-2}\int_0^{\infty}t^{H-3/2}(t+1)^{H-3/2}dt\\
&=|u-v|^{2H-2}\beta(H-1/2,2-2H)
\end{align} 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:distance_from_left_to_right_less_than_distance_from_bottom_to_top of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Suppose that we have the setup described above and let $a,R_0$ be the constants in (lem:rectangles_are_not_wide of the paper).  Fix $j \in \{1,\ldots,N\}$,  $k \in \{0,1,\ldots,\lfloor R \rfloor -1\}$ and $m \in \{3q+1 : q \in [0,7]_\BZ\}$.  Then,  there exist constants $p \in (0,1) ,  B \in (0,\infty)$ depending only on $a,R_0$ such that the following is true.  We condition on $U_1,\ldots,U_N$ and the outermost loops in $\phi_j(\overline{\Gamma}|_{U_j})$ with height in $\{-\lambda ,  \lambda\}$ which intersect either the bottom boundary of $V_{j,k}^{m-1}$ or the top boundary of $V_{j,k}^{m+1}$,  and we assume that we are working on the event that the field $\Psi|_{U_j}$ has zero-boundary conditions,  and that $I_j^3 \cap \partial B_{2^{-2R/3}}(0) = \emptyset,  I_j^4 \cap \partial B_{2^{-R/3}}(0) = \emptyset$.  Then,  with conditional probability at least $p$,  the following hold.  First,  we have that
	\begin{align*}
			D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}
		([0,\ri] ,  [b_{j,k}^m ,  b_{j,k}^m + \ri]) < B \leq 
				D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}
			([0,b_{j,k}^m] ,  [\ri ,  \ri + b_{j,k}^m]).
	\end{align*}
	 More precisely, the rectangle $f^m_{j,k}(G^m_{j,k}) = (0,b^m_{j,k}) \times (0,1)$ can be divided from top to bottom into three conformal rectangles $G^{m,1}_{j,k}$, $G^{m,2}_{j,k}$ and $G^{m,3}_{j,k}$ such that $L(G_{j,k}^{m,i}) \subseteq L(f_{j,k}^m(G_{j,k}^m))$ and $R(G_{j,k}^{m,i}) \subseteq R(f_{j,k}^m(G_{j,k}^m))$ for all $i \in \{1,2,3\}$,  and such that the following hold. 
	\begin{enumerate}[label=({\alph*})]
		\item  The $D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}$-distance from the left boundary $L(G^{m,2}_{j,k})$ of $G^{m,2}_{j,k}$ to its right boundary $R(G^{m,2}_{j,k})$ is smaller than $B$;
		\item  The right boundary (as defined in (lem:genealogy of the paper)) of the metric ball $\SCB_B(L(f^m_{j,k}(G^{m}_{j,k})),\allowbreak D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})})$ intersects $L(G^{m,2}_{j,k})$;
		\item  The $D^{f^m_{j,k}(G^m_{j,k})}_{f^m_{j,k}(\phi_j(\Gamma|_{U_j})\vert_{G^m_{j,k}})}$-distance from the bottom boundary to the top boundary of $G^{m,1}_{j,k}$ (resp.\ $G^{m,3}_{j,k}$) is at least $B$.
		\end{enumerate}
	The same statement holds if we condition instead on all of the outermost loops in $\phi_j(\overline{\Gamma}|_{U_j})$ with height in $\{-\lambda,\lambda\}$ which intersect the bottom boundary of $V_{j,k'}^{m'-1}$ or the top boundary of $V_{j,k'}^{m'+1}$ for some $k'$ and some $m' \in \{3q+1 : q \in [0,7]_\BZ\}$,  since the proof below only uses that,  conditionally on the collection in question,  the loops of $\overline{\Gamma}$ contained in $G^m_{j,k}$ form a nested $\CLE_4$ in $G^m_{j,k}$.  It is in this form that we shall use the lemma.

[Theorem 124 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble $X$ satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit} and \ref{Assumptions_analyticity}, with segments $[\hat{a}_h,\hat{b}_h]$ indexed by $h \in [H]$ and equilibrium measure $\boldsymbol{\mu}$. There exists two small numbers $\eps_1,\eps_2>0$ and a large number $C>0$, all depending only on the constants in the assumptions and satisfying the following conditions for $\N$ large enough.

Consider a $3K$-tuple of real parameters $(\mathfrak{a}_k$, $\mathfrak{b}_k$, $\mathfrak{n}_k)_{k = 1}^{K}$ such that $\mathfrak a_1 < \mathfrak{b}_1<\mathfrak a_2<\dots< \mathfrak a_k<\mathfrak b_k$ and $[\mathfrak{a}_{k},\mathfrak{b}_{k}] \subset [\hat{a}_{h^k}',\hat{b}_{h^k}']$ for any $k \in [K]$. Define the shifted parameters
 \[
\forall k \in [K]\qquad {\mathfrak a}'_k= {\mathfrak a}_k - \frac{\theta_{h^k,h^k}-\frac{1}{2}}{\N}\quad \textnormal{and}\quad {\mathfrak b}'_k= {\mathfrak b}_k + \frac{\theta_{h^k,h^k}-\frac{1}{2}}{\N}.
 \]
Assume the following properties.
 \begin{enumerate}
  \item $\forall k\in[K] \quad \N \mathfrak{n}_{k}\in\amsmathbb Z_{\geq 0} \quad \textnormal{and}\quad \N \mathfrak{b}_k -\N \mathfrak{a}_k - \theta_{h^k,h^k} (\N\mathfrak n_k-1)\in \amsmathbb Z_{\geq 0}$.

  \item For any $h\in[H]$
    \begin{itemize}
    \item if $[\hat a'_h,\mathfrak a'_{k^-(h)}]$ is void, then $\N(\mathfrak a_{k^-(h)}-\hat a_h)\in\amsmathbb Z_{\geq 0}$, otherwise $[\hat a'_h,\mathfrak a'_{k^-(h)}]$ is saturated and $\N(\mathfrak a_{k^-(h)}-\hat a_h)\in\theta_{h,h}\amsmathbb Z_{\geq 0}$;
    \item if $[\mathfrak b'_{k^+(h)},\hat b'_h]$ is void, then $\N(\hat b_h-\mathfrak b_{k^+(h)})\in\amsmathbb Z_{\geq 0}$, otherwise $[\mathfrak b'_{k^+(h)},\hat b'_h]$ is a saturated and then $\N(\hat b_h-\mathfrak b_{k^+(h)})\in\theta_{h,h}\amsmathbb Z_{\geq 0}$;
    \item for any $k \in \llbracket k^-(h),k^+(h)-1\rrbracket$, if $[\mathfrak b'_{k},\mathfrak a'_{k+1}]$ is void, then $\N(\mathfrak a_{k+1}-\mathfrak b_k)\in\amsmathbb Z_{\geq 0}$, otherwise $[\mathfrak b'_{k},\mathfrak a'_{k+1}]$ is a saturated and then $\N(\mathfrak a_{k+1}-\mathfrak b_k)\in\theta_{h,h}\amsmathbb Z_{\geq 0}$.
    \end{itemize}
If $a_1 = -\infty$ the first condition is omitted for $h = 1$. If $b_H = +\infty$ the second condition is omitted for $h = H$. If $H = 1$, $a_1 = -\infty$ and $b_1 = +\infty$, then we require that $\N\mathfrak a_1$ belongs to the lattice $\amsmathbb{L}$ where the leftmost particle of the system varies.
  \item $\forall k \in [K] \quad [\alpha_{k} - \eps_1,\beta_k + \eps_1] \subset [\mathfrak a_k,\mathfrak b_k] \subset [\alpha_k - 2\eps_1,\beta_k + 2\eps_1]$.
   \item $\forall k\in[K] \quad \big|\mathfrak{n}_{k}-\mu([\mathfrak a'_k,\mathfrak b'_k])\big|<\eps_2$.
   \item The $H$-tuple $(\widetilde{\mathfrak{n}}_h)_{h = 1}^{H}$ satisfies the constraints ($\star$), where for any $h \in [H]$ the number $\widetilde{\mathfrak{n}}_h$ is defined as the sum of the following terms: $\mathfrak{n}_k$ for $k \in \llbracket k^-(h),k^+(h)\rrbracket$; the mass $\frac{v - u}{\theta}$ of all the saturations $[u,v] \subseteq [\hat{a}'_h,\hat{b}'_h]$ appearing in Condition 2.; an extra $\big(-\frac{1}{\N}\big)$ for each $k \in \llbracket k^-(h),k^+(h) - 1\rrbracket$ such that $[\mathfrak{b}'_k,\mathfrak{a}'_{k + 1}]$ is saturated.
 \end{enumerate}
Define an event $\mathcal{A}$ by the two properties
 \begin{enumerate}
 \item[A.] The void segments appearing in Condition 2. do not have particles.
 \item[B.] The saturated segments appearing in Condition 2. do not have holes.
 \end{enumerate}
Then, the event $\mathcal{A}$ has probability at least $1 - C\exp\big(-\frac{\N}{C}\big)$, and the discrete ensemble $X$ conditioned on the intersection of $\mathcal{A}$ with the event that for any $k \in [K]$ there are $\N \mathfrak{n}_k$ particles in $[\N \mathfrak a_k, \N \mathfrak b_k]$, and localized to $\mathfrak{A} = \bigcup_{k = 1}^K [\mathfrak{a}_{k},\mathfrak{b}_{k}]$, yields a discrete ensemble obeyin

[Defn Characterization of radial SLE of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] The radial SLE is a family $\mathbb{P}(\mathbb{D};\zeta,0)$ of probability measures on curves $\eta:[0, \infty) \rightarrow \overline{\mathbb{D}}$ with $\eta(0)=\zeta$ and parametrized by capacity satisfies the following properties:
\begin{itemize}
    \item (Conformal invariance) For all $a \in \mathbb{R}$, let $\rho_a(z)=\mathrm{e}^{\mathrm{i} a} z$ be the rotation map $\mathbb{D} \rightarrow \mathbb{D}$, the pullback measure $\rho_a^* \mathbb{P}(\mathbb{D};\zeta,0)=\mathbb{P}(\mathbb{D};e^{-ia}\zeta,0)$. From this, we may extend the definition to $\mathbb{P}(\Omega; a,b)$ in any simply connected domain $\Omega$ with an interior marked point $u$ by pulling back using a uniformizing conformal map $\Omega \rightarrow \mathbb{D}$ sending $u$ to 0.
\item (Domain Markov property) given an initial segment $\gamma[0, \tau]$ of the radial $\operatorname{SLE}_\kappa$ curve $\gamma \sim \mathbb{P}(\Omega ; x, y)$ up to a stopping time $\tau$, the conditional law of $\gamma[\tau, \infty)$ is the law $\mathbb{P}\left(\Omega \backslash K_\tau ; \gamma(\tau), 0\right)$ of the $\mathrm{SLE}_\kappa$ curve in the complement of the hull $K_\tau$ from the tip $\gamma(\tau)$ to $0$.
\item (Reflection symmetry) Let $\iota: z \mapsto \bar{z}$ be the complex conjugation, then $\mathbb{P}(\zeta,0) \sim \iota^* \mathbb{P}(\overline{\zeta},0)$.
\end{itemize}

[Proposition 61 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] $F$ is $r$-$\sigma$-semicontinuous if and only if the common $\sigma$-order and $\mathrm{u\sigma o}$ closure of $\Ba_{F}$ is contained in $r\Ba_{F}$. Moreover, the following conditions are equivalent:
\item[(i)] $F$ is topologically $\sigma$-semicontinuous;
\item[(ii)] The norm topology is $\sigma$-semicontinuous;
\item[(iii)] The common $\sigma$-order and $\mathrm{u\sigma o}$ closure of $\Ba_{F}$ is norm bounded;
\item[(iv)] $\sigma$-order closure preserves norm bounded sets;
\item[(iv')] $\mathrm{u\sigma o}$ closure preserves norm bounded sets. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] We say that $\mu_{\ast }$ is a $(\psi ,p)$-stationary measure if for every $
		\mu \in \mathcal{P}_{p}(\mathbb{R}^{d})$ and every $k\in \mathbb{N}$ 
		\begin{equation*}
			\lim_{n}W_{p}^{p}(\Theta_{t_{k},t_{n}}^{\pi }(\mu ),\mu _{\ast })=0.
		\end{equation*}

[Lemma lem:mixed_tail_finite_pointwise of arXiv:2609.01576, '\normalfont Pointwise Majorization for sub-Weibull and Mixed Tail Processes with Applicati'] Let $K\subseteq T$ be finite and contain $t_0$. For every
$j\in\cbr{1,2}$, let $\mathcal T_j=(T_{j,k})_{k\ge0}$ be an admissible sequence of subsets of $K$ such that $T_{j,0}=\cbr{t_0}$ and $T_{j,k}=K$ for all sufficiently large $k$. We define
\begin{align*}
G_j(t)
:=
\sum_{k\ge0}
2^{k/\alpha_j}d_j(t,T_{j,k}),
\ t\in K.
\end{align*}
There exists a finite constant $A_{\alpha_1,\alpha_2}$, depending only
on $\alpha_1$ and $\alpha_2$, such that, for every $u\ge1$, with
probability at least $1-e^{-u}$, simultaneously for every $t\in K$,
\begin{align*}
\|Z_t\|
\le
A_{\alpha_1,\alpha_2}
\cbr{
G_1(t)+G_2(t)
+
u^{1/\alpha_1}v_1(t)
+
u^{1/\alpha_2}v_2(t)
}.
\end{align*}

