[Proposition 14 ($a+b=1$, moments) of arXiv:2606.00781, '2606.00781'] If $a+b=1$ then the moments of the stationary distribution $\mu$ are given by
   \begin{equation} 
   \mu_n
    = \frac{1}{\binom{-b}{n}}
        \sum_{k=1}^n\frac{1}{2^k}\sum_{\ell=1}^k(-1)^\ell\binom{k}{\ell}
        \binom{b\ell}{n}
    = \frac{1}{(-b)_n}\sum_{k=1}^n\frac{(-1)^k}{2^k}k!
        \sum_{j=1}^n s(n,j)b^jS(j,k),\ n\in\nz,
   \end{equation}
   where $s(.,.)$ and $S(.,.)$ denote the Stirling numbers of the first and second kind respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma CountingConnectedSets of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] For every $m\in \mathbb{N}$, there is a $C>0$ such that for all $n\in \mathbb{N}$ and $x\in \mathbb{Z}^d $ 
\begin{align*}
    |\{\gamma\subset \mathbb{Z}^d\,|\,  \gamma\text{ is $m$-connected, }|\gamma|=n\text{ and }x\in \gamma \}|\le C^n.
\end{align*}

[Prop 20 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] The potential $E_d*\zeta^{1/(m-1)}$ of $\zeta^{1/(m-1)}$ is given by
\begin{equation}
    \big(E_d*\zeta^{1/(m-1)}\big)(x) = \frac{m}{m-1} \zeta(x) + \frac{2-m}{m-1} \frac{I_\zeta}{M_c}\,, \quad x\in\mathbb{B}_1\,, 
\end{equation}
and
\begin{equation}
   \big(E_d*\zeta^{1/(m-1)}\big)(x) = \frac{M_c}{(d-2)\sigma_d} \frac{1}{|x|^{d-2}}\,, \quad x\in\mathbb{R}^d\setminus\mathbb{B}_1\,,  
\end{equation}
where
\begin{equation}
    I_\zeta := \int_{\mathbb{B}_1} \zeta^{m/(m-1)}(x)\,\rd x\,. 
\end{equation}
Moreover,
\begin{equation}
    I_\zeta = \frac{m-1}{2-m}\frac{M_c^2}{(d-2)\sigma_d} = \frac{m}{m-1} \int_{\mathbb{B}_1} |\nabla\zeta(x)|^2\,\rd x\,. 
\end{equation}

