[Prop 68 (Controlling the error terms) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $\mathcal E^j_N, \mathcal V^j_N$ $(1\le j \le 2)$ be as in Proposition \ref{4.3}. Let $q\ge 1$ be an even integer, and let $T>0$. Then there exists $C>0$ and a function $f:I\to \mathbb R_+$ such that $|f(x)| \leq F(|x|)$ where $F:[0,\infty)\to[0,\infty)$ is decreasing and 
of exponential decay at infinity, such that uniformly over all $N\ge 1$ and $s,t\in [0,T]\cap (N^{-1}\mathbb Z_{\ge 0})$ we have the following:
    \begin{enumerate}\item \hyperref[eq:regimeA]{Regime A:} In the case where $|  \varsigma_N|=O(N^{-1/2})$ we have the bound 
    \begin{align*}
        \sum_{j=1,2}\mathbb E[ |\mathcal V^j_N(t,\phi)-\mathcal V^j_N(s,\phi)|^q]^{1/q} &\leq C N^{-1/2}\|\phi\|_{C^{p+2}(\mathbb R^d)}^2 \bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
\end{align*}
The integer $p$ appearing on the right side is the one from Assumption \ref{a1}.
\item \hyperref[eq:regimeB]{Regime B:} In the case where $N^{-1/2} \ll  |  \varsigma_N| \ll  \psi_N(p,d)N^{-1}$ we have \begin{align*}\sum_{j=1,2}\mathbb E[ |\mathcal E^j_N(t,\phi)-\mathcal E^j_N(s,\phi)|^q]^{1/q}& \leq C |  \varsigma_N|^{1/2} \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
    \end{align*}
    \item \hyperref[eq:regimeC]{Regime C:} In the case where $d=2$ and  $ (\log N)^{1/2p}   \varsigma_N\to   {\boldsymbol v}\ne 0 $, we have 
    \begin{align*}\sum_{j=1,2}\mathbb E[ |\mathcal E^j_N(t,\phi)-\mathcal E^j_N(s,\phi)|^q]^{1/q}& \leq C |  \varsigma_N|^{1/2} \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
    \end{align*}
    \item \hyperref[eq:regimeD]{Regime D:} In the case where $d\ge 3$ and $  \varsigma_N  \to   {\boldsymbol v}\ne 0$ we have that $$\mathbb E[ |\mathcal E^1_N(t,\phi)-\mathcal E^1_N(s,\phi)|^q]^{1/q} \leq C|\varsigma_N-  {\boldsymbol v}| \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).$$
    \end{enumerate}
 Note that the second and third cases have the same error bounds; however, we distinguish these two cases because they will need to be analyzed separately later on. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RBM-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator satisfies the following identities.
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item \textup{(Splitting.)}
For $i < p < j$,
\begin{equation}
\partial_{a_p} [B_{\mathbf{a},\mathbf{n}}]_{ij}(z, w)
= [B_{\mathbf{a},\mathbf{n}}]_{ip}(z, a_p)[B_{\mathbf{a},\mathbf{n}}]_{pj}(a_p, w).
\end{equation}

\item \textup{(Flux conservation.)}
For $i < j$,
\begin{equation}
\Bigl(\partial_z + \partial_w
+ \sum_{i < p < j} \partial_{a_p}\Bigr)
[B_{\mathbf{a},\mathbf{n}}]_{ij}(z, w) = 0.
\end{equation}

\item The propagator depends on the particle labels
$\mathbf{n}$ only through differences
$n_{\ell'} - n_\ell$, and is $t$-independent.
\end{enumerate}

[Definition eq:detailed balance reactions of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] A chemical system  $(\Omega, \mathcal R,  \mathcal R_s , \mathcal K, \mathcal K_s )$ satisfies the property of detailed balance if there exists a  $f_s  \in \mathcal P (\mathbb N^M ) $ that is  such that 
\begin{equation} 
R_\rho (n) f_s( n)  = R_{- \rho}(n+ S_\rho) f_s( n + S_\rho), \quad \forall n \in \mathbb N^M, \  \forall \rho \in \{ 1, \dots, r \}
\end{equation}
and 
\begin{equation} 
A_k (n) f_s( n)  = B_k (n+ e_k) f_s( n + e_k ), \quad \forall n \in \mathbb N^M, \  \forall k \in \Omega_c. 
\end{equation}

[Theorem GeneralizKolmogBackwardEq of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let  $A \in \mathcal{F}_{T}$ for $T < \infty$, and let  $P^i$, $i \in \mathcal{Z}$, be given stochastic processes.  The two following statements are equivalent:
\begin{itemize}
	\item[(i)] The multivariate process $(P^i)_{i \in \mathcal{Z}}$  satisfies $P^i(t)= \mathbb{P}_{t}^i[A]$, $t \in [0,T]${.}
	\item[(ii)]  The multivariate process $(P^i)_{i \in \mathcal{Z}}$ is a solution in  $\mathcal{Y}(\Lambda)$ for the backward equation
\begin{align}
	0 = \mathds{1}_{\{   \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)< \infty\}} I^i(t-) \bigg( P^i(\mathrm{d} t)+\sum_{j:j\neq  i} \big(P^j(t)-P^i(t) \big) \Lambda^{ij}(\mathrm{d} t)\bigg) 
\end{align}
with terminal value $P^i(T)= \mathbb{P}_T^i[A]$. 
\end{itemize} 
If for a  subset $\mathcal{Z}_0 \subset \mathcal{Z}$ we have $\Lambda^{ij}=0$ for all $i \in \mathcal{Z}_0$ and $j \not\in \mathcal{Z}_0$, then the equivalence is also true for the sub-process $(P^i)_{i  \in \mathcal{Z}_0}$ only. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 62 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definitions \ref{Def.ParametersEdge} and \ref{Def.ScalingEdge}. Then for each $j \in \llbracket 1, m \rrbracket$
\begin{equation}
\lim_{N \rightarrow \infty} \sum_{i \geq 1} \mathbb{P}(Y^{j,N}_i \geq \sigma_2^{-1} [h_1(\kappa_j) - h_2(\kappa_j)] N^{1/2} + 1) = 1.
\end{equation}

